        // ── Dynamic dependency / supersedence lists (any count) ─────────────
        // On disk these flatten to numbered keys (DependencyAppName1/DependencyAppID1/
        // DependencyAutoInstall1 ... and SupersedenceAppName1/SupersedenceAppID1/
        // SupersedenceUninstallPreviousVersion1 ...) via the extension-data round-trip
        // below, so none of the JsonSerializer call sites need to change.
        [JsonIgnore] public List<DependencyItem>   Dependencies  { get; set; } = new();
        [JsonIgnore] public List<SupersedenceItem> Supersedences { get; set; } = new();

        [JsonExtensionData] public Dictionary<string, object> Extra { get; set; } = new();

        void IJsonOnSerializing.OnSerializing()
        {
            Extra ??= new();
            foreach (var k in Extra.Keys.Where(IsDynamicDepSupKey).ToList()) Extra.Remove(k);
            for (int i = 0; i < Dependencies.Count; i++)
            {
                var d = Dependencies[i]; int n = i + 1;
                if (string.IsNullOrWhiteSpace(d.AppName) && string.IsNullOrWhiteSpace(d.AppID)) continue;
                Extra[$"DependencyAppName{n}"]     = d.AppName ?? "";
                Extra[$"DependencyAppID{n}"]       = d.AppID ?? "";
                Extra[$"DependencyAutoInstall{n}"] = string.IsNullOrWhiteSpace(d.AutoInstall) ? "No" : d.AutoInstall;
            }
            for (int i = 0; i < Supersedences.Count; i++)
            {
                var s = Supersedences[i]; int n = i + 1;
                if (string.IsNullOrWhiteSpace(s.AppName) && string.IsNullOrWhiteSpace(s.AppID)) continue;
                Extra[$"SupersedenceAppName{n}"]                  = s.AppName ?? "";
                Extra[$"SupersedenceAppID{n}"]                    = s.AppID ?? "";
                Extra[$"SupersedenceUninstallPreviousVersion{n}"] = string.IsNullOrWhiteSpace(s.UninstallPreviousVersion) ? "No" : s.UninstallPreviousVersion;
            }
        }

        void IJsonOnDeserialized.OnDeserialized()
        {
            // Legacy migration: the manual "download via Download Page URL" option used to be
            // stored as "none". It is now "URL" everywhere. Normalise on load so every existing
            // app keeps working and only "URL" is ever compared against downstream.
            if (string.Equals(ApiType, "none", StringComparison.OrdinalIgnoreCase))
                ApiType = "URL";

            Dependencies  = new();
            Supersedences = new();
            if (Extra == null) return;
            string S(string key)
            {
                if (!Extra.TryGetValue(key, out var v) || v == null) return "";
                if (v is JsonElement el) return el.ValueKind == JsonValueKind.String ? (el.GetString() ?? "") : el.ToString();
                return v.ToString() ?? "";
            }
            for (int n = 1; n <= 50; n++)
            {
                string name = S($"DependencyAppName{n}"), id = S($"DependencyAppID{n}"), auto = S($"DependencyAutoInstall{n}");
                if (name.Length == 0 && id.Length == 0) continue;
                Dependencies.Add(new DependencyItem { AppName = name, AppID = id, AutoInstall = string.IsNullOrWhiteSpace(auto) ? "No" : auto });
            }
            for (int n = 1; n <= 50; n++)
            {
                string name = S($"SupersedenceAppName{n}"), id = S($"SupersedenceAppID{n}"), unin = S($"SupersedenceUninstallPreviousVersion{n}");
                if (name.Length == 0 && id.Length == 0) continue;
                Supersedences.Add(new SupersedenceItem { AppName = name, AppID = id, UninstallPreviousVersion = string.IsNullOrWhiteSpace(unin) ? "No" : unin });
            }
        }

        private static bool IsDynamicDepSupKey(string k) =>
            System.Text.RegularExpressions.Regex.IsMatch(k,
                @"^(DependencyAppName|DependencyAppID|DependencyAutoInstall|SupersedenceAppName|SupersedenceAppID|SupersedenceUninstallPreviousVersion|Dependency|AutoInstallDependency|Supersedence|UninstallPreviousVersion)\d+$");

        // ── COPY OUTPUT TO DOCUMENTS ──────────────────────────────────────────
        // Excluded from the per-app JSON (JsonIgnore). Kept in-memory only because
        // other code paths still reference them; no UI sets them, so they stay "No".
        [JsonIgnore] public string CopyLogsToDocuments       { get; set; } = "No";
        [JsonIgnore] public string CopyCSVToDocuments        { get; set; } = "No";
        [JsonIgnore] public string CopyHtmlToDocuments       { get; set; } = "No";
        [JsonIgnore] public string CopytxtToDocuments        { get; set; } = "No";
        [JsonIgnore] public string CopydocxToDocuments       { get; set; } = "No";
    }

