    public partial class SourceDownloadPage : Page
    {
        /// <summary>
        /// Global flag set from per-app JSON ShowMessageBox field.
        /// When false, completion dialogs auto-close; only failure dialogs show.
        /// </summary>
        public static bool GlobalShowMessageBox { get; set; } = true;
        // Both clients connect through ConnectDualStackAsync below. .NET connects to a
        // host's addresses strictly one at a time, and Windows abandons a TCP connect
        // after about 21 seconds (SYN at 0s, retries at 3s and 9s), so a host that
        // publishes an IPv6 address on a network whose IPv6 goes nowhere costs a full
        // 21 seconds before the IPv4 address is even tried. The callback races the two
        // families instead, so a dead IPv6 path costs a few hundred milliseconds.
        private static readonly HttpClient _http = new HttpClient(NewDualStackHandler());
        // Installer bodies get their own client. HttpClient.Timeout bounds the WHOLE
        // operation, response body included, so the 10-second ceiling below (right for the
        // small YAML/API fetches) was tearing the stream down on any transfer that ran
        // longer than 10 seconds. There is no timeout here: the read loop is bounded by the
        // download's own CancellationToken, which the Cancel button owns.
        private static readonly HttpClient _httpDownload = new HttpClient(NewDualStackHandler());

        static SourceDownloadPage()
        {
            _http.DefaultRequestHeaders.Add("User-Agent", "SwiftPack/1.0");
            _http.Timeout = TimeSpan.FromSeconds(10);
            _httpDownload.DefaultRequestHeaders.Add("User-Agent", "SwiftPack/1.0");
            _httpDownload.Timeout = System.Threading.Timeout.InfiniteTimeSpan;
        }

        // ── Dual-stack connect (Happy Eyeballs) ────────────────────────────
        // How long IPv6 gets to connect on its own before IPv4 is started alongside it.
        // On a healthy network IPv6 connects well inside this and keeps the connection;
        // on a broken one this is the whole price, instead of the 21-second TCP give-up.
        private const int IPv6HeadStartMs = 300;

        private static SocketsHttpHandler NewDualStackHandler() => new SocketsHttpHandler
        {
            ConnectCallback = ConnectDualStackAsync,
            // These clients are static and live for the whole process, and without a
            // lifetime a pooled connection pins whichever mirror address DNS returned on
            // day one for as long as the app runs. Ten minutes is the standard guidance
            // for long-lived clients.
            PooledConnectionLifetime = TimeSpan.FromMinutes(10),
        };

        private static async ValueTask<Stream> ConnectDualStackAsync(
            SocketsHttpConnectionContext context, CancellationToken ct)
        {
            // Local helper: one line in the winget log per NEW pooled connection (not per
            // request), naming the family and address that actually carries the traffic.
            // Happy-eyeballs picks the family that CONNECTS fastest, which on a network
            // with a broken-but-connectable IPv6 route is not the family that TRANSFERS
            // fastest - and without this line that condition is invisible from the logs.
            static Stream Carry(System.Net.Sockets.Socket s, string host)
            {
                // Parity with the stock SocketsHttpHandler connect, which sets NoDelay on
                // every socket it creates. This is the only socket-level difference the
                // custom connect had against the default path; closed so the callback is
                // byte-for-byte equivalent after the connect race is decided.
                try { s.NoDelay = true; } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                try
                {
                    var ep = s.RemoteEndPoint as System.Net.IPEndPoint;
                    if (ep != null)
                        LogWinget($"[Net] {host}: connected via " +
                                  $"{(ep.AddressFamily == System.Net.Sockets.AddressFamily.InterNetworkV6 ? "IPv6" : "IPv4")} " +
                                  $"({ep.Address})");
                }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                return new System.Net.Sockets.NetworkStream(s, ownsSocket: true);
            }

            var addresses = await System.Net.Dns.GetHostAddressesAsync(
                context.DnsEndPoint.Host, ct).ConfigureAwait(false);
            var v6 = System.Array.FindAll(addresses,
                a => a.AddressFamily == System.Net.Sockets.AddressFamily.InterNetworkV6);
            var v4 = System.Array.FindAll(addresses,
                a => a.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork);
            int port = context.DnsEndPoint.Port;

            // One family only: there is nothing to race, and a cap would add a failure
            // mode a genuinely slow single-family host does not deserve.
            if (v6.Length == 0 || v4.Length == 0)
                return Carry(
                    await ConnectAnyAsync(addresses, port, ct).ConfigureAwait(false),
                    context.DnsEndPoint.Host);

            using var race = CancellationTokenSource.CreateLinkedTokenSource(ct);
            var v6Task = ConnectAnyAsync(v6, port, race.Token);

            var headStart = await Task.WhenAny(
                v6Task, Task.Delay(IPv6HeadStartMs, race.Token)).ConfigureAwait(false);
            if (headStart == v6Task && v6Task.Status == TaskStatus.RanToCompletion)
            {
                race.Cancel();
                return Carry(v6Task.Result, context.DnsEndPoint.Host);
            }

            // IPv6 has not connected inside its head start (or already failed): start
            // IPv4 beside it and take whichever lands first. The loser is cancelled and
            // its socket disposed; a loser that fails instead has its exception observed
            // so it can never surface as an unobserved task fault.
            var v4Task = ConnectAnyAsync(v4, port, race.Token);
            var first  = await Task.WhenAny(v6Task, v4Task).ConfigureAwait(false);
            var second = first == v6Task ? v4Task : v6Task;

            if (first.Status == TaskStatus.RanToCompletion)
            {
                race.Cancel();
                AbandonConnectAttempt(second);
                return Carry(first.Result, context.DnsEndPoint.Host);
            }

            AbandonConnectAttempt(first);
            var winner = await second.ConfigureAwait(false); // both dead: this throw is the real error
            return Carry(winner, context.DnsEndPoint.Host);
        }

        /// <summary>Connects to the given addresses in order and returns the first socket that lands.</summary>
        private static async Task<System.Net.Sockets.Socket> ConnectAnyAsync(
            System.Net.IPAddress[] addresses, int port, CancellationToken ct)
        {
            System.Exception? last = null;
            foreach (var address in addresses)
            {
                var socket = new System.Net.Sockets.Socket(address.AddressFamily,
                    System.Net.Sockets.SocketType.Stream,
                    System.Net.Sockets.ProtocolType.Tcp) { NoDelay = true };
                try
                {
                    await socket.ConnectAsync(new System.Net.IPEndPoint(address, port), ct)
                        .ConfigureAwait(false);
                    return socket;
                }
                catch (System.Exception ex)
                {
                    socket.Dispose();
                    last = ex;
                    if (ct.IsCancellationRequested) throw;
                }
            }
            throw last ?? new System.Net.Sockets.SocketException(
                (int)System.Net.Sockets.SocketError.HostNotFound);
        }

        /// <summary>
        /// Detaches a losing connect attempt: disposes its socket if it lands late, and
        /// observes its exception if it fails, in either case without waiting for it.
        /// </summary>
        private static void AbandonConnectAttempt(Task<System.Net.Sockets.Socket> attempt)
            => attempt.ContinueWith(t =>
            {
                if (t.Status == TaskStatus.RanToCompletion) t.Result.Dispose();
                else _ = t.Exception;
            }, TaskScheduler.Default);

        private List<DownloadSourceEntry> _allApps           = new();
        private IAutoPackageHost? _mainWindow; // set on first load, survives navigation

        /// <summary>Called by MainWindow to inject itself so scheduled downloads work even before page is visited.</summary>
        public void SetMainWindow(IAutoPackageHost mw) => _mainWindow = mw;

        /// <summary>
        /// Called by MainWindow after a silent EXE install completes.
        /// Scans the uninstall registry hives by DisplayName and fills any empty
        /// detection fields on the currently selected app, then saves to JSON.
        /// Only runs when RulesFormat == "Manual detection rules".
        /// </summary>
        public void FillDetectionFromRegistryByName(string appName)
        {
            if (_selectedApp == null || string.IsNullOrWhiteSpace(appName)) return;
            if (!(_selectedApp.RulesFormat ?? "Manual detection rules")
                    .Equals("Manual detection rules", StringComparison.OrdinalIgnoreCase)) return;

            bool needsFill =
                string.IsNullOrWhiteSpace(_selectedApp.DetectionFileFolderPath) ||
                string.IsNullOrWhiteSpace(_selectedApp.DetectionFileFileName)   ||
                string.IsNullOrWhiteSpace(_selectedApp.DetectionFileValue)      ||
                string.IsNullOrWhiteSpace(_selectedApp.DetectionRegKeyPath)     ||
                string.IsNullOrWhiteSpace(_selectedApp.DetectionRegistryValue);
            if (!needsFill) return;

            var hives = new[]
            {
                (Microsoft.Win32.Registry.LocalMachine,
                 @"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"),
                (Microsoft.Win32.Registry.LocalMachine,
                 @"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall"),
                (Microsoft.Win32.Registry.CurrentUser,
                 @"Software\Microsoft\Windows\CurrentVersion\Uninstall"),
            };

            int bestLen = 0;
            foreach (var (hRoot, sub) in hives)
            {
                try
                {
                    using var hive = hRoot.OpenSubKey(sub);
                    if (hive == null) continue;
                    foreach (string subName in hive.GetSubKeyNames())
                    {
                        try
                        {
                            using var key = hive.OpenSubKey(subName);
                            if (key == null) continue;
                            string dn = key.GetValue("DisplayName") as string ?? "";
                            if (string.IsNullOrWhiteSpace(dn)) continue;
                            bool match = dn.Contains(appName, StringComparison.OrdinalIgnoreCase) ||
                                         appName.Contains(dn, StringComparison.OrdinalIgnoreCase);
                            if (!match || dn.Length <= bestLen) continue;
                            bestLen = dn.Length;

                            string hName    = hRoot == Microsoft.Win32.Registry.CurrentUser
                                ? "HKEY_CURRENT_USER" : "HKEY_LOCAL_MACHINE";
                            string regPath  = $"{hName}\\{sub}\\{subName}";
                            string dispVer  = key.GetValue("DisplayVersion")  as string ?? "";
                            string instLoc  = (key.GetValue("InstallLocation") as string ?? "")
                                                  .TrimEnd(Path.DirectorySeparatorChar);
                            string dispIcon = (key.GetValue("DisplayIcon")     as string ?? "")
                                                  .Split(',')[0].Trim().Trim('"');

                            if (string.IsNullOrWhiteSpace(instLoc) &&
                                dispIcon.EndsWith(".exe", StringComparison.OrdinalIgnoreCase))
                                instLoc = (Path.GetDirectoryName(dispIcon) ?? "")
                                              .TrimEnd(Path.DirectorySeparatorChar);

                            if (string.IsNullOrWhiteSpace(_selectedApp.DetectionRegKeyPath))
                                _selectedApp.DetectionRegKeyPath = regPath;
                            if (string.IsNullOrWhiteSpace(_selectedApp.DetectionRegistryValue) &&
                                !string.IsNullOrWhiteSpace(dispVer))
                                _selectedApp.DetectionRegistryValue = dispVer;
                            if (string.IsNullOrWhiteSpace(_selectedApp.DetectionFileFolderPath) &&
                                !string.IsNullOrWhiteSpace(instLoc))
                                _selectedApp.DetectionFileFolderPath = instLoc;

                            // Resolve main exe: DisplayIcon → largest in InstallLocation → shortcuts
                            if (string.IsNullOrWhiteSpace(_selectedApp.DetectionFileFileName))
                            {
                                string exePath = "";
                                if (!string.IsNullOrWhiteSpace(dispIcon) &&
                                    dispIcon.EndsWith(".exe", StringComparison.OrdinalIgnoreCase) &&
                                    File.Exists(dispIcon))
                                    exePath = dispIcon;

                                if (string.IsNullOrWhiteSpace(exePath) &&
                                    !string.IsNullOrWhiteSpace(instLoc) && Directory.Exists(instLoc))
                                {
                                    try
                                    {
                                        var exes = Directory.GetFiles(instLoc, "*.exe",
                                                       SearchOption.TopDirectoryOnly);
                                        if (exes.Length > 0)
                                            exePath = exes.OrderByDescending(
                                                e => new System.IO.FileInfo(e).Length).First();
                                    }
                                    catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                                }

                                // Start Menu .lnk shortcuts
                                if (string.IsNullOrWhiteSpace(exePath))
                                {
                                    var startDirs = new[]
                                    {
                                        Environment.GetFolderPath(Environment.SpecialFolder.CommonPrograms),
                                        Environment.GetFolderPath(Environment.SpecialFolder.Programs),
                                    };
                                    foreach (string sDir in startDirs.Where(
                                        d => !string.IsNullOrWhiteSpace(d) && Directory.Exists(d)))
                                    {
                                        try
                                        {
                                            foreach (string lnk in Directory.GetFiles(
                                                sDir, "*.lnk", SearchOption.AllDirectories))
                                            {
                                                try
                                                {
                                                    var shell = Activator.CreateInstance(
                                                        Type.GetTypeFromProgID("WScript.Shell")!);
                                                    if (shell == null) continue;
                                                    var sc = shell.GetType().InvokeMember(
                                                        "CreateShortcut",
                                                        System.Reflection.BindingFlags.InvokeMethod,
                                                        null, shell, new object[] { lnk });
                                                    if (sc == null) continue;
                                                    string target = sc.GetType().InvokeMember(
                                                        "TargetPath",
                                                        System.Reflection.BindingFlags.GetProperty,
                                                        null, sc, null)?.ToString() ?? "";
                                                    if (!target.EndsWith(".exe",
                                                            StringComparison.OrdinalIgnoreCase) ||
                                                        !File.Exists(target)) continue;
                                                    string lnkName = Path.GetFileNameWithoutExtension(lnk);
                                                    bool lnkMatch =
                                                        lnkName.Contains(appName,
                                                            StringComparison.OrdinalIgnoreCase) ||
                                                        appName.Contains(lnkName,
                                                            StringComparison.OrdinalIgnoreCase) ||
                                                        (!string.IsNullOrWhiteSpace(instLoc) &&
                                                         target.StartsWith(instLoc,
                                                             StringComparison.OrdinalIgnoreCase));
                                                    if (lnkMatch) { exePath = target; break; }
                                                }
                                                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                                            }
                                            if (!string.IsNullOrWhiteSpace(exePath)) break;
                                        }
                                        catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                                    }
                                }

                                if (!string.IsNullOrWhiteSpace(exePath))
                                {
                                    _selectedApp.DetectionFileFileName = Path.GetFileName(exePath);
                                    if (string.IsNullOrWhiteSpace(_selectedApp.DetectionFileFolderPath))
                                        _selectedApp.DetectionFileFolderPath =
                                            Path.GetDirectoryName(exePath) ?? "";
                                    if (string.IsNullOrWhiteSpace(_selectedApp.DetectionFileValue) &&
                                        File.Exists(exePath))
                                    {
                                        try
                                        {
                                            var fvi = System.Diagnostics.FileVersionInfo.GetVersionInfo(exePath);
                                            string fv = (fvi.FileMajorPart > 0 || fvi.FileMinorPart > 0 ||
                                                         fvi.FileBuildPart > 0 || fvi.FilePrivatePart > 0)
                                                ? $"{fvi.FileMajorPart}.{fvi.FileMinorPart}.{fvi.FileBuildPart}.{fvi.FilePrivatePart}"
                                                : fvi.FileVersion?.Trim() ?? "";
                                            if (!string.IsNullOrWhiteSpace(fv))
                                                _selectedApp.DetectionFileValue = fv;
                                        }
                                        catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                                    }
                                }
                            }
                        }
                        catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                    }
                }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
            }

        }

        // ── Auto-prefill containment ───────────────────────────────────────────
        // The detection auto-fill (registry/exe scan) resolves empty detection
        // fields so the downstream Publish objects have values to work with.
        // Those resolved values are PREFILL data and must NOT be persisted to the
        // per-app template JSON — only values the user typed manually or values
        // that already existed in the JSON may be saved. To guarantee that, we
        // snapshot the relevant detection fields on _selectedApp BEFORE the fill
        // runs, and restore them AFTER the downstream static objects have been
        // built from the (temporarily filled) _selectedApp. Any later SaveApps()
        // therefore writes only the original (manual / pre-existing) values.
        // (DetectionMsiProductCode is already never mutated by the fill.)
        private string[]? SnapshotDetectionPrefillFields()
        {
            if (_selectedApp == null) return null;
            return new[]
            {
                _selectedApp.DetectionFileFolderPath ?? "",
                _selectedApp.DetectionFileFileName   ?? "",
                _selectedApp.DetectionFileValue      ?? "",
                _selectedApp.DetectionMsiValue       ?? "",
                _selectedApp.DetectionRegKeyPath     ?? "",
                _selectedApp.DetectionRegistryValue  ?? "",
            };
        }

        private void RestoreDetectionPrefillFields(string[]? snapshot)
        {
            if (_selectedApp == null || snapshot == null || snapshot.Length < 6) return;
            _selectedApp.DetectionFileFolderPath = snapshot[0];
            _selectedApp.DetectionFileFileName   = snapshot[1];
            _selectedApp.DetectionFileValue      = snapshot[2];
            _selectedApp.DetectionMsiValue       = snapshot[3];
            _selectedApp.DetectionRegKeyPath     = snapshot[4];
            _selectedApp.DetectionRegistryValue  = snapshot[5];
        }

        /// <summary>
        /// Post-install variant called by MainWindow after a silent EXE install.
        /// The publish step (AutoPublishPage) re-derives all empty detection fields
        /// from the registry at publish time, so the only effect of persisting this
        /// post-install scan would be leaking auto-prefill data into the per-app JSON.
        /// We therefore run the scan but immediately restore the original values, so
        /// nothing auto-resolved here is ever saved to the JSON.
        /// </summary>
        public void FillDetectionFromRegistryByNameNoPersist(string appName)
        {
            string[]? snap = SnapshotDetectionPrefillFields();
            FillDetectionFromRegistryByName(appName);
            RestoreDetectionPrefillFields(snap);
        }


        private string                    _activeCategory    = "All";
        private string                    _searchText        = "";
        private DownloadSourceEntry?      _selectedApp       = null;
        private string                    _selectedVendor    = "";
        private string                    _sourceDownloadPath             = "";
        private string                    _psadtTemplateFolder            = "";
        private string                    _packageInputFolder             = "";
        private string                    _packageOutputFolder            = "";
        private string                    _appVersionReportPath           = "";

        /// <summary>Resolves a WPF resource brush. Falls back gracefully if not yet loaded.</summary>
        private static Brush Res(string key, Brush fallback)
        {
            try
            {
                if (Application.Current?.Resources?.Contains(key) == true)
                {
                    var v = Application.Current.Resources[key];
                    if (v is Brush b) return b;
                }
                if (Application.Current?.Resources?.MergedDictionaries != null)
                    foreach (var d in Application.Current.Resources.MergedDictionaries)
                        if (d.Contains(key) && d[key] is Brush b2) return b2;
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
            return fallback;
        }

        /// <summary>Sets a DynamicResource binding on a FrameworkElement — equivalent to {DynamicResource key} in XAML.
        /// This ensures the element updates automatically when the theme changes, unlike a one-time Res() snapshot.</summary>
        private static T BindFg<T>(T el, string resourceKey) where T : FrameworkElement
        {
            el.SetResourceReference(System.Windows.Controls.Control.ForegroundProperty, resourceKey);
            return el;
        }
        private static T BindBg<T>(T el, string resourceKey) where T : FrameworkElement
        {
            el.SetResourceReference(System.Windows.Controls.Panel.BackgroundProperty, resourceKey);
            return el;
        }


        private DateTime                  _downloadStartTime              = DateTime.Now;

        // Persists the last selected app across page navigations (static survives page disposal)
        private static string? _lastSelectedVendor  = null;
        private static string? _lastSelectedAppName = null;

        // Set when a download button is clicked — "EXE" or "MSI"
        // Used to populate Silent Install/Uninstall fields in Package Information panel
        private static string _lastTriggeredDownloadType = "";
        // PSADT v4 native launcher, used to seed both the PSADT and the Intune Install/Uninstall
        // command fields for a new app. The .exe wrapper resolves its own architecture, so unlike
        // the old "powershell.exe -File Invoke-AppDeployToolkit.ps1" form it needs no Sysnative
        // rewrite to write 64-bit registry keys under the Intune (32-bit) agent.
        internal const string DefaultPsadtInstallCommand   = "Invoke-AppDeployToolkit.exe";
        internal const string DefaultPsadtUninstallCommand = "Invoke-AppDeployToolkit.exe Uninstall";

        private AppDownloadInfo? _lastInfo = null; // cached for download-button re-highlighting
        private WrapPanel? _downloadPrefRadioPanel = null; // Download Preference radios (filtered to available links)
        // Reassigned on every RenderInfoPanel pass to (re)apply the Rule Type default that follows
        // the Download Preference: MSI picks the product-code rule, EXE the ARP registry key. Kept
        // as a field, not a RenderInfoPanel local, so the Download Information button-click handler
        // (which lives in a separate scope) can invoke the same additive logic the radio uses.
        private Action<string>? _applyRuleTypeForPreference = null;

        /// <summary>
        /// Shows only the Download Preference radios for which the live fetch produced
        /// a download link (e.g. a winget 64-bit package → only "EXE x64"), hiding options
        /// the vendor doesn't offer. All options stay visible while no live data exists
        /// for the selected app, and defensively when nothing would match.
        /// </summary>
        private void UpdateDownloadPreferenceRadioVisibility()
        {
            var panel = _downloadPrefRadioPanel;
            if (panel == null) return;

            var info = _lastInfo;
            bool haveLinks = info != null && info.Links != null && info.Links.Count > 0 &&
                             string.Equals(info.SourceAppName, _selectedApp?.SourceAppName,
                                 StringComparison.OrdinalIgnoreCase);
            bool locked = (_selectedApp?.LockDownloadPreference ?? "No")
                .Equals("Yes", StringComparison.OrdinalIgnoreCase);
            // Locked → only the configured preference is offered; otherwise filter to
            // the links the live fetch actually produced (all visible when no data).
            var available = locked
                ? new HashSet<string>(new[] { _selectedApp?.DownloadPreference ?? "" },
                                      StringComparer.OrdinalIgnoreCase)
                : haveLinks
                    ? new HashSet<string>(info!.Links.Select(l => $"{l.Type}_{l.Arch}"),
                                          StringComparer.OrdinalIgnoreCase)
                    : null;

            int visible = 0;
            foreach (var child in panel.Children)
            {
                if (child is not RadioButton rb) continue;
                string key = (rb.Content?.ToString() ?? "").Replace(' ', '_');
                bool show = available == null || available.Contains(key);
                rb.Visibility = show ? Visibility.Visible : Visibility.Collapsed;
                if (show) visible++;
            }
            if (visible == 0) // never hide the whole row
                foreach (var child in panel.Children)
                    if (child is RadioButton rb2) rb2.Visibility = Visibility.Visible;
        }

        // Cache of live versions fetched from APIs — keyed by SourceAppName
        // Survives RenderCards() calls so "⬆ New" badge persists after card refresh
        private static readonly Dictionary<string, string> _liveVersionCache = new();

        // Auto-refresh interval — re-fetches all live versions every 30 minutes

        // Scheduler — checks every minute whether any app is due for automatic download
        /// <summary>Scheduler timer — adopted by MainWindow so it survives page navigation.</summary>
        public System.Windows.Threading.DispatcherTimer? ScheduleTimer => _scheduleTimer;
        private System.Windows.Threading.DispatcherTimer? _scheduleTimer;
        // The page-level timer currently running, whichever instance started it. Static so a new
        // instance can stop its predecessor's timer instead of leaving it ticking forever.
        private static System.Windows.Threading.DispatcherTimer? _pageScheduleTimer;
        private static readonly Dictionary<string, DateTime> _lastScheduledDownload = new();

        // ── In-slot retry for failed scheduled checks ──────────────────────
        // A due app whose check or download FAILED must not lose its slot: it stays in the
        // queue and is retried after a short backoff, because the alternative was one
        // transient 403 or network blip silently costing the whole period. The bound
        // matters just as much: without one, a permanently broken app (bad winget id,
        // deleted repo) becomes a 10-second hammer for the entire slot. So: retries at
        // 2 / 4 / 8 / 15 minutes, and the fifth failure spends the slot with a loud log
        // line instead of another attempt.
        private sealed class ScheduleRetryState
        {
            public string   SlotKey   = "";
            public int      Attempts;
            public DateTime NotBefore;
        }
        private static readonly Dictionary<string, ScheduleRetryState> _scheduleRetry = new();
        private static readonly int[] ScheduleRetryDelaysMin = { 2, 4, 8, 15 };
        private const int ScheduleRetryMaxAttempts = 5;

        private static void ClearScheduleRetry(string appName) => _scheduleRetry.Remove(appName);

        /// <summary>
        /// One failed attempt inside a slot: park the app with a backoff, or - on the final
        /// allowed attempt - spend the slot and say so. SlotKey scoping means a retry chain
        /// never leaks into the next occurrence: a new slot starts with a clean count.
        /// </summary>
        private static void RegisterScheduleFailure(DownloadSourceEntry app, string periodKey, DateTime now, string reason)
        {
            if (!_scheduleRetry.TryGetValue(app.SourceAppName, out var st) || st.SlotKey != periodKey)
                st = new ScheduleRetryState { SlotKey = periodKey };
            st.Attempts++;

            if (st.Attempts >= ScheduleRetryMaxAttempts)
            {
                _scheduleRetry.Remove(app.SourceAppName);
                _lastScheduledDownload[app.SourceAppName] = now;
                LogSched($"{app.SourceAppName}: attempt {st.Attempts} failed ({reason}) - GIVING UP on " +
                         $"slot {periodKey}; the next occurrence gets a fresh set of attempts");
                return;
            }

            int delay = ScheduleRetryDelaysMin[Math.Min(st.Attempts - 1, ScheduleRetryDelaysMin.Length - 1)];
            st.NotBefore = now.AddMinutes(delay);
            _scheduleRetry[app.SourceAppName] = st;
            LogSched($"{app.SourceAppName}: attempt {st.Attempts} failed ({reason}) - staying in the queue, " +
                     $"retry in {delay} min ({st.Attempts + 1} of {ScheduleRetryMaxAttempts} at most)");
        }

        private static readonly string DefaultDownloadPath = @"C:\Temp\Source";

        private static string JsonPath =>
            @"C:\Program Files\Smekal\SwiftPack Studio\Templates\AutoPackage.json";

        /// <summary>
        /// The five "Copy ... To Documents" flags, read LIVE from the global
        /// AutoPackage.json - the file the Settings window actually saves to. The matching
        /// per-app properties are [JsonIgnore] and never deserialize, so they sit at "No"
        /// forever; passing them into the chain was how a Settings window full of Yes
        /// still suppressed every copy downstream. Missing file or key reads as "No".
        /// </summary>
        private static (string logs, string csv, string html, string txt, string docx) ReadGlobalDocumentCopyFlags()
        {
            string logs = "No", csv = "No", html = "No", txt = "No", docx = "No";
            try
            {
                if (File.Exists(JsonPath))
                {
                    using var doc = JsonDocument.Parse(File.ReadAllText(JsonPath),
                        new JsonDocumentOptions
                        {
                            CommentHandling    = JsonCommentHandling.Skip,
                            AllowTrailingCommas = true,
                        });
                    string Read(string key) =>
                        doc.RootElement.TryGetProperty(key, out var v) && v.ValueKind == JsonValueKind.String
                            ? (v.GetString() ?? "No") : "No";
                    logs = Read("CopyLogsToDocuments");
                    csv  = Read("CopyCSVToDocuments");
                    html = Read("CopyHtmlToDocuments");
                    txt  = Read("CopytxtToDocuments");
                    docx = Read("CopydocxToDocuments");
                }
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
            return (logs, csv, html, txt, docx);
        }

        // Winget command cache: the silent EXE install/uninstall switches (and the installer type)
        // per winget package id, parsed from the installer manifest on first use.
        //
        // IN MEMORY ONLY, for the life of the session. There is no Commands.json: nothing reads one
        // and nothing writes one, so the file never appears in Templates on any install. An earlier
        // design persisted it there and a CommandsJsonPath property survived that change, pointing
        // at a file no code touched; it is gone now, along with the comment describing the on-disk
        // behaviour it used to have.
        //
        // The cost of not persisting is one re-fetch of a package's switches after a restart, which
        // is a single cheap read from the raw CDN. Within a session the cache still stops repeats.

        private sealed class WingetCmd
        {
            public string install { get; set; } = "";
            public string uninstall { get; set; } = "";
            public string exe { get; set; } = "";
            [JsonIgnore] public string type { get; set; } = "";
        }

        private static readonly object _cmdLock = new object();
        private static Dictionary<string, WingetCmd>? _cmdCache;

        private static Dictionary<string, WingetCmd> CommandsCache()
        {
            // In memory only, for the session. See the note above WingetCmd: there is no Commands.json
            // to read, so the read-only Templates folder is never touched here.
            if (_cmdCache != null) return _cmdCache;
            lock (_cmdLock) { _cmdCache ??= new Dictionary<string, WingetCmd>(StringComparer.OrdinalIgnoreCase); }
            return _cmdCache;
        }

        private static void SaveCommands()
        {
            // Intentionally empty, and intentionally KEPT. The cache is in-memory only, so there is
            // nothing to persist - but this is called from the manifest-fetch path below, and it
            // marks the one point where persistence would go if it is ever wanted again. Deleting
            // it would mean deleting a live call site for no gain.
        }

        // Parse a winget installer manifest into install/uninstall switches + a type label. Mirrors
        // the block-wise reading used by the download path: a top-level default InstallerType plus
        // per-installer blocks; the first EXE installer supplies the switches (explicit Silent /
        // SilentWithProgress when present, otherwise inferred from the framework).
        private static WingetCmd ParseWingetManifest(string yaml)
        {
            static string MapT(string it, string url)
            {
                string t = it.Trim().ToLowerInvariant();
                if (t == "msi" || t == "wix") return "MSI";
                if (t == "exe" || t == "nullsoft" || t == "inno" || t == "burn" || t == "portable") return "EXE";
                string u = url.Trim().ToLowerInvariant();
                if (u.EndsWith(".msi")) return "MSI";
                if (u.EndsWith(".exe")) return "EXE";
                return "";
            }
            string defType = "", defSilent = "", defSilentWP = "";
            var blocks = new List<Dictionary<string, string>>();
            Dictionary<string, string>? cur = null;
            bool inInstallers = false;
            var kvRx = new System.Text.RegularExpressions.Regex(@"^\s*-?\s*(\w+):\s*(.*?)\s*$");
            foreach (var rawLine in yaml.Split('\n'))
            {
                string line = rawLine.TrimEnd('\r');
                if (!inInstallers)
                {
                    if (System.Text.RegularExpressions.Regex.IsMatch(line, @"^Installers:\s*$")) { inInstallers = true; continue; }
                    var mTop = System.Text.RegularExpressions.Regex.Match(line, @"^InstallerType:\s*(\S+)");
                    if (mTop.Success) defType = mTop.Groups[1].Value;
                    var mDS = System.Text.RegularExpressions.Regex.Match(line, @"^\s+Silent:\s*(.+?)\s*$");
                    if (mDS.Success && defSilent.Length == 0) defSilent = mDS.Groups[1].Value.Trim().Trim('"', '\'');
                    var mDW = System.Text.RegularExpressions.Regex.Match(line, @"^\s+SilentWithProgress:\s*(.+?)\s*$");
                    if (mDW.Success && defSilentWP.Length == 0) defSilentWP = mDW.Groups[1].Value.Trim().Trim('"', '\'');
                    continue;
                }
                if (line.Length > 0 && !char.IsWhiteSpace(line[0]) && !line.StartsWith("-")) break;
                if (System.Text.RegularExpressions.Regex.IsMatch(line, @"^-\s")) { cur = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase); blocks.Add(cur); }
                if (cur == null) continue;
                var m = kvRx.Match(line);
                if (m.Success && !cur.ContainsKey(m.Groups[1].Value)) cur[m.Groups[1].Value] = m.Groups[2].Value.Trim().Trim('"', '\'');
            }
            bool hasMsi = false, hasExe = false, gotExe = false;
            string inst = "", uninst = "", exe = "";
            foreach (var b in blocks)
            {
                string it  = b.TryGetValue("InstallerType", out var v1) ? v1 : "";
                string url = b.TryGetValue("InstallerUrl",  out var v2) ? v2 : "";
                string eff = (it.Length > 0 ? it : defType).Trim().ToLowerInvariant();
                string ty  = MapT(it.Length > 0 ? it : defType, url);
                if (ty == "MSI") hasMsi = true;
                else if (ty == "EXE")
                {
                    hasExe = true;
                    if (!gotExe)   // first EXE installer supplies the filename and the switches
                    {
                        gotExe = true;
                        string iurl = url;
                        int q = iurl.IndexOf('?'); if (q >= 0) iurl = iurl.Substring(0, q);
                        int sl = iurl.LastIndexOf('/');
                        string fn = Uri.UnescapeDataString(sl >= 0 ? iurl.Substring(sl + 1) : iurl);
                        exe = fn.Contains('.') ? fn : "";   // a real filename has an extension (skips odd URLs like .../download)
                        string sil = b.TryGetValue("Silent", out var s1) ? s1
                                   : b.TryGetValue("SilentWithProgress", out var s2) ? s2
                                   : defSilent.Length > 0 ? defSilent : defSilentWP;
                        (string ii, string uu) = eff switch
                        {
                            "nullsoft" => ("/S", "/S"),
                            "inno"     => ("/VERYSILENT /NORESTART", "/VERYSILENT /NORESTART"),
                            "burn"     => ("/quiet /norestart", ""),
                            _          => ("", ""),
                        };
                        inst = sil.Length > 0 ? sil : ii;
                        // Manifests carry only the INSTALL switch. NSIS/Inno keep a clean symmetric
                        // uninstall switch (uu). For a generic exe the uninstall is unknown, except
                        // NSIS's "/S" which is universally symmetric; anything else (e.g. a
                        // self-extractor's "-sfx_nu /sAll /rs /msi") stays blank rather than guessed.
                        uninst = uu.Length > 0 ? uu : (inst == "/S" ? "/S" : "");
                    }
                }
            }
            string type = (hasMsi && hasExe) ? "MSI + EXE" : hasMsi ? "MSI only" : hasExe ? "EXE only" : "type unknown";
            return new WingetCmd { install = inst, uninstall = uninst, exe = exe, type = type };
        }

        // Session-cached: return cached commands for a winget package, else fetch its manifest once
        // from the raw CDN (no API quota), cache EXE apps in memory, and return.
        private static async Task<WingetCmd> WingetCommandsAsync(string id, string version)
        {
            var cache = CommandsCache();
            WingetCmd? cached = null;
            lock (_cmdLock) { if (cache.TryGetValue(id, out var hit)) cached = hit; }
            // A cache hit that actually has switches wins outright. But an entry with BOTH install and
            // uninstall blank can be a stale parse miss - older builds mis-split any manifest that
            // lists InstallModes before InstallerSwitches, caching empty switches. Re-fetch
            // those, keeping the old entry only as an offline fallback so a failed fetch loses nothing.
            if (cached != null && (cached.install.Length > 0 || cached.uninstall.Length > 0)) return cached;
            var meta = new WingetCmd();
            if (string.IsNullOrWhiteSpace(id) || string.IsNullOrWhiteSpace(version) || id.IndexOf('.') < 0) return cached ?? meta;
            try
            {
                string relPath = "manifests/" + char.ToLowerInvariant(id[0]) + "/" + id.Replace('.', '/');
                string verSeg = Uri.EscapeDataString(version);   // versions can contain spaces, e.g. "7.1.0 (41345)"
                string yaml = await _http.GetStringAsync($"https://raw.githubusercontent.com/microsoft/winget-pkgs/master/{relPath}/{verSeg}/{id}.installer.yaml");
                meta = ParseWingetManifest(yaml);
                if (meta.install.Length > 0 || meta.exe.Length > 0)   // an EXE app: persist its filename + switches for offline/manual use
                {
                    lock (_cmdLock) { cache[id] = meta; }
                    SaveCommands();
                }
            }
            catch (Exception ex) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] winget commands: " + ex.Message); return cached ?? meta; }
            return meta;
        }


        // ══════════════════════════════════════════════════════════════════════════════════
        //  GITHUB AUTHENTICATION  (AutoPackage.json -> "GitHubToken")
        // ══════════════════════════════════════════════════════════════════════════════════
        // The CUSTOMER's own token, pasted by their admin in Settings. Nothing is shipped in the
        // product: a token baked into the binary would be one 5,000/hour bucket shared by every
        // customer, and an extractable secret besides.
        //
        //   unauthenticated : 60 requests/hour, per IP
        //   authenticated   : 5,000 requests/hour, per user
        // Public repositories can still be read without a token. A bad configured token is
        // therefore treated as optional: GitHubGetAsync retries public requests without it.
        //
        // A classic PAT with NO scopes ticked is enough - reading public repos needs none.
        // Blank = unchanged behaviour, so this is purely opt-in.
        //
        // It also unlocks free conditional requests. Measured against api.github.com: an
        // If-None-Match request returning 304 still DECREMENTED x-ratelimit-remaining without a
        // token. GitHub's docs say why - a 304 is only free "if the request was made while correctly
        // authorized with an Authorization header". So ETags are worth nothing unauthenticated, and
        // everything once a token is set: an app whose release has not changed then costs zero.
        private static string? _ghToken;
        private static bool    _ghTokenLoaded;

        private static string? GitHubToken()
        {
            if (_ghTokenLoaded) return _ghToken;
            _ghTokenLoaded = true;
            try
            {
                if (File.Exists(JsonPath))
                {
                    using var doc = JsonDocument.Parse(File.ReadAllText(JsonPath));
                    if (doc.RootElement.TryGetProperty("GitHubToken", out var t))
                    {
                        string v = (t.GetString() ?? "").Trim();
                        _ghToken = v.Length > 0 ? v : null;
                    }
                }
            }
            catch (Exception ex) { LogWinget($"[GitHub] token read failed: {ex.Message}"); }
            LogWinget(_ghToken == null
                ? "[GitHub] no token set - unauthenticated, 60 requests/hour"
                : "[GitHub] token found - authenticated, 5,000 requests/hour");
            return _ghToken;
        }

        /// <summary>Clears the cached token so a Save in Settings takes effect without a restart.</summary>
        private static void ResetGitHubToken() { _ghTokenLoaded = false; _ghToken = null; }

        /// <summary>
        /// GETs an api.github.com URL with the token attached when one is configured, and with an
        /// ETag conditional request so an unchanged resource costs nothing.
        ///
        /// Returns null on 304 (unchanged - the caller keeps its cached data) and throws on a real
        /// failure, which is what the existing callers already expect.
        /// </summary>
        private static readonly Dictionary<string, string> _ghETags = new(StringComparer.OrdinalIgnoreCase);

        private static async Task<string?> GitHubGetAsync(string url)
        {
            using var req = new HttpRequestMessage(HttpMethod.Get, url);

            string? token = GitHubToken();
            if (!string.IsNullOrEmpty(token))
                req.Headers.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", token);

            if (_ghETags.TryGetValue(url, out string? etag) && !string.IsNullOrEmpty(etag))
                req.Headers.TryAddWithoutValidation("If-None-Match", etag);

            HttpResponseMessage resp = await _http.SendAsync(req).ConfigureAwait(false);
            try
            {
                // Public GitHub repositories do not require authentication. If a configured customer
                // token is expired/revoked/malformed, GitHub returns 401 before evaluating the public
                // resource. Retry once without the token so a bad optional credential cannot break
                // public GitHub downloads or scheduled updates.
                if (resp.StatusCode == System.Net.HttpStatusCode.Unauthorized && !string.IsNullOrEmpty(token))
                {
                    LogWinget($"[GitHub] 401 Unauthorized for {url} with configured token; retrying without authentication");
                    resp.Dispose();

                    using var publicReq = new HttpRequestMessage(HttpMethod.Get, url);
                    if (_ghETags.TryGetValue(url, out string? publicEtag) && !string.IsNullOrEmpty(publicEtag))
                        publicReq.Headers.TryAddWithoutValidation("If-None-Match", publicEtag);

                    resp = await _http.SendAsync(publicReq).ConfigureAwait(false);
                }

                if (resp.StatusCode == System.Net.HttpStatusCode.NotModified)
                    return null;   // caller keeps its cached info

                resp.EnsureSuccessStatusCode();

                if (resp.Headers.ETag != null)
                    _ghETags[url] = resp.Headers.ETag.ToString();

                return await resp.Content.ReadAsStringAsync().ConfigureAwait(false);
            }
            finally
            {
                resp.Dispose();
            }
        }


        public SourceDownloadPage()
        {
            InitializeComponent();
            // Up/Down move the vendor or app selection (whichever column was clicked
            // last); the page must be focusable for its PreviewKeyDown to see the keys.
            Focusable = true;
            PreviewKeyDown += OnColumnKeyNav;
            // Rebuild code-built UI whenever the theme changes — works for every
            // instance of this page, wherever it is hosted.
            ThemeManager.ThemeChanged += () =>
                Dispatcher.BeginInvoke(new Action(RefreshAfterThemeChange));
            // Load apps immediately so scheduler can run before page is visited
            LoadApps();
            Loaded += (_, _) =>
            {
                _liveInstance = this;   // target for ReportPackageError from the other Auto tabs
                _mainWindow ??= Window.GetWindow(this) as IAutoPackageHost;
                LoadApps(); // Reload on each navigation to pick up any changes
                BuildCategoryChips();

                // Restore the vendor selection BEFORE RenderVendors so it doesn't
                // auto-reset to the first alphabetical vendor on every navigation.
                if (_lastSelectedVendor != null)
                    _selectedVendor = _lastSelectedVendor;

                // Defer first render to ensure theme resources are fully loaded
                Dispatcher.InvokeAsync(() => {
                    RenderVendors();
                    RenderCards();
                }, System.Windows.Threading.DispatcherPriority.Render);

                // Restore the previously selected app if one exists; fall back to first app on first visit
                var appToSelect = (_lastSelectedVendor != null && _lastSelectedAppName != null)
                    ? _allApps.FirstOrDefault(a =>
                          a.SourceAppVendor  == _lastSelectedVendor &&
                          a.SourceAppName == _lastSelectedAppName)
                    : null;

                appToSelect ??= _allApps.OrderBy(a => a.SourceAppVendor).ThenBy(a => a.SourceAppName).FirstOrDefault();

                if (appToSelect != null)
                    Dispatcher.InvokeAsync(() => SelectApp(appToSelect),
                        System.Windows.Threading.DispatcherPriority.Render);

                // No periodic version check. Nothing polls vendors on a timer any more - the version
                // data is refreshed once at startup (from the cache, so usually with no network calls
                // at all) and thereafter only when the user presses "Check now" in the Downloads
                // window. The old timer ran every 30 minutes, cleared the live version map and swept
                // every app; harmless once caching was added, but it was still the app deciding on its
                // own when to go out to the network.
                //
                // The startup sweep itself lives inside ReportMissedSchedulesAsync below - it has to
                // await it anyway to know what is out of date, so running it here as well was doing
                // the same work twice.

                // ── Slow the mouse wheel, everywhere on this page ──────────────────────────────
                //
                // WPF's default is 3 * SystemParameters.WheelScrollLines per notch, which on a
                // pixel-scrolling StackPanel is a ~150px jump - the vendor and app lists fly past, and
                // so do the dropdown lists.
                //
                // ONE handler on the page, not one per ScrollViewer. A ComboBox dropdown's ScrollViewer
                // lives inside a Popup, so hooking the four column ScrollViewers could never reach it -
                // every dropdown (API Type, Winget Package ID, Category, Frequency, Days, Date, Time,
                // Month, and any added later) would have needed wiring individually.
                //
                // Instead: find the ScrollViewer the mouse is actually OVER and scroll that one. Popup
                // content routes its events up through this page, so a dropdown is reached the same way
                // as the panels, with no special case.
                // Item-scroll targets (every ComboBox dropdown) count VerticalOffset in whole ROWS,
                // and ScrollToVerticalOffset rounds a fractional row back to the same row. A mouse
                // wheel sends Delta = 120 per click, so notches = 1 and one row moves. A touchpad
                // sends a stream of SMALL deltas (4, 8, 20, ...), so notches is a fraction that rounds
                // to zero every event - the dropdown sits frozen until the deltas happen to sum to a
                // full 120. Fix: carry the fractional part across events and scroll only once a whole
                // row has built up. Reset the running total when the pointer moves to a different
                // scroller so a leftover fraction from one dropdown never leaks into the next. Pixel
                // targets (the four column panels) already scroll smoothly on a touchpad, so they are
                // left exactly as before.
                double wheelItemAccum = 0;
                ScrollViewer? wheelItemTarget = null;
                PreviewMouseWheel += (_, me) =>
                {
                    var target = ScrollViewerUnderMouse();
                    if (target == null) return;

                    double notches = me.Delta / 120.0;   // one wheel click = 120

                    if (target.CanContentScroll)
                    {
                        // ITEM scrolling: VerticalOffset counts ROWS, not pixels.
                        //
                        // This is the case for every ComboBox dropdown, and it is why the dropdowns
                        // stayed fast while the panels went slow: subtracting a PIXEL count of 32 from
                        // an item-based offset jumps 32 ROWS per notch, not 32 pixels.
                        //
                        // Start a fresh accumulator whenever the pointer lands on a different scroller.
                        if (!ReferenceEquals(target, wheelItemTarget))
                        {
                            wheelItemTarget = target;
                            wheelItemAccum = 0;
                        }

                        const double NOTCH_ITEMS = 1;
                        wheelItemAccum += notches * NOTCH_ITEMS;

                        // Truncate toward zero and keep the remainder so small touchpad deltas add up
                        // instead of being discarded.
                        int wholeRows = (int)wheelItemAccum;
                        if (wholeRows != 0)
                        {
                            target.ScrollToVerticalOffset(target.VerticalOffset - wholeRows);
                            wheelItemAccum -= wholeRows;
                        }
                    }
                    else
                    {
                        // PIXEL scrolling: the four column panels. WPF's default is ~150px per notch.
                        const double NOTCH_PX = 32;
                        target.ScrollToVerticalOffset(target.VerticalOffset - notches * NOTCH_PX);
                    }

                    me.Handled = true;
                };

                // Start scheduler — checks every 10 seconds so downloads trigger within ~10s of scheduled time
                //
                // ONCE per instance. Loaded fires again on every re-navigation to the Download tab,
                // and Unloaded deliberately does not stop the timer, so an unguarded create left the
                // old timer running AND overwrote the only field pointing at it - it could no longer
                // even be stopped. A DispatcherTimer is rooted by the dispatcher, so each visit added
                // one more permanent ticker (and pinned the dead page instance it captured). Four
                // tickers meant four scheduler passes per interval.
                //
                // _pageScheduleTimer is static so an instance taking over can retire the timer left
                // behind by the one before it.
                if (_scheduleTimer == null)
                {
                    try { _pageScheduleTimer?.Stop(); }
                    catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }

                    _scheduleTimer = new System.Windows.Threading.DispatcherTimer
                    {
                        Interval = TimeSpan.FromSeconds(10),
                    };
                    _scheduleTimer.Tick += (_, _) => _ = RunScheduledDownloadsAsync();
                    _scheduleTimer.Start();
                    _pageScheduleTimer = _scheduleTimer;
                }

                // NOT a catch-up download. See ReportMissedSchedulesAsync: a schedule missed while the
                // app was closed is REPORTED, never silently downloaded on startup.
                //
                // The session is stamped ONCE per run. Loaded fires again every time the Download tab
                // is returned to, and re-stamping moved the "before this session" line forward, so
                // slots that fired while the app was up and running started counting as missed while
                // it was closed. The sweep itself still runs on every load - it refreshes the version
                // data and the Updates badge - but only the first one can raise the window.
                if (!_sessionStamped)
                {
                    _sessionStamped = true;

                    // TRUNCATED TO THE MINUTE, deliberately. A scheduled slot is built at minute
                    // precision - its seconds are always 0 - so a raw DateTime.Now stamp loses every
                    // schedule due in the very minute the app starts: slot 10:25:00 against a session
                    // stamped 10:25:02 compares as "before this session" and is written off as missed
                    // while closed. Five apps due at 10:25 were dropped in a single tick that way.
                    var stamp = DateTime.Now;
                    _sessionStart = new DateTime(stamp.Year, stamp.Month, stamp.Day,
                                                 stamp.Hour, stamp.Minute, 0);
                }
                _ = ReportMissedSchedulesAsync();
            };

            Unloaded += (_, _) =>
            {
                // Schedule timer kept running — ownership transferred to MainWindow on first load
            };
        }

        // ── Refresh button ─────────────────────────────────────────────────
        /// <summary>
        /// Finds the Yes/No radio-button row in PnlPackageInfo whose label matches
        /// <paramref name="label"/> and sets it to <paramref name="value"/> ("Yes"/"No").
        /// Called from left-panel checkbox handlers so both panels stay in sync.
        /// </summary>
        private void SyncPkgInfoRadio(string label, string value)
        {
            if (PnlPackageInfo == null) return;
            foreach (var child in PnlPackageInfo.Children)
            {
                if (child is not Grid g || g.Children.Count < 2) continue;
                if (g.Children[0] is not TextBlock lbl) continue;
                if (!lbl.Text.Equals(label, StringComparison.OrdinalIgnoreCase)) continue;

                IEnumerable<RadioButton>? radios = null;
                if (g.Children[1] is StackPanel sp) radios = sp.Children.OfType<RadioButton>();
                else if (g.Children[1] is WrapPanel wp) radios = wp.Children.OfType<RadioButton>();
                if (radios == null) break;

                bool isYesNoRow = radios.Any(r =>
                    (r.Content?.ToString() ?? "").Equals("Yes", StringComparison.OrdinalIgnoreCase));

                foreach (var rb in radios)
                {
                    string content = rb.Content?.ToString() ?? "";
                    rb.IsChecked = isYesNoRow
                        ? (value.Equals("No", StringComparison.OrdinalIgnoreCase)
                            ? content.Equals("No",  StringComparison.OrdinalIgnoreCase)
                            : content.Equals("Yes", StringComparison.OrdinalIgnoreCase))
                        : content.Equals(value, StringComparison.OrdinalIgnoreCase);
                }
                break;
            }
        }

        /// <summary>Enable/disable a Yes/No radio row in the Package Information column by label.</summary>
        private void SetPkgInfoRadioEnabled(string label, bool enabled)
        {
            if (PnlPackageInfo == null) return;
            foreach (var child in PnlPackageInfo.Children)
            {
                if (child is not Grid g || g.Children.Count < 2) continue;
                if (g.Children[0] is not TextBlock lbl) continue;
                if (!lbl.Text.Equals(label, StringComparison.OrdinalIgnoreCase)) continue;
                if (g.Children[1] is StackPanel sp) sp.IsEnabled = true;
                else if (g.Children[1] is WrapPanel wp) wp.IsEnabled = true;
                break;
            }
        }

        /// <summary>
        /// Refreshes the Silent Install and Silent Uninstall text boxes in PnlPackageInfo
        /// based on the last triggered download type (EXE or MSI).
        /// Called when a download button is clicked.
        /// </summary>
        // ── Req 5: persist ONLY DownloadPreference to the per-app JSON ─────────
        // Updates the single "DownloadPreference" value inside the existing
        // VendorName_AppName.json, leaving every other variable byte-identical.
        // Never re-serializes the whole entry (which could alter other fields).
        private static void SaveDownloadPreferenceOnly(DownloadSourceEntry app, string newPref)
        {
            try
            {
                var path = GetAppJsonPath(app);
                if (path == null || !File.Exists(path)) return;

                System.Text.Json.Nodes.JsonNode? node;
                using (var fs = File.OpenRead(path))
                    node = System.Text.Json.Nodes.JsonNode.Parse(fs);
                if (node is not System.Text.Json.Nodes.JsonObject obj) return;

                // Only touch DownloadPreference — do not add/remove/modify anything else.
                obj["DownloadPreference"] = newPref;

                File.WriteAllText(path, obj.ToJsonString(
                    new JsonSerializerOptions { WriteIndented = true }));
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
        }

        // ── Req 4: lock the Download-Information + Package-Information columns ──
        // while a download (and its chained actions) run. The Cancel "X" lives in
        // PnlHeaderProgress, a separate panel, so it stays fully clickable.
        private bool _downloadColumnsLocked = false;

        // True between download-completion and the end of the auto-flow chain
        // (Package → Execute → Intunewin → Publish). While set, RemoveDownloadProgress
        // must NOT unlock the columns — only the AutoPackagePage all-complete callback
        // (or a cancel/error) may unlock. Prevents premature unlock when the download
        // finishes but the downstream tabs are still working.
        private bool _autoFlowChainPending = false;

        private void LockDownloadAndPackageColumns()
        {
            _downloadColumnsLocked = true;
            // Download-information column body (links, checkboxes, open-page button…).
            // Whole panel disabled — only the Cancel "X" (in PnlHeaderProgress) stays usable.
            if (PnlAppInfo != null)
            {
                PnlAppInfo.IsHitTestVisible = false;
                PnlAppInfo.Focusable        = false;
                PnlAppInfo.Opacity          = 0.55;
            }
            // Package-information column: lock the ENTIRE column, including the
            // Download Preference row. Nothing here may change until all actions
            // complete. Lock the whole panel in one shot.
            if (PnlPackageInfo != null)
            {
                PnlPackageInfo.IsHitTestVisible = false;
                PnlPackageInfo.Focusable        = false;
                PnlPackageInfo.Opacity          = 0.55;
            }

            // Lock the rest of the Download tab during the flow: the Vendor list, the
            // Application list, the category filter buttons, the search box, and the
            // Add App / Refresh buttons. The user may not start another action mid-flow.
            void Disable(UIElement? e, double op = 0.55)
            {
                if (e == null) return;
                e.IsHitTestVisible = false;
                e.Focusable        = false;
                e.Opacity          = op;
            }
            Disable(PnlVendors);
            Disable(PnlCards);
            Disable(PnlCategories);
            Disable(TxtSearch, 0.6);
            Disable(BtnUpdates);    // its "Check now" goes to the network - not during a download
            Disable(BtnAddApp);
            Disable(BtnSettings);   // Settings disabled during download / install-source / uninstall-source

            // Lock the Auto Package sub-tab bar so the user cannot switch tabs mid-flow;
            // the automation still switches programmatically via ActivateTopTab.
            AutoFlowStatus.FlowRunning = true;
            _flowLockedAt = DateTime.Now;   // watchdog: see RunScheduledDownloadsAsync
        }

        private void UnlockDownloadAndPackageColumns()
        {
            _downloadColumnsLocked = false;
            if (PnlAppInfo != null)
            {
                PnlAppInfo.IsHitTestVisible = true;
                PnlAppInfo.Focusable        = true;
                PnlAppInfo.Opacity          = 1.0;
            }
            if (PnlPackageInfo != null)
            {
                PnlPackageInfo.IsHitTestVisible = true;
                PnlPackageInfo.Focusable        = true;
                PnlPackageInfo.Opacity          = 1.0;
            }

            void Enable(UIElement? e)
            {
                if (e == null) return;
                e.IsHitTestVisible = true;
                e.Focusable        = true;
                e.Opacity          = 1.0;
            }
            Enable(PnlVendors);
            Enable(PnlCards);
            Enable(PnlCategories);
            Enable(TxtSearch);
            Enable(BtnUpdates);
            Enable(BtnAddApp);
            Enable(BtnSettings);
            // NOTE: AutoFlowStatus.FlowRunning is intentionally NOT cleared here. This unlock also
            // fires mid-flow (the "uninstall source" safety net) while Package/Intunewin/Publish are
            // still to come; the tab lock must persist. It is cleared at the true whole-flow end
            // (AutoFlowStatus.Finish), and on the download-only / cancel paths.
        }

        private void UpdatePackageInfoSilentParams()
        {
            if (PnlPackageInfo == null || _selectedApp == null) return;

            // Use triggered type if set, otherwise fall back to DownloadPreference
            string effectiveType = !string.IsNullOrWhiteSpace(_lastTriggeredDownloadType)
                ? _lastTriggeredDownloadType
                : (_selectedApp.DownloadPreference ?? "EXE_x64").ToUpperInvariant().StartsWith("MSI")
                    ? "MSI" : "EXE";

            bool isMsi = effectiveType.Equals("MSI", StringComparison.OrdinalIgnoreCase);

            string instVal   = isMsi ? (_selectedApp.SilentInstallParameterMSI   ?? "")
                                     : (_selectedApp.SilentInstallParameterEXE   ?? "");
            string uninstVal = isMsi ? (_selectedApp.SilentUninstallParameterMSI ?? "")
                                     : (_selectedApp.SilentUninstallParameterEXE ?? "");

            // Find the tagged text boxes by walking PnlPackageInfo children
            foreach (var child in PnlPackageInfo.Children)
            {
                if (child is Grid row && row.Tag is string tag)
                {
                    if (tag == "SilentInstall" && row.Children.Count > 1 && row.Children[1] is TextBox tbInst)
                        tbInst.Text = instVal;
                    if (tag == "SilentUninstall" && row.Children.Count > 1 && row.Children[1] is TextBox tbUninst)
                        tbUninst.Text = uninstVal;
                }
            }
        }

        // ── Refresh button (now in toolbar XAML) ──────────────────────────
        /// <summary>
        /// Goes and looks: re-pulls the winget catalog and re-queries every vendor, bypassing the
        /// 6-hour cache. This is the ONLY thing in the app that touches the network on demand -
        /// everything else (page load, the hourly timer, the scheduler, the Updates window) reads the
        /// cache and makes no calls at all.
        ///
        /// It used to be the toolbar's Refresh button, which sat next to Updates and looked like it
        /// did the same thing. It now lives inside the Downloads window, beside a "last checked"
        /// timestamp - so LOOKING at update information is free and instant, and CHECKING is a
        /// deliberate act you take when the timestamp tells you it is worth it.
        ///
        /// Worth knowing: this is also the last thing that can exhaust GitHub's 60/hour, because it
        /// forces a call for every app with API Type = github. Winget apps cost nothing (local
        /// catalog).
        /// </summary>
        private async Task CheckForUpdatesNowAsync()
        {
            _liveVersionCache.Clear();
            await FetchAllVersionsInBackgroundAsync(force: true);
            RefreshUpdatesBadge();
            ExportStatusWorkbook();
        }

        /// <summary>
        /// When the version data was last actually fetched. Taken from the persistent info cache, so
        /// it survives a restart and tells the truth about how stale the numbers are.
        /// </summary>
        private static DateTime? LastVersionCheck()
        {
            LoadInfoCache();
            if (_infoCache.Count == 0) return null;
            return _infoCache.Values.Max(v => v.At).ToLocalTime();
        }

        // ── Status Workbook Export ─────────────────────────────────────────
        /// <summary>
        /// Exports "Auto Package Applications Status.xlsx": an Applications sheet (the full
        /// catalog of added apps) plus three sheets mirroring the Downloads window - Missed Auto
        /// Schedules, Auto Schedules Status (latest verdict per app) and Updates Available - with
        /// the same columns as the window's tables.
        /// Written with System.IO.Packaging (built into WPF), no extra libraries, and
        /// refreshed automatically whenever an app's status changes (see QueueStatusWorkbook).
        /// Replaces the old single-sheet "...Version Report.xlsx", which is deleted here so
        /// only one report ever exists in the folder.
        /// </summary>
        private void ExportStatusWorkbook()
        {
            try
            {
                // Use AppVersionReportPath if configured, otherwise fall back to SourceDownloadPath
                string folder = !string.IsNullOrWhiteSpace(_appVersionReportPath)
                    ? _appVersionReportPath
                    : !string.IsNullOrWhiteSpace(_sourceDownloadPath)
                        ? _sourceDownloadPath
                        : @"C:\Temp\Source";
                Directory.CreateDirectory(folder);

                string xlsxPath = Path.Combine(folder, "Auto Package Applications Status.xlsx");

                static string X(string? v) => System.Security.SecurityElement.Escape(v ?? "") ?? "";
                string[] colLetters = { "A", "B", "C", "D", "E", "F", "G", "H" };

                string RowsXml(string[] headers, IEnumerable<string[]> rows)
                {
                    var sb = new System.Text.StringBuilder();
                    sb.Append("<row r=\"1\">");
                    for (int c = 0; c < headers.Length; c++)
                        sb.Append($"<c r=\"{colLetters[c]}1\" s=\"1\" t=\"inlineStr\"><is><t>{X(headers[c])}</t></is></c>");
                    sb.Append("</row>");
                    int r = 2;
                    foreach (var vals in rows)
                    {
                        sb.Append($"<row r=\"{r}\">");
                        for (int c = 0; c < vals.Length; c++)
                            sb.Append($"<c r=\"{colLetters[c]}{r}\" s=\"2\" t=\"inlineStr\"><is><t xml:space=\"preserve\">{X(vals[c])}</t></is></c>");
                        sb.Append("</row>");
                        r++;
                    }
                    return sb.ToString();
                }

                const string nsMain = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";

                string SheetXml(int colCount, string rowsXml) =>
                    "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>" +
                    $"<worksheet xmlns=\"{nsMain}\">" +
                    "<cols><col min=\"1\" max=\"2\" width=\"24\" customWidth=\"1\"/>" +
                    $"<col min=\"3\" max=\"{colCount}\" width=\"20\" customWidth=\"1\"/></cols>" +
                    $"<sheetData>{rowsXml}</sheetData></worksheet>";

                // The exact rows the Downloads window shows, from the same builders, so the
                // workbook and the window can never disagree about an app's status.
                DateTime now = DateTime.Now;
                var (missed, updates) = BuildUpdateLists(now);

                string[] MissedVals(MissedRow m)  => new[] { m.Vendor, m.AppName, m.ExistingVersion, m.NewVersion, m.Schedule, m.ExistingSchedule, m.NewSchedule };

                var statusRows = LoadScheduleOutcomes()
                    .GroupBy(o => (o.Vendor + "|" + o.AppName).ToLowerInvariant())
                    .Select(gr => gr.First())
                    // Match the Auto Schedules Status tab: only apps still in the catalog. The history
                    // log on disk keeps every outcome; this filters what the sheet exports.
                    .Where(o => _allApps.Any(a =>
                        string.Equals(a.SourceAppVendor, o.Vendor,  StringComparison.OrdinalIgnoreCase) &&
                        string.Equals(a.SourceAppName,   o.AppName, StringComparison.OrdinalIgnoreCase)))
                    .Select(o =>
                    {
                        var appRef = _allApps.FirstOrDefault(a =>
                            string.Equals(a.SourceAppVendor, o.Vendor,  StringComparison.OrdinalIgnoreCase) &&
                            string.Equals(a.SourceAppName,   o.AppName, StringComparison.OrdinalIgnoreCase));
                        DateTime? nextRun = appRef != null ? NextScheduledOccurrence(appRef, now) : null;
                        return new[]
                        {
                            o.Vendor, o.AppName, o.ExistingVersion, o.NewVersion, o.Schedule, o.Status, o.At,
                            nextRun.HasValue ? nextRun.Value.ToString("ddd dd-MM-yyyy HH:mm") : "-",
                        };
                    })
                    .ToList();

                string sheet1 = SheetXml(7, RowsXml(
                    new[] { "Vendor", "App Name", "Existing Version", "New Version", "Schedule", "Existing Schedule", "Next Schedule" },
                    missed.Select(MissedVals)));
                string sheet2 = SheetXml(8, RowsXml(
                    new[] { "Vendor", "App Name", "Existing Version", "New Version", "Schedule", "Status", "Completed At", "Next Schedule" },
                    statusRows));
                string sheet3 = SheetXml(7, RowsXml(
                    new[] { "Vendor", "App Name", "Existing Version", "New Version", "Schedule", "Auto Download", "Next Scheduled" },
                    updates.Select(MissedVals)));

                // Applications sheet: the full catalog (every app added via Add App), independent of
                // any update/schedule state. "Source" shows the identifier the API Type actually uses.
                static string SourceId(DownloadSourceEntry a)
                {
                    string t = (a.ApiType ?? "").Trim();
                    if (t.Equals("winget", StringComparison.OrdinalIgnoreCase))     return a.WingetPackageId ?? "";
                    if (t.Equals("github", StringComparison.OrdinalIgnoreCase))     return a.GitHubRepo ?? "";
                    if (t.Equals("Vendor API", StringComparison.OrdinalIgnoreCase)) return a.VendorApiId ?? "";
                    return a.DownloadPageUrl ?? "";
                }
                var appRows = _allApps
                    .OrderBy(a => a.SourceAppVendor, StringComparer.OrdinalIgnoreCase)
                    .ThenBy(a => a.SourceAppName,   StringComparer.OrdinalIgnoreCase)
                    .Select(a => new[] { a.SourceAppVendor, a.SourceAppName, a.SourceAppVersion, a.ApiType, a.Category, SourceId(a) })
                    .ToList();
                string sheetApps = SheetXml(6, RowsXml(
                    new[] { "Vendor", "App Name", "Version", "API Type", "Category", "Source" },
                    appRows));

                // Display order in the workbook: Applications (full catalog) first, then the three
                // status sheets. sheetId and r:id follow this order; the worksheet parts below are
                // written in the same order.
                var sheetDefs = new (string name, string xml)[]
                {
                    ("Applications",          sheetApps),
                    ("Missed Auto Schedules", sheet1),
                    ("Auto Schedules Status", sheet2),
                    ("Updates Available",     sheet3),
                };

                var sheetsSb = new System.Text.StringBuilder();
                for (int i = 0; i < sheetDefs.Length; i++)
                    sheetsSb.Append($"<sheet name=\"{X(sheetDefs[i].name)}\" sheetId=\"{i + 1}\" r:id=\"rId{i + 1}\"/>");
                string workbookXml =
                    "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>" +
                    $"<workbook xmlns=\"{nsMain}\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\">" +
                    "<sheets>" + sheetsSb + "</sheets></workbook>";

                string stylesXml =
                    "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>" +
                    $"<styleSheet xmlns=\"{nsMain}\">" +
                    "<fonts count=\"2\"><font><sz val=\"11\"/><name val=\"Calibri\"/></font>" +
                    "<font><b/><sz val=\"11\"/><name val=\"Calibri\"/></font></fonts>" +
                    "<fills count=\"2\"><fill><patternFill patternType=\"none\"/></fill>" +
                    "<fill><patternFill patternType=\"gray125\"/></fill></fills>" +
                    "<borders count=\"2\"><border><left/><right/><top/><bottom/><diagonal/></border>" +
                    "<border><left style=\"thin\"/><right style=\"thin\"/><top style=\"thin\"/><bottom style=\"thin\"/><diagonal/></border></borders>" +
                    "<cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs>" +
                    "<cellXfs count=\"3\">" +
                    "<xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\"/>" +
                    "<xf numFmtId=\"0\" fontId=\"1\" fillId=\"0\" borderId=\"1\" xfId=\"0\" applyFont=\"1\" applyBorder=\"1\"/>" +
                    "<xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"1\" xfId=\"0\" applyBorder=\"1\"/>" +
                    "</cellXfs>" +
                    "<cellStyles count=\"1\"><cellStyle name=\"Normal\" xfId=\"0\" builtinId=\"0\"/></cellStyles></styleSheet>";

                using var pkgFs = new FileStream(xlsxPath, FileMode.Create, FileAccess.ReadWrite);
                using (var pkg = System.IO.Packaging.Package.Open(pkgFs, FileMode.Create))
                {
                    var wbUri = new Uri("/xl/workbook.xml", UriKind.Relative);
                    var stUri = new Uri("/xl/styles.xml", UriKind.Relative);

                    var wbPart = pkg.CreatePart(wbUri, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml");
                    var stPart = pkg.CreatePart(stUri, "application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml");

                    pkg.CreateRelationship(wbUri, System.IO.Packaging.TargetMode.Internal,
                        "http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument", "rId1");

                    static void WritePart(System.IO.Packaging.PackagePart part, string xml)
                    {
                        using var st = part.GetStream(FileMode.Create, FileAccess.Write);
                        byte[] bytes = System.Text.Encoding.UTF8.GetBytes(xml);
                        st.Write(bytes, 0, bytes.Length);
                    }

                    for (int i = 0; i < sheetDefs.Length; i++)
                    {
                        var wsUri  = new Uri($"/xl/worksheets/sheet{i + 1}.xml", UriKind.Relative);
                        var wsPart = pkg.CreatePart(wsUri, "application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml");
                        wbPart.CreateRelationship(new Uri($"worksheets/sheet{i + 1}.xml", UriKind.Relative),
                            System.IO.Packaging.TargetMode.Internal,
                            "http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet", $"rId{i + 1}");
                        WritePart(wsPart, sheetDefs[i].xml);
                    }
                    wbPart.CreateRelationship(new Uri("styles.xml", UriKind.Relative),
                        System.IO.Packaging.TargetMode.Internal,
                        "http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles", $"rId{sheetDefs.Length + 1}");

                    WritePart(wbPart, workbookXml);
                    WritePart(stPart, stylesXml);
                }

                // Remove the retired reports so only the status workbook exists.
                foreach (string old in new[] { "Auto Package Applications Version Report.xlsx",
                                               "Auto Package Applications Version Report.csv" })
                {
                    try
                    {
                        string p = Path.Combine(folder, old);
                        if (File.Exists(p)) File.Delete(p);
                    }
                    catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                }
            }
            catch { /* silently ignore export errors */ }
        }

        // Coalesces workbook refreshes: status changes arrive in bursts (a batch of scheduled
        // downloads, several outcome records seconds apart) and from worker threads, so every
        // trigger goes through here - marshalled to the UI thread at Background priority, and
        // a pending refresh absorbs any further requests until it runs.
        private bool _statusWorkbookQueued;
        internal void QueueStatusWorkbook()
        {
            if (_statusWorkbookQueued) return;
            _statusWorkbookQueued = true;
            Dispatcher.BeginInvoke((Action)(() =>
            {
                _statusWorkbookQueued = false;
                ExportStatusWorkbook();
            }), System.Windows.Threading.DispatcherPriority.Background);
        }

        // ── Scheduled Auto-Download ────────────────────────────────────────
        /// <summary>

        /// Returns true if 'date' is the Nth occurrence of 'weekday' in its month.
        private static bool IsNthWeekdayOfMonth(DateTime date, DayOfWeek weekday, int n)
        {
            if (date.DayOfWeek != weekday) return false;
            // Count how many times this weekday has occurred so far this month
            int count = 0;
            for (int d = 1; d <= date.Day; d++)
                if (new DateTime(date.Year, date.Month, d).DayOfWeek == weekday) count++;
            return count == n;
        }

        /// Checks all apps where SourceDownload = "Yes" and fires a download
        /// if the current time matches the app's DownloadFrequency + DownloadScheduleTime.
        /// Called every minute by _scheduleTimer.
        /// </summary>
        // Re-entrancy guard. _scheduleTimer ticks every 10 seconds, and this method awaits a
        // download that can take minutes - without this, a second tick starts a SECOND app while the
        // first is still going. It closes the window between an app being picked and
        // AutoFlowStatus.FlowRunning going true.
        private static bool _schedulerBusy = false;

        /// <summary>
        /// Set by a scheduled download that recorded a new version, cleared by the repaint at the
        /// end of RunScheduledDownloadsAsync. Static for the same reason the timer is: it has to
        /// survive the page instance being rebuilt mid-batch.
        /// </summary>
        private static bool _repaintPending = false;

        private static DateTime _flowLockedAt = DateTime.MinValue;   // when AutoFlowStatus.FlowRunning was taken
        private static DateTime _lastBlockLog = DateTime.MinValue;   // throttles the "waiting" log line

        // app|slot keys already reported this session, so a missed slot is logged once and not on
        // every tick for the rest of the day. Static: it must outlive a page rebuild on navigation.
        private static readonly HashSet<string> _loggedMissedSlots = new();

        /// <summary>Period skips already written to the log, keyed app+period. Same reason as
        /// _loggedMissedSlots: the condition holds for the whole period, so an unkeyed line repeats
        /// every 10 seconds. It filled 1,829 of 2,017 lines in one day's log.</summary>
        private static readonly HashSet<string> _loggedPeriodSkips = new();

        /// <summary>
        /// Scheduler log: %TEMP%\SwiftPack_Scheduler.log
        ///
        /// The scheduler used to explain itself only through Debug.WriteLine, which is invisible in a
        /// release build - so "it did not download and I do not know why" was unanswerable. Every
        /// decision that stops a download now leaves a line here.
        ///
        /// Append-only and never cleaned up, so the file is rolled at 1 MB keeping one previous
        /// generation. A log that grows without limit eventually stops being read at all.
        /// </summary>
        private const long SchedLogMaxBytes = 1024 * 1024;

        private static void LogSched(string line)
        {
            try
            {
                string path = Path.Combine(Path.GetTempPath(), "SwiftPack_Scheduler.log");

                try
                {
                    var fi = new FileInfo(path);
                    if (fi.Exists && fi.Length > SchedLogMaxBytes)
                        File.Move(path, Path.Combine(Path.GetTempPath(), "SwiftPack_Scheduler.prev.log"), overwrite: true);
                }
                catch (Exception exRoll) { System.Diagnostics.Debug.WriteLine("[LogSched] roll: " + exRoll.Message); }

                File.AppendAllText(path, $"[{DateTime.Now:yyyy-MM-dd HH:mm:ss}] {line}\r\n");
            }
            catch (Exception ex) { System.Diagnostics.Debug.WriteLine("[LogSched] " + ex.Message); }
        }

        public async Task RunScheduledDownloadsAsync()
        {
            // ── ONE app's ENTIRE chain at a time ────────────────────────────────────────────────
            // A scheduled app does not just download. Depending on its Download Information flags it
            // goes on to install the source, create the package, install/uninstall it, build the
            // .intunewin, publish to Intune and mail the owner - 5 to 10 minutes. Starting a second
            // app's download in the middle of that would interleave two flows through the same shared
            // state (_selectedApp, the package folder, the Auto Package tabs) and corrupt both.
            //
            // AutoFlowStatus.FlowRunning is already exactly this lock: set when the columns lock at
            // the start of a download, cleared ONLY at the true whole-flow end (AutoFlowStatus.Finish),
            // on cancel, or on the download-only path. So: if a flow is running, do nothing. The
            // 10-second timer is the queue pump - it comes back and starts the next app once the
            // previous one has completely finished.
            if (_schedulerBusy) return;

            // A manual feature owns the app: hold off. Deliberately WITHOUT stamping the
            // period slot - by the retry contract above, an unstamped slot stays queued and
            // fires as soon as the manual work ends, so a scheduled download is delayed,
            // never lost. One log line per slot so the delay is never a mystery.
            if (AppBusy.ManualRunning)
            {
                string holdKey = "manual|" + DateTime.Now.ToString("yyyy-MM-dd HH");
                if (_loggedPeriodSkips.Add(holdKey))
                    LogSched($"scheduler holding: a manual feature is running ({AppBusy.ManualReason}) - " +
                             $"due apps stay queued and run when it finishes");
                return;
            }

            if (AutoFlowStatus.FlowRunning)
            {
                // WATCHDOG.
                //
                // This lock is the whole serialisation mechanism, and it is cleared in only three
                // places: AutoFlowStatus.Finish, cancel, and the download-only path. If a flow throws
                // anywhere before one of those, FlowRunning stays true FOREVER - and with it the
                // scheduler is dead. Silently: nothing downloads, nothing says why, and closing and
                // reopening the app is the only thing that clears it (which is exactly the symptom
                // reported).
                //
                // No real chain - download, install source, create package, intunewin, publish, mail -
                // runs for an hour. If the lock is older than that, it is stuck, not busy.
                TimeSpan held = _flowLockedAt == DateTime.MinValue
                    ? TimeSpan.Zero : DateTime.Now - _flowLockedAt;

                if (held > TimeSpan.FromHours(1))
                {
                    LogSched($"WARNING: flow lock held for {held.TotalMinutes:F0} min (since {_flowLockedAt:HH:mm:ss}). " +
                             "No flow runs that long - treating it as a crashed flow and releasing the lock.");
                    AutoFlowStatus.FlowRunning = false;
                    _flowLockedAt = DateTime.MinValue;
                    // The nav lock rides on the same flow: releasing one without the other
                    // would leave the manual features greyed out until the app restarts.
                    AppBusy.SetAuto("Auto Package chain", false);
                    AppBusy.SetAuto("Download", false);
                }
                else
                {
                    if (DateTime.Now - _lastBlockLog > TimeSpan.FromMinutes(5))
                    {
                        _lastBlockLog = DateTime.Now;
                        LogSched($"waiting: a flow has been running since {_flowLockedAt:HH:mm:ss} " +
                                 $"({held.TotalMinutes:F0} min). The next due app starts when it finishes.");
                    }
                    return;
                }
            }

            _schedulerBusy = true;
            try
            {
            var now = DateTime.Now;

            var appsToDownload = _allApps
                .Where(a => a.AutoDownloadSource.Equals("Yes", StringComparison.OrdinalIgnoreCase)
                         && !string.IsNullOrWhiteSpace(a.DownloadFrequency))
                .ToList();

            // Repairs entries whose schedule fields were displayed but never stored.
            //
            // An "Every 2 weeks" app with no anchor yet (added before this field existed, or added
            // through the Add App dialog) gets one now: the next occurrence of its scheduled day.
            // Without an anchor the schedule is undefined, so it would simply never fire.
            // Write back the defaults the panel is already DISPLAYING, so the stored app stops
            // disagreeing with the screen. The schedule combos set SelectedIndex before wiring their
            // SelectionChanged handler, so a default the user never touched is shown but never saved -
            // which is why an app could have DownloadScheduleDays = "" and never be due.
            //
            // A leftover full date in DownloadScheduleDate (from the interim build) is not a valid
            // day-of-month, so it is reset to "01" here as well.
            bool seeded = false;
            foreach (var a in appsToDownload)
            {
                // A blank time is fatal for every frequency except Hourly: IsScheduledDownloadDue
                // gives up on an unparseable time before it looks at the frequency at all, so the
                // app just never fires and nothing on screen says why. Both the panel and
                // ScheduleHourMinute already read blank as 06:00, so the row is sitting there
                // reading "At 06 Hours 00 Minutes" - write down what it is showing.
                //
                // This repairs entries saved before the Add App dialog was fixed to store the time
                // for "Every 2 weeks"; it is written generally because a hand-edited JSON, or any
                // later frequency added to the dialog and forgotten, lands in the same hole.
                //
                // Hourly is no longer excluded, because it now carries a time as well - the phase of
                // its interval. It seeds to MIDNIGHT, not 06:00: the old due check counted the
                // interval with now.Hour % interval, which is phased from 00:00, so midnight is the
                // schedule every existing hourly app already has. Seeding it to 06:00 like the rest
                // would silently shift every one of them by six hours on first run after this build.
                bool isHourly = a.DownloadFrequency.Trim().Equals("Hourly", StringComparison.OrdinalIgnoreCase);
                if (!TryParseScheduleTime(a.DownloadScheduleTime, out _, out _))
                { a.DownloadScheduleTime = isHourly ? "00:00" : "06:00"; seeded = true; }

                // The interval itself has the same never-saved-default hole as DownloadScheduleDays
                // had: both editors set the combo to "02" before wiring SelectionChanged, so an app
                // the user never touched the row on DISPLAYS "Every 02 Hours" while storing "", and
                // HourlyIntervalOf then reads blank as 1. The screen said two hours, the scheduler
                // ran one. Write down what the row is showing.
                if (isHourly
                    && !(int.TryParse((a.DownloadScheduleHour ?? "").Trim(),
                             System.Globalization.NumberStyles.Integer, null, out int seedIv) && seedIv >= 1))
                { a.DownloadScheduleHour = "02"; seeded = true; }

                if (!IsEvery2Weeks(a.DownloadFrequency)) continue;

                if (string.IsNullOrWhiteSpace(a.DownloadScheduleDays))
                { a.DownloadScheduleDays = ScheduledDayOf(a).ToString(); seeded = true; }

                bool validDom = int.TryParse((a.DownloadScheduleDate ?? "").Trim(),
                                    System.Globalization.NumberStyles.Integer, null, out int dom0)
                                && dom0 >= 1 && dom0 <= 31;
                if (!validDom) { a.DownloadScheduleDate = "01"; seeded = true; }

                if (string.IsNullOrWhiteSpace(a.DownloadScheduleMonth))
                { a.DownloadScheduleMonth = "January"; seeded = true; }
            }

            // Hour 24 is now a legitimate value meaning "end of the scheduled day" (see
            // TryParseScheduleTime), so it is no longer rewritten to 00 - that would have flipped the
            // user's intent from the END of the day to the START of it. Non-zero minutes on hour 24
            // are simply clamped at parse time; the UI locks them to 00 anyway.

            if (seeded) SaveApps();

            // ── Diagnostic: log what the scheduler is checking ──────────
            System.Diagnostics.Debug.WriteLine($"[Scheduler] {now:HH:mm:ss} — checking {appsToDownload.Count} app(s)");
            foreach (var app in appsToDownload)
            {
                bool due = IsScheduledDownloadDue(app, now);
                System.Diagnostics.Debug.WriteLine(
                    $"[Scheduler] {app.SourceAppName}: freq={app.DownloadFrequency} " +
                    $"date={app.DownloadScheduleDate} time={app.DownloadScheduleTime} " +
                    $"month={app.DownloadScheduleMonth} → due={due}");
                if (!due) continue;

                // LIVE ONLY. The scheduled moment must have arrived while SwiftPack was running.
                //
                // Without this the 10-second timer still catches up: open the app at 19:00 on a Monday
                // whose slot was 18:35, and the very next tick sees "Monday, past 18:35" and downloads
                // - the startup catch-up we just removed, arriving 10 seconds later through another
                // door. A slot that fell before this session belongs to ReportMissedSchedulesAsync,
                // which tells the user rather than acting on its own.
                DateTime? slot = PreviousScheduledOccurrence(app, now);
                if (slot != null && slot.Value < _sessionStart)
                {
                    // ONCE per app+slot, not once per tick. Nothing here ever converges: the app
                    // stays due for the rest of the scheduled day (IsScheduledDownloadDue is just
                    // currentTime >= scheduledTime), the slot never stops predating this session,
                    // and this branch records no state before continuing. Unkeyed, that is the same
                    // sentence every 10 seconds until the app closes - roughly 34,000 lines a day,
                    // which buries every other scheduler line in the file.
                    string missedKey = $"{app.SourceAppName}|{slot:yyyy-MM-dd HH:mm}";
                    if (_loggedMissedSlots.Add(missedKey))
                        LogSched($"{app.SourceAppName}: slot {slot:dd-MM-yyyy HH:mm} predates this session " +
                                 $"({_sessionStart:dd-MM-yyyy HH:mm}) - missed while closed, reported not downloaded");
                    continue;
                }

                // One run per scheduled occurrence. GetSchedulePeriodKey resolves both moments to the
                // slot they belong to, so two ticks inside one slot match and a changed schedule
                // does not.
                string periodKey = GetSchedulePeriodKey(app, now, slot);
                if (_lastScheduledDownload.TryGetValue(app.SourceAppName, out DateTime lastRun))
                {
                    string lastPeriodKey = GetSchedulePeriodKey(app, lastRun);
                    if (lastPeriodKey == periodKey)
                    {
                        if (_loggedPeriodSkips.Add($"{app.SourceAppName}|{periodKey}"))
                            LogSched($"{app.SourceAppName}: already checked in this period ({periodKey}) " +
                                     $"- no further check until the next one");
                        continue;
                    }
                }

                // A failed attempt earlier in this slot parked the app with a backoff; while the
                // backoff runs the app just waits, silently - the failure itself was logged the
                // moment it happened, so these ticks have nothing new to say.
                if (_scheduleRetry.TryGetValue(app.SourceAppName, out var retryState)
                    && retryState.SlotKey == periodKey && now < retryState.NotBefore)
                    continue;

                // NOTE the slot is deliberately NOT stamped here. It used to be - written before
                // the fetch, so a check that threw, a manifest with no usable link, or a download
                // that died mid-transfer all silently spent the whole period on one transient
                // failure. The slot is now spent only by a DEFINITIVE verdict: a successful check
                // that found nothing newer, or a download whose version write confirmed. Every
                // failure shape goes through RegisterScheduleFailure instead, which keeps the app
                // in the queue with a bounded backoff.

                // Fetch download info then trigger download
                try
                {
                    AppDownloadInfo info;

                    try
                    {
                        info = app.ApiType switch
                        {
                            "winget"       => await FetchWingetAsync(app),
                            "github"       => await FetchGitHubAsync(app),
                            "Vendor API"   => await FetchVendorApiAsync(app),
                            _              => FallbackInfo(app),
                        };
                    }
                    catch (Exception fetchEx)
                    {
                        // The UI path already serves the last-known-good GitHub entry when a live
                        // request fails. The scheduler used to bypass that fallback, so the UI could
                        // show e.g. 2.5.8 while the scheduled run failed with 401/403 and never
                        // reached the version gate. Keep the scheduler consistent with the UI.
                        if (app.ApiType.Equals("github", StringComparison.OrdinalIgnoreCase))
                        {
                            LoadInfoCache();
                            if (_infoCache.TryGetValue(InfoKey(app), out var cached)
                                && cached.Info.Links.Count > 0
                                && !string.IsNullOrWhiteSpace(cached.Info.Version))
                            {
                                info = cached.Info;
                                LogSched($"{app.SourceAppName}: GitHub live check failed ({fetchEx.GetType().Name}: {fetchEx.Message}); " +
                                         $"using last-known-good version {info.Version} from cache");
                            }
                            else
                            {
                                throw;
                            }
                        }
                        else
                        {
                            throw;
                        }
                    }

                    // Select link based on DownloadPreference (EXE/MSI × x64/x86/ARM64)
                    string pref   = (app.DownloadPreference ?? "EXE_x64").ToUpperInvariant();
                    string prefType = pref.StartsWith("MSI") ? "MSI" : "EXE";
                    string prefArch = pref.EndsWith("ARM64") ? "ARM64"
                                    : pref.EndsWith("X86")   ? "x86" : "x64";

                    var link = info.Links.FirstOrDefault(l =>
                                   l.Type.Equals(prefType, StringComparison.OrdinalIgnoreCase) &&
                                   l.Arch.Equals(prefArch, StringComparison.OrdinalIgnoreCase))
                            ?? info.Links.FirstOrDefault(l =>
                                   l.Type.Equals(prefType, StringComparison.OrdinalIgnoreCase))
                            ?? info.Links.FirstOrDefault();

                    // ── VERSION GATE ────────────────────────────────────────────────────────
                    // The schedule says when to CHECK, not when to download. SourceAppVersion holds
                    // the version last downloaded (DownloadFileAsync writes it back on success), so
                    // only fetch when the vendor genuinely has something newer.
                    //
                    // This is what makes a backlog harmless. Without it, a week of missed runs meant
                    // a week's worth of apps each re-downloading a file we already had - and then each
                    // running its full 5-10 minute package/install/publish chain for nothing.
                    // With it, that backlog is N cheap version checks and a download only for the one
                    // or two apps that actually released.
                    if (!IsRemoteNewer(info.Version, app.SourceAppVersion))
                    {
                        // Definitive verdict: the check succeeded and there is nothing to do,
                        // which is exactly what spending the slot means.
                        _lastScheduledDownload[app.SourceAppName] = now;
                        ClearScheduleRetry(app.SourceAppName);
                        LogSched($"{app.SourceAppName}: DUE, but remote={info.Version} is not newer than " +
                                 $"local={app.SourceAppVersion} - nothing to download");
                        continue;
                    }

                    if (link != null && !string.IsNullOrWhiteSpace(link.Url))
                    {
                        Dispatcher.Invoke(() =>
                        {
                            _selectedApp               = app;
                            _lastSelectedVendor        = app.SourceAppVendor;
                            _lastSelectedAppName       = app.SourceAppName;
                            _lastTriggeredDownloadType = link.Type;

                            // Bring the UI to the app that is about to download, so the user can see
                            // WHICH app is running rather than staring at whichever one happened to be
                            // selected on load (the first in the list). _selectedVendor has to move
                            // too - SelectApp assumes the vendor column is already on the right vendor,
                            // because normally the user got there by clicking into it.
                            //
                            // Guarded: the scheduler also runs while this page is not the visible tab,
                            // and RenderCards touches controls that may not be realised yet.
                            try
                            {
                                if (PnlVendors != null && PnlCards != null)
                                    SelectAppAnyVendor(app);
                            }
                            catch (Exception uiEx)
                            {
                                System.Diagnostics.Debug.WriteLine($"[Scheduler] UI select skipped: {uiEx.Message}");
                            }

                            // Lock the sub-tab bar and both columns for the whole scheduled flow, the
                            // same way a manual download does. Before this, a scheduled run (Auto
                            // Download Source = Yes) left the Package / Execute / Intunewin / Publish /
                            // Document tabs clickable, unlike a manual one (Auto Download Source = No).
                            // LockDownloadAndPackageColumns sets AutoFlowStatus.FlowRunning, which is
                            // also the scheduler's own serialisation lock (the guard at the top of this
                            // method bails while it is held). It is released by the shared download
                            // completion logic at the true end of the chain, or right after the download
                            // when nothing downstream is scheduled to run.
                            _autoFlowChainPending = false; // re-armed by DownloadFileAsync if a chain runs
                            LockDownloadAndPackageColumns();

                            System.Diagnostics.Debug.WriteLine($"[Scheduler] Set _selectedApp={app.SourceAppName} CreatePackage={app.CreatePackage}");
                        });
                        LogSched($"{app.SourceAppName}: DUE - remote={info.Version} > local={app.SourceAppVersion} - DOWNLOADING");
                        await DownloadFileAsync(link.Url, link.Label, app.SourceAppName, info.Version, app.SourceAppVendor, scheduled: true,
                            existingVersion: app.SourceAppVersion ?? "", scheduleName: app.DownloadFrequency ?? "");

                        // The download's own success signal: DownloadFileAsync writes info.Version
                        // into SourceAppVersion only when the file truly landed (the scheduler holds
                        // the same object - the sameRefAsList diagnostics exist to prove it). A
                        // download that failed or was torn down leaves the version untouched, and
                        // then the slot is NOT spent: the app stays in the queue and retries after
                        // the backoff. If the comparison ever misjudges a success, the retry's own
                        // version check lands on "not newer" and spends the slot there - the
                        // mistake self-corrects at the cost of one cheap fetch.
                        bool downloadConfirmed = string.Equals(
                            (app.SourceAppVersion ?? "").Trim(), (info.Version ?? "").Trim(),
                            StringComparison.OrdinalIgnoreCase);
                        if (downloadConfirmed)
                        {
                            _lastScheduledDownload[app.SourceAppName] = now;
                            ClearScheduleRetry(app.SourceAppName);
                        }
                        else
                        {
                            RegisterScheduleFailure(app, periodKey, DateTime.Now, "download did not complete");
                        }

                        // ONE app per pass. Its chain (install source / create package / intunewin /
                        // publish / mail) may still be running well after the download itself returns;
                        // AutoFlowStatus.FlowRunning stays set until the whole thing finishes, and the
                        // guard at the top of this method bails while it is. The 10-second timer then
                        // picks up the next due app once the flow has completely ended.
                        return;
                    }

                    // The fetch succeeded, the version really is newer, and then no usable link came
                    // back - a manifest with no installer of the preferred type, a GitHub release
                    // with no matching asset. Treated as a failure, not a verdict: it might be a
                    // transient parse or CDN blip, so the app stays in the queue for the bounded
                    // retries, and if all of them see the same empty manifest the give-up line
                    // spends the slot in the open.
                    LogSched($"{app.SourceAppName}: DUE - remote={info.Version} > local={app.SourceAppVersion}, " +
                             $"but no usable download link came back (wanted {prefType} {prefArch}, " +
                             $"{info.Links.Count} link(s) offered: " +
                             $"{(info.Links.Count == 0 ? "none" : string.Join(", ", info.Links.Select(l => $"{l.Type} {l.Arch}")))})");
                    RegisterScheduleFailure(app, periodKey, DateTime.Now, "no usable download link");
                }
                catch (Exception schedEx)
                {
                    // This is where a GitHub 403 used to swallow the run: the fetch threw, the app was
                    // skipped, and nothing anywhere said so.
                    LogSched($"{app.SourceAppName}: ERROR - {schedEx.GetType().Name}: {schedEx.Message}");
                    RegisterScheduleFailure(app, periodKey, DateTime.Now, schedEx.GetType().Name);
                }
            }

            // ── Repaint once, after the whole batch has settled ─────────────────────────────────
            // Each download already repaints on its own completion, and that is enough when one app
            // runs. In a batch it is not: the next app's SelectAppAnyVendor repaints over it ten
            // seconds later, and the previous app's fire-and-forget FetchAndShowAsync can finish
            // after THAT, so what the user is left looking at is whichever of the two happened to
            // arrive last - stale versions and "New" badges on apps that just downloaded.
            //
            // Reaching this line means the foreach found nothing left to start. The AutoFlowStatus
            // .FlowRunning guard at the top of this method returns long before here while any chain
            // is still going, so a repaint here cannot land in the middle of one.
            //
            // This is the same refresh that leaving the tab and coming back performs, which is the
            // workaround people found for themselves.
            if (_repaintPending)
            {
                _repaintPending = false;
                Dispatcher.Invoke(() =>
                {
                    try
                    {
                        // ONE try per call, not one around all four. A single guard meant the very
                        // first render throwing took the cards, the Updates count and the app panel
                        // down with it, left the log naming only that one failure, and left
                        // _repaintPending already cleared above so no later pass retried any of it.
                        try { RenderVendors(); }          // vendor column "New" badges
                        catch (Exception exV) { LogSched($"batch repaint: RenderVendors FAILED - {exV.GetType().Name}: {exV.Message}"); }

                        try { RenderCards(); }            // app card "New" badges
                        catch (Exception exC) { LogSched($"batch repaint: RenderCards FAILED - {exC.GetType().Name}: {exC.Message}"); }

                        try { RefreshUpdatesBadge(); }    // toolbar count, which nothing on this path refreshed
                        catch (Exception exU) { LogSched($"batch repaint: RefreshUpdatesBadge FAILED - {exU.GetType().Name}: {exU.Message}"); }

                        try { if (_selectedApp != null) SelectApp(_selectedApp); }   // rebuilds the Package Information form
                        catch (Exception exS) { LogSched($"batch repaint: SelectApp FAILED - {exS.GetType().Name}: {exS.Message}"); }

                        LogSched("batch finished - vendors, cards, Updates count and app panel repainted");
                    }
                    catch (Exception repaintEx)
                    {
                        // The per-app renders sit behind catch blocks that only reach Debug.WriteLine,
                        // so a render throwing during a scheduled run leaves no trace anywhere. If the
                        // badges are still stale after this build, this line is where it will say so.
                        LogSched($"batch repaint FAILED - {repaintEx.GetType().Name}: {repaintEx.Message}");
                    }
                });
            }
            }
            finally { _schedulerBusy = false; }
        }

        /// <summary>
        /// True when <paramref name="remote"/> is strictly NEWER than <paramref name="local"/>.
        ///
        /// Compared numerically, part by part - never as strings. "2.61.1" vs "2.9" must not be
        /// decided alphabetically (it would pick 2.9), and "260.4.2926" has four parts where "1.0"
        /// has two, so the shorter one is padded with zeros.
        ///
        /// Deliberately STRICTLY greater, not "different":
        ///   remote &gt; local  -> download
        ///   remote == local -> nothing new, skip
        ///   remote &lt; local  -> the vendor rolled back; the higher version is already downloaded, skip
        /// (The "New" badges on this page use this same comparison, so a badge is a promise the
        /// version gate will honour - they used plain inequality once, and a local version that
        /// was AHEAD of the vendor showed "New" while the scheduler correctly refused, which cost
        /// an afternoon of chasing a scheduler bug that did not exist.)
        ///
        /// A version that cannot be parsed at all (a date string, a build tag) falls back to
        /// "different means newer" - erring towards downloading rather than never updating again.
        /// </summary>
        internal static bool IsRemoteNewer(string? remote, string? local)
        {
            string r = (remote ?? "").Trim();
            string l = (local  ?? "").Trim();
            if (string.IsNullOrEmpty(r)) return false;   // nothing to compare against - do not download
            if (string.IsNullOrEmpty(l)) return true;    // never downloaded

            static int[]? Parse(string v)
            {
                var nums = new List<int>();
                foreach (string part in v.Split('.', '-', '_', '+', ' '))
                {
                    // Leading digits of each part: "2026b" -> 2026. Stop at the first part that does
                    // not start with a digit ("1.0-beta" -> [1, 0]).
                    int i = 0;
                    while (i < part.Length && char.IsDigit(part[i])) i++;
                    if (i == 0) break;
                    if (!int.TryParse(part.Substring(0, i), out int n)) break;
                    nums.Add(n);
                }
                return nums.Count > 0 ? nums.ToArray() : null;
            }

            int[]? rv = Parse(r), lv = Parse(l);
            if (rv == null || lv == null)
                return !r.Equals(l, StringComparison.OrdinalIgnoreCase);   // unparseable: different = newer

            for (int i = 0; i < Math.Max(rv.Length, lv.Length); i++)
            {
                int a = i < rv.Length ? rv[i] : 0;
                int b = i < lv.Length ? lv[i] : 0;
                if (a != b) return a > b;
            }
            return false;   // identical
        }

        // ══════════════════════════════════════════════════════════════════════
        //  EVERY 2 WEEKS - anchored fortnight
        // ══════════════════════════════════════════════════════════════════════
        /// <summary>Frequency label shown in the UI. Older app JSON stores "Fortnightly".</summary>
        internal const string FREQ_EVERY_2_WEEKS = "Every 2 weeks";

        /// <summary>
        /// True for the 2-weekly frequency under either name. The label changed from "Fortnightly"
        /// to "Every 2 weeks"; both are accepted so existing app JSON keeps working with no migration.
        /// </summary>
        internal static bool IsEvery2Weeks(string? freq)
        {
            string f = (freq ?? "").Trim();
            return f.Equals(FREQ_EVERY_2_WEEKS, StringComparison.OrdinalIgnoreCase)
                || f.Equals("Fortnightly",      StringComparison.OrdinalIgnoreCase);
        }

        /// <summary>
        /// Which schedule fields a frequency actually uses - exactly the rows the two schedule
        /// editors show for it. Stated once, here, because the same list living in three places is
        /// how "Every 2 weeks" ended up displaying rows the Add App dialog then refused to save.
        ///
        /// Month covers the year as well: the two are one start date and never travel apart.
        ///
        /// Everything false means the frequency is not one of ours - blank, "None", or a literal
        /// dd-MM-yyyy date written by hand - and callers leave such an entry alone rather than
        /// guessing at it.
        /// </summary>
        internal static (bool Hour, bool Occurrence, bool Days, bool Date, bool Time, bool Month)
            ScheduleFieldsFor(string? freq)
        {
            string f = (freq ?? "").Trim();
            bool fortnight = IsEvery2Weeks(f);
            bool Is(string n) => f.Equals(n, StringComparison.OrdinalIgnoreCase);

            bool hour = Is("Hourly");
            bool occ  = Is("Every");
            bool known = hour || occ || fortnight
                      || Is("Daily") || Is("Weekly") || Is("Monthly")
                      || Is("Quarterly") || Is("HalfYearly") || Is("Yearly");
            if (!known) return (false, false, false, false, false, false);

            // Year and month are the start of the series, and EVERY frequency has one - "hourly,
            // starting from February 2026" is as meaningful as the yearly version. They were once
            // restricted to the frequencies that repeat on a month boundary, which left no way to
            // say when an hourly or daily schedule begins.
            bool month = true;

            // The day of the month is asked for everywhere EXCEPT "Every", where the run days come
            // from the occurrence and the weekday - "the Fourth Wednesday" - and a day of the month
            // decides nothing about them. Its only effect there was on the start: set it past that
            // month's Nth weekday and the first month vanished with nothing on screen saying why.
            // "Fourth Wednesday, starting from 29 July" first runs on 26 August. So the start for
            // "Every" is the month, and the series begins with that month's occurrence.
            bool date = !occ;

            // The weekday shows for every frequency too. It reads differently depending on which -
            // Weekly runs ON it, Every 2 weeks counts fortnights FROM it, Every pairs it with the
            // occurrence, and elsewhere it is simply the day the start date falls on - but it is
            // always filled in from that date, so it is always worth showing.
            bool days = known;

            // Every frequency has a clock time, Hourly included. For Hourly it is not the moment a
            // run happens but the PHASE of the interval: "every 5 hours starting from 09:00" means
            // 09:00, 14:00, 19:00, then 00:00 the next day. Without it the interval could only be
            // counted from midnight (now.Hour % interval), so the start date the editors were
            // already showing decided nothing at all about when the series actually fired.
            bool time = true;

            return (hour, occ, days, date, time, month);
        }

        // ── Start of the series: year + month + day of month ─────────────────────────────
        //
        // DownloadScheduleYear is the newest of the three. Together they are a real date - the first
        // run of the series - and nothing fires before it.
        //
        // It can only be blank in an app saved before the field existed; both schedule editors always
        // write a year. A blank one keeps the old behaviour exactly: the month is read as a position
        // in the calendar year and the series repeats every year.

        /// <summary>Stored start year, or null in an app saved before the field existed.</summary>
        private static int? ScheduleYearOf(DownloadSourceEntry app)
        {
            string y = (app.DownloadScheduleYear ?? "").Trim();
            if (int.TryParse(y, System.Globalization.NumberStyles.Integer,
                    System.Globalization.CultureInfo.InvariantCulture, out int n)
                && n >= 1900 && n <= 9999)
                return n;
            return null;
        }

        /// <summary>Stored start month as 1-12. Blank means January, which is what the combo shows.</summary>
        private static int ScheduleMonthOf(DownloadSourceEntry app)
        {
            if (!string.IsNullOrWhiteSpace(app.DownloadScheduleMonth) &&
                DateTime.TryParseExact(app.DownloadScheduleMonth.Trim(), "MMMM",
                    System.Globalization.CultureInfo.InvariantCulture,
                    System.Globalization.DateTimeStyles.None, out DateTime pm))
                return pm.Month;
            return 1;
        }

        /// <summary>Stored day of month as 1-31. Blank means the 1st.</summary>
        private static int ScheduleDomOf(DownloadSourceEntry app)
        {
            if (!string.IsNullOrWhiteSpace(app.DownloadScheduleDate) &&
                int.TryParse(app.DownloadScheduleDate.Trim(),
                    System.Globalization.NumberStyles.Integer, null, out int pd) && pd >= 1 && pd <= 31)
                return pd;
            return 1;
        }

        /// <summary>
        /// How many days that month really has. February is 28 or 29 depending on the year, and
        /// April, June, September and November are 30 - which is what the day combo has to offer,
        /// rather than a flat 1-31 that lets 31 February be picked.
        ///
        /// With no year to go on the count comes from a LEAP year, so 29 February stays offerable.
        /// What it does in a common year is decided by ScheduleDayIn below, not by hiding the option.
        /// </summary>
        internal static int DaysInScheduleMonth(int? year, int month)
        {
            int mo = month >= 1 && month <= 12 ? month : 1;
            return DateTime.DaysInMonth(year ?? 2024, mo);   // 2024: a leap year
        }

        /// <summary>
        /// The day a "day of the month" schedule actually falls on in a given month, pulled back to
        /// the last day when the month is too short. The 31st runs on 30 April and on 28 February;
        /// 29 February runs on the 28th in a common year.
        ///
        /// Without this a date-based schedule silently skips whole months: the old test was a plain
        /// now.Day == scheduledDate, so "the 31st" fired in seven months of the year and 29 February
        /// fired once every four years.
        /// </summary>
        private static int ScheduleDayIn(int dom, int year, int month)
            => Math.Min(dom < 1 ? 1 : dom, DateTime.DaysInMonth(year, month));

        /// <summary>
        /// The first moment of the series, or null when no year is stored. Time of day included, so a
        /// start on the same day is compared at the scheduled hour rather than at midnight.
        /// </summary>
        private static DateTime? ScheduleStart(DownloadSourceEntry app)
        {
            int? y = ScheduleYearOf(app);
            if (y == null) return null;
            int mo = ScheduleMonthOf(app);
            int d  = ScheduleDayIn(ScheduleDomOf(app), y.Value, mo);
            var (h, m) = ScheduleHourMinute(app);
            return new DateTime(y.Value, mo, d, h, m, 0);
        }

        /// <summary>
        /// Start of the 2-weekly series, built from the SAME fields Quarterly uses:
        ///   DownloadScheduleMonth ("July") + DownloadScheduleDate ("08") + DownloadScheduleDays
        ///   ("Monday") + DownloadScheduleYear ("2026", optional)
        /// read as "every 2 weeks on Monday, starting from 8 July 2026". No new format.
        ///
        /// With a year set the anchor is that exact date - the cadence is then fixed forever and the
        /// re-phasing described below cannot happen.
        ///
        /// Without a year (an app saved before the field existed) there is nothing to work from, so
        /// it is resolved as the MOST RECENT (month, day) on or before <paramref name="now"/> - use
        /// last year's if this year's has not arrived yet. Resolving it as "this year" instead would
        /// leave the schedule dead from January until the start date came round again.
        ///
        /// Either way it is snapped FORWARD to the scheduled weekday, because "starting from 8 July"
        /// means the first Monday on or after the 8th.
        ///
        /// KNOWN AND ACCEPTED, and only for those year-less apps: such an anchor re-phases once a
        /// year. 8 July is a Wednesday in 2026 and a Thursday in 2027, so the first Monday after it
        /// moves, and at the anniversary one gap is 7 or 21 days instead of 14. That is inherent to
        /// an anchor with no year (26 x 14 = 364 days, one short of a year).
        /// </summary>
        private static DateTime? FortnightAnchor(DownloadSourceEntry app, DateTime now, DayOfWeek day)
        {
            int month = ScheduleMonthOf(app);
            int dom   = ScheduleDomOf(app);

            DateTime SeedFor(int year) => new DateTime(year, month, ScheduleDayIn(dom, year, month));

            int? startYear = ScheduleYearOf(app);
            DateTime seed;
            if (startYear != null)
            {
                // Pinned. A start in the future simply means the series has not begun: the weeks
                // count comes out negative and the caller's "weeks >= 0" test holds it back.
                seed = SeedFor(startYear.Value);
            }
            else
            {
                seed = SeedFor(now.Year);
                if (seed.Date > now.Date) seed = SeedFor(now.Year - 1);   // this year's start has not arrived
            }

            return NextWeekdayOnOrAfter(seed, day);
        }

        /// <summary>Whole weeks from the anchor to <paramref name="now"/>; negative before the anchor.</summary>
        private static int WeeksSinceAnchor(DateTime anchor, DateTime now)
            => (int)Math.Floor((now.Date - anchor.Date).TotalDays / 7.0);

        /// <summary>The first occurrence of <paramref name="day"/> on or after <paramref name="from"/>.</summary>
        private static DateTime NextWeekdayOnOrAfter(DateTime from, DayOfWeek day)
            => from.Date.AddDays(((int)day - (int)from.Date.DayOfWeek + 7) % 7);

        /// <summary>Scheduled weekday for an app, defaulting to Monday.</summary>
        private static DayOfWeek ScheduledDayOf(DownloadSourceEntry app)
            => Enum.TryParse<DayOfWeek>(app.DownloadScheduleDays, true, out DayOfWeek d) ? d : DayOfWeek.Monday;

        /// <summary>Interval in hours for an Hourly schedule. Blank or unparseable reads as 1.</summary>
        private static int HourlyIntervalOf(DownloadSourceEntry app)
        {
            if (!string.IsNullOrWhiteSpace(app.DownloadScheduleHour) &&
                int.TryParse(app.DownloadScheduleHour.Trim(),
                    System.Globalization.NumberStyles.Integer, null, out int ih) && ih >= 1)
                return ih;
            return 1;
        }

        /// <summary>
        /// The hourly slot <paramref name="now"/> falls inside, or null before the series starts.
        ///
        /// CONTINUOUS from the anchor, not reset each day: "every 5 hours from 09:00" runs 09:00,
        /// 14:00, 19:00, 00:00, 05:00 and on, so the spacing is never broken by a midnight that does
        /// not divide the interval. Intervals that do divide 24 (1, 2, 3, 4, 6, 8, 12) land on the
        /// same clock times every day regardless, which is every interval the combos offer except
        /// 5, 7, 9, 10 and 11.
        ///
        /// Returning the slot rather than a bool is what lets the due check, the period key and the
        /// occurrence walk all agree on which run a moment belongs to. The old due check answered
        /// "now.Hour % interval == 0 && now.Minute &lt; 2", a two-minute window phased from midnight,
        /// and there was no slot to key on at all.
        /// </summary>
        private static DateTime? HourlySlotFor(DownloadSourceEntry app, DateTime now)
        {
            DateTime anchor;
            DateTime? start = ScheduleStart(app);
            if (start != null)
            {
                if (now < start.Value) return null;   // the series has not begun
                anchor = start.Value;
            }
            else
            {
                // Saved before DownloadScheduleYear existed, so there is no start date to phase from.
                // Fall back to the scheduled time on the current day, stepped back one day when that
                // moment has not arrived yet. With the seeded 00:00 that is midnight, which is the
                // phase such an app has always run on.
                var (fh, fm) = ScheduleHourMinute(app);
                anchor = now.Date.AddHours(fh).AddMinutes(fm);
                if (anchor > now) anchor = anchor.AddDays(-1);
            }

            long elapsed = (long)Math.Floor((now - anchor).TotalHours);
            if (elapsed < 0) return null;
            int interval = HourlyIntervalOf(app);
            return anchor.AddHours(elapsed - (elapsed % interval));
        }

        /// <summary>
        /// Returns a string key representing the current download period for the app.
        /// Used to detect whether we've already downloaded in this period.
        /// </summary>
        /// <summary>
        /// Which scheduled RUN a moment belongs to. The "already ran this period" guard compares the
        /// key for now against the key for the last run, and skips when they match.
        ///
        /// The key is the scheduled occurrence itself, not a calendar bucket. Buckets were the
        /// original approach and every one of them was wrong in the same way, because a bucket edge
        /// has nothing to do with the schedule that has to fit inside it:
        ///
        ///   weekly     yyyy-W{DayOfYear/7}   ran Friday, moved the schedule to Saturday, blocked -
        ///                                    24 and 25 July are both W29 (the window is Wed to Tue)
        ///   daily      yyyy-MM-dd            ran at 06:00, moved it to 22:00, blocked until tomorrow
        ///   monthly    yyyy-MM               ran on the 5th, moved it to the 20th, blocked for a month
        ///   yearly     yyyy                  ran once, changed anything, blocked for a YEAR
        ///
        /// Keying on the occurrence fixes all of them at once. Two ticks inside one slot still
        /// resolve to the same occurrence, so the ten-second re-entry storm the guard exists to stop
        /// is still stopped. Change the time from 15:45 to 15:50 and the last run's occurrence
        /// resolves against the NEW schedule - the most recent 15:50 slot on or before 15:45, which
        /// is last week - so the keys differ and today's 15:50 runs. No restart, which is what it
        /// took before.
        ///
        /// Note this is only ever reached for an app that is already DUE, and the caller has just
        /// computed the occurrence for "now" - hence knownSlot, which makes that half free.
        /// </summary>
        private static string GetSchedulePeriodKey(DownloadSourceEntry app, DateTime dt, DateTime? knownSlot = null)
        {
            // Hourly resolves through its own slot arithmetic rather than the occurrence walk, since
            // it repeats inside the day.
            //
            // This was the clock hour, yyyy-MM-dd-HH, which only held while the due window was two
            // minutes wide at the top of an hour. Now that an app stays due for its whole slot, a
            // clock-hour key would turn over partway through any interval above 1 and let the same
            // slot run a second time: on "every 3 hours from 00:00", the 09:00 slot would run at
            // 09:xx under key ...-09 and again at 10:00 under key ...-10.
            if (app.DownloadFrequency.Trim().Equals("Hourly", StringComparison.OrdinalIgnoreCase))
                return HourlySlotFor(app, dt)?.ToString("yyyy-MM-dd HH:mm") ?? "no-occurrence";

            DateTime? slot = knownSlot ?? PreviousScheduledOccurrence(app, dt);

            // No occurrence on or before this moment - a start date still in the future, or a
            // timestamp older than the schedule itself. Distinct from every real key, so the run is
            // allowed rather than silently held back.
            return slot?.ToString("yyyy-MM-dd HH:mm") ?? "no-occurrence";
        }

        /// <summary>
        /// Returns true if the app's scheduled download is due.
        /// Handles both HH:MM and HH-MM time formats.
        /// Also returns true if the schedule was missed today/this period
        /// (e.g. app was closed at the scheduled time).
        /// DownloadFrequency: Hourly / Daily / Weekly / Biweekly / Monthly / DD-MM-YYYY
        /// DownloadScheduleTime: HH:MM or HH-MM (24h)
        /// </summary>
        // ══════════════════════════════════════════════════════════════════════════════════
        //  MISSED SCHEDULES
        // ══════════════════════════════════════════════════════════════════════════════════
        // When the app is closed (or the machine is off) at an app's scheduled moment, that run is
        // gone. It is NOT silently downloaded the next time SwiftPack opens.
        //
        // Auto-downloading on startup was worse than it sounds: a machine off for a week would, the
        // instant someone opened the app, start firing off full 5-10 minute install / package /
        // intunewin / publish chains for every app it thought it had missed - unattended, unasked, and
        // right when the user was trying to do something else.
        //
        // Instead: report. On startup, list the apps whose scheduled moment passed while we were not
        // running AND for which a NEWER version actually exists. Everything else is left alone - a
        // missed run for an app with nothing new to fetch is a non-event, and there is no point
        // telling anyone about it.

        /// <summary>When this session started. A schedule that fell BEFORE this was missed.</summary>
        private static DateTime _sessionStart = DateTime.Now;

        /// <summary>True once the session has been stamped, and once the missed-schedule report has
        /// been shown. Both are per RUN of the app, not per page load - Loaded fires again on every
        /// return to the Download tab, and these are static because that builds a new page instance.</summary>
        private static bool _sessionStamped = false;
        private static bool _missedReported = false;

        /// <summary>True once this RUN has attempted the first-launch catalog seed. Static for the
        /// same reason as the two above: Loaded fires again on every return to the Download tab.
        /// Set even when the attempt FAILS, so an offline machine tries once per launch rather than
        /// once per tab switch; the next launch and Check now both retry.</summary>
        private static bool _catalogSeedAttempted = false;

        /// <summary>
        /// Parses DownloadScheduleTime. THE one place that reads it - the due check and the missed
        /// -schedule report both come through here, so they cannot disagree about what a time means.
        ///
        /// Hour 24 is accepted and means the END of the scheduled day. That is the whole point of
        /// offering it: "00:00 on Wednesday" is the START of Wednesday, "24:00 on Wednesday" is the
        /// end of it, and the two were impossible to tell apart with a 00-23 dial.
        ///
        /// 24:00 is CLAMPED TO 23:59, not rolled into the next day.
        ///
        /// Rolling would move the DAY as well - "Wednesday 24:00" would have to fire on Thursday at
        /// 00:00 - and then every frequency's day / date / month test would have to shift with it,
        /// across month ends, year ends, and the nth-weekday-of-month rule. That is a lot of places to
        /// get subtly wrong. Clamping keeps the run on the day the user picked and fires it in the
        /// last minute of that day, which is what "end of Wednesday" means in practice.
        ///
        /// Note what CANNOT be done here: leaving h = 24 and building a TimeSpan(24, 0, 0). now.TimeOfDay
        /// never exceeds 23:59:59, so `currentTime >= scheduledTime` would never be true and the
        /// schedule would silently never fire - which is exactly what the old 01..24 dial did.
        /// </summary>
        private static bool TryParseScheduleTime(string? raw, out int h, out int m)
        {
            h = 0; m = 0;
            var parts = (raw ?? "").Trim().Replace('-', ':').Split(':');
            if (parts.Length < 2) return false;
            if (!int.TryParse(parts[0], System.Globalization.NumberStyles.Integer, null, out h)) return false;
            if (!int.TryParse(parts[1], System.Globalization.NumberStyles.Integer, null, out m)) return false;

            if (h == 24) { h = 23; m = 59; return true; }   // end of the scheduled day
            return h >= 0 && h <= 23 && m >= 0 && m <= 59;
        }

        /// <summary>Scheduled time of day, defaulting to 06:00 when unset or malformed.</summary>
        private static (int H, int M) ScheduleHourMinute(DownloadSourceEntry app)
            => TryParseScheduleTime(app.DownloadScheduleTime, out int h, out int m) ? (h, m) : (6, 0);

        /// <summary>
        /// The most recent moment this app was scheduled to run, at or before <paramref name="now"/>.
        /// Null when it has no occurrence in the last ~14 months.
        ///
        /// Walks back a day at a time and asks IsScheduledDownloadDue - deliberately, rather than
        /// re-deriving each frequency. There are nine of them (hourly, daily, weekly, every 2 weeks,
        /// monthly, quarterly, half-yearly, yearly, nth-weekday, plus a literal date) and a second
        /// implementation would drift from the first.
        /// </summary>
        private static DateTime? PreviousScheduledOccurrence(DownloadSourceEntry app, DateTime now)
        {
            // Hourly steps in hours, so it cannot go through the day walk below.
            //
            // THIS WAS THE BUG THAT STOPPED HOURLY DOWNLOADING ENTIRELY. The walk builds one
            // candidate per day at ScheduleHourMinute, which for an app with no stored time was
            // 06:00, and the old due check said yes to 06:00 for any interval dividing 6 (1, 2, 3
            // and 6). So every such app resolved to today at 06:00, whatever its real schedule was.
            // The caller then compared that against _sessionStart, found it hours in the past, and
            // took the "missed while closed" branch - on every tick, for the entire session. Hourly
            // could only ever download if SwiftPack had been started before 06:00 that morning.
            if (app.DownloadFrequency.Trim().Equals("Hourly", StringComparison.OrdinalIgnoreCase))
                return HourlySlotFor(app, now);

            var (h, m) = ScheduleHourMinute(app);
            for (int back = 0; back <= 430; back++)
            {
                DateTime moment = now.Date.AddDays(-back).AddHours(h).AddMinutes(m);
                if (moment > now) continue;                       // today's slot has not arrived yet
                if (IsScheduledDownloadDue(app, moment)) return moment;
            }
            return null;
        }

        /// <summary>The next moment this app is scheduled to run, after <paramref name="now"/>.</summary>
        private static DateTime? NextScheduledOccurrence(DownloadSourceEntry app, DateTime now)
        {
            // Same reason as the backward walk. Without this the Updates window and the missed
            // -schedule report showed an hourly app's next run as tomorrow at 06:00.
            if (app.DownloadFrequency.Trim().Equals("Hourly", StringComparison.OrdinalIgnoreCase))
            {
                DateTime? slot = HourlySlotFor(app, now);
                if (slot != null) return slot.Value.AddHours(HourlyIntervalOf(app));

                // No slot yet means the start date is still ahead, and that start IS the first run.
                DateTime? notYet = ScheduleStart(app);
                return notYet != null && notYet.Value > now ? notYet : null;
            }

            var (h, m) = ScheduleHourMinute(app);
            for (int fwd = 0; fwd <= 430; fwd++)
            {
                DateTime moment = now.Date.AddDays(fwd).AddHours(h).AddMinutes(m);
                if (moment <= now) continue;
                if (IsScheduledDownloadDue(app, moment)) return moment;
            }
            return null;
        }

        /// <summary>
        /// Reports schedules that were missed because SwiftPack was not running - it does NOT download
        /// them.
        ///
        /// An app is reported only when BOTH are true:
        ///   1. its scheduled moment fell before this session started, and
        ///   2. the vendor genuinely has a newer version than the one already downloaded.
        ///
        /// (2) is what keeps it quiet. A missed run for an app with nothing new to fetch is a
        /// non-event - the schedule would have checked, found nothing, and done nothing - so there is
        /// no reason to tell anyone. In practice that means a machine off for a week produces a list
        /// of the one or two apps that actually released, not a wall of noise.
        ///
        /// Runs after the version sweep so the version data is already cached and this costs no extra
        /// network calls.
        /// </summary>
        /// <summary>
        /// Builds both lists. Shared by the startup report and the toolbar Updates button, so the two
        /// can never show different answers.
        ///
        ///   missed  - scheduled moment fell before this session AND a newer version exists
        ///   updates - EVERY app with a newer version (missed is a subset of it)
        /// </summary>
        private (List<MissedRow> Missed, List<MissedRow> Updates) BuildUpdateLists(DateTime now)
        {
            var missed  = new List<MissedRow>();
            var updates = new List<MissedRow>();

            foreach (var app in _allApps)
            {
                if (!_liveVersionCache.TryGetValue(app.SourceAppName, out string? remote)) continue;
                if (!IsRemoteNewer(remote, app.SourceAppVersion)) continue;

                bool auto = app.AutoDownloadSource.Equals("Yes", StringComparison.OrdinalIgnoreCase)
                         && !string.IsNullOrWhiteSpace(app.DownloadFrequency);
                DateTime? next = auto ? NextScheduledOccurrence(app, now) : null;
                string have = string.IsNullOrWhiteSpace(app.SourceAppVersion)
                            ? "(never downloaded)" : app.SourceAppVersion;

                string freq = auto ? (app.DownloadFrequency ?? "") : "manual";

                // Missed = its slot passed while we were not running. An app sitting here is
                // NOT repeated on the Updates tab: the two lists are disjoint, so an update is
                // either waiting on its schedule (missed) or offered for manual download
                // (updates), never both at once.
                if (auto)
                {
                    DateTime? was = PreviousScheduledOccurrence(app, now);
                    if (was != null && was.Value < _sessionStart)
                    {
                        missed.Add(new MissedRow
                        {
                            App              = app,
                            Vendor           = app.SourceAppVendor,
                            AppName          = app.SourceAppName,
                            ExistingVersion  = have,
                            NewVersion       = remote,
                            Schedule         = freq,   // Daily / Weekly / Every 2 weeks / Quarterly ...
                            ExistingSchedule = was.Value.ToString("ddd dd-MM-yyyy HH:mm"),
                            NewSchedule      = next.HasValue ? next.Value.ToString("ddd dd-MM-yyyy HH:mm") : "unknown",
                        });
                        continue;
                    }
                }

                updates.Add(new MissedRow
                {
                    App              = app,
                    Vendor           = app.SourceAppVendor,
                    AppName          = app.SourceAppName,
                    ExistingVersion  = have,
                    NewVersion       = remote,
                    Schedule         = freq,
                    ExistingSchedule = auto ? "Yes" : "No",   // "Auto Download" column on the Updates tab
                    NewSchedule      = next.HasValue ? next.Value.ToString("ddd dd-MM-yyyy HH:mm") : "-",
                });
            }

            return (missed.OrderBy(m => m.Vendor).ThenBy(m => m.AppName).ToList(),
                    updates.OrderBy(u => u.Vendor).ThenBy(u => u.AppName).ToList());
        }

        /// <summary>Puts the live count on the toolbar Updates button.</summary>
        private void RefreshUpdatesBadge()
        {
            try
            {
                // Missed and Updates are disjoint now, so the toolbar number - which means
                // "apps with a newer version", full stop - is the sum of both.
                var lists = BuildUpdateLists(DateTime.Now);
                int n = lists.Missed.Count + lists.Updates.Count;
                if (BtnUpdates != null)
                    BtnUpdates.Content = n > 0 ? $"⬆  Updates ({n})" : "⬆  Updates";
            }
            catch (Exception ex) { LogWinget($"[Updates] badge failed: {ex.Message}"); }
        }

        /// <summary>
        /// Repaints everything on the Download tab that a version change touches: vendor badges,
        /// app card badges and the toolbar Updates count.
        ///
        /// Before this, the only place that refreshed ALL of them after a scheduled download was
        /// the end-of-batch block in RunScheduledDownloadsAsync, and reaching that block depends on
        /// three things that can each fail quietly: the 10-second timer coming back, the
        /// AutoFlowStatus.FlowRunning lock having been released (the watchdog only breaks a stuck
        /// one after an hour), and no render throwing on the way there. When it did not run, a
        /// download that finished cleanly left "New" badges and a stale "Updates (n)" count on
        /// screen until the tab was left and returned to, which is the workaround people found for
        /// themselves.
        ///
        /// Three things make this safe to call straight from the download completion block:
        ///   - it targets _liveInstance, the page that loaded last and is therefore the one on
        ///     screen, so it cannot paint into a page instance that was rebuilt out from under it;
        ///   - it re-syncs that instance's own _allApps entry by name first, because a rebuilt page
        ///     holds different objects from the ones the completion block wrote the version to;
        ///   - every step is guarded on its own, so one render throwing cannot swallow the other
        ///     two and leave the log naming only the first failure.
        /// </summary>
        private static void SdRefreshDownloadTabAfterVersionChange(string appName, string version)
        {
            SourceDownloadPage? inst = _liveInstance;
            if (inst == null) return;   // page never loaded: nothing is on screen to repaint

            try
            {
                inst.Dispatcher.Invoke(() =>
                {
                    try
                    {
                        DownloadSourceEntry? listEntry = inst._allApps.FirstOrDefault(
                            a => string.Equals(a.SourceAppName, appName, System.StringComparison.OrdinalIgnoreCase));
                        if (listEntry != null && !string.IsNullOrWhiteSpace(version)
                            && listEntry.SourceAppVersion != version)
                        {
                            listEntry.SourceAppVersion = version;
                            listEntry.AppVersion       = version;
                            listEntry.IntuneAppVersion = version;
                            LogSched($"{appName}: live page held an older copy of this entry - re-synced to {version}");
                        }
                    }
                    catch (System.Exception exSync)
                    { LogSched($"{appName}: repaint re-sync FAILED - {exSync.GetType().Name}: {exSync.Message}"); }

                    try { inst.RenderVendors(); }
                    catch (System.Exception exV)
                    { LogSched($"{appName}: repaint RenderVendors FAILED - {exV.GetType().Name}: {exV.Message}"); }

                    try { inst.RenderCards(); }
                    catch (System.Exception exC)
                    { LogSched($"{appName}: repaint RenderCards FAILED - {exC.GetType().Name}: {exC.Message}"); }

                    try { inst.RefreshUpdatesBadge(); }
                    catch (System.Exception exU)
                    { LogSched($"{appName}: repaint RefreshUpdatesBadge FAILED - {exU.GetType().Name}: {exU.Message}"); }

                    // A version write moves apps between the Missed / Updates lists and
                    // changes Existing Version everywhere - refresh the status workbook.
                    try { inst.QueueStatusWorkbook(); }
                    catch (System.Exception exW)
                    { LogSched($"{appName}: repaint QueueStatusWorkbook FAILED - {exW.GetType().Name}: {exW.Message}"); }

                    LogSched($"{appName}: Download tab repainted on completion (vendors, cards, Updates count)");
                });
            }
            catch (System.Exception ex)
            { LogSched($"{appName}: Download tab repaint FAILED - {ex.GetType().Name}: {ex.Message}"); }
        }

        // Always opens the window - even with nothing out of date, because it now also carries
        // "last checked" and "Check now", which is exactly what you want when you think the numbers
        // look stale.
        private void BtnUpdates_Click(object sender, RoutedEventArgs e) => ShowDownloadsDialog();

        /// <summary>
        /// First-launch seed of the winget catalog, so a fresh machine never has to be told to press
        /// "Check now" before the Add App picker will list anything.
        ///
        /// Why it was needed: WingetCatalog.EnsureAsync had exactly two callers - the per-app version
        /// fetch inside FetchAllVersionsInBackgroundAsync, and the forced refresh under "Check now".
        /// A fresh install has ZERO configured apps, so the per-app loop never executes a single
        /// iteration and EnsureAsync is never reached. index.db therefore never appears,
        /// SearchPackages returns nothing, and the picker is blank with no explanation.
        /// catalog_snapshot.json and new_apps.json have the same problem one level up: only
        /// RefreshNewAppsAsync writes them, and only "Check now" calls it.
        ///
        /// Deliberately NOT done by the installer. The catalog lives under %LOCALAPPDATA%, which is
        /// per USER - a per-machine install writes it into the installing account (or SYSTEM) and
        /// every real user still starts empty. On top of that it would put a 7MB download inside a
        /// silent enterprise deployment, which is the one place a network stall is least welcome.
        ///
        /// Runs only when the files are actually absent, so an existing machine pays a File.Exists
        /// and nothing else; staleness stays the job of EnsureAsync's own cache gate.
        /// </summary>
        private async Task SeedWingetCatalogAsync()
        {
            if (_catalogSeedAttempted) return;
            _catalogSeedAttempted = true;
            try
            {
                bool haveIndex    = System.IO.File.Exists(WingetIndexPath);
                bool haveBaseline = System.IO.File.Exists(CatalogSnapshotPath);
                if (haveIndex && haveBaseline) return;

                LogWinget("[WingetCatalog] first launch on this machine - seeding the catalog in the background");
                if (!await WingetCatalog.EnsureAsync(_http, LogWinget).ConfigureAwait(true))
                {
                    LogWinget("[WingetCatalog] seed did not complete (offline?) - the picker stays empty "
                            + "until the next launch, or until Check now is pressed");
                    return;
                }

                // The FIRST RefreshNewAppsAsync only records the baseline and reports nothing new.
                // Getting that out of the way now means the user's first real "Check now" reports
                // actual new packages instead of spending itself writing the baseline.
                if (!haveBaseline) await RefreshNewAppsAsync().ConfigureAwait(true);

                LogWinget("[WingetCatalog] seed complete - the Add App picker is populated");
            }
            catch (Exception ex) { LogWinget($"[WingetCatalog] seed failed: {ex.Message}"); }
        }

        private async Task ReportMissedSchedulesAsync()
        {
            try
            {
                // BEFORE the version sweep, not alongside it: FetchAllVersionsInBackgroundAsync is
                // the other caller of EnsureAsync, and starting both would put two callers on the
                // same 7MB download. On an already-seeded machine this returns on a File.Exists.
                await SeedWingetCatalogAsync().ConfigureAwait(true);

                // Populate versions first (cached / catalog-backed, so normally no network at all).
                // This is now the ONLY automatic version sweep in the app.
                await FetchAllVersionsInBackgroundAsync().ConfigureAwait(true);
                RefreshUpdatesBadge();

                // The status workbook is written here on launch, by "Check now", and by
                // QueueStatusWorkbook whenever an app's status changes - so it stays current
                // without anything polling on a schedule.
                ExportStatusWorkbook();

                DateTime now = _sessionStart;

                // Shared builder - the startup report and the toolbar Updates button must never
                // disagree about what is out of date.
                var (missed, updates) = BuildUpdateLists(now);

                // Only the MISSED list justifies popping a dialog on startup. "Updates available" is
                // almost always non-empty, so raising a window for it every launch would be noise -
                // that is what the toolbar Updates button is for.
                if (missed.Count == 0) return;

                // ONCE per run of the app. This method is started from Loaded, which fires again on
                // every return to the Download tab, so switching to another feature and back put the
                // window straight back in your face - with the same list, already read. The report is
                // about what was missed while the app was CLOSED, so saying it once is the whole
                // story; the toolbar Updates button reopens the window on purpose.
                if (_missedReported) return;
                _missedReported = true;

                // ── Log ────────────────────────────────────────────────────────────────────────
                var log = new System.Text.StringBuilder();
                log.AppendLine($"[{DateTime.Now:yyyy-MM-dd HH:mm:ss}] Missed schedules - {missed.Count} app(s) with a newer version available.");
                log.AppendLine("SwiftPack was not running at the scheduled time. Nothing was downloaded.");
                foreach (var m in missed)
                    log.AppendLine(
                        $"    {m.Vendor} / {m.AppName}: scheduled {m.ExistingSchedule}, " +
                        $"have {m.ExistingVersion}, available {m.NewVersion}, next {m.NewSchedule}");
                LogWinget(log.ToString().TrimEnd());

                // Deliberately NO window here. This used to pop the Downloads dialog on
                // every launch that had missed schedules, which read as the app opening
                // with an interruption. The missed work is still fully visible: the badge
                // counts it, this log records it, and the toolbar Updates button opens the
                // same window on the user's own click.
            }
            catch (Exception ex)
            {
                LogWinget($"[MissedSchedules] failed: {ex.Message}");
            }
        }

        /// <summary>One row of the Downloads window tables - Missed Auto Schedules, Updates
        /// Available and Auto Schedules Status all share this shape (the last maps Status into
        /// ExistingSchedule and the timestamp into NewSchedule).</summary>
        private sealed class MissedRow : System.ComponentModel.INotifyPropertyChanged
        {
            /// <summary>The app itself, so double-clicking a row can jump straight to it.</summary>
            public DownloadSourceEntry? App { get; set; }
            public string Vendor           { get; set; } = "";
            public string AppName          { get; set; } = "";
            public string ExistingVersion  { get; set; } = "";
            public string NewVersion       { get; set; } = "";
            /// <summary>The frequency itself: Daily, Weekly, Every 2 weeks, Quarterly... or "manual".</summary>
            public string Schedule         { get; set; } = "";
            public string ExistingSchedule { get; set; } = "";
            public string NewSchedule      { get; set; } = "";
            // Eighth column, used only by tables that ask for one (Auto Schedules Status
            // binds its "Next Schedule" here); empty everywhere else.
            public string Extra            { get; set; } = "";

            // "", "match" or "current" - drives the search highlight row background via
            // DataTriggers on the status tab's row style. The one notifying property on
            // this row type, because it is the one the search rewrites while the list is
            // on screen; everything else is set once before the list is bound.
            public string HighlightState
            {
                get => _highlightState;
                set
                {
                    if (_highlightState == value) return;
                    _highlightState = value;
                    PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs(nameof(HighlightState)));
                }
            }
            private string _highlightState = "";
            public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged;
        }

        /// <summary>
        /// TextBlock that paints every occurrence of the current search query inside its own
        /// text: yellow normally, orange when its row is the current match. The query arrives
        /// through an inherited attached property set once per ListView, so one assignment
        /// re-renders every visible cell; black foreground on the painted runs keeps them
        /// readable in dark mode, where yellow-behind-white would vanish.
        /// </summary>
        private sealed class HighlightTextBlock : TextBlock
        {
            public static readonly DependencyProperty FullTextProperty = DependencyProperty.Register(
                nameof(FullText), typeof(string), typeof(HighlightTextBlock),
                new PropertyMetadata("", OnAnyChanged));
            public string FullText { get => (string)GetValue(FullTextProperty); set => SetValue(FullTextProperty, value); }

            /// <summary>"", "match" or "current" - the row's search state; only picks orange.</summary>
            public static readonly DependencyProperty MatchKindProperty = DependencyProperty.Register(
                nameof(MatchKind), typeof(string), typeof(HighlightTextBlock),
                new PropertyMetadata("", OnAnyChanged));
            public string MatchKind { get => (string)GetValue(MatchKindProperty); set => SetValue(MatchKindProperty, value); }

            public static readonly DependencyProperty SearchQueryProperty = DependencyProperty.RegisterAttached(
                "SearchQuery", typeof(string), typeof(HighlightTextBlock),
                new FrameworkPropertyMetadata("", FrameworkPropertyMetadataOptions.Inherits, OnAnyChanged));
            public static void   SetSearchQuery(DependencyObject d, string value) => d.SetValue(SearchQueryProperty, value);
            public static string GetSearchQuery(DependencyObject d) => (string)d.GetValue(SearchQueryProperty);

            private static readonly Brush MatchBg   = new SolidColorBrush(Color.FromRgb(0xFF, 0xE0, 0x66));
            private static readonly Brush CurrentBg = new SolidColorBrush(Color.FromRgb(0xFF, 0xA5, 0x2B));
            static HighlightTextBlock() { MatchBg.Freeze(); CurrentBg.Freeze(); }

            private static void OnAnyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
            {
                if (d is HighlightTextBlock h) h.RebuildInlines();
            }

            private void RebuildInlines()
            {
                Inlines.Clear();
                string t = FullText ?? "";
                string q = (GetSearchQuery(this) ?? "").Trim();
                if (q.Length == 0)
                {
                    Inlines.Add(new System.Windows.Documents.Run(t));
                    return;
                }
                Brush bg = MatchKind == "current" ? CurrentBg : MatchBg;
                int idx = 0;
                while (idx <= t.Length)
                {
                    int hit = idx < t.Length ? t.IndexOf(q, idx, StringComparison.OrdinalIgnoreCase) : -1;
                    if (hit < 0)
                    {
                        if (idx < t.Length) Inlines.Add(new System.Windows.Documents.Run(t.Substring(idx)));
                        break;
                    }
                    if (hit > idx) Inlines.Add(new System.Windows.Documents.Run(t.Substring(idx, hit - idx)));
                    Inlines.Add(new System.Windows.Documents.Run(t.Substring(hit, q.Length))
                    {
                        Background = bg,
                        Foreground = Brushes.Black,
                    });
                    idx = hit + q.Length;
                }
            }
        }

        /// <summary>One row of the New Apps table - a catalog package added since the last check.</summary>
        private sealed class NewAppRow
        {
            public string Vendor  { get; set; } = "";
            public string AppName { get; set; } = "";
            public string Version { get; set; } = "";
            public string Source  { get; set; } = "";   // "winget" or "github"
            public string Id      { get; set; } = "";    // winget package id, or owner/repo
        }

        // Snapshot of catalog identifiers taken at the last "Check now", so the next check can show
        // what was ADDED. winget uses package ids (installer-only, the same set the picker shows);
        // GitHub uses owner/repo from github_catalog.json. Both files live beside the winget index
        // (writable), NOT in Templates.
        private sealed class CatalogSnapshot
        {
            public List<string> Winget { get; set; } = new();
            public List<string> GitHub { get; set; } = new();
        }

        private static string CatalogSnapshotPath => System.IO.Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "SwiftPack", "winget", "catalog_snapshot.json");

        private static string NewAppsListPath => System.IO.Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "SwiftPack", "winget", "new_apps.json");

        // WingetCatalog owns this file; the path is repeated here ONLY to answer "has this machine
        // ever pulled the catalog?" without opening it. SearchPackages("") would answer the same
        // question, but it walks ~10k rows to do it, which is not what a startup gate should cost.
        private static string WingetIndexPath => System.IO.Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "SwiftPack", "winget", "index.db");

        // The four catalog files this page generates (catalog_snapshot, new_apps,
        // github_catalog, winget_noninstaller) each open with a "//" header explaining what
        // they are. JSON has no comments, so every read of them goes through these options;
        // without Skip, the first file written with a header would fail to parse. Trailing
        // commas are tolerated because two of the files are explicitly meant to be edited by
        // hand. Case-insensitive names because github_catalog uses camelCase keys against
        // PascalCase properties; for the other files the names match exactly either way.
        private static readonly System.Text.Json.JsonSerializerOptions _catalogReadOptions =
            new System.Text.Json.JsonSerializerOptions
            {
                ReadCommentHandling         = System.Text.Json.JsonCommentHandling.Skip,
                AllowTrailingCommas         = true,
                PropertyNameCaseInsensitive = true,
            };

        private static CatalogSnapshot? LoadCatalogSnapshot()
        {
            try
            {
                if (System.IO.File.Exists(CatalogSnapshotPath))
                    return System.Text.Json.JsonSerializer.Deserialize<CatalogSnapshot>(System.IO.File.ReadAllText(CatalogSnapshotPath), _catalogReadOptions);
            }
            catch { }
            return null;
        }

        // ── Auto schedule outcomes ─────────────────────────────────────────
        /// <summary>One finished scheduled download - the Auto Schedules Status tab's row.</summary>
        private sealed class ScheduleOutcome
        {
            public string Vendor          { get; set; } = "";
            public string AppName         { get; set; } = "";
            public string ExistingVersion { get; set; } = "";
            public string NewVersion      { get; set; } = "";
            public string Schedule        { get; set; } = "";
            public string Status          { get; set; } = "";   // "Completed" or "Failed"
            public string At              { get; set; } = "";   // ddd dd-MM-yyyy HH:mm
        }

        private static string ScheduleStatusPath => System.IO.Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "SwiftPack", "winget", "schedule_status.json");

        private static readonly object _scheduleStatusLock = new object();
        private const int ScheduleStatusCap = 300;

        private static List<ScheduleOutcome> LoadScheduleOutcomes()
        {
            try
            {
                if (System.IO.File.Exists(ScheduleStatusPath))
                    return System.Text.Json.JsonSerializer.Deserialize<List<ScheduleOutcome>>(
                        System.IO.File.ReadAllText(ScheduleStatusPath), _catalogReadOptions) ?? new();
            }
            catch { }
            return new();
        }

        // Set when a SCHEDULED download hands off to the action chain, consumed when the
        // chain reports finished. Manual chains null it, so a manual run can never amend a
        // scheduled row. Chains are serialized by AutoFlowStatus.FlowRunning, which is what
        // makes one static marker sufficient.
        private static string? _scheduledChainKey;

        /// <summary>Writes the outcome list with its header. Caller holds _scheduleStatusLock.</summary>
        private static void SaveScheduleOutcomesLocked(List<ScheduleOutcome> list)
        {
            System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(ScheduleStatusPath)!);
            string nl = Environment.NewLine;
            string header = string.Join(nl, new[]
            {
                "// schedule_status.json - the outcome of every scheduled auto download this",
                "// machine has run, newest first: the app, the version it moved from and to,",
                "// its schedule, and whether the run Completed or Failed. A run that downloads",
                "// fine but fails a chained action (install source, create package, publish...)",
                "// counts as Failed. Shown on the \"Auto Schedules Status\" tab of the Downloads",
                "// window.",
                "//",
                "// Derived history, capped at the most recent " + ScheduleStatusCap + " outcomes. Safe to",
                "// delete - the tab simply starts empty again.",
            }) + nl;
            System.IO.File.WriteAllText(ScheduleStatusPath,
                header + System.Text.Json.JsonSerializer.Serialize(list,
                    new System.Text.Json.JsonSerializerOptions
                    {
                        WriteIndented = true,
                        Encoder       = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
                    }));
        }

        /// <summary>
        /// The chain's veto. The row was written "Completed" the moment the download landed,
        /// but a scheduled run is download PLUS its selected actions, so when the chain ends
        /// with any step Failed the newest row for that app is rewritten Failed and stamped
        /// with the moment the chain gave its verdict.
        /// </summary>
        private static void AmendLatestScheduleOutcome(string vendor, string appName)
        {
            try
            {
                lock (_scheduleStatusLock)
                {
                    var list = LoadScheduleOutcomes();
                    var row = list.FirstOrDefault(o =>
                        string.Equals(o.Vendor,  vendor,  StringComparison.OrdinalIgnoreCase) &&
                        string.Equals(o.AppName, appName, StringComparison.OrdinalIgnoreCase));
                    if (row == null || row.Status == "Failed") return;
                    row.Status = "Failed";
                    row.At     = DateTime.Now.ToString("ddd dd-MM-yyyy HH:mm");
                    SaveScheduleOutcomesLocked(list);
                }
                LogSched($"{appName}: schedule outcome amended to Failed - the download landed but a chained action failed");
            }
            catch (Exception ex) { LogSched($"{appName}: schedule outcome NOT amended - {ex.Message}"); }
        }

        /// <summary>
        /// Appends one scheduled download's verdict, newest first, capped. Called from the
        /// download task's terminal points (worker thread) for scheduled runs only, which is
        /// why the whole load-insert-save is under a lock: two scheduled downloads never
        /// overlap today, but nothing here should depend on that staying true.
        /// </summary>
        private static void RecordScheduleOutcome(string vendor, string appName,
            string existingVersion, string newVersion, string schedule, bool failed)
        {
            try
            {
                lock (_scheduleStatusLock)
                {
                    var list = LoadScheduleOutcomes();
                    list.Insert(0, new ScheduleOutcome
                    {
                        Vendor          = vendor,
                        AppName         = appName,
                        ExistingVersion = string.IsNullOrWhiteSpace(existingVersion) ? "(never downloaded)" : existingVersion,
                        NewVersion      = newVersion,
                        Schedule        = schedule,
                        Status          = failed ? "Failed" : "Completed",
                        At              = DateTime.Now.ToString("ddd dd-MM-yyyy HH:mm"),
                    });
                    if (list.Count > ScheduleStatusCap) list.RemoveRange(ScheduleStatusCap, list.Count - ScheduleStatusCap);
                    SaveScheduleOutcomesLocked(list);
                }
                LogSched($"{appName}: schedule outcome recorded - {(failed ? "Failed" : "Completed")}");
            }
            catch (Exception ex) { LogSched($"{appName}: schedule outcome NOT recorded - {ex.Message}"); }
        }

        private static void SaveCatalogSnapshot(List<string> winget, List<string> github)
        {
            try
            {
                System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(CatalogSnapshotPath)!);

                // One id per line. This file is 11,000 ids and was written as a single line, which is
                // unreadable in an editor and impossible to diff - and it does get opened by hand,
                // since removing ids from it is how a Check now is tested.
                //
                // The relaxed encoder for the same reason: the default wrote
                // "RamenSoftware.7\u002BTaskbarTweaker" where the package is plainly 7+TaskbarTweaker.
                // Both forms parse identically, so nothing downstream notices.
                string nl = Environment.NewLine;
                string header = string.Join(nl, new[]
                {
                    "// catalog_snapshot.json - the winget catalog baseline from the last \"Check now\"",
                    "// on the Auto Package Download tab. The next check diffs the live catalog against",
                    "// these ids; anything not listed here counts as a new app. Written after every",
                    "// check, so the baseline moves forward each time.",
                    "//",
                    "// The ids come from the local winget package index (installer-only packages, with",
                    "// pre-release builds and known non-installers filtered out - the same set the",
                    "// winget picker shows).",
                    "//",
                    "// Safe to experiment with: removing ids makes the next check report those packages",
                    "// as new again, and deleting the whole file turns the next check into a",
                    "// baseline-only run that reports nothing.",
                }) + nl;
                System.IO.File.WriteAllText(CatalogSnapshotPath,
                    header + System.Text.Json.JsonSerializer.Serialize(
                        new CatalogSnapshot { Winget = winget, GitHub = github },
                        new System.Text.Json.JsonSerializerOptions
                        {
                            WriteIndented = true,
                            Encoder       = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
                        }));
            }
            catch { }
        }

        // The New Apps list from the last check, read straight off disk. Currently UNCALLED:
        // the New Apps tab was removed from the Downloads window on request, but the data
        // keeps being written by every check (see RefreshNewAppsAsync), so this loader stays
        // for the day the tab comes back rather than being rebuilt from scratch.
        private List<NewAppRow> LoadNewApps()
        {
            try
            {
                if (System.IO.File.Exists(NewAppsListPath))
                    return System.Text.Json.JsonSerializer.Deserialize<List<NewAppRow>>(System.IO.File.ReadAllText(NewAppsListPath), _catalogReadOptions) ?? new();
            }
            catch { }
            return new();
        }

        // Called by "Check now" AFTER the catalog is refreshed. Diffs winget against the snapshot to
        // find newly-added packages, then probes each one's manifest to see if it is GitHub-hosted:
        // GitHub-hosted installers are added to the GitHub catalog (so the picker gets them) and shown
        // as "github"; everything else is shown as "winget". The baseline then moves forward. The FIRST
        // call just records the baseline and returns nothing. Reports progress through the callback.
        private async Task<List<NewAppRow>> RefreshNewAppsAsync(Action<int, int>? progress = null)
        {
            var rows = new List<NewAppRow>();
            try
            {
                var hide = WingetHiddenIds();
                var wingetNow = WingetCatalog.SearchPackages("")
                    .Where(p => !hide.Contains(p.Id) && !IsBetaPackage(p.Id, p.Name))
                    .ToList();
                var wingetIds = wingetNow.Select(p => p.Id).ToList();

                var snap = LoadCatalogSnapshot();
                if (snap == null)   // first run - baseline only, nothing is "new" yet
                {
                    // Said out loud, because it is the answer to "why did nothing update?". Deleting
                    // the winget cache folder puts every check back here for one run.
                    LogWinget($"[NewApps] first check - baseline recorded ({wingetIds.Count} packages), " +
                              $"nothing counts as new yet");
                    SaveCatalogSnapshot(wingetIds, new List<string>());
                    PersistNewApps(rows);
                    return rows;
                }

                var oldW = new HashSet<string>(snap.Winget, StringComparer.OrdinalIgnoreCase);
                var newWinget = wingetNow.Where(p => !oldW.Contains(p.Id)).ToList();

                // The one number that explains everything downstream. Zero here means the catalog has
                // not changed since the last check, so there is nothing to add to either reference
                // file - which is the intended behaviour, not a failed write.
                LogWinget($"[NewApps] {newWinget.Count} new package(s) since the last check " +
                          $"(catalog now holds {wingetIds.Count})");

                // Probe every new package's manifest (in parallel, bounded) to classify GitHub-hosted vs
                // plain winget. A GitHub-hosted installer found here did not exist at the last check, so
                // it is a genuinely new GitHub app.
                var probe = new System.Collections.Concurrent.ConcurrentDictionary<string, (GitHubApp? Gh, bool NonInstaller)>();
                int done = 0, total = newWinget.Count;
                using (var gate = new System.Threading.SemaphoreSlim(12))
                {
                    var tasks = newWinget.Select(async p =>
                    {
                        await gate.WaitAsync().ConfigureAwait(false);
                        try { probe[p.Id] = await ProbeGitHubAppAsync(p.Id, p.Version, p.Name).ConfigureAwait(false); }
                        finally
                        {
                            gate.Release();
                            progress?.Invoke(System.Threading.Interlocked.Increment(ref done), total);
                        }
                    });
                    await Task.WhenAll(tasks).ConfigureAwait(true);
                }

                var discovered    = new List<GitHubApp>();
                var nonInstallers = new List<string>();
                foreach (var p in newWinget)
                {
                    probe.TryGetValue(p.Id, out var pr);
                    if (pr.Gh != null)
                    {
                        discovered.Add(pr.Gh);
                        rows.Add(new NewAppRow { Vendor = pr.Gh.Vendor, AppName = pr.Gh.Name, Version = pr.Gh.Version, Source = "github", Id = pr.Gh.Repo });
                    }
                    else if (pr.NonInstaller)
                    {
                        // Recorded, and deliberately NOT listed. A zip or an MSIX cannot be packaged,
                        // so announcing it as a new app only leads someone to add it and find no
                        // download link. The picker already hides these; New Apps now agrees.
                        nonInstallers.Add(p.Id);
                    }
                    else
                    {
                        int dot = p.Id.IndexOf('.');
                        rows.Add(new NewAppRow { Vendor = dot > 0 ? p.Id.Substring(0, dot) : p.Id, AppName = p.Name, Version = p.Version, Source = "winget", Id = p.Id });
                    }
                }

                if (discovered.Count > 0)    GitHubCatalog.AddDiscovered(discovered);
                if (nonInstallers.Count > 0) AddWingetNonInstallerIds(nonInstallers);

                rows = rows.OrderBy(r => r.Vendor, StringComparer.OrdinalIgnoreCase)
                           .ThenBy(r => r.AppName, StringComparer.OrdinalIgnoreCase).ToList();

                SaveCatalogSnapshot(wingetIds, new List<string>());   // baseline moves forward
                PersistNewApps(rows);
            }
            catch (Exception ex) { LogWinget($"[NewApps] refresh failed: {ex.Message}"); }
            return rows;
        }

        private static void PersistNewApps(List<NewAppRow> rows)
        {
            try
            {
                System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(NewAppsListPath)!);
                string nl = Environment.NewLine;
                string header = string.Join(nl, new[]
                {
                    "// new_apps.json - packages that appeared in the winget catalog since the",
                    "// previous \"Check now\", cached from the last check. Source says whether each",
                    "// one's installer turned out to be GitHub-hosted (\"github\") or plain winget",
                    "// (\"winget\").",
                    "//",
                    "// The Downloads window no longer shows this list (the New Apps tab was",
                    "// removed), but every check still refreshes it, and the same probe feeds the",
                    "// GitHub catalog and the non-installer list.",
                    "//",
                    "// Derived cache, rewritten by every check - not a file to edit, safe to delete.",
                }) + nl;
                System.IO.File.WriteAllText(NewAppsListPath, header + System.Text.Json.JsonSerializer.Serialize(rows));
            }
            catch { }
        }

        // Fetches ONE new winget package's manifest and, if its installer is hosted on GitHub releases
        // AND it resolves to a real MSI/EXE installer (not a zip / portable-in-zip / msix archive),
        // returns the GitHub app (owner/repo + identity). Otherwise null. Same raw CDN + parser the
        // download path uses - no GitHub API quota is touched.
        private async Task<(GitHubApp? Gh, bool NonInstaller)> ProbeGitHubAppAsync(string id, string version, string name)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(id) || string.IsNullOrWhiteSpace(version) || id.IndexOf('.') < 0) return (null, false);
                string relPath = "manifests/" + char.ToLowerInvariant(id[0]) + "/" + id.Replace('.', '/');
                string verSeg  = Uri.EscapeDataString(version);
                string yaml = await _http.GetStringAsync($"https://raw.githubusercontent.com/microsoft/winget-pkgs/master/{relPath}/{verSeg}/{id}.installer.yaml").ConfigureAwait(false);

                // zip / portable / msix. Not usable, and now SAID so rather than just dropped: this is
                // exactly the verdict winget_noninstaller.json exists to record.
                if (ParseWingetManifest(yaml).type == "type unknown") return (null, true);

                var m = System.Text.RegularExpressions.Regex.Match(
                    yaml, @"InstallerUrl:\s*https?://github\.com/([A-Za-z0-9._-]+)/([A-Za-z0-9._-]+)",
                    System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                if (!m.Success) return (null, false);

                int dot = id.IndexOf('.');
                return (new GitHubApp
                {
                    Repo    = m.Groups[1].Value + "/" + m.Groups[2].Value,
                    Vendor  = dot > 0 ? id.Substring(0, dot) : id,
                    Name    = name,
                    Version = version,
                    Id      = id,
                }, false);
            }
            // A fetch that failed says nothing about the installer type, so it is not recorded as
            // a non-installer - a network blip must not hide a package for good.
            catch { return (null, false); }
        }

        /// <summary>
        /// The Downloads window. One place for everything to do with what is out of date.
        ///
        ///   Missed Auto Schedules - should have downloaded while we were closed, and has a newer version
        ///   Auto Schedules Status - the latest verdict per app: Completed, or Failed if the download
        ///                           or ANY selected chained action failed
        ///   Updates Available     - apps with a newer version to download manually
        ///
        /// Missed and Updates are DISJOINT: an app waiting on a missed schedule appears only on the
        /// missed tab, so nobody sees the same app offered twice and wonders which entry to act on.
        ///
        /// The New Apps tab was removed on request - the list only invited "should I add this?"
        /// doubt. The machinery behind it still runs on every Check now (new_apps.json, the GitHub
        /// catalog and the non-installer list all keep growing), so putting the tab back is one
        /// TabItem away.
        ///
        /// Opening this costs NOTHING - it just displays what is already cached. The one expensive
        /// action, "Check now", lives here beside a "last checked" timestamp that tells you whether it
        /// is even worth pressing. That is the whole reason the toolbar's Refresh button is gone: two
        /// buttons that both sounded like "check for updates", one free and instant, one hitting the
        /// network for every app, with nothing on screen to say which was which.
        ///
        /// Double-clicking a row closes the window and jumps to that app, ready to download manually.
        /// </summary>
        private void ShowDownloadsDialog()
        {
            var winBg     = Res("WindowBgBrush",      Brushes.White);
            var borderClr = Res("BorderMainBrush",    Brushes.LightGray);
            var lblFg     = Res("TextSecondaryBrush", Brushes.Gray);
            var valFg     = Res("TextPrimaryBrush",   Brushes.Black);
            // Table grid lines: translucent grey reads as a hairline on both themes.
            var gridLine = new SolidColorBrush(Color.FromArgb(0x40, 0x90, 0x90, 0x90));
            gridLine.Freeze();

            // 1180 wide: the eight columns total 1060px, and less than that would force a horizontal
            // scrollbar once the margins, border and vertical scrollbar are taken out.
            var win = new Window
            {
                Width = 1180, Height = 480,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = Window.GetWindow(this),
                ResizeMode = ResizeMode.NoResize,
                WindowStyle = WindowStyle.None,
                AllowsTransparency = true,
                Background = Brushes.Transparent,
                ShowInTaskbar = false,
            };
            var outer = new Border
            {
                Background = winBg, BorderBrush = borderClr, BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(10),
            };
            win.Content = outer;

            var g = new Grid { Margin = new Thickness(16) };
            g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });                      // title
            g.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) }); // tabs
            g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });                      // note
            g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });                      // footer
            outer.Child = g;

            var title = new TextBlock
            {
                Text = "Applications Status", FontSize = 13, FontWeight = FontWeights.SemiBold,
                Foreground = valFg, Margin = new Thickness(0, 0, 0, 8),
            };
            title.MouseLeftButtonDown += (_, _) => win.DragMove();
            Grid.SetRow(title, 0); g.Children.Add(title);

            // Close (X), top right of the title row. The window is WindowStyle.None, so it has no
            // system title bar and the only way out was the OK button down in the footer.
            var closeBtn = new Button
            {
                Content = "\u2715", FontSize = 12, Width = 26, Height = 22,
                Foreground = lblFg, Background = Brushes.Transparent,
                BorderThickness = new Thickness(0), Template = RoundedTabButtonTemplate(),
                HorizontalAlignment = HorizontalAlignment.Right,
                VerticalAlignment   = VerticalAlignment.Top,
                Cursor = System.Windows.Input.Cursors.Hand, ToolTip = "Close",
            };
            closeBtn.MouseEnter += (_, _) => closeBtn.Foreground = valFg;
            closeBtn.MouseLeave += (_, _) => closeBtn.Foreground = lblFg;
            closeBtn.Click      += (_, _) => win.Close();
            Grid.SetRow(closeBtn, 0); g.Children.Add(closeBtn);

            var note = new TextBlock
            {
                FontSize = 10, FontStyle = FontStyles.Italic, Foreground = lblFg,
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 10, 0, 0),
            };
            Grid.SetRow(note, 2); g.Children.Add(note);

            // GridView always appends a filler header after the last real column (Role="Padding").
            // Nobody declared it; it is what shows up as an empty column. Collapse it.
            var hdrStyle = new Style(typeof(GridViewColumnHeader));
            var padTrigger = new Trigger { Property = GridViewColumnHeader.RoleProperty, Value = GridViewColumnHeaderRole.Padding };
            padTrigger.Setters.Add(new Setter(UIElement.VisibilityProperty, Visibility.Collapsed));
            hdrStyle.Triggers.Add(padTrigger);

            // The row container. Left alone, the stock GridView row paints a near-white band under
            // the pointer and under the selection while the cell text keeps the theme foreground -
            // light text on a light band, so the row reads as blank the moment you touch it. Own the
            // row template instead: the highlight becomes a translucent tint of the accent colour,
            // which sits behind the text on both themes, and the foreground is pinned to the theme
            // colour so the system highlight colour can never take over.
            Color accent = Res("AccentBlueBrush", Brushes.DodgerBlue) is SolidColorBrush accentBrush
                ? accentBrush.Color
                : Colors.DodgerBlue;
            var rowHoverBg = new SolidColorBrush(Color.FromArgb(0x33, accent.R, accent.G, accent.B));
            var rowSelBg   = new SolidColorBrush(Color.FromArgb(0x66, accent.R, accent.G, accent.B));
            var rowSelBd   = new SolidColorBrush(Color.FromArgb(0xB0, accent.R, accent.G, accent.B));
            rowHoverBg.Freeze();
            rowSelBg.Freeze();
            rowSelBd.Freeze();

            var rowStyle = new Style(typeof(ListViewItem));
            rowStyle.Setters.Add(new Setter(Control.ForegroundProperty,      valFg));
            rowStyle.Setters.Add(new Setter(Control.BackgroundProperty,      Brushes.Transparent));
            // Horizontal grid line: bottom hairline per row, via the row template's Border.
            rowStyle.Setters.Add(new Setter(Control.BorderBrushProperty,     gridLine));
            rowStyle.Setters.Add(new Setter(Control.BorderThicknessProperty, new Thickness(0, 0, 0, 1)));
            rowStyle.Setters.Add(new Setter(Control.TemplateProperty,
                DownloadsRowTemplate(rowHoverBg, rowSelBg, rowSelBd)));

            // ── Column sorting: click a header to sort, click again to flip ────
            // Every column of every table. The comparer is type-aware per cell pair:
            // the tables' own timestamp format sorts chronologically, dotted versions
            // sort numerically, everything else alphabetically (case-insensitive).
            var colPath   = new Dictionary<GridViewColumn, (string Path, string Header)>();
            var sortState = new Dictionary<ListView, (GridViewColumn Col, bool Asc)>();
            Func<MissedRow, string> CellOf(string path) => path switch
            {
                "Vendor"           => m => m.Vendor,
                "AppName"          => m => m.AppName,
                "ExistingVersion"  => m => m.ExistingVersion,
                "NewVersion"       => m => m.NewVersion,
                "Schedule"         => m => m.Schedule,
                "ExistingSchedule" => m => m.ExistingSchedule,
                "NewSchedule"      => m => m.NewSchedule,
                "Extra"            => m => m.Extra,
                _                  => m => "",
            };
            int CompareCells(string a, string b)
            {
                bool da = DateTime.TryParseExact(a, "ddd dd-MM-yyyy HH:mm",
                    System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.None, out var ta);
                bool db = DateTime.TryParseExact(b, "ddd dd-MM-yyyy HH:mm",
                    System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.None, out var tb);
                if (da && db) return ta.CompareTo(tb);
                if (da != db) return da ? 1 : -1;   // plain text ("-", "unknown") groups before real dates
                if (Version.TryParse(a, out var va) && Version.TryParse(b, out var vb)) return va.CompareTo(vb);
                return string.Compare(a, b, StringComparison.OrdinalIgnoreCase);
            }
            void SortByColumn(ListView lv, GridViewColumn col)
            {
                if (lv.ItemsSource is not List<MissedRow> rows || rows.Count == 0) return;
                bool asc = !(sortState.TryGetValue(lv, out var st) && st.Col == col && st.Asc);
                sortState[lv] = (col, asc);
                var get = CellOf(colPath[col].Path);
                var sorted = new List<MissedRow>(rows);
                sorted.Sort((x, y) =>
                {
                    int c = CompareCells(get(x) ?? "", get(y) ?? "");
                    return asc ? c : -c;
                });
                lv.ItemsSource = sorted;
                if (lv.View is GridView sortedGv)
                    foreach (var c in sortedGv.Columns)
                        if (colPath.TryGetValue(c, out var meta))
                            c.Header = c == col ? meta.Header + (asc ? "  ▲" : "  ▼") : meta.Header;
                // Row indices just changed; the search's match positions must follow.
                RecomputeStatusSearch();
            }

            ListView MakeTable(string col6, string col7, string? col8 = null)
            {
                var lv = new ListView
                {
                    FontSize = 11, Foreground = valFg, BorderBrush = borderClr,
                    BorderThickness = new Thickness(1),
                };
                lv.SetResourceReference(ListView.BackgroundProperty, "InputBgBrush");
                lv.Resources.Add(typeof(GridViewColumnHeader), hdrStyle);
                lv.ItemContainerStyle = rowStyle;

                var gv = new GridView();
                void Col(string header, string path, double w)
                {
                    // CellTemplate instead of DisplayMemberBinding so the cell can paint the
                    // matched substring; margin mirrors the default cell TextBlock's.
                    var cell = new FrameworkElementFactory(typeof(HighlightTextBlock));
                    cell.SetBinding(HighlightTextBlock.FullTextProperty,  new System.Windows.Data.Binding(path));
                    cell.SetBinding(HighlightTextBlock.MatchKindProperty, new System.Windows.Data.Binding("HighlightState"));
                    cell.SetValue(FrameworkElement.MarginProperty, new Thickness(6, 0, 6, 0));
                    var gvc = new GridViewColumn
                    {
                        Header = header, Width = w,
                        CellTemplate = new DataTemplate { VisualTree = cell },
                    };
                    colPath[gvc] = (path, header);
                    gv.Columns.Add(gvc);
                }
                Col("Vendor",           "Vendor",           135);
                Col("App Name",         "AppName",          145);
                Col("Existing Version", "ExistingVersion",  110);
                Col("New Version",      "NewVersion",       110);
                Col("Schedule",         "Schedule",          95);   // Daily / Weekly / Quarterly ...
                Col(col6,               "ExistingSchedule", 155);
                Col(col7,               "NewSchedule",      155);
                if (col8 != null) Col(col8, "Extra",        155);
                lv.View = gv;

                lv.MouseDoubleClick += (_, _) =>
                {
                    if (lv.SelectedItem is not MissedRow mr || mr.App == null) return;
                    win.Close();
                    SelectAppAnyVendor(mr.App);
                };
                return lv;
            }

            // ── Columns fill the list, no dead strip on the right ──────────────────────────
            // GridView never stretches a column. The declared widths total 905 (1060 with the
            // eighth), the list is wider than that, and the leftover showed as an empty band past
            // the last column - the padding header is collapsed, so it read as blank table rather
            // than as an unused column. Hand the leftover to the LAST column, measured off the
            // ScrollViewer's viewport so a vertical scrollbar is already discounted. Resizing any
            // other column is absorbed the same way, so the table stays flush with the right edge
            // whatever the user drags.
            bool fitting = false;
            void FitColumns(ListView lv)
            {
                if (fitting || lv.View is not GridView gv || gv.Columns.Count == 0) return;
                double avail = FindVisualChild<ScrollViewer>(lv)?.ViewportWidth ?? 0;
                if (avail <= 1) return;                 // no layout pass yet, nothing to measure
                double used = 0;
                for (int i = 0; i < gv.Columns.Count - 1; i++) used += gv.Columns[i].ActualWidth;
                var lastCol = gv.Columns[gv.Columns.Count - 1];
                double want = avail - used - 1;         // 1px keeps the fill off the border
                // Below this there is nothing sensible left to show, so stop fighting the drag and
                // let the horizontal scrollbar appear instead of crushing the last column.
                if (want < 80) return;
                if (Math.Abs(want - lastCol.Width) < 0.5) return;
                fitting = true;
                try { lastCol.Width = want; }
                finally { fitting = false; }
            }

            // Vertical grid lines as an overlay anchored to the HEADERS' rendered geometry:
            // each boundary is read from a real GridViewColumnHeader's on-screen position and
            // width, so the lines sit exactly on the header seams by construction. Cell-level
            // borders were tried and depended on how GridViewRowPresenter arranges each cell,
            // which is precisely what kept going wrong; this bypasses the cells entirely.
            Grid WithGridLines(ListView lv)
            {
                var lines = new Canvas { IsHitTestVisible = false };
                void Redraw()
                {
                    lines.Children.Clear();
                    if (lv.ActualHeight <= 0) return;
                    var headers = new List<GridViewColumnHeader>();
                    void Walk(DependencyObject d)
                    {
                        int n = System.Windows.Media.VisualTreeHelper.GetChildrenCount(d);
                        for (int i = 0; i < n; i++)
                        {
                            var c = System.Windows.Media.VisualTreeHelper.GetChild(d, i);
                            if (c is GridViewColumnHeader h && h.Role != GridViewColumnHeaderRole.Padding && h.Column != null)
                                headers.Add(h);
                            Walk(c);
                        }
                    }
                    Walk(lv);
                    if (headers.Count < 2) return;
                    headers.Sort((a, b) =>
                        a.TransformToAncestor(lv).Transform(default).X
                        .CompareTo(b.TransformToAncestor(lv).Transform(default).X));
                    var first = headers[0].TransformToAncestor(lv).Transform(default);
                    double top = first.Y + headers[0].ActualHeight;
                    double height = lv.ActualHeight - top - 2;
                    if (height <= 0) return;
                    double x = first.X;
                    // Boundaries BETWEEN columns only: count-1 lines, none at the outer edges.
                    for (int i = 0; i < headers.Count - 1; i++)
                    {
                        x += headers[i].ActualWidth;
                        var r = new System.Windows.Shapes.Rectangle { Width = 1, Height = height, Fill = gridLine };
                        Canvas.SetLeft(r, x - 0.5);
                        Canvas.SetTop(r, top);
                        lines.Children.Add(r);
                    }
                }
                // Loaded refires each time the tab shows its content again; the deferred call
                // lets the headers finish their first layout before they are measured.
                lv.Loaded      += (_, _) => Dispatcher.BeginInvoke(
                    (Action)(() => { FitColumns(lv); Redraw(); }),
                    System.Windows.Threading.DispatcherPriority.Loaded);
                lv.SizeChanged += (_, _) => { FitColumns(lv); Redraw(); };

                // Dragging a header gripper changes NO ListView size, so SizeChanged never fired
                // and the overlay kept the line positions it had before the drag. Every line then
                // sat one column-delta away from the seam it traces - and since those lines are
                // what the eye reads as the column edges, widening a header looked like nothing
                // had moved. The only notification a resize produces is GridViewColumn's
                // PropertyChanged for ActualWidth, so listen to that.
                if (lv.View is GridView gvCols && gvCols.Columns.Count > 0)
                {
                    var fillCol = gvCols.Columns[gvCols.Columns.Count - 1];
                    foreach (var gvc in gvCols.Columns)
                    {
                        var watched = gvc;
                        ((System.ComponentModel.INotifyPropertyChanged)watched).PropertyChanged += (_, ev) =>
                        {
                            if (ev.PropertyName != "ActualWidth") return;
                            // The last column is the one absorbing the leftover; refitting on its
                            // own change would snap a drag of it straight back.
                            if (!ReferenceEquals(watched, fillCol)) FitColumns(lv);
                            Dispatcher.BeginInvoke((Action)Redraw,
                                System.Windows.Threading.DispatcherPriority.Loaded);
                        };
                    }
                }

                var host = new Grid();
                host.Children.Add(lv);
                host.Children.Add(lines);
                return host;
            }

            // Applications tab table: the full catalog. Reuses MissedRow (App + the display fields)
            // so the shared search, column-sort and double-click-to-open machinery all apply, exactly
            // like the status tab does. Columns map onto MissedRow paths CellOf already understands:
            // Version->ExistingVersion, API Type->Schedule, Category->ExistingSchedule, Source->NewSchedule.
            ListView MakeAppsTable()
            {
                var lv = new ListView
                {
                    FontSize = 11, Foreground = valFg, BorderBrush = borderClr,
                    BorderThickness = new Thickness(1),
                };
                lv.SetResourceReference(ListView.BackgroundProperty, "InputBgBrush");
                lv.Resources.Add(typeof(GridViewColumnHeader), hdrStyle);
                lv.ItemContainerStyle = rowStyle;

                var gv = new GridView();
                void Col(string header, string path, double w)
                {
                    var cell = new FrameworkElementFactory(typeof(HighlightTextBlock));
                    cell.SetBinding(HighlightTextBlock.FullTextProperty,  new System.Windows.Data.Binding(path));
                    cell.SetBinding(HighlightTextBlock.MatchKindProperty, new System.Windows.Data.Binding("HighlightState"));
                    cell.SetValue(FrameworkElement.MarginProperty, new Thickness(6, 0, 6, 0));
                    var gvc = new GridViewColumn
                    {
                        Header = header, Width = w,
                        CellTemplate = new DataTemplate { VisualTree = cell },
                    };
                    colPath[gvc] = (path, header);
                    gv.Columns.Add(gvc);
                }
                Col("Vendor",   "Vendor",           150);
                Col("App Name", "AppName",          170);
                Col("Version",  "ExistingVersion",  110);
                Col("API Type", "Schedule",          95);
                Col("Category", "ExistingSchedule", 120);
                Col("Source",   "NewSchedule",      250);
                lv.View = gv;

                lv.MouseDoubleClick += (_, _) =>
                {
                    if (lv.SelectedItem is not MissedRow mr || mr.App == null) return;
                    win.Close();
                    SelectAppAnyVendor(mr.App);
                };
                return lv;
            }
            var lvApps    = MakeAppsTable();
            var lvMissed  = MakeTable("Existing Schedule", "Next Schedule");
            var lvUpdates = MakeTable("Auto Download",     "Next Scheduled");
            // Same seven columns as the missed tab plus "Next Schedule", with Status and the
            // timestamp carrying the verdict. MissedRow is reused as the row type (Status
            // rides in ExistingSchedule, the timestamp in NewSchedule, Next Schedule in
            // Extra), which is what makes double-click-to-open work here for free.
            var lvStatus  = MakeTable("Status",            "Completed At", "Next Schedule");

            var tMissed  = new TabItem { Content = WithGridLines(lvMissed)  };
            var tStatus  = new TabItem { Content = WithGridLines(lvStatus)  };
            var tUpdates = new TabItem { Content = WithGridLines(lvUpdates) };
            var tApps    = new TabItem { Content = WithGridLines(lvApps)    };

            // Strip order: Applications, Updates Available, Auto Schedules Status, Missed Auto Schedules.
            var tabs = new TabControl { Background = Brushes.Transparent, BorderThickness = new Thickness(0) };
            tabs.Items.Add(tApps);
            tabs.Items.Add(tUpdates);
            tabs.Items.Add(tStatus);
            tabs.Items.Add(tMissed);

            // ── Find bar, in the tab strip, working on WHICHEVER tab is active ─
            // ◀ [ 🔍 Search            1/10 ] ▶  - everything round-cornered. Navigation,
            // not filtering, and the highlight is painted on the matched text itself by
            // HighlightTextBlock, not on whole rows.
            ControlTemplate RoundButtonTemplate()
            {
                System.Windows.Data.Binding FromBtn(string p) => new System.Windows.Data.Binding(p)
                {
                    RelativeSource = new System.Windows.Data.RelativeSource(
                        System.Windows.Data.RelativeSourceMode.TemplatedParent),
                };
                var bd = new FrameworkElementFactory(typeof(Border));
                bd.SetValue(Border.CornerRadiusProperty, new CornerRadius(8));
                bd.SetBinding(Border.BackgroundProperty,      FromBtn(nameof(Control.Background)));
                bd.SetBinding(Border.BorderBrushProperty,     FromBtn(nameof(Control.BorderBrush)));
                bd.SetBinding(Border.BorderThicknessProperty, FromBtn(nameof(Control.BorderThickness)));
                var cp = new FrameworkElementFactory(typeof(ContentPresenter));
                cp.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Center);
                cp.SetValue(FrameworkElement.VerticalAlignmentProperty,   VerticalAlignment.Center);
                bd.AppendChild(cp);
                return new ControlTemplate(typeof(Button)) { VisualTree = bd };
            }
            Button MkNavBtn(string glyph)
            {
                var b = new Button
                {
                    Content = glyph, Width = 28, Height = 26, FontSize = 11,
                    Foreground = valFg, BorderBrush = borderClr, BorderThickness = new Thickness(1),
                    Margin = new Thickness(0, 0, 5, 0), Template = RoundButtonTemplate(),
                };
                b.SetResourceReference(Button.BackgroundProperty, "InputBgBrush");
                return b;
            }
            var btnStatusPrev = MkNavBtn("◀");
            var btnStatusNext = MkNavBtn("▶");
            btnStatusNext.Margin = new Thickness(0);

            var mutedFg = TryBrush("TextMutedBrush") ?? Brushes.Gray;
            var statusSearch = new TextBox
            {
                FontSize = 11, BorderThickness = new Thickness(0), Background = Brushes.Transparent,
                Foreground = valFg, VerticalAlignment = VerticalAlignment.Center,
                VerticalContentAlignment = VerticalAlignment.Center, Padding = new Thickness(0),
                // WPF's default caret is effectively black; on the dark theme's input
                // background it vanished. Following the themed foreground fixes both modes.
                CaretBrush = valFg,
            };
            var statusPlaceholder = new TextBlock
            {
                Text = "🔍  Search", FontSize = 11, Foreground = mutedFg,
                VerticalAlignment = VerticalAlignment.Center, IsHitTestVisible = false,
                Margin = new Thickness(1, 0, 0, 0),
            };
            var statusCount = new TextBlock
            {
                FontSize = 10.5, Foreground = mutedFg,
                VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(8, 0, 0, 0),
            };
            var searchInner = new Grid { VerticalAlignment = VerticalAlignment.Center };
            searchInner.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            searchInner.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            Grid.SetColumn(statusSearch, 0);      searchInner.Children.Add(statusSearch);
            Grid.SetColumn(statusPlaceholder, 0); searchInner.Children.Add(statusPlaceholder);
            Grid.SetColumn(statusCount, 1);       searchInner.Children.Add(statusCount);
            var searchBorder = new Border
            {
                CornerRadius = new CornerRadius(8), BorderBrush = borderClr,
                BorderThickness = new Thickness(1), Padding = new Thickness(9, 0, 9, 0),
                Width = 230, Height = 26, Margin = new Thickness(0, 0, 5, 0), Child = searchInner,
            };
            searchBorder.SetResourceReference(Border.BackgroundProperty, "InputBgBrush");

            var statusFind = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = HorizontalAlignment.Right,
                VerticalAlignment   = VerticalAlignment.Top,
                // Lives in the TITLE row, clear of the tab strip it used to overlap; the
                // right margin leaves room for the close X.
                Margin = new Thickness(0, 0, 40, 0),
            };
            statusFind.Children.Add(btnStatusPrev);
            statusFind.Children.Add(searchBorder);
            statusFind.Children.Add(btnStatusNext);

            // ── Search model: the match list plus a position, on the ACTIVE tab ─
            var statusMatches = new List<int>();
            int statusPos = -1;
            ListView ActiveList() => tabs.SelectedItem == tApps    ? lvApps
                                   : tabs.SelectedItem == tMissed  ? lvMissed
                                   : tabs.SelectedItem == tUpdates ? lvUpdates
                                   : lvStatus;
            List<MissedRow> ActiveRows() => ActiveList().ItemsSource as List<MissedRow> ?? new List<MissedRow>();
            void ApplyStatusHighlights()
            {
                var rows = ActiveRows();
                for (int i = 0; i < rows.Count; i++)
                {
                    int m = statusMatches.IndexOf(i);
                    rows[i].HighlightState = m < 0 ? "" : (m == statusPos ? "current" : "match");
                }
                string q = (statusSearch.Text ?? "").Trim();
                statusCount.Text = q.Length == 0 ? ""
                    : statusMatches.Count == 0 ? "0/0"
                    : $"{statusPos + 1}/{statusMatches.Count}";
            }
            void RecomputeStatusSearch()
            {
                statusMatches.Clear();
                statusPos = -1;
                var rows = ActiveRows();
                string q = (statusSearch.Text ?? "").Trim();
                if (q.Length > 0)
                    for (int i = 0; i < rows.Count; i++)
                    {
                        var m = rows[i];
                        string hay = m.Vendor + " " + m.AppName + " " + m.ExistingVersion + " " +
                                     m.NewVersion + " " + m.Schedule + " " + m.ExistingSchedule + " " +
                                     m.NewSchedule + " " + m.Extra;
                        if (hay.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0) statusMatches.Add(i);
                    }
                if (statusMatches.Count > 0) statusPos = 0;
                ApplyStatusHighlights();
                if (statusPos >= 0) ActiveList().ScrollIntoView(rows[statusMatches[statusPos]]);
            }
            // The end-of-results ask, in the house dialog style (see Create Package's own
            // search dialog): dark header strip with icon, title and close X, a bold
            // "Status" label beside a rounded message box, the big accent "?", and wide
            // ✔ Yes / ✖ No buttons with Yes carrying the accent.
            bool AskSearchWrap(string message)
            {
                // Resolved VALUES, not SetResourceReference: the theme dictionaries live
                // below Application scope, so a brand-new Window cannot resolve the keys
                // by reference - which rendered the header white-on-white (invisible) and
                // left the fills blank. Res() resolves from the page, where the keys exist.
                var accent  = Res("AccentBrush",   new SolidColorBrush(Color.FromRgb(0x6C, 0x63, 0xFF)));
                var cardBg  = Res("CardBgBrush",   Brushes.White);
                var inputBg = Res("InputBgBrush",  new SolidColorBrush(Color.FromRgb(0xF2, 0xF3, 0xF7)));
                // FIXED dark slate, deliberately NOT a theme key. NavBarBgBrush is light in
                // the Light theme, so the white title text painted white-on-white and the
                // whole strip read as missing. The house dialogs' bar is dark in BOTH
                // themes; matching that is the point.
                var headBg  = new SolidColorBrush(Color.FromRgb(0x38, 0x3D, 0x4A));
                var dlg = new Window
                {
                    Owner = win, WindowStartupLocation = WindowStartupLocation.CenterOwner,
                    WindowStyle = WindowStyle.None, AllowsTransparency = true,
                    Background = Brushes.Transparent, SizeToContent = SizeToContent.Height,
                    Width = 470, ShowInTaskbar = false, ResizeMode = ResizeMode.NoResize,
                };
                bool yes = false;

                var outer = new Border
                {
                    CornerRadius = new CornerRadius(10), BorderThickness = new Thickness(1),
                    BorderBrush = borderClr, Background = cardBg,
                };
                var stack = new StackPanel();

                // Header strip: icon + "Downloads - Search" left, close X right; draggable.
                var head = new Border
                {
                    CornerRadius = new CornerRadius(10, 10, 0, 0), Padding = new Thickness(14, 9, 12, 9),
                    Background = headBg,
                };
                var headRow = new DockPanel();
                var headClose = new TextBlock
                {
                    Text = "✕", FontSize = 13, Foreground = Brushes.White,
                    VerticalAlignment = VerticalAlignment.Center, Cursor = System.Windows.Input.Cursors.Hand,
                    Margin = new Thickness(10, 0, 0, 0),
                };
                headClose.MouseLeftButtonUp += (_, _) => dlg.Close();
                DockPanel.SetDock(headClose, Dock.Right);
                headRow.Children.Add(headClose);
                headRow.Children.Add(new TextBlock
                {
                    Text = "🔍  Downloads - Search", FontSize = 12.5, FontWeight = FontWeights.SemiBold,
                    Foreground = Brushes.White, VerticalAlignment = VerticalAlignment.Center,
                });
                head.Child = headRow;
                head.MouseLeftButtonDown += (_, e) => { if (e.ChangedButton == System.Windows.Input.MouseButton.Left) dlg.DragMove(); };
                stack.Children.Add(head);

                // Body: bold "Status" label beside the rounded message box.
                var body = new Grid { Margin = new Thickness(16, 16, 16, 4) };
                body.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                body.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                var statusLbl = new TextBlock
                {
                    Text = "Status", FontSize = 12.5, FontWeight = FontWeights.Bold, Foreground = valFg,
                    VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 14, 0),
                };
                Grid.SetColumn(statusLbl, 0); body.Children.Add(statusLbl);
                var msgBox = new Border
                {
                    CornerRadius = new CornerRadius(8), BorderBrush = borderClr,
                    BorderThickness = new Thickness(1), Padding = new Thickness(12, 9, 12, 9),
                    Background = inputBg,
                };
                msgBox.Child = new TextBlock
                {
                    Text = message, FontSize = 12, Foreground = valFg, TextWrapping = TextWrapping.Wrap,
                };
                Grid.SetColumn(msgBox, 1); body.Children.Add(msgBox);
                stack.Children.Add(body);

                // Footer: big accent "?" left, wide ✔ Yes / ✖ No right; Yes is the primary.
                var foot = new DockPanel { Margin = new Thickness(16, 14, 16, 16) };
                var qm = new TextBlock
                {
                    Text = "?", FontSize = 30, FontWeight = FontWeights.Bold, Foreground = accent,
                    VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(4, 0, 0, 0),
                };
                DockPanel.SetDock(qm, Dock.Left);
                foot.Children.Add(qm);
                Button MkDlgBtn(string label, bool primary)
                {
                    var b = new Button
                    {
                        Content = label, Width = 132, Height = 34, FontSize = 12.5,
                        Foreground = valFg, Template = RoundButtonTemplate(),
                        BorderBrush = primary ? accent : borderClr,
                        BorderThickness = new Thickness(primary ? 1.5 : 1),
                        Margin = new Thickness(0, 0, primary ? 10 : 0, 0),
                    };
                    b.Background = primary
                        ? new SolidColorBrush(Color.FromArgb(0x24, 0x6C, 0x63, 0xFF))
                        : inputBg;
                    return b;
                }
                var bYes = MkDlgBtn("✔  Yes", primary: true);
                var bNo  = MkDlgBtn("✖  No",  primary: false);
                bYes.Click += (_, _) => { yes = true; dlg.Close(); };
                bNo.Click  += (_, _) => dlg.Close();
                var btnRow = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
                btnRow.Children.Add(bYes); btnRow.Children.Add(bNo);
                foot.Children.Add(btnRow);
                stack.Children.Add(foot);

                outer.Child = stack; dlg.Content = outer;
                dlg.ShowDialog();
                return yes;
            }
            void StepStatusSearch(int dir)
            {
                if (statusMatches.Count == 0) return;
                int next = statusPos + dir;
                if (next >= statusMatches.Count)
                {
                    if (!AskSearchWrap("Search completed. Do you want to search again?")) return;
                    next = 0;
                }
                else if (next < 0)
                {
                    if (!AskSearchWrap("Reached the first result. Continue from the end?")) return;
                    next = statusMatches.Count - 1;
                }
                statusPos = next;
                ApplyStatusHighlights();
                ActiveList().ScrollIntoView(ActiveRows()[statusMatches[statusPos]]);
            }
            btnStatusNext.Click += (_, _) => StepStatusSearch(+1);
            btnStatusPrev.Click += (_, _) => StepStatusSearch(-1);
            statusSearch.KeyDown += (_, e) => { if (e.Key == System.Windows.Input.Key.Enter) StepStatusSearch(+1); };
            statusSearch.TextChanged += (_, _) =>
            {
                statusPlaceholder.Visibility = string.IsNullOrEmpty(statusSearch.Text)
                    ? Visibility.Visible : Visibility.Collapsed;
                // One inherited assignment per list re-renders every visible cell's runs.
                string q = (statusSearch.Text ?? "").Trim();
                HighlightTextBlock.SetSearchQuery(lvMissed,  q);
                HighlightTextBlock.SetSearchQuery(lvUpdates, q);
                HighlightTextBlock.SetSearchQuery(lvStatus,  q);
                HighlightTextBlock.SetSearchQuery(lvApps,    q);
                RecomputeStatusSearch();
            };

            // Sorting is wired HERE, after the tables, the tabs AND the search state all
            // exist: the click lambda transitively captures every one of them (SortByColumn
            // → RecomputeStatusSearch → ActiveList + the match model), and C# requires each
            // captured variable to be definitely assigned where the delegate is created.
            // Wiring inside MakeTable - or even beside the tab construction - creates the
            // delegate before parts of that set exist: the nine CS0165s' worth of variables.
            void AttachSort(ListView lv) =>
                lv.AddHandler(System.Windows.Controls.Primitives.ButtonBase.ClickEvent,
                    new RoutedEventHandler((s, e) =>
                    {
                        if (e.OriginalSource is GridViewColumnHeader h && h.Column != null
                            && colPath.ContainsKey(h.Column))
                            SortByColumn(lv, h.Column);
                    }));
            AttachSort(lvMissed);
            AttachSort(lvStatus);
            AttachSort(lvUpdates);
            AttachSort(lvApps);

            Grid.SetRow(tabs, 1); g.Children.Add(tabs);
            // In the title row, right side, beside the close X - up out of the tab strip so
            // it no longer sits on the list's border, and available on every tab.
            Grid.SetRow(statusFind, 0); g.Children.Add(statusFind);

            var lastChecked = new TextBlock
            {
                FontSize = 10, FontStyle = FontStyles.Italic, Foreground = lblFg,
                VerticalAlignment = VerticalAlignment.Center,
            };

            void SyncNote()
            {
                // The find bar serves every tab; switching retargets it at the new list, so
                // the count and the orange current-match always describe what is on screen.
                RecomputeStatusSearch();
                if (tabs.SelectedItem == tApps)
                    note.Text = "Every application in the catalog, added via Add App. Double-click a row to open it.";
                else if (tabs.SelectedItem == tStatus)
                    note.Text = "Every scheduled auto download this machine has run, newest first, with its outcome. "
                              + "Double-click a row to open the app.";
                else if (tabs.SelectedItem == tUpdates)
                    note.Text = "Apps with a newer version to download manually. Apps waiting on a missed auto schedule "
                              + "are listed on the Missed Auto Schedules tab instead, not here. Double-click a row to open it.";
                else
                    note.Text = "Nothing was downloaded - SwiftPack was not running at the scheduled time. Download manually if "
                              + "required, or leave it and the next scheduled run will pick it up.";
            }

            // First open only. The landing rule used to lean on tMissed being FIRST in the strip:
            // the TabControl auto-selects index 0, so "there are missed rows" just meant "leave it
            // alone". Updates Available is first now, so the first open has to say it outright.
            bool firstOpen = true;

            void Rebuild()
            {
                // A rebuild puts every list back in its default order; drop any user sort
                // so the ▲▼ arrows never lie about what is on screen.
                sortState.Clear();
                foreach (var kv in colPath) kv.Key.Header = kv.Value.Header;

                var (missed, updates) = BuildUpdateLists(DateTime.Now);
                lvMissed.ItemsSource  = missed;
                lvUpdates.ItemsSource = updates;
                tMissed.Header  = $"Missed Auto Schedules ({missed.Count})";
                tUpdates.Header = $"Updates Available ({updates.Count})";

                // Applications tab: the full catalog, mapped into MissedRow so the shared search,
                // sort and double-click-to-open all apply. "Source" is the identifier the API Type uses.
                static string SrcId(DownloadSourceEntry a)
                {
                    string t = (a.ApiType ?? "").Trim();
                    if (t.Equals("winget", StringComparison.OrdinalIgnoreCase))     return a.WingetPackageId ?? "";
                    if (t.Equals("github", StringComparison.OrdinalIgnoreCase))     return a.GitHubRepo ?? "";
                    if (t.Equals("Vendor API", StringComparison.OrdinalIgnoreCase)) return a.VendorApiId ?? "";
                    return a.DownloadPageUrl ?? "";
                }
                var appRows = _allApps
                    .OrderBy(a => a.SourceAppVendor, StringComparer.OrdinalIgnoreCase)
                    .ThenBy(a => a.SourceAppName,   StringComparer.OrdinalIgnoreCase)
                    .Select(a => new MissedRow
                    {
                        App              = a,
                        Vendor           = a.SourceAppVendor,
                        AppName          = a.SourceAppName,
                        ExistingVersion  = a.SourceAppVersion,
                        Schedule         = a.ApiType,
                        ExistingSchedule = a.Category,
                        NewSchedule      = SrcId(a),
                    })
                    .ToList();
                lvApps.ItemsSource = appRows;
                tApps.Header = $"Applications ({appRows.Count})";

                // The status tab reuses MissedRow so MakeTable's bindings and double-click
                // just work; App is resolved by name so the jump lands on the right card.
                // One row per app - the newest - because the store is newest-first and a
                // per-app history reads as duplicates to anyone scanning for current state.
                // Ordered EXPLICITLY by Completed At, newest first: the store's insertion
                // order says the same thing until AmendLatestScheduleOutcome rewrites a
                // row's timestamp in place, at which point only the parse-and-sort keeps
                // the "latest run on top" promise true.
                DateTime ParseAt(string s) => DateTime.TryParseExact(s, "ddd dd-MM-yyyy HH:mm",
                    System.Globalization.CultureInfo.InvariantCulture,
                    System.Globalization.DateTimeStyles.None, out var d) ? d : DateTime.MinValue;
                var outcomes = LoadScheduleOutcomes()
                    .GroupBy(o => (o.Vendor + "|" + o.AppName).ToLowerInvariant())
                    .Select(gr => gr.First())
                    // Show only apps still in the catalog. The history log on disk is left intact -
                    // outcomes for removed apps are just not shown (and reappear if the app is re-added).
                    .Where(o => _allApps.Any(a =>
                        string.Equals(a.SourceAppVendor, o.Vendor,  StringComparison.OrdinalIgnoreCase) &&
                        string.Equals(a.SourceAppName,   o.AppName, StringComparison.OrdinalIgnoreCase)))
                    .OrderByDescending(o => ParseAt(o.At))
                    .ToList();
                lvStatus.ItemsSource = outcomes.Select(o =>
                {
                    var appRef = _allApps.FirstOrDefault(a =>
                        string.Equals(a.SourceAppVendor, o.Vendor,  StringComparison.OrdinalIgnoreCase) &&
                        string.Equals(a.SourceAppName,   o.AppName, StringComparison.OrdinalIgnoreCase));
                    DateTime? nextRun = appRef != null ? NextScheduledOccurrence(appRef, DateTime.Now) : null;
                    return new MissedRow
                    {
                        App              = appRef,
                        Vendor           = o.Vendor,
                        AppName          = o.AppName,
                        ExistingVersion  = o.ExistingVersion,
                        NewVersion       = o.NewVersion,
                        Schedule         = o.Schedule,
                        ExistingSchedule = o.Status,
                        NewSchedule      = o.At,
                        Extra            = nextRun.HasValue ? nextRun.Value.ToString("ddd dd-MM-yyyy HH:mm") : "-",
                    };
                }).ToList();
                tStatus.Header = $"Auto Schedules Status ({outcomes.Count})";
                // The list was just replaced, so the match positions belong to the old one.
                RecomputeStatusSearch();

                DateTime? last = LastVersionCheck();
                lastChecked.Text = last.HasValue
                    ? $"Last checked  {last.Value:ddd dd-MM-yyyy HH:mm}"
                    : "Never checked";

                // Land on whichever tab actually has something in it.
                if (firstOpen || missed.Count == 0)
                    tabs.SelectedItem = missed.Count > 0 ? tMissed : tUpdates;
                firstOpen = false;
                SyncNote();
            }

            tabs.SelectionChanged += (_, _) => SyncNote();

            // ── Footer: last-checked on the left, actions on the right ─────────────────────────
            var footer = new Grid { Margin = new Thickness(0, 12, 0, 0) };
            footer.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            footer.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            Grid.SetColumn(lastChecked, 0);
            footer.Children.Add(lastChecked);

            var bar = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };

            var check = new Button
            {
                Content = "🔄  Check now", FontSize = 11, Height = 28, Width = 118,
                Margin = new Thickness(0, 0, 8, 0), Cursor = System.Windows.Input.Cursors.Hand,
                ToolTip = "Re-pull the winget catalog and re-query every vendor, ignoring the cache",
            };
            if (TryFindResource("SecondaryButtonStyle") is Style sb) check.Style = sb;
            check.Click += async (_, _) =>
            {
                check.IsEnabled = false;
                check.Content   = "🔄  Checking…";

                // Progress arrives from the probe's worker threads through BeginInvoke, so it is
                // QUEUED - and a post made during the scan can still be sitting in the dispatcher
                // queue when the scan itself is over. It then runs after the label has been put back
                // and writes "Scanning 50/50" over it, which is why the button sat there looking busy
                // while being perfectly enabled and clickable. This flag makes a late post a no-op.
                bool scanning = true;

                try
                {
                    try { await CheckForUpdatesNowAsync(); }
                    catch (Exception ex) { LogWinget($"[Updates] check failed: {ex.Message}"); }
                    Rebuild();

                    // Short enough to fit the button. "Scanning 50/50 new packages" was clipped to
                    // "Scanning 50/50 n" at 118px, which read like a crash rather than a count.
                    //
                    // The New Apps TAB is gone, but this refresh is the backend behind it and
                    // stays: it keeps new_apps.json, the GitHub catalog and the non-installer
                    // list growing on every check. Only the on-screen hand-off was removed.
                    _ = await RefreshNewAppsAsync((d, t) =>
                        check.Dispatcher.BeginInvoke(new Action(() =>
                            { if (scanning && t > 0) check.Content = $"Scanning {d}/{t}"; })));
                }
                catch (Exception ex) { LogWinget($"[Updates] check now failed: {ex.Message}"); }
                finally
                {
                    // In a finally, so the button comes back even when something above throws. It
                    // was the last statement of the handler before, which meant any exception left
                    // the dialog with a dead, permanently disabled Check now.
                    scanning        = false;
                    check.Content   = "🔄  Check now";
                    check.IsEnabled = true;
                }
            };
            bar.Children.Add(check);

            var ok = new Button
            {
                Content = "\u2714  OK", FontSize = 11, Height = 28, Width = 92,
                Cursor = System.Windows.Input.Cursors.Hand,
            };
            if (TryFindResource("ActionBtnStyle") is Style ab) ok.Style = ab;
            ok.Click += (_, _) => win.Close();
            bar.Children.Add(ok);

            Grid.SetColumn(bar, 1);
            footer.Children.Add(bar);
            Grid.SetRow(footer, 3); g.Children.Add(footer);

            Rebuild();
            win.ShowDialog();
        }

        /// <summary>
        /// The row template behind the Downloads tables. Same shape as the stock GridView row - one
        /// Border carrying the highlight with a GridViewRowPresenter inside it, so the cells still
        /// line up with the headers - but the hover and selection colours are ours, so the row text
        /// stays readable instead of disappearing into a light band on the dark theme. The presenter
        /// picks its columns up from the ListView's GridView by property inheritance, exactly as the
        /// stock template does; only the row content is bound explicitly.
        /// </summary>
        private static ControlTemplate DownloadsRowTemplate(Brush hoverBg, Brush selBg, Brush selBorder)
        {
            System.Windows.Data.Binding FromParent(string prop) =>
                new System.Windows.Data.Binding(prop)
                {
                    RelativeSource = new System.Windows.Data.RelativeSource(
                        System.Windows.Data.RelativeSourceMode.TemplatedParent),
                };

            var tpl = new ControlTemplate(typeof(ListViewItem));

            var bd = new FrameworkElementFactory(typeof(Border), "RowBd");
            bd.SetBinding(Border.BackgroundProperty,      FromParent(nameof(Control.Background)));
            bd.SetBinding(Border.BorderBrushProperty,     FromParent(nameof(Control.BorderBrush)));
            bd.SetBinding(Border.BorderThicknessProperty, FromParent(nameof(Control.BorderThickness)));
            bd.SetBinding(Border.PaddingProperty,         FromParent(nameof(Control.Padding)));
            bd.SetValue(UIElement.SnapsToDevicePixelsProperty, true);

            var rp = new FrameworkElementFactory(typeof(GridViewRowPresenter));
            rp.SetBinding(GridViewRowPresenter.ContentProperty, FromParent(nameof(ContentControl.Content)));
            rp.SetBinding(FrameworkElement.VerticalAlignmentProperty,
                FromParent(nameof(Control.VerticalContentAlignment)));
            rp.SetValue(UIElement.SnapsToDevicePixelsProperty, true);
            bd.AppendChild(rp);
            tpl.VisualTree = bd;

            // Selection is added after hover so a selected row keeps its colour while the pointer
            // is over it, rather than dropping back to the lighter hover tint.
            var hov = new Trigger { Property = UIElement.IsMouseOverProperty, Value = true };
            hov.Setters.Add(new Setter(Border.BackgroundProperty, hoverBg, "RowBd"));
            tpl.Triggers.Add(hov);

            var sel = new Trigger { Property = ListBoxItem.IsSelectedProperty, Value = true };
            sel.Setters.Add(new Setter(Border.BackgroundProperty,  selBg,     "RowBd"));
            sel.Setters.Add(new Setter(Border.BorderBrushProperty, selBorder, "RowBd"));
            tpl.Triggers.Add(sel);

            return tpl;
        }

        private static bool IsScheduledDownloadDue(DownloadSourceEntry app, DateTime now)
        {
            // Parse scheduled time — support both HH:MM and HH-MM
            string timeStr = (app.DownloadScheduleTime ?? "").Trim();
            timeStr = timeStr.Replace('-', ':');
            // Same parser the report uses - hour 24 means end of day and is clamped to 23:59.
            bool hasValidTime = TryParseScheduleTime(timeStr, out int h, out int m);
            if (!hasValidTime) { h = 0; m = 0; }
            if (!app.DownloadFrequency.Trim().Equals("Hourly", StringComparison.OrdinalIgnoreCase) && !hasValidTime) return false;

            var scheduledTime = new TimeSpan(h, m, 0);
            var currentTime   = now.TimeOfDay;
            string freq       = app.DownloadFrequency.Trim();

            // Exact date: DD-MM-YYYY
            if (freq.Length == 10 && freq[2] == '-' && freq[5] == '-')
            {
                if (DateTime.TryParseExact(freq, "dd-MM-yyyy",
                    System.Globalization.CultureInfo.InvariantCulture,
                    System.Globalization.DateTimeStyles.None, out DateTime exactDate))
                {
                    // Due if today is the exact date and time has passed
                    return now.Date == exactDate.Date && currentTime >= scheduledTime;
                }
                return false;
            }

            // Due if scheduled time has passed today/this period (catches missed schedules)
            bool timeHasPassed = currentTime >= scheduledTime;

            // Parse scheduled day of week (for weekly/fortnightly/every)
            DayOfWeek? scheduledDay = null;
            if (!string.IsNullOrWhiteSpace(app.DownloadScheduleDays) &&
                Enum.TryParse<DayOfWeek>(app.DownloadScheduleDays, true, out DayOfWeek parsedDay))
                scheduledDay = parsedDay;

            // Parse scheduled date of month (for monthly/quarterly/halfyearly/yearly)
            int scheduledDate = 1;
            if (!string.IsNullOrWhiteSpace(app.DownloadScheduleDate) &&
                int.TryParse(app.DownloadScheduleDate, System.Globalization.NumberStyles.Integer, null, out int pd) && pd >= 1 && pd <= 31)
                scheduledDate = pd;

            // Parse scheduled month (for quarterly/halfyearly/yearly)
            int scheduledMonth = 1;
            if (!string.IsNullOrWhiteSpace(app.DownloadScheduleMonth) &&
                DateTime.TryParseExact(app.DownloadScheduleMonth, "MMMM",
                    System.Globalization.CultureInfo.InvariantCulture,
                    System.Globalization.DateTimeStyles.None, out DateTime pm))
                scheduledMonth = pm.Month;

            // Parse occurrence (First=1..Fourth=4) for "Every" frequency
            int occurrence = app.DownloadOccurrence?.ToLowerInvariant() switch
            {
                "first"  => 1, "second" => 2, "third" => 3, "fourth" => 4, _ => 2
            };

            // ── Start of the series ─────────────────────────────────────────────────────────
            // Bound to the same rule that decides whether the editors show a start date at all, so a
            // frequency without one can never be stopped by a stale month left in its JSON.
            //
            // Null when no year is stored - an app saved before the field existed - and then nothing
            // below changes. With a year, "starting from 18 February 2027" is a real moment and the
            // series simply does not exist before it.
            DateTime? start = ScheduleFieldsFor(freq).Month ? ScheduleStart(app) : null;
            if (start != null && now < start.Value) return false;

            // The scheduled day, pulled back to the last day of the month being tested. An app set
            // to the 31st still runs in February and April, and 29 February runs on the 28th in a
            // common year, instead of the month being skipped outright.
            int dueDay = ScheduleDayIn(scheduledDate, now.Year, now.Month);

            // For Hourly: due whenever a slot is open, which is the whole slot.
            //
            // The window used to be `now.Hour % intervalHours == 0 && now.Minute < 2`. Two problems
            // in one line. The modulo phases the interval from midnight, so the start date the
            // editors show had no effect on when anything ran, and an interval that does not divide
            // 24 left a short final gap every night. And a two-minute window is lost outright if
            // AutoFlowStatus.FlowRunning happens to be held by another app's chain when it opens,
            // which costs the whole interval.
            //
            // Staying due for the entire slot is safe because GetSchedulePeriodKey resolves both
            // moments to that same slot, so the run still happens exactly once per slot and the
            // 10-second timer simply picks it up as soon as the flow lock clears.
            if (freq.Equals("hourly", StringComparison.OrdinalIgnoreCase))
                return HourlySlotFor(app, now) != null;

            // ── Every 2 weeks ───────────────────────────────────────────────────────────────
            // Anchored to DownloadScheduleDate (a full date for this frequency), NOT to January 1st.
            //
            // The old test was:  (now.DayOfYear / 7) % 2 == 0
            // i.e. a parity counted from Jan 1. Which of the two possible Mondays the series landed
            // on was therefore an accident of the calendar - the user had no way to pick it - and the
            // parity RESETS every 1 January, so across the year boundary the series either fires
            // twice 7 days apart or skips to a 21-day gap. That is the "not working properly".
            //
            // With an anchor it is exact: run on the scheduled weekday whenever a whole number of
            // fortnights has elapsed since the first run.
            if (IsEvery2Weeks(freq))
            {
                // ScheduledDayOf, not scheduledDay: an empty DownloadScheduleDays must mean the SAME
                // day the UI is showing (Monday), not "never run".
                //
                // The Schedule Days combo sets SelectedIndex BEFORE its SelectionChanged handler is
                // wired, so the default it displays is never written to the JSON. An app the user did
                // not explicitly set a day on therefore shows "On Monday" but stores "" - and the old
                // `if (!scheduledDay.HasValue) return false;` then bailed before the anchor was even
                // looked at. That is why an app with no day set never downloaded while a hand-dated one did.
                DayOfWeek day = ScheduledDayOf(app);
                if (now.DayOfWeek != day || !timeHasPassed) return false;

                DateTime? anchor = FortnightAnchor(app, now, day);
                if (anchor == null) return false;

                int weeks = WeeksSinceAnchor(anchor.Value, now);
                return weeks >= 0 && weeks % 2 == 0;
            }

            return freq.ToLowerInvariant() switch
            {
                "daily"       => timeHasPassed,
                "weekly"      => scheduledDay.HasValue && now.DayOfWeek == scheduledDay.Value && timeHasPassed,
                "monthly"     => now.Day == dueDay && timeHasPassed,
                "quarterly"   => ((now.Month - scheduledMonth + 12) % 3 == 0) && now.Day == dueDay && timeHasPassed,
                "halfyearly"  => (now.Month == scheduledMonth || now.Month == ((scheduledMonth - 1 + 6) % 12) + 1) &&
                                 now.Day == dueDay && timeHasPassed,
                "yearly"      => now.Month == scheduledMonth && now.Day == dueDay && timeHasPassed,
                // "Every" is the Nth <weekday> of every month, and the schedule start is where that
                // series begins: "Fourth Friday, starting from July 2026" must not fire in June 2026.
                // From the start onwards it runs every month for good, including the January after,
                // which is what a start date means.
                //
                // An app saved before the year field existed has no year to compare against, so the
                // start can only be read as a position in the calendar year: eligible months run
                // from the start month to December, and it picks up again at the start month the
                // following year. A blank or January start parses as month 1, so such an app keeps
                // firing in all twelve months exactly as it always has.
                "every"       => (start != null || now.Month >= scheduledMonth) &&
                                 IsNthWeekdayOfMonth(now, scheduledDay ?? DayOfWeek.Monday, occurrence) && timeHasPassed,
                _             => false,
            };
        }

        // ── Background version fetch — populates _liveVersionCache for ALL apps on load ──
        // Runs silently with a small delay between requests to avoid rate-limiting.
        // Once each version is fetched, vendor and card badges update immediately.
        /// <param name="force">
        /// True only for the manual Refresh button, where the user has explicitly asked for fresh
        /// data. Everything else (page load, the hourly timer) goes through the cache.
        /// </param>
        private async Task FetchAllVersionsInBackgroundAsync(bool force = false)
        {
            LoadInfoCache();

            // Refresh means "go and look again". Re-pull the winget catalog too, ONCE, before the
            // loop - otherwise every winget app re-reads the same local index and reports the same
            // version, and Refresh silently does nothing for them for up to 12 hours.
            //
            // Once per Refresh, not once per app: one 7MB download covers all of them, however many
            // there are.
            if (force)
            {
                try { await WingetCatalog.EnsureAsync(_http, LogWinget, force: true).ConfigureAwait(true); }
                catch (Exception ex) { LogWinget($"[WingetCatalog] forced refresh failed: {ex.Message}"); }
            }

            // Only fetch apps that have a live API (not "URL") and have been downloaded before
            // (SourceAppVersion set) so we know whether there's a meaningful update to show.
            // Apps with no SourceAppVersion will show badges only after first download.
            // Direct URL apps are also version-checkable when the installer URL contains a
            // version in its filename/path (for example: SmekalFolderCompare-Setup-1.0.0.exe).
            // Previously ApiType=none was excluded from this sweep, so the UI could show a
            // cached NEW badge while the scheduler only saw SourceAppVersion and concluded that
            // remote == local. Include versioned direct URLs; this check is local string parsing
            // and does not consume any API quota.
            var appsToFetch = _allApps
                .Where(a => a.ApiType != "URL" || IsVersionedDirectFileUrl(a.DownloadPageUrl))
                .ToList();

            foreach (var app in appsToFetch)
            {
                // Skip if already cached from a user click this session
                if (_liveVersionCache.ContainsKey(app.SourceAppName)) continue;

                // ── Serve from the persistent cache while it is fresh ──────────────────────────
                // This is the line that actually stops the quota being burned. This sweep called the
                // Fetch*Async methods DIRECTLY, bypassing _infoCache entirely - so the hourly timer
                // and every page load re-fetched every app from the network, forever. With ~15 apps
                // that is 15 of GitHub's 60/hour gone every hour before the user touches anything.
                //
                // Now: fresh cache (6h) -> no network call at all. Only the manual Refresh forces it.
                string ck = InfoKey(app);
                if (!force
                    && _infoCache.TryGetValue(ck, out var cachedHit)
                    && DateTime.UtcNow - cachedHit.At < _infoCacheTtl
                    && cachedHit.Info.Links.Count > 0)
                {
                    if (!string.IsNullOrWhiteSpace(cachedHit.Info.Version))
                        _liveVersionCache[app.SourceAppName] = cachedHit.Info.Version;
                    continue;   // repainted once at the end - see the final render below
                }

                try
                {
                    AppDownloadInfo info = app.ApiType switch
                    {
                        "winget"       => await FetchWingetAsync(app),
                        "github"       => await FetchGitHubAsync(app),
                        "Vendor API"   => await FetchVendorApiAsync(app),
                        _              => FallbackInfo(app),
                    };

                    if (!string.IsNullOrWhiteSpace(info.Version))
                    {
                        _liveVersionCache[app.SourceAppName] = info.Version;

                        // Persist it, so the next sweep (and the next process) is a cache hit rather
                        // than another network call. Only results that actually carry links are
                        // stored - see FetchAndShowAsync.
                        if (info.Links.Count > 0)
                        {
                            _infoCache[ck] = (info, DateTime.UtcNow);
                            SaveInfoCacheDebounced();
                        }

                        // Refresh vendor + card badges on the UI thread after each fetch
                        // so badges appear progressively as versions come in
                        Dispatcher.Invoke(() =>
                        {
                            RenderVendors();
                            RenderCards();
                        });
                    }
                }
                catch { /* silently skip failed fetches - the cached entry, if any, still stands */ }

                // Small delay to avoid hammering APIs simultaneously
                await Task.Delay(300);
            }

            // Final repaint, ALWAYS.
            //
            // The per-app render above only runs on the network path. On startup nearly every app is
            // a CACHE HIT, so _liveVersionCache was filled but the badges were never redrawn - which
            // is why "New" appeared for the one app that happened to miss the cache and for nothing
            // else, and why pressing Check now (force: true, so every app takes the network path)
            // appeared to "fix" it.
            Dispatcher.Invoke(() =>
            {
                RenderVendors();
                RenderCards();
            });
        }

        // ── Per-app JSON helpers ────────────────────────────────────────────

        /// <summary>Walks up the logical/visual tree to find the AutoPackagePage that hosts
        /// this SourceDownloadPage in its FrameDownload — returns null if not hosted there.</summary>
        private AutoPackagePage? FindAncestorAutoPackagePage()
        {
            System.Windows.DependencyObject? current = this;
            while (current != null)
            {
                if (current is AutoPackagePage ap) return ap;
                current = System.Windows.Media.VisualTreeHelper.GetParent(current)
                          ?? System.Windows.LogicalTreeHelper.GetParent(current);
            }
            return null;
        }

        /// <summary>
        /// Returns the path for the per-app JSON file inside PackageTemplateFolder.
        /// e.g. C:\Templates\Smekal_FileCompare.json
        /// Returns null if PackageTemplateFolder is not set.
        /// </summary>
        private static string? GetAppJsonPath(DownloadSourceEntry app)
        {
            if (string.IsNullOrWhiteSpace(app.PackageTemplateFolder)) return null;
            string fileName = $"{app.SourceAppVendor}_{app.SourceAppName}.json";
            return Path.Combine(app.PackageTemplateFolder, fileName);
        }

        /// <summary>
        /// DIAGNOSTIC ONLY. Reads SourceAppVersion straight back out of the per-app JSON, so the
        /// scheduler log can report what actually reached disk instead of what was assigned in
        /// memory.
        ///
        /// Returns a marker rather than throwing, because SaveAppJson gives up silently in three
        /// separate places: a blank PackageTemplateFolder (NO-PATH), a folder that does not exist
        /// (the file never appears, so NO-FILE), and any exception inside the write. Each marker
        /// names which one happened.
        /// </summary>
        private static string SourceAppVersionOnDisk(DownloadSourceEntry app)
        {
            try
            {
                string? p = GetAppJsonPath(app);
                if (p == null) return "NO-PATH";
                if (!File.Exists(p)) return "NO-FILE";

                System.Text.Json.Nodes.JsonNode? node;
                using (var fs = File.OpenRead(p))
                    node = System.Text.Json.Nodes.JsonNode.Parse(fs);

                string? v = node?["SourceAppVersion"]?.GetValue<string>();
                return string.IsNullOrWhiteSpace(v) ? "EMPTY" : v;
            }
            catch (System.Exception ex) { return "ERR:" + ex.GetType().Name; }
        }

        /// <summary>
        /// Saves the app entry as an individual JSON file in its PackageTemplateFolder.
        /// </summary>
        private static void SaveAppJson(DownloadSourceEntry app)
        {
            try
            {
                var path = GetAppJsonPath(app);
                if (path == null) return;
                // Only write if folder already exists — never create it (Add App does that)
                string? dir = Path.GetDirectoryName(path);
                if (string.IsNullOrWhiteSpace(dir) || !Directory.Exists(dir)) return;

                // Persist the detection field values exactly as they currently are in
                // `app` (whether the user typed them in the Package Information column or
                // they were auto-resolved). Previously these were blanked unless the
                // ORIGINAL file already had a value — which silently discarded values the
                // user typed when the field started empty. We now save them as-is so the
                // per-app JSON always reflects what the user sees/entered, and so the
                // Publish → Detection tab can give the JSON values first preference.

                File.WriteAllText(path, JsonSerializer.Serialize(app,
                    new JsonSerializerOptions { WriteIndented = true }));

                // Remove any stale wrongly-named JSON files in the same folder
                foreach (string stale in Directory.GetFiles(dir, "*.json"))
                    if (!stale.Equals(path, StringComparison.OrdinalIgnoreCase))
                        try { File.Delete(stale); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
        }

        /// <summary>
        /// Loads per-app JSON from PackageTemplateFolder (if it exists) and merges
        /// it into the app entry — the per-app file takes precedence over the
        /// central AutoPackage.json for fields that are non-empty in the file.
        /// </summary>
        private static void LoadAppJson(DownloadSourceEntry app)
        {
            try
            {
                var path = GetAppJsonPath(app);
                if (path == null || !File.Exists(path)) return;
                var loaded = JsonSerializer.Deserialize<DownloadSourceEntry>(
                    File.ReadAllText(path),
                    new JsonSerializerOptions { PropertyNameCaseInsensitive = true, AllowTrailingCommas = true });
                if (loaded == null) return;

                // Merge: only overwrite fields that are non-empty in the per-app file
                if (!string.IsNullOrWhiteSpace(loaded.AppVendor))                  app.AppVendor                  = loaded.AppVendor;
                if (!string.IsNullOrWhiteSpace(loaded.AppName))                    app.AppName                    = loaded.AppName;
                if (!string.IsNullOrWhiteSpace(loaded.Category))                   app.Category                   = loaded.Category;
                if (!string.IsNullOrWhiteSpace(loaded.ApiType))                    app.ApiType                    = loaded.ApiType;
                if (!string.IsNullOrWhiteSpace(loaded.GitHubRepo))                 app.GitHubRepo                 = loaded.GitHubRepo;
                if (!string.IsNullOrWhiteSpace(loaded.WingetPackageId))            app.WingetPackageId            = loaded.WingetPackageId;
                if (!string.IsNullOrWhiteSpace(loaded.DownloadPageUrl))            app.DownloadPageUrl            = loaded.DownloadPageUrl;
                // Written by the automatic logo fetch as well as by hand, so it has to survive a
                // restart the same way the typed fields do.
                if (!string.IsNullOrWhiteSpace(loaded.Logo))                       app.Logo                       = loaded.Logo;
                if (!string.IsNullOrWhiteSpace(loaded.SilentInstallParameterEXE))  app.SilentInstallParameterEXE  = loaded.SilentInstallParameterEXE;
                if (!string.IsNullOrWhiteSpace(loaded.SilentInstallParameterMSI))  app.SilentInstallParameterMSI  = loaded.SilentInstallParameterMSI;
                if (!string.IsNullOrWhiteSpace(loaded.SilentUninstallParameterEXE))app.SilentUninstallParameterEXE= loaded.SilentUninstallParameterEXE;
                if (!string.IsNullOrWhiteSpace(loaded.SilentUninstallParameterMSI))app.SilentUninstallParameterMSI= loaded.SilentUninstallParameterMSI;
                if (!string.IsNullOrWhiteSpace(loaded.CloseApps))                  app.CloseApps                  = loaded.CloseApps;
                if (!string.IsNullOrWhiteSpace(loaded.AutoDownloadSource))         app.AutoDownloadSource         = loaded.AutoDownloadSource;
                if (!string.IsNullOrWhiteSpace(loaded.DownloadPreference))         app.DownloadPreference         = loaded.DownloadPreference;
                if (!string.IsNullOrWhiteSpace(loaded.LockDownloadPreference))     app.LockDownloadPreference     = loaded.LockDownloadPreference;
                if (!string.IsNullOrWhiteSpace(loaded.DownloadFrequency))          app.DownloadFrequency          = loaded.DownloadFrequency;
                // Always overwrite schedule fields (empty string = clear previous value)
                app.DownloadOccurrence      = loaded.DownloadOccurrence     ?? "";
                app.DownloadScheduleDays    = loaded.DownloadScheduleDays   ?? "";
                app.DownloadScheduleDate    = loaded.DownloadScheduleDate   ?? "";
                app.DownloadScheduleTime    = loaded.DownloadScheduleTime   ?? "";
                app.DownloadScheduleMonth   = loaded.DownloadScheduleMonth  ?? "";
                app.DownloadScheduleYear    = loaded.DownloadScheduleYear   ?? "";
                app.DownloadScheduleHour    = loaded.DownloadScheduleHour   ?? "";
                if (!string.IsNullOrWhiteSpace(loaded.InstallSourceSilently))      app.InstallSourceSilently      = loaded.InstallSourceSilently;
                if (!string.IsNullOrWhiteSpace(loaded.CreatePackage))              app.CreatePackage              = loaded.CreatePackage;
                if (!string.IsNullOrWhiteSpace(loaded.PackageTemplateFolder))      app.PackageTemplateFolder      = loaded.PackageTemplateFolder;
                // PackageInputFolder is global (AutoPackage.json) — not loaded per-app
                if (!string.IsNullOrWhiteSpace(loaded.CreateMST))                  app.CreateMST                  = loaded.CreateMST;
                if (!string.IsNullOrWhiteSpace(loaded.RemoveDesktopShortcut))      app.RemoveDesktopShortcut      = loaded.RemoveDesktopShortcut;
                if (!string.IsNullOrWhiteSpace(loaded.AddInstallName))             app.AddInstallName             = loaded.AddInstallName;
                if (!string.IsNullOrWhiteSpace(loaded.AddInstallTitle))            app.AddInstallTitle            = loaded.AddInstallTitle;
                if (!string.IsNullOrWhiteSpace(loaded.AddNoRemove))                app.AddNoRemove                = loaded.AddNoRemove;
                if (!string.IsNullOrWhiteSpace(loaded.AddNoModify))                app.AddNoModify                = loaded.AddNoModify;
                if (!string.IsNullOrWhiteSpace(loaded.AddNoRepair))                app.AddNoRepair                = loaded.AddNoRepair;
                if (!string.IsNullOrWhiteSpace(loaded.InstallPackage))             app.InstallPackage             = loaded.InstallPackage;
                if (!string.IsNullOrWhiteSpace(loaded.UninstallSourceSilently))    app.UninstallSourceSilently    = loaded.UninstallSourceSilently;
                if (!string.IsNullOrWhiteSpace(loaded.UninstallPackage))           app.UninstallPackage           = loaded.UninstallPackage;
                if (!string.IsNullOrWhiteSpace(loaded.OpenApplication))            app.OpenApplication            = loaded.OpenApplication;
                if (!string.IsNullOrWhiteSpace(loaded.UninstallPath))        app.UninstallPath        = loaded.UninstallPath;
                if (!string.IsNullOrWhiteSpace(loaded.PublishSettings))            app.PublishSettings            = loaded.PublishSettings;
                if (!string.IsNullOrWhiteSpace(loaded.PublishToIntune))            app.PublishToIntune            = loaded.PublishToIntune;
                if (!string.IsNullOrWhiteSpace(loaded.AddSupersedenceAutomatically)) app.AddSupersedenceAutomatically = loaded.AddSupersedenceAutomatically;
                // Intune assignment groups (were not merged before, so values from the
                // per-app JSON never reached the publish script).
                if (!string.IsNullOrWhiteSpace(loaded.AssignmentsAvailable))       app.AssignmentsAvailable       = loaded.AssignmentsAvailable;
                // Migration: old JSON had "PublishToIntune":"Yes" set by the "Publish settings" checkbox
                if (string.IsNullOrWhiteSpace(app.PublishSettings) &&
                    (app.PublishToIntune ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase))
                {
                    app.PublishSettings = "Yes";
                    app.PublishToIntune = "No";
                }
                if (!string.IsNullOrWhiteSpace(loaded.InstallBehaviour))           app.InstallBehaviour           = loaded.InstallBehaviour;
                if (!string.IsNullOrWhiteSpace(loaded.CreateIntunewin))            app.CreateIntunewin            = loaded.CreateIntunewin;
                if (!string.IsNullOrWhiteSpace(loaded.ShowMessageBox))             app.ShowMessageBox             = loaded.ShowMessageBox;
                if (!string.IsNullOrWhiteSpace(loaded.RulesFormat))                              app.RulesFormat                          = loaded.RulesFormat;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionTypeMSI))                       app.DetectionTypeMSI                     = loaded.DetectionTypeMSI;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionTypeFile))                      app.DetectionTypeFile                    = loaded.DetectionTypeFile;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionTypeRegistry))                  app.DetectionTypeRegistry                = loaded.DetectionTypeRegistry;
                // DetectionTypeScript no longer loaded — field removed
                if (!string.IsNullOrWhiteSpace(loaded.DetectionMsiVersionCheck))               app.DetectionMsiVersionCheck             = loaded.DetectionMsiVersionCheck;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionMsiOperator))                   app.DetectionMsiOperator                 = loaded.DetectionMsiOperator;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionMsiValue))                     app.DetectionMsiValue                    = loaded.DetectionMsiValue;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionMsiProductCode))               app.DetectionMsiProductCode              = loaded.DetectionMsiProductCode;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionFileFolderPath))                app.DetectionFileFolderPath              = loaded.DetectionFileFolderPath;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionFileFileName))                  app.DetectionFileFileName                = loaded.DetectionFileFileName;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionFileDetectionMethod))                 app.DetectionFileDetectionMethod               = loaded.DetectionFileDetectionMethod;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionFileSizeValue))                 app.DetectionFileSizeValue               = loaded.DetectionFileSizeValue;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionFileOperator))                  app.DetectionFileOperator                = loaded.DetectionFileOperator;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionFile32Bit))                     app.DetectionFile32Bit                   = loaded.DetectionFile32Bit;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionRegKeyPath))                    app.DetectionRegKeyPath                  = loaded.DetectionRegKeyPath;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionRegValueName))                  app.DetectionRegValueName                = loaded.DetectionRegValueName;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionRegDetectionMethod))                  app.DetectionRegDetectionMethod                = loaded.DetectionRegDetectionMethod;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionRegOperator))                   app.DetectionRegOperator                 = loaded.DetectionRegOperator;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionRegistryValue))                app.DetectionRegistryValue               = loaded.DetectionRegistryValue;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionReg32Bit))                      app.DetectionReg32Bit                    = loaded.DetectionReg32Bit;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionScriptFile))                    app.DetectionScriptFile                  = loaded.DetectionScriptFile;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionScriptEnforceSignatureCheck))   app.DetectionScriptEnforceSignatureCheck = loaded.DetectionScriptEnforceSignatureCheck;
                if (!string.IsNullOrWhiteSpace(loaded.DetectionScriptRunAs32Bit))              app.DetectionScriptRunAs32Bit            = loaded.DetectionScriptRunAs32Bit;
                if (!string.IsNullOrWhiteSpace(loaded.GroupName))                  app.GroupName                  = loaded.GroupName;
                if (!string.IsNullOrWhiteSpace(loaded.Description))               app.Description                = loaded.Description;
                if (!string.IsNullOrWhiteSpace(loaded.AppOwnerEmail))             app.AppOwnerEmail              = loaded.AppOwnerEmail;
                if (!string.IsNullOrWhiteSpace(loaded.SendMailToAppOwner))        app.SendMailToAppOwner         = loaded.SendMailToAppOwner;
                if (!string.IsNullOrWhiteSpace(loaded.MailSubject))               app.MailSubject                = loaded.MailSubject;
                if (!string.IsNullOrWhiteSpace(loaded.MailBody))                  app.MailBody                   = loaded.MailBody;
                if (!string.IsNullOrWhiteSpace(loaded.IntuneCategory))            app.IntuneCategory             = loaded.IntuneCategory;
                if (!string.IsNullOrWhiteSpace(loaded.Dependency1))               app.Dependency1                = loaded.Dependency1;
                if (!string.IsNullOrWhiteSpace(loaded.Dependency2))               app.Dependency2                = loaded.Dependency2;
                if (!string.IsNullOrWhiteSpace(loaded.Dependency3))               app.Dependency3                = loaded.Dependency3;
                if (!string.IsNullOrWhiteSpace(loaded.Dependency4))               app.Dependency4                = loaded.Dependency4;
                if (!string.IsNullOrWhiteSpace(loaded.AutoInstallDependency1)) app.AutoInstallDependency1 = loaded.AutoInstallDependency1;
                if (!string.IsNullOrWhiteSpace(loaded.AutoInstallDependency2)) app.AutoInstallDependency2 = loaded.AutoInstallDependency2;
                if (!string.IsNullOrWhiteSpace(loaded.AutoInstallDependency3)) app.AutoInstallDependency3 = loaded.AutoInstallDependency3;
                if (!string.IsNullOrWhiteSpace(loaded.AutoInstallDependency4)) app.AutoInstallDependency4 = loaded.AutoInstallDependency4;
                if (!string.IsNullOrWhiteSpace(loaded.Supersedence1))             app.Supersedence1              = loaded.Supersedence1;
                if (!string.IsNullOrWhiteSpace(loaded.Supersedence2))             app.Supersedence2              = loaded.Supersedence2;
                if (!string.IsNullOrWhiteSpace(loaded.Supersedence3))             app.Supersedence3              = loaded.Supersedence3;
                if (!string.IsNullOrWhiteSpace(loaded.Supersedence4))             app.Supersedence4              = loaded.Supersedence4;
                if (!string.IsNullOrWhiteSpace(loaded.UninstallPreviousVersion1)) app.UninstallPreviousVersion1 = loaded.UninstallPreviousVersion1;
                if (!string.IsNullOrWhiteSpace(loaded.UninstallPreviousVersion2)) app.UninstallPreviousVersion2 = loaded.UninstallPreviousVersion2;
                if (!string.IsNullOrWhiteSpace(loaded.UninstallPreviousVersion3)) app.UninstallPreviousVersion3 = loaded.UninstallPreviousVersion3;
                if (!string.IsNullOrWhiteSpace(loaded.UninstallPreviousVersion4)) app.UninstallPreviousVersion4 = loaded.UninstallPreviousVersion4;
                if (loaded.Dependencies.Count  > 0) app.Dependencies  = loaded.Dependencies;
                if (loaded.Supersedences.Count > 0) app.Supersedences = loaded.Supersedences;
                if (!string.IsNullOrWhiteSpace(loaded.CopyLogsToDocuments))       app.CopyLogsToDocuments        = loaded.CopyLogsToDocuments;
                if (!string.IsNullOrWhiteSpace(loaded.CopyCSVToDocuments))        app.CopyCSVToDocuments         = loaded.CopyCSVToDocuments;
                if (!string.IsNullOrWhiteSpace(loaded.CopyHtmlToDocuments))       app.CopyHtmlToDocuments        = loaded.CopyHtmlToDocuments;
                if (!string.IsNullOrWhiteSpace(loaded.CopytxtToDocuments))        app.CopytxtToDocuments         = loaded.CopytxtToDocuments;
                if (!string.IsNullOrWhiteSpace(loaded.CopydocxToDocuments))       app.CopydocxToDocuments        = loaded.CopydocxToDocuments;
                if (!string.IsNullOrWhiteSpace(loaded.SourceAppVersion))           app.SourceAppVersion           = loaded.SourceAppVersion;
                if (!string.IsNullOrWhiteSpace(loaded.AppVersion))                app.AppVersion                 = loaded.AppVersion;
                if (!string.IsNullOrWhiteSpace(loaded.PSADTTemplateFolder))            app.PSADTTemplateFolder             = loaded.PSADTTemplateFolder;
                // Without these two the file was write-only: the packaging step reads
                // _selectedApp.PSADTInstallCommand, so a value edited straight into the JSON never
                // reached it and the previous in-memory command was used instead.
                if (!string.IsNullOrWhiteSpace(loaded.PSADTInstallCommand))            app.PSADTInstallCommand             = loaded.PSADTInstallCommand;
                if (!string.IsNullOrWhiteSpace(loaded.PSADTUninstallCommand))          app.PSADTUninstallCommand           = loaded.PSADTUninstallCommand;
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
        }

        // ── Data ───────────────────────────────────────────────────────────
        private static T? FindVisualChild<T>(System.Windows.DependencyObject parent) where T : System.Windows.DependencyObject
        {
            for (int i = 0; i < System.Windows.Media.VisualTreeHelper.GetChildrenCount(parent); i++)
            {
                var child = System.Windows.Media.VisualTreeHelper.GetChild(parent, i);
                if (child is T t) return t;
                var result = FindVisualChild<T>(child);
                if (result != null) return result;
            }
            return null;
        }

        private void LoadApps()
        {
            try
            {
                // Load global config (no Apps array)
                if (File.Exists(JsonPath))
                {
                    // Use lenient options: trailing commas, comments, case-insensitive
                    // This handles common hand-edited JSON mistakes (missing comma, trailing comma)
                    var opts = new JsonSerializerOptions
                    {
                        PropertyNameCaseInsensitive = true,
                        AllowTrailingCommas         = true,
                        ReadCommentHandling         = JsonCommentHandling.Skip
                    };
                    SourceDownloadConfig? config = null;
                    try
                    {
                        config = JsonSerializer.Deserialize<SourceDownloadConfig>(
                            File.ReadAllText(JsonPath), opts);
                    }
                    catch
                    {
                        // JSON is malformed (e.g. missing comma) — try to extract fields
                        // individually using regex so the app list still loads
                        string raw = File.ReadAllText(JsonPath);
                        config = new SourceDownloadConfig
                        {
                            SourceDownloadPath   = ExtractJsonString(raw, "SourceDownloadPath"),
                            PackageInputFolder   = ExtractJsonString(raw, "PackageInputFolder"),
                            PackageOutputFolder  = ExtractJsonString(raw, "PackageOutputFolder"),
                            AppVersionReportPath = ExtractJsonString(raw, "AppVersionReportPath"),
                            PSADTTemplateFolder  = ExtractJsonString(raw, "PSADTTemplateFolder"),
                        };
                    }
                    _sourceDownloadPath  = config?.SourceDownloadPath ?? "";
                    // The folder that drives packaging is still per-app, stored in each app's JSON.
                    // This global value is only the DEFAULT the Add App dialog starts from, so a new
                    // app does not open with the field blank. Previously this was hardcoded to "" and
                    // never read again, which is why every new app began with nothing here.
                    _psadtTemplateFolder = config?.PSADTTemplateFolder ?? "";
                    _packageInputFolder  = config?.PackageInputFolder  ?? "";
                    _packageOutputFolder = config?.PackageOutputFolder ?? "";
                    _appVersionReportPath = config?.AppVersionReportPath ?? "";
                }

                // Scan PackageInputFolder: new structure = <Vendor>\<AppName>\Vendor_AppName.json
                _allApps = new();
                if (!string.IsNullOrWhiteSpace(_packageInputFolder) && Directory.Exists(_packageInputFolder))
                {
                    foreach (var vendorDir in Directory.GetDirectories(_packageInputFolder))
                    {
                        foreach (var appFolder in Directory.GetDirectories(vendorDir))
                        {
                            // Only load files named Vendor_AppName.json (contain underscore)
                            var jsonFile = Directory.GetFiles(appFolder, "*.json")
                                .FirstOrDefault(f => Path.GetFileNameWithoutExtension(f).Contains('_'));
                            if (jsonFile == null) continue;
                            try
                            {
                                var entry = JsonSerializer.Deserialize<DownloadSourceEntry>(
                                    File.ReadAllText(jsonFile),
                                    new JsonSerializerOptions { PropertyNameCaseInsensitive = true });
                                if (entry != null)
                                {
                                    if (string.IsNullOrWhiteSpace(entry.PackageTemplateFolder))
                                        entry.PackageTemplateFolder = appFolder;
                                    _allApps.Add(entry);
                                }
                            }
                            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                        }
                    }
                }
            }
            catch { _allApps = new(); }
        }

        /// <summary>
        /// Regex-based fallback to extract a string value from malformed JSON
        /// (e.g. missing comma between fields). Returns empty string if not found.
        /// </summary>
        private static string ExtractJsonString(string json, string key)
        {
            var m = System.Text.RegularExpressions.Regex.Match(
                json,
                $@"""{System.Text.RegularExpressions.Regex.Escape(key)}""\s*:\s*""([^""\\]*(?:\\.[^""\\]*)*)""",
                System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            return m.Success ? m.Groups[1].Value.Replace("\\\\", "\\") : "";
        }

        private void SaveApps()
        {
            try
            {
                // Merge only the four download-stage keys into AutoPackage.json,
                // preserving every other setting in the file. If the file is
                // malformed and cannot be parsed, skip the global save entirely
                // rather than risk destroying the user's other settings.
                try
                {
                    System.Text.Json.Nodes.JsonObject? root = null;
                    if (File.Exists(JsonPath))
                    {
                        var docOpts = new JsonDocumentOptions
                        {
                            AllowTrailingCommas = true,
                            CommentHandling = JsonCommentHandling.Skip
                        };
                        root = System.Text.Json.Nodes.JsonNode.Parse(
                            File.ReadAllText(JsonPath), null, docOpts)?.AsObject();
                    }
                    root ??= new System.Text.Json.Nodes.JsonObject();
                    // SourceDownloadPath / PackageInputFolder / PackageOutputFolder /
                    // AppVersionReportPath are GLOBAL configuration paths. This page only
                    // READS them (LoadApps); it must never overwrite them, or the Add App /
                    // save flow can clobber a user-configured value (e.g. reset
                    // PackageInputFolder back to the installed default). Rule: if the file
                    // already has a value, the FILE WINS — keep it and re-sync our in-memory
                    // copy. Only seed a key when it is entirely missing (brand-new file).
                    void PreserveConfigPath(string key, ref string field)
                    {
                        string? onDisk = null;
                        try { onDisk = root![key]?.GetValue<string>(); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                        if (string.IsNullOrWhiteSpace(onDisk))
                            root[key] = field;   // bootstrap only when absent
                        else
                            field = onDisk;      // disk wins — re-sync in-memory field
                    }
                    PreserveConfigPath("SourceDownloadPath",   ref _sourceDownloadPath);
                    PreserveConfigPath("PackageInputFolder",   ref _packageInputFolder);
                    PreserveConfigPath("PackageOutputFolder",  ref _packageOutputFolder);
                    PreserveConfigPath("AppVersionReportPath", ref _appVersionReportPath);
                    PreserveConfigPath("PSADTTemplateFolder",  ref _psadtTemplateFolder);
                    File.WriteAllText(JsonPath, root.ToJsonString(
                        new JsonSerializerOptions { WriteIndented = true }));
                }
                catch { /* unparsable AutoPackage.json — do not overwrite it */ }
                // Save each app to its individual VendorName_AppName.json
                foreach (var app in _allApps)
                    SaveAppJson(app);
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
        }

        /// <summary>
        /// Immediately persists _selectedApp to its per-app JSON file
        /// (e.g. Smekal_FileCompare.json inside PackageTemplateFolder).
        /// Called when Install/Uninstall Package checkboxes change so the value
        /// is saved instantly without waiting for a full SaveApps() pass.
        /// </summary>
        private void SaveJsonAppForSelectedApp()
        {
            if (_selectedApp != null)
                SaveAppJson(_selectedApp);
        }

        // ── Category Chips ─────────────────────────────────────────────────
        private void BuildCategoryChips()
        {
            PnlCategories.Children.Clear();
            var cats = _allApps
                .Select(a => a.Category).Distinct().OrderBy(c => c)
                .ToList();
            foreach (var cat in cats)
            {
                var btn = new Button
                {
                    Content = cat, Tag = cat,
                    Style   = cat == _activeCategory
                              ? (Style)(TryFindResource("ChipActiveStyle") ?? new Style())
                              : (Style)(TryFindResource("ChipStyle")       ?? new Style()),
                };
                btn.Click += (_, _) =>
                {
                    // Toggle: clicking active chip goes back to "All"
                    _activeCategory = _activeCategory == cat ? "All" : cat;
                    _selectedVendor = "";
                    _selectedApp    = null;
                    // Reset all category chips
                    foreach (Button c in PnlCategories.Children)
                        c.Style = (Style)(TryFindResource("ChipStyle") ?? new Style());
                    // Set All button: active when showing all, inactive when category selected
                    if (BtnChipAll != null)
                        BtnChipAll.Style = (Style)(TryFindResource(
                            _activeCategory == "All" ? "ChipActiveStyle" : "ChipStyle") ?? new Style());
                    // Activate this chip if category selected
                    if (_activeCategory != "All")
                        btn.Style = (Style)(TryFindResource("ChipActiveStyle") ?? new Style());
                    RenderVendors();
                    RenderCards();
                    var firstApp = _allApps
                        .Where(a => _activeCategory == "All" || a.Category == _activeCategory)
                        .OrderBy(a => a.SourceAppVendor).ThenBy(a => a.SourceAppName)
                        .FirstOrDefault();
                    if (firstApp != null) SelectApp(firstApp);
                };
                PnlCategories.Children.Add(btn);
            }
        }

        // ── Table Rendering ────────────────────────────────────────────────
        // ── Vendor List (master panel) ─────────────────────────────────────
        private void RenderVendors()
        {
            PnlVendors.Children.Clear();

            var vendors = _allApps
                .Where(a => _activeCategory == "All" || a.Category == _activeCategory)
                .Where(a => string.IsNullOrWhiteSpace(_searchText)
                         || a.SourceAppName.Contains(_searchText,  StringComparison.OrdinalIgnoreCase)
                         || a.SourceAppVendor.Contains(_searchText,   StringComparison.OrdinalIgnoreCase))
                .GroupBy(a => a.SourceAppVendor)
                .OrderBy(g => g.Key)
                .ToList();

            if (vendors.Count == 0) return;

            // Auto-select first vendor if none selected or selected not in list
            if (string.IsNullOrEmpty(_selectedVendor) ||
                vendors.All(g => g.Key != _selectedVendor))
                _selectedVendor = vendors[0].Key;

            var accent  = Res("AccentBrush", new SolidColorBrush(Color.FromRgb(0x6C, 0x63, 0xFF)));
            var selBg   = new SolidColorBrush(Color.FromArgb(0x15, 0x6C, 0x63, 0xFF));
            var lblFg   = Res("TextPrimaryBrush", Brushes.Black);
            var mutFg   = Res("TextMutedBrush", Brushes.DarkGray);
            var hoverBg = new SolidColorBrush(Color.FromArgb(0x0A, 0x6C, 0x63, 0xFF));

            foreach (var group in vendors)
            {
                bool isSel     = _selectedVendor == group.Key;
                var  capVendor = group.Key;

                var row = new Border
                {
                    Tag             = group.Key,   // so ScrollVendorIntoView can find this row
                    Background      = isSel ? selBg : Brushes.Transparent,
                    BorderBrush     = accent,
                    BorderThickness = new Thickness(0),
                    CornerRadius    = new CornerRadius(6),
                    Padding         = new Thickness(10, 6, 8, 6),
                    Margin          = new Thickness(4, 1, 4, 1),
                    Cursor          = System.Windows.Input.Cursors.Hand,
                };

                // Hover effect
                row.MouseEnter += (_, _) => { if (_selectedVendor != capVendor) row.Background = hoverBg; };
                row.MouseLeave += (_, _) => { if (_selectedVendor != capVendor) row.Background = Brushes.Transparent; };

                var sp = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };

                // Vendor name — same font as Create Package command list
                var vendorTb = new TextBlock
                {
                    Text       = group.Key,
                    FontSize   = 12,
                    FontWeight = FontWeights.Normal,
                    Foreground = lblFg,
                    VerticalAlignment = VerticalAlignment.Center,
                };
                vendorTb.SetResourceReference(TextBlock.ForegroundProperty, "TextPrimaryBrush");
                sp.Children.Add(vendorTb);

                // App count badge — only when vendor has multiple apps
                if (group.Count() > 1)
                {
                    var badge = new Border
                    {
                        Background    = isSel ? accent : new SolidColorBrush(Color.FromArgb(0x18, 0x6C, 0x63, 0xFF)),
                        CornerRadius  = new CornerRadius(8),
                        Padding       = new Thickness(5, 1, 5, 1),
                        Margin        = new Thickness(6, 0, 0, 0),
                        VerticalAlignment = VerticalAlignment.Center,
                    };
                    badge.Child = new TextBlock
                    {
                        Text       = group.Count().ToString(),
                        FontSize   = 9, FontWeight = FontWeights.SemiBold,
                        Foreground = isSel ? Brushes.White : accent,
                    };
                    sp.Children.Add(badge);
                }

                // "⬆" badge — any app in this vendor group has a live version available
                // Show when a genuinely NEWER live version exists (or nothing was ever
                // downloaded). Was plain inequality, which lit the badge when the LOCAL
                // version was ahead - a vendor rollback, or a hand-edited Source App
                // Version - while the scheduler's gate correctly refused to download.
                // Badge, Updates tab and scheduler now share one comparison.
                bool vendorHasUpdate = group.Any(a =>
                    _liveVersionCache.TryGetValue(a.SourceAppName, out string? lv) &&
                    IsRemoteNewer(lv, a.SourceAppVersion));

                if (vendorHasUpdate)
                {
                    var upBadge = new Border
                    {
                        Background      = new SolidColorBrush(Color.FromArgb(0x22, 0xFF, 0x80, 0x00)),
                        BorderBrush     = new SolidColorBrush(Color.FromArgb(0xAA, 0xFF, 0x80, 0x00)),
                        BorderThickness = new Thickness(1),
                        CornerRadius    = new CornerRadius(3),
                        Padding         = new Thickness(4, 1, 4, 1),
                        Margin          = new Thickness(5, 0, 0, 0),
                        VerticalAlignment = VerticalAlignment.Center,
                        ToolTip         = "One or more apps from this vendor have a new version available",
                    };
                    upBadge.Child = new TextBlock
                    {
                        Text       = "New",
                        FontSize   = 8,
                        FontWeight = FontWeights.Bold,
                        Foreground = new SolidColorBrush(Color.FromRgb(0xFF, 0x80, 0x00)),
                    };
                    sp.Children.Add(upBadge);
                }

                row.Child = sp;
                row.MouseLeftButtonUp += (_, _) =>
                {
                    _kbNavColumn = "vendor";
                    Focus();   // arrows now route through the page's PreviewKeyDown
                    SelectVendorByName(capVendor);
                };

                PnlVendors.Children.Add(row);
            }
        }

        /// <summary>
        /// The vendor click, as a method: select the vendor, reset the app side, repaint,
        /// and open the vendor's first app. Extracted so the keyboard navigation can do
        /// exactly what a mouse click does instead of drifting into its own variant.
        /// </summary>
        private void SelectVendorByName(string vendor)
        {
            _selectedVendor = vendor;
            _selectedApp    = null;
            PnlInfoPlaceholder.Visibility = Visibility.Visible;
            PnlAppInfo.Visibility         = Visibility.Collapsed;
            TxtInfoTitle.Visibility = Visibility.Visible;
            PnlPackageInfo?.Children.Clear();
            RenderVendors();
            RenderCards();

            // Auto-select and open the first app of this vendor
            var firstApp = _allApps
                .Where(a => a.SourceAppVendor == vendor)
                .Where(a => _activeCategory == "All" || a.Category == _activeCategory)
                .OrderBy(a => a.SourceAppName)
                .FirstOrDefault();
            if (firstApp != null)
                SelectApp(firstApp);
        }

        // ── App List (detail panel — shows only selected vendor's apps) ────
        private void RenderCards()
        {
            PnlCards.Children.Clear();

            if (string.IsNullOrEmpty(_selectedVendor)) return;

            var apps = _allApps
                .Where(a => a.SourceAppVendor == _selectedVendor)
                .Where(a => _activeCategory == "All" || a.Category == _activeCategory)
                .Where(a => string.IsNullOrWhiteSpace(_searchText)
                         || a.SourceAppName.Contains(_searchText,  StringComparison.OrdinalIgnoreCase)
                         || a.SourceAppVendor.Contains(_searchText,   StringComparison.OrdinalIgnoreCase))
                .OrderBy(a => a.SourceAppName)
                .ToList();

            // footer removed — count no longer displayed
            if (apps.Count == 0) return;

            var accent  = Res("AccentBrush", new SolidColorBrush(Color.FromRgb(0x6C, 0x63, 0xFF)));
            var selBg   = new SolidColorBrush(Color.FromArgb(0x15, 0x6C, 0x63, 0xFF));
            var lblFg   = Res("TextPrimaryBrush", Brushes.Black);
            var mutFg   = Res("TextMutedBrush", Brushes.DarkGray);
            var bdrBr   = Res("BorderMainBrush", Brushes.LightGray);
            var hoverBg = new SolidColorBrush(Color.FromArgb(0x0A, 0x6C, 0x63, 0xFF));

            foreach (var app in apps)
            {
                bool isSel  = _selectedApp == app;
                var  cap    = app;

                var row = new Border
                {
                    Background      = isSel ? selBg : Brushes.Transparent,
                    BorderBrush     = accent,
                    BorderThickness = new Thickness(0),
                    CornerRadius    = new CornerRadius(6),
                    Padding         = new Thickness(10, 6, 8, 6),
                    Margin          = new Thickness(4, 1, 4, 1),
                    Cursor          = System.Windows.Input.Cursors.Hand,
                };

                // Hover effect
                row.MouseEnter += (_, _) => { if (_selectedApp != cap) row.Background = hoverBg; };
                row.MouseLeave += (_, _) => { if (_selectedApp != cap) row.Background = Brushes.Transparent; };

                var sp = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };

                // App name — same font as Create Package command list
                var appTb = new TextBlock
                {
                    Text       = app.SourceAppName,
                    FontSize   = 12,
                    FontWeight = FontWeights.Normal,
                    Foreground = lblFg,
                    VerticalAlignment = VerticalAlignment.Center,
                    TextTrimming = TextTrimming.CharacterEllipsis,
                };
                appTb.SetResourceReference(TextBlock.ForegroundProperty, "TextPrimaryBrush");
                sp.Children.Add(appTb);

                // Live badge removed — version number in info panel is sufficient

                // "New" badge - shown for a genuinely NEWER live version (or never downloaded);
                // same IsRemoteNewer the scheduler uses, so the badge can never promise a
                // download the version gate will refuse.
                if (_liveVersionCache.TryGetValue(app.SourceAppName, out string? liveVer) &&
                    IsRemoteNewer(liveVer, app.SourceAppVersion))
                {
                    var newBadge = new Border
                    {
                        Background      = new SolidColorBrush(Color.FromArgb(0x22, 0xFF, 0x80, 0x00)),
                        BorderBrush     = new SolidColorBrush(Color.FromArgb(0xAA, 0xFF, 0x80, 0x00)),
                        BorderThickness = new Thickness(1),
                        CornerRadius    = new CornerRadius(3),
                        Padding         = new Thickness(4, 1, 4, 1),
                        Margin          = new Thickness(4, 0, 0, 0),
                        VerticalAlignment = VerticalAlignment.Center,
                        ToolTip         = $"New version available: {liveVer} (downloaded: {app.SourceAppVersion})",
                    };
                    newBadge.Child = new TextBlock
                    {
                        Text       = "New",
                        FontSize   = 8,
                        FontWeight = FontWeights.Bold,
                        Foreground = new SolidColorBrush(Color.FromRgb(0xFF, 0x80, 0x00)),
                    };
                    sp.Children.Add(newBadge);
                }

                row.Child = sp;
                row.Tag = cap.SourceAppName;   // keyboard navigation scrolls this card into view
                row.MouseLeftButtonUp += (_, _) =>
                {
                    _kbNavColumn = "app";
                    Focus();   // arrows now route through the page's PreviewKeyDown
                    SelectApp(cap);
                };

                PnlCards.Children.Add(row);
            }
        }

        // ── Selection + Async Fetch ────────────────────────────────────────
        // Version info is cached per app so switching vendors/apps (and theme
        // rebuilds) render instantly; only the first view fetches the network.
        private static readonly Dictionary<string, (AppDownloadInfo Info, DateTime At)>
            _infoCache = new(StringComparer.OrdinalIgnoreCase);
        // How long a cached entry counts as FRESH (no network call at all).
        //
        // Was 15 minutes, which is what burned the GitHub quota: every page load and every Refresh
        // cleared the live-version cache and re-fetched all apps, and 15 minutes later did it again.
        // Vendors ship releases a few times a month, not four times an hour.
        private static readonly TimeSpan _infoCacheTtl = TimeSpan.FromHours(6);

        // ── Persistent info cache ─────────────────────────────────────────────────────────────
        // The in-memory cache above dies with the process, so every restart re-fetched every app.
        // This mirrors it to disk, which gives two things:
        //   1. a cold start costs no network calls at all if the cache is fresh, and
        //   2. a LAST-KNOWN-GOOD copy to fall back on when a fetch fails.
        //
        // (2) is the one that fixes the disappearing download buttons: FetchAndShowAsync used to do
        //         catch { info = FallbackInfo(app); }
        //         _infoCache[InfoKey(app)] = (info, DateTime.UtcNow);
        // so a single 403 OVERWROTE good links with an empty FallbackInfo and pinned that for the
        // whole TTL. A transient rate-limit therefore destroyed data we already had.
        private sealed class CachedInfo
        {
            public AppDownloadInfo Info { get; set; } = new();
            public DateTime        At   { get; set; }
        }

        private static string InfoCachePath => Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "SwiftPack", "cache", "appinfo.json");

        private static bool _infoCacheLoaded;
        private static System.Threading.CancellationTokenSource? _infoSaveCts;

        /// <summary>Reads the on-disk cache into _infoCache. Runs once per process.</summary>
        private static void LoadInfoCache()
        {
            if (_infoCacheLoaded) return;
            _infoCacheLoaded = true;
            try
            {
                if (!File.Exists(InfoCachePath)) return;
                var map = JsonSerializer.Deserialize<Dictionary<string, CachedInfo>>(
                    File.ReadAllText(InfoCachePath));
                if (map == null) return;
                foreach (var kv in map)
                    if (kv.Value?.Info != null)
                        _infoCache[kv.Key] = (kv.Value.Info, kv.Value.At);
            }
            catch (Exception ex) { LogWinget($"[InfoCache] load failed: {ex.Message}"); }
        }

        /// <summary>
        /// Writes the cache to disk, debounced. The background sweep writes an entry per app, and at
        /// 1000 apps a save per entry would be 1000 rewrites of the whole file - so coalesce them and
        /// flush 3 seconds after the last one.
        /// </summary>
        private static void SaveInfoCacheDebounced()
        {
            try
            {
                _infoSaveCts?.Cancel();
                _infoSaveCts = new System.Threading.CancellationTokenSource();
                var token = _infoSaveCts.Token;
                _ = Task.Run(async () =>
                {
                    try
                    {
                        await Task.Delay(3000, token).ConfigureAwait(false);
                        if (token.IsCancellationRequested) return;

                        Directory.CreateDirectory(Path.GetDirectoryName(InfoCachePath)!);
                        var map = _infoCache.ToDictionary(
                            kv => kv.Key,
                            kv => new CachedInfo { Info = kv.Value.Info, At = kv.Value.At });
                        string tmp = InfoCachePath + ".tmp";
                        File.WriteAllText(tmp, JsonSerializer.Serialize(map,
                            new JsonSerializerOptions { WriteIndented = false }));
                        if (File.Exists(InfoCachePath)) File.Delete(InfoCachePath);
                        File.Move(tmp, InfoCachePath);
                    }
                    catch (OperationCanceledException) { }
                    catch (Exception ex) { LogWinget($"[InfoCache] save failed: {ex.Message}"); }
                }, token);
            }
            catch (Exception ex) { LogWinget($"[InfoCache] save schedule failed: {ex.Message}"); }
        }

        /// <summary>
        /// Every API Type the fetch switch actually handles, plus "URL".
        ///
        /// This exists because API Type used to be a FREE-TEXT box. Anything typed that was not one of
        /// these fell into the switch's `_ => FallbackInfo(app)` arm - which returns no links and says
        /// nothing about why. That is how an app ended up with API Type set to its own vendor name (not a fetcher,
        /// and the switch is case-sensitive anyway) showing a permanently empty Download Information
        /// panel with no explanation. A dropdown makes the mistake impossible.
        ///
        /// KEEP IN STEP with the switch in FetchAndShowAsync / FetchAllVersionsInBackgroundAsync.
        /// "URL" is meaningful: no fetcher, download manually via Download Page URL. It was previously
        /// stored as "none"; legacy apps are normalised to "URL" in DownloadSourceEntry.OnDeserialized,
        /// so only the value "URL" is ever compared against below.
        /// </summary>
        internal static readonly string[] ApiTypeOptions =
        {
            "URL", "winget", "github", "Vendor API",
        };

        // Winget package IDs are "Publisher.Package" (e.g. "Smekal.FileCompare"); this pulls the
        // publisher out for the picker's Vendor column without touching the WingetPackage model.
        private sealed class IdVendorConverter : System.Windows.Data.IValueConverter
        {
            public object Convert(object value, Type targetType, object parameter, System.Globalization.CultureInfo culture)
            {
                string id = value as string ?? "";
                int dot = id.IndexOf('.');
                return dot > 0 ? id.Substring(0, dot) : id;
            }
            public object ConvertBack(object value, Type targetType, object parameter, System.Globalization.CultureInfo culture)
                => System.Windows.Data.Binding.DoNothing;
        }
        private static readonly IdVendorConverter _idVendor = new IdVendorConverter();

        /// <summary>
        /// Searchable picker over the LOCAL winget catalog. Returns the chosen package ID, or null.
        ///
        /// Purely local - WingetCatalog already holds the whole community repo on disk, so this makes
        /// no network call and is not subject to any rate limit. It exists so nobody has to guess an
        /// ID: a wrong one produces no download links and no error, which is exactly how an app ended
        /// up with a permanently blank Download Information panel.
        /// </summary>
        private WingetCatalog.WingetPackage? PickWingetPackage(string initialQuery)
        {
            var winBg     = Res("WindowBgBrush",     Brushes.White);
            var borderClr = Res("BorderMainBrush",   Brushes.LightGray);
            var lblFg     = Res("TextSecondaryBrush", Brushes.Gray);
            var valFg     = Res("TextPrimaryBrush",  Brushes.Black);
            WingetCatalog.WingetPackage? result = null;

            var win = new Window
            {
                Width = 800, Height = 420,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = Window.GetWindow(this),
                ResizeMode = ResizeMode.NoResize,
                WindowStyle = WindowStyle.None,
                AllowsTransparency = true,
                Background = Brushes.Transparent,
                ShowInTaskbar = false,
            };
            var outer = new Border
            {
                Background = winBg, BorderBrush = borderClr, BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(10),
            };
            win.Content = outer;

            var g = new Grid { Margin = new Thickness(16) };
            g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });                      // title
            g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });                      // search
            g.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) }); // results
            g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });                      // buttons
            outer.Child = g;

            var title = new TextBlock
            {
                Text = "Winget Package ID", FontSize = 13, FontWeight = FontWeights.SemiBold,
                Foreground = valFg, Margin = new Thickness(0, 0, 0, 2), VerticalAlignment = VerticalAlignment.Center,
            };
            title.MouseLeftButtonDown += (_, _) => win.DragMove();
            var titleClose = new Button
            {
                Content = "\u2715", FontSize = 12, Width = 24, Height = 24, Padding = new Thickness(0),
                Background = Brushes.Transparent, BorderThickness = new Thickness(0),
                Foreground = lblFg, Cursor = System.Windows.Input.Cursors.Hand, ToolTip = "Close",
                VerticalAlignment = VerticalAlignment.Top, HorizontalAlignment = HorizontalAlignment.Right,
            };
            titleClose.Click += (_, _) => win.Close();
            var titleBar = new Grid();
            titleBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            titleBar.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            Grid.SetColumn(title, 0); Grid.SetColumn(titleClose, 1);
            titleBar.Children.Add(title); titleBar.Children.Add(titleClose);
            Grid.SetRow(titleBar, 0); g.Children.Add(titleBar);

            var search = new TextBox
            {
                Text = initialQuery, FontSize = 11, Height = 28,
                Padding = new Thickness(8, 0, 8, 0),
                VerticalContentAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 6, 0, 6),
                BorderBrush = borderClr, BorderThickness = new Thickness(1),
                Foreground = valFg,
            };
            if (TryFindResource("ModernTextBoxStyle") is Style ts) search.Style = ts;
            search.SetResourceReference(TextBox.BackgroundProperty, "InputBgBrush");
            Grid.SetRow(search, 1); g.Children.Add(search);

            // Name | Id | Version - the id alone is not enough to recognise a package
            // ("XPFCG5NRKXQPKT" tells you nothing; "Smekal FileCompare" does).
            var list = new ListView { FontSize = 11, Foreground = valFg, BorderBrush = borderClr };
            list.SetResourceReference(ListView.BackgroundProperty, "InputBgBrush");
            var gv = new GridView();
            gv.Columns.Add(new GridViewColumn { Header = "Vendor",  Width = 150, DisplayMemberBinding = new System.Windows.Data.Binding("Id") { Converter = _idVendor } });
            gv.Columns.Add(new GridViewColumn { Header = "Name",    Width = 220, DisplayMemberBinding = new System.Windows.Data.Binding("Name") });
            gv.Columns.Add(new GridViewColumn { Header = "Package ID", Width = 250, DisplayMemberBinding = new System.Windows.Data.Binding("Id") });
            gv.Columns.Add(new GridViewColumn { Header = "Version", Width = 95,  DisplayMemberBinding = new System.Windows.Data.Binding("Version") });
            list.View = gv;
            Grid.SetRow(list, 2); g.Children.Add(list);

            // The results ListView is item-scrolled (each wheel notch = 1 ROW). A touchpad emits many
            // small deltas, so the default handling races through the list; accumulate fractional
            // notches and move one whole row at a time - same slow, controlled feel as the main page.
            double pickWheelAccum = 0;
            list.PreviewMouseWheel += (_, me) =>
            {
                var sv = FindVisualChild<ScrollViewer>(list);
                if (sv == null) return;
                pickWheelAccum += me.Delta / 120.0;   // one wheel click = 120
                int rows = (int)pickWheelAccum;       // keep the remainder so small deltas add up
                if (rows != 0)
                {
                    sv.ScrollToVerticalOffset(sv.VerticalOffset - rows);
                    pickWheelAccum -= rows;
                }
                me.Handled = true;
            };

            // Package ID holds the longest text, so let it absorb whatever width is left after the
            // other three fixed columns: the four then fill the window edge-to-edge (no empty band on
            // the right) and long ids still show in full. Runs once, after the list has laid out.
            list.Loaded += (_, _) => list.Dispatcher.BeginInvoke(new Action(() =>
            {
                double others = gv.Columns[0].Width + gv.Columns[1].Width + gv.Columns[3].Width;
                double fill = list.ActualWidth - others - 26;   // spare a little for the vertical scrollbar
                if (fill > 180) gv.Columns[2].Width = fill;
            }), System.Windows.Threading.DispatcherPriority.Loaded);

            var hint = new TextBlock
            {
                Text = "type at least 2 characters", FontSize = 10, FontStyle = FontStyles.Italic,
                Foreground = lblFg, Margin = new Thickness(0, 6, 0, 0),
            };

            // Plain TextBox -> typing is never interfered with. The results list is a separate
            // control, so nothing resets the caret (which is exactly what the editable ComboBox did).
            void Refresh()
            {
                // An empty query lists the catalog (capped), so the picker is never blank.
                // No cap: the catalog is ~10k packages and ListView virtualises, so browsing the whole
                // thing alphabetically is fine.
                var hits = WingetCatalog.SearchPackages(search.Text?.Trim() ?? "");
                var hide = WingetHiddenIds();
                if (hide.Count > 0) hits = hits.Where(p => !hide.Contains(p.Id)).ToList();
                // Pre-release builds are never offered. Note this means typing "beta" here returns
                // nothing rather than a list of betas, which is the intent.
                hits = hits.Where(p => !IsBetaPackage(p.Id, p.Name)).ToList();
                list.ItemsSource = hits;
                hint.FontStyle = FontStyles.Italic; hint.FontWeight = FontWeights.Normal; hint.Foreground = lblFg;
                // "no match" is a lie on a machine that has no catalog at all - which is what the
                // picker showed for the whole of the first-launch download, with nothing on screen
                // to say so. Separate the two states.
                hint.Text = hits.Count > 0
                    ? $"{hits.Count:N0} package(s)"
                    : System.IO.File.Exists(WingetIndexPath)
                        ? "no match in the catalog"
                        : "the package catalog is still downloading - reopen this in a moment, "
                        + "or press Check now in the Downloads window";
            }
            search.TextChanged += (_, _) => Refresh();
            list.MouseDoubleClick += (_, _) =>
            {
                if (list.SelectedItem is WingetCatalog.WingetPackage wp) { result = wp; win.Close(); }
            };

            // Per-selection installer-type readout: the local catalog has no installer type, so when a
            // row is highlighted, fetch just that package's manifest and show what it offers (MSI only /
            // EXE only / MSI + EXE) in the footer. One cached lookup per package, best-effort.
            var typeCache = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            async Task<string> WingetTypesAsync(string id, string version)
            {
                var meta = await WingetCommandsAsync(id, version);
                return string.IsNullOrEmpty(meta.type) ? "type unknown" : meta.type;
            }
            void ShowType(string text, bool strong)
            {
                hint.FontStyle  = FontStyles.Normal;
                hint.FontWeight = strong ? FontWeights.Bold : FontWeights.Normal;
                hint.Foreground = strong ? valFg : lblFg;
                hint.Text       = text;
            }
            list.SelectionChanged += async (_, _) =>
            {
                if (list.SelectedItem is not WingetCatalog.WingetPackage sel) return;
                string id = sel.Id, ver = sel.Version;
                if (typeCache.TryGetValue(id, out var cached)) { ShowType($"Installer type:  {cached}", true); return; }
                ShowType("Installer type:  checking...", false);
                string label = await WingetTypesAsync(id, ver);
                typeCache[id] = label;
                if (list.SelectedItem is WingetCatalog.WingetPackage cur2 && string.Equals(cur2.Id, id, StringComparison.OrdinalIgnoreCase))
                    ShowType($"Installer type:  {label}", true);
            };

            var bar = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = HorizontalAlignment.Right,
                Margin = new Thickness(0, 10, 0, 0),
            };
            var hintHost = new Grid();
            Grid.SetRow(hintHost, 3);

            var bCancel = new Button { Content = "✕  Cancel", FontSize = 11, Height = 28, Width = 92, Margin = new Thickness(0, 0, 8, 0), Cursor = System.Windows.Input.Cursors.Hand };
            if (TryFindResource("SecondaryButtonStyle") is Style sb) bCancel.Style = sb;
            bCancel.Click += (_, _) => win.Close();

            var bOk = new Button { Content = "✔  Select", FontSize = 11, Height = 28, Width = 92, Cursor = System.Windows.Input.Cursors.Hand };
            if (TryFindResource("ActionBtnStyle") is Style ab) bOk.Style = ab;
            bOk.Click += (_, _) =>
            {
                if (list.SelectedItem is WingetCatalog.WingetPackage wp) { result = wp; win.Close(); }
            };
            bar.Children.Add(bCancel); bar.Children.Add(bOk);

            var bottom = new Grid();
            bottom.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            bottom.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            Grid.SetColumn(hint, 0); Grid.SetColumn(bar, 1);
            bottom.Children.Add(hint); bottom.Children.Add(bar);
            Grid.SetRow(bottom, 3); g.Children.Add(bottom);

            Refresh();
            search.Focus();
            search.CaretIndex = search.Text.Length;
            win.ShowDialog();
            return result;
        }

        // Resolves a bundled reference file (github_catalog.json, winget_noninstaller.json) from the
        // SAME Templates folder the app already uses for AutoPackage.json, so they sit right beside
        // it. Falls back to the per-user winget folder, then beside the exe.
        private static string? TemplateFile(string fileName)
        {
            string templates = System.IO.Path.Combine(System.IO.Path.GetDirectoryName(JsonPath) ?? "", fileName);
            if (System.IO.File.Exists(templates)) return templates;
            string local = System.IO.Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "SwiftPack", "winget", fileName);
            if (System.IO.File.Exists(local)) return local;
            string exe = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, fileName);
            return System.IO.File.Exists(exe) ? exe : null;
        }

        /// <summary>
        /// Write-then-rename. WriteAllText truncates the target first, so a crash, a power loss or a
        /// full disk part-way through leaves a half-written catalog on disk. A truncated catalog does
        /// not parse, and an unparseable catalog used to be silently rebuilt from nothing - which is
        /// the path that turned a 4,120-entry github_catalog.json into a 127-entry one. The temp file
        /// sits in the target's own directory so Replace/Move stay on one volume.
        /// </summary>
        private static void WriteFileAtomic(string path, string text)
        {
            string tmp = path + ".tmp";
            System.IO.File.WriteAllText(tmp, text);
            try
            {
                if (System.IO.File.Exists(path)) System.IO.File.Replace(tmp, path, null);
                else                             System.IO.File.Move(tmp, path);
            }
            catch
            {
                // The rename failed, so the temp file is the only thing this call produced. Left
                // behind it would drop a github_catalog.json.tmp beside the real one in Templates -
                // harmless to the reader, but it looks like a half-finished write to anyone looking
                // at the folder. Rethrow so the caller still falls back to the per-user copy.
                try { System.IO.File.Delete(tmp); } catch { }
                throw;
            }
        }

        /// <summary>
        /// True when the Templates copy of <paramref name="fileName"/> exists AND parses as a
        /// non-empty JSON array - i.e. it was genuinely read, so rewriting it as "itself plus the new
        /// entries" cannot lose anything.
        ///
        /// This is the guard on a rule the code did not previously state: the app may APPEND to a
        /// shipped catalog, but it must never author one from scratch and never replace one it failed
        /// to read. Both readers (ReadFile here, Load in WingetHiddenIds) swallow every exception and
        /// return an empty list, so "file is missing" and "file is corrupt" arrived at the writer
        /// looking identical - and the writer then wrote the empty result back over Templates.
        /// Deliberately type-agnostic: it answers "is there an intact array here", which is the only
        /// question the writer needs, and so covers github_catalog.json and winget_noninstaller.json
        /// with one implementation.
        /// </summary>
        private static bool TemplatesCatalogIsIntact(string fileName)
        {
            string templates = System.IO.Path.Combine(
                System.IO.Path.GetDirectoryName(JsonPath) ?? "", fileName);
            if (!System.IO.File.Exists(templates))
            {
                LogWinget($"[Catalog] {fileName}: not present in Templates - discoveries go to the " +
                          $"per-user copy. The shipped catalog is never created by the app.");
                return false;
            }
            try
            {
                using var doc = System.Text.Json.JsonDocument.Parse(
                    System.IO.File.ReadAllText(templates),
                    new System.Text.Json.JsonDocumentOptions
                    {
                        CommentHandling  = System.Text.Json.JsonCommentHandling.Skip,
                        AllowTrailingCommas = true,
                    });
                if (doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Array
                    && doc.RootElement.GetArrayLength() > 0) return true;
                LogWinget($"[Catalog] {fileName}: Templates copy is an empty array - left untouched");
                return false;
            }
            catch (Exception ex)
            {
                LogWinget($"[Catalog] {fileName}: Templates copy could not be parsed ({ex.Message}) " +
                          $"- it will NOT be overwritten; discoveries go to the per-user copy");
                return false;
            }
        }

        // Where a reference file is WRITTEN. TemplateFile answers where to read one from; this is the
        // other half of the question, and the two have different answers.
        //
        // Templates is the right home: one shared copy per machine, beside AutoPackage.json, where an
        // admin would look for it. But it lives under Program Files, which is read-only for a standard
        // user on a default install. So Templates is tried first and, if the write is refused, the
        // content goes to a per-user fallback that is always writable and is also read.
        //
        // allowTemplates = false skips the shared copy entirely. Callers pass false when
        // TemplatesCatalogIsIntact said the shared file could not be read: writing there would replace
        // a catalog the app cannot see with one built from the part of it that it can.
        //
        // Returns the path actually written, or null when neither location took it.
        private static string? WriteCatalogFile(string templatesFileName, string fallbackPath, string json,
                                                bool allowTemplates = true)
        {
            string templates = System.IO.Path.Combine(
                System.IO.Path.GetDirectoryName(JsonPath) ?? "", templatesFileName);
            if (allowTemplates)
            {
                try
                {
                    WriteFileAtomic(templates, json);
                    return templates;
                }
                catch (Exception exTemplates)
                {
                    LogWinget($"[Catalog] {templatesFileName}: Templates is not writable ({exTemplates.Message}) " +
                              $"- writing the per-user copy instead");
                }
            }

            try
            {
                System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(fallbackPath)!);
                WriteFileAtomic(fallbackPath, json);
                return fallbackPath;
            }
            catch (Exception exFallback)
            {
                LogWinget($"[Catalog] {templatesFileName}: could not be written anywhere ({exFallback.Message})");
            }
            return null;
        }

        /// <summary>Per-user additions to the non-installer list, for when Templates is read-only.</summary>
        private static string WingetHiddenExtraPath => System.IO.Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "SwiftPack", "winget", "winget_noninstaller_extra.json");

        // Package ids that are NOT MSI/EXE installers (zip / portable-in-zip / MSIX-only). The winget
        // picker hides these so it only offers packages SwiftPack can actually package.
        //
        // Read as the UNION of the shipped list in Templates and the per-user additions file, the same
        // way the GitHub catalog reads base + extra. Union, not first-one-wins, because a Check now on
        // a machine where Templates is read-only has to be able to add to the list at all - and
        // TemplateFile would otherwise keep returning the untouched Templates copy and ignore it.
        private static HashSet<string>? _wingetHide;
        /// <summary>
        /// True when a catalog entry is a pre-release (beta) build rather than the shipping product.
        ///
        /// Both fields are checked, because the two carry it differently:
        ///   id    AgileBits.1Password.Beta, ArduinoSA.IDE.beta   a dotted segment that IS "beta"
        ///   name  1Password Beta, Android Studio Beta            a whole word
        ///   name  DpzxbrowseBeta                                 appended in camelCase
        ///
        /// Deliberately NOT a plain Contains("beta"). Checked against the 4,120-entry
        /// github_catalog.json, that would wrongly remove five real products: Betaflight
        /// Configurator, axcore/tartube, both of GPBeta's SAO Utils (the vendor handle is
        /// literally "GPBeta"), MrMYHuang.cbetar2, and PikeNote's Taskbar Groups, whose repo
        /// merely ends in -beta. Every rule below needs a separator or a case change, so all
        /// five survive and DpzxbrowseBeta is the only entry removed.
        ///
        /// The repo is not examined on purpose: taskbar-groups-pike-beta is the repository's
        /// name, not the product's, and the app it ships is the ordinary Taskbar Groups.
        /// </summary>
        private static bool IsBetaPackage(string? id, string? name)
        {
            string i = (id ?? "").Trim();
            string n = (name ?? "").Trim();

            // A whole separated segment equal to "beta": AgileBits.1Password.Beta, foo-beta, foo_beta.
            foreach (var seg in i.Split('.', '-', '_', '/'))
                if (seg.Equals("beta", StringComparison.OrdinalIgnoreCase)) return true;

            if (n.Length == 0) return false;

            // "1Password Beta". Betaflight and Betamax are untouched: the word boundary after "beta"
            // fails when a letter follows.
            if (System.Text.RegularExpressions.Regex.IsMatch(
                    n, @"\bbeta\b", System.Text.RegularExpressions.RegexOptions.IgnoreCase)) return true;

            // "DpzxbrowseBeta" - appended with no separator, so only a capital B directly after a
            // lowercase letter counts. Case-sensitive by design; "Betaflight" has nothing before
            // the B and is left alone.
            if (System.Text.RegularExpressions.Regex.IsMatch(n, @"[a-z]Beta\b")) return true;

            return false;
        }

        private static HashSet<string> WingetHiddenIds()
        {
            if (_wingetHide != null) return _wingetHide;
            var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            void Load(string? path)
            {
                try
                {
                    if (path == null || !System.IO.File.Exists(path)) return;
                    var ids = System.Text.Json.JsonSerializer.Deserialize<List<string>>(
                        System.IO.File.ReadAllText(path), _catalogReadOptions);
                    foreach (var id in ids ?? new List<string>())
                        if (!string.IsNullOrWhiteSpace(id)) set.Add(id.Trim());
                }
                catch { }
            }

            Load(TemplateFile("winget_noninstaller.json"));
            Load(WingetHiddenExtraPath);
            _wingetHide = set;
            return _wingetHide;
        }

        /// <summary>
        /// Adds newly-found non-installer package ids to the list and writes it back, preferring the
        /// shared copy in Templates. Called from Check now, where every new package's manifest has
        /// just been read anyway - the answer was already known there and simply discarded.
        /// Returns the ids actually added.
        /// </summary>
        private static List<string> AddWingetNonInstallerIds(IEnumerable<string> ids)
        {
            var added = new List<string>();
            try
            {
                var known = new HashSet<string>(WingetHiddenIds(), StringComparer.OrdinalIgnoreCase);
                foreach (var id in ids)
                {
                    string t = (id ?? "").Trim();
                    if (t.Length > 0 && known.Add(t)) added.Add(t);
                }
                if (added.Count == 0) return added;

                // Ordinal order, one id per line. It was written as a single 57 KB line, matching how
                // the file shipped, but 2,500 ids on one line cannot be read or diffed by anyone.
                // Relaxed encoder so "ChuyuTeam.DISM++" stays itself instead of becoming
                // "ChuyuTeam.DISM\u002B\u002B".
                string json = System.Text.Json.JsonSerializer.Serialize(
                    known.OrderBy(x => x, StringComparer.Ordinal).ToList(),
                    new System.Text.Json.JsonSerializerOptions
                    {
                        WriteIndented = true,
                        Encoder       = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
                    });

                string nlH = Environment.NewLine;
                string header = string.Join(nlH, new[]
                {
                    "// winget_noninstaller.json - winget package ids that are NOT MSI/EXE installers:",
                    "// zips, portable apps and MSIX-only packages. SwiftPack cannot package these, so",
                    "// the winget picker and the New Apps list hide them.",
                    "//",
                    "// The shipped list grows on this machine: \"Check now\" reads each newly-added",
                    "// package's manifest from https://raw.githubusercontent.com/microsoft/winget-pkgs",
                    "// and records the verdict here. When this Templates copy is not writable",
                    "// (Program Files, standard user), additions go to",
                    "// %LocalAppData%\\SwiftPack\\winget\\winget_noninstaller_extra.json; the app reads",
                    "// the union of both, at startup.",
                    "//",
                    "// Removing an id makes the picker offer that package again after a restart.",
                }) + nlH;

                string? written = WriteCatalogFile(
                    "winget_noninstaller.json", WingetHiddenExtraPath, header + json,
                    // Same trap as the GitHub catalog: WingetHiddenIds' Load swallows a parse
                    // failure and returns nothing, so `known` would carry only the per-user ids
                    // and the new finds. Writing that to Templates would drop the shipped 2,500.
                    allowTemplates: TemplatesCatalogIsIntact("winget_noninstaller.json"));
                _wingetHide = null;   // rebuilt from disk on the next read
                LogWinget($"[Catalog] {added.Count} non-installer package(s) added to {written ?? "nowhere"}");
            }
            catch (Exception ex) { LogWinget($"[Catalog] non-installer list not updated: {ex.Message}"); }
            return added;
        }

        // GitHub-app catalog and picker (mirrors the winget catalog and picker above).
        // Winget packages whose installer is hosted on GitHub releases, so the GitHub Repo field gets
        // the same searchable picker the Winget Package ID has. Loaded once from github_catalog.json
        // (placed next to the winget index) - purely local, no network, no rate limit.
        internal sealed class GitHubApp
        {
            public string Repo    { get; set; } = "";
            public string Vendor  { get; set; } = "";
            public string Name    { get; set; } = "";
            public string Version { get; set; } = "";
            public string Id      { get; set; } = "";   // winget package id, for fetching silent switches
            public override string ToString() => Repo;
        }

        private static class GitHubCatalog
        {
            private static List<GitHubApp>? _apps;

            // Auto-discovered GitHub apps (new GitHub-hosted winget packages found on Check now) live in
            // a WRITABLE file beside the winget index, so the read-only base catalog in Templates is
            // never touched and Program-Files permissions never block a write. The catalog the picker
            // sees is base + extra, deduped by repo.
            private static string ExtraPath => System.IO.Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "SwiftPack", "winget", "github_catalog_extra.json");

            /// <summary>
            /// Writes the catalog in the shipped file's own layout, byte for byte: no indentation,
            /// one field per line, fields in the order repo / vendor / name / version / id, and the
            /// closing brace of the last entry followed by "]" with no trailing newline.
            ///
            /// Hand-built rather than left to WriteIndented, which indents two spaces and would
            /// rewrite all 28,000 lines of a file people read and diff. The encoder is the relaxed
            /// one for the same reason: the default escapes "+" to \u002B and every non-ASCII
            /// character to \uXXXX, so a package id containing "+" and the CJK names in the file would
            /// come back unrecognisable. Values are serialized one at a time, never by splitting the
            /// object on commas, so a comma inside a name cannot break the layout.
            /// </summary>
            private static string SerializeCatalog(List<GitHubApp> apps)
            {
                var opts = new System.Text.Json.JsonSerializerOptions
                {
                    Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
                };
                string Q(string? v) => System.Text.Json.JsonSerializer.Serialize(v ?? "", opts);

                var sb = new System.Text.StringBuilder(apps.Count * 128);
                sb.Append("[\n");
                for (int i = 0; i < apps.Count; i++)
                {
                    var a = apps[i];
                    sb.Append("{\n")
                      .Append("\"repo\":").Append(Q(a.Repo)).Append(",\n")
                      .Append("\"vendor\":").Append(Q(a.Vendor)).Append(",\n")
                      .Append("\"name\":").Append(Q(a.Name)).Append(",\n")
                      .Append("\"version\":").Append(Q(a.Version)).Append(",\n")
                      .Append("\"id\":").Append(Q(a.Id)).Append("\n")
                      .Append(i == apps.Count - 1 ? "}\n" : "},\n");
                }
                sb.Append("]");
                return sb.ToString();
            }

            private static List<GitHubApp> ReadFile(string? path)
            {
                try
                {
                    if (path != null && System.IO.File.Exists(path))
                        return System.Text.Json.JsonSerializer.Deserialize<List<GitHubApp>>(
                            System.IO.File.ReadAllText(path),
                            SourceDownloadPage._catalogReadOptions) ?? new List<GitHubApp>();
                }
                catch (Exception ex)
                {
                    // A silent catch here is how a corrupt catalog looked exactly like a missing one.
                    // The writer no longer trusts this result (see TemplatesCatalogIsIntact), but the
                    // reason still has to reach the log or the picker just quietly gets shorter.
                    SourceDownloadPage.LogWinget(
                        $"[Catalog] {System.IO.Path.GetFileName(path)} could not be read ({ex.Message})");
                }
                return new List<GitHubApp>();
            }

            // Deduped by winget ID, not by repo. Repo used to be the key because the picker returns a
            // repo string and two rows showing the same one look identical - but 157 repos publish
            // more than one winget package between them (400 entries collapsing to 157 rows), and the
            // survivor was simply whichever sorted first. That hid AdoptOpenJDK's Hotspot build behind
            // its OpenJ9 build, and hid Past Paper Manager behind a root certificate that happened to
            // share its repo, with no way to reach either from this picker. Id is unique across all
            // 4,120 entries, so keying on it gives one row per package; the Name column is what tells
            // two rows sharing a repo apart, and the selection carries its own Id back to the caller.
            private static List<GitHubApp> All()
            {
                if (_apps != null) return _apps;
                var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var merged = new List<GitHubApp>();
                var baseApps  = ReadFile(SourceDownloadPage.TemplateFile("github_catalog.json"));
                var extraApps = ReadFile(ExtraPath);
                // Same rule the file's own rewrite uses (see AddDiscovered): a blank Id cannot be
                // deduped against anything, so it is kept rather than silently dropped. A blank Repo
                // still goes - selecting such a row would hand back an empty repo.
                foreach (var a in baseApps.Concat(extraApps))
                    if (a.Repo.Length > 0 && (a.Id.Length == 0 || seen.Add(a.Id))) merged.Add(a);
                _apps = merged;
                // Said out loud, because the only previous evidence of a collapsed catalog was a
                // small number in the picker's footer, which reads like a search result rather than
                // like a missing file. The shipped list is ~4,120; anything near a hundred here means
                // the Templates copy is absent or unreadable and only discoveries are being listed.
                SourceDownloadPage.LogWinget(
                    $"[Catalog] GitHub picker: {merged.Count} app(s) " +
                    $"(shipped {baseApps.Count}, per-user {extraApps.Count})");
                return _apps;
            }

            internal static bool Available => All().Count > 0;

            internal static List<GitHubApp> Search(string query, int max = 20000)
            {
                var all = All();
                query = (query ?? "").Trim();
                if (query.Length == 0) return all.Take(max).ToList();
                return all.Where(a =>
                        a.Name.IndexOf(query, StringComparison.OrdinalIgnoreCase) >= 0 ||
                        a.Vendor.IndexOf(query, StringComparison.OrdinalIgnoreCase) >= 0 ||
                        a.Repo.IndexOf(query, StringComparison.OrdinalIgnoreCase) >= 0)
                    .Take(max).ToList();
            }

            // Adds newly-discovered GitHub apps (deduped against everything already known) and drops
            // the cache so the next read picks them up. Returns the ones actually added.
            //
            // Written to the SHARED catalog in Templates when that folder allows it, so there is one
            // file per machine rather than a copy per user profile, and an admin editing
            // github_catalog.json sees everything Check now has found. Where Program Files is
            // read-only - the default - it falls back to the per-user extra file exactly as before.
            //
            // What gets written is base + extra + the new ones, already deduped, so whichever file
            // receives it is complete on its own and the reader still merges both.
            internal static List<GitHubApp> AddDiscovered(IEnumerable<GitHubApp> found)
            {
                var added = new List<GitHubApp>();
                try
                {
                    // Keyed on Id, matching All() and the merge below. Keying on Repo meant a newly
                    // published package was thrown away whenever ANY package from that repo was
                    // already listed - so the catalog could gain 7-Zip but never 7zr, and could never
                    // pick up a second edition of a tool it already knew. Nothing was logged; the
                    // package just never appeared.
                    var known = new HashSet<string>(All().Select(a => a.Id), StringComparer.OrdinalIgnoreCase);
                    foreach (var a in found)
                        if (a.Repo.Length > 0 && a.Id.Length > 0 && known.Add(a.Id)) added.Add(a);
                    if (added.Count == 0) return added;

                    // Rebuilt from the FILES, not from All(): All() is a merge of the two on-disk
                    // lists, so writing it back would silently drop anything the reader skipped.
                    // Id is unique across all 4,120 entries; Repo is not - 157 repos cover 400 of
                    // them, which is why Repo is a display field here and never a key.
                    var merged  = new List<GitHubApp>();
                    var seenIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    var baseApps = ReadFile(SourceDownloadPage.TemplateFile("github_catalog.json"));
                    foreach (var a in baseApps
                                      .Concat(ReadFile(ExtraPath))
                                      .Concat(added))
                        if (a.Id.Length == 0 || seenIds.Add(a.Id)) merged.Add(a);

                    // Vendor order, which is how the shipped file is already sorted, and camelCase
                    // keys, which is how it is already written. Rewriting 4,120 entries in PascalCase
                    // would still load - the reader is case-insensitive - but it would churn every
                    // line of a file that people read and diff.
                    merged = merged.OrderBy(a => a.Vendor, StringComparer.OrdinalIgnoreCase)
                                   .ThenBy(a => a.Name,   StringComparer.OrdinalIgnoreCase).ToList();

                    string json = SerializeCatalog(merged);

                    string nl = Environment.NewLine;
                    string header = string.Join(nl, new[]
                    {
                        "// github_catalog.json - the catalog behind the GitHub Repo picker on the Auto",
                        "// Package Download tab: winget packages whose installers are hosted on GitHub",
                        "// releases (owner/repo plus vendor / name / version / winget id).",
                        "//",
                        "// The shipped list grows on this machine: \"Check now\" reads each newly-added",
                        "// package's manifest from",
                        "// https://raw.githubusercontent.com/microsoft/winget-pkgs and the ones whose",
                        "// InstallerUrl points at github.com are added here. When this Templates copy is",
                        "// not writable (Program Files, standard user), additions go to",
                        "// %LocalAppData%\\SwiftPack\\winget\\github_catalog_extra.json; the picker reads",
                        "// the union of both.",
                        "//",
                        "// Safe to edit by hand - entries are deduped by winget id when rewritten, and",
                        "// edits are picked up the next time the app starts.",
                    }) + nl;

                    string? written = SourceDownloadPage.WriteCatalogFile(
                        "github_catalog.json", ExtraPath, header + json,
                        // Append to the shipped catalog only when it was actually read. Absent or
                        // unparseable means merged holds the extra file plus the new finds and
                        // NOTHING of the shipped list, so writing it to Templates would replace the
                        // catalog with the fraction of it currently visible.
                        //
                        // BOTH conditions, because they answer different questions.
                        // TemplatesCatalogIsIntact asks about the file that would be WRITTEN (the
                        // Templates path); baseApps asks whether the file that was READ actually
                        // deserialized. They can disagree: TemplateFile falls through to the
                        // per-user copy when Templates is missing, and JsonDocument accepts array
                        // shapes that Deserialize<List<GitHubApp>> rejects. Either disagreement
                        // alone would let the shared copy shrink.
                        allowTemplates: baseApps.Count > 0
                                     && SourceDownloadPage.TemplatesCatalogIsIntact("github_catalog.json"));
                    _apps = null;   // force a merged reload on next access
                    SourceDownloadPage.LogWinget($"[Catalog] {added.Count} GitHub app(s) added to {written ?? "nowhere"}");
                }
                catch (Exception ex) { SourceDownloadPage.LogWinget($"[Catalog] GitHub catalog not updated: {ex.Message}"); }
                return added;
            }
        }

        // Searchable picker over the local GitHub-app catalog, mirroring the winget picker exactly
        // (same window, slow touchpad scroll, column-fill). Returns the chosen app (owner/repo plus
        // vendor / name / version), or null. There is no installer-type footer - GitHub apps do not
        // need it.
        private GitHubApp? PickGitHubApp(string initialQuery)
        {
            var winBg     = Res("WindowBgBrush",     Brushes.White);
            var borderClr = Res("BorderMainBrush",   Brushes.LightGray);
            var lblFg     = Res("TextSecondaryBrush", Brushes.Gray);
            var valFg     = Res("TextPrimaryBrush",  Brushes.Black);
            GitHubApp? result = null;

            var win = new Window
            {
                Width = 800, Height = 420,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = Window.GetWindow(this),
                ResizeMode = ResizeMode.NoResize,
                WindowStyle = WindowStyle.None,
                AllowsTransparency = true,
                Background = Brushes.Transparent,
                ShowInTaskbar = false,
            };
            var outer = new Border
            {
                Background = winBg, BorderBrush = borderClr, BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(10),
            };
            win.Content = outer;

            var g = new Grid { Margin = new Thickness(16) };
            g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            g.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            outer.Child = g;

            var title = new TextBlock
            {
                Text = "GitHub Repo", FontSize = 13, FontWeight = FontWeights.SemiBold,
                Foreground = valFg, Margin = new Thickness(0, 0, 0, 2), VerticalAlignment = VerticalAlignment.Center,
            };
            title.MouseLeftButtonDown += (_, _) => win.DragMove();
            var titleClose = new Button
            {
                Content = "\u2715", FontSize = 12, Width = 24, Height = 24, Padding = new Thickness(0),
                Background = Brushes.Transparent, BorderThickness = new Thickness(0),
                Foreground = lblFg, Cursor = System.Windows.Input.Cursors.Hand, ToolTip = "Close",
                VerticalAlignment = VerticalAlignment.Top, HorizontalAlignment = HorizontalAlignment.Right,
            };
            titleClose.Click += (_, _) => win.Close();
            var titleBar = new Grid();
            titleBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            titleBar.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            Grid.SetColumn(title, 0); Grid.SetColumn(titleClose, 1);
            titleBar.Children.Add(title); titleBar.Children.Add(titleClose);
            Grid.SetRow(titleBar, 0); g.Children.Add(titleBar);

            var search = new TextBox
            {
                Text = initialQuery, FontSize = 11, Height = 28,
                Padding = new Thickness(8, 0, 8, 0),
                VerticalContentAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 6, 0, 6),
                BorderBrush = borderClr, BorderThickness = new Thickness(1),
                Foreground = valFg,
            };
            if (TryFindResource("ModernTextBoxStyle") is Style ts) search.Style = ts;
            search.SetResourceReference(TextBox.BackgroundProperty, "InputBgBrush");
            Grid.SetRow(search, 1); g.Children.Add(search);

            var list = new ListView { FontSize = 11, Foreground = valFg, BorderBrush = borderClr };
            list.SetResourceReference(ListView.BackgroundProperty, "InputBgBrush");
            var gv = new GridView();
            gv.Columns.Add(new GridViewColumn { Header = "Vendor",  Width = 150, DisplayMemberBinding = new System.Windows.Data.Binding("Vendor") });
            gv.Columns.Add(new GridViewColumn { Header = "Name",    Width = 220, DisplayMemberBinding = new System.Windows.Data.Binding("Name") });
            gv.Columns.Add(new GridViewColumn { Header = "GitHub Repo", Width = 250, DisplayMemberBinding = new System.Windows.Data.Binding("Repo") });
            gv.Columns.Add(new GridViewColumn { Header = "Version", Width = 95,  DisplayMemberBinding = new System.Windows.Data.Binding("Version") });
            list.View = gv;
            Grid.SetRow(list, 2); g.Children.Add(list);

            double pickWheelAccum = 0;
            list.PreviewMouseWheel += (_, me) =>
            {
                var sv = FindVisualChild<ScrollViewer>(list);
                if (sv == null) return;
                pickWheelAccum += me.Delta / 120.0;
                int rows = (int)pickWheelAccum;
                if (rows != 0)
                {
                    sv.ScrollToVerticalOffset(sv.VerticalOffset - rows);
                    pickWheelAccum -= rows;
                }
                me.Handled = true;
            };

            list.Loaded += (_, _) => list.Dispatcher.BeginInvoke(new Action(() =>
            {
                double others = gv.Columns[0].Width + gv.Columns[1].Width + gv.Columns[3].Width;
                double fill = list.ActualWidth - others - 26;
                if (fill > 180) gv.Columns[2].Width = fill;   // GitHub Repo absorbs the leftover width
            }), System.Windows.Threading.DispatcherPriority.Loaded);

            var hint = new TextBlock
            {
                Text = "", FontSize = 10, FontStyle = FontStyles.Italic,
                Foreground = lblFg, Margin = new Thickness(0, 6, 0, 0),
            };

            void Refresh()
            {
                // Same rule as the winget picker. Left unfiltered, this one would still offer
                // DpzxbrowseBeta, since Check now writes GitHub-hosted discoveries into
                // github_catalog.json and this picker reads straight from that file.
                var hits = GitHubCatalog.Search(search.Text?.Trim() ?? "")
                    .Where(a => !IsBetaPackage(a.Id, a.Name)).ToList();
                list.ItemsSource = hits;
                hint.Text = !GitHubCatalog.Available
                    ? "github_catalog.json not found - place it in the app's Templates folder"
                    : hits.Count == 0 ? "no match in the catalog" : $"{hits.Count:N0} app(s)";
            }
            search.TextChanged += (_, _) => Refresh();
            list.MouseDoubleClick += (_, _) =>
            {
                if (list.SelectedItem is GitHubApp a) { result = a; win.Close(); }
            };

            var bar = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = HorizontalAlignment.Right,
                Margin = new Thickness(0, 10, 0, 0),
            };
            var bCancel = new Button { Content = "✕  Cancel", FontSize = 11, Height = 28, Width = 92, Margin = new Thickness(0, 0, 8, 0), Cursor = System.Windows.Input.Cursors.Hand };
            if (TryFindResource("SecondaryButtonStyle") is Style sb) bCancel.Style = sb;
            bCancel.Click += (_, _) => win.Close();

            var bOk = new Button { Content = "✔  Select", FontSize = 11, Height = 28, Width = 92, Cursor = System.Windows.Input.Cursors.Hand };
            if (TryFindResource("ActionBtnStyle") is Style ab) bOk.Style = ab;
            bOk.Click += (_, _) =>
            {
                if (list.SelectedItem is GitHubApp a) { result = a; win.Close(); }
            };
            bar.Children.Add(bCancel); bar.Children.Add(bOk);

            var bottom = new Grid();
            bottom.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            bottom.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            Grid.SetColumn(hint, 0); Grid.SetColumn(bar, 1);
            bottom.Children.Add(hint); bottom.Children.Add(bar);
            Grid.SetRow(bottom, 3); g.Children.Add(bottom);

            Refresh();
            search.Focus();
            search.CaretIndex = search.Text.Length;
            win.ShowDialog();
            return result;
        }

        /// <summary>
        /// The nearest scrollable ScrollViewer above the element under the mouse pointer.
        ///
        /// Walks the VISUAL tree upward from Mouse.DirectlyOver, so it naturally lands on whichever
        /// ScrollViewer the pointer is really inside - the vendor list, the package panel, or an OPEN
        /// COMBOBOX DROPDOWN, whose ScrollViewer lives under its own PopupRoot and could never have
        /// been reached by hooking the page's own ScrollViewers.
        ///
        /// Skips ScrollViewers that cannot scroll vertically (ScrollableHeight == 0) - otherwise an
        /// inner non-scrolling one, like the horizontal category strip, would swallow the wheel and
        /// the panel behind it would never move.
        /// </summary>
        private static ScrollViewer? ScrollViewerUnderMouse()
        {
            DependencyObject? d = System.Windows.Input.Mouse.DirectlyOver as DependencyObject;
            while (d != null)
            {
                if (d is ScrollViewer sv && sv.ScrollableHeight > 0) return sv;
                d = d is Visual || d is System.Windows.Media.Media3D.Visual3D
                    ? System.Windows.Media.VisualTreeHelper.GetParent(d)
                    : null;
            }
            return null;
        }

        private static string InfoKey(DownloadSourceEntry a) =>
            (a.SourceAppVendor ?? "") + "|" + (a.SourceAppName ?? "");

        /// <summary>
        /// Selects an app that may belong to a DIFFERENT vendor than the one currently shown - used by
        /// the Downloads window and by the scheduler.
        ///
        /// SelectApp alone is not enough: it calls RenderCards but never RenderVendors, because a
        /// normal click comes from a vendor the user already selected. Jumping in from outside left
        /// the vendor column on the old vendor - which is why double-clicking LibreOffice showed
        /// LibreOffice in the panel while the vendor list still sat on Foxit, with "The Document
        /// Foundation" not even scrolled into view.
        /// </summary>
        private void SelectAppAnyVendor(DownloadSourceEntry app)
        {
            _selectedVendor = app.SourceAppVendor;
            RenderVendors();                              // move the highlight to the right vendor
            SelectApp(app);
            ScrollVendorIntoView(app.SourceAppVendor);    // ...and make sure it is actually on screen
        }

        /// <summary>Scrolls the vendor list so the given vendor is visible.</summary>
        private void ScrollVendorIntoView(string vendor)
        {
            try
            {
                foreach (var child in PnlVendors.Children)
                    if (child is FrameworkElement fe
                        && fe.Tag is string v
                        && string.Equals(v, vendor, StringComparison.OrdinalIgnoreCase))
                    {
                        fe.BringIntoView();
                        return;
                    }
            }
            catch (Exception ex) { LogWinget($"[Vendors] scroll failed: {ex.Message}"); }
        }

        // ── Keyboard navigation for the Vendor / Application columns ───────
        // The lists are code-built Borders, not ListBoxes, so arrow keys did nothing.
        // Clicking a vendor or app card arms its column and focuses the page; Up/Down
        // then move the selection through that column exactly like clicks would.
        private string _kbNavColumn = "vendor";

        private void ScrollCardIntoView(string appName)
        {
            try
            {
                foreach (var child in PnlCards.Children)
                    if (child is FrameworkElement fe
                        && fe.Tag is string n
                        && string.Equals(n, appName, StringComparison.OrdinalIgnoreCase))
                    {
                        fe.BringIntoView();
                        return;
                    }
            }
            catch (Exception ex) { LogWinget($"[Cards] scroll failed: {ex.Message}"); }
        }

        private void NavigateVendor(int dir)
        {
            // Mirror RenderVendors' filters and order exactly, so "next" on screen and
            // "next" on the keyboard can never disagree.
            var keys = _allApps
                .Where(a => _activeCategory == "All" || a.Category == _activeCategory)
                .Where(a => string.IsNullOrWhiteSpace(_searchText)
                         || a.SourceAppName.Contains(_searchText,  StringComparison.OrdinalIgnoreCase)
                         || a.SourceAppVendor.Contains(_searchText,   StringComparison.OrdinalIgnoreCase))
                .GroupBy(a => a.SourceAppVendor)
                .OrderBy(g => g.Key)
                .Select(g => g.Key)
                .ToList();
            if (keys.Count == 0) return;
            int i  = keys.FindIndex(k => k == _selectedVendor);
            int ni = Math.Clamp(i + dir, 0, keys.Count - 1);
            if (ni == i && i >= 0) return;
            SelectVendorByName(keys[ni < 0 ? 0 : ni]);
            ScrollVendorIntoView(_selectedVendor);
        }

        private void NavigateApp(int dir)
        {
            // Mirror RenderCards' filters and order exactly.
            var apps = _allApps
                .Where(a => a.SourceAppVendor == _selectedVendor)
                .Where(a => _activeCategory == "All" || a.Category == _activeCategory)
                .Where(a => string.IsNullOrWhiteSpace(_searchText)
                         || a.SourceAppName.Contains(_searchText,  StringComparison.OrdinalIgnoreCase)
                         || a.SourceAppVendor.Contains(_searchText,   StringComparison.OrdinalIgnoreCase))
                .OrderBy(a => a.SourceAppName)
                .ToList();
            if (apps.Count == 0) return;
            int i  = _selectedApp != null ? apps.IndexOf(_selectedApp) : -1;
            int ni = Math.Clamp(i + dir, 0, apps.Count - 1);
            if (ni == i && i >= 0) return;
            SelectApp(apps[ni < 0 ? 0 : ni]);
            ScrollCardIntoView(_selectedApp?.SourceAppName ?? "");
        }

        private void OnColumnKeyNav(object sender, System.Windows.Input.KeyEventArgs e)
        {
            if (e.Key is not (System.Windows.Input.Key.Down or System.Windows.Input.Key.Up)) return;
            // Arrows belong to any control that actually uses them for editing/selection.
            if (System.Windows.Input.Keyboard.FocusedElement is
                System.Windows.Controls.Primitives.TextBoxBase or ComboBox or ComboBoxItem or PasswordBox or Slider)
                return;
            // The columns lock while a download runs; the keyboard must honour that too.
            if (PnlVendors == null || !PnlVendors.IsEnabled) return;

            int dir = e.Key == System.Windows.Input.Key.Down ? +1 : -1;
            if (_kbNavColumn == "app") NavigateApp(dir); else NavigateVendor(dir);
            e.Handled = true;
        }

        private void SelectApp(DownloadSourceEntry app)
        {
            _lastSelectedVendor  = app.SourceAppVendor;
            _lastSelectedAppName = app.SourceAppName;
            _selectedApp = app;
            RenderCards();
            TxtInfoTitle.Visibility = Visibility.Visible;
            PnlInfoPlaceholder.Visibility = Visibility.Collapsed;
            PnlAppInfo.Visibility         = Visibility.Visible;

            // Cache hit → render immediately, no placeholder, no network round-trip
            LoadInfoCache();
            if (_infoCache.TryGetValue(InfoKey(app), out var hit) &&
                DateTime.UtcNow - hit.At < _infoCacheTtl)
            {
                RenderInfoPanel(hit.Info);
                return;
            }

            PnlAppInfo.Children.Clear();
            var mutFg = Res("TextMutedBrush", Brushes.DarkGray);
            PnlAppInfo.Children.Add(new TextBlock { Text = "⏳  Fetching latest version info...", FontSize = 11, Foreground = mutFg, FontStyle = FontStyles.Italic });
            _ = FetchAndShowAsync(app);
        }

        private async Task FetchAndShowAsync(DownloadSourceEntry app)
        {
            AppDownloadInfo info;
            try
            {
                info = app.ApiType switch
                {
                    "winget"       => await FetchWingetAsync(app),
                    "github"       => await FetchGitHubAsync(app),
                    "Vendor API"   => await FetchVendorApiAsync(app),
                    _              => FallbackInfo(app),
                };
            }
            catch { info = FallbackInfo(app); }

            // Only cache a result that actually carries links. A failed fetch returns an empty
            // FallbackInfo, and storing THAT is what made the download buttons disappear: one 403
            // wiped links we already had and pinned the emptiness for the whole TTL.
            //
            // On failure, keep serving the last known good entry instead - stale links beat none, and
            // the app keeps working straight through a rate-limit window.
            string key = InfoKey(app);
            LoadInfoCache();
            if (info.Links.Count > 0)
            {
                _infoCache[key] = (info, DateTime.UtcNow);
                SaveInfoCacheDebounced();
            }
            else if (_infoCache.TryGetValue(key, out var lastGood) && lastGood.Info.Links.Count > 0)
            {
                LogWinget($"[InfoCache] {app.SourceAppName}: fetch failed, serving cached links from {lastGood.At:yyyy-MM-dd HH:mm}");
                info = lastGood.Info;
            }
            Dispatcher.BeginInvoke(new Action(() =>
            {
                // Don't overwrite the panel if the user has already moved on
                if (!ReferenceEquals(_selectedApp, app)) return;
                RenderInfoPanel(info);
            }), System.Windows.Threading.DispatcherPriority.Normal);
        }

        // ── API Fetchers ───────────────────────────────────────────────────
        private async Task<AppDownloadInfo> FetchGitHubAsync(DownloadSourceEntry app)
        {
            if (string.IsNullOrWhiteSpace(app.GitHubRepo)) return FallbackInfo(app);
            // Authenticated when a token is configured (5,000/hr instead of 60/hr), and conditional -
            // a 304 means the release has not changed, so keep the cached info and spend nothing.
            string? json = await GitHubGetAsync($"https://api.github.com/repos/{app.GitHubRepo}/releases/latest");
            if (json == null)
            {
                LogWinget($"[GitHub] {app.GitHubRepo}: 304 not modified - serving cached info");
                LoadInfoCache();
                if (_infoCache.TryGetValue(InfoKey(app), out var unchanged) && unchanged.Info.Links.Count > 0)
                    return unchanged.Info;
                return FallbackInfo(app);
            }
            var doc  = JsonDocument.Parse(json);
            string v = doc.RootElement.GetProperty("tag_name").GetString()?.TrimStart('v') ?? "";

            var links = new List<DownloadLink>();
            var seen  = new HashSet<string>(); // deduplicate by TYPE-ARCH key

            foreach (var asset in doc.RootElement.GetProperty("assets").EnumerateArray())
            {
                string name = asset.GetProperty("name").GetString() ?? "";
                string url  = asset.GetProperty("browser_download_url").GetString() ?? "";

                // Skip non-installer files
                if (name.EndsWith(".sha256") || name.EndsWith(".asc")    || name.EndsWith(".sig")
                 || name.EndsWith(".md5")    || name.EndsWith(".sha1")   || name.Contains("debug")
                 || name.EndsWith(".7z")     || name.EndsWith(".zip")    || name.EndsWith(".tar.gz")
                 || name.EndsWith(".tar.bz2")|| name.Contains("source")  || name.EndsWith(".txt")
                 || name.EndsWith(".xml")    || name.EndsWith(".json"))
                    continue;

                string type = name.EndsWith(".msi", StringComparison.OrdinalIgnoreCase) ? "MSI"
                            : name.EndsWith(".exe", StringComparison.OrdinalIgnoreCase) ? "EXE" : "";
                if (string.IsNullOrEmpty(type)) continue;

                // Strict arch detection using explicit markers only.
                // Avoids false positives from bare filenames like "7z2409.exe" matching "64".
                string nl = name.ToLowerInvariant();
                string arch;
                if (nl.Contains("arm64") || nl.Contains("aarch64"))
                    arch = "ARM64";
                else if (nl.Contains("-x64")    || nl.Contains("_x64")   || nl.Contains("win64")
                      || nl.Contains("-amd64")  || nl.Contains("_amd64") || nl.Contains("-64.")
                      || nl.Contains("64bit")   || nl.Contains("x86_64")
                      || nl.EndsWith("64.exe")  || nl.EndsWith("64.msi"))
                    arch = "x64";
                else if (nl.Contains("-x86")    || nl.Contains("_x86")   || nl.Contains("win32")
                      || nl.Contains("-i386")   || nl.Contains("_i386")  || nl.Contains("-32.")
                      || nl.Contains("32bit")   || nl.Contains("x86_32")
                      || nl.EndsWith("32.exe")  || nl.EndsWith("32.msi"))
                    arch = "x86";
                else
                    arch = "x86"; // no explicit marker = treat as universal/x86

                // Keep only first match per TYPE-ARCH combination
                if (!seen.Add($"{type}-{arch}")) continue;

                links.Add(new DownloadLink { Label = $"{type} {arch}", Type = type, Arch = arch, Url = url });
            }

            // Sort: EXE x64, EXE x86, EXE ARM64, MSI x64, MSI x86, MSI ARM64
            links = links
                .OrderBy(l => l.Type == "MSI" ? 0 : 1)
                .ThenBy(l => l.Arch == "x64" ? 0 : l.Arch == "x86" ? 1 : 2)
                .ToList();

            return new AppDownloadInfo
            {
                SourceAppName = app.SourceAppName, SourceAppVendor = app.SourceAppVendor, Version = v,
                Source  = $"GitHub ({app.GitHubRepo})",
                PageUrl = app.DownloadPageUrl, Links = links,
            };
        }

        /// <summary>
        /// Fetches latest version + installer links from the winget-pkgs manifest
        /// repository on GitHub (the same data the winget client uses — winget has no
        /// official REST API). Package id "Smekal.FileCompare" maps to the manifest path
        /// manifests/s/Smekal/FileCompare; the newest version folder's *.installer.yaml is
        /// parsed line-wise for per-architecture installer URLs.
        /// </summary>
        private async Task<AppDownloadInfo> FetchWingetAsync(DownloadSourceEntry app)
        {
            string id = (app.WingetPackageId ?? "").Trim();
            if (id.Length == 0) return FallbackInfo(app);

            try
            {
                return await FetchWingetCoreAsync(app, id);
            }
            catch (Exception ex)
            {
                // Surface the reason (rate limit, proxy, 404, parse error) instead of
                // failing silently into the download-page fallback.
                try
                {
                    File.AppendAllText(Path.Combine(Path.GetTempPath(), "SwiftPack_WingetFetch.log"),
                        $"[{DateTime.Now:yyyy-MM-dd HH:mm:ss}] {id}: {ex.GetType().Name}: {ex.Message}\r\n");
                }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                return FallbackInfo(app);
            }
        }

        // "Vendor API" resolves through the same winget backend as the "winget" type, but keyed
        // on the manually-entered Vendor API ID rather than the picker-populated Winget Package ID.
        // Without this the type fell through to FallbackInfo, which only yields a link when the
        // Download Page URL is a direct .msi/.exe - so a Vendor API app with only an id showed no
        // download buttons. Same resolver, error handling and cache behaviour as FetchWingetAsync.
        private async Task<AppDownloadInfo> FetchVendorApiAsync(DownloadSourceEntry app)
        {
            string id = (app.VendorApiId ?? "").Trim();
            if (id.Length == 0) return FallbackInfo(app);

            try
            {
                return await FetchWingetCoreAsync(app, id);
            }
            catch (Exception ex)
            {
                try
                {
                    File.AppendAllText(Path.Combine(Path.GetTempPath(), "SwiftPack_WingetFetch.log"),
                        $"[{DateTime.Now:yyyy-MM-dd HH:mm:ss}] {id}: {ex.GetType().Name}: {ex.Message}\r\n");
                }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                return FallbackInfo(app);
            }
        }

        /// <summary>Appends to the same %TEMP%\SwiftPack_WingetFetch.log the fetch errors go to.</summary>
        private static void LogWinget(string line)
        {
            try
            {
                File.AppendAllText(Path.Combine(Path.GetTempPath(), "SwiftPack_WingetFetch.log"),
                    $"[{DateTime.Now:yyyy-MM-dd HH:mm:ss}] {line}\r\n");
            }
            catch (Exception ex) { System.Diagnostics.Debug.WriteLine("[WingetLog] " + ex.Message); }
        }

        private async Task<AppDownloadInfo> FetchWingetCoreAsync(DownloadSourceEntry app, string id)
        {

            var info = new AppDownloadInfo
            {
                SourceAppName = app.SourceAppName, SourceAppVendor = app.SourceAppVendor,
                Version = "", Source = "winget-pkgs manifests", PageUrl = app.DownloadPageUrl, Links = new(),
            };

            // "Smekal.FileCompare" → "manifests/s/Smekal/FileCompare"
            string relPath = "manifests/" + char.ToLowerInvariant(id[0]) + "/" + id.Replace('.', '/');

            static string VerSortKey(string v) => string.Join(".",
                v.Split('.', '-', '+').Select(p =>
                {
                    string digits = new string(p.TakeWhile(char.IsDigit).ToArray());
                    return (digits.Length > 0 ? digits : "0").PadLeft(12, '0');
                }));

            // ── 1) Latest version ────────────────────────────────────────────────────────────
            // From the LOCAL winget catalog, not from api.github.com.
            //
            // The GitHub API call this replaces existed only to list the version folders and read the
            // newest name. It cost one request per app against a 60/hour unauthenticated budget, so
            // ~15 apps burned a quarter of the hour on a single refresh and everything 403'd after
            // four. At 1000 apps it could never work, and a PAT would not fix it - the 5,000/hour
            // ceiling is per token, so one token in the product is one bucket shared by every customer.
            //
            // WingetCatalog downloads the pre-indexed source ONCE (source2.msix -> Public/index.db)
            // and answers every lookup locally: one request per day, whatever the app count.
            string? version = null;
            if (await WingetCatalog.EnsureAsync(_http, LogWinget).ConfigureAwait(true))
                version = WingetCatalog.TryGetLatestVersion(id, LogWinget);

            if (string.IsNullOrEmpty(version))
            {
                // Fallback: the catalog is unavailable (offline, CDN down, package absent from the
                // index). Use the old GitHub listing. It is rate-limited, which is why it is no longer
                // the primary path - but for a handful of stragglers it is better than no links.
                LogWinget($"[WingetCatalog] {id}: not in the catalog, falling back to api.github.com");

                string? listJson = await GitHubGetAsync(
                    "https://api.github.com/repos/microsoft/winget-pkgs/contents/" + relPath);
                if (listJson == null) return info;   // 304 - unchanged, nothing new to report

                using var listDoc = JsonDocument.Parse(listJson);
                if (listDoc.RootElement.ValueKind != JsonValueKind.Array) return info;
                version = listDoc.RootElement.EnumerateArray()
                    .Where(e => e.TryGetProperty("type", out var t) && t.GetString() == "dir")
                    .Select(e => e.TryGetProperty("name", out var n) ? (n.GetString() ?? "") : "")
                    .Where(n => n.Length > 0 && !n.StartsWith("."))
                    .OrderByDescending(VerSortKey, StringComparer.Ordinal)
                    .FirstOrDefault();
            }

            if (string.IsNullOrEmpty(version)) return info;
            info.Version = version;

            // 2) Fetch the installer manifest for that version.
            //    raw.githubusercontent.com is a CDN with NO API quota, so this stays as it was - and
            //    thanks to the version gate in the scheduler it only runs for apps that actually
            //    changed.
            string yaml = await _http.GetStringAsync(
                $"https://raw.githubusercontent.com/microsoft/winget-pkgs/master/{relPath}/{version}/{id}.installer.yaml");

            // 3) Minimal line-wise YAML parse: defaults above "Installers:", then one
            //    block per "- " item; key order inside a block varies between manifests.
            static string MapType(string installerType, string url)
            {
                string t = installerType.Trim().ToLowerInvariant();
                if (t == "msi" || t == "wix") return "MSI";
                if (t == "exe" || t == "nullsoft" || t == "inno" || t == "burn" || t == "portable") return "EXE";
                try
                {
                    string ext = Path.GetExtension(new Uri(url).AbsolutePath).ToLowerInvariant();
                    if (ext == ".msi") return "MSI";
                    if (ext == ".exe") return "EXE";
                }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                return "";
            }

            string defType = "";
            var blocks   = new List<Dictionary<string, string>>();
            Dictionary<string, string>? cur = null;
            bool inInstallers = false;
            var kvRx = new Regex(@"^\s*-?\s*(\w+):\s*(.*?)\s*$");

            foreach (var rawLine in yaml.Split('\n'))
            {
                string line = rawLine.TrimEnd('\r');
                if (!inInstallers)
                {
                    if (Regex.IsMatch(line, @"^Installers:\s*$")) { inInstallers = true; continue; }
                    var mTop = Regex.Match(line, @"^InstallerType:\s*(\S+)");
                    if (mTop.Success) defType = mTop.Groups[1].Value;
                    continue;
                }
                // A new top-level key after the Installers list ends the section.
                if (line.Length > 0 && !char.IsWhiteSpace(line[0]) && !line.StartsWith("-")) break;

                if (Regex.IsMatch(line, @"^\s*-\s"))
                {
                    cur = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                    blocks.Add(cur);
                }
                if (cur == null) continue;
                var m = kvRx.Match(line);
                if (m.Success && !cur.ContainsKey(m.Groups[1].Value))
                    cur[m.Groups[1].Value] = m.Groups[2].Value.Trim().Trim('"', '\'');
            }

            string Get(Dictionary<string, string> b, string k) => b.TryGetValue(k, out var v) ? v : "";

            var entries = blocks
                .Select(b => new
                {
                    Url   = Get(b, "InstallerUrl"),
                    Arch  = Get(b, "Architecture").ToLowerInvariant() == "x86" ? "x86"
                          : Get(b, "Architecture").ToLowerInvariant().Contains("arm") ? "ARM64" : "x64",
                    Type  = MapType(Get(b, "InstallerType").Length > 0 ? Get(b, "InstallerType") : defType, Get(b, "InstallerUrl")),
                    Scope = Get(b, "Scope"),
                })
                .Where(x => x.Url.Length > 0 && x.Type.Length > 0)
                // Prefer machine-scope installers; entries without Scope rank equally high.
                .OrderByDescending(x => x.Scope.Length == 0 ||
                    x.Scope.Equals("machine", StringComparison.OrdinalIgnoreCase))
                .ToList();

            foreach (var slot in new[] { ("MSI", "x64"), ("MSI", "x86"), ("EXE", "x64"), ("EXE", "x86") })
            {
                var hit = entries.FirstOrDefault(x => x.Type == slot.Item1 && x.Arch == slot.Item2);
                if (hit == null) continue;
                info.Links.Add(new() { Label = $"{slot.Item1} {slot.Item2}", Type = slot.Item1, Arch = slot.Item2, Url = hit.Url });
            }
            if (info.Links.Count == 0 && entries.Count > 0)
            {
                var first = entries[0];
                info.Links.Add(new() { Label = $"{first.Type} {first.Arch}", Type = first.Type, Arch = first.Arch, Url = first.Url });
            }
            return info;
        }

        // Extract a release version from a direct installer URL. This supports common URL/file-name
        // forms such as:
        //   MyApp-1.0.0.exe
        //   MyApp_Setup_v2.5.8.msi
        //   /Release/MyApp/2026.1.0529.7/installer.exe
        // The filename is preferred over the full path to avoid accidentally selecting an unrelated
        // version-like number from a parent folder. If no version is present, the method returns empty
        // and the caller falls back to SourceAppVersion.
        private static string TryGetVersionFromDirectUrl(string url)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(url)) return "";

                string path = url;
                try { path = new Uri(url).AbsolutePath; } catch { }
                path = Uri.UnescapeDataString(path);

                string fileName = Path.GetFileNameWithoutExtension(path);
                string[] candidates =
                {
                    fileName,
                    path,
                    url
                };

                // 2 to 4 numeric components: 1.0, 1.0.0, 1.0.0.0, 2026.1.0529.7
                const string pattern = @"(?<!\d)v?(\d+(?:\.\d+){1,3})(?!\d)";

                foreach (string candidate in candidates)
                {
                    if (string.IsNullOrWhiteSpace(candidate)) continue;
                    var matches = System.Text.RegularExpressions.Regex.Matches(
                        candidate, pattern,
                        System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                    if (matches.Count > 0)
                        return matches[matches.Count - 1].Groups[1].Value;
                }
            }
            catch { }

            return "";
        }

        private static bool IsVersionedDirectFileUrl(string url)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(url)) return false;
                string path = url;
                try { path = new Uri(url).AbsolutePath; } catch { }
                string ext = Path.GetExtension(Uri.UnescapeDataString(path)).ToLowerInvariant();
                return (ext == ".msi" || ext == ".exe") &&
                       !string.IsNullOrWhiteSpace(TryGetVersionFromDirectUrl(url));
            }
            catch { return false; }
        }

        private static AppDownloadInfo FallbackInfo(DownloadSourceEntry app)
        {
            var info = new AppDownloadInfo
            {
                SourceAppName = app.SourceAppName, SourceAppVendor = app.SourceAppVendor, Version = "",
                Source  = "Download Page", PageUrl = app.DownloadPageUrl, Links = new(),
            };

            // When the Download Page URL itself points at an installer file (.msi/.exe),
            // surface it as a direct download link so a download button appears even
            // for custom apps with ApiType = none.
            try
            {
                string url = app.DownloadPageUrl ?? "";
                string pathPart = url;
                try { pathPart = new Uri(url).AbsolutePath; } catch { /* keep raw url */ }
                string ext = Path.GetExtension(Uri.UnescapeDataString(pathPart)).ToLowerInvariant();
                if (ext == ".msi" || ext == ".exe")
                {
                    string type = ext == ".msi" ? "MSI" : "EXE";
                    // Best-effort architecture from the configured Download Preference; default x64.
                    string arch = (app.DownloadPreference ?? "")
                        .IndexOf("ARM64", StringComparison.OrdinalIgnoreCase) >= 0 ? "ARM64"
                        : (app.DownloadPreference ?? "")
                        .IndexOf("x86", StringComparison.OrdinalIgnoreCase) >= 0 ? "x86" : "x64";
                    info.Source  = "Direct file URL";

                    // For ApiType=none, SourceAppVersion is the locally downloaded version, not
                    // the remote version. When the URL contains a version, use that as the remote
                    // version so both the NEW badge and the automatic scheduler use the same value.
                    // If the URL has no version, preserve the old behavior and use the local version.
                    info.Version = TryGetVersionFromDirectUrl(url);
                    if (string.IsNullOrWhiteSpace(info.Version))
                        info.Version = app.SourceAppVersion ?? "";

                    info.Links.Add(new() { Label = $"{type} {arch}", Type = type, Arch = arch, Url = url });
                }
            }
            catch { /* fall through to page-only info */ }

            return info;
        }

        // ── Info Panel Renderer ────────────────────────────────────────────
        // ══════════════════════════════════════════════════════════════════════
        // DIRECT DOWNLOAD
        // ══════════════════════════════════════════════════════════════════════
        // ── Download cancellation ──────────────────────────────────────────
        private CancellationTokenSource? _downloadCts        = null;
        // How long a transfer may go completely silent before it is treated as dead. This is
        // NOT a cap on how long a download may take: the deadline is pushed forward every
        // time bytes arrive, so a slow but live transfer runs for as long as it needs. It
        // exists because _httpDownload has no timeout, and an unattended scheduled run must
        // not sit on a dead socket forever holding the flow lock.
        private const int StallTimeoutMs = 120_000;

        // ── SourceForge slow-mirror escape ─────────────────────────────────
        // SourceForge assigns a download mirror per request, and mirrors differ by an
        // order of magnitude (webwerks in Mumbai has been measured at ~80 KB/s while
        // European mirrors do multiple MB/s from the same client). A transfer that is
        // still under the floor after the probe window is not going to get better, so
        // it is cheaper to throw away the first megabyte and re-request with an
        // explicit use_mirror than to let a 30 MB file take seven minutes. Applies
        // ONLY to sourceforge.net URLs, and never when the URL already pins a mirror.
        private const int  SlowMirrorProbeMs           = 15_000;
        private const long SlowMirrorFloorBytesPerSec  = 200 * 1024;
        // 'master' is SourceForge's own origin server - it exists as long as SourceForge
        // does, which makes it the one retry that can never be a dead name, and it serves
        // every region acceptably. jaist (Japan) and netix (Bulgaria) add geographic
        // diversity for APAC and Europe. SourceForge retires mirrors over time, so every
        // name here is DNS-checked before use and a dead one is skipped in milliseconds -
        // the list can go stale without ever failing a download (a retired 'gigenet' entry
        // pinned by hostname produced exactly that failure: NXDOMAIN, download dead).
        private static readonly string[] SourceForgeFallbackMirrors = { "master", "jaist", "netix" };

        private static bool IsSourceForgeUrl(string u)
        {
            try { return new Uri(u).Host.EndsWith("sourceforge.net", StringComparison.OrdinalIgnoreCase); }
            catch { return false; }
        }

        private static string WithSourceForgeMirror(string u, string mirror)
            => u + (u.Contains('?') ? "&" : "?") + "use_mirror=" + mirror;
        // Pause gate for the active download. Set (signaled) = running; reset = paused.
        // The read loop waits on this each iteration so a pause holds the connection/file
        // open without cancelling, and resume continues from where it left off.
        private readonly System.Threading.ManualResetEventSlim _downloadPauseGate = new System.Threading.ManualResetEventSlim(true);
        private volatile bool _downloadIsPaused = false;
        private Task                      _activeDownloadTask = Task.CompletedTask;
        // Every download start takes the next number, and the shared header progress panel
        // belongs to whichever download is holding the current one. A task that was cancelled
        // to make room for a newer download unwinds asynchronously, seconds later; without a
        // number to compare against, its teardown collapsed the panel the newer download was
        // using, which is what "Connecting..." vanishing with nothing in its place looks like.
        private int _downloadGeneration = 0;

        /// <summary>True while the caller's download still owns the shared progress panel.</summary>
        private bool IsCurrentDownload(int generation)
            => System.Threading.Volatile.Read(ref _downloadGeneration) == generation;

        private void BtnCancelDownload_Click(object sender, RoutedEventArgs e)
            => _downloadCts?.Cancel();

        // Pause / resume the active download. Pausing holds the connection and file stream
        // open (the read loop waits on the gate); resuming continues from the same offset.
        private void BtnPauseDownload_Click(object sender, RoutedEventArgs e)
        {
            _downloadIsPaused = !_downloadIsPaused;
            if (_downloadIsPaused) _downloadPauseGate.Reset();   // pause
            else                   _downloadPauseGate.Set();     // resume

            void Reflect()
            {
                foreach (var name in new[] { "BtnPauseDownload", "BtnPauseDownloadTop" })
                {
                    if (FindName(name) is Button b)
                    {
                        b.Content = _downloadIsPaused ? "▶" : "❚❚";
                        b.ToolTip = _downloadIsPaused ? "Resume download" : "Pause download";
                    }
                }
                if (TxtProgressStatus != null && _downloadIsPaused)
                    TxtProgressStatus.Text += "  (paused)";
            }
            if (Dispatcher.CheckAccess()) Reflect(); else Dispatcher.Invoke(Reflect);
        }

        // ══════════════════════════════════════════════════════════════════════
        // ── Silent Install/Uninstall source — progress + highlight + cancel ──
        //    The actual process runs in AutoSilentRunner (AutoPackageShared.cs),
        //    which calls BeginSilentPhase/EndSilentPhase on this page (via Dispatcher) and
        //    honours CancelSilentRun() through the host's CancellationToken.
        // ══════════════════════════════════════════════════════════════════════
        private CheckBox? _chkInstallSilent;     // "Install source silently" label (Download Information column)
        private CheckBox? _chkUninstallSilent;   // "Uninstall source silently" label

        // Accent used to highlight the active silent-phase label.
        private static readonly Brush _silentAccentBrush =
            new SolidColorBrush(Color.FromRgb(0x2D, 0x7D, 0xF6));

        // Remembers the highlighted checkbox so EndSilentPhase can restore its look.
        private CheckBox? _highlightedSilentChk;
        private FontWeight _highlightedSilentPrevWeight = FontWeights.Normal;
        private bool _lastSilentPhaseWasUninstall;
        private string? _activeSilentPhase;   // "install" | "uninstall" while a silent phase is running; null otherwise

        /// <summary>
        /// Called by the host immediately before a silent Install/Uninstall process starts.
        /// Shows the thin top progress bar, highlights the relevant label, and reveals the
        /// Cancel button. For the uninstall phase it first navigates back to the Download tab
        /// (uninstall otherwise runs while the Package tab is showing).
        /// </summary>
        public void BeginSilentPhase(string phase)   // phase: "install" | "uninstall"
        {
            void Run()
            {
                bool isUninstall = phase.Equals("uninstall", StringComparison.OrdinalIgnoreCase);
                _lastSilentPhaseWasUninstall = isUninstall;
                _activeSilentPhase = isUninstall ? "uninstall" : "install";

                // For uninstall, bring the user back to the Download tab so the progress is visible.
                if (isUninstall)
                {
                    try { (_mainWindow?.AutoPackagePage ?? FindAncestorAutoPackagePage())?.ActivateTopTab("Download"); }
                    catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                }

                if (TopSilentProgressBar != null)
                {
                    TopSilentProgressBar.IsIndeterminate = true;
                    TopSilentProgressBar.Visibility      = Visibility.Visible;
                }
                if (FindName("BtnCancelSilent") is Button btn) btn.Visibility = Visibility.Visible;

                // Find the checkbox LIVE in the panel (robust against re-renders that would
                // orphan a cached reference).
                HighlightSilentLabel(FindSilentCheckBox(isUninstall ? "Uninstall source silently"
                                                                    : "Install source silently"));
            }
            if (Dispatcher.CheckAccess()) Run(); else Dispatcher.Invoke(Run);
        }

        /// <summary>Called by the host after a silent phase finishes (or is cancelled).</summary>
        public void EndSilentPhase()
        {
            void Run()
            {
                if (TopSilentProgressBar != null)
                {
                    TopSilentProgressBar.Visibility      = Visibility.Collapsed;
                    TopSilentProgressBar.IsIndeterminate = false;
                }
                if (FindName("BtnCancelSilent") is Button btn) btn.Visibility = Visibility.Collapsed;
                UnhighlightSilentLabel();
                _activeSilentPhase = null;

                // Safety net: "Uninstall source silently" is the last user-visible action in the
                // no-install-package scenario. If the auto-flow-complete callback didn't release
                // the Download/Package columns (timing/instance edge cases), release them here so
                // the Download tab doesn't stay greyed until the user clicks through the tabs.
                if (_lastSilentPhaseWasUninstall && _downloadColumnsLocked)
                {
                    _autoFlowChainPending = false;
                    UnlockDownloadAndPackageColumns();
                }
            }
            if (Dispatcher.CheckAccess()) Run(); else Dispatcher.Invoke(Run);
        }

        // Locate the "Install/Uninstall source silently" CheckBox currently in the visual
        // tree by its content text. Prefers the cached reference, then a live tree walk.
        private CheckBox? FindSilentCheckBox(string content)
        {
            // Cached first (set during RenderInfoPanel), if still attached.
            var cached = content.StartsWith("Install", StringComparison.OrdinalIgnoreCase)
                ? _chkInstallSilent : _chkUninstallSilent;
            if (cached != null) return cached;

            // Fall back to a live walk of the package-info panel.
            if (PnlPackageInfo != null)
            {
                foreach (var cb in EnumerateVisuals(PnlPackageInfo).OfType<CheckBox>())
                    if (string.Equals(cb.Content?.ToString(), content, StringComparison.OrdinalIgnoreCase))
                        return cb;
            }
            return null;
        }

        private static IEnumerable<DependencyObject> EnumerateVisuals(DependencyObject root)
        {
            int n = System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);
            for (int i = 0; i < n; i++)
            {
                var c = System.Windows.Media.VisualTreeHelper.GetChild(root, i);
                yield return c;
                foreach (var d in EnumerateVisuals(c)) yield return d;
            }
        }

        // ── Auto-flow status (colour the action checkboxes + show a status line) ──────────
        private static readonly (string Key, int Index)[] _autoFlowMap =
        {
            (AutoFlowStatus.InstallSource,    0),
            (AutoFlowStatus.UninstallSource,  1),
            (AutoFlowStatus.CreatePackage,    2),
            (AutoFlowStatus.InstallPackage,   3),
            (AutoFlowStatus.UninstallPackage, 4),
            (AutoFlowStatus.CreateIntunewin,  5),
            (AutoFlowStatus.PublishSettings,  6),
            (AutoFlowStatus.PublishToIntune,  7),
            (AutoFlowStatus.SendMail,         8),
            (AutoFlowStatus.AddSupersedence,  9),
        };

        /// <summary>Stable per-application key (survives revision changes).</summary>
        private string CurrentAppKey()
        {
            try
            {
                string v = _selectedApp?.SourceAppVendor ?? _selectedApp?.IntuneAppVendor ?? "";
                string a = _selectedApp?.SourceAppName   ?? _selectedApp?.IntuneAppName   ?? "";
                if (string.IsNullOrWhiteSpace(v) && string.IsNullOrWhiteSpace(a)) return "";
                return (v + "|" + a).Trim();
            }
            catch { return ""; }
        }

        /// <summary>Called when the flow finishes: save the result for this app, then paint it.</summary>
        public void RenderAutoFlowStatusPanel()
        {
            void Run()
            {
                try
                {
                    var snapshot = AutoFlowStatus.Snapshot();
                    AutoFlowStatus.SaveResultFor(CurrentAppKey());
                    ApplyAutoFlowResultToUI(snapshot, Finished: true);

                    // The flow is over however it ended: give the manual features back.
                    AppBusy.SetAuto("Auto Package chain", false);
                    AppBusy.SetAuto("Download", false);

                    // The chain's verdict for the schedule history: a scheduled run is the
                    // download plus its selected actions, so any Failed step here rewrites
                    // the row that the download optimistically recorded as Completed. The
                    // marker is consumed either way - the next chain speaks for itself.
                    if (_scheduledChainKey is string chainKey)
                    {
                        _scheduledChainKey = null;
                        if (snapshot.Values.Any(v => v == AutoFlowStatus.State.Failed))
                        {
                            int bar = chainKey.IndexOf('|');
                            if (bar > 0)
                            {
                                AmendLatestScheduleOutcome(chainKey.Substring(0, bar), chainKey.Substring(bar + 1));
                                QueueStatusWorkbook();
                            }
                        }
                    }
                }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
            }
            if (Dispatcher.CheckAccess()) Run(); else Dispatcher.BeginInvoke((Action)Run);
        }

        /// <summary>Re-apply a saved result for the currently-selected app (on selection).</summary>
        private void ReapplySavedAutoFlowResult()
        {
            try
            {
                var r = AutoFlowStatus.GetResultFor(CurrentAppKey());
                if (r == null)
                {
                    // No chain result. If a plain download of THIS app left a verdict, repaint
                    // it: panel rebuilds land here deferred, including the one the completion
                    // path itself triggers, and clearing unconditionally is what made
                    // "Status: Completed" flash and vanish.
                    if (!string.IsNullOrEmpty(_downloadVerdictKey) && _downloadVerdictKey == CurrentAppKey())
                        ShowDownloadStatusLine(_downloadVerdictFailed);
                    else
                        ClearAutoFlowStatusPanel();
                    return;
                }
                ApplyAutoFlowResultToUI(r.Status, Finished: true);
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
        }

        /// <summary>Colour the action checkboxes (green/red) and show a single status line.</summary>
        private void ApplyAutoFlowResultToUI(System.Collections.Generic.Dictionary<string, AutoFlowStatus.State> status, bool Finished)
        {
            try
            {
                if (PnlPackageInfo?.Tag is not CheckBox[] acts) return;

                var green = TryBrush("SuccessBrush") ?? new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(0x2E, 0xA0, 0x43));
                var red   = TryBrush("DangerBrush")  ?? new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(0xD1, 0x3A, 0x3A));
                var normal= TryBrush("TextPrimaryBrush") ?? System.Windows.Media.Brushes.Black;

                bool anyFailed = false;
                bool anyShown  = false;

                foreach (var (key, idx) in _autoFlowMap)
                {
                    if (acts.Length <= idx) continue;
                    var cb = acts[idx];
                    // Never override the blue "in progress" highlight on the active silent phase.
                    if (ReferenceEquals(cb, _highlightedSilentChk)) { anyShown = true; continue; }
                    var st = status.TryGetValue(key, out var s) ? s : AutoFlowStatus.State.None;
                    if (st == AutoFlowStatus.State.Ok)        { cb.Foreground = green;  anyShown = true; }
                    else if (st == AutoFlowStatus.State.Failed){ cb.Foreground = red;    anyShown = true; anyFailed = true; }
                    else                                       { cb.Foreground = normal; }   // not run → default colour
                }

                // Status line at the bottom of the column (reuse the progress footer area).
                // Skipped entirely while a download owns that area - see _downloadPanelActive.
                if (PnlAutoFlowStatus != null && PnlAutoFlowStatusItems != null && !_downloadPanelActive)
                {
                    PnlAutoFlowStatusItems.Children.Clear();
                    if (anyShown && Finished)
                    {
                        PnlAutoFlowStatusItems.Children.Add(new TextBlock
                        {
                            Text = anyFailed ? "Status: Failed" : "Status: Completed",
                            FontSize = 11, FontWeight = FontWeights.Bold,
                            Foreground = anyFailed ? red : green,
                            HorizontalAlignment = HorizontalAlignment.Center
                        });
                        if (PnlHeaderProgress != null) PnlHeaderProgress.Visibility = Visibility.Collapsed;
                        PnlAutoFlowStatus.Visibility = Visibility.Visible;
                    }
                    else
                    {
                        PnlAutoFlowStatus.Visibility = Visibility.Collapsed;
                    }
                }
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
        }

        // The plain-download verdict, keyed to the app it belongs to. The footer is wiped by
        // every panel rebuild (ReapplySavedAutoFlowResult runs deferred after each one, and a
        // plain download has no saved chain result, so it used to fall through to the clear),
        // and the completion path itself triggers a rebuild via FetchAndShowAsync to refresh
        // the "New" badge - which is why "Status: Completed" appeared and instantly vanished.
        // Recording the verdict here lets the reapply path repaint it instead.
        private string _downloadVerdictKey = "";
        private bool   _downloadVerdictFailed;

        /// <summary>
        /// Writes the one-line footer verdict for a plain download, in the exact spot and
        /// styling the chained flow uses, so a download with no actions and a full chain end
        /// on the same "Status: Completed" / "Status: Failed" line. Only called when no chain
        /// follows: a running chain owns the footer and writes its own verdict at the end.
        /// </summary>
        private void ShowDownloadStatusLine(bool failed)
        {
            try
            {
                if (PnlAutoFlowStatus == null || PnlAutoFlowStatusItems == null) return;
                // A live download owns the footer. This painter is reachable mid-transfer
                // (any panel rebuild defers ReapplySavedAutoFlowResult), and painting here
                // would collapse the progress bar of a download that is still running. The
                // verdict is not lost: the next rebuild after the download ends repaints it.
                if (_downloadPanelActive) return;
                _downloadVerdictKey    = CurrentAppKey();
                _downloadVerdictFailed = failed;
                var green = TryBrush("SuccessBrush") ?? new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(0x2E, 0xA0, 0x43));
                var red   = TryBrush("DangerBrush")  ?? new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(0xD1, 0x3A, 0x3A));
                PnlAutoFlowStatusItems.Children.Clear();
                PnlAutoFlowStatusItems.Children.Add(new TextBlock
                {
                    Text = failed ? "Status: Failed" : "Status: Completed",
                    FontSize = 11, FontWeight = FontWeights.Bold,
                    Foreground = failed ? red : green,
                    HorizontalAlignment = HorizontalAlignment.Center
                });
                if (PnlHeaderProgress != null) PnlHeaderProgress.Visibility = Visibility.Collapsed;
                PnlAutoFlowStatus.Visibility = Visibility.Visible;
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
        }

        private System.Windows.Media.Brush? TryBrush(string key)
        {
            try { return TryFindResource(key) as System.Windows.Media.Brush; } catch { return null; }
        }

        /// <summary>Reset the action checkbox colours and hide the status line.</summary>
        public void ClearAutoFlowStatusPanel()
        {
            void Run()
            {
                try
                {
                    var normal = TryBrush("TextPrimaryBrush") ?? System.Windows.Media.Brushes.Black;
                    if (PnlPackageInfo?.Tag is CheckBox[] acts)
                        foreach (var cb in acts)
                        {
                            if (ReferenceEquals(cb, _highlightedSilentChk)) continue; // keep blue in-progress
                            cb.Foreground = normal;
                        }
                    if (PnlAutoFlowStatusItems != null) PnlAutoFlowStatusItems.Children.Clear();
                    if (PnlAutoFlowStatus != null) PnlAutoFlowStatus.Visibility = Visibility.Collapsed;
                }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
            }
            if (Dispatcher.CheckAccess()) Run(); else Dispatcher.BeginInvoke((Action)Run);
        }

        // ── Package error notice (Download Information column) ──────────────────────────
        // When a step of the auto-flow fails before it can even start - the PSADT Template
        // Folder is missing, or PsExec.exe is missing for a System Context run - the failure
        // is written to the per-package log and the matching checklist item is painted red.
        // That is easy to miss, so the same message is surfaced in the empty area of the
        // Download Information column, just under the action checklist.
        //
        // The notice is kept per app so switching apps shows the right one (or none), and it
        // is static so it survives the page being rebuilt on navigation. RenderInfoPanel
        // re-adds it on every rebuild; a fresh run for that app clears it.
        private static readonly Dictionary<string, (string Title, string Message, string Hint)> _packageErrorByKey = new();
        private UIElement? _pkgErrorNoticeElement;

        // The page instance currently shown in the Auto Package > Download tab. The other Auto
        // Package tabs carry no compile-time dependency on this page, so they report a failure
        // through the public static entry point below, by reflection.
        private static SourceDownloadPage? _liveInstance;

        /// <summary>
        /// Surface a failed step in the Download Information column. Called by the other Auto
        /// Package tabs via reflection (no compile-time dependency on this page), so it may be
        /// called from a background thread.
        /// </summary>
        public static void ReportPackageError(string title, string message, string hint)
        {
            var inst = _liveInstance;
            if (inst == null) return;
            void Run() { inst.SetPackageErrorNotice(title, message, hint); }
            if (inst.Dispatcher.CheckAccess()) Run(); else inst.Dispatcher.BeginInvoke((Action)Run);
        }

        /// <summary>Store the notice against the selected app, then paint it.</summary>
        private void SetPackageErrorNotice(string title, string message, string hint)
        {
            try
            {
                string key = CurrentAppKey();
                if (string.IsNullOrEmpty(key)) return;
                _packageErrorByKey[key] = (title, message, hint);
                RenderPackageErrorNotice();
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
        }

        /// <summary>
        /// The same notice, but against a NAMED app instead of the selected one. A scheduled run has
        /// to report against the app it was actually downloading, which is not necessarily the app on
        /// screen by the time it fails - nothing stops the user clicking elsewhere while it runs. The
        /// key is built exactly the way CurrentAppKey builds it, so the two always agree; the notice
        /// is stored either way and painted as soon as that app is the one being shown.
        /// </summary>
        private void SetPackageErrorNoticeForApp(string vendor, string appName, string title, string message, string hint)
        {
            try
            {
                string v = vendor  ?? "";
                string a = appName ?? "";
                string key = (string.IsNullOrWhiteSpace(v) && string.IsNullOrWhiteSpace(a))
                    ? CurrentAppKey()
                    : (v + "|" + a).Trim();
                if (string.IsNullOrEmpty(key)) return;
                _packageErrorByKey[key] = (title, message, hint);
                RenderPackageErrorNotice();
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
        }

        /// <summary>
        /// True when a REAL deployment Invoke-AppDeployToolkit.ps1 exists in <paramref name="root"/>
        /// or in any folder beneath it. Consumed by the Create Package pre-flight guard, which
        /// aborts the run when this returns false - checked at RUN time only, on request: a
        /// standing warning in the Download Information column was tried and pulled, because it sat
        /// there on app open before anything had been asked to run and read as something already
        /// wrong. Both layouts are valid and both are in use: the script sits at the template root,
        /// or one level down in a per-app folder
        /// (…\PSADT Template\Acrolics\Invoke-AppDeployToolkit.ps1), so the search has to recurse.
        ///
        /// The name is matched EXACTLY, and that is not an oversight. Everything downstream is
        /// hard-wired to it: AutoPackagePage.FindDeploymentPs1 searches for that name,
        /// CopyTemplateToPackage copies that name into the package, and the generated commands are
        /// -File "Invoke-AppDeployToolkit.ps1". A template holding a differently named entry script
        /// - a PSADT v3 Deploy-Application.ps1, or one somebody renamed - produces a package with
        /// nothing to run, so it SHOULD warn. Matching loosely would silence the warning for exactly
        /// the templates it exists to catch. (Windows path matching is case-insensitive, so casing
        /// is already tolerated.)
        ///
        /// EnumerateFiles rather than GetFiles: it stops at the first real hit instead of
        /// materialising every match, and .NET's default enumeration options skip folders the
        /// process cannot read instead of throwing part-way through the walk.
        /// </summary>
        private static bool HasInvokeAppDeployToolkitScript(string root)
        {
            try
            {
                foreach (var p in System.IO.Directory.EnumerateFiles(
                             root, "Invoke-AppDeployToolkit.ps1", System.IO.SearchOption.AllDirectories))
                {
                    // Skip the decoy the toolkit ships inside itself, at
                    // …\PSAppDeployToolkit\Frontend\v4\Invoke-AppDeployToolkit.ps1. Every v4 template
                    // carries that module folder, so counting it would make this check pass for a
                    // template with no deployment script at all - the warning would never fire.
                    // Same exclusion AutoPackagePage.FindDeploymentPs1 applies when it picks the
                    // real one; the two must agree or the panel and the packager disagree about
                    // whether a template is usable.
                    if (p.IndexOf(@"\PSAppDeployToolkit\", StringComparison.OrdinalIgnoreCase) >= 0) continue;
                    return true;
                }
                return false;
            }
            catch (Exception ex)
            {
                // Unreadable tree. Report "present" so the panel stays quiet: warning that a
                // template is broken when the truth is that the folder could not be walked would
                // send someone looking for a missing file that is sitting right there.
                LogWinget($"[CreatePackage] template folder could not be searched ({ex.Message}): {root}");
                return true;
            }
        }

        private void RenderPackageErrorNotice()
        {
            try
            {
                if (PnlAppInfo == null) return;

                // Drop any existing notice first so two never stack. After a panel rebuild the
                // old element is already gone from the tree, so Contains guards that case too.
                if (_pkgErrorNoticeElement != null && PnlAppInfo.Children.Contains(_pkgErrorNoticeElement))
                    PnlAppInfo.Children.Remove(_pkgErrorNoticeElement);
                _pkgErrorNoticeElement = null;

                string key = CurrentAppKey();
                if (string.IsNullOrEmpty(key)) return;
                if (!_packageErrorByKey.TryGetValue(key, out var err) || string.IsNullOrWhiteSpace(err.Message))
                    return;

                var red    = TryBrush("DangerBrush") ?? new SolidColorBrush(Color.FromRgb(0xD1, 0x3A, 0x3A));
                var redBg  = new SolidColorBrush(Color.FromArgb(0x18, 0xD1, 0x3A, 0x3A));
                var redBdr = new SolidColorBrush(Color.FromArgb(0x55, 0xD1, 0x3A, 0x3A));
                var mutFg  = TryBrush("TextMutedBrush") ?? Brushes.DarkGray;

                var stack = new StackPanel();
                stack.Children.Add(new TextBlock
                {
                    Text       = "⚠  " + (string.IsNullOrWhiteSpace(err.Title) ? "Step failed" : err.Title),
                    FontSize   = 11,
                    FontWeight = FontWeights.Bold,
                    Foreground = red,
                    Margin     = new Thickness(0, 0, 0, 4),
                });
                stack.Children.Add(new TextBlock
                {
                    Text         = err.Message,
                    FontSize     = 11,
                    Foreground   = red,
                    TextWrapping = TextWrapping.Wrap,
                });
                if (!string.IsNullOrWhiteSpace(err.Hint))
                    stack.Children.Add(new TextBlock
                    {
                        Text         = err.Hint,
                        FontSize     = 11,
                        Foreground   = mutFg,
                        TextWrapping = TextWrapping.Wrap,
                        Margin       = new Thickness(0, 6, 0, 0),
                    });

                var border = new Border
                {
                    Background      = redBg,
                    BorderBrush     = redBdr,
                    BorderThickness = new Thickness(1),
                    CornerRadius    = new CornerRadius(6),
                    Padding         = new Thickness(10, 8, 10, 8),
                    Margin          = new Thickness(0, 12, 0, 0),
                    Child           = stack,
                };
                PnlAppInfo.Children.Add(border);
                _pkgErrorNoticeElement = border;
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
        }

        private void HighlightSilentLabel(CheckBox? chk)
        {
            UnhighlightSilentLabel();
            if (chk == null) return;
            _highlightedSilentChk        = chk;
            _highlightedSilentPrevWeight = chk.FontWeight;
            // The checkbox foreground is driven by a DynamicResource (SetResourceReference),
            // so a plain local-value assignment can be overridden by the resource. Clear the
            // resource reference first, then set the accent as a local value.
            // Use the same accent the Package-tab progress bar uses, for uniformity;
            // fall back to a fixed blue if the resource isn't found.
            chk.ClearValue(Control.ForegroundProperty);
            chk.Foreground = (TryFindResource("AccentBlueBrush") as Brush) ?? _silentAccentBrush;
            chk.FontWeight = FontWeights.Bold;
        }

        private void UnhighlightSilentLabel()
        {
            if (_highlightedSilentChk == null) return;
            _highlightedSilentChk.FontWeight = _highlightedSilentPrevWeight;
            // Restore the theme-driven foreground (re-attach the resource reference).
            _highlightedSilentChk.SetResourceReference(Control.ForegroundProperty, "TextPrimaryBrush");
            _highlightedSilentChk        = null;
            _highlightedSilentPrevWeight = FontWeights.Normal;
        }

        private void BtnCancelSilent_Click(object sender, RoutedEventArgs e)
        {
            _mainWindow ??= Window.GetWindow(this) as IAutoPackageHost;
            try { _mainWindow?.CancelSilentRun(); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
            // Reflect cancellation immediately; the host also calls EndSilentPhase when the
            // process is actually torn down.
            EndSilentPhase();
            // Cancelling aborts the auto-flow chain, so the all-complete callback that would
            // normally unlock the columns will not fire. Release them here so the app doesn't
            // stay disabled after Cancel.
            _activeSilentPhase = null;
            _autoFlowChainPending = false;
            AutoFlowStatus.FlowRunning = false;   // cancel aborts the whole flow — re-enable the tabs
            if (_downloadColumnsLocked) UnlockDownloadAndPackageColumns();
        }


        // scheduled: this run was started by the scheduler (Auto Download Source = Yes), not by a
        // click. Nothing in it may open a modal window. The scheduler AWAITS this task, so a dialog
        // left sitting on screen holds the entire queue - the next due app is not even looked at
        // until somebody presses OK, which on an unattended machine can be the following morning.
        // Failures are written to the Download Information column instead.
        private async Task DownloadFileAsync(string url, string label, string appName, string version, string vendor = "", bool scheduled = false, string existingVersion = "", string scheduleName = "")
        {
            // Destination: <SourceDownloadPath>\<Vendor>\<AppName> <Version>\
            string basePath = string.IsNullOrWhiteSpace(_sourceDownloadPath)
                ? DefaultDownloadPath
                : _sourceDownloadPath;
            _downloadStartTime = DateTime.Now;

            string safeVendor = vendor.Trim();
            foreach (char c in Path.GetInvalidFileNameChars()) safeVendor = safeVendor.Replace(c, '_');
            if (string.IsNullOrWhiteSpace(safeVendor)) safeVendor = "Unknown";

            string folderName = $"{appName} {version}".Trim();
            foreach (char c in Path.GetInvalidFileNameChars()) folderName = folderName.Replace(c, '_');
            string destFolder = Path.Combine(basePath, safeVendor, folderName);

            // Claim the shared progress panel before anything is painted on it. The previous
            // download is cancelled two lines below and its teardown arrives later, on its own
            // thread, so it needs a number it can fail to match.
            int myGeneration = System.Threading.Interlocked.Increment(ref _downloadGeneration);

            var progressBorder = ShowDownloadProgress(label, destFolder);

            // Cancel any previous download and wait for it to stop
            _downloadCts?.Cancel();
            try { await _activeDownloadTask.ConfigureAwait(false); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
            _downloadCts = new CancellationTokenSource();
            var ct = _downloadCts.Token;
            // New download starts in the running (un-paused) state.
            _downloadIsPaused = false;
            _downloadPauseGate.Set();

            var thisDownload = Task.Run(async () =>
            {
            // Set once the destination name is known, so a cancelled or aborted transfer can
            // remove the half-written file instead of leaving a truncated installer in the
            // folder for the packaging chain to pick up.
            string partialFile = "";
            long received = 0;
            // Phase timing. Everything before the first byte is invisible from the outside:
            // the panel reads "Connecting..." for the folder wipe, the connect and the
            // server's own think time alike, so a report of "it takes 15 seconds" says
            // nothing about which of the three is responsible. These four numbers separate
            // them, which means a slow download can be diagnosed from a customer's log
            // instead of having to be reproduced on the machine that is slow.
            var phaseWatch = System.Diagnostics.Stopwatch.StartNew();
            long tWipe = -1, tConnect = -1, tFirstByte = -1;
            // Cancels on silence rather than on elapsed time, and is linked to ct so the
            // Cancel button still reaches the request and the read loop.
            using var stallCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
            stallCts.CancelAfter(StallTimeoutMs);
            var dlToken = stallCts.Token;
            try
            {
                // REQ1: Pre-download cleanup of existing files in destination folder
                if (Directory.Exists(destFolder))
                {
                    foreach (string f in Directory.GetFiles(destFolder))
                        try { File.Delete(f); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                    foreach (string d in Directory.GetDirectories(destFolder))
                        try { Directory.Delete(d, recursive: true); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                }
                Directory.CreateDirectory(destFolder);
                tWipe = phaseWatch.ElapsedMilliseconds;

                // ── Mirror-attempt loop ──────────────────────────────────────────────
                // One pass for every host; SourceForge URLs get up to three more passes,
                // each pinning a different mirror, when the read loop below flags the
                // transfer as hopeless. Locals the post-loop verification reads are
                // declared here so they survive the final attempt.
                string fileName = "";
                string destFile = "";
                string finalUrl = "";
                long   total    = -1;
                bool   slowMirrorRetry;
                int    mirrorAttempt  = 0;
                string attemptUrl     = url;
                bool   mirrorEligible = IsSourceForgeUrl(url)
                    && url.IndexOf("use_mirror=", StringComparison.OrdinalIgnoreCase) < 0;
                do
                {
                slowMirrorRetry = false;
                using var response = await _httpDownload.GetAsync(attemptUrl, HttpCompletionOption.ResponseHeadersRead, dlToken);
                tConnect = phaseWatch.ElapsedMilliseconds;
                response.EnsureSuccessStatusCode();

                // The host that actually served the file, which is not always the host that
                // was asked. VideoLAN and SourceForge redirect to a mirror chosen per request,
                // so two runs of the same app can perform completely differently and the only
                // way to see it is to write down which mirror answered.
                string servedBy = response.RequestMessage?.RequestUri?.Host ?? "";
                finalUrl = response.RequestMessage?.RequestUri?.ToString() ?? attemptUrl;
                string askedFor = "";
                try { askedFor = new Uri(url).Host; } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                string hostNote = string.IsNullOrWhiteSpace(servedBy) || string.Equals(servedBy, askedFor, StringComparison.OrdinalIgnoreCase)
                    ? askedFor
                    : $"{askedFor} redirected to {servedBy}";

                // Derive filename: prefer Content-Disposition, then response URI (after redirect), then label
                fileName = "";

                // 1. Content-Disposition header
                if (response.Content.Headers.ContentDisposition?.FileNameStar is string fnStar && !string.IsNullOrWhiteSpace(fnStar))
                    fileName = fnStar.Trim('"');
                else if (response.Content.Headers.ContentDisposition?.FileName is string fn && !string.IsNullOrWhiteSpace(fn))
                    fileName = fn.Trim('"');

                // 2. Response URI (after redirect) — handles SourceForge /download redirects
                if (string.IsNullOrWhiteSpace(fileName) && response.RequestMessage?.RequestUri != null)
                {
                    string uriFile = Path.GetFileName(response.RequestMessage.RequestUri.LocalPath);
                    if (!string.IsNullOrWhiteSpace(uriFile) && uriFile != "download" && uriFile.Contains('.'))
                        fileName = uriFile;
                }

                // 3. Original URL
                if (string.IsNullOrWhiteSpace(fileName))
                {
                    string uriFile = Path.GetFileName(new Uri(url).LocalPath);
                    if (!string.IsNullOrWhiteSpace(uriFile) && uriFile != "download" && uriFile.Contains('.'))
                        fileName = uriFile;
                }

                // 4. Fallback: derive from label + type
                if (string.IsNullOrWhiteSpace(fileName))
                {
                    string ext = label.Contains("MSI") ? ".msi" : ".exe";
                    fileName = $"{appName.Replace(" ", "_")}_{label.Replace(" ", "_")}{ext}";
                }

                // Sanitise filename
                foreach (char c in Path.GetInvalidFileNameChars()) fileName = fileName.Replace(c, '_');
                destFile = Path.Combine(destFolder, fileName);
                partialFile = destFile;

                total         = response.Content.Headers.ContentLength ?? -1;
                received      = 0;

                var stream = await response.Content.ReadAsStreamAsync();
                var fileStream = new FileStream(destFile, FileMode.Create, FileAccess.Write, FileShare.None);
                try
                {
                    var buffer     = new byte[81920];
                    int read;
                    int uiThrottle = 0;
                    while ((read = await stream.ReadAsync(buffer, dlToken)) > 0)
                    {
                        if (tFirstByte < 0)
                        {
                            tFirstByte = phaseWatch.ElapsedMilliseconds;
                            // Written once per download, at the exact moment "Connecting..."
                            // stops being true. wipe is local disk, connect is DNS plus TCP
                            // plus TLS plus any redirect, and think is the server deciding to
                            // start sending. A fixed cost that is the same for a 2 MB app and
                            // a 40 MB app is in connect; a cost that scales with what was
                            // already in the folder is in wipe.
                            LogSched($"{appName}: timing - wipe {tWipe} ms, connect {tConnect - tWipe} ms, " +
                                     $"server think {tFirstByte - tConnect} ms, " +
                                     $"total before first byte {tFirstByte} ms " +
                                     $"({(total > 0 ? $"{total / 1024.0 / 1024.0:0.0} MB" : "size unknown")} from {hostNote})");
                        }
                        if (ct.IsCancellationRequested) break;
                        // Honour pause: block here (without cancelling) until resumed or cancelled.
                        if (!_downloadPauseGate.IsSet)
                        {
                            // A pause is not a stall. Suspend the watchdog while the gate is
                            // shut, or holding the download for longer than StallTimeoutMs
                            // would look exactly like a dead connection.
                            stallCts.CancelAfter(System.Threading.Timeout.InfiniteTimeSpan);
                            try { _downloadPauseGate.Wait(ct); }
                            catch (OperationCanceledException) { break; }
                            stallCts.CancelAfter(StallTimeoutMs);
                        }
                        await fileStream.WriteAsync(buffer.AsMemory(0, read));
                        received += read;
                        stallCts.CancelAfter(StallTimeoutMs); // bytes arrived - push the deadline out
                        // Slow-mirror probe. Fires only when a retry is actually available
                        // (SourceForge URL, mirrors left) and the remaining payload is big
                        // enough to be worth restarting for; measured from THIS attempt's
                        // first byte so a retry judges the new mirror on its own transfer.
                        if (mirrorEligible && mirrorAttempt < SourceForgeFallbackMirrors.Length
                            && tFirstByte >= 0 && (total < 0 || total - received > 4L * 1024 * 1024))
                        {
                            long el = phaseWatch.ElapsedMilliseconds - tFirstByte;
                            if (el > SlowMirrorProbeMs && received * 1000 < SlowMirrorFloorBytesPerSec * el)
                            {
                                slowMirrorRetry = true;
                                break;
                            }
                        }
                        // Update on byte count, not on a known total. A server that sends no
                        // Content-Length used to leave the panel reading "Connecting..." for
                        // the entire transfer, which looks exactly like a download that never
                        // started; UpdateDownloadProgress renders the unknown-total case.
                        // Post-increment: the very first chunk repaints the panel, so the
                        // moment bytes flow "Connecting..." becomes visible progress.
                        if ((uiThrottle++ & 7) == 0)
                        {
                            double pct = total > 0 ? (double)received / total * 100 : 0;
                            Dispatcher.BeginInvoke(
                                new Action(() => UpdateDownloadProgress(progressBorder, myGeneration, pct, received, total)),
                                System.Windows.Threading.DispatcherPriority.Background);
                        }
                    }
                }
                finally
                {
                    await fileStream.FlushAsync();
                    await fileStream.DisposeAsync();
                    await stream.DisposeAsync();
                    // Transfer is over either way. Disarm the watchdog so it cannot fire
                    // during the settle delay or the downstream chain that follows.
                    stallCts.CancelAfter(System.Threading.Timeout.InfiniteTimeSpan);
                }

                if (slowMirrorRetry && !ct.IsCancellationRequested)
                {
                    long elMs = phaseWatch.ElapsedMilliseconds - tFirstByte;
                    // Pin by HOST, not by parameter: use_mirror= is a request to
                    // SourceForge's chooser and the chooser sometimes ignores it - a pinned
                    // retry was observed being served by the same slow mirror it was
                    // escaping. The previous attempt's redirect already exposed the direct
                    // mirror URL (https://<mirror>.dl.sourceforge.net/project/...), and
                    // those are interchangeable by hostname.
                    //
                    // Each candidate is DNS-resolved BEFORE it is used. SourceForge retires
                    // mirror names, and against a direct hostname a retired name is not
                    // silently rerouted the way use_mirror was - it is NXDOMAIN and the
                    // download dies. The preflight turns a dead list entry into a
                    // milliseconds skip instead. If every listed mirror is dead, the
                    // original URL is re-requested once: a fresh roll of the chooser, with
                    // no further probes because the attempts are spent.
                    string  mirror = "";
                    string? next   = null;
                    while (mirrorAttempt < SourceForgeFallbackMirrors.Length && next == null)
                    {
                        mirror = SourceForgeFallbackMirrors[mirrorAttempt++];
                        string cand = mirror + ".dl.sourceforge.net";
                        try { await System.Net.Dns.GetHostAddressesAsync(cand, ct); }
                        catch (OperationCanceledException) { break; }
                        catch
                        {
                            LogSched($"{appName}: SourceForge mirror '{mirror}' does not resolve - skipped");
                            continue;
                        }
                        try
                        {
                            var fu = new Uri(finalUrl);
                            if (fu.Host.EndsWith(".dl.sourceforge.net", StringComparison.OrdinalIgnoreCase))
                                next = new UriBuilder(fu) { Host = cand }.Uri.ToString();
                        }
                        catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                        if (next == null) next = WithSourceForgeMirror(url, mirror);
                    }
                    if (next == null) { next = url; mirror = "chooser (all listed mirrors dead)"; }
                    LogSched($"{appName}: transfer at {(elMs > 0 ? received * 1000 / elMs / 1024 : 0)} KB/s " +
                             $"after {elMs / 1000}s - abandoning this SourceForge mirror, retrying via '{mirror}'");
                    attemptUrl = next;
                    // Per-attempt state back to zero: the file is re-created by the next
                    // attempt's FileMode.Create, the progress panel restarts, and the new
                    // mirror gets a fresh first-byte clock and a fresh stall deadline.
                    received   = 0;
                    tFirstByte = -1;
                    stallCts.CancelAfter(StallTimeoutMs);
                }
                else slowMirrorRetry = false;
                } while (slowMirrorRetry);

                // REQ4: Cancelled — delete partial file
                if (ct.IsCancellationRequested)
                {
                    try { if (File.Exists(destFile)) File.Delete(destFile); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                    // Cancelled before the chain runs — clear pending so the columns unlock.
                    _autoFlowChainPending = false;
                    Dispatcher.Invoke(() => RemoveDownloadProgress(progressBorder, myGeneration));
                    return;
                }

                // Complete — file is now fully closed and released.
                // Req: give a 2-second settle delay after the download completes before the
                // download-complete dialog / downstream auto-flow chain is triggered. Done on
                // the worker thread (not via Dispatcher) so the UI thread is never blocked.
                if (!ct.IsCancellationRequested)
                {
                    try { await Task.Delay(2000, ct); }
                    catch (OperationCanceledException exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                }
                if (ct.IsCancellationRequested)
                {
                    // DIAGNOSTIC. This branch deletes the finished file and returns BEFORE the
                    // version write further down, so an app that downloaded successfully can end
                    // the pass with SourceAppVersion untouched and stay permanently "New". If a
                    // scheduled batch is re-downloading the same upgrade every period, this line
                    // firing once per app is the proof.
                    LogSched($"{appName}: download task saw IsCancellationRequested AFTER the file " +
                             $"finished - deleting {Path.GetFileName(destFile)} and returning early, " +
                             $"so version '{version}' is NOT recorded");
                    try { if (File.Exists(destFile)) File.Delete(destFile); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                    _autoFlowChainPending = false;
                    Dispatcher.Invoke(() => RemoveDownloadProgress(progressBorder, myGeneration));
                    return;
                }

                // DIAGNOSTIC. Reaching here means the cancellation branch above did NOT fire, so
                // the version write is at least going to be attempted. The transfer figure
                // excludes everything before the first byte and the 2-second settle above, so
                // it is the rate the connection actually sustained rather than wall time.
                {
                    long tDone = phaseWatch.ElapsedMilliseconds;
                    long transferMs = tFirstByte < 0 ? 0 : tDone - tFirstByte;
                    string rate = transferMs > 0 && received > 0
                        ? $"{received / 1024.0 / 1024.0 / (transferMs / 1000.0):0.0} MB/s"
                        : "n/a";
                    LogSched($"{appName}: download complete, not cancelled - proceeding to the version write " +
                             $"(transfer {transferMs} ms for {received / 1024.0 / 1024.0:0.0} MB, {rate})");
                }
                if (scheduled)
                {
                    RecordScheduleOutcome(vendor, appName, existingVersion, version, scheduleName, failed: false);
                    QueueStatusWorkbook();
                }

                Dispatcher.Invoke(() =>
                {
                    // ── Req 4: decide whether a downstream auto-flow chain will run BEFORE
                    // removing the progress UI. RemoveDownloadProgress only unlocks the
                    // columns when no chain is pending, so this flag MUST be set first or
                    // the columns would briefly unlock when the download finishes.
                    {
                        bool yesFlag(string v) => v.Equals("Yes", StringComparison.OrdinalIgnoreCase);
                        bool willInstall = _selectedApp != null
                            ? yesFlag(_selectedApp.InstallSourceSilently ?? "No")
                            : (PnlPackageInfo?.Tag is CheckBox[] ci && ci.Length > 0 && ci[0].IsChecked == true);
                        bool willPC = _selectedApp != null
                            ? yesFlag(_selectedApp.CreatePackage ?? "")
                            : (PnlPackageInfo?.Tag is CheckBox[] cp && cp.Length > 2 && cp[2].IsChecked == true);
                        bool willInstallPkg = _selectedApp != null
                            ? (!(_selectedApp.InstallPackage ?? "No").Equals("No", StringComparison.OrdinalIgnoreCase) && !string.IsNullOrWhiteSpace(_selectedApp.InstallPackage))
                            : (PnlPackageInfo?.Tag is CheckBox[] cip && cip.Length > 3 && cip[3].IsChecked == true);
                        bool willUninstallPkg = _selectedApp != null
                            ? (!(_selectedApp.UninstallPackage ?? "No").Equals("No", StringComparison.OrdinalIgnoreCase) && !string.IsNullOrWhiteSpace(_selectedApp.UninstallPackage))
                            : (PnlPackageInfo?.Tag is CheckBox[] cup && cup.Length > 4 && cup[4].IsChecked == true);
                        _autoFlowChainPending = willInstall || willPC || willInstallPkg || willUninstallPkg;
                    }

                    RemoveDownloadProgress(progressBorder, myGeneration);

                    // Read flags — prefer app JSON (works for scheduled/background downloads)
                    // Fall back to UI checkboxes when page is active
                    bool yes(string v) => v.Equals("Yes", StringComparison.OrdinalIgnoreCase);
                    System.Diagnostics.Debug.WriteLine($"[Pkg] _selectedApp={_selectedApp?.SourceAppName ?? "NULL"} CreatePackage={_selectedApp?.CreatePackage ?? "NULL"} InstallPkg={_selectedApp?.InstallPackage ?? "NULL"}");
                    // Read Install/Uninstall source flags — prefer per-app JSON so that
                    // scheduled / background downloads (page not loaded → checkboxes invisible)
                    // correctly honour InstallSourceSilently and UninstallSourceSilently.
                    // Fall back to UI checkboxes only when no JSON app entry is selected.
                    bool doInstall = _selectedApp != null
                        ? yes(_selectedApp.InstallSourceSilently ?? "No")
                        : (PnlPackageInfo?.Tag is CheckBox[] chksI && chksI.Length > 0 && chksI[0].IsChecked == true);
                    bool doUninstall = _selectedApp != null
                        ? yes(_selectedApp.UninstallSourceSilently ?? "No")
                        : (PnlPackageInfo?.Tag is CheckBox[] chksU && chksU.Length > 1 && chksU[1].IsChecked == true);
                    bool doPC           = _selectedApp != null
                        ? yes(_selectedApp.CreatePackage ?? "")
                        : (PnlPackageInfo?.Tag is CheckBox[] chks2 && chks2.Length > 2 && chks2[2].IsChecked == true);
                    bool doInstallPkg   = _selectedApp != null
                        ? !(_selectedApp.InstallPackage ?? "No").Equals("No", StringComparison.OrdinalIgnoreCase) && !string.IsNullOrWhiteSpace(_selectedApp.InstallPackage)
                        : (PnlPackageInfo?.Tag is CheckBox[] chks3 && chks3.Length > 3 && chks3[3].IsChecked == true);
                    bool doUninstallPkg = _selectedApp != null
                        ? !(_selectedApp.UninstallPackage ?? "No").Equals("No", StringComparison.OrdinalIgnoreCase) && !string.IsNullOrWhiteSpace(_selectedApp.UninstallPackage)
                        : (PnlPackageInfo?.Tag is CheckBox[] chks4 && chks4.Length > 4 && chks4[4].IsChecked == true);
                    // When a JSON app is selected the flags above are already set from JSON.
                    // When falling back to UI, also sync from checkboxes (covers the interactive path).
                    if (_selectedApp == null && PnlPackageInfo?.Tag is CheckBox[] chks)
                    {
                        doInstall   = chks.Length > 0 && chks[0].IsChecked == true;
                        doUninstall = chks.Length > 1 && chks[1].IsChecked == true;
                    }

                    // For scheduled downloads, skip the dialog and auto-trigger the package.
                    //
                    // !IsLoaded was only ever a proxy for "nobody is watching", and it reads wrong
                    // the moment a schedule fires while the Download tab happens to be open: the run
                    // is scheduled, but the completion window came up anyway and sat there holding
                    // the scheduler until it was dismissed. The caller now states it outright.
                    bool isScheduled = scheduled || !IsLoaded;
                    bool showMsgBox = !isScheduled && (_selectedApp?.ShowMessageBox ?? "Yes").Equals("Yes", StringComparison.OrdinalIgnoreCase);
                    GlobalShowMessageBox = showMsgBox;
                    // Mirror into the shared Auto-flow flag so silent-source / Intunewin / Publish
                    // status dialogs honour the per-app ShowMessageBox setting too.
                    SwiftPack.Views.AutoShowMessageBox.Value = showMsgBox;
                    // Build unified log path — shared between ShowDownloadCompleteDialog
                    // and RunPsadtCommandAndThenAutoPackage so only one file is created.
                    // Normalise version: strip revision suffix e.g. "3.0.23_09" → "3.0.23"
                    string _logVendor  = (_selectedApp?.AppVendor ?? "").Trim().Replace(" ", "");
                    string _logApp     = appName.Replace(" ", "");
                    string _rawVer     = version.Trim();
                    var _verMatch = System.Text.RegularExpressions.Regex.Match(_rawVer, @"^[\d]+(?:\.[\d]+)*");
                    string _logVer = _verMatch.Success ? _verMatch.Value : _rawVer;
                    foreach (char _lc in Path.GetInvalidFileNameChars())
                    { _logVendor = _logVendor.Replace(_lc,'_'); _logApp = _logApp.Replace(_lc,'_'); _logVer = _logVer.Replace(_lc,'_'); }
                    string unifiedLogPath = Path.Combine(Path.GetTempPath(),
                        $"AutoPackage_{_logVendor}_{_logApp}_{_logVer}.log");

                    // Icon.png is not fetched from the vendor site on download either: the same
                    // favicon fallback produced under-sized logos, and writing one here would
                    // again pre-empt the 256px logo the Execute (Install) step creates from the
                    // installed application's icon. Execute is the single writer now.

                    if (!isScheduled) ShowDownloadCompleteDialog(appName, version, destFile, destFolder, showMsgBox, _selectedApp?.AppVendor ?? "", unifiedLogPath);
                    System.Diagnostics.Debug.WriteLine($"[Pkg] isScheduled={isScheduled} doPC={doPC} destFile={destFile}");

                    // Persist the downloaded version so we can detect newer versions later.
                    // SourceAppVersion drives the "New" badge comparison; AppVersion (PSADT /
                    // package naming) and IntuneAppVersion (Intune metadata) are kept in sync
                    // so the next Create Package / Publish uses the freshly downloaded version.
                    //
                    // DIAGNOSTIC. The write targets _selectedApp rather than the entry the caller
                    // named, so it only reaches the scheduler if _selectedApp is still the SAME
                    // OBJECT as the _allApps entry for this app. sameRefAsList=NO would mean the
                    // write lands on a detached copy while the scheduler keeps reading the old
                    // version off the list, which is what re-downloading every period looks like.
                    DownloadSourceEntry? dbgListEntry = _allApps.FirstOrDefault(
                        a => string.Equals(a.SourceAppName, appName, System.StringComparison.OrdinalIgnoreCase));
                    LogSched($"{appName}: version write ATTEMPT - selected={_selectedApp?.SourceAppName ?? "NULL"} " +
                             $"newVersion='{version}' " +
                             $"sameRefAsList={(object.ReferenceEquals(_selectedApp, dbgListEntry) ? "yes" : "NO")} " +
                             $"listVersionBefore={(dbgListEntry == null ? "MISSING" : dbgListEntry.SourceAppVersion)}");

                    if (_selectedApp != null && !string.IsNullOrWhiteSpace(version))
                    {
                        _selectedApp.SourceAppVersion = version;
                        _selectedApp.AppVersion       = version;
                        _selectedApp.IntuneAppVersion = version;
                        SaveApps();

                        // DIAGNOSTIC. Three readings of the same value straight after the save:
                        // the object written to, the entry the scheduler will read next period,
                        // and what actually reached the per-app JSON. Whichever of the three is
                        // still the old version is the one to fix.
                        LogSched($"{appName}: version write DONE - selected={_selectedApp.SourceAppVersion} " +
                                 $"listVersionAfter={(dbgListEntry == null ? "MISSING" : dbgListEntry.SourceAppVersion)} " +
                                 $"onDisk={SourceAppVersionOnDisk(_selectedApp)}");

                        // Arms the single repaint at the end of RunScheduledDownloadsAsync. The
                        // renders just below are still worth doing so a lone download updates
                        // immediately; the batch pass is what covers the case where the next app
                        // paints over them before anyone sees it.
                        _repaintPending = true;

                        // Refresh every place a version change shows up: vendor badges, app card
                        // badges, the toolbar Updates count and the version row in the info panel.
                        //
                        // RefreshUpdatesBadge is the part that was missing here. Its only callers
                        // were "Check now", page load, and the end-of-batch repaint in
                        // RunScheduledDownloadsAsync, so a scheduled download that finished cleanly
                        // could sit there reading "Updates (2)" with nothing out of date. That
                        // stale toolbar count is itself the proof that the end-of-batch block never
                        // ran, which is why the badges below it were stale too.
                        //
                        // The bare RenderVendors/RenderCards pair that used to be here painted into
                        // "this", which is not necessarily the page on screen, and was unguarded:
                        // either render throwing unwound the rest of this completion block out
                        // through the scheduler's per-app catch, taking the chain with it.
                        SdRefreshDownloadTabAfterVersionChange(appName, version);
                        // Re-render info panel so the version row "New" badge clears
                        if (_selectedApp != null)
                        {
                            var appToRefresh = _selectedApp;
                            _ = FetchAndShowAsync(appToRefresh);
                        }
                    }
                    else
                    {
                        // DIAGNOSTIC. This guard is the only thing between a finished download and
                        // the version being recorded, and today it fails without a word.
                        LogSched($"{appName}: version write SKIPPED - " +
                                 $"{(_selectedApp == null ? "_selectedApp was null" : "version string was blank")}");
                    }

                    // ── Req: keep Download/Package columns locked through the WHOLE chain ──
                    // If any downstream auto-action will run (install source, create package,
                    // install/uninstall package — which in turn lead to Execute / Intunewin /
                    // Publish), register an all-complete callback on AutoPackagePage so the
                    // columns unlock only after every tab's actions finish. Otherwise the
                    // plain-download path unlocks normally in RemoveDownloadProgress.
                    bool willRunChain = doInstall || doPC || doInstallPkg || doUninstallPkg;
                    if (willRunChain)
                    {
                        _autoFlowChainPending = true; // (already set above; keep locked)
                        // The chain outlives the download: it drives the manual pages, so the
                        // manual nav stays locked until RenderAutoFlowStatusPanel reports the
                        // whole flow finished.
                        AppBusy.SetAuto("Auto Package chain", true);
                        // A scheduled chain marks itself so its finish can amend the status
                        // row; a manual chain clears the marker so it can never amend one.
                        _scheduledChainKey = isScheduled ? (vendor + "|" + appName).Trim() : null;
                        try
                        {
                            _mainWindow ??= Window.GetWindow(this) as IAutoPackageHost;
                            var autoPg = _mainWindow?.AutoPackagePage ?? FindAncestorAutoPackagePage();
                            autoPg?.SetAutoFlowCompleteCallback(() =>
                            {
                                // Marshalled to the UI thread by AutoPackagePage.RaiseAutoFlowComplete.
                                _autoFlowChainPending = false;
                                UnlockDownloadAndPackageColumns();
                                // Icon.png now exists in the app's folder - fill the Intune Logo box
                                // on this FIRST run instead of waiting for a later panel re-render.
                                ApplyIconLogoForFinishedApp(vendor, appName);
                                // Same idea for the Intune Install/Uninstall Command: with no PSADT
                                // template, the Source command Create Package computed IS the Intune
                                // command. Carry it into the JSON and refresh the tab now, so the
                                // FIRST run shows it and a second run (EXE after MSI) replaces the
                                // earlier value instead of leaving it on screen.
                                ApplyIntuneCommandsForFinishedApp(vendor, appName);
                            });
                            // When per-action status is computed, paint the result panel and
                            // return focus to the Download tab.
                            autoPg?.SetAutoFlowStatusReadyCallback(() =>
                            {
                                try { autoPg?.ActivateTopTab("Download"); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                                RenderAutoFlowStatusPanel();
                            });
                        }
                        catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                    }
                    else
                    {
                        // No chain will run — make sure the flag is clear so the columns
                        // unlock (they were unlocked by RemoveDownloadProgress above).
                        _autoFlowChainPending = false;
                        // The download IS the whole flow here, so it writes the footer
                        // verdict itself. Interactive runs only: on a scheduled run the app
                        // on screen is whatever the user is looking at, not necessarily the
                        // app that finished, and the footer is not keyed to an app.
                        if (!isScheduled) ShowDownloadStatusLine(failed: false);
                    }

                    // PSADT Template Folder guard (Create Package pre-flight).
                    // The per-app PSADT Template Folder drives packaging, but a bad template used
                    // to be skipped SILENTLY - the package was built WITHOUT a usable template and
                    // looked fine, which is pure confusion. Fail loudly instead: log the exact path,
                    // paint "Create package" red in the checklist, and end the flow so NO package is
                    // created. The download itself succeeded and stays.
                    //
                    // TWO ways the template is unusable, one abort. The second was found by renaming
                    // the script to "-Invoke-AppDeployToolkit.ps1": the folder existed, the copy ran,
                    // the package folder appeared and the footer said Completed - but the package had
                    // no entry point, so it could never install. The Download Information column
                    // warned about it and nothing acted on the warning.
                    //
                    // The presence test is the SAME helper the warning uses, so the panel and this
                    // guard can never disagree about whether a template is usable - including its
                    // exclusion of the decoy copy the toolkit ships inside its own module folder.
                    if (doPC)
                    {
                        string tplGuard = (_selectedApp?.PSADTTemplateFolder ?? "").Trim();
                        string? abortWhy = null, abortFix = null;

                        if (tplGuard.Length > 0 && !Directory.Exists(tplGuard))
                        {
                            abortWhy = $"PSADT Template Folder not found on this machine: \"{tplGuard}\"";
                            abortFix = "The package was not created. Restore the folder or correct the path in Package settings, then run again.";
                        }
                        else if (tplGuard.Length > 0 && !HasInvokeAppDeployToolkitScript(tplGuard))
                        {
                            abortWhy = $"Invoke-AppDeployToolkit.ps1 not found in the PSADT Template Folder or any of its subfolders: \"{tplGuard}\"";
                            abortFix = "The package was not created. Add the script to the template folder or correct the path in Package settings, then run again.";
                        }

                        if (abortWhy != null)
                        {
                            try
                            {
                                File.AppendAllText(unifiedLogPath,
                                    $"[{DateTime.Now:HH:mm:ss}] Create package ABORTED: {abortWhy}{Environment.NewLine}" +
                                    $"[{DateTime.Now:HH:mm:ss}] {abortFix}{Environment.NewLine}");
                            }
                            catch { }
                            LogWinget($"[CreatePackage] ABORTED - {abortWhy}");
                            // Surface the same abort message in the Download Information column
                            // (empty area under the action checklist), keyed to this app.
                            SetPackageErrorNotice("Create package failed", abortWhy, abortFix);
                            AutoFlowStatus.Set(AutoFlowStatus.CreatePackage, AutoFlowStatus.State.Failed);
                            AutoFlowStatus.SetPackageName(_selectedApp?.SourceAppName ?? appName);
                            AutoFlowStatus.Finish();   // FlowRunning=false; status panel shows the failed step
                            // This whole completion block already runs on the UI thread (inside the
                            // Dispatcher.Invoke that opened earlier), so update the panel and unlock
                            // directly - no nested dispatcher call, and no await (this lambda is not async).
                            RenderAutoFlowStatusPanel();
                            _autoFlowChainPending = false;
                            if (_downloadColumnsLocked) UnlockDownloadAndPackageColumns();
                            return;
                        }
                    }

                    // ── Trigger sequential flow AFTER the download dialog is closed ──
                    // Fully decoupled from ValidateSourcePage — uses direct silent install/uninstall.
                    if (doInstall)
                    {
                        string ext   = Path.GetExtension(destFile).ToLowerInvariant();
                        bool   isMsi = ext == ".msi" || ext == ".msp";

                        // Read intunewin/publish flags early — needed for command building below.
                        bool _doCreateIw  = PnlPackageInfo?.Tag is CheckBox[] _iwChksE && _iwChksE.Length > 5 && _iwChksE[5].IsChecked == true;
                        bool _doPublishIw = PnlPackageInfo?.Tag is CheckBox[] _pbChksE && _pbChksE.Length > 6 && _pbChksE[6].IsChecked == true;

                        // ── Build install command ─────────────────────────────────────
                        // When Create Package is NOT checked (doPC=false), always use the
                        // source-direct command — PSADTInstallCommand requires the PSADT
                        // package to exist and must not be used here.
                        // When doPC=true, honour PSADTInstallCommand if set in per-app JSON.
                        string psadtInstallCmd = (!doPC ? "" : (_selectedApp?.PSADTInstallCommand ?? ""));
                        string pkgInstallArgs  = isMsi
                            ? (_selectedApp?.SilentInstallParameterMSI ?? "")
                            : (_selectedApp?.SilentInstallParameterEXE ?? "");
                        if (string.IsNullOrWhiteSpace(psadtInstallCmd))
                        {
                            psadtInstallCmd = isMsi
                                ? $"msiexec.exe /i \"{destFile}\" {pkgInstallArgs}".TrimEnd()
                                : $"\"{destFile}\" {pkgInstallArgs}".TrimEnd();
                        }

                        // ── Build uninstall command ───────────────────────────────────
                        // Same rule: when doPC=false, use source-direct command only.
                        string psadtUninstallCmd = (!doPC ? "" : (_selectedApp?.PSADTUninstallCommand ?? ""));
                        string pkgUninstallArgs  = isMsi
                            ? (_selectedApp?.SilentUninstallParameterMSI ?? "")
                            : (_selectedApp?.SilentUninstallParameterEXE ?? "");
                        if (string.IsNullOrWhiteSpace(psadtUninstallCmd) && doUninstall && !(_doCreateIw || _doPublishIw))
                        {
                            // For MSI: read product code from the file and use msiexec /x {ProductCode}.
                            // Fall back to file path if product code cannot be read.
                            string srcUninstFile = !string.IsNullOrWhiteSpace(_selectedApp?.UninstallPath ?? "")
                                ? (_selectedApp?.UninstallPath ?? "") : destFile;
                            if (isMsi)
                            {
                                string pc = ReadMsiProductCodeSTA(destFile);
                                psadtUninstallCmd = !string.IsNullOrWhiteSpace(pc)
                                    ? $"msiexec.exe /x {pc} {pkgUninstallArgs}".TrimEnd()
                                    : $"msiexec.exe /x \"{destFile}\" {pkgUninstallArgs}".TrimEnd();
                            }
                            else
                            {
                                psadtUninstallCmd = $"\"{srcUninstFile}\" {pkgUninstallArgs}".TrimEnd();
                            }
                        }

                        string pkgAppVendor      = _selectedApp?.AppVendor           ?? "";
                        string pkgAppName        = _selectedApp?.AppName             ?? "";
                        string pkgCloseApps      = _selectedApp?.CloseApps           ?? "";
                        string pkgAppVersion     = _selectedApp?.AppVersion          ?? "";
                        string pkgUninstallPath  = _selectedApp?.UninstallPath       ?? "";
                        string pkgTemplateFolder = _selectedApp?.PSADTTemplateFolder ?? "";
                        string pkgSourceAppName  = _selectedApp?.SourceAppName ?? pkgAppName;
                        bool   hasAppTpl         = !string.IsNullOrWhiteSpace(pkgTemplateFolder);

                        var mwInstall = _mainWindow ?? Dispatcher.Invoke(() => Window.GetWindow(this) as IAutoPackageHost);
                        if (mwInstall != null)
                        {
                            // Build per-app IntuneSettings overrides
                            var appIntuneOverrides = new AutoIntuneSettingsOverride
                            {
                                InstallCommand            = _selectedApp?.InstallCommand            ?? "",
                                UninstallCommand          = _selectedApp?.UninstallCommand          ?? "",
                                AllowAvailableUninstall   = _selectedApp?.AllowAvailableUninstall   ?? "",
                                InstallBehavior           = !string.IsNullOrWhiteSpace(_selectedApp?.InstallBehavior) ? _selectedApp!.InstallBehavior : _selectedApp?.InstallBehaviour ?? "",
                                DeviceRestartBehaviour    = _selectedApp?.DeviceRestartBehaviour    ?? "",
                                MinimumOperatingSystem    = _selectedApp?.MinimumOperatingSystem    ?? "",
                                OperatingSystemArchitecture = _selectedApp?.OperatingSystemArchitecture ?? "",
                                AssignmentsAvailable      = !string.IsNullOrWhiteSpace(_selectedApp?.AssignmentsAvailable) ? _selectedApp!.AssignmentsAvailable : _selectedApp?.GroupName ?? "",
                                RulesFormat                          = _selectedApp?.RulesFormat                          ?? "Manual detection rules",
                                DetectionTypeMSI                     = _selectedApp?.DetectionTypeMSI                     ?? "No",
                                DetectionTypeFile                    = _selectedApp?.DetectionTypeFile                    ?? "No",
                                DetectionTypeRegistry                = _selectedApp?.DetectionTypeRegistry                ?? "No",
                                DetectionMsiVersionCheck             = _selectedApp?.DetectionMsiVersionCheck             ?? "",
                                DetectionMsiOperator                 = _selectedApp?.DetectionMsiOperator                 ?? "",
                                DetectionFileFolderPath              = _selectedApp?.DetectionFileFolderPath              ?? "",
                                DetectionFileFileName                = _selectedApp?.DetectionFileFileName                ?? "",
                                DetectionFileDetectionMethod               = _selectedApp?.DetectionFileDetectionMethod               ?? "",
                                DetectionFileOperator                = _selectedApp?.DetectionFileOperator                ?? "",
                                DetectionFile32Bit                   = _selectedApp?.DetectionFile32Bit                   ?? "",
                                DetectionFileValue                   = _selectedApp?.DetectionFileValue                   ?? "",
                                DetectionFileSizeValue               = _selectedApp?.DetectionFileSizeValue               ?? "",
                                DetectionFileTimeValue               = _selectedApp?.DetectionFileTimeValue               ?? "",
                                DetectionRegKeyPath                  = _selectedApp?.DetectionRegKeyPath                  ?? "",
                                DetectionRegValueName                = _selectedApp?.DetectionRegValueName                ?? "",
                                DetectionRegDetectionMethod                = _selectedApp?.DetectionRegDetectionMethod                ?? "",
                                DetectionRegOperator                 = _selectedApp?.DetectionRegOperator                 ?? "",
                                DetectionReg32Bit                    = _selectedApp?.DetectionReg32Bit                    ?? "",
                                DetectionScriptFile                  = _selectedApp?.DetectionScriptFile                  ?? "",
                                DetectionScriptEnforceSignatureCheck = _selectedApp?.DetectionScriptEnforceSignatureCheck ?? "",
                                DetectionScriptRunAs32Bit            = _selectedApp?.DetectionScriptRunAs32Bit            ?? "",
                                Developer                 = _selectedApp?.Developer                 ?? "",
                                Owner                     = _selectedApp?.Owner                     ?? "",
                                FeaturedApp               = _selectedApp?.FeaturedApp               ?? "",
                                Category                  = !string.IsNullOrWhiteSpace(_selectedApp?.IntuneCategory) ? _selectedApp!.IntuneCategory : _selectedApp?.Category ?? "",
                                Description               = _selectedApp?.Description               ?? "",
                                IntuneAppName             = _selectedApp?.IntuneAppName             ?? "",
                                IntuneAppVendor           = _selectedApp?.IntuneAppVendor           ?? "",
                                IntuneAppVersion          = _selectedApp?.IntuneAppVersion          ?? "",
                                InformationURL            = _selectedApp?.InformationURL            ?? "",
                                PrivacyURL                = _selectedApp?.PrivacyURL                ?? "",
                                Notes                     = _selectedApp?.Notes                     ?? "",
                                Logo                      = _selectedApp?.Logo                      ?? "",
                                InstallationTime          = _selectedApp?.InstallationTime          ?? "",
                            };

                            // ── Auto-populate empty detection fields from downloaded file ───────
                            // Runs for both MSI and EXE, before SetStaticSelectedApp, while the
                            // downloaded file is on disk.
                            // MSI: product code read from file → registry lookup by GUID key.
                            // EXE: no product code → registry scan by DisplayName (app name).
                            // Snapshot detection fields first so the resolved PREFILL values used
                            // for the downstream Publish objects are NOT persisted to JSON.
                            string[]? _detPrefillSnapshot = SnapshotDetectionPrefillFields();
                            if (_selectedApp != null && File.Exists(destFile) &&
                                (_selectedApp.RulesFormat ?? "Manual detection rules")
                                    .Equals("Manual detection rules", StringComparison.OrdinalIgnoreCase))
                            {
                                bool needsAnyFill =
                                    string.IsNullOrWhiteSpace(_selectedApp.DetectionFileFolderPath) ||
                                    string.IsNullOrWhiteSpace(_selectedApp.DetectionFileFileName)   ||
                                    string.IsNullOrWhiteSpace(_selectedApp.DetectionFileValue)      ||
                                    string.IsNullOrWhiteSpace(_selectedApp.DetectionRegKeyPath)     ||
                                    string.IsNullOrWhiteSpace(_selectedApp.DetectionRegistryValue)  ||
                                    (isMsi && (
                                        string.IsNullOrWhiteSpace(_selectedApp.DetectionMsiProductCode) ||
                                        string.IsNullOrWhiteSpace(_selectedApp.DetectionMsiValue)));

                                if (needsAnyFill)
                                {
                                    // Shared helper: given an open registry key + full path, fill empty fields
                                    void FillFromRegKey(Microsoft.Win32.RegistryKey key, string regPath)
                                    {
                                        string dispVer  = key.GetValue("DisplayVersion")  as string ?? "";
                                        string instLoc  = (key.GetValue("InstallLocation") as string ?? "")
                                                              .TrimEnd(Path.DirectorySeparatorChar);
                                        string dispIcon = (key.GetValue("DisplayIcon")     as string ?? "")
                                                              .Split(',')[0].Trim().Trim('"');

                                        // Derive InstallLocation from DisplayIcon if empty
                                        if (string.IsNullOrWhiteSpace(instLoc) &&
                                            dispIcon.EndsWith(".exe", StringComparison.OrdinalIgnoreCase))
                                            instLoc = (Path.GetDirectoryName(dispIcon) ?? "")
                                                          .TrimEnd(Path.DirectorySeparatorChar);

                                        // MSI-only: DetectionMsiValue from DisplayVersion
                                        if (isMsi && string.IsNullOrWhiteSpace(_selectedApp.DetectionMsiValue) &&
                                            !string.IsNullOrWhiteSpace(dispVer))
                                            _selectedApp.DetectionMsiValue = dispVer;

                                        // DetectionRegKeyPath
                                        if (string.IsNullOrWhiteSpace(_selectedApp.DetectionRegKeyPath))
                                            _selectedApp.DetectionRegKeyPath = regPath;

                                        // DetectionRegistryValue — DisplayVersion
                                        if (string.IsNullOrWhiteSpace(_selectedApp.DetectionRegistryValue) &&
                                            !string.IsNullOrWhiteSpace(dispVer))
                                            _selectedApp.DetectionRegistryValue = dispVer;

                                        // DetectionFileFolderPath — InstallLocation
                                        if (string.IsNullOrWhiteSpace(_selectedApp.DetectionFileFolderPath) &&
                                            !string.IsNullOrWhiteSpace(instLoc))
                                            _selectedApp.DetectionFileFolderPath = instLoc;

                                        // DetectionFileFileName + DetectionFileValue — main exe
                                        if (string.IsNullOrWhiteSpace(_selectedApp.DetectionFileFileName))
                                        {
                                            string exePath = "";

                                            // 1. DisplayIcon if it is a .exe that exists
                                            if (!string.IsNullOrWhiteSpace(dispIcon) &&
                                                dispIcon.EndsWith(".exe", StringComparison.OrdinalIgnoreCase) &&
                                                File.Exists(dispIcon))
                                                exePath = dispIcon;

                                            // 2. Largest exe in InstallLocation
                                            if (string.IsNullOrWhiteSpace(exePath) &&
                                                !string.IsNullOrWhiteSpace(instLoc) && Directory.Exists(instLoc))
                                            {
                                                try
                                                {
                                                    var exes = Directory.GetFiles(instLoc, "*.exe",
                                                                   SearchOption.TopDirectoryOnly);
                                                    if (exes.Length > 0)
                                                        exePath = exes.OrderByDescending(
                                                            e => new System.IO.FileInfo(e).Length).First();
                                                }
                                                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                                            }

                                            // 3. Start Menu .lnk shortcuts whose name matches app name
                                            if (string.IsNullOrWhiteSpace(exePath))
                                            {
                                                string appHint = _selectedApp.SourceAppName?.Trim() ?? "";
                                                var startDirs = new[]
                                                {
                                                    Environment.GetFolderPath(Environment.SpecialFolder.CommonPrograms),
                                                    Environment.GetFolderPath(Environment.SpecialFolder.Programs),
                                                };
                                                foreach (string sDir in startDirs.Where(
                                                    d => !string.IsNullOrWhiteSpace(d) && Directory.Exists(d)))
                                                {
                                                    try
                                                    {
                                                        foreach (string lnk in Directory.GetFiles(
                                                            sDir, "*.lnk", SearchOption.AllDirectories))
                                                        {
                                                            try
                                                            {
                                                                var shell = Activator.CreateInstance(
                                                                    Type.GetTypeFromProgID("WScript.Shell")!);
                                                                if (shell == null) continue;
                                                                var sc = shell.GetType().InvokeMember(
                                                                    "CreateShortcut",
                                                                    System.Reflection.BindingFlags.InvokeMethod,
                                                                    null, shell, new object[] { lnk });
                                                                if (sc == null) continue;
                                                                string target = sc.GetType().InvokeMember(
                                                                    "TargetPath",
                                                                    System.Reflection.BindingFlags.GetProperty,
                                                                    null, sc, null)?.ToString() ?? "";
                                                                if (!target.EndsWith(".exe",
                                                                        StringComparison.OrdinalIgnoreCase) ||
                                                                    !File.Exists(target)) continue;
                                                                string lnkName = Path.GetFileNameWithoutExtension(lnk);
                                                                bool match =
                                                                    (!string.IsNullOrWhiteSpace(appHint) &&
                                                                     (lnkName.Contains(appHint,
                                                                          StringComparison.OrdinalIgnoreCase) ||
                                                                      appHint.Contains(lnkName,
                                                                          StringComparison.OrdinalIgnoreCase))) ||
                                                                    (!string.IsNullOrWhiteSpace(instLoc) &&
                                                                     target.StartsWith(instLoc,
                                                                          StringComparison.OrdinalIgnoreCase));
                                                                if (match) { exePath = target; break; }
                                                            }
                                                            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                                                        }
                                                        if (!string.IsNullOrWhiteSpace(exePath)) break;
                                                    }
                                                    catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                                                }
                                            }

                                            if (!string.IsNullOrWhiteSpace(exePath))
                                            {
                                                _selectedApp.DetectionFileFileName = Path.GetFileName(exePath);
                                                if (string.IsNullOrWhiteSpace(_selectedApp.DetectionFileFolderPath))
                                                    _selectedApp.DetectionFileFolderPath =
                                                        Path.GetDirectoryName(exePath) ?? "";
                                                if (string.IsNullOrWhiteSpace(_selectedApp.DetectionFileValue) &&
                                                    File.Exists(exePath))
                                                {
                                                    try
                                                    {
                                                        var fvi = System.Diagnostics.FileVersionInfo
                                                                      .GetVersionInfo(exePath);
                                                        string fv = (fvi.FileMajorPart > 0 || fvi.FileMinorPart > 0 ||
                                                                     fvi.FileBuildPart > 0 || fvi.FilePrivatePart > 0)
                                                            ? $"{fvi.FileMajorPart}.{fvi.FileMinorPart}.{fvi.FileBuildPart}.{fvi.FilePrivatePart}"
                                                            : fvi.FileVersion?.Trim() ?? "";
                                                        if (!string.IsNullOrWhiteSpace(fv))
                                                            _selectedApp.DetectionFileValue = fv;
                                                    }
                                                    catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                                                }
                                            }
                                        }
                                    } // end FillFromRegKey

                                    var hives = new[]
                                    {
                                        (Microsoft.Win32.Registry.LocalMachine,
                                         @"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"),
                                        (Microsoft.Win32.Registry.LocalMachine,
                                         @"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall"),
                                        (Microsoft.Win32.Registry.CurrentUser,
                                         @"Software\Microsoft\Windows\CurrentVersion\Uninstall"),
                                    };

                                    if (isMsi)
                                    {
                                        // ── MSI: look up by product code ─────────────────────────
                                        string resolvedPc = _selectedApp.DetectionMsiProductCode?.Trim() ?? "";
                                        if (string.IsNullOrWhiteSpace(resolvedPc))
                                            resolvedPc = ReadMsiProductCodeSTA(destFile);

                                        if (!string.IsNullOrWhiteSpace(resolvedPc))
                                        {
                                            // NOTE: do NOT write the auto-resolved product code into
                                            // _selectedApp.DetectionMsiProductCode. That value is PREFILL
                                            // data (resolved from the .msi / registry during this download)
                                            // and must not be persisted to the per-app template JSON —
                                            // otherwise a later EXE download inherits the previous MSI run's
                                            // product code. It is used locally below only to find the
                                            // matching uninstall registry key. A product code the USER typed
                                            // in the Package Information column is stored via its own UI
                                            // binding and is unaffected by this.

                                            string pcKey = resolvedPc.Trim();
                                            if (!pcKey.StartsWith("{")) pcKey = "{" + pcKey;
                                            if (!pcKey.EndsWith("}"))   pcKey += "}";

                                            foreach (var (hRoot, sub) in hives)
                                            {
                                                try
                                                {
                                                    using var hive = hRoot.OpenSubKey(sub);
                                                    if (hive == null) continue;
                                                    using var key  = hive.OpenSubKey(pcKey);
                                                    if (key  == null) continue;
                                                    string hName = hRoot == Microsoft.Win32.Registry.CurrentUser
                                                        ? "HKEY_CURRENT_USER" : "HKEY_LOCAL_MACHINE";
                                                    FillFromRegKey(key, $"{hName}\\{sub}\\{pcKey}");
                                                    break;
                                                }
                                                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                                            }
                                        }
                                    }
                                    else
                                    {
                                        // ── EXE: scan hives by DisplayName matching app name ──────
                                        string appHint = _selectedApp.SourceAppName?.Trim() ?? "";
                                        if (string.IsNullOrWhiteSpace(appHint))
                                            appHint = _selectedApp.AppName?.Trim() ?? "";

                                        if (!string.IsNullOrWhiteSpace(appHint))
                                        {
                                            // Find best match: longest DisplayName that contains appHint
                                            int bestLen = 0;
                                            foreach (var (hRoot, sub) in hives)
                                            {
                                                try
                                                {
                                                    using var hive = hRoot.OpenSubKey(sub);
                                                    if (hive == null) continue;
                                                    foreach (string subName in hive.GetSubKeyNames())
                                                    {
                                                        try
                                                        {
                                                            using var key = hive.OpenSubKey(subName);
                                                            if (key == null) continue;
                                                            string dn = key.GetValue("DisplayName") as string ?? "";
                                                            if (string.IsNullOrWhiteSpace(dn)) continue;
                                                            bool match =
                                                                dn.Contains(appHint, StringComparison.OrdinalIgnoreCase) ||
                                                                appHint.Contains(dn, StringComparison.OrdinalIgnoreCase);
                                                            if (!match || dn.Length <= bestLen) continue;
                                                            bestLen = dn.Length;
                                                            string hName = hRoot == Microsoft.Win32.Registry.CurrentUser
                                                                ? "HKEY_CURRENT_USER" : "HKEY_LOCAL_MACHINE";
                                                            FillFromRegKey(key, $"{hName}\\{sub}\\{subName}");
                                                        }
                                                        catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                                                    }
                                                }
                                                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                                            }
                                        }
                                    }

                                }
                            }
                            // ── End auto-populate ───────────────────────────────────────────────

                            AutoPackagePage.SetStaticSelectedApp(_selectedApp == null ? null : new SwiftPack.Views.AutoPackageAppEntry
                                                        {
                                                            SourceAppName                        = _selectedApp.SourceAppName                        ?? "",
                                                            Description                          = _selectedApp.Description                          ?? "",
                                                            Developer                            = _selectedApp.Developer                            ?? "",
                                                            Owner                                = _selectedApp.Owner                                ?? "",
                                                            InformationURL                       = _selectedApp.InformationURL                       ?? "",
                                                            PrivacyURL                           = _selectedApp.PrivacyURL                           ?? "",
                                                            Notes                                = _selectedApp.Notes                                ?? "",
                                                            Logo                                 = _selectedApp.Logo                                 ?? "",
                                                            IntuneCategory                       = _selectedApp.IntuneCategory                       ?? "",
                                                            FeaturedApp                          = _selectedApp.FeaturedApp                          ?? "",
                                                            IntuneAppName                        = _selectedApp.IntuneAppName                        ?? "",
                                                            IntuneAppVendor                      = _selectedApp.IntuneAppVendor                      ?? "",
                                                            IntuneAppVersion                     = _selectedApp.IntuneAppVersion                     ?? "",
                                                            InstallCommand                       = _selectedApp.InstallCommand                       ?? "",
                                                            UninstallCommand                     = _selectedApp.UninstallCommand                     ?? "",
                                                            AllowAvailableUninstall              = _selectedApp.AllowAvailableUninstall              ?? "",
                                                            InstallBehavior                      = _selectedApp.InstallBehavior                      ?? "",
                                                            InstallationTime                     = _selectedApp.InstallationTime                     ?? "",
                                                            DeviceRestartBehaviour               = _selectedApp.DeviceRestartBehaviour               ?? "",
                                                            MinimumOperatingSystem               = _selectedApp.MinimumOperatingSystem               ?? "",
                                                            OperatingSystemArchitecture          = _selectedApp.OperatingSystemArchitecture          ?? "",
                                                            RulesFormat                          = _selectedApp.RulesFormat                          ?? "",
