                                                        PSADTUninstallCommand                = _selectedApp.PSADTUninstallCommand                ?? "",
                                                        SourceInstallCommand                 = _selectedApp.SourceInstallCommand                 ?? "",
                                                        SourceUninstallCommand               = _selectedApp.SourceUninstallCommand               ?? "",
                                                        DownloadPreference                   = _selectedApp.DownloadPreference                   ?? "",
                                                        // ── Install / Uninstall context — must be passed so AutoPackagePage
                                                        //    can trigger the correct SYSTEM CONTEXT or ADMINISTRATOR button
                                                        InstallPackage                       = _selectedApp.InstallPackage                       ?? "",
                                                        UninstallPackage                     = _selectedApp.UninstallPackage                     ?? "",
                                                        OpenApplication                      = _selectedApp.OpenApplication                      ?? "No",
                                                        CreateIntunewin                      = _selectedApp.CreateIntunewin                      ?? "",
                                                        PublishToIntune                      = _selectedApp.PublishToIntune                      ?? "",
                                                        PublishSettings                      = _selectedApp.PublishSettings                      ?? "",
                                                        AddSupersedenceAutomatically         = _selectedApp.AddSupersedenceAutomatically         ?? "Yes",
                                                    });
                        AutoPackagePage.SetStaticPendingMetadata(
                            templateFolder:          pkgTemplateFolder,
                            createIntunewin:         pkgCreateIntunewin,
                            publishToIntune:         (_selectedApp?.PublishSettings ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase) ? "Yes" : "No",
                            assignToGroup:           "",
                            msiInstallArgs:          _selectedApp?.SilentInstallParameterMSI   ?? "",
                            msiUninstallArgs:        _selectedApp?.SilentUninstallParameterMSI ?? "",
                            description:             _selectedApp?.Description                 ?? "",
                            groupName:               _selectedApp?.GroupName                   ?? "",
                            packageOutputFolder:     _packageOutputFolder,
                            createMst:               _selectedApp?.CreateMST                    ?? "",
                            removeDesktopShortcut:   _selectedApp?.RemoveDesktopShortcut        ?? "",
                            packageTemplateFolder:   _selectedApp?.PackageTemplateFolder        ?? "",
                            installPackage:          _selectedApp?.InstallPackage ?? "No",
                            uninstallPackage:        _selectedApp?.UninstallPackage ?? "No",
                            addInstallName:          _selectedApp?.AddInstallName  ?? "",
                            addInstallTitle:         _selectedApp?.AddInstallTitle ?? "",
                            addNoModify:             hasAppTpl2 ? (_selectedApp?.AddNoModify ?? "") : "",
                            addNoRepair:             hasAppTpl2 ? (_selectedApp?.AddNoRepair ?? "") : "",
                            addNoRemove:             hasAppTpl2 ? (_selectedApp?.AddNoRemove ?? "") : "",
                            dependency1:             _selectedApp?.Dependency1   ?? "",
                            autoInstallDependency1:  _selectedApp?.AutoInstallDependency1 ?? "No",
                            dependency2:             _selectedApp?.Dependency2   ?? "",
                            autoInstallDependency2:  _selectedApp?.AutoInstallDependency2 ?? "No",
                            dependency3:             _selectedApp?.Dependency3   ?? "",
                            autoInstallDependency3:  _selectedApp?.AutoInstallDependency3 ?? "No",
                            dependency4:             _selectedApp?.Dependency4   ?? "",
                            autoInstallDependency4:  _selectedApp?.AutoInstallDependency4 ?? "No",
                            supersedence1:           _selectedApp?.Supersedence1 ?? "",
                            uninstallPreviousVersion1: _selectedApp?.UninstallPreviousVersion1 ?? "No",
                            supersedence2:           _selectedApp?.Supersedence2 ?? "",
                            uninstallPreviousVersion2: _selectedApp?.UninstallPreviousVersion2 ?? "No",
                            supersedence3:           _selectedApp?.Supersedence3 ?? "",
                            uninstallPreviousVersion3: _selectedApp?.UninstallPreviousVersion3 ?? "No",
                            supersedence4:           _selectedApp?.Supersedence4 ?? "",
                            uninstallPreviousVersion4: _selectedApp?.UninstallPreviousVersion4 ?? "No",
                            intuneOverrides:         appIntuneOverrides2);

                        // Downstream Publish objects have now captured the resolved detection
                        // values; restore _selectedApp so the auto-prefill is never saved to the
                        // per-app JSON via any later SaveApps() pass.
                        RestoreDetectionPrefillFields(_detPrefillSnapshot2);

                        Dispatcher.Invoke(() =>
                        {
                            mwPC.NavigateAndTriggerAutoPackage(destFile, pkgAppVendor, pkgAppName, pkgCloseApps,
                                doInstallPkg, doUninstallPkg, pkgTemplateFolder, pkgAppVersion, pkgUninstallPath);
                        });
                    } // if mwPC
                    } // if doPC
                });
            }
            catch (OperationCanceledException ocx)
            {
                _autoFlowChainPending = false; // cancelled — allow unlock
                try { if (!string.IsNullOrWhiteSpace(partialFile) && File.Exists(partialFile)) File.Delete(partialFile); }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }

                // The Cancel button is not the only thing that lands here. A transfer that is
                // aborted or torn down mid-stream arrives as TaskCanceledException too, and
                // swallowing that silently is what made a failed download indistinguishable
                // from one that never started: the panel simply vanished. Only this download's
                // own token means "the user cancelled"; anything else is a failure and is
                // reported like one.
                if (ct.IsCancellationRequested)
                {
                    // The one exit that says nothing on screen, by design: the person pressed
                    // the X, or a second download started and cancelled this one at the top of
                    // DownloadFileAsync. Those two are indistinguishable from the outside, so
                    // the generation is logged with it: gen != current means it was superseded
                    // rather than cancelled by hand.
                    LogSched($"{appName}: download CANCELLED after {received} byte(s) " +
                             $"(gen {myGeneration}, current {System.Threading.Volatile.Read(ref _downloadGeneration)}) " +
                             $"- nothing is shown for this path");
                    Dispatcher.Invoke(() => RemoveDownloadProgress(progressBorder, myGeneration));
                }
                else
                {
                    // Which phase it died in is the whole diagnosis. A stall with no connect
                    // recorded is DNS, TCP or TLS; a connect but no first byte is a server
                    // that accepted the request and then sent nothing; a first byte followed
                    // by silence is a connection that dropped mid-transfer.
                    string phase = tConnect < 0 ? "before the connection completed"
                                 : tFirstByte < 0 ? $"after connecting in {tConnect - tWipe} ms but before the first byte"
                                 : $"mid-transfer, {phaseWatch.ElapsedMilliseconds - tFirstByte} ms after the first byte";
                    LogSched($"{appName}: DOWNLOAD ABORTED {phase} - {ocx.GetType().Name}: {ocx.Message} " +
                             $"(received {received} byte(s); a silence longer than {StallTimeoutMs / 1000}s " +
                             $"or a dropped connection ends the transfer)");
                    if (scheduled)
                    {
                        RecordScheduleOutcome(vendor, appName, existingVersion, version, scheduleName, failed: true);
                        QueueStatusWorkbook();
                    }
                    Dispatcher.Invoke(() =>
                    {
                        RemoveDownloadProgress(progressBorder, myGeneration);
                        if (!scheduled) ShowDownloadStatusLine(failed: true);
                        // Reason only: the muted how-to-fix line is dropped for download
                        // failures at the user's request, so the box reads title + cause.
                        // No modal window either way: the footer Status line plus this box
                        // are the whole report, and nothing has to be dismissed.
                        SetPackageErrorNoticeForApp(vendor, appName, "Download failed",
                            $"{label}: the connection stopped before the file finished.", "");
                    });
                }
            }
            catch (Exception ex)
            {
                _autoFlowChainPending = false; // errored — allow unlock
                // A partial file left in the folder would be packaged as if it were the real
                // installer, so it goes with the failure.
                try { if (!string.IsNullOrWhiteSpace(partialFile) && File.Exists(partialFile)) File.Delete(partialFile); }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                // Logged for every run. This used to be gated to scheduled runs only, so a
                // manual download that failed wrote nothing at all - the one line that says
                // WHY was missing from exactly the log a support ticket arrives with.
                LogSched($"{appName}: DOWNLOAD FAILED ({(scheduled ? "scheduled run" : "manual download")}) " +
                         $"after {phaseWatch.ElapsedMilliseconds} ms " +
                         $"(wipe {tWipe} ms, connect {(tConnect < 0 ? -1 : tConnect - tWipe)} ms, " +
                         $"first byte {(tFirstByte < 0 ? -1 : tFirstByte - tConnect)} ms; -1 means the phase " +
                         $"was never reached) - {ex.GetType().Name}: {ex.Message}");
                if (scheduled)
                {
                    RecordScheduleOutcome(vendor, appName, existingVersion, version, scheduleName, failed: true);
                    QueueStatusWorkbook();
                }
                // The raw exception is for the log above. The person gets wording that says
                // what to do: "No such host is known. (host:443)" is a no-internet failure,
                // and telling someone to close a file over it helps nobody.
                var (failDetail, _) = DescribeDownloadFailure(ex);
                Dispatcher.Invoke(() =>
                {
                    RemoveDownloadProgress(progressBorder, myGeneration);
                    if (!scheduled) ShowDownloadStatusLine(failed: true);

                    // The failure always lands in the Download Information column, under the
                    // action checklist, against the app it belongs to, worded for what actually
                    // failed: no internet, a server that said no, or a locked file. Reason
                    // only - the hint line is dropped for download failures, and no modal
                    // window is shown: the footer Status line plus this box are the report.
                    SetPackageErrorNoticeForApp(vendor, appName, "Download failed",
                        $"{label}: {failDetail}", "");
                });
            }
            }); // end Task.Run

            // The caller assigns the Task this method returns to _activeDownloadTask, which
            // used to overwrite the Task.Run above with one that had already finished: the
            // field pointed at nothing running, so "cancel any previous download and wait for
            // it to stop" waited on a completed Task and returned instantly, letting two
            // transfers overlap. Awaiting here keeps both the field and the returned Task
            // alive for exactly as long as the transfer runs, so either one is safe to wait on.
            _activeDownloadTask = thisDownload;
            try { await thisDownload.ConfigureAwait(false); }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
        }

        // True from ShowDownloadProgress to the owning RemoveDownloadProgress: the footer
        // belongs to the live download for that whole span. The two verdict painters
        // (ApplyAutoFlowResultToUI, ShowDownloadStatusLine) check this and stand down,
        // because both are reachable mid-transfer through ReapplySavedAutoFlowResult -
        // every panel rebuild defers it, and clicking another app during a scheduled batch
        // is a panel rebuild - and both collapse PnlHeaderProgress when they paint, which
        // is exactly a progress bar vanishing while the download is still running.
        private volatile bool _downloadPanelActive;

        private Border ShowDownloadProgress(string label, string destFolder)
        {
            Dispatcher.Invoke(() =>
            {
                _downloadPanelActive = true;
                // Manual features are locked out for the whole download; released by the
                // owning RemoveDownloadProgress (or by the chain end, if one follows).
                AppBusy.SetAuto("Download", true);
                TxtProgressLabel.Text        = label;
                TxtProgressStatus.Text       = "Connecting...";
                // Indeterminate while connecting. DNS, TLS and the vendor's redirect chain
                // (VideoLAN picks a mirror, for example) can take a few seconds before the
                // first byte, and a motionless empty bar over "Connecting..." reads as a
                // hang. The first progress callback switches the bar to determinate.
                HeaderProgressBar.IsIndeterminate = true;
                HeaderProgressBar.Value      = 0;
                PnlHeaderProgress.Visibility = Visibility.Visible;
                if (FindName("BtnCancelDownload") is Button btn)
                    btn.Visibility = Visibility.Visible;
                if (FindName("BtnCancelDownloadTop") is Button btnTop)
                    btnTop.Visibility = Visibility.Visible;
                // Reset pause button to its default (running) look for the new download.
                if (FindName("BtnPauseDownload") is Button btnPause)
                { btnPause.Content = "❚❚"; btnPause.ToolTip = "Pause download"; }
                // Also show the thin top overlay bar during download. It starts indeterminate
                // with the header bar and goes determinate on the first progress callback.
                if (TopSilentProgressBar != null)
                {
                    TopSilentProgressBar.IsIndeterminate = true;
                    TopSilentProgressBar.Value           = 0;
                    TopSilentProgressBar.Visibility      = Visibility.Visible;
                }
                // Clear the Package-tab EVENT LOG so output from a previous run doesn't linger.
                try
                {
                    _mainWindow ??= Window.GetWindow(this) as IAutoPackageHost;
                    var app = _mainWindow?.AutoPackagePage ?? FindAncestorAutoPackagePage();
                    app?.ClearPackageEventLog();
                    app?.ClearDocumentTab();
                }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }

                // Record which actions are selected for this run so the status panel only
                // colours the chosen ones, and clear any previous run's status panel.
                try
                {
                    var wanted = new System.Collections.Generic.List<string>();
                    if (PnlPackageInfo?.Tag is CheckBox[] acts)
                    {
                        void Add(int i, string key) { if (acts.Length > i && acts[i].IsChecked == true) wanted.Add(key); }
                        Add(0, AutoFlowStatus.InstallSource);
                        Add(1, AutoFlowStatus.UninstallSource);
                        Add(2, AutoFlowStatus.CreatePackage);
                        Add(3, AutoFlowStatus.InstallPackage);
                        Add(4, AutoFlowStatus.UninstallPackage);
                        Add(5, AutoFlowStatus.CreateIntunewin);
                        Add(6, AutoFlowStatus.PublishSettings);
                        Add(7, AutoFlowStatus.PublishToIntune);
                        Add(8, AutoFlowStatus.SendMail);
                        // Belt and braces: the checkbox cannot be ticked without Publish to intune
                        // now that it is chain-gated, but a config written before that rule could
                        // still carry the pair, and a wanted action that never runs would sit
                        // unresolved in the status panel.
                        if (acts.Length > 7 && acts[7].IsChecked == true)
                            Add(9, AutoFlowStatus.AddSupersedence);
                    }
                    AutoFlowStatus.Reset();
                    AutoFlowStatus.ClearResultFor(CurrentAppKey());
                    AutoFlowStatus.SetWanted(wanted);
                    AutoFlowStatus.SetPackageName(_selectedApp?.SourceAppName ?? "");
                    // The verdict belongs to the run that produced it. Cleared here so the
                    // rebuilds that happen DURING the new download repaint nothing, and the
                    // footer stays empty until this run writes its own verdict.
                    _downloadVerdictKey = "";
                    ClearAutoFlowStatusPanel();
                    // A new run starts clean: drop any prior package-error notice for this app
                    // (the guard below will set a fresh one only if it trips again).
                    _packageErrorByKey.Remove(CurrentAppKey());
                    RenderPackageErrorNotice();
                }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
            });
            return new Border();
        }

        private void UpdateDownloadProgress(Border _, int generation, double pct, long received, long total)
        {
            // A superseded download must not repaint the panel the current one owns. Its
            // queued Dispatcher callbacks can still arrive after the newer download has
            // claimed the panel, which would show the wrong app's byte count.
            if (!IsCurrentDownload(generation)) return;
            // total <= 0 means the server sent no Content-Length. Show what has arrived and
            // run the bar indeterminate rather than leaving the panel on "Connecting...".
            bool known = total > 0;
            HeaderProgressBar.IsIndeterminate = !known;
            HeaderProgressBar.Value = known ? pct : 0;
            TxtProgressStatus.Text  = known
                ? $"{pct:0}%  {received / 1024.0 / 1024.0:0.0} / {total / 1024.0 / 1024.0:0.0} MB"
                : $"{received / 1024.0 / 1024.0:0.0} MB";
            if (TopSilentProgressBar != null)
            {
                TopSilentProgressBar.IsIndeterminate = !known;
                TopSilentProgressBar.Value           = known ? pct : 0;
            }
        }

        private void RemoveDownloadProgress(Border _, int generation)
        {
            // Only the download that currently owns the panel may tear it down, and only it
            // may release the column lock below. A task cancelled by the next download unwinds
            // seconds later and used to run all of this against the panel and the lock that
            // belonged to its replacement.
            if (!IsCurrentDownload(generation)) return;
            _downloadPanelActive = false;
            AppBusy.SetAuto("Download", false);
            PnlHeaderProgress.Visibility = Visibility.Collapsed;
            HeaderProgressBar.IsIndeterminate = false;
            HeaderProgressBar.Value      = 0;
            TxtProgressLabel.Text        = "";
            TxtProgressStatus.Text       = "";
            if (FindName("BtnCancelDownload") is Button btn)
                btn.Visibility = Visibility.Collapsed;
            if (FindName("BtnCancelDownloadTop") is Button btnTop)
                btnTop.Visibility = Visibility.Collapsed;
            // Hide the thin top overlay bar when the download finishes.
            if (TopSilentProgressBar != null)
            {
                TopSilentProgressBar.Visibility      = Visibility.Collapsed;
                TopSilentProgressBar.IsIndeterminate = false;
                TopSilentProgressBar.Value           = 0;
            }
            // Req 4: unlock the Download-Information and Package-Information columns
            // when the download finishes — BUT only if no downstream auto-flow chain
            // (Package → Execute → Intunewin → Publish) is still pending. When a chain
            // is pending the columns stay locked until AutoPackagePage signals that all
            // actions completed (or the flow is cancelled/errored, which force-unlocks).
            if (!_autoFlowChainPending)
            {
                UnlockDownloadAndPackageColumns();
                AutoFlowStatus.FlowRunning = false;   // no downstream chain — the whole flow ends with the download
            }
        }

        private void ShowDownloadCompleteDialog(string appName, string version, string filePath, string folder, bool showMessageBox = true, string appVendor = "", string sharedLogPath = "")
        {
            var winBg  = Res("NavBarBgBrush", new SolidColorBrush(Color.FromRgb(0xE8, 0xEA, 0xF5)));
            var bClr   = new SolidColorBrush(Color.FromRgb(0x53, 0x56, 0x63));
            var lblFg  = Res("TextPrimaryBrush", Brushes.Black);
            var boxBg  = Res("InputBgBrush", Brushes.White);
            var boxBdr = Res("BorderMainBrush", Brushes.LightGray);
            var sec    = Application.Current.TryFindResource("SecondaryButtonStyle") as Style;

            string timeStarted = _downloadStartTime.ToString("HH:mm:ss");
            string timeFinished = DateTime.Now.ToString("HH:mm:ss");
            var duration = DateTime.Now - _downloadStartTime;
            string durationStr = duration.TotalSeconds >= 60
                ? $"{(int)duration.TotalMinutes}m {duration.Seconds}s"
                : $"{duration.TotalSeconds:0.0}s";

            // Calculate folder size
            string sizeStr = "";
            try
            {
                var dirInfo = new DirectoryInfo(folder);
                if (dirInfo.Exists)
                {
                    long bytes = dirInfo.EnumerateFiles("*", SearchOption.AllDirectories).Sum(f => f.Length);
                    sizeStr = bytes >= 1024L * 1024 * 1024
                        ? $"{bytes / 1024.0 / 1024.0 / 1024.0:0.00} GB"
                        : $"{bytes / 1024.0 / 1024.0:0.00} MB";
                }
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }

            string timeRow = $"Started: {timeStarted}   Finished: {timeFinished}   Duration: {durationStr}";

            // Use shared log path when provided — same file used by RunPsadtCommandAndThenAutoPackage
            string logPath;
            if (!string.IsNullOrWhiteSpace(sharedLogPath))
            {
                logPath = sharedLogPath;
            }
            else
            {
                string safeVendor  = appVendor.Trim().Replace(" ", "");
                string safeApp     = appName.Replace(" ", "");
                var vMatch = System.Text.RegularExpressions.Regex.Match(version.Trim(), @"^[\d]+(?:\.[\d]+)*");
                string safeVersion = vMatch.Success ? vMatch.Value : version.Trim();
                foreach (char c in Path.GetInvalidFileNameChars())
                { safeVendor = safeVendor.Replace(c,'_'); safeApp = safeApp.Replace(c,'_'); safeVersion = safeVersion.Replace(c,'_'); }
                logPath = Path.Combine(Path.GetTempPath(),
                    $"AutoPackage_{safeVendor}_{safeApp}_{safeVersion}.log");
            }

            // Write download header to the unified log file
            try
            {
                File.WriteAllText(logPath,
                    $"=== AutoPackage Log ===\r\n" +
                    $"App:      {appVendor} {appName} {version}\r\n" +
                    $"File:     {filePath}\r\n" +
                    $"Folder:   {folder}\r\n" +
                    $"Size:     {sizeStr}\r\n" +
                    $"Started:  {timeStarted}\r\n" +
                    $"Finished: {timeFinished}\r\n" +
                    $"Duration: {durationStr}\r\n\r\n");
            }
            catch { logPath = "Log unavailable"; }

            var win = new Window
            {
                Title = "Source Download - Complete",
                Width = 480, SizeToContent = SizeToContent.Height,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = Window.GetWindow(this), ResizeMode = ResizeMode.NoResize,
                WindowStyle = WindowStyle.None, AllowsTransparency = true,
                Background = Brushes.Transparent,
                FontFamily = new System.Windows.Media.FontFamily("Segoe UI"),
                ShowInTaskbar = false,
            };

            var outer = new Border
            {
                Background = winBg, BorderBrush = bClr, BorderThickness = new Thickness(1.5),
                CornerRadius = new CornerRadius(10),
                Effect = new System.Windows.Media.Effects.DropShadowEffect
                { BlurRadius = 20, ShadowDepth = 4, Opacity = 0.3, Color = System.Windows.Media.Colors.Black }
            };
            win.Content = outer;

            var og = new Grid();
            og.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            og.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            outer.Child = og;

            // Title bar — matches Create Package Complete style
            var tb = new Border
            {
                Background = new SolidColorBrush(Color.FromRgb(0x53, 0x56, 0x63)),
                BorderThickness = new Thickness(0, 0, 0, 1), BorderBrush = boxBdr,
                CornerRadius = new CornerRadius(10, 10, 0, 0),
                Padding = new Thickness(16, 6, 12, 6),
            };
            tb.MouseLeftButtonDown += (_, _) => win.DragMove();
            Grid.SetRow(tb, 0);
            var tg = new Grid();
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            var ti  = new TextBlock { Text = "📥", FontSize = 14, Foreground = Brushes.White, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 0) };
            var tt  = new TextBlock { Text = "Source Download - Complete", FontSize = 13, FontWeight = FontWeights.SemiBold, Foreground = Brushes.White, VerticalAlignment = VerticalAlignment.Center };
            var tcl = new Button   { Content = "✕", FontSize = 11, Foreground = new SolidColorBrush(Color.FromArgb(0xCC, 0xFF, 0xFF, 0xFF)), Background = Brushes.Transparent, BorderThickness = new Thickness(0), Cursor = System.Windows.Input.Cursors.Hand, Padding = new Thickness(6, 2, 6, 2) };
            tcl.Click += (_, _) => win.Close();
            Grid.SetColumn(ti, 0); Grid.SetColumn(tt, 1); Grid.SetColumn(tcl, 2);
            tg.Children.Add(ti); tg.Children.Add(tt); tg.Children.Add(tcl);
            tb.Child = tg; og.Children.Add(tb);

            // Content grid — matching Create Package Complete layout
            var cg = new Grid { Margin = new Thickness(14, 10, 14, 14) };
            cg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(60) });
            cg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            Grid.SetRow(cg, 1); og.Children.Add(cg);
            int r = 0;

            void AddRow(string labelText, string valueText)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(4) }); r++;
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var lbl = new TextBlock { Text = labelText, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg, VerticalAlignment = VerticalAlignment.Center };
                var box = new Border { Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(6), Padding = new Thickness(8, 5, 8, 5) };
                box.Child = new TextBlock { Text = valueText, FontSize = 11, Foreground = lblFg, TextWrapping = TextWrapping.Wrap };
                Grid.SetRow(lbl, r); Grid.SetColumn(lbl, 0);
                Grid.SetRow(box, r); Grid.SetColumn(box, 1);
                cg.Children.Add(lbl); cg.Children.Add(box);
                r++;
            }

            cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(6) }); r++;
            AddRow("Time",   timeRow);
            AddRow("Path",   folder);
            AddRow("Log",    logPath);

            cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(10) }); r++;
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            // Buttons row
            var iconTb = SdDecisionIcon();
            Grid.SetRow(iconTb, r); Grid.SetColumn(iconTb, 0); cg.Children.Add(iconTb);

            // Equal-width buttons filling the full column width — matching Create Package Complete
            var btnGrid = new Grid();
            btnGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            btnGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(6) });
            btnGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            btnGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(6) });
            btnGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            btnGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var bPath = new Button { Content = "📂  Open Path", Style = sec, FontSize = 11, FontWeight = FontWeights.SemiBold, Height = 28 };
            SdApplyPrimaryLook(bPath);
            bPath.Click += (_, _) =>
            {
                try { Process.Start(new ProcessStartInfo("explorer.exe", $"\"{folder}\"") { UseShellExecute = true }); }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
            };

            var bLog = new Button { Content = "📄  Open Log", Style = sec, FontSize = 11, FontWeight = FontWeights.SemiBold, Height = 28 };
            bLog.Click += (_, _) =>
            {
                try { Process.Start(new ProcessStartInfo(logPath) { UseShellExecute = true }); }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
            };

            var bClose = new Button { Content = "✕  Close", Style = sec, FontSize = 11, FontWeight = FontWeights.SemiBold, Height = 28 };
            bClose.Click += (_, _) => win.Close();

            Grid.SetColumn(bPath,  0); Grid.SetColumn(bLog, 2); Grid.SetColumn(bClose, 4);
            btnGrid.Children.Add(bPath); btnGrid.Children.Add(bLog); btnGrid.Children.Add(bClose);

            Grid.SetRow(btnGrid, r); Grid.SetColumn(btnGrid, 1); cg.Children.Add(btnGrid);

            if (showMessageBox)
            {
                win.ShowDialog();
                // Manual use — ensure flag is reset
                GlobalShowMessageBox = true;
            }
            else
            {
                // Auto-close: show briefly then close automatically
                win.Loaded += (_, _) =>
                {
                    win.Dispatcher.BeginInvoke(new Action(() => win.Close()),
                        System.Windows.Threading.DispatcherPriority.Background);
                };
                win.ShowDialog();
                // Flag stays false for downstream dialogs in this flow chain
            }
        }

        // Turns a download exception into wording the person can act on. The raw messages
        // are socket-level ("No such host is known. (download.videolan.org:443)") and read
        // like nonsense next to a download button; what matters is whether the problem is
        // the internet connection, the server, or a locked file. The raw exception still
        // goes to the scheduler log unchanged, so nothing is lost for diagnostics.
        private static (string Detail, string Hint) DescribeDownloadFailure(Exception ex)
        {
            if (ex is HttpRequestException hre)
            {
                // EnsureSuccessStatusCode: the server answered, but said no.
                if (hre.StatusCode is System.Net.HttpStatusCode sc)
                    return ($"The server refused the download (HTTP {(int)sc}).",
                            "The download link may be outdated. Refresh the app's download "
                            + "information and retry; if it keeps failing, check the Download "
                            + "Source settings.");
                // Walk to the socket error underneath, if any. HostNotFound and friends are
                // DNS: nothing was reached at all, which on a client machine almost always
                // means the internet connection itself is down.
                for (Exception? e = hre.InnerException; e != null; e = e.InnerException)
                {
                    if (e is System.Net.Sockets.SocketException se)
                    {
                        bool dns = se.SocketErrorCode is System.Net.Sockets.SocketError.HostNotFound
                                                       or System.Net.Sockets.SocketError.TryAgain
                                                       or System.Net.Sockets.SocketError.NoData;
                        return (dns
                                ? "The download server's address could not be found. This usually "
                                  + "means there is no internet connection."
                                : "Could not connect to the download server. The internet "
                                  + "connection may be down.",
                                "Check the internet connection, then retry with the download "
                                + "button. The next scheduled run also retries on its own.");
                    }
                }
                return ("The connection to the download server failed.",
                        "Check the internet connection, then retry with the download button. "
                        + "The next scheduled run also retries on its own.");
            }
            // Locked destination file: the one case the old fixed wording was written for.
            if (ex is IOException || ex is UnauthorizedAccessException)
                return (ex.Message,
                        "Close whatever is using the file. The next scheduled run retries on "
                        + "its own; the download button retries it now.");
            return (ex.Message,
                    "The next scheduled run retries on its own; the download button retries it now.");
        }

        private void RenderInfoPanel(AppDownloadInfo info)
        {
            _lastInfo = info; // cache so DownloadPreference changes can re-highlight buttons
            // Live links just arrived — narrow the Download Preference radios to them.
            UpdateDownloadPreferenceRadioVisibility();
            PnlInfoPlaceholder.Visibility = Visibility.Collapsed;
            PnlAppInfo.Visibility         = Visibility.Visible;
            PnlAppInfo.Children.Clear();

            // Cache the live version so RenderCards can show "⬆ New" badge
            if (!string.IsNullOrWhiteSpace(info.Version) && _selectedApp != null)
            {
                _liveVersionCache[_selectedApp.SourceAppName] = info.Version;
                RenderVendors(); // refresh vendor badges
                RenderCards();   // refresh app card badges
            }

            var accent  = Res("AccentBrush", new SolidColorBrush(Color.FromRgb(0x6C, 0x63, 0xFF)));
            var lblFg   = Res("TextPrimaryBrush", Brushes.Black);
            var mutFg   = Res("TextMutedBrush", Brushes.DarkGray);
            var bdrBr   = Res("BorderMainBrush", Brushes.LightGray);
            var secFg   = Res("TextSecondaryBrush", Brushes.Gray);
            var sec     = TryFindResource("SecondaryButtonStyle") as Style;

            // Header — consistent font sizes throughout (11pt base, Segoe UI)
            var hdr = new StackPanel { Margin = new Thickness(0, 0, 0, 6) };
            hdr.Children.Add(new TextBlock { Text = info.SourceAppName, FontSize = 11, FontWeight = FontWeights.Bold, Foreground = lblFg });

            // Always show the version row — either the version number or a "not available" message
            {
                var vRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 6, 0, 0) };

                if (string.IsNullOrWhiteSpace(info.Version))
                {
                    // Version could not be fetched — show muted placeholder
                    vRow.Children.Add(new TextBlock
                    {
                        Text              = "Not available - check download page",
                        FontSize          = 11,
                        Foreground        = mutFg,
                        FontStyle         = FontStyles.Italic,
                        VerticalAlignment = VerticalAlignment.Center,
                    });
                }
                else
                {
                var vBadge = new Border { Background = new SolidColorBrush(Color.FromArgb(0x20, 0x6C, 0x63, 0xFF)), CornerRadius = new CornerRadius(4), Padding = new Thickness(8, 2, 8, 2) };
                vBadge.Child = new TextBlock { Text = info.Version, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = accent };
                vRow.Children.Add(vBadge);
                // Live badge removed — version number alone is sufficient

                // Show "New" only when the live/download version is genuinely NEWER than the recorded
                // Source App Version - the same IsRemoteNewer the scheduler and Updates tab use. If the
                // two versions are the same, no badge (a freshly added, already-current app shows none).
                string lastVer = _selectedApp?.SourceAppVersion ?? "";
                if (_liveVersionCache.TryGetValue(_selectedApp?.SourceAppName ?? "", out string? cachedLive) &&
                    IsRemoteNewer(cachedLive, lastVer))
                {
                    var newBadge = new Border
                    {
                        Background      = new SolidColorBrush(Color.FromArgb(0x22, 0xFF, 0x80, 0x00)),
                        BorderBrush     = new SolidColorBrush(Color.FromArgb(0x88, 0xFF, 0x80, 0x00)),
                        BorderThickness = new Thickness(1),
                        CornerRadius    = new CornerRadius(4),
                        Padding         = new Thickness(8, 3, 8, 3),
                        Margin          = new Thickness(8, 0, 0, 0),
                        ToolTip         = string.IsNullOrWhiteSpace(lastVer)
                            ? $"Available: {cachedLive} (not yet downloaded)"
                            : $"Last downloaded: {lastVer} → New: {cachedLive}",
                    };
                    newBadge.Child = new TextBlock
                    {
                        Text              = "New",
                        FontSize          = 11,
                        FontWeight        = FontWeights.Bold,
                        Foreground        = new SolidColorBrush(Color.FromRgb(0xFF, 0x80, 0x00)),
                        VerticalAlignment = VerticalAlignment.Center,
                    };
                    vRow.Children.Add(newBadge);
                }
                else if (!string.IsNullOrWhiteSpace(lastVer) && lastVer == info.Version)
                {
                    // Downloaded badge and file size moved to a separate row below — added after vRow is finalised

                    // Collect size info to use below
                    string downloadedSizeStr = "";
                    try
                    {
                        string basePath   = string.IsNullOrWhiteSpace(_sourceDownloadPath)
                            ? DefaultDownloadPath : _sourceDownloadPath;
                        string safeVendorChk = (_selectedApp?.SourceAppVendor ?? "").Trim();
                        foreach (char c in Path.GetInvalidFileNameChars()) safeVendorChk = safeVendorChk.Replace(c, '_');
                        if (string.IsNullOrWhiteSpace(safeVendorChk)) safeVendorChk = "Unknown";
                        string folderName = $"{_selectedApp?.AppName ?? ""} {lastVer}".Trim();
                        foreach (char c in Path.GetInvalidFileNameChars()) folderName = folderName.Replace(c, '_');
                        string folder     = Path.Combine(basePath, safeVendorChk, folderName);
                        if (Directory.Exists(folder))
                        {
                            string pref = _selectedApp?.DownloadPreference ?? "";
                            string prefExt = pref.StartsWith("EXE", StringComparison.OrdinalIgnoreCase) ? ".exe"
                                           : pref.StartsWith("MSI", StringComparison.OrdinalIgnoreCase) ? ".msi"
                                           : "";

                            var allFiles = Directory.GetFiles(folder)
                                .Select(f => new FileInfo(f))
                                .Where(fi => fi.Length > 0)
                                .ToList();

                            FileInfo? fi = (!string.IsNullOrEmpty(prefExt)
                                ? allFiles.Where(f => f.Extension.Equals(prefExt, StringComparison.OrdinalIgnoreCase))
                                          .OrderByDescending(f => f.LastWriteTime)
                                          .FirstOrDefault()
                                : null)
                                ?? allFiles.OrderByDescending(f => f.LastWriteTime).FirstOrDefault();

                            if (fi != null)
                            {
                                long bytes = fi.Length;
                                downloadedSizeStr = bytes >= 1_073_741_824
                                    ? $"{bytes / 1_073_741_824.0:F1} GB"
                                    : bytes >= 1_048_576
                                        ? $"{bytes / 1_048_576.0:F1} MB"
                                        : $"{bytes / 1024.0:F0} KB";
                            }
                        }
                    }
                    catch { /* size display is best-effort */ }

                    // Build the downloaded sub-row (shown below vRow) — size only, no "Downloaded" label.
                    var downloadedRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 0) };
                    if (!string.IsNullOrWhiteSpace(downloadedSizeStr))
                    {
                        downloadedRow.Children.Add(new TextBlock
                        {
                            Text              = downloadedSizeStr,
                            FontSize          = 11,
                            Foreground        = mutFg,
                            VerticalAlignment = VerticalAlignment.Center,
                        });
                    }
                    hdr.Children.Add(vRow);
                    hdr.Children.Add(downloadedRow);
                    goto vRowDone;
                }
                } // end else (version available)

                hdr.Children.Add(vRow);
                vRowDone:;
            }

            // ── App header (left) + checkboxes (right) side by side ───────

            // Install/Uninstall package cannot run without a PSADT template folder, so they must
            // not be STORED as enabled without one. Add App defaults both radios to Administrator
            // while its own row is greyed out and nothing resets them unless the folder textbox is
            // edited, so a newly added app arrives here saying "Administrator" with no folder set.
            // That rendered as a ticked but disabled checklist item, which reads as "this step will
            // run" when it cannot. Normalising here, before the checklist and the Package settings
            // radios are built from these values, keeps all three consistent and repairs apps that
            // were already saved in that state.
            if (_selectedApp != null && string.IsNullOrWhiteSpace(_selectedApp.PSADTTemplateFolder))
            {
                bool pkgActionReset = false;
                if (!"No".Equals(_selectedApp.InstallPackage, StringComparison.OrdinalIgnoreCase))
                {
                    _selectedApp.InstallPackage = "No";
                    pkgActionReset = true;
                }
                if (!"No".Equals(_selectedApp.UninstallPackage, StringComparison.OrdinalIgnoreCase))
                {
                    _selectedApp.UninstallPackage = "No";
                    pkgActionReset = true;
                }
                if (pkgActionReset) SaveApps();
            }

            bool effectivePC = (_selectedApp?.CreatePackage ?? "").Equals("Yes", StringComparison.OrdinalIgnoreCase);

            // ── Install Source Silently ────────────────────────────────────
            string installTooltipEXE = !string.IsNullOrWhiteSpace(_selectedApp?.SilentInstallParameterEXE) ? _selectedApp!.SilentInstallParameterEXE.Trim() : "/S (default)";
            string installTooltipMSI = !string.IsNullOrWhiteSpace(_selectedApp?.SilentInstallParameterMSI) ? _selectedApp!.SilentInstallParameterMSI.Trim() : "/qn /norestart (default)";
            bool effectiveInstall = (_selectedApp?.InstallSourceSilently ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase);
            var chkInstall = new CheckBox
            {
                Content    = "Install source silently",
                IsChecked  = effectiveInstall,
                IsEnabled  = true,
                FontSize   = 11,
                Foreground = lblFg,
                Margin     = new Thickness(0, 0, 0, 6),
                ToolTip    = $"After download, silently installs in Source Validation then triggers Execute.\nEXE: {installTooltipEXE}\nMSI: {installTooltipMSI}",
            };
            chkInstall.SetResourceReference(CheckBox.ForegroundProperty, "TextPrimaryBrush");
            chkInstall.Checked   += (_, _) => { if (_selectedApp != null) { _selectedApp.InstallSourceSilently = "Yes"; SaveApps(); } SyncPkgInfoRadio("Install Source Silently", "Yes"); };
            chkInstall.Unchecked += (_, _) => { if (_selectedApp != null) { _selectedApp.InstallSourceSilently = "No";  SaveApps(); } SyncPkgInfoRadio("Install Source Silently", "No"); };
            _chkInstallSilent = chkInstall;   // keep a reference so silent-phase progress can highlight this label

            // ── Uninstall Source Silently ──────────────────────────────────
            string uninstallTooltipEXE = !string.IsNullOrWhiteSpace(_selectedApp?.SilentUninstallParameterEXE) ? _selectedApp!.SilentUninstallParameterEXE.Trim() : "(not set - add SilentUninstallParameterEXE to the app's JSON file)";
            string uninstallTooltipMSI = !string.IsNullOrWhiteSpace(_selectedApp?.SilentUninstallParameterMSI) ? _selectedApp!.SilentUninstallParameterMSI.Trim() : "(not set - add SilentUninstallParameterMSI to the app's JSON file)";
            bool effectiveUninstall = (_selectedApp?.UninstallSourceSilently ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase);
            var chkUninstall = new CheckBox
            {
                Content    = "Uninstall source silently",
                IsChecked  = effectiveUninstall,
                IsEnabled  = true,
                FontSize   = 11,
                Foreground = lblFg,
                Margin     = new Thickness(0, 0, 0, 6),
                ToolTip    = $"Runs silently after Create Package completes.\nEXE: {uninstallTooltipEXE}\nMSI: {uninstallTooltipMSI}",
            };
            chkUninstall.SetResourceReference(CheckBox.ForegroundProperty, "TextPrimaryBrush");
            chkUninstall.Checked   += (_, _) => { if (_selectedApp != null) { _selectedApp.UninstallSourceSilently = "Yes"; SaveApps(); } SyncPkgInfoRadio("Uninstall Source Silently", "Yes"); };
            chkUninstall.Unchecked += (_, _) =>
            {
                if (_selectedApp != null) { _selectedApp.UninstallSourceSilently = "No";  SaveApps(); }
                SyncPkgInfoRadio("Uninstall Source Silently", "No");
                // Contrapositive of the Install-package rule: with Install source silently + Create
                // package on, Install package requires Uninstall source silently - so unchecking this
                // unchecks Install package (array 0=install-source, 2=create-package, 3=install-package).
                if (PnlPackageInfo?.Tag is CheckBox[] chks && chks.Length > 3 &&
                    chks[0].IsChecked == true && chks[2].IsChecked == true && chks[3].IsChecked == true)
                    chks[3].IsChecked = false;
            };
            _chkUninstallSilent = chkUninstall;   // keep a reference so silent-phase progress can highlight this label

            // ── Create Package ─────────────────────────────────────────────
            var chkPC = new CheckBox
            {
                Content    = "Create package",
                IsChecked  = effectivePC,
                IsEnabled  = true,
                FontSize   = 11,
                Foreground = lblFg,
                Margin     = new Thickness(0, 0, 0, 6),
                ToolTip    = "Triggers Create Package after Install source silently completes.",
            };
            chkPC.SetResourceReference(CheckBox.ForegroundProperty, "TextPrimaryBrush");

            // ── Install Package ────────────────────────────────────────────
            bool effectiveInstallPkg = !(_selectedApp?.InstallPackage ?? "No").Equals("No", StringComparison.OrdinalIgnoreCase)
                                    && !string.IsNullOrWhiteSpace(_selectedApp?.InstallPackage);
            var chkInstallPkg = new CheckBox
            {
                Content    = "Install package",
                IsChecked  = effectiveInstallPkg,
                IsEnabled  = true,   // always editable
                FontSize   = 11,
                Foreground = lblFg,
                Margin     = new Thickness(0, 0, 0, 6),
                ToolTip    = "Install the created package after Create Package completes. Requires PSADT Template Folder to be set.",
            };
            chkInstallPkg.SetResourceReference(CheckBox.ForegroundProperty, "TextPrimaryBrush");
            bool _updatingInstallPkg = false;
            chkInstallPkg.Checked   += (_, _) =>
            {
                if (_updatingInstallPkg) return;
                _updatingInstallPkg = true;
                if (_selectedApp != null) { _selectedApp.InstallPackage = "Administrator"; SaveApps(); }
                SyncPkgInfoRadio("Install Package", "Administrator");
                SaveJsonAppForSelectedApp();
                // If the source is installed (Install source silently on) and a package is being built
                // (Create package on), installing the package requires the source to be removed first -
                // so auto-check Uninstall source silently when it is off.
                if (chkInstall.IsChecked == true && chkPC.IsChecked == true && chkUninstall.IsChecked != true)
                    chkUninstall.IsChecked = true;
                _updatingInstallPkg = false;
            };
            chkInstallPkg.Unchecked += (_, _) =>
            {
                if (_updatingInstallPkg) return;
                _updatingInstallPkg = true;
                if (_selectedApp != null) { _selectedApp.InstallPackage = "No"; SaveApps(); }
                SyncPkgInfoRadio("Install Package", "No");
                SaveJsonAppForSelectedApp();
                // With a PSADT template folder set, Publish settings requires both Install and
                // Uninstall package - unchecking this one turns Publish settings off (index 6).
                if (!string.IsNullOrWhiteSpace(_selectedApp?.PSADTTemplateFolder) &&
                    PnlPackageInfo?.Tag is CheckBox[] pubChks && pubChks.Length > 6 && pubChks[6].IsChecked == true)
                    pubChks[6].IsChecked = false;
                _updatingInstallPkg = false;
            };

            // ── Uninstall Package ──────────────────────────────────────────
            bool effectiveUninstallPkg = !(_selectedApp?.UninstallPackage ?? "No").Equals("No", StringComparison.OrdinalIgnoreCase)
                                      && !string.IsNullOrWhiteSpace(_selectedApp?.UninstallPackage);
            var chkUninstallPkg = new CheckBox
            {
                Content    = "Uninstall package",
                IsChecked  = effectiveUninstallPkg,
                IsEnabled  = true,   // always editable
                FontSize   = 11,
                Foreground = lblFg,
                ToolTip    = "Uninstall the package after Install package completes. Requires PSADT Template Folder to be set.",
            };
            chkUninstallPkg.SetResourceReference(CheckBox.ForegroundProperty, "TextPrimaryBrush");
            bool _updatingUninstallPkg = false;
            chkUninstallPkg.Checked   += (_, _) =>
            {
                if (_updatingUninstallPkg) return;
                _updatingUninstallPkg = true;
                if (_selectedApp != null) { _selectedApp.UninstallPackage = "Administrator"; SaveApps(); }
                SyncPkgInfoRadio("Uninstall Package", "Administrator");
                SaveJsonAppForSelectedApp();
                _updatingUninstallPkg = false;
            };
            chkUninstallPkg.Unchecked += (_, _) =>
            {
                if (_updatingUninstallPkg) return;
                _updatingUninstallPkg = true;
                if (_selectedApp != null) { _selectedApp.UninstallPackage = "No"; SaveApps(); }
                SyncPkgInfoRadio("Uninstall Package", "No");
                SaveJsonAppForSelectedApp();
                // With a PSADT template folder set, Publish settings requires both Install and
                // Uninstall package - unchecking this one turns Publish settings off (index 6).
                if (!string.IsNullOrWhiteSpace(_selectedApp?.PSADTTemplateFolder) &&
                    PnlPackageInfo?.Tag is CheckBox[] pubChks && pubChks.Length > 6 && pubChks[6].IsChecked == true)
                    pubChks[6].IsChecked = false;
                _updatingUninstallPkg = false;
            };

            // ── Create Intunewin ───────────────────────────────────────────

            // A greyed-out step must also read as off. Clearing the box runs its Unchecked handler,
            // which is what writes "No" back to the app, the JSON and the Package settings radio -
            // so enable state, checkbox and stored value can never disagree.
            void SetPkgActionEnabled(CheckBox box, bool enabled)
            {
                box.IsEnabled = enabled;
                if (!enabled && box.IsChecked == true) box.IsChecked = false;
            }

            bool effectiveCreateIntunewin = (_selectedApp?.CreateIntunewin ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase);
            bool effectivePublishSettings = (_selectedApp?.PublishSettings  ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase);
            bool effectivePublishToIntune = (_selectedApp?.PublishToIntune  ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase);

            var chkCreateIntunewin = new CheckBox
            {
                Content    = "Create intunewin",
                IsChecked  = effectiveCreateIntunewin,
                IsEnabled  = true,   // always editable
                FontSize   = 11, Foreground = lblFg, Margin = new Thickness(0, 0, 0, 6),
                ToolTip    = "Create an .intunewin package after Create Package completes.",
            };
            chkCreateIntunewin.SetResourceReference(CheckBox.ForegroundProperty, "TextPrimaryBrush");

            // ── Publish to Intune ──────────────────────────────────────────
            var chkPublishToIntune = new CheckBox
            {
                Content    = "Publish settings",
                IsChecked  = effectivePublishSettings,
                IsEnabled  = true, // always editable
                FontSize   = 11, Foreground = lblFg, Margin = new Thickness(0, 0, 0, 6),
                ToolTip    = "Publish the package to Microsoft Intune.",
            };
            chkPublishToIntune.SetResourceReference(CheckBox.ForegroundProperty, "TextPrimaryBrush");

            // ── Publish to intune ──────────────────────────────────────────
            var chkPublishToIntune2 = new CheckBox
            {
                Content    = "Publish to intune",
                IsChecked  = effectivePublishToIntune,
                IsEnabled  = true,
                FontSize   = 11, Foreground = lblFg, Margin = new Thickness(0, 0, 0, 6),
                ToolTip    = "Publish the package to Microsoft Intune.",
            };
            chkPublishToIntune2.SetResourceReference(CheckBox.ForegroundProperty, "TextPrimaryBrush");

            // ── Add supersedence automatically ─────────────────────────────
            // Modifies what the publish step sends rather than adding work of its own, but it is
            // meaningless unless the publish actually runs, so it sits in SyncPublishChainEnabled
            // on the same gate as Send mail: enabled only once Publish to intune is checked.
            // Note the consequence: unchecking Publish to intune unchecks this too and writes
            // "No", exactly as it does for Send mail, so the choice is not remembered across a
            // publish being switched off and back on.
            var chkAutoSupersede = new CheckBox
            {
                Content    = "Add supersedence automatically",
                IsChecked  = !(_selectedApp?.AddSupersedenceAutomatically ?? "Yes").Equals("No", StringComparison.OrdinalIgnoreCase),
                IsEnabled  = true,
                FontSize   = 11, Foreground = lblFg, Margin = new Thickness(0, 0, 0, 6),
                ToolTip    = "Supersede the previous version of this app in Intune automatically.\nUncheck to publish only the supersedences listed in Intune settings.",
            };
            chkAutoSupersede.SetResourceReference(CheckBox.ForegroundProperty, "TextPrimaryBrush");
            chkAutoSupersede.Checked   += (_, _) =>
            {
                if (_selectedApp != null) { _selectedApp.AddSupersedenceAutomatically = "Yes"; SaveApps(); }
                SyncPkgInfoRadio("Add Supersedence Automatically", "Yes");
                SaveJsonAppForSelectedApp();
            };
            chkAutoSupersede.Unchecked += (_, _) =>
            {
                if (_selectedApp != null) { _selectedApp.AddSupersedenceAutomatically = "No"; SaveApps(); }
                SyncPkgInfoRadio("Add Supersedence Automatically", "No");
                SaveJsonAppForSelectedApp();
            };

            // Declare chkSendMail here so it's available in all Checked/Unchecked handlers below
            var chkSendMail = new CheckBox
            {
                Content   = "Send mail to app owner",
                IsChecked = (_selectedApp?.SendMailToAppOwner ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase),
                IsEnabled = true, // always editable
                FontSize  = 11, Margin = new Thickness(0, 0, 0, 6),
                ToolTip   = "Send a notification email to the app owner after processing completes.",
            };
            chkSendMail.SetResourceReference(CheckBox.ForegroundProperty, "TextPrimaryBrush");
            chkSendMail.Checked   += (_, _) => { if (_selectedApp != null) { _selectedApp.SendMailToAppOwner = "Yes"; SaveApps(); } SyncPkgInfoRadio("Send Mail to App Owner", "Yes"); };
            chkSendMail.Unchecked += (_, _) => { if (_selectedApp != null) { _selectedApp.SendMailToAppOwner = "No";  SaveApps(); } SyncPkgInfoRadio("Send Mail to App Owner", "No"); };

            // Publish-chain enable cascade for the Download Information column.
            // A downstream checkbox is enabled only when the full upstream chain is checked:
            //   Publish settings  needs Create package + Create intunewin
            //   Publish to intune needs the above + Publish settings
            //   Add supersedence  needs the above + Publish to intune
            //   Send mail         needs the above + Publish to intune
            // A box that becomes disabled is also unchecked, so the column can never show a
            // checked-but-greyed box (e.g. from a config saved before this rule existed).
            void SyncPublishChainEnabled()
            {
                bool pc = chkPC.IsChecked               == true;
                bool iw = chkCreateIntunewin.IsChecked  == true;
                bool ps = chkPublishToIntune.IsChecked  == true;
                bool pi = chkPublishToIntune2.IsChecked == true;
                bool enPS = pc && iw;
                bool enPI = pc && iw && ps;
                bool enSM = pc && iw && ps && pi;
                chkPublishToIntune.IsEnabled  = enPS;
                chkPublishToIntune2.IsEnabled = enPI;
                chkAutoSupersede.IsEnabled    = enSM;
                chkSendMail.IsEnabled         = enSM;
                if (!enPS && chkPublishToIntune.IsChecked  == true) chkPublishToIntune.IsChecked  = false;
                if (!enPI && chkPublishToIntune2.IsChecked == true) chkPublishToIntune2.IsChecked = false;
                if (!enSM && chkAutoSupersede.IsChecked    == true) chkAutoSupersede.IsChecked    = false;
                if (!enSM && chkSendMail.IsChecked         == true) chkSendMail.IsChecked         = false;
            }

            // Wire chkCreateIntunewin — must be after chkPublishToIntune, chkPublishToIntune2, chkSendMail declared
            chkCreateIntunewin.Checked += (_, _) =>
            {
                if (_selectedApp != null) { _selectedApp.CreateIntunewin = "Yes"; SaveApps(); }
                SyncPkgInfoRadio("Create Intunewin", "Yes");
                SyncPublishChainEnabled();
            };
            chkCreateIntunewin.Unchecked += (_, _) =>
            {
                if (_selectedApp != null) { _selectedApp.CreateIntunewin = "No"; SaveApps(); }
                chkPublishToIntune.IsChecked  = false;
                chkPublishToIntune2.IsChecked = false;
                chkSendMail.IsChecked         = false;
                SetPkgInfoRadioEnabled("Send Mail to App Owner", false);
                if (_selectedApp != null) { _selectedApp.PublishSettings = "No"; _selectedApp.PublishToIntune = "No"; _selectedApp.SendMailToAppOwner = "No"; SaveApps(); }
                SyncPkgInfoRadio("Create Intunewin",  "No");
                SyncPkgInfoRadio("Publish settings", "No");
                SyncPkgInfoRadio("Publish to intune", "No");
                SyncPkgInfoRadio("Send Mail to App Owner", "No");
                SyncPublishChainEnabled();
            };

            // Wire chkPublishToIntune — must be after chkPublishToIntune2 declared
            chkPublishToIntune.Checked += (_, _) =>
            {
                if (_selectedApp != null) { _selectedApp.PublishSettings = "Yes"; SaveApps(); }
                SyncPkgInfoRadio("Publish settings", "Yes");
                SyncPublishChainEnabled();
                // Publish settings + a PSADT template folder means the package must be installed and
                // uninstalled as part of the publish flow — auto-check both if not already checked.
                if (!string.IsNullOrWhiteSpace(_selectedApp?.PSADTTemplateFolder))
                {
                    if (chkInstallPkg.IsChecked   != true) chkInstallPkg.IsChecked   = true;
                    if (chkUninstallPkg.IsChecked != true) chkUninstallPkg.IsChecked = true;
                }
            };
            chkPublishToIntune.Unchecked += (_, _) =>
            {
                if (_selectedApp != null) { _selectedApp.PublishSettings = "No"; SaveApps(); }
                chkPublishToIntune2.IsChecked = false;
                chkSendMail.IsChecked = false;
                SetPkgInfoRadioEnabled("Send Mail to App Owner", false);
                if (_selectedApp != null) { _selectedApp.SendMailToAppOwner = "No"; SaveApps(); }
                SyncPkgInfoRadio("Publish settings", "No");
                SyncPkgInfoRadio("Publish to intune", "No");
                SyncPkgInfoRadio("Send Mail to App Owner", "No");
                SyncPublishChainEnabled();
            };

            chkPublishToIntune2.Checked   += (_, _) =>
            {
                if (_selectedApp != null) { _selectedApp.PublishToIntune = "Yes"; SaveApps(); }
                SetPkgInfoRadioEnabled("Send Mail to App Owner", true);
                SyncPkgInfoRadio("Publish to intune", "Yes");
                SyncPublishChainEnabled();
            };
            chkPublishToIntune2.Unchecked += (_, _) =>
            {
                if (_selectedApp != null) { _selectedApp.PublishToIntune = "No"; SaveApps(); }
                chkSendMail.IsChecked = false;
                SetPkgInfoRadioEnabled("Send Mail to App Owner", false);
                if (_selectedApp != null) { _selectedApp.SendMailToAppOwner = "No"; SaveApps(); }
                SyncPkgInfoRadio("Publish to intune", "No");
                SyncPkgInfoRadio("Send Mail to App Owner", "No");
                SyncPublishChainEnabled();
            };

            chkPC.Checked   += (_, _) =>
            {
                if (_selectedApp != null) { _selectedApp.CreatePackage = "Yes"; SaveApps(); }
                SetPkgActionEnabled(chkInstallPkg,   !string.IsNullOrWhiteSpace(_selectedApp?.PSADTTemplateFolder));
                SetPkgActionEnabled(chkUninstallPkg, !string.IsNullOrWhiteSpace(_selectedApp?.PSADTTemplateFolder));
                // Create intunewin becomes available once Create package is checked
                chkCreateIntunewin.IsEnabled = true;
                SyncPkgInfoRadio("Create Package", "Yes");
                SyncPublishChainEnabled();
            };
            chkPC.Unchecked += (_, _) =>
            {
                if (_selectedApp != null) { _selectedApp.CreatePackage = "No"; SaveApps(); }
                // Uncheck and disable Install/Uninstall package to avoid confusion
                chkInstallPkg.IsChecked   = false;
                chkUninstallPkg.IsChecked  = false;
                SetPkgActionEnabled(chkInstallPkg,   !string.IsNullOrWhiteSpace(_selectedApp?.PSADTTemplateFolder));
                SetPkgActionEnabled(chkUninstallPkg, !string.IsNullOrWhiteSpace(_selectedApp?.PSADTTemplateFolder));
                // Create intunewin requires Create package: uncheck (its handler cascades to the publish chain) and disable
                chkCreateIntunewin.IsChecked = false;
                chkCreateIntunewin.IsEnabled = true;
                if (_selectedApp != null) { _selectedApp.InstallPackage = "No"; _selectedApp.UninstallPackage = "No"; SaveApps(); }
                SyncPkgInfoRadio("Create Package",    "No");
                SyncPkgInfoRadio("Install Package",   "No");
                SyncPkgInfoRadio("Uninstall Package", "No");
                SyncPublishChainEnabled();
            };

            var chkPanel = new StackPanel { VerticalAlignment = VerticalAlignment.Center };
            // Tag: [0]=InstallSilently, [1]=UninstallSilently, [2]=CreatePackage, [3]=InstallPackage, [4]=UninstallPackage, [5]=CreateIntunewin, [6]=PublishSettings, [7]=PublishToIntune, [8]=SendMailToAppOwner, [9]=AddSupersedenceAutomatically
            // AddSupersedenceAutomatically is APPENDED at [9] rather than inserted at its on-screen
            // position (between PublishToIntune and SendMail), so the [0]..[8] indices hard-coded
            // in _autoFlowMap and in the wanted-actions block stay put. Display order comes from
            // the re-parenting loop further down (search "Checkboxes below Open Download Page"),
            // not from this array, so the two can differ safely.
            chkPanel.Tag = new CheckBox[] { chkInstall, chkUninstall, chkPC, chkInstallPkg, chkUninstallPkg, chkCreateIntunewin, chkPublishToIntune, chkPublishToIntune2, chkSendMail, chkAutoSupersede };
            foreach (var _rc in (CheckBox[])chkPanel.Tag) _rc.SetResourceReference(FrameworkElement.StyleProperty, "ModernCheckBoxStyle");
            chkPanel.Children.Add(chkInstall);
            chkPanel.Children.Add(chkUninstall);
            chkPanel.Children.Add(chkPC);
            chkPanel.Children.Add(chkInstallPkg);
            chkPanel.Children.Add(chkUninstallPkg);
            chkPanel.Children.Add(chkCreateIntunewin);
            chkPanel.Children.Add(chkPublishToIntune);
            chkPanel.Children.Add(chkPublishToIntune2);
            chkPanel.Children.Add(chkAutoSupersede);
            chkPanel.Children.Add(chkSendMail);

            var headerGrid = new Grid { Margin = new Thickness(0, 0, 0, 6) };
            headerGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            Grid.SetColumn(hdr, 0);
            headerGrid.Children.Add(hdr);

            // ── Package Information sidebar — interactive Add-App-style panel ──────────────────
            if (PnlPackageInfo != null)
            {
                PnlPackageInfo.Children.Clear();
                var app = _selectedApp;

                // Keep Tag for backward compatibility (doPC / doInstallPkg reads)
                var pkgChks = new CheckBox[] { chkInstall, chkUninstall, chkPC, chkInstallPkg, chkUninstallPkg, chkCreateIntunewin, chkPublishToIntune, chkPublishToIntune2, chkSendMail, chkAutoSupersede };
                PnlPackageInfo.Tag = pkgChks;

                // Re-apply this app's saved auto-flow result (green/red on the action checkboxes
                // + status line), if a previous run for this app left one. Deferred so it runs
                // after the panel finishes building.
                Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded,
                    (Action)(() => ReapplySavedAutoFlowResult()));

                // Enforce on load too: Publish settings on + PSADT template folder set means Install/
                // Uninstall package are required — auto-check them if not already. Deferred so it runs
                // after the panel (and the folder textbox / gating) finish building.
                Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded, (Action)(() =>
                {
                    if (!ReferenceEquals(_selectedApp, app)) return; // app switched before defer ran
                    if (chkPublishToIntune.IsChecked == true && !string.IsNullOrWhiteSpace(app?.PSADTTemplateFolder))
                    {
                        if (chkInstallPkg.IsChecked   != true) chkInstallPkg.IsChecked   = true;
                        if (chkUninstallPkg.IsChecked != true) chkUninstallPkg.IsChecked = true;
                    }
                }));

                // ── Load the per-app JSON ─────────────────────────────────
                DownloadSourceEntry? jsonApp = null;
                string? jsonFilePath = null;
                try
                {
                    if (!string.IsNullOrWhiteSpace(app?.PackageTemplateFolder) &&
                        !string.IsNullOrWhiteSpace(app?.SourceAppVendor) &&
                        !string.IsNullOrWhiteSpace(app?.SourceAppName))
                    {
                        jsonFilePath = Path.Combine(
                            app.PackageTemplateFolder,
                            $"{app.SourceAppVendor}_{app.SourceAppName}.json");
                        if (File.Exists(jsonFilePath))
                            jsonApp = JsonSerializer.Deserialize<DownloadSourceEntry>(
                                File.ReadAllText(jsonFilePath),
                                new JsonSerializerOptions { PropertyNameCaseInsensitive = true });
                    }
                }
                catch { /* best-effort */ }
                // ── Snapshot which detection fields were originally empty in the JSON file ──
                // Declared here so SaveJsonApp() closure can reference them.
                bool origPcEmpty = true, origMsiValEmpty = true, origFilePathEmpty = true,
                     origFileNameEmpty = true, origFileValEmpty = true, origRegKeyEmpty = true,
                     origRegNameEmpty = true, origRegValEmpty = true;
                // Must be read from disk BEFORE jsonApp ??= app, because if the file doesn't
                // exist jsonApp falls back to app (_selectedApp) which already has auto-populated
                // values — causing the snapshot to incorrectly record them as non-empty.
                {
                    DownloadSourceEntry? diskEntry = null;
                    if (jsonFilePath != null && File.Exists(jsonFilePath))
                    {
                        try
                        {
                            diskEntry = JsonSerializer.Deserialize<DownloadSourceEntry>(
                                File.ReadAllText(jsonFilePath),
                                new JsonSerializerOptions { PropertyNameCaseInsensitive = true, AllowTrailingCommas = true });
                        }
                        catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                    }
                    // If no file exists yet, treat all detection fields as originally empty
                    origPcEmpty        = string.IsNullOrWhiteSpace(diskEntry?.DetectionMsiProductCode);
                    origMsiValEmpty    = string.IsNullOrWhiteSpace(diskEntry?.DetectionMsiValue);
                    origFilePathEmpty  = string.IsNullOrWhiteSpace(diskEntry?.DetectionFileFolderPath);
                    origFileNameEmpty  = string.IsNullOrWhiteSpace(diskEntry?.DetectionFileFileName);
                    origFileValEmpty   = string.IsNullOrWhiteSpace(diskEntry?.DetectionFileValue);
                    origRegKeyEmpty    = string.IsNullOrWhiteSpace(diskEntry?.DetectionRegKeyPath);
                    origRegNameEmpty   = string.IsNullOrWhiteSpace(diskEntry?.DetectionRegValueName);
                    origRegValEmpty    = string.IsNullOrWhiteSpace(diskEntry?.DetectionRegistryValue);
                }

                jsonApp ??= app;

                // ── Save helper — writes changes back to the JSON file ─────
                void SaveJsonApp()
                {
                    try
                    {
                        if (!string.IsNullOrWhiteSpace(jsonFilePath) && jsonApp != null)
                        {
                            // Persist the detection fields exactly as they currently are
                            // (whether the user typed them in the Package Information column
                            // or they were auto-resolved). Previously these were blanked unless
                            // the original file already had a value, which silently discarded
                            // user-typed values (e.g. File Value date/time for Date created /
                            // Date modified). The per-app template JSON now reflects what the
                            // user sees/entered, and Publish gives JSON values first preference.
                            File.WriteAllText(jsonFilePath,
                                JsonSerializer.Serialize(jsonApp,
                                    new JsonSerializerOptions { WriteIndented = true }));
                        }
                    }
                    catch { /* best-effort */ }
                }

                // ── Style resources ────────────────────────────────────────
                var pBg    = Res("InputBgBrush",      Brushes.White);
                var pBdr   = Res("BorderMainBrush",   Brushes.LightGray);
                var pLblFg = Res("TextPrimaryBrush",  Brushes.Black);
                var pSecFg = Res("TextSecondaryBrush",Brushes.Gray);
                var tbStyle = TryFindResource("ModernTextBoxStyle") as Style;
                const int LWIDTH = 175; // label column width
                const int RGAP   = 6;   // gap between rows

                // ── Inline label inside a row ("At", "Hours", "Minutes", "On day", ...) ────
                // These were plain TextBlocks with no Foreground set, so they fell back to the WPF
                // default (black) and disappeared against the dark background. Every other label on
                // the page takes its colour from the theme; these did not.
                TextBlock PkgInline(string text)
                {
                    var t = new TextBlock { Text = text, FontSize = 11, VerticalAlignment = VerticalAlignment.Center };
                    t.SetResourceReference(TextBlock.ForegroundProperty, "TextPrimaryBrush");
                    return t;
                }

                // ── Section header ─────────────────────────────────────────
                void PkgSection(string title)
                {
                    // Sections are separated by a bold header only (no divider line).
                    double topGap = PnlPackageInfo.Children.Count > 0 ? 10 : 0;
                    var tb2 = new TextBlock { Text = title, FontSize = 11, FontWeight = FontWeights.Bold, Margin = new Thickness(0, topGap, 0, 4) };
                    tb2.SetResourceReference(TextBlock.ForegroundProperty, "TextPrimaryBrush");
                    // Tag marks this as a section boundary so RebuildPackageInfoTabs can route the rows
                    // that follow it into the correct Package Information tab.
                    tb2.Tag = "PKGSECTION:" + title;
                    PnlPackageInfo.Children.Add(tb2);
                }

                // ── TextBox row ────────────────────────────────────────────
                TextBox PkgTxtRow(string label, string value, Action<string> save, bool required = false)
                {
                    var g = new Grid { Margin = new Thickness(0, 0, 0, RGAP) };
                    g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                    g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    g.RowDefinitions.Add(new RowDefinition { Height = new GridLength(26) });
                    var lbl = new TextBlock { FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    lbl.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    // When required, show the label with a trailing red asterisk (matches Add App dialog).
                    lbl.Inlines.Add(new System.Windows.Documents.Run(label));
                    if (required)
                        lbl.Inlines.Add(new System.Windows.Documents.Run(" *") { Foreground = new SolidColorBrush(Color.FromRgb(0xE5, 0x39, 0x35)), FontWeight = FontWeights.Bold });
                    var tx = new TextBox { Text = value, FontSize = 11, Padding = new Thickness(6, 0, 6, 0), BorderBrush = pBdr, BorderThickness = new Thickness(1), Style = tbStyle, VerticalAlignment = VerticalAlignment.Stretch };
                    tx.SetResourceReference(TextBox.ForegroundProperty, "TextPrimaryBrush");
                    tx.SetResourceReference(TextBox.BackgroundProperty, "InputBgBrush");
                    tx.TextChanged += (_, _) => { save(tx.Text); SaveJsonApp(); if (app != null) SaveApps(); };

                    // ── Natural click-to-caret + drag-to-select behaviour ──────────
                    // WPF default: clicking a TextBox selects all and ignores click position.
                    // Fix: capture the hit-test position on MouseDown, then after WPF's
                    // focus/select-all completes, use Dispatcher.BeginInvoke to move the
                    // caret to the exact character index the user clicked.
                    bool _gainedFocusByMouse = false;

                    tx.PreviewMouseLeftButtonDown += (s, e) =>
                    {
                        if (!tx.IsKeyboardFocused)
                        {
                            _gainedFocusByMouse = true;
                            tx.Focus();

                            // Hit-test the click position against the text content.
                            Point pt = e.GetPosition(tx);

                            // GetCharacterIndexFromPoint with snapToText=true snaps to the
                            // nearest character boundary — which on a right-of-text click
                            // lands one character short of the end. Fix: if the click X is
                            // past the right edge of the last character, snap to end instead.
                            int charIndex = tx.GetCharacterIndexFromPoint(pt, true);
                            if (charIndex >= 0 && charIndex < tx.Text.Length)
                            {
                                Rect charRect = tx.GetRectFromCharacterIndex(charIndex);
                                // If the click is to the right of this character's left edge
                                // and the text doesn't extend further, move to end.
                                if (pt.X > charRect.Right && charIndex == tx.Text.Length - 1)
                                    charIndex = tx.Text.Length;
                            }
                            else if (charIndex < 0)
                            {
                                charIndex = tx.Text.Length;
                            }

                            int finalIndex = charIndex;
                            tx.Dispatcher.BeginInvoke(new Action(() =>
                            {
                                tx.Select(0, 0);
                                tx.CaretIndex = finalIndex;
                            }), System.Windows.Threading.DispatcherPriority.Input);

                            e.Handled = true;
                        }
                        // If already focused: let WPF handle normally (drag-select works).
                    };

                    // Click anywhere outside this TextBox clears its selection.
                    tx.GotKeyboardFocus += (s, e) =>
                    {
                        void ClearOnOutsideClick(object? sender2, System.Windows.Input.MouseButtonEventArgs e2)
                        {
                            if (sender2 is UIElement root)
                            {
                                root.PreviewMouseLeftButtonDown -= ClearOnOutsideClick;
                                if (!tx.IsMouseOver)
                                    tx.Select(0, 0);
                            }
                        }
                        System.Windows.DependencyObject? ancestor = tx;
                        while (ancestor != null)
                        {
                            ancestor = System.Windows.Media.VisualTreeHelper.GetParent(ancestor);
                            if (ancestor is ScrollViewer sv2) { sv2.PreviewMouseLeftButtonDown += ClearOnOutsideClick; break; }
                            if (ancestor is Page pg)          { pg.PreviewMouseLeftButtonDown  += ClearOnOutsideClick; break; }
                            if (ancestor is Window wn)        { wn.PreviewMouseLeftButtonDown  += ClearOnOutsideClick; break; }
                        }
                    };
                    // ── End natural click-to-caret behaviour ───────────────────────

                    Grid.SetColumn(lbl, 0); Grid.SetColumn(tx, 1);
                    g.Children.Add(lbl); g.Children.Add(tx);
                    PnlPackageInfo.Children.Add(g);
                    return tx;
                }

                // ── Text row with File browse icon ─────────────────────────
                TextBox PkgTxtRowWithFileBrowse(string label, string value, Action<string> save)
                {
                    var tx = PkgTxtRow(label, value, save);
                    var g = (Grid)PnlPackageInfo.Children[PnlPackageInfo.Children.Count - 1];
                    // Remove tx from its parent Grid before reparenting to overlay
                    g.Children.Remove(tx);
                    var overlay = new Grid();
                    Grid.SetColumn(overlay, 1);
                    var btn = new Button
                    {
                        Content = "📄", FontSize = 11, Width = 24, Height = 22,
                        HorizontalAlignment = HorizontalAlignment.Right,
                        VerticalAlignment   = VerticalAlignment.Center,
                        Margin = new Thickness(0, 0, 2, 0),
                        BorderThickness = new Thickness(0),
                        Background = System.Windows.Media.Brushes.Transparent,
                        Cursor = System.Windows.Input.Cursors.Hand, ToolTip = "Browse for file"
                    };
                    btn.SetResourceReference(Button.ForegroundProperty, "TextSecondaryBrush");
                    btn.Click += (_, _) =>
                    {
                        var dlg = new Microsoft.Win32.OpenFileDialog { Title = "Select file" };
                        if (dlg.ShowDialog() == true) { tx.Text = dlg.FileName; save(dlg.FileName); SaveJsonApp(); }
                    };
                    tx.Padding = new System.Windows.Thickness(6, 0, 28, 0);
                    tx.HorizontalAlignment = HorizontalAlignment.Stretch;
                    overlay.Children.Add(tx);
                    overlay.Children.Add(btn);
                    g.Children.Add(overlay);
                    return tx;
                }

                // ── Text row with Folder browse icon ────────────────────────
                TextBox PkgTxtRowWithFolderBrowse(string label, string value, Action<string> save)
                {
                    var tx = PkgTxtRow(label, value, save);
                    var g = (Grid)PnlPackageInfo.Children[PnlPackageInfo.Children.Count - 1];
                    g.Children.Remove(tx);
                    var overlay = new Grid();
                    Grid.SetColumn(overlay, 1);
                    var btn = new Button
                    {
                        Content = "📁", FontSize = 11, Width = 24, Height = 22,
                        HorizontalAlignment = HorizontalAlignment.Right,
                        VerticalAlignment   = VerticalAlignment.Center,
                        Margin = new Thickness(0, 0, 2, 0),
                        BorderThickness = new Thickness(0),
                        Background = System.Windows.Media.Brushes.Transparent,
                        Cursor = System.Windows.Input.Cursors.Hand, ToolTip = "Browse for folder"
                    };
                    btn.SetResourceReference(Button.ForegroundProperty, "TextSecondaryBrush");
                    btn.Click += (_, _) =>
                    {
                        var dlg = new System.Windows.Forms.FolderBrowserDialog { Description = "Select folder", UseDescriptionForTitle = true };
                        if (dlg.ShowDialog() == System.Windows.Forms.DialogResult.OK)
                        { tx.Text = dlg.SelectedPath; save(dlg.SelectedPath); SaveJsonApp(); }
                    };
                    tx.Padding = new System.Windows.Thickness(6, 0, 28, 0);
                    tx.HorizontalAlignment = HorizontalAlignment.Stretch;
                    overlay.Children.Add(tx);
                    overlay.Children.Add(btn);
                    g.Children.Add(overlay);
                    return tx;
                }

                // ── Text row with Registry browse icon ───────────────────────
                TextBox PkgTxtRowWithRegBrowse(string label, string value, Action<string> save)
                {
                    var tx = PkgTxtRow(label, value, save);
                    var g = (Grid)PnlPackageInfo.Children[PnlPackageInfo.Children.Count - 1];
                    g.Children.Remove(tx);
                    var overlay = new Grid();
                    Grid.SetColumn(overlay, 1);
                    var btn = new Button
                    {
                        Content = "🔑", FontSize = 11, Width = 24, Height = 22,
                        HorizontalAlignment = HorizontalAlignment.Right,
                        VerticalAlignment   = VerticalAlignment.Center,
                        Margin = new Thickness(0, 0, 2, 0),
                        BorderThickness = new Thickness(0),
                        Background = System.Windows.Media.Brushes.Transparent,
                        Cursor = System.Windows.Input.Cursors.Hand, ToolTip = "Open Registry Editor"
                    };
                    btn.SetResourceReference(Button.ForegroundProperty, "TextSecondaryBrush");
                    btn.Click += (_, _) =>
                    {
                        try { System.Diagnostics.Process.Start("regedit.exe"); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                    };
                    tx.Padding = new System.Windows.Thickness(6, 0, 28, 0);
                    tx.HorizontalAlignment = HorizontalAlignment.Stretch;
                    overlay.Children.Add(tx);
                    overlay.Children.Add(btn);
                    g.Children.Add(overlay);
                    return tx;
                }

                // ── Yes/No radio row ───────────────────────────────────────
                // Returns the StackPanel holding the Yes/No radio buttons so callers can
                // enable or disable the row after creation (e.g. dependency chaining).
                StackPanel PkgRadioYesNo(string label, string currentVal, Action<string> save, bool enabled = true)
                {
                    var g = new Grid { Margin = new Thickness(0, 0, 0, RGAP) };
                    g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                    g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    g.RowDefinitions.Add(new RowDefinition { Height = new GridLength(26) });
                    var lbl = new TextBlock { Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    lbl.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    var sp = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center, IsEnabled = true };
                    string grp = Guid.NewGuid().ToString();
                    bool isYes = currentVal.Equals("Yes", StringComparison.OrdinalIgnoreCase);
                    var rbY = new RadioButton { Content = "Yes", GroupName = grp, FontSize = 11, IsChecked = isYes,  Margin = new Thickness(0, 0, 12, 0), Cursor = System.Windows.Input.Cursors.Hand };
                    var rbN = new RadioButton { Content = "No",  GroupName = grp, FontSize = 11, IsChecked = !isYes, Cursor = System.Windows.Input.Cursors.Hand };
                    rbY.SetResourceReference(RadioButton.ForegroundProperty, "TextPrimaryBrush");
                    rbN.SetResourceReference(RadioButton.ForegroundProperty, "TextPrimaryBrush");
                    rbY.Checked += (_, _) => { save("Yes"); SaveJsonApp(); if (app != null) SaveApps(); };
                    rbN.Checked += (_, _) => { save("No");  SaveJsonApp(); if (app != null) SaveApps(); };
                    sp.Children.Add(rbY); sp.Children.Add(rbN);
                    Grid.SetColumn(lbl, 0); Grid.SetColumn(sp, 1);
                    g.Children.Add(lbl); g.Children.Add(sp);
                    PnlPackageInfo.Children.Add(g);
                    return sp;
                }

                // ── Multi-option radio row ─────────────────────────────────
                WrapPanel PkgRadioRow(string label, string[] options, string currentVal, Action<string> save, bool skipGenericSave = false)
                {
                    var g = new Grid { Margin = new Thickness(0, 0, 0, RGAP) };
                    g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                    g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    // Auto height (min 26) so rows with many options — e.g. the six
                    // Download Preference radios — can wrap to a second line unclipped.
                    g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto, MinHeight = 26 });
                    var lbl = new TextBlock { Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    lbl.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    var sp = new WrapPanel { VerticalAlignment = VerticalAlignment.Center };
                    // Do NOT use GroupName — it causes cross-row interference in WPF's visual tree.
                    // Mutual exclusion is handled manually in the Click handler below.
                    var radioButtons = new List<RadioButton>();
                    foreach (var opt in options)
                    {
                        var capOpt = opt;
                        string displayLabel = opt.Replace("_", " ");
                        var rb = new RadioButton
                        {
                            Content = displayLabel,
                            FontSize = 11,
                            IsChecked = currentVal.Equals(opt, StringComparison.OrdinalIgnoreCase),
                            Margin = new Thickness(0, 0, 10, 2),
                            Cursor = System.Windows.Input.Cursors.Hand
                        };
                        rb.SetResourceReference(RadioButton.ForegroundProperty, "TextPrimaryBrush");
                        // Use Click (not Checked) to avoid re-entrancy when IsChecked is set programmatically
                        rb.Click += (_, _) =>
                        {
                            // Manually enforce mutual exclusion within this row
                            foreach (var other in radioButtons)
                                if (!ReferenceEquals(other, rb)) other.IsChecked = false;
                            rb.IsChecked = true;
                            save(capOpt);
                            // When skipGenericSave is set (Req 5 — Download Preference row),
                            // the save callback already persisted ONLY the DownloadPreference
                            // value; do NOT re-serialize the whole entry here.
                            if (!skipGenericSave)
                            {
                                SaveJsonApp();
                                if (app != null) SaveApps();
                            }
                        };
                        radioButtons.Add(rb);
                        sp.Children.Add(rb);
                    }
                    Grid.SetColumn(lbl, 0); Grid.SetColumn(sp, 1);
                    g.Children.Add(lbl); g.Children.Add(sp);
                    PnlPackageInfo.Children.Add(g);
                    return sp;
                }

                // ── ComboBox row ───────────────────────────────────────────
                void PkgComboRow(string label, string[] options, string currentVal, Action<string> save, Action? onChanged = null)
                {
                    var g = new Grid { Margin = new Thickness(0, 0, 0, RGAP) };
                    g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                    g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    g.RowDefinitions.Add(new RowDefinition { Height = new GridLength(26) });
                    var lbl = new TextBlock { Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    lbl.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    var cb = new ComboBox { FontSize = 11, BorderBrush = pBdr, BorderThickness = new Thickness(1), VerticalAlignment = VerticalAlignment.Stretch };
                    cb.SetResourceReference(ComboBox.BackgroundProperty, "InputBgBrush");
                    if (TryFindResource("ModernComboBoxStyle") is Style cbSty) cb.Style = cbSty;
                    foreach (var opt in options) cb.Items.Add(opt);
                    int idx = options.ToList().FindIndex(o => o.Equals(currentVal, StringComparison.OrdinalIgnoreCase));
                    cb.SelectedIndex = idx >= 0 ? idx : 0;
                    cb.SelectionChanged += (_, _) => { if (cb.SelectedItem is string v) { save(v); SaveJsonApp(); if (app != null) SaveApps(); onChanged?.Invoke(); } };
                    Grid.SetColumn(lbl, 0); Grid.SetColumn(cb, 1);
                    g.Children.Add(lbl); g.Children.Add(cb);
                    PnlPackageInfo.Children.Add(g);
                }

                // ══════════════════════════════════════════════════════════════
                // ── Download Source ───────────────────────────────────────────
                // Built FIRST so it renders ABOVE App Identity (same order as the Add App dialog):
                // API Type and its package identifier are what everything else is derived from, so
                // they are what gets filled in first.
                // Matches Add App dialog: API Type, GitHub Repo, Download Page URL, Category, Download Preference
                PkgSection("Download Source");
                // ── Download Source ───────────────────────────────────────────────────────────
                // Only ONE identifier is ever relevant, and which one is decided by API Type:
                //     winget -> Winget Package ID      github -> GitHub Repo
                //     none   -> manual, via Download Page URL.
                //
                // Showing all three at once was misleading, so hide what does not apply.
                // Only ONE identifier is ever relevant, decided by API Type: winget -> Winget
                // Package ID, github -> GitHub Repo, none -> manual via Download Page URL. Rather than
                // build all of them and toggle Visibility (which proved unreliable in this panel), build
                // ONLY the one that applies - the others simply never exist here. Changing API Type
                // re-renders the panel so the correct field appears.
                string apiT = (jsonApp?.ApiType ?? app?.ApiType ?? "URL").Trim();

                // API Type is fixed once the app has been added - it is chosen in the Add App dialog
                // and everything downstream (which identifier field shows, the fetchers, the links) is
                // derived from it. Show it read-only as plain text with no dropdown, so it cannot be
                // changed here. The correct identifier field below is still chosen from the stored apiT.
                {
                    var txApi = PkgTxtRow("API Type", apiT, _ => { });
                    txApi.IsReadOnly = true;
                }

                if (apiT.Equals("github", StringComparison.OrdinalIgnoreCase))
                {
                    // Read-only: the repo is set when the app is added (via the Add App dialog's inline
                    // picker) and cannot be changed here. No picker button, no picker window.
                    var txGh = PkgTxtRow("GitHub Repo", jsonApp?.GitHubRepo ?? "",
                        v => { if (jsonApp != null) jsonApp.GitHubRepo = v; if (app != null) app.GitHubRepo = v; });
                    txGh.IsReadOnly = true;
                }
                else if (apiT.Equals("winget", StringComparison.OrdinalIgnoreCase))
                {
                    // Read-only: the package ID is set when the app is added (via the Add App dialog's
                    // inline picker) and cannot be changed here. No picker button, no picker window.
                    var txWg = PkgTxtRow("Winget Package ID", jsonApp?.WingetPackageId ?? "",
                        v => { if (jsonApp != null) jsonApp.WingetPackageId = v; if (app != null) app.WingetPackageId = v; });
                    txWg.IsReadOnly = true;
                }
                else if (apiT.Equals("Vendor API", StringComparison.OrdinalIgnoreCase))
                {
                    // No shared catalog to pick from (unlike winget/github), so a plain text box.
                    PkgTxtRow("Vendor API ID", jsonApp?.VendorApiId ?? "",
                        v => { if (jsonApp != null) jsonApp.VendorApiId = v; if (app != null) app.VendorApiId = v; });
                }

                // Download Page URL is OPTIONAL for winget/github (the fetchers supply the links). For
                // API Type = URL it is the ONLY way to reach the download, so it is required there.
                PkgTxtRow("Download Page URL", jsonApp?.DownloadPageUrl ?? "",
                    v => { if (jsonApp != null) jsonApp.DownloadPageUrl = v; if (app != null) app.DownloadPageUrl = v; },
                    required: apiT.Equals("URL", StringComparison.OrdinalIgnoreCase));
                PkgComboRow("Category",
                    new[] { "Browser","Communication","Media","PDF","Runtime","Security","Utility","In-House","Other" },
                    jsonApp?.Category ?? "Other",
                    v => { if (jsonApp != null) jsonApp.Category = v; if (app != null) app.Category = v; });
                // Forward-declared so the DownloadPreference save lambda can call it
                // (UpdatePkgMstVisibility is defined after Package Settings rows below)
                Action? _updatePkgMstVisibility = null;
                // The Rule Type checkboxes live on the Intune tab, built after this row, but the
                // Download Preference change has to drive them. The Action is the field declared at
                // class scope (assigned below) so both this row and the download buttons can call it.

                // The Add App dialog stores a Download Preference (default MSI x64) before any
                // link is known, so it is frequently an option the vendor does not publish: the
                // WinSCP winget manifest, for example, carries only x86 builds. The link filter
                // then collapses the one radio that was checked and the row reads as unselected.
                // Fall back to the first option that survived the filter and apply it everywhere
                // the preference is consumed, so the radio, the highlighted download button, the
                // MST rows and the per-app JSON all agree. A locked preference is always among
                // the visible options, so locked apps return at the first check, untouched.
                void EnsureDownloadPrefSelected()
                {
                    var prefPanel = _downloadPrefRadioPanel;
                    if (prefPanel == null) return;
                    RadioButton? firstVisible = null;
                    foreach (var child in prefPanel.Children)
                    {
                        if (child is not RadioButton rbv || rbv.Visibility != Visibility.Visible) continue;
                        if (rbv.IsChecked == true) return; // a visible option is already selected
                        firstVisible ??= rbv;
                    }
                    if (firstVisible == null) return;
                    foreach (var child in prefPanel.Children)
                        if (child is RadioButton rbc) rbc.IsChecked = ReferenceEquals(rbc, firstVisible);
                    string pick = (firstVisible.Content?.ToString() ?? "").Replace(' ', '_');
                    if (jsonApp != null) jsonApp.DownloadPreference = pick;
                    if (app != null) app.DownloadPreference = pick;
                    // Req 5: persist ONLY DownloadPreference to the per-app JSON.
                    if (_selectedApp != null) SaveDownloadPreferenceOnly(_selectedApp, pick);
                    _lastTriggeredDownloadType =
                        pick.StartsWith("MSI", StringComparison.OrdinalIgnoreCase) ? "MSI" : "EXE";
                    _updatePkgMstVisibility?.Invoke();
                    // The preference really did change here (the saved one had no download link),
                    // so the Rule Type follows it exactly as it does for a click.
                    _applyRuleTypeForPreference?.Invoke(pick);
                }

                _downloadPrefRadioPanel = PkgRadioRow("Download Preference",
                    new[] { "MSI_x64","MSI_x86","MSI_ARM64","EXE_x64","EXE_x86","EXE_ARM64" },
                    jsonApp?.DownloadPreference ?? "EXE_x64",
                    v =>
                    {
                        if (jsonApp != null) jsonApp.DownloadPreference = v;
                        if (app != null) app.DownloadPreference = v;
                        // Req 5: persist ONLY DownloadPreference to the per-app JSON.
                        if (_selectedApp != null) SaveDownloadPreferenceOnly(_selectedApp, v);
                        // Keep the download-button trigger type in sync so the Silent
                        // Install/Uninstall fields and button highlight follow the choice.
                        _lastTriggeredDownloadType =
                            v.StartsWith("MSI", StringComparison.OrdinalIgnoreCase) ? "MSI" : "EXE";
                        // Toggle Create MST / Remove Desktop Shortcut visibility
                        _updatePkgMstVisibility?.Invoke();
                        // MSI download -> detect by product code; EXE -> detect by ARP registry key.
                        _applyRuleTypeForPreference?.Invoke(v);
                        // Re-render the download buttons so the highlight follows the new preference
                        if (_lastInfo != null) Dispatcher.BeginInvoke(new Action(() => RenderInfoPanel(_lastInfo)),
                            System.Windows.Threading.DispatcherPriority.Background);
                    },
                    skipGenericSave: true); // Req 5: only DownloadPreference is persisted
                PkgRadioRow("Lock Download Preference",
                    new[] { "Yes", "No" },
                    jsonApp?.LockDownloadPreference ?? "No",
                    v =>
                    {
                        if (jsonApp != null) jsonApp.LockDownloadPreference = v;
                        if (app != null) app.LockDownloadPreference = v;
                        // Re-apply: lock hides all but the selected preference; unlock
                        // restores link-based filtering. Buttons follow on re-render.
                        UpdateDownloadPreferenceRadioVisibility();
                        // Unlocking can re-hide the checked radio, so re-seat the selection.
                        EnsureDownloadPrefSelected();
                        if (_lastInfo != null) Dispatcher.BeginInvoke(new Action(() => RenderInfoPanel(_lastInfo)),
                            System.Windows.Threading.DispatcherPriority.Background);
                    });
                UpdateDownloadPreferenceRadioVisibility(); // filter to links available for this app
                // Runs before the download buttons are built further down this render, so the
                // highlight picks up the corrected preference without a second render pass.
                EnsureDownloadPrefSelected();

                // ── App Identity ──────────────────────────────────────────────
                // Matches Add App dialog: Source App Vendor, Source App Name, Source App Version only
                PkgSection("App Identity");
                PkgTxtRow("Source App Vendor",  jsonApp?.SourceAppVendor  ?? "", v => { if (jsonApp != null) jsonApp.SourceAppVendor  = v; if (app != null) app.SourceAppVendor  = v; }, required: true);
                PkgTxtRow("Source App Name",    jsonApp?.SourceAppName    ?? "", v => { if (jsonApp != null) jsonApp.SourceAppName    = v; if (app != null) app.SourceAppName    = v; }, required: true);
                PkgTxtRow("Source App Version", jsonApp?.SourceAppVersion ?? "", v => { if (jsonApp != null) jsonApp.SourceAppVersion = v; if (app != null) app.SourceAppVersion = v; }, required: true);

                // ── Download Schedule ─────────────────────────────────────────
                PkgSection("Download Schedule");

                // Auto Download Source (Yes/No radios) — stored for wiring
                string autoSrcVal = jsonApp?.AutoDownloadSource ?? "No";
                Grid pkgAutoGrid;
                RadioButton pkgRbAutoYes, pkgRbAutoNo;
                {
                    pkgAutoGrid = new Grid { Margin = new Thickness(0, 0, 0, RGAP) };
                    pkgAutoGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                    pkgAutoGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    var lbl2 = new TextBlock { Text = "Auto Download Source", FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    lbl2.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    var sp2 = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                    string grp2 = Guid.NewGuid().ToString();
                    bool isAutoYes = autoSrcVal.Equals("Yes", StringComparison.OrdinalIgnoreCase);
                    pkgRbAutoYes = new RadioButton { Content = "Yes", GroupName = grp2, FontSize = 11, IsChecked = isAutoYes,  Margin = new Thickness(0,0,12,0), Cursor = System.Windows.Input.Cursors.Hand };
                    pkgRbAutoNo  = new RadioButton { Content = "No",  GroupName = grp2, FontSize = 11, IsChecked = !isAutoYes, Cursor = System.Windows.Input.Cursors.Hand };
                    pkgRbAutoYes.SetResourceReference(RadioButton.ForegroundProperty, "TextPrimaryBrush");
                    pkgRbAutoNo.SetResourceReference(RadioButton.ForegroundProperty,  "TextPrimaryBrush");
                    pkgRbAutoYes.Checked += (_, _) => { if (jsonApp != null) jsonApp.AutoDownloadSource = "Yes"; if (app != null) app.AutoDownloadSource = "Yes"; SaveJsonApp(); SaveApps(); };
                    pkgRbAutoNo.Checked  += (_, _) => { if (jsonApp != null) jsonApp.AutoDownloadSource = "No";  if (app != null) app.AutoDownloadSource = "No";  SaveJsonApp(); SaveApps(); };
                    sp2.Children.Add(pkgRbAutoYes); sp2.Children.Add(pkgRbAutoNo);
                    Grid.SetColumn(lbl2, 0); Grid.SetColumn(sp2, 1);
                    pkgAutoGrid.Children.Add(lbl2); pkgAutoGrid.Children.Add(sp2);
                    PnlPackageInfo.Children.Add(pkgAutoGrid);
                }

                // Download Frequency — combo, only visible when AutoDownload=Yes
                ComboBox pkgCbFreq;
                Grid pkgFreqGrid;
                {
                    pkgFreqGrid = new Grid { Margin = new Thickness(0, 0, 0, RGAP), Visibility = Visibility.Collapsed };
                    pkgFreqGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                    pkgFreqGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    var lbl2 = new TextBlock { Text = "Download Frequency", FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    lbl2.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    pkgCbFreq = new ComboBox { FontSize = 11, Height = 26, BorderBrush = pBdr, BorderThickness = new Thickness(1) };
                    pkgCbFreq.SetResourceReference(ComboBox.BackgroundProperty, "InputBgBrush");
                    if (TryFindResource("ModernComboBoxStyle") is Style cbStyF) pkgCbFreq.Style = cbStyF;
                    var freqOpts = new[] { "Hourly","Daily","Weekly",FREQ_EVERY_2_WEEKS,"Monthly","Quarterly","HalfYearly","Yearly","Every" };
                    foreach (var o in freqOpts) pkgCbFreq.Items.Add(o);
                    // Match on IsEvery2Weeks too, so an app whose JSON still says "Fortnightly"
                    // selects the renamed "Every 2 weeks" item instead of falling back to Hourly.
                    string curFreq = jsonApp?.DownloadFrequency ?? "";
                    int freqIdx = freqOpts.ToList().FindIndex(o =>
                        o.Equals(curFreq, StringComparison.OrdinalIgnoreCase)
                     || (o == FREQ_EVERY_2_WEEKS && IsEvery2Weeks(curFreq)));
                    pkgCbFreq.SelectedIndex = freqIdx >= 0 ? freqIdx : 0;
                    pkgCbFreq.SelectionChanged += (_, _) => { if (pkgCbFreq.SelectedItem is string v) { if (jsonApp != null) jsonApp.DownloadFrequency = v; if (app != null) app.DownloadFrequency = v; SaveJsonApp(); SaveApps(); } };
                    Grid.SetColumn(lbl2, 0); Grid.SetColumn(pkgCbFreq, 1);
                    pkgFreqGrid.Children.Add(lbl2); pkgFreqGrid.Children.Add(pkgCbFreq);
                    PnlPackageInfo.Children.Add(pkgFreqGrid);
                }

                // Schedule Hour — "Every [N] Hours"  (Hourly only)
                Grid pkgHourGrid;
                ComboBox pkgCbHour;
                {
                    pkgHourGrid = new Grid { Margin = new Thickness(0, 0, 0, RGAP), Visibility = Visibility.Collapsed };
                    pkgHourGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                    pkgHourGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    var lbl2 = new TextBlock { Text = "Schedule Hour", FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    lbl2.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    pkgCbHour = new ComboBox { FontSize = 11, Height = 26, Width = 60, HorizontalContentAlignment = HorizontalAlignment.Center };
                    if (TryFindResource("ModernComboBoxStyle") is Style cbStyH) pkgCbHour.Style = cbStyH;
                    foreach (var h in Enumerable.Range(1,12)) pkgCbHour.Items.Add(h.ToString("D2"));
                    string sh = jsonApp?.DownloadScheduleHour ?? "";
                    pkgCbHour.SelectedItem = string.IsNullOrWhiteSpace(sh) ? "02" : sh.PadLeft(2,'0');
                    if (pkgCbHour.SelectedIndex < 0) pkgCbHour.SelectedIndex = 1;
                    pkgCbHour.SelectionChanged += (_, _) => { if (pkgCbHour.SelectedItem is string v) { if (jsonApp != null) jsonApp.DownloadScheduleHour = v; if (app != null) app.DownloadScheduleHour = v; SaveJsonApp(); SaveApps(); } };
                    var pnl2 = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                    pnl2.Children.Add(PkgInline("Every  "));
                    pnl2.Children.Add(pkgCbHour);
                    pnl2.Children.Add(PkgInline("  Hours"));
                    Grid.SetColumn(lbl2, 0); Grid.SetColumn(pnl2, 1);
                    pkgHourGrid.Children.Add(lbl2); pkgHourGrid.Children.Add(pnl2);
                    PnlPackageInfo.Children.Add(pkgHourGrid);
                }

                // Occurrence — "Every month [First/Second/...]" (Every only)
                Grid pkgOccGrid;
                ComboBox pkgCbOcc;
                {
                    pkgOccGrid = new Grid { Margin = new Thickness(0, 0, 0, RGAP), Visibility = Visibility.Collapsed };
                    pkgOccGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                    pkgOccGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    var lbl2 = new TextBlock { Text = "Occurrence", FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    lbl2.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    pkgCbOcc = new ComboBox { FontSize = 11, Height = 26, Width = 110 };
                    if (TryFindResource("ModernComboBoxStyle") is Style cbStyO) pkgCbOcc.Style = cbStyO;
                    foreach (var o in new[] { "First","Second","Third","Fourth" }) pkgCbOcc.Items.Add(o);
                    string savedOcc2 = jsonApp?.DownloadOccurrence ?? "";
                    pkgCbOcc.SelectedItem = string.IsNullOrWhiteSpace(savedOcc2) ? "Second" : savedOcc2;
                    if (pkgCbOcc.SelectedIndex < 0) pkgCbOcc.SelectedItem = "Second";
                    pkgCbOcc.SelectionChanged += (_, _) => { if (pkgCbOcc.SelectedItem is string v) { if (jsonApp != null) jsonApp.DownloadOccurrence = v; if (app != null) app.DownloadOccurrence = v; SaveJsonApp(); SaveApps(); } };
                    var pnl2 = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                    pnl2.Children.Add(PkgInline("Every month  "));
                    pnl2.Children.Add(pkgCbOcc);
                    Grid.SetColumn(lbl2, 0); Grid.SetColumn(pnl2, 1);
                    pkgOccGrid.Children.Add(lbl2); pkgOccGrid.Children.Add(pnl2);
                    PnlPackageInfo.Children.Add(pkgOccGrid);
                }

                // Schedule Days (start of the series, every frequency)
                Grid pkgDaysGrid;
                ComboBox pkgCbDays;
                TextBlock pkgLbDaysPrefix;
                {
                    pkgDaysGrid = new Grid { Margin = new Thickness(0, 0, 0, RGAP), Visibility = Visibility.Collapsed };
                    pkgDaysGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                    pkgDaysGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    var lbl2 = new TextBlock { Text = "Schedule Days", FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    lbl2.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    pkgCbDays = new ComboBox { FontSize = 11, Height = 26, Width = 120, BorderBrush = pBdr, BorderThickness = new Thickness(1) };
                    pkgCbDays.SetResourceReference(ComboBox.BackgroundProperty, "InputBgBrush");
                    if (TryFindResource("ModernComboBoxStyle") is Style cbStyD) pkgCbDays.Style = cbStyD;
                    var daysOpts = new[] { "Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday" };
                    foreach (var o in daysOpts) pkgCbDays.Items.Add(o);
                    int daysIdx = daysOpts.ToList().FindIndex(o => o.Equals(jsonApp?.DownloadScheduleDays ?? "", StringComparison.OrdinalIgnoreCase));
                    pkgCbDays.SelectedIndex = daysIdx >= 0 ? daysIdx : 1;
                    pkgCbDays.SelectionChanged += (_, _) => { if (pkgCbDays.SelectedItem is string v) { if (jsonApp != null) jsonApp.DownloadScheduleDays = v; if (app != null) app.DownloadScheduleDays = v; SaveJsonApp(); SaveApps(); } };

                    // SelectedIndex is set ABOVE the handler, so the default it lands on ("Monday")
                    // never reaches the JSON - the panel showed "On Monday" while the app stored "".
                    // Weekly and Every 2 weeks both need the weekday, so they simply never fired.
                    // Seed the entry with what is on screen the moment the panel is built.
                    if (string.IsNullOrWhiteSpace(jsonApp?.DownloadScheduleDays)
                        && pkgCbDays.SelectedItem is string dayNow)
                    {
                        if (jsonApp != null) jsonApp.DownloadScheduleDays = dayNow;
                        if (app     != null) app.DownloadScheduleDays     = dayNow;
                    }
                    var pnlDays2 = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                    pkgLbDaysPrefix = PkgInline("Starting from  ");
                    pnlDays2.Children.Add(pkgLbDaysPrefix);
                    pnlDays2.Children.Add(pkgCbDays);
                    Grid.SetColumn(lbl2, 0); Grid.SetColumn(pnlDays2, 1);
                    pkgDaysGrid.Children.Add(lbl2); pkgDaysGrid.Children.Add(pnlDays2);
                }

                // Declared here, ahead of the first row that calls them, and assigned once the
                // combos they work on exist - the year block, at the end of the schedule rows.
                // A local cannot be used above the line that declares it, however late it is
                // assigned, and the Date row below is the first caller.
                //
                // pkgSyncDateItems  rebuilds the day list for the month and year now selected.
                // pkgSyncDerivedDay fills the weekday in from the start date.
                Action pkgSyncDateItems  = () => { };
                Action pkgSyncDerivedDay = () => { };

                // Schedule Date (start of the series, every frequency)
                Grid pkgDateGrid;
                ComboBox pkgCbDate;
                TextBlock pkgLbDatePrefix;
                // Set while the day list is being rebuilt for a new month or year, so the rebuild
                // itself does not look like the user picking a date and write to disk.
                bool pkgDateSyncing = false;
                {
                    pkgDateGrid = new Grid { Margin = new Thickness(0, 0, 0, RGAP), Visibility = Visibility.Collapsed };
                    pkgDateGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                    pkgDateGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    var lbl2 = new TextBlock { Text = "Schedule Date", FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    lbl2.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    pkgCbDate = new ComboBox { FontSize = 11, Height = 26, Width = 62, HorizontalContentAlignment = HorizontalAlignment.Center };
                    if (TryFindResource("ModernComboBoxStyle") is Style cbStyDt) pkgCbDate.Style = cbStyDt;
                    foreach (var d in Enumerable.Range(1,31)) pkgCbDate.Items.Add(d.ToString("D2"));
                    string sd = jsonApp?.DownloadScheduleDate ?? "";
                    pkgCbDate.SelectedItem = string.IsNullOrWhiteSpace(sd) ? "01" : sd.PadLeft(2,'0');
                    if (pkgCbDate.SelectedIndex < 0) pkgCbDate.SelectedItem = "01";
                    pkgCbDate.SelectionChanged += (_, _) => { if (pkgDateSyncing) return; if (pkgCbDate.SelectedItem is string v) { if (jsonApp != null) jsonApp.DownloadScheduleDate = v; if (app != null) app.DownloadScheduleDate = v; SaveJsonApp(); SaveApps(); } pkgSyncDerivedDay(); };
                    var pnl2 = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                    pkgLbDatePrefix = PkgInline("On day  ");
                    pnl2.Children.Add(pkgLbDatePrefix);
                    pnl2.Children.Add(pkgCbDate);
                    Grid.SetColumn(lbl2, 0); Grid.SetColumn(pnl2, 1);
                    pkgDateGrid.Children.Add(lbl2); pkgDateGrid.Children.Add(pnl2);
                }

                // Schedule Time — "At [HH] Hours [MM] Minutes" (Daily/Weekly/Fortnightly/Monthly/Quarterly/HalfYearly/Yearly/Every)
                Grid pkgTimeGrid;
                ComboBox pkgCbTimeHour, pkgCbTimeMin;
                // "At" for a schedule that runs at a time, "Starting from" for Hourly, where the
                // time is the phase the interval is counted from. Captured like pkgLbDaysPrefix so
                // UpdatePkgScheduleVisibility owns the wording in one place.
                TextBlock pkgLbTimePrefix;
                // Assigned inside the block below, same pattern as pkgSyncDateItems: the hint depends
                // on the frequency, so the gate has to be able to re-run it.
                Action pkgSyncTimeHint = () => { };
                {
                    pkgTimeGrid = new Grid { Margin = new Thickness(0, 0, 0, RGAP), Visibility = Visibility.Collapsed };
                    pkgTimeGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                    pkgTimeGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    var lbl2 = new TextBlock { Text = "Schedule Time", FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    lbl2.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");

                    pkgCbTimeHour = new ComboBox { FontSize = 11, Height = 26, Width = 52, HorizontalContentAlignment = HorizontalAlignment.Center };
                    pkgCbTimeMin  = new ComboBox { FontSize = 11, Height = 26, Width = 52, HorizontalContentAlignment = HorizontalAlignment.Center };
                    if (TryFindResource("ModernComboBoxStyle") is Style cbStyTH) pkgCbTimeHour.Style = cbStyTH;
                    if (TryFindResource("ModernComboBoxStyle") is Style cbStyTM) pkgCbTimeMin.Style  = cbStyTM;
                    // Hours run 00..23 (a normal 24-hour clock). Hour 24 was once offered as a
                    // separate "end of the scheduled day" value, but 24:00 and 00:00 both read as
                    // midnight and only caused confusion, so it was retired. TryParseScheduleTime still
                    // accepts a legacy "24" in saved data (clamped to 23:59), and the load below maps a
                    // stored "24" to "00", so anything already scheduled keeps working.
                    foreach (var h in Enumerable.Range(0, 24)) pkgCbTimeHour.Items.Add(h.ToString("D2"));
                    foreach (var m in new[] { 0,5,10,15,20,25,30,35,40,45,50,55 }) pkgCbTimeMin.Items.Add(m.ToString("D2"));

                    // Parse saved "HH:MM"
                    string savedTime2 = jsonApp?.DownloadScheduleTime ?? "";
                    string[] tp = savedTime2.Split(':');
                    string pkgHh = tp.Length > 0 && !string.IsNullOrWhiteSpace(tp[0]) ? tp[0].PadLeft(2,'0') : "06";
                    if (pkgHh == "24") pkgHh = "00";   // legacy "end of day" value retired; show midnight
                    pkgCbTimeHour.SelectedItem = pkgHh;
                    pkgCbTimeMin.SelectedItem  = tp.Length > 1 && !string.IsNullOrWhiteSpace(tp[1]) ? tp[1].PadLeft(2,'0') : "00";
                    if (pkgCbTimeHour.SelectedIndex < 0) pkgCbTimeHour.SelectedItem = "06";
                    if (pkgCbTimeMin.SelectedIndex  < 0) pkgCbTimeMin.SelectedItem  = "00";

                    void SaveTime() { string t = $"{pkgCbTimeHour.SelectedItem?.ToString()?.Trim() ?? "06"}:{pkgCbTimeMin.SelectedItem?.ToString()?.Trim() ?? "00"}"; if (jsonApp != null) jsonApp.DownloadScheduleTime = t; if (app != null) app.DownloadScheduleTime = t; SaveJsonApp(); SaveApps(); }
                    // Minutes stay selectable for every hour now that 24 (which forced minutes to 00)
                    // is gone.
                    pkgCbTimeHour.SelectionChanged += (_, _) => SaveTime();
                    pkgCbTimeMin.SelectionChanged  += (_, _) => SaveTime();

                    var pnlTime2 = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                    pkgLbTimePrefix = PkgInline("At  ");
                    pnlTime2.Children.Add(pkgLbTimePrefix);
                    pnlTime2.Children.Add(pkgCbTimeHour);
                    pnlTime2.Children.Add(PkgInline("  Hours  "));
                    pnlTime2.Children.Add(pkgCbTimeMin);
                    pnlTime2.Children.Add(PkgInline("  Minutes"));

                    // 00:00 is the very first minute of the scheduled day. Label it so, since a bare
                    // "00:00" can otherwise read as either midnight-at-the-start or an unset time.
                    var pkgLbTimeHint = new TextBlock
                    {
                        FontSize = 10, FontStyle = FontStyles.Italic,
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(10, 0, 0, 0),
                    };
                    pkgLbTimeHint.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    pnlTime2.Children.Add(pkgLbTimeHint);

                    void SyncTimeHint()
                    {
                        string hh = pkgCbTimeHour.SelectedItem?.ToString() ?? "";
                        bool hourly = (pkgCbFreq.SelectedItem?.ToString()?.Trim() ?? "")
                                      .Equals("Hourly", StringComparison.OrdinalIgnoreCase);

                        // Hourly gets NO inline hint. This row is the widest in the panel, and the
                        // Package Information column is whatever is left after the 462 and 237
                        // MinWidth columns to its left, so at 150% the value area is about 380 units
                        // against roughly 445 needed with a hint on the end. The hint was the part
                        // that ran off the edge.
                        //
                        // Nothing is lost by dropping it: the row prefix already reads "Starting
                        // from" on Hourly rather than "At", which says the same thing in the space
                        // the row was always going to have. The longer explanation moves to a
                        // tooltip, which costs no width at all.
                        //
                        // "(start of the day)" is left exactly as it was for every other frequency.
                        // It predates this change, it is half the length, and it has always fit.
                        pkgLbTimeHint.Text = !hourly && hh == "00" ? "(start of the day)" : "";
                        pkgTimeGrid.ToolTip = hourly
                            ? "The interval is counted from this time. Every 2 hours from 09:00 runs "
                              + "at 09:00, 11:00, 13:00 and on through midnight."
                            : null;
                    }
                    pkgCbTimeHour.SelectionChanged += (_, _) => SyncTimeHint();
                    pkgSyncTimeHint = SyncTimeHint;
                    SyncTimeHint();

                    Grid.SetColumn(lbl2, 0); Grid.SetColumn(pnlTime2, 1);
                    pkgTimeGrid.Children.Add(lbl2); pkgTimeGrid.Children.Add(pnlTime2);
                    // NOT added to the panel here. The rows appear in the order they are added, and
                    // Time belongs after the three that spell out the date: day, then month, then
                    // year. It is added at the end of the Schedule Year block below.
                }

                // Schedule Month (Quarterly / HalfYearly / Yearly / Every 2 weeks / Every)
                Grid pkgMonthGrid;
                ComboBox pkgCbMonth;
                ComboBox pkgCbYear;
                {
                    pkgMonthGrid = new Grid { Margin = new Thickness(0, 0, 0, RGAP), Visibility = Visibility.Collapsed };
                    pkgMonthGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                    pkgMonthGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    var lbl2 = new TextBlock { Text = "Schedule Month", FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    lbl2.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    pkgCbMonth = new ComboBox { FontSize = 11, Height = 26, Width = 130, BorderBrush = pBdr, BorderThickness = new Thickness(1) };
                    pkgCbMonth.SetResourceReference(ComboBox.BackgroundProperty, "InputBgBrush");
                    if (TryFindResource("ModernComboBoxStyle") is Style cbStyM) pkgCbMonth.Style = cbStyM;
                    var monthOpts = new[] { "January","February","March","April","May","June","July","August","September","October","November","December" };
                    foreach (var o in monthOpts) pkgCbMonth.Items.Add(o);
                    int monthIdx = monthOpts.ToList().FindIndex(o => o.Equals(jsonApp?.DownloadScheduleMonth ?? "", StringComparison.OrdinalIgnoreCase));
                    pkgCbMonth.SelectedIndex = monthIdx >= 0 ? monthIdx : 0;
                    pkgCbMonth.SelectionChanged += (_, _) => { if (pkgCbMonth.SelectedItem is string v) { if (jsonApp != null) jsonApp.DownloadScheduleMonth = v; if (app != null) app.DownloadScheduleMonth = v; SaveJsonApp(); SaveApps(); } pkgSyncDateItems(); pkgSyncDerivedDay(); };

                    var pnl2 = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                    pnl2.Children.Add(PkgInline("Starting from  "));
                    pnl2.Children.Add(pkgCbMonth);
                    Grid.SetColumn(lbl2, 0); Grid.SetColumn(pnl2, 1);
                    pkgMonthGrid.Children.Add(lbl2); pkgMonthGrid.Children.Add(pnl2);
                }

                // Schedule Year (same frequencies as Schedule Month)
                Grid pkgYearGrid;
                {
                    pkgYearGrid = new Grid { Margin = new Thickness(0, 0, 0, RGAP), Visibility = Visibility.Collapsed };
                    pkgYearGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                    pkgYearGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    var lbl2 = new TextBlock { Text = "Schedule Year", FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    lbl2.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");

                    pkgCbYear = new ComboBox { FontSize = 11, Height = 26, Width = 96, BorderBrush = pBdr, BorderThickness = new Thickness(1) };
                    pkgCbYear.SetResourceReference(ComboBox.BackgroundProperty, "InputBgBrush");
                    if (TryFindResource("ModernComboBoxStyle") is Style cbStyY) pkgCbYear.Style = cbStyY;
                    for (int y = DateTime.Now.Year - 1; y <= DateTime.Now.Year + 10; y++) pkgCbYear.Items.Add(y.ToString());
                    string savedYear2 = (jsonApp?.DownloadScheduleYear ?? "").Trim();
                    // A stored year outside the offered range (set years ago, or well ahead) is added
                    // rather than silently dropped to something else.
                    if (savedYear2.Length > 0 && !pkgCbYear.Items.Contains(savedYear2)) pkgCbYear.Items.Insert(0, savedYear2);

                    // Choosing a year FOR an app that never had one must not quietly pause it. The
                    // current year is the obvious pick, but if the stored month and day fall later in
                    // this year than today, that start date is in the future and the schedule would
                    // stop until it arrived. Last year is used instead: the series reads as already
                    // running, which is exactly what it was doing before a year existed.
                    string defaultYear = DateTime.Now.Year.ToString();
                    if (savedYear2.Length == 0)
                    {
                        int seedMo = pkgCbMonth.SelectedIndex + 1;
                        if (seedMo < 1 || seedMo > 12) seedMo = 1;
                        int seedDom = int.TryParse(pkgCbDate.SelectedItem as string ?? "", out int sd2) ? sd2 : 1;
                        var seedStart = new DateTime(DateTime.Now.Year, seedMo,
                            ScheduleDayIn(seedDom, DateTime.Now.Year, seedMo));
                        if (seedStart.Date > DateTime.Now.Date) defaultYear = (DateTime.Now.Year - 1).ToString();
                    }

                    pkgCbYear.SelectedItem = savedYear2.Length > 0 ? savedYear2 : defaultYear;
                    if (pkgCbYear.SelectedIndex < 0) pkgCbYear.SelectedItem = defaultYear;

                    // The combo sets SelectedItem above, before the handler below is wired, so a year
                    // it lands on by default would be shown but never stored - the same trap the
                    // Schedule Days combo fell into. Write down what is on screen straight away.
                    if (savedYear2.Length == 0 && pkgCbYear.SelectedItem is string yearNow)
                    {
                        if (jsonApp != null) jsonApp.DownloadScheduleYear = yearNow;
                        if (app     != null) app.DownloadScheduleYear     = yearNow;
                    }

                    pkgCbYear.SelectionChanged += (_, _) =>
                    {
                        if (pkgCbYear.SelectedItem is string v)
                        {
                            if (jsonApp != null) jsonApp.DownloadScheduleYear = v;
                            if (app     != null) app.DownloadScheduleYear     = v;
                            SaveJsonApp(); SaveApps();
                        }
                        pkgSyncDateItems();
                        pkgSyncDerivedDay();
                    };

                    // February has 28 days, or 29 in a leap year, and four months have 30 - so the
                    // day list follows the month and the year that are selected, for EVERY
                    // frequency. They all carry a start date now, and 31 February is not a date on
                    // any of them.
                    //
                    // A stored day the new month cannot hold (31 January, then February) is pulled
                    // back to the last day of that month and written down, so the panel and the JSON
                    // never disagree. A monthly schedule started on the 28th of February still runs
                    // on the 28th of the longer months; the scheduler clamps per month from there.
                    pkgSyncDateItems = () =>
                    {
                        int mo2 = pkgCbMonth.SelectedIndex + 1;
                        if (mo2 < 1 || mo2 > 12) mo2 = 1;
                        int? yr2 = int.TryParse(pkgCbYear.SelectedItem as string ?? "", out int py2) ? py2 : (int?)null;
                        int days2 = DaysInScheduleMonth(yr2, mo2);
                        if (pkgCbDate.Items.Count == days2) return;

                        string cur2 = pkgCbDate.SelectedItem as string ?? "01";
                        pkgDateSyncing = true;
                        pkgCbDate.Items.Clear();
                        foreach (var d in Enumerable.Range(1, days2)) pkgCbDate.Items.Add(d.ToString("D2"));
                        int want2 = int.TryParse(cur2, out int c2) && c2 >= 1 ? Math.Min(c2, days2) : 1;
                        string wantS = want2.ToString("D2");
                        pkgCbDate.SelectedItem = wantS;
                        pkgDateSyncing = false;

                        if (wantS != cur2)
                        {
                            if (jsonApp != null) jsonApp.DownloadScheduleDate = wantS;
                            if (app     != null) app.DownloadScheduleDate     = wantS;
                            SaveJsonApp(); SaveApps();
                        }
                    };

                    // The weekday is not a separate choice, it is a fact about the start date: pick
                    // 1 February 2026 and the day IS Sunday. So the Days row fills itself in from
                    // year + month + date. It stays editable, because Weekly and Every read it as
                    // "which weekday to run", which need not be the weekday the series starts on.
                    pkgSyncDerivedDay = () =>
                    {
                        // Only where the weekday is part of the schedule. Elsewhere the row is hidden
                        // and the field is blanked, so filling it in would put a value in the JSON
                        // that nothing on screen accounts for.
                        string fDerive = pkgCbFreq.SelectedItem?.ToString()?.Trim() ?? "";
                        if (!ScheduleFieldsFor(fDerive).Days) return;
                        // "Every" is the one frequency whose weekday is a real choice, paired with the
                        // occurrence, and the one with no date row to read it from.
                        if (fDerive == "Every") return;
                        int mo3 = pkgCbMonth.SelectedIndex + 1;
                        if (mo3 < 1 || mo3 > 12) mo3 = 1;
                        if (!int.TryParse(pkgCbYear.SelectedItem as string ?? "", out int yr3)) return;
                        if (!int.TryParse(pkgCbDate.SelectedItem as string ?? "", out int dd3)) return;
                        string dayName = new DateTime(yr3, mo3, ScheduleDayIn(dd3, yr3, mo3)).DayOfWeek.ToString();
                        if ((pkgCbDays.SelectedItem as string ?? "") == dayName) return;
                        pkgCbDays.SelectedItem = dayName;   // its own handler stores and saves it
                    };

                    var pnl2 = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                    pnl2.Children.Add(PkgInline("Starting from  "));
                    pnl2.Children.Add(pkgCbYear);
                    Grid.SetColumn(lbl2, 0); Grid.SetColumn(pnl2, 1);
                    pkgYearGrid.Children.Add(lbl2); pkgYearGrid.Children.Add(pnl2);
                }

                // The schedule rows are ADDED here, not in the blocks that build them - those run in
                // whatever order their dependencies allow. Read top to bottom they spell out one
                // date, widest part first: year, month, day of the month, then the weekday that date
                // falls on. The time of day comes last.
                PnlPackageInfo.Children.Add(pkgYearGrid);
                PnlPackageInfo.Children.Add(pkgMonthGrid);
                PnlPackageInfo.Children.Add(pkgDateGrid);
                PnlPackageInfo.Children.Add(pkgDaysGrid);
                PnlPackageInfo.Children.Add(pkgTimeGrid);

                // Keep the stored schedule to exactly the fields the chosen frequency uses, each one
                // holding what its combo is showing. That is two problems in one:
                //
                //   - The JSON kept every field ever set. An app on Hourly still carried Days, Date,
                //     Time, Month and Year from whatever it was before, which reads as though all of
                //     them are in force while the page shows nothing but Schedule Hour.
                //   - The other direction: a row that becomes visible shows its combo default while
                //     the JSON holds nothing for it, so the screen and the file disagree.
                //
                // Only touches a frequency we recognise, so a hand-written one (a literal
                // dd-MM-yyyy date, or None) is left exactly as it was, and only writes when
                // something actually changed.
                void PkgApplyScheduleShape()
                {
                    string f = pkgCbFreq.SelectedItem?.ToString()?.Trim() ?? "";
                    var use = ScheduleFieldsFor(f);
                    if (!(use.Hour || use.Occurrence || use.Days || use.Date || use.Time || use.Month)) return;

                    string hourV  = use.Hour       ? (pkgCbHour.SelectedItem  as string ?? "") : "";
                    string occV   = use.Occurrence ? (pkgCbOcc.SelectedItem   as string ?? "") : "";
                    string daysV  = use.Days       ? (pkgCbDays.SelectedItem  as string ?? "") : "";
                    string dateV  = use.Date       ? (pkgCbDate.SelectedItem  as string ?? "") : "";
                    string monthV = use.Month      ? (pkgCbMonth.SelectedItem as string ?? "") : "";
                    string yearV  = use.Month      ? (pkgCbYear.SelectedItem  as string ?? "") : "";
                    string timeV  = use.Time
                        ? $"{pkgCbTimeHour.SelectedItem as string ?? "06"}:{pkgCbTimeMin.SelectedItem as string ?? "00"}"
                        : "";

                    bool Apply(DownloadSourceEntry? e)
                    {
                        if (e == null) return false;
                        if ((e.DownloadScheduleHour  ?? "") == hourV  && (e.DownloadOccurrence    ?? "") == occV
                         && (e.DownloadScheduleDays  ?? "") == daysV  && (e.DownloadScheduleDate  ?? "") == dateV
                         && (e.DownloadScheduleTime  ?? "") == timeV  && (e.DownloadScheduleMonth ?? "") == monthV
                         && (e.DownloadScheduleYear  ?? "") == yearV) return false;
                        e.DownloadScheduleHour  = hourV;
                        e.DownloadOccurrence    = occV;
                        e.DownloadScheduleDays  = daysV;
                        e.DownloadScheduleDate  = dateV;
                        e.DownloadScheduleTime  = timeV;
                        e.DownloadScheduleMonth = monthV;
                        e.DownloadScheduleYear  = yearV;
                        return true;
                    }

                    bool changed = Apply(jsonApp);
                    changed |= Apply(app);
                    if (changed) { SaveJsonApp(); SaveApps(); }
                }

                // ── Conditional visibility update (mirrors Add App dialog logic exactly) ──
                void UpdatePkgScheduleVisibility()
                {
                    // Only while Application settings is the ACTIVE tab. This function forces its
                    // rows Visible, and it has invokers that run after the tab sweep has collapsed
                    // them - pkgAutoGrid.Loaded fires on the layout pass AFTER RebuildPackageInfoTabs,
                    // so on any other tab it was re-showing the schedule rows on top of that tab's
                    // content (Download Frequency and the Starting-from rows rendered above
                    // Communication on Email settings). Returning here loses nothing: switching to
                    // the Application tab re-invokes this via _pkgReapplyScheduleVis.
                    if (_pkgActiveTab != "app") return;
                    bool srcYes = pkgRbAutoYes.IsChecked == true;
                    string freq = pkgCbFreq.SelectedItem?.ToString()?.Trim() ?? "";
                    System.Diagnostics.Debug.WriteLine($"[PkgSchedule] gate ran: srcYes={srcYes} freq='{freq}'");

                    pkgFreqGrid.Visibility  = srcYes ? Visibility.Visible : Visibility.Collapsed;
                    if (!srcYes)
                    {
                        pkgHourGrid.Visibility = pkgOccGrid.Visibility = pkgDaysGrid.Visibility =
                        pkgDateGrid.Visibility = pkgTimeGrid.Visibility = pkgMonthGrid.Visibility =
                        pkgYearGrid.Visibility = Visibility.Collapsed;
                        return;
                    }
                    // One rule, stated in ScheduleFieldsFor and shared with the Add App dialog and
                    // with what gets written to the JSON. Year, month and date show for every
                    // frequency now - they are the start of the series, and an hourly or daily
                    // schedule has one just as much as a yearly schedule does.
                    var use = ScheduleFieldsFor(freq);
                    pkgHourGrid.Visibility  = use.Hour       ? Visibility.Visible : Visibility.Collapsed;
                    pkgOccGrid.Visibility   = use.Occurrence ? Visibility.Visible : Visibility.Collapsed;
                    pkgYearGrid.Visibility  = use.Month      ? Visibility.Visible : Visibility.Collapsed;
                    pkgMonthGrid.Visibility = use.Month      ? Visibility.Visible : Visibility.Collapsed;
                    pkgDateGrid.Visibility  = use.Date       ? Visibility.Visible : Visibility.Collapsed;
                    pkgDaysGrid.Visibility  = use.Days       ? Visibility.Visible : Visibility.Collapsed;
                    pkgTimeGrid.Visibility  = use.Time       ? Visibility.Visible : Visibility.Collapsed;

                    // Year, month, date and weekday are one start date, so all four rows say so. The
                    // exception is "Every", where the weekday pairs with the occurrence above it and
                    // reads as "the Fourth Friday", not as a starting point.
                    pkgLbDaysPrefix.Text = freq == "Every" ? "" : "Starting from  ";

                    // Year, month and date are all one thing - where the series starts - so all three
                    // rows say so.
                    pkgLbDatePrefix.Text = "Starting from  ";

                    // On Hourly the time joins them: it is the phase the interval is counted from,
                    // not the moment of a run. Every other frequency runs AT it.
                    pkgLbTimePrefix.Text = freq.Equals("Hourly", StringComparison.OrdinalIgnoreCase)
                                         ? "Starting from  " : "At  ";
                    pkgSyncTimeHint();

                    // The frequency decides whether the day list is measured against the chosen
                    // month, so it has to be re-checked here too, not only when a month or year is
                    // picked.
                    pkgSyncDateItems();

                    // The weekday is only a choice under "Every", where it pairs with the occurrence
                    // to mean "the Fourth Thursday". Everywhere else it is a fact about the start
                    // date - 30 July 2026 IS a Thursday - so the combo is locked.
                    //
                    // Locking it means it has to be RIGHT, which is why the value is re-derived here
                    // and not only when a date is picked: a weekday stored under an older date would
                    // otherwise sit there for good, contradicting the date two rows above it and
                    // with no way for anyone to correct it.
                    bool dayIsChosen = freq == "Every";
                    pkgCbDays.IsEnabled = dayIsChosen;
                    pkgCbDays.ToolTip   = dayIsChosen ? null : "Set by the schedule date above";
                    if (!dayIsChosen) pkgSyncDerivedDay();

                    // Then write the schedule down as the rows now stand. After pkgSyncDateItems,
                    // so a day clamped to the end of a short month is the one that gets stored.
                    PkgApplyScheduleShape();
                }

                // Wire radio and frequency combo changes to visibility update
                pkgRbAutoYes.Checked    += (_, _) => UpdatePkgScheduleVisibility();
                pkgRbAutoNo.Checked     += (_, _) => UpdatePkgScheduleVisibility();
                pkgCbFreq.SelectionChanged += (_, _) => UpdatePkgScheduleVisibility();
                _pkgReapplyScheduleVis = UpdatePkgScheduleVisibility;

                // Apply initial state immediately
                UpdatePkgScheduleVisibility();
                // The synchronous pass above can run before the Yes/No radios are fully realized in
                // the visual tree, so IsChecked may read stale and the fields render as if Yes. That is
                // why toggling fixed it but the first render did not. Re-apply once the row is loaded
                // and the radio group has settled, so the very first render matches the No state.
                pkgAutoGrid.Loaded += (_, _) => UpdatePkgScheduleVisibility();

                // ── Silent Parameters ─────────────────────────────────────────
                // Matches Add App dialog: Silent Install MSI, Silent Uninstall MSI, Silent Install EXE, Silent Uninstall EXE, Install Source Silently, Uninstall Source Silently
                PkgSection("Silent Parameters");
                PkgTxtRow("Silent Install MSI",     jsonApp?.SilentInstallParameterMSI   ?? "", v => { if (jsonApp != null) jsonApp.SilentInstallParameterMSI   = v; if (app != null) app.SilentInstallParameterMSI   = v; });
                PkgTxtRow("Silent Uninstall MSI",   jsonApp?.SilentUninstallParameterMSI ?? "", v => { if (jsonApp != null) jsonApp.SilentUninstallParameterMSI = v; if (app != null) app.SilentUninstallParameterMSI = v; });
                PkgTxtRow("Silent Install EXE",     jsonApp?.SilentInstallParameterEXE   ?? "", v => { if (jsonApp != null) jsonApp.SilentInstallParameterEXE   = v; if (app != null) app.SilentInstallParameterEXE   = v; });
                PkgTxtRow("Silent Uninstall EXE",   jsonApp?.SilentUninstallParameterEXE ?? "", v => { if (jsonApp != null) jsonApp.SilentUninstallParameterEXE = v; if (app != null) app.SilentUninstallParameterEXE = v; });
                PkgTxtRowWithFileBrowse("Uninstall Path",
                    jsonApp?.UninstallPath ?? "",
                    v => { if (jsonApp != null) jsonApp.UninstallPath = v; if (app != null) app.UninstallPath = v; });
                PkgRadioYesNo("Install Source Silently",
                    jsonApp?.InstallSourceSilently ?? "No",
                    v => { if (jsonApp != null) jsonApp.InstallSourceSilently = v; if (app != null) app.InstallSourceSilently = v; chkInstall.IsChecked = v.Equals("Yes", StringComparison.OrdinalIgnoreCase); });
                PkgRadioYesNo("Uninstall Source Silently",
                    jsonApp?.UninstallSourceSilently ?? "No",
                    v => { if (jsonApp != null) jsonApp.UninstallSourceSilently = v; if (app != null) app.UninstallSourceSilently = v; chkUninstall.IsChecked = v.Equals("Yes", StringComparison.OrdinalIgnoreCase); });

                // ── Package Settings ──────────────────────────────────────────
                // Matches Add App dialog order exactly:
                // Create Package, Create MST, Remove Desktop Shortcut, Template Folder,
                // App Vendor, App Name, App Version, Close Apps,
                // Add Install Name, Add Install Title, Hide buttons,
                // Install Package, Uninstall Package, Show Message Box, Uninstall Path, Description
                PkgSection("Package Settings");

                // Create Package sits at the top of Package Settings (above Create MST).
                var spPkgCreatePkg = PkgRadioYesNo("Create Package",
                    jsonApp?.CreatePackage ?? "No",
                    v => { if (jsonApp != null) jsonApp.CreatePackage = v; if (app != null) app.CreatePackage = v; chkPC.IsChecked = v.Equals("Yes", StringComparison.OrdinalIgnoreCase); });

                // Capture panels so visibility can be toggled when DownloadPreference changes
                StackPanel spPkgCreateMst     = PkgRadioYesNo("Create MST",
                    jsonApp?.CreateMST ?? "No",
                    v => { if (jsonApp != null) jsonApp.CreateMST = v; if (app != null) app.CreateMST = v; });
                StackPanel spPkgRemoveDesktop = PkgRadioYesNo("Remove Desktop Shortcut",
                    jsonApp?.RemoveDesktopShortcut ?? "No",
                    v => { if (jsonApp != null) jsonApp.RemoveDesktopShortcut = v; if (app != null) app.RemoveDesktopShortcut = v; });

                // Remove Desktop Shortcut is editable only when Create MST = Yes; when No, force it to No + disable.
                {
                    var mstY = spPkgCreateMst.Children.OfType<RadioButton>().FirstOrDefault(rb => (rb.Content as string) == "Yes");
                    var mstN = spPkgCreateMst.Children.OfType<RadioButton>().FirstOrDefault(rb => (rb.Content as string) == "No");
                    var remN = spPkgRemoveDesktop.Children.OfType<RadioButton>().FirstOrDefault(rb => (rb.Content as string) == "No");
                    void SyncPkgRemoveDesktop()
                    {
                        bool mstOn = mstY?.IsChecked == true;
                        spPkgRemoveDesktop.IsEnabled = mstOn;
                        if (!mstOn && remN != null) remN.IsChecked = true;
                    }
                    if (mstY != null) mstY.Checked += (_, _) => SyncPkgRemoveDesktop();
                    if (mstN != null) mstN.Checked += (_, _) => SyncPkgRemoveDesktop();
                    SyncPkgRemoveDesktop();
                }

                // Show Create MST / Remove Desktop Shortcut only when preference is MSI
                void UpdatePkgMstVisibility()
                {
                    string pref = _selectedApp?.DownloadPreference ?? "";
                    bool isMsi  = pref.StartsWith("MSI", StringComparison.OrdinalIgnoreCase);
                    // Hide the entire Grid row (parent of the StackPanel) so the label also disappears
                    if (spPkgCreateMst.Parent     is Grid gMst)     gMst.Visibility     = isMsi ? Visibility.Visible : Visibility.Collapsed;
                    if (spPkgRemoveDesktop.Parent is Grid gRemove)  gRemove.Visibility  = isMsi ? Visibility.Visible : Visibility.Collapsed;
                }
                _updatePkgMstVisibility = UpdatePkgMstVisibility; // wire forward-declared Action
                _pkgReapplyMstVis       = UpdatePkgMstVisibility; // survives the tab sweep (see ShowPackageInfoTab)
                UpdatePkgMstVisibility(); // set initial state
                // Declare refs before PkgTxtRow so the PSADT folder callback can close over them
                WrapPanel? spPkgInstallPkg   = null;
                WrapPanel? spPkgUninstallPkg = null;
                // Install/Uninstall Command textboxes (under Intune & Deployment) — captured
                // below so the PSADT Template Folder change handler can re-fill them (Req 3/4).
                TextBox? txInstallCmd   = null;
                TextBox? txUninstallCmd = null;
                // PSADT Install/Uninstall Command textboxes (Package Settings) - forward-declared
                // for the same reason: the folder change handler gates them and re-fills them.
                TextBox? txPsadtInstallCmd   = null;
                TextBox? txPsadtUninstallCmd = null;

                // Capture the PSADT Template Folder TextBox so we can wire TextChanged after
                // spPkgInstallPkg/spPkgUninstallPkg are assigned below
                int pkgGateStart = PnlPackageInfo.Children.Count;
                var txPsadtTplFolder = PkgTxtRowWithFolderBrowse("PSADT Template Folder", jsonApp?.PSADTTemplateFolder ?? "", v =>
                {
                    if (jsonApp != null) jsonApp.PSADTTemplateFolder = v;
                    if (app    != null) app.PSADTTemplateFolder      = v;
                });
                PkgTxtRow("App Vendor",         jsonApp?.AppVendor      ?? "", v => { if (jsonApp != null) jsonApp.AppVendor      = v; if (app != null) app.AppVendor      = v; }, required: true);
                PkgTxtRow("App Name",           jsonApp?.AppName        ?? "", v => { if (jsonApp != null) jsonApp.AppName        = v; if (app != null) app.AppName        = v; }, required: true);
                PkgTxtRow("App Version",        jsonApp?.AppVersion     ?? "", v => { if (jsonApp != null) jsonApp.AppVersion     = v; if (app != null) app.AppVersion     = v; }, required: true);
                var txCloseApps = PkgTxtRow("Close Apps", jsonApp?.CloseApps ?? "", v => { if (jsonApp != null) jsonApp.CloseApps = v; if (app != null) app.CloseApps = v; });
                var spPkgAddInstallName  = PkgRadioYesNo("Add Install Name",
                    jsonApp?.AddInstallName ?? "No",
                    v => { if (jsonApp != null) jsonApp.AddInstallName = v; if (app != null) app.AddInstallName = v; });
                var spPkgAddInstallTitle = PkgRadioYesNo("Add Install Title",
                    jsonApp?.AddInstallTitle ?? "Yes",
                    v => { if (jsonApp != null) jsonApp.AddInstallTitle = v; if (app != null) app.AddInstallTitle = v; });
                var spPkgAddNoRemove = PkgRadioYesNo("Hide Uninstall Button",
                    jsonApp?.AddNoRemove ?? "Yes",
                    v => { if (jsonApp != null) jsonApp.AddNoRemove = v; if (app != null) app.AddNoRemove = v; });
                var spPkgAddNoModify = PkgRadioYesNo("Hide Change Button",
                    jsonApp?.AddNoModify ?? "Yes",
                    v => { if (jsonApp != null) jsonApp.AddNoModify = v; if (app != null) app.AddNoModify = v; });
                var spPkgAddNoRepair = PkgRadioYesNo("Hide Repair Button",
                    jsonApp?.AddNoRepair ?? "Yes",
                    v => { if (jsonApp != null) jsonApp.AddNoRepair = v; if (app != null) app.AddNoRepair = v; });

                StackPanel? spPkgShowMsgBox = null; // forward-declared; assigned after Install/Uninstall Package rows

                // Resolve current values from _selectedApp (always authoritative) with JSON fallback
                string curInstallPkg   = _selectedApp?.InstallPackage   ?? jsonApp?.InstallPackage   ?? "No";
                string curUninstallPkg = _selectedApp?.UninstallPackage ?? jsonApp?.UninstallPackage ?? "No";
                // Normalise legacy "Yes" values
                if (curInstallPkg.Equals("Yes",   StringComparison.OrdinalIgnoreCase)) curInstallPkg   = "Administrator";
                if (curUninstallPkg.Equals("Yes",  StringComparison.OrdinalIgnoreCase)) curUninstallPkg = "Administrator";

                spPkgInstallPkg = PkgRadioRow("Install Package",
                    new[] { "No", "Administrator", "System Context" },
                    curInstallPkg,
                    v =>
                    {
                        if (jsonApp      != null) jsonApp.InstallPackage      = v;
                        if (app          != null) app.InstallPackage          = v;
                        if (_selectedApp != null) _selectedApp.InstallPackage = v;
                        // Sync checkbox — guard prevents re-entry loop
                        bool shouldCheck = !v.Equals("No", StringComparison.OrdinalIgnoreCase);
                        _updatingInstallPkg = true;
                        if (chkInstallPkg.IsChecked != shouldCheck) chkInstallPkg.IsChecked = shouldCheck;
                        _updatingInstallPkg = false;
                    });
                bool initTpl = !string.IsNullOrWhiteSpace(txPsadtTplFolder.Text);
                txCloseApps.IsEnabled          = initTpl;
                spPkgInstallPkg.IsEnabled      = initTpl;
                spPkgInstallPkg.Opacity        = initTpl ? 1.0 : 0.5;
                spPkgAddInstallName.IsEnabled  = initTpl;
                spPkgAddInstallTitle.IsEnabled = initTpl;
                spPkgAddNoRemove.IsEnabled     = initTpl;
                spPkgAddNoModify.IsEnabled     = initTpl;
                spPkgAddNoRepair.IsEnabled     = initTpl;
                SetPkgActionEnabled(chkInstallPkg,   initTpl);
                SetPkgActionEnabled(chkUninstallPkg, initTpl);
                // Package group is editable only when the PSADT Template Folder is set.
                if (spPkgShowMsgBox != null) spPkgShowMsgBox.IsEnabled = initTpl;

                spPkgUninstallPkg = PkgRadioRow("Uninstall Package",
                    new[] { "No", "Administrator", "System Context" },
                    curUninstallPkg,
                    v =>
                    {
                        if (jsonApp      != null) jsonApp.UninstallPackage      = v;
                        if (app          != null) app.UninstallPackage          = v;
                        if (_selectedApp != null) _selectedApp.UninstallPackage = v;
                        bool shouldCheck = !v.Equals("No", StringComparison.OrdinalIgnoreCase);
                        _updatingUninstallPkg = true;
                        if (chkUninstallPkg.IsChecked != shouldCheck) chkUninstallPkg.IsChecked = shouldCheck;
                        _updatingUninstallPkg = false;
                    });
                spPkgUninstallPkg.IsEnabled = initTpl;
                spPkgUninstallPkg.Opacity   = initTpl ? 1.0 : 0.5;

                // Open Application (Yes/No) - sits directly after Uninstall Package.
                // When Yes, Execute opens the installed app's main exe after a successful
                // Install, holds it 2-3s, then closes it before the next step. Default No.
                var spPkgOpenApp = PkgRadioYesNo("Open Application",
                    jsonApp?.OpenApplication ?? "No",
                    v => { if (jsonApp != null) jsonApp.OpenApplication = v; if (app != null) app.OpenApplication = v; if (_selectedApp != null) _selectedApp.OpenApplication = v; });
                spPkgOpenApp.IsEnabled = initTpl;
                spPkgOpenApp.Opacity   = initTpl ? 1.0 : 0.5;

                // Wire live enable/disable to PSADT Template Folder TextBox — runs AFTER
                // spPkgInstallPkg and spPkgUninstallPkg are assigned so refs are always valid
                // Create Package = No disables the PSADT Template Folder + the downstream
                // checkboxes (Install/Uninstall package, Create intunewin, Publish settings,
                // Publish to intune, Send mail). Install/Uninstall also require a template folder.
                void SyncCreatePkgGating()
                {
                    bool createOn = string.Equals(_selectedApp?.CreatePackage, "Yes", StringComparison.OrdinalIgnoreCase);
                    bool tpl      = !string.IsNullOrWhiteSpace(txPsadtTplFolder.Text);
                    chkCreateIntunewin.IsEnabled  = createOn;
                    SyncPublishChainEnabled();   // Publish settings/intune + Send mail follow the cascade, not just createOn
                    SetPkgActionEnabled(chkInstallPkg,   createOn && tpl);
                    SetPkgActionEnabled(chkUninstallPkg, createOn && tpl);
                    // Create MST + Remove Desktop rows sit above the Create Package row.
                    if (spPkgCreateMst.Parent     is UIElement mstRow) mstRow.IsEnabled = createOn;
                    if (spPkgRemoveDesktop.Parent is UIElement remRow) remRow.IsEnabled = createOn;
                    // PSADT Template Folder + every row below it (App identity, Intune & Deployment, Communication).
                    for (int gi = pkgGateStart; gi < PnlPackageInfo.Children.Count; gi++)
                        PnlPackageInfo.Children[gi].IsEnabled = createOn;
                    if (createOn)
                    {
                        // Re-apply the finer rules the blanket enable above flattened.
                        // Remove Desktop needs Create MST = Yes (rule inlined; the helper is block-scoped).
                        bool mstOn = spPkgCreateMst.Children.OfType<RadioButton>().FirstOrDefault(rb => (rb.Content as string) == "Yes")?.IsChecked == true;
                        spPkgRemoveDesktop.IsEnabled = mstOn;
                        txCloseApps.IsEnabled          = tpl;          // PSADT sub-group needs a template folder
                        spPkgAddInstallName.IsEnabled  = tpl;
                        spPkgAddInstallTitle.IsEnabled = tpl;
                        spPkgAddNoRemove.IsEnabled     = tpl;
                        spPkgAddNoModify.IsEnabled     = tpl;
                        spPkgAddNoRepair.IsEnabled     = tpl;
                        if (spPkgInstallPkg   != null) spPkgInstallPkg.IsEnabled   = tpl;
                        if (spPkgUninstallPkg != null) spPkgUninstallPkg.IsEnabled = tpl;
                        spPkgOpenApp.IsEnabled = tpl;
                        if (spPkgShowMsgBox   != null) spPkgShowMsgBox.IsEnabled   = tpl;
                    }
                }
                {
                    var cpY = spPkgCreatePkg.Children.OfType<RadioButton>().FirstOrDefault(rb => (rb.Content as string) == "Yes");
                    var cpN = spPkgCreatePkg.Children.OfType<RadioButton>().FirstOrDefault(rb => (rb.Content as string) == "No");
                    if (cpY != null) cpY.Checked += (_, _) => SyncCreatePkgGating();
                    if (cpN != null) cpN.Checked += (_, _) => SyncCreatePkgGating();
                }

                txPsadtTplFolder.TextChanged += (_, _) =>
                {
                    bool tplSet = !string.IsNullOrWhiteSpace(txPsadtTplFolder.Text);
                    // ── Package Information panel radio rows ──
                    // Package Information group enabled only when the PSADT Template Folder is set.
                    spPkgInstallPkg.IsEnabled   = tplSet;
                    spPkgUninstallPkg.IsEnabled = tplSet;
                    spPkgInstallPkg.Opacity     = tplSet ? 1.0 : 0.5;
                    spPkgUninstallPkg.Opacity   = tplSet ? 1.0 : 0.5;
                    spPkgOpenApp.IsEnabled      = tplSet;
                    spPkgOpenApp.Opacity        = tplSet ? 1.0 : 0.5;
                    SyncCreatePkgGating();
                    txCloseApps.IsEnabled           = tplSet;
                    spPkgAddInstallName.IsEnabled   = tplSet;
                    spPkgAddInstallTitle.IsEnabled  = tplSet;
                    spPkgAddNoRemove.IsEnabled      = tplSet;
                    spPkgAddNoModify.IsEnabled      = tplSet;
                    spPkgAddNoRepair.IsEnabled      = tplSet;
                    if (spPkgShowMsgBox != null) spPkgShowMsgBox.IsEnabled = tplSet;
                    if (txPsadtInstallCmd   != null) txPsadtInstallCmd.IsEnabled   = tplSet;
                    if (txPsadtUninstallCmd != null) txPsadtUninstallCmd.IsEnabled = tplSet;
                    if (!tplSet)
                    {
                        // Reset to No when folder is cleared and sync checkboxes
                        if (jsonApp != null) { jsonApp.InstallPackage = "No"; jsonApp.UninstallPackage = "No"; }
                        if (app     != null) { app.InstallPackage     = "No"; app.UninstallPackage     = "No"; }
                        SyncPkgInfoRadio("Install Package",   "No");
                        SyncPkgInfoRadio("Uninstall Package", "No");
                        chkInstallPkg.IsChecked   = false;
                        chkUninstallPkg.IsChecked = false;
                        foreach (var rb in spPkgInstallPkg.Children.OfType<RadioButton>())
                            rb.IsChecked = rb.Content?.ToString() == "No";
                        foreach (var rb in spPkgUninstallPkg.Children.OfType<RadioButton>())
                            rb.IsChecked = rb.Content?.ToString() == "No";
                    }

                    // ── Req 3/4: re-fill Install/Uninstall Command based on template folder ──
                    // Req 3 (folder SET):   show PSADTInstallCommand / PSADTUninstallCommand.
                    // Req 4 (folder EMPTY): show SourceInstallCommand / SourceUninstallCommand.
                    // Values come from the per-app JSON (jsonApp) with live-app fallback.
                    if (tplSet)
                    {
                        // When a template folder becomes available while Publish settings is on, the
                        // package must be installed and uninstalled as part of the publish flow —
                        // auto-check both if not already checked.
                        if (chkPublishToIntune.IsChecked == true)
                        {
                            if (chkInstallPkg.IsChecked   != true) chkInstallPkg.IsChecked   = true;
                            if (chkUninstallPkg.IsChecked != true) chkUninstallPkg.IsChecked = true;
                        }
                        string pi = !string.IsNullOrWhiteSpace(jsonApp?.PSADTInstallCommand)   ? jsonApp!.PSADTInstallCommand
                                  : !string.IsNullOrWhiteSpace(app?.PSADTInstallCommand)        ? app!.PSADTInstallCommand
                                  : DefaultPsadtInstallCommand;
                        string pu = !string.IsNullOrWhiteSpace(jsonApp?.PSADTUninstallCommand)   ? jsonApp!.PSADTUninstallCommand
                                  : !string.IsNullOrWhiteSpace(app?.PSADTUninstallCommand)       ? app!.PSADTUninstallCommand
                                  : DefaultPsadtUninstallCommand;
                        if (txInstallCmd   != null) { txInstallCmd.Text   = pi; if (jsonApp != null) jsonApp.InstallCommand   = pi; if (app != null) app.InstallCommand   = pi; }
                        if (txUninstallCmd != null) { txUninstallCmd.Text = pu; if (jsonApp != null) jsonApp.UninstallCommand = pu; if (app != null) app.UninstallCommand = pu; }
                        // Keep the Package Settings copies showing the same resolved commands.
                        if (txPsadtInstallCmd   != null && txPsadtInstallCmd.Text   != pi) txPsadtInstallCmd.Text   = pi;
                        if (txPsadtUninstallCmd != null && txPsadtUninstallCmd.Text != pu) txPsadtUninstallCmd.Text = pu;
                    }
                    else
                    {
                        string ii = jsonApp?.SourceInstallCommand   ?? app?.SourceInstallCommand   ?? "";
                        string iu = jsonApp?.SourceUninstallCommand ?? app?.SourceUninstallCommand ?? "";
                        if (txInstallCmd   != null) { txInstallCmd.Text   = ii; if (jsonApp != null) jsonApp.InstallCommand   = ii; if (app != null) app.InstallCommand   = ii; }
                        if (txUninstallCmd != null) { txUninstallCmd.Text = iu; if (jsonApp != null) jsonApp.UninstallCommand = iu; if (app != null) app.UninstallCommand = iu; }
                    }
                };
                spPkgShowMsgBox = PkgRadioYesNo("Show Message Box",
                    jsonApp?.ShowMessageBox ?? "No",
                    v => { if (jsonApp != null) jsonApp.ShowMessageBox = v; if (app != null) app.ShowMessageBox = v; });
                // "Show Message Box" is enabled only when the PSADT Template Folder is set.
                spPkgShowMsgBox.IsEnabled = initTpl;

                // ── PSADT Install / Uninstall Command ──────────────────────────
                // These edit PSADTInstallCommand / PSADTUninstallCommand in the per-app JSON
                // directly. The Install Command / Uninstall Command rows on the Intune tab already
                // display these SAME two values whenever a template folder is set (they fall back
                // to the Source* commands when it is not), so an edit here is mirrored into those
                // boxes and into InstallCommand / UninstallCommand. Without the mirror the two
                // tabs would show different text for one value until the panel was rebuilt.
                // The Text guards on both sides stop the mirroring from looping: PkgTxtRow saves
                // on every keystroke, so an unguarded assignment would bounce between the pair.
                string initPsadtInst = !string.IsNullOrWhiteSpace(jsonApp?.PSADTInstallCommand)   ? jsonApp!.PSADTInstallCommand
                                     : !string.IsNullOrWhiteSpace(app?.PSADTInstallCommand)       ? app!.PSADTInstallCommand
                                     : DefaultPsadtInstallCommand;
                string initPsadtUnin = !string.IsNullOrWhiteSpace(jsonApp?.PSADTUninstallCommand) ? jsonApp!.PSADTUninstallCommand
                                     : !string.IsNullOrWhiteSpace(app?.PSADTUninstallCommand)     ? app!.PSADTUninstallCommand
                                     : DefaultPsadtUninstallCommand;
                txPsadtInstallCmd = PkgTxtRow("PSADT Install Command", initPsadtInst, v =>
                {
                    // Independent of the Intune Install Command: an edit here touches only the PSADT field.
                    if (jsonApp != null) jsonApp.PSADTInstallCommand = v;
                    if (app     != null) app.PSADTInstallCommand     = v;
                });
                txPsadtUninstallCmd = PkgTxtRow("PSADT Uninstall Command", initPsadtUnin, v =>
                {
                    // Independent of the Intune Uninstall Command: an edit here touches only the PSADT field.
                    if (jsonApp != null) jsonApp.PSADTUninstallCommand = v;
                    if (app     != null) app.PSADTUninstallCommand     = v;
                });
                // Gated like Close Apps and Show Message Box above: a PSADT command means nothing
                // without a PSADT template folder.
                txPsadtInstallCmd.IsEnabled   = initTpl;
                txPsadtUninstallCmd.IsEnabled = initTpl;

                // ── Intune & Deployment ───────────────────────────────────────
                // Matches Add App dialog: Create Intunewin, Publish settings, Publish to intune,
                // Deployment Type, Detection Type, Group Name, Description
                PkgSection("Intune & Deployment");
                // ── Intune dependency state ────────────────────────────────────
                bool pkgIntunewinIsYes = (jsonApp?.CreateIntunewin ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase);
                bool pkgPublishIsYes   = (jsonApp?.PublishSettings  ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase);

                // Forward-declare so lambdas can reference each other
                StackPanel? spPublish = null;
                StackPanel? spDeploy  = null;

                var spIntunewin = PkgRadioYesNo("Create Intunewin",
                    jsonApp?.CreateIntunewin ?? "No",
                    v =>
                    {
                        if (jsonApp != null) jsonApp.CreateIntunewin = v; if (app != null) app.CreateIntunewin = v;
                        chkCreateIntunewin.IsChecked = v.Equals("Yes", StringComparison.OrdinalIgnoreCase);
                        bool on = v.Equals("Yes", StringComparison.OrdinalIgnoreCase);
                        if (spPublish != null) spPublish.IsEnabled = true;
                        // When Intunewin turns off, also disable Deploy and reset Publish+Deploy to No
                        if (!on)
                        {
                            if (spDeploy != null) spDeploy.IsEnabled = true;
                        }
                        else
                        {
                            // Re-enable Deploy only if Publish is currently Yes
                            if (spDeploy != null)
                                spDeploy.IsEnabled = true;
                        }
                    },
                    enabled: true);

                spPublish = PkgRadioYesNo("Publish settings",
                    jsonApp?.PublishSettings ?? "No",
                    v =>
                    {
                        if (jsonApp != null) jsonApp.PublishSettings = v; if (app != null) app.PublishSettings = v;
                        chkPublishToIntune.IsChecked = v.Equals("Yes", StringComparison.OrdinalIgnoreCase);
                        if (spDeploy != null) spDeploy.IsEnabled = true;
                    },
                    enabled: pkgIntunewinIsYes);

                spDeploy = PkgRadioYesNo("Publish to intune",
                    jsonApp?.PublishToIntune ?? "No",
                    v =>
                    {
                        if (jsonApp != null) jsonApp.PublishToIntune = v; if (app != null) app.PublishToIntune = v;
                        chkPublishToIntune2.IsChecked = v.Equals("Yes", StringComparison.OrdinalIgnoreCase);
                    },
                    enabled: pkgIntunewinIsYes && pkgPublishIsYes);

                // ── Intune Category ─────────────────────────────────────────
                var pkgIntuneCatItems = new[] {
                    "Business", "Books & Reference", "Developer Tools", "Education",
                    "Entertainment", "Games", "Government & Politics", "Kids",
                    "Lifestyle", "Medical", "Productivity", "Security",
                    "Shopping", "Social", "Sports", "Travel", "Utilities", "Other" };
                var pkgIntuneCatGrid = new Grid { Margin = new Thickness(0, 0, 0, RGAP) };
                pkgIntuneCatGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                pkgIntuneCatGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                pkgIntuneCatGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(26) });
                var pkgIntuneCatLb = new TextBlock { Text = "Category", FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                pkgIntuneCatLb.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                var pkgIntuneCatCb = new ComboBox { FontSize = 11, VerticalAlignment = VerticalAlignment.Stretch };
                if (TryFindResource("ModernComboBoxStyle") is Style intuneCatStyle) pkgIntuneCatCb.Style = intuneCatStyle;
                foreach (var ci in pkgIntuneCatItems) pkgIntuneCatCb.Items.Add(ci);
                var pkgIntuneCatIdx = Array.FindIndex(pkgIntuneCatItems, c => c.Equals(jsonApp?.IntuneCategory, StringComparison.OrdinalIgnoreCase));
                pkgIntuneCatCb.SelectedIndex = pkgIntuneCatIdx >= 0 ? pkgIntuneCatIdx : 0;
                pkgIntuneCatCb.SelectionChanged += (_, _) =>
                {
                    string v = pkgIntuneCatCb.SelectedItem?.ToString() ?? "Business";
                    if (jsonApp != null) jsonApp.IntuneCategory = v;
                    if (app != null) app.IntuneCategory = v;
                    SaveApps(); SaveJsonApp();
                };
                Grid.SetColumn(pkgIntuneCatLb, 0); Grid.SetColumn(pkgIntuneCatCb, 1);
                pkgIntuneCatGrid.Children.Add(pkgIntuneCatLb); pkgIntuneCatGrid.Children.Add(pkgIntuneCatCb);
                PnlPackageInfo.Children.Add(pkgIntuneCatGrid);

                // ── 1  App Info tab ─────────────────────────────────────────
                PkgTxtRow("App Name",    jsonApp?.IntuneAppName    ?? "", v => { if (jsonApp != null) jsonApp.IntuneAppName    = v; if (app != null) app.IntuneAppName    = v; }, required: true);
                PkgTxtRow("App Vendor",  jsonApp?.IntuneAppVendor  ?? "", v => { if (jsonApp != null) jsonApp.IntuneAppVendor  = v; if (app != null) app.IntuneAppVendor  = v; }, required: true);
                PkgTxtRow("App Version", jsonApp?.IntuneAppVersion ?? "", v => { if (jsonApp != null) jsonApp.IntuneAppVersion = v; if (app != null) app.IntuneAppVersion = v; });
                PkgRadioYesNo("Featured App",
                    jsonApp?.FeaturedApp ?? "No",
                    v => { if (jsonApp != null) jsonApp.FeaturedApp = v; if (app != null) app.FeaturedApp = v; },
                    enabled: true);
                var txDescription = PkgTxtRow("Description",      jsonApp?.Description     ?? "", v => { if (jsonApp != null) jsonApp.Description     = v; if (app != null) app.Description     = v; }, required: true);
                // Behaves like Mail Body: Enter inserts a new line and the box grows
                // to show every line. Local auto height overrides the style's fixed
                // height, and the row must size to content instead of the fixed 26.
                txDescription.AcceptsReturn = true;
                txDescription.TextWrapping = TextWrapping.Wrap;
                txDescription.Height = double.NaN;
                txDescription.MinHeight = 26;
                if (txDescription.Parent is Grid gDescription && gDescription.RowDefinitions.Count > 0)
                    gDescription.RowDefinitions[0].Height = GridLength.Auto;
                PkgTxtRow("Developer",        jsonApp?.Developer       ?? "", v => { if (jsonApp != null) jsonApp.Developer       = v; if (app != null) app.Developer       = v; });
                PkgTxtRow("Owner",            jsonApp?.Owner           ?? "", v => { if (jsonApp != null) jsonApp.Owner           = v; if (app != null) app.Owner           = v; });
                PkgTxtRow("Information URL",  jsonApp?.InformationURL  ?? "", v => { if (jsonApp != null) jsonApp.InformationURL  = v; if (app != null) app.InformationURL  = v; });
                PkgTxtRow("Privacy URL",      jsonApp?.PrivacyURL      ?? "", v => { if (jsonApp != null) jsonApp.PrivacyURL      = v; if (app != null) app.PrivacyURL      = v; });
                PkgTxtRow("Notes",            jsonApp?.Notes           ?? "", v => { if (jsonApp != null) jsonApp.Notes           = v; if (app != null) app.Notes           = v; });
                // Auto-populate the Logo path from Icon.png once the auto flow (or a manual Execute)
                // has written it into the per-app folder, and persist it so Publish and later
                // sessions use it. Only when the field is still empty - a hand-picked path wins.
                string logoInit = jsonApp?.Logo ?? "";
                if (string.IsNullOrWhiteSpace(logoInit))
                {
                    string logoTf = (jsonApp?.PackageTemplateFolder ?? app?.PackageTemplateFolder ?? "").Trim();
                    if (logoTf.Length > 0)
                    {
                        string logoCand = Path.Combine(logoTf, "Icon.png");
                        if (File.Exists(logoCand))
                        {
                            logoInit = logoCand;
                            if (jsonApp != null) jsonApp.Logo = logoCand;
                            if (app     != null) { app.Logo = logoCand; SaveAppJson(app); }
                        }
                    }
                }
                _pkgLogoBox = PkgTxtRowWithFileBrowse("Logo", logoInit, v => { if (jsonApp != null) jsonApp.Logo = v; if (app != null) app.Logo = v; });
                _pkgLogoBoxApp = app;

                // ── 2  Program tab ──────────────────────────────────────────
                // Initial display: when a PSADT template folder is set, show the PSADT
                // commands (Req 1); otherwise show the Source commands (Req 2). The
                // TextChanged handler above keeps these in sync as the folder changes.
                bool tplSetInit = !string.IsNullOrWhiteSpace(jsonApp?.PSADTTemplateFolder)
                               || !string.IsNullOrWhiteSpace(_selectedApp?.PSADTTemplateFolder);
                // The Intune Install/Uninstall Command is now an independent field. Show the app's
                // own InstallCommand/UninstallCommand when it has one (so an edit here survives a
                // reload); otherwise seed it from the PSADT default for a template app, or from the
                // Source command for a source app. The PSADT boxes above keep their own values.
                // No PSADT template (direct-install app): the Intune Install/Uninstall command IS the
                // source command that Create Package computed (e.g. vlc-...exe /S). AutoPackagePage
                // stored it on the shared selected-app; adopt and persist it over the .exe default so
                // this tab, the JSON and Publish all agree.
                if (!tplSetInit)
                {
                    var sa = AutoPackagePage.StaticSelectedApp;
                    if (sa != null && string.IsNullOrWhiteSpace(sa.PSADTTemplateFolder)
                        && string.Equals(sa.SourceAppName, _selectedApp?.SourceAppName, StringComparison.OrdinalIgnoreCase))
                    {
                        bool cmdChanged = false;
                        if (!string.IsNullOrWhiteSpace(sa.InstallCommand) && (jsonApp?.InstallCommand ?? "") != sa.InstallCommand)
                        { if (jsonApp != null) jsonApp.InstallCommand = sa.InstallCommand; if (_selectedApp != null) _selectedApp.InstallCommand = sa.InstallCommand; cmdChanged = true; }
                        if (!string.IsNullOrWhiteSpace(sa.UninstallCommand) && (jsonApp?.UninstallCommand ?? "") != sa.UninstallCommand)
                        { if (jsonApp != null) jsonApp.UninstallCommand = sa.UninstallCommand; if (_selectedApp != null) _selectedApp.UninstallCommand = sa.UninstallCommand; cmdChanged = true; }
                        if (cmdChanged && _selectedApp != null) SaveAppJson(_selectedApp);
                    }
                }
                string initInstallCmd = !string.IsNullOrWhiteSpace(jsonApp?.InstallCommand)      ? jsonApp!.InstallCommand
                                      : !string.IsNullOrWhiteSpace(_selectedApp?.InstallCommand) ? _selectedApp!.InstallCommand
                                      : (tplSetInit ? DefaultPsadtInstallCommand : (jsonApp?.SourceInstallCommand ?? ""));
                string initUninstallCmd = !string.IsNullOrWhiteSpace(jsonApp?.UninstallCommand)      ? jsonApp!.UninstallCommand
                                        : !string.IsNullOrWhiteSpace(_selectedApp?.UninstallCommand) ? _selectedApp!.UninstallCommand
                                        : (tplSetInit ? DefaultPsadtUninstallCommand : (jsonApp?.SourceUninstallCommand ?? ""));
                // Seed the in-memory objects with what is displayed so the defaults persist on the
                // next save - PSADT commands from their own values, Intune commands from theirs,
                // with no cross-assignment between the two.
                if (jsonApp != null)
                {
                    if (string.IsNullOrWhiteSpace(jsonApp.InstallCommand))   jsonApp.InstallCommand   = initInstallCmd;
                    if (string.IsNullOrWhiteSpace(jsonApp.UninstallCommand)) jsonApp.UninstallCommand = initUninstallCmd;
                    if (tplSetInit)
                    {
                        if (string.IsNullOrWhiteSpace(jsonApp.PSADTInstallCommand))   jsonApp.PSADTInstallCommand   = initPsadtInst;
                        if (string.IsNullOrWhiteSpace(jsonApp.PSADTUninstallCommand)) jsonApp.PSADTUninstallCommand = initPsadtUnin;
                    }
                }
                if (_selectedApp != null)
                {
                    if (string.IsNullOrWhiteSpace(_selectedApp.InstallCommand))   _selectedApp.InstallCommand   = initInstallCmd;
                    if (string.IsNullOrWhiteSpace(_selectedApp.UninstallCommand)) _selectedApp.UninstallCommand = initUninstallCmd;
                    if (tplSetInit)
                    {
                        if (string.IsNullOrWhiteSpace(_selectedApp.PSADTInstallCommand))   _selectedApp.PSADTInstallCommand   = initPsadtInst;
                        if (string.IsNullOrWhiteSpace(_selectedApp.PSADTUninstallCommand)) _selectedApp.PSADTUninstallCommand = initPsadtUnin;
                    }
                }
                txInstallCmd   = PkgTxtRow("Install Command",   initInstallCmd,   v =>
                {
                    // Independent of the PSADT Install Command: an edit here touches only the Intune
                    // final command. The init below reads InstallCommand back, so the edit survives a
                    // reload without being copied into the PSADT/Source fields.
                    if (jsonApp != null) jsonApp.InstallCommand = v;
                    if (app     != null) app.InstallCommand     = v;
                });
                txUninstallCmd = PkgTxtRow("Uninstall Command", initUninstallCmd, v =>
                {
                    // Independent of the PSADT Uninstall Command: an edit here touches only the Intune
                    // final command (read back by the init below, so the edit survives a reload).
                    if (jsonApp != null) jsonApp.UninstallCommand = v;
                    if (app     != null) app.UninstallCommand     = v;
                });
                PkgRadioYesNo("Allow Available Uninstall",
                    jsonApp?.AllowAvailableUninstall ?? "No",
                    v => { if (jsonApp != null) jsonApp.AllowAvailableUninstall = v; if (app != null) app.AllowAvailableUninstall = v; },
                    enabled: true);
                PkgRadioRow("Install Behaviour",
                    new[] { "System", "User" },
                    jsonApp?.InstallBehaviour ?? "System",
                    v => {
                        if (jsonApp != null) { jsonApp.InstallBehaviour = v; jsonApp.InstallBehavior = v; }
                        if (app    != null) { app.InstallBehaviour      = v; app.InstallBehavior     = v; }
                    });
                PkgTxtRow("Installation Time (mins)", jsonApp?.InstallationTime ?? "60", v => { if (jsonApp != null) jsonApp.InstallationTime = v; if (app != null) app.InstallationTime = v; });
                PkgComboRow("Device Restart Behaviour",
                    new[] { "Determine behaviour based on return codes", "No specific action", "App install may force a device restart", "SwiftPack will force a device restart" },
                    jsonApp?.DeviceRestartBehaviour ?? "Determine behaviour based on return codes",
                    v => { if (jsonApp != null) jsonApp.DeviceRestartBehaviour = v; if (app != null) app.DeviceRestartBehaviour = v; });

                // ── 3  Requirements tab ─────────────────────────────────────
                PkgComboRow("Minimum Operating System",
                    new[] { "Windows 10 1507","Windows 10 1511","Windows 10 1607","Windows 10 1703","Windows 10 1709","Windows 10 1803","Windows 10 1809","Windows 10 1903","Windows 10 1909","Windows 10 2004","Windows 10 20H2","Windows 10 21H1","Windows 10 21H2","Windows 10 22H2","Windows 11 21H2","Windows 11 22H2","Windows 11 23H2","Windows 11 24H2" },
                    jsonApp?.MinimumOperatingSystem ?? "Windows 10 21H2",
                    v => { if (jsonApp != null) jsonApp.MinimumOperatingSystem = v; if (app != null) app.MinimumOperatingSystem = v; });
                PkgRadioRow("OS Architecture",
                    new[] { "64Bit", "32Bit", "ARM64" },
                    jsonApp?.OperatingSystemArchitecture ?? "64Bit",
                    v => { if (jsonApp != null) jsonApp.OperatingSystemArchitecture = v; if (app != null) app.OperatingSystemArchitecture = v; });

                // ── Rules Format ─────────────────────────────────────────────
                var spRulesFormat = PkgRadioRow("Rules Format",
                    new[] { "Manual detection rules", "Custom script" },
                    string.IsNullOrWhiteSpace(jsonApp?.RulesFormat) ? "Manual detection rules" : jsonApp.RulesFormat,
                    v => { if (jsonApp != null) jsonApp.RulesFormat = v; if (app != null) app.RulesFormat = v; });

                // Helper: get the Grid container just added to PnlPackageInfo
                Grid LastPkgGrid() => (Grid)PnlPackageInfo.Children[PnlPackageInfo.Children.Count - 1];

                // ── 4  Detection tab ─────────────────────────────────────────
                // Detection Type — checkboxes for MSI, File, Registry (Manual); Script radio (Custom script)
                // Manual: checkbox row
                // Captured so the Download Preference row can drive them - see
                // _applyRuleTypeForPreference immediately below this block.
                CheckBox? chkDetMsi = null, chkDetReg = null;
                {
                    var gDT = new Grid { Margin = new Thickness(0, 0, 0, RGAP) };
                    gDT.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                    gDT.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    gDT.RowDefinitions.Add(new RowDefinition { Height = new GridLength(26) });
                    var lbDT = new TextBlock { FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    lbDT.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    lbDT.Inlines.Add(new System.Windows.Documents.Run("Rule Type"));
                    lbDT.Inlines.Add(new System.Windows.Documents.Run(" *") { Foreground = new SolidColorBrush(Color.FromRgb(0xE5, 0x39, 0x35)), FontWeight = FontWeights.Bold });
                    var spDT = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };

                    CheckBox MakePkgDetChk(string label, string curVal, Action<string> save, StackPanel parent)
                    {
                        var cb2 = new CheckBox { Content = label, FontSize = 11, IsChecked = curVal.Equals("Yes", StringComparison.OrdinalIgnoreCase), Margin = new Thickness(0, 0, 14, 0), Cursor = System.Windows.Input.Cursors.Hand };
                        cb2.SetResourceReference(CheckBox.ForegroundProperty, "TextPrimaryBrush");
                        cb2.SetResourceReference(FrameworkElement.StyleProperty, "ModernCheckBoxStyle");
                        cb2.Checked   += (_, _) => { save("Yes"); SaveJsonApp(); if (app != null) SaveApps(); };
                        cb2.Unchecked += (_, _) => { save("No");  SaveJsonApp(); if (app != null) SaveApps(); };
                        parent.Children.Add(cb2);
                        return cb2;
                    }
                    chkDetMsi = MakePkgDetChk("MSI",      jsonApp?.DetectionTypeMSI      ?? "No", v => { if (jsonApp != null) jsonApp.DetectionTypeMSI      = v; if (app != null) app.DetectionTypeMSI      = v;
                        // Detecting by MSI means detecting on its version, so ticking MSI turns
                        // MSI Version Check on. Only towards Yes and only on tick: unticking MSI
                        // leaves it alone, and a No the user sets afterwards stays No. The radio's
                        // own handler persists the value and refreshes the MSI Value row.
                        if (v.Equals("Yes", StringComparison.OrdinalIgnoreCase)) SyncPkgInfoRadio("MSI Version Check", "Yes"); }, spDT);
                                MakePkgDetChk("File",     jsonApp?.DetectionTypeFile     ?? "No", v => { if (jsonApp != null) jsonApp.DetectionTypeFile     = v; if (app != null) app.DetectionTypeFile     = v; }, spDT);
                    chkDetReg = MakePkgDetChk("Registry", jsonApp?.DetectionTypeRegistry ?? "No", v => { if (jsonApp != null) jsonApp.DetectionTypeRegistry = v; if (app != null) app.DetectionTypeRegistry = v; }, spDT);

                    Grid.SetColumn(lbDT, 0); Grid.SetColumn(spDT, 1);
                    gDT.Children.Add(lbDT); gDT.Children.Add(spDT);
                    PnlPackageInfo.Children.Add(gDT);
                }
                var gPkgDetType = LastPkgGrid();

                // ── Rule Type follows Download Preference ──────────────────────
                // An MSI download is detected by its product code; an EXE has no MSI to look up,
                // so it falls back to the ARP registry key. Wired to the Download Preference row
                // further up, which is built before this one, hence the forward-declared Action.
                //
                // ADDITIVE ONLY: this ticks the default for the new preference and never unticks
                // anything. Switching MSI -> EXE -> MSI must not throw away rule types the user
                // chose by hand, and there is no way to tell a box the user ticked from one this
                // rule ticked, so nothing is cleared. Flipping back and forth therefore leaves
                // both MSI and Registry ticked, which is a valid Intune multi-rule detection.
                //
                // Applied on CHANGE only, never on load: running it during a rebuild would tick
                // the default again every time the panel refreshed, undoing a deliberate untick.
                _applyRuleTypeForPreference = pref =>
                {
                    if (string.IsNullOrWhiteSpace(pref)) return;
                    bool isMsi   = pref.StartsWith("MSI", StringComparison.OrdinalIgnoreCase);
                    var  target  = isMsi ? chkDetMsi : chkDetReg;
                    // The Checked handler above persists to jsonApp, app and both files, so
                    // setting IsChecked is enough to save the change.
                    if (target != null && target.IsChecked != true) target.IsChecked = true;
                };

                // Script Detection Type row removed — Custom script mode no longer shows
                // a "Detection Type: Script" checkbox row. The Script sub-rows (Script File,
                // Enforce Signature Check, Run as 32-bit) are still shown/hidden by UpdatePkgDetVis.
                Grid? gPkgDetScript = null; // kept as null so UpdatePkgDetVis null-checks pass safely

                // Pre-declare detection grid refs so UpdatePkgDetVis can reference them
                // even though they are assigned after the PkgComboRow calls that wire the callback.
                Grid? gPkgMsiVc = null, gPkgMsiOp = null, gPkgMsiVal = null, gPkgMsiPc = null;
                Grid? gPkgFilePath = null, gPkgFileName = null, gPkgFileChk = null, gPkgFileOp = null, gPkgFileVal = null, gPkgFileValTxt = null, gPkgFile32 = null;
                // File Value textbox handle — declared here (before any lambda that may call
                // UpdatePkgDetVis → RefreshFileValueField) so it is definitely assigned.
                TextBox? txFileVal = null;
                Grid? gPkgRegKey  = null, gPkgRegVal  = null, gPkgRegChk  = null, gPkgRegOp  = null, gPkgReg32  = null, gPkgRegValue = null;
                Grid? gPkgScriptFile = null, gPkgScriptSig = null, gPkgScript32 = null;

                // ── Product Code — shown in Manual mode (below Detection Type) ──
                PkgTxtRow("Product Code",
                    jsonApp?.DetectionMsiProductCode ?? "",
                    v => { if (jsonApp != null) jsonApp.DetectionMsiProductCode = v;
                           if (app     != null) app.DetectionMsiProductCode     = v; });
                gPkgMsiPc = LastPkgGrid();

                // MSI sub-rows
                PkgRadioYesNo("MSI Version Check", jsonApp?.DetectionMsiVersionCheck ?? "No", v => { if (jsonApp != null) jsonApp.DetectionMsiVersionCheck = v; if (app != null) app.DetectionMsiVersionCheck = v; UpdatePkgDetVis(); }, enabled: true);
                gPkgMsiVc = LastPkgGrid();
                PkgComboRow("MSI Operator", new[] { "Equals","Not equal to","Greater than or equal to","Greater than","Less than or equal to","Less than" }, jsonApp?.DetectionMsiOperator ?? "Greater than or equal to", v => { if (jsonApp != null) jsonApp.DetectionMsiOperator = v; if (app != null) app.DetectionMsiOperator = v; });
                gPkgMsiOp = LastPkgGrid();
                PkgTxtRow("MSI Value", jsonApp?.DetectionMsiValue ?? "", v => { if (jsonApp != null) jsonApp.DetectionMsiValue = v; if (app != null) app.DetectionMsiValue = v; });
                gPkgMsiVal = LastPkgGrid();
                // File sub-rows
                PkgTxtRowWithFolderBrowse("File Folder Path",  jsonApp?.DetectionFileFolderPath ?? "", v => { if (jsonApp != null) jsonApp.DetectionFileFolderPath = v; if (app != null) app.DetectionFileFolderPath = v; });
                gPkgFilePath = LastPkgGrid();
                PkgTxtRow("File Name",         jsonApp?.DetectionFileFileName   ?? "", v => { if (jsonApp != null) jsonApp.DetectionFileFileName   = v; if (app != null) app.DetectionFileFileName   = v; });
                gPkgFileName = LastPkgGrid();
                PkgComboRow("File Detection Method", new[] { "File or folder exists","Date modified","Date created","Size in MB","String (Version)" }, jsonApp?.DetectionFileDetectionMethod ?? "String (Version)", v => { if (jsonApp != null) jsonApp.DetectionFileDetectionMethod = v; if (app != null) app.DetectionFileDetectionMethod = v; }, () => UpdatePkgDetVis());
                gPkgFileChk = LastPkgGrid();
                PkgComboRow("File Operator",   new[] { "Equals","Not equal to","Greater than or equal to","Greater than","Less than or equal to","Less than" }, jsonApp?.DetectionFileOperator ?? "Greater than or equal to", v => { if (jsonApp != null) jsonApp.DetectionFileOperator = v; if (app != null) app.DetectionFileOperator = v; });
                gPkgFileOp = LastPkgGrid();
                // File Value (plain text) — shown for String (Version) and Size in MB.
                // The stored field depends on the current File Detection Method:
                //   • "Size in MB"        → DetectionFileSizeValue (the on-disk size)
                //   • "String (Version)"  → DetectionFileValue     (the version)
                // This keeps the version out of the Size rule and vice-versa.
                bool CurFileMethodIsSize() =>
                    ((jsonApp?.DetectionFileDetectionMethod) ?? "String (Version)")
                        .Equals("Size in MB", StringComparison.OrdinalIgnoreCase);
                txFileVal = PkgTxtRow("File Value",
                    CurFileMethodIsSize()
                        ? (jsonApp?.DetectionFileSizeValue ?? "")
                        : (jsonApp?.DetectionFileValue ?? ""),
                    v =>
                    {
                        if (CurFileMethodIsSize())
                        {
                            if (jsonApp != null) jsonApp.DetectionFileSizeValue = v;
                            if (app     != null) app.DetectionFileSizeValue     = v;
                        }
                        else
                        {
                            if (jsonApp != null) jsonApp.DetectionFileValue = v;
                            if (app     != null) app.DetectionFileValue     = v;
                        }
                    });
                gPkgFileValTxt = LastPkgGrid();
                // Re-point the File Value textbox to the field that matches the
                // currently-selected method (called by UpdatePkgDetVis on change).
                void RefreshFileValueField()
                {
                    if (txFileVal == null) return;
                    txFileVal.Text = CurFileMethodIsSize()
                        ? (jsonApp?.DetectionFileSizeValue ?? "")
                        : (jsonApp?.DetectionFileValue ?? "");
                }

                // ── File Value — date + time fields (shown only for Date modified / Date created) ──
                {
                    var gFV = new Grid { Margin = new Thickness(0, 0, 0, RGAP) };
                    gFV.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(LWIDTH) });
                    gFV.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    gFV.RowDefinitions.Add(new RowDefinition { Height = new GridLength(28) });
                    var lbFV = new TextBlock { Text = "File Value", FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    lbFV.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    // Date + Time side by side
                    var spFV = new StackPanel { Orientation = Orientation.Horizontal };
                    var txDate = new TextBox { Text = jsonApp?.DetectionFileDateValue ?? "", FontSize = 11, Height = 28, Width = 130,
                        Style = tbStyle,
                        Padding = new Thickness(8, 0, 8, 0) };
                    txDate.SetResourceReference(TextBox.BackgroundProperty, "InputBgBrush");
                    txDate.SetResourceReference(TextBox.ForegroundProperty, "TextPrimaryBrush");
                    txDate.SetResourceReference(TextBox.BorderBrushProperty, "BorderMainBrush");
                    var lbDateHint = new TextBlock { Text = "MM/DD/YYYY", FontSize = 9, FontStyle = FontStyles.Italic,
                        Foreground = secFg, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(2, 0, 0, 0) };
                    // Show hint when empty
                    txDate.GotFocus  += (_, _) => { if (txDate.Text == "MM/DD/YYYY") txDate.Text = ""; };
                    txDate.LostFocus += (_, _) => { if (string.IsNullOrWhiteSpace(txDate.Text)) txDate.Text = ""; };
                    txDate.TextChanged += (_, _) =>
                    {
                        if (jsonApp != null) jsonApp.DetectionFileDateValue = txDate.Text.Trim();
                        if (app    != null) app.DetectionFileDateValue      = txDate.Text.Trim();
                        SaveJsonApp();
                    };
                    var txTime = new TextBox { Text = jsonApp?.DetectionFileTimeValue ?? "", FontSize = 11, Height = 28, Width = 110,
                        Style = tbStyle,
                        Padding = new Thickness(8, 0, 8, 0), Margin = new Thickness(6, 0, 0, 0) };
                    txTime.SetResourceReference(TextBox.BackgroundProperty, "InputBgBrush");
                    txTime.SetResourceReference(TextBox.ForegroundProperty, "TextPrimaryBrush");
                    txTime.SetResourceReference(TextBox.BorderBrushProperty, "BorderMainBrush");
                    txTime.GotFocus  += (_, _) => { if (txTime.Text == "12:00:00 AM") txTime.Text = ""; };
                    txTime.LostFocus += (_, _) => { if (string.IsNullOrWhiteSpace(txTime.Text)) txTime.Text = ""; };
                    txTime.TextChanged += (_, _) =>
                    {
                        if (jsonApp != null) jsonApp.DetectionFileTimeValue = txTime.Text.Trim();
                        if (app    != null) app.DetectionFileTimeValue      = txTime.Text.Trim();
                        SaveJsonApp();
                    };
                    spFV.Children.Add(txDate);
                    spFV.Children.Add(txTime);
                    Grid.SetColumn(lbFV, 0); Grid.SetColumn(spFV, 1);
                    gFV.Children.Add(lbFV); gFV.Children.Add(spFV);
                    PnlPackageInfo.Children.Add(gFV);
                    gPkgFileVal = gFV;
                }
                {
                    string f32v = jsonApp?.DetectionFile32Bit ?? "No";
                    bool f32on  = f32v.Equals("Yes", StringComparison.OrdinalIgnoreCase) ||
                                  f32v.Equals("Check", StringComparison.OrdinalIgnoreCase);
                    PkgRadioRow("File 32-bit App on 64-bit Clients", new[] { "Yes","No" },
                        f32on ? "Yes" : "No",
                        v => {
                            string val = v.Equals("Yes", StringComparison.OrdinalIgnoreCase) ? "Yes" : "No";
                            if (jsonApp != null) jsonApp.DetectionFile32Bit = val;
                            if (app != null) app.DetectionFile32Bit = val;
                        });
                }
                gPkgFile32 = LastPkgGrid();
                // Registry sub-rows
                PkgTxtRowWithRegBrowse("Registry Key Path",   jsonApp?.DetectionRegKeyPath   ?? "", v => { if (jsonApp != null) jsonApp.DetectionRegKeyPath   = v; if (app != null) app.DetectionRegKeyPath   = v; });
                gPkgRegKey = LastPkgGrid();
                PkgTxtRow("Registry Value Name",  jsonApp?.DetectionRegValueName ?? "", v => { if (jsonApp != null) jsonApp.DetectionRegValueName = v; if (app != null) app.DetectionRegValueName = v; });
                gPkgRegVal = LastPkgGrid();
                PkgComboRow("Registry Detection Method", new[] { "Key exists","Key does not exist","Value exists","Value does not exist","String comparison","Integer comparison","Version comparison" }, jsonApp?.DetectionRegDetectionMethod ?? "Version comparison", v => { if (jsonApp != null) jsonApp.DetectionRegDetectionMethod = v; if (app != null) app.DetectionRegDetectionMethod = v; }, () => UpdatePkgDetVis());
                gPkgRegChk = LastPkgGrid();
                PkgComboRow("Registry Operator",   new[] { "Equals","Not equal to","Greater than or equal to","Greater than","Less than or equal to","Less than" }, jsonApp?.DetectionRegOperator ?? "Greater than or equal to", v => { if (jsonApp != null) jsonApp.DetectionRegOperator = v; if (app != null) app.DetectionRegOperator = v; });
                gPkgRegOp = LastPkgGrid();
                PkgTxtRow("Registry Value", jsonApp?.DetectionRegistryValue ?? "", v => { if (jsonApp != null) jsonApp.DetectionRegistryValue = v; if (app != null) app.DetectionRegistryValue = v; });
                gPkgRegValue = LastPkgGrid();
                {
                    string r32v = jsonApp?.DetectionReg32Bit ?? "No";
                    bool r32on  = r32v.Equals("Yes", StringComparison.OrdinalIgnoreCase) ||
                                  r32v.Equals("Check", StringComparison.OrdinalIgnoreCase);
                    PkgRadioRow("Registry 32-bit App on 64-bit Clients", new[] { "Yes","No" },
                        r32on ? "Yes" : "No",
                        v => {
                            string val = v.Equals("Yes", StringComparison.OrdinalIgnoreCase) ? "Yes" : "No";
                            if (jsonApp != null) jsonApp.DetectionReg32Bit = val;
                            if (app != null) app.DetectionReg32Bit = val;
                        });
                }
                gPkgReg32 = LastPkgGrid();
                // Script sub-rows
                PkgTxtRowWithFileBrowse("Script File", jsonApp?.DetectionScriptFile ?? "", v => { if (jsonApp != null) jsonApp.DetectionScriptFile = v; if (app != null) app.DetectionScriptFile = v; });
                gPkgScriptFile = LastPkgGrid();
                PkgRadioYesNo("Enforce Script Signature Check", jsonApp?.DetectionScriptEnforceSignatureCheck ?? "No", v => { if (jsonApp != null) jsonApp.DetectionScriptEnforceSignatureCheck = v; if (app != null) app.DetectionScriptEnforceSignatureCheck = v; }, enabled: true);
                gPkgScriptSig = LastPkgGrid();
                PkgRadioYesNo("Run Script as 32-bit Process on 64-bit Client", jsonApp?.DetectionScriptRunAs32Bit ?? "No", v => { if (jsonApp != null) jsonApp.DetectionScriptRunAs32Bit = v; if (app != null) app.DetectionScriptRunAs32Bit = v; }, enabled: true);
                gPkgScript32 = LastPkgGrid();

                // Wire Rules Format → show/hide detection rows
                void UpdatePkgDetVis()
                {
                    // Same guard as UpdatePkgScheduleVisibility, same reason: this forces its rows
                    // Visible, and any invoker that runs while another tab is active (a radio or
                    // combo change replayed programmatically during a rebuild) would paint the
                    // detection rows over that tab. Switching to Intune settings re-invokes this
                    // via _pkgReapplyDetVis, so returning early elsewhere loses nothing.
                    if (_pkgActiveTab != "intune") return;
                    bool isManual  = spRulesFormat.Children.OfType<RadioButton>()
                        .FirstOrDefault(rb => rb.Content?.ToString() == "Manual detection rules")?.IsChecked == true;
                    var manVis    = isManual  ? Visibility.Visible : Visibility.Collapsed;
                    var scriptVis = !isManual ? Visibility.Visible : Visibility.Collapsed;

                    // Manual: checkbox detection type + MSI/File/Registry sub-rows
                    gPkgDetType.Visibility = manVis;
                    if (gPkgMsiPc  != null) gPkgMsiPc.Visibility  = manVis;
                    if (gPkgMsiVc  != null) gPkgMsiVc.Visibility  = manVis;
                    if (gPkgMsiOp  != null) gPkgMsiOp.Visibility  = manVis;
                    bool msiVerYes = (jsonApp?.DetectionMsiVersionCheck ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase);
                    if (gPkgMsiVal != null) gPkgMsiVal.Visibility = (isManual && msiVerYes) ? Visibility.Visible : Visibility.Collapsed;
                    if (gPkgFilePath != null) gPkgFilePath.Visibility = manVis;
                    if (gPkgFileName != null) gPkgFileName.Visibility = manVis;
                    if (gPkgFileChk  != null) gPkgFileChk.Visibility  = manVis;
                    if (gPkgFile32   != null) gPkgFile32.Visibility   = manVis;
                    if (gPkgRegKey   != null) gPkgRegKey.Visibility   = manVis;
                    if (gPkgRegVal   != null) gPkgRegVal.Visibility   = manVis;
                    if (gPkgRegChk   != null) gPkgRegChk.Visibility   = manVis;
                    if (gPkgReg32    != null) gPkgReg32.Visibility    = manVis;

                    // Hide File Operator when File Check Type = "File or folder exists"
                    string fileCheckType = jsonApp?.DetectionFileDetectionMethod ?? "String (Version)";
                    bool fileIsDate = fileCheckType.Equals("Date modified", StringComparison.OrdinalIgnoreCase) ||
                                     fileCheckType.Equals("Date created",  StringComparison.OrdinalIgnoreCase);
                    bool fileIsExists = fileCheckType.Equals("File or folder exists", StringComparison.OrdinalIgnoreCase);
                    bool fileOpVisible = isManual && !fileIsExists;
                    if (gPkgFileOp     != null) gPkgFileOp.Visibility     = fileOpVisible ? Visibility.Visible : Visibility.Collapsed;
                    // Plain text File Value: shown for String (Version) and Size in MB
                    if (gPkgFileValTxt != null) gPkgFileValTxt.Visibility = (isManual && !fileIsDate && !fileIsExists) ? Visibility.Visible : Visibility.Collapsed;
                    // Re-bind the File Value textbox to the field matching the current method
                    // (DetectionFileSizeValue for "Size in MB", DetectionFileValue otherwise).
                    if (isManual && !fileIsDate && !fileIsExists) RefreshFileValueField();
                    // Date/time File Value: shown only for Date modified / Date created
                    if (gPkgFileVal    != null) gPkgFileVal.Visibility    = (isManual && fileIsDate) ? Visibility.Visible : Visibility.Collapsed;

                    // Hide Registry Operator + Value for existence checks (Key/Value
                    // exists or does not exist) — they carry no operator/value, matching
                    // the Intune portal. Operator + Value show only for a value
                    // comparison (String / Integer / Version comparison).
                    string regCheckType = jsonApp?.DetectionRegDetectionMethod ?? "Version comparison";
                    bool regIsComparison = regCheckType.Equals("String comparison",  StringComparison.OrdinalIgnoreCase) ||
                                           regCheckType.Equals("Integer comparison", StringComparison.OrdinalIgnoreCase) ||
                                           regCheckType.Equals("Version comparison", StringComparison.OrdinalIgnoreCase);
                    bool regOpVisible  = isManual && regIsComparison;
                    bool regValVisible = isManual && regIsComparison;
                    if (gPkgRegOp    != null) gPkgRegOp.Visibility    = regOpVisible  ? Visibility.Visible : Visibility.Collapsed;
                    if (gPkgRegValue != null) gPkgRegValue.Visibility = regValVisible ? Visibility.Visible : Visibility.Collapsed;

                    // Custom script: Script checkbox + Script sub-rows
                    if (gPkgDetScript  != null) gPkgDetScript.Visibility  = scriptVis;
                    if (gPkgScriptFile != null) gPkgScriptFile.Visibility = scriptVis;
                    if (gPkgScriptSig  != null) gPkgScriptSig.Visibility  = scriptVis;
                    if (gPkgScript32   != null) gPkgScript32.Visibility   = scriptVis;
                }
                foreach (var rb in spRulesFormat.Children.OfType<RadioButton>())
                    rb.Checked += (_, _) => UpdatePkgDetVis();
                UpdatePkgDetVis();
                _pkgReapplyDetVis = UpdatePkgDetVis;

                // ── 7  Assignments tab: dynamic Dependencies + Supersedences ──
                // Point both entry objects at one shared list each, so edits / adds / deletes
                // reflect in jsonApp (per-app JSON) and app (in-memory list) together.
                var depList = jsonApp?.Dependencies ?? app?.Dependencies ?? new List<DependencyItem>();
                if (jsonApp != null) jsonApp.Dependencies = depList;
                if (app     != null) app.Dependencies     = depList;
                var supList = jsonApp?.Supersedences ?? app?.Supersedences ?? new List<SupersedenceItem>();
                if (jsonApp != null) jsonApp.Supersedences = supList;
                if (app     != null) app.Supersedences     = supList;

                void SaveDepSup() { SaveJsonApp(); if (app != null) SaveApps(); }

                void PkgCardField(Panel host, string label, string value, Action<string> onChanged)
                {
                    var g = new Grid { Margin = new Thickness(0, 0, 0, 4) };
                    g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(95) });
                    g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    var lbl = new TextBlock { Text = label, FontSize = 11, VerticalAlignment = VerticalAlignment.Center };
                    lbl.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    var tx = new TextBox { Text = value, FontSize = 11, Padding = new Thickness(6, 2, 6, 2), BorderBrush = pBdr, BorderThickness = new Thickness(1), Style = tbStyle };
                    tx.SetResourceReference(TextBox.ForegroundProperty, "TextPrimaryBrush");
                    tx.SetResourceReference(TextBox.BackgroundProperty, "InputBgBrush");
                    tx.TextChanged += (_, _) => { onChanged(tx.Text); SaveDepSup(); };
                    Grid.SetColumn(lbl, 0); Grid.SetColumn(tx, 1);
                    g.Children.Add(lbl); g.Children.Add(tx);
                    host.Children.Add(g);
                }
                void PkgCardRadio(Panel host, string label, string value, Action<string> onChanged)
                {
                    var g = new Grid { Margin = new Thickness(0, 0, 0, 2) };
                    g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(95) });
                    g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    var lbl = new TextBlock { Text = label, FontSize = 11, VerticalAlignment = VerticalAlignment.Center };
                    lbl.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    var sp = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                    string grp = Guid.NewGuid().ToString();
                    bool isYes = string.Equals(value, "Yes", StringComparison.OrdinalIgnoreCase);
                    var rbY = new RadioButton { Content = "Yes", GroupName = grp, FontSize = 11, IsChecked = isYes,  Margin = new Thickness(0, 0, 12, 0), Cursor = System.Windows.Input.Cursors.Hand };
                    var rbN = new RadioButton { Content = "No",  GroupName = grp, FontSize = 11, IsChecked = !isYes, Cursor = System.Windows.Input.Cursors.Hand };
                    rbY.SetResourceReference(RadioButton.ForegroundProperty, "TextPrimaryBrush");
                    rbN.SetResourceReference(RadioButton.ForegroundProperty, "TextPrimaryBrush");
                    rbY.Checked += (_, _) => { onChanged("Yes"); SaveDepSup(); };
                    rbN.Checked += (_, _) => { onChanged("No");  SaveDepSup(); };
                    sp.Children.Add(rbY); sp.Children.Add(rbN);
                    Grid.SetColumn(lbl, 0); Grid.SetColumn(sp, 1);
                    g.Children.Add(lbl); g.Children.Add(sp);
                    host.Children.Add(g);
                }
                void PkgCardHeader(string text)
                {
                    var h = new TextBlock { Text = text, FontSize = 11, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 6, 0, 4) };
                    h.SetResourceReference(TextBlock.ForegroundProperty, "TextPrimaryBrush");
                    PnlPackageInfo.Children.Add(h);
                }
                Border PkgCardShell(Panel host, string title, Action onDelete)
                {
                    var card = new Border { BorderBrush = pBdr, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(6), Padding = new Thickness(8), Margin = new Thickness(0, 0, 0, 6) };
                    var body = new StackPanel(); card.Child = body;
                    var hg = new Grid();
                    hg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    hg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                    var ht = new TextBlock { Text = title, FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                    ht.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
                    var del = new Button { Content = "✕", FontSize = 11, Width = 22, Height = 22, Background = Brushes.Transparent, BorderThickness = new Thickness(0), Cursor = System.Windows.Input.Cursors.Hand, ToolTip = "Remove" };
                    del.SetResourceReference(Button.ForegroundProperty, "TextSecondaryBrush");
                    del.Click += (_, _) => onDelete();
                    Grid.SetColumn(ht, 0); Grid.SetColumn(del, 1);
                    hg.Children.Add(ht); hg.Children.Add(del);
                    body.Children.Add(hg);
                    host.Children.Add(card);
                    return card;
                }
                Button PkgAddButton(string text)
                    => new Button { Content = text, FontSize = 11, Padding = new Thickness(10, 3, 10, 3), HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(0, 0, 0, 8), Cursor = System.Windows.Input.Cursors.Hand, Style = TryFindResource("ActionBtnStyle") as Style };

                // Dependencies
                PkgCardHeader("Dependencies");
                var depHost = new StackPanel();
                PnlPackageInfo.Children.Add(depHost);
                void RebuildDeps()
                {
                    depHost.Children.Clear();
                    for (int di = 0; di < depList.Count; di++)
                    {
                        var d = depList[di]; int idx = di;
                        var card = PkgCardShell(depHost, $"Dependency {idx + 1}",
                            () => { if (idx < depList.Count) { depList.RemoveAt(idx); SaveDepSup(); RebuildDeps(); } });
                        var body = (StackPanel)card.Child;
                        PkgCardField(body, "App Name", d.AppName, v => d.AppName = v);
                        PkgCardField(body, "App ID",   d.AppID,   v => d.AppID = v);
                        PkgCardRadio(body, "Auto Install", d.AutoInstall, v => d.AutoInstall = v);
                    }
                }
                RebuildDeps();
                var addDepBtn = PkgAddButton("＋  Add Dependency");
                addDepBtn.Click += async (_, _) =>
                {
                    var chosen = await IntunePickerDialogs.PickAppsAsync(Window.GetWindow(this),
                        "Add dependency", "Dependency Count", superseded: false);
                    if (chosen == null || chosen.Count == 0) return;
                    var seen = new HashSet<string>(depList.Select(d => (d.AppName ?? "").Trim())
                        .Where(s => s.Length > 0), StringComparer.OrdinalIgnoreCase);
                    foreach (var a in chosen)
                        if (seen.Add(a.Name)) depList.Add(new DependencyItem { AppName = a.Name, AppID = a.Id, AutoInstall = "Yes" });
                    SaveDepSup(); RebuildDeps();
                };
                PnlPackageInfo.Children.Add(addDepBtn);

                // Supersedences
                PkgCardHeader("Supersedences");
                // Mirrors the "Add supersedence automatically" checkbox in the Download Information
                // column. Blank counts as Yes so apps saved before this field existed keep the
                // behaviour they already had.
                PkgRadioYesNo("Add Supersedence Automatically",
                    string.IsNullOrWhiteSpace(jsonApp?.AddSupersedenceAutomatically) ? "Yes" : jsonApp!.AddSupersedenceAutomatically,
                    v =>
                    {
                        if (jsonApp != null) jsonApp.AddSupersedenceAutomatically = v;
                        if (app     != null) app.AddSupersedenceAutomatically     = v;
                        // The checkbox now follows the publish chain. PkgRadioYesNo hardcodes its
                        // row enabled, so this radio stays live even when the chain is off - mirror
                        // to the box only while it is enabled, or the column would show a
                        // checked-but-greyed box, which the cascade exists to prevent.
                        if (chkAutoSupersede.IsEnabled)
                            chkAutoSupersede.IsChecked = v.Equals("Yes", StringComparison.OrdinalIgnoreCase);
                    });
                var supHost = new StackPanel();
                PnlPackageInfo.Children.Add(supHost);
                void RebuildSups()
                {
                    supHost.Children.Clear();
                    for (int si = 0; si < supList.Count; si++)
                    {
                        var s = supList[si]; int idx = si;
                        var card = PkgCardShell(supHost, $"Supersedence {idx + 1}",
                            () => { if (idx < supList.Count) { supList.RemoveAt(idx); SaveDepSup(); RebuildSups(); } });
                        var body = (StackPanel)card.Child;
                        PkgCardField(body, "App Name", s.AppName, v => s.AppName = v);
                        PkgCardField(body, "App ID",   s.AppID,   v => s.AppID = v);
                        PkgCardRadio(body, "Uninstall Prev.", s.UninstallPreviousVersion, v => s.UninstallPreviousVersion = v);
                    }
                }
                RebuildSups();
                var addSupBtn = PkgAddButton("＋  Add Supersedence");
                addSupBtn.Click += async (_, _) =>
                {
                    var chosen = await IntunePickerDialogs.PickAppsAsync(Window.GetWindow(this),
                        "Add app to supersede", "Superseded Count", superseded: true);
                    if (chosen == null || chosen.Count == 0) return;
                    var seen = new HashSet<string>(supList.Select(s => (s.AppName ?? "").Trim())
                        .Where(s => s.Length > 0), StringComparer.OrdinalIgnoreCase);
                    foreach (var a in chosen)
                        if (seen.Add(a.Name)) supList.Add(new SupersedenceItem { AppName = a.Name, AppID = a.Id, UninstallPreviousVersion = "No" });
                    SaveDepSup(); RebuildSups();
                };
                PnlPackageInfo.Children.Add(addSupBtn);

                // ── Assignments ───────────────────────────────────────────────────────────────
                // A card list, exactly like Dependencies and Supersedences above - one card per group
                // with its own ✕. It used to be a single text box holding the names comma-separated,
                // which was inconsistent with the two sections directly above it and meant a stray
                // comma or a group name containing one quietly corrupted the list.
                //
                // The JSON is UNCHANGED: AssignmentsAvailable is still a comma-separated string. Only
                // the editing surface changed, so nothing downstream has to care.
                PkgCardHeader("Assignments");
                var grpHost = new StackPanel();
                PnlPackageInfo.Children.Add(grpHost);

                var grpList = new List<string>();
                foreach (var part in (jsonApp?.AssignmentsAvailable ?? "").Split(','))
                { var t = part.Trim(); if (t.Length > 0) grpList.Add(t); }

                void SaveGroups()
                {
                    string v = string.Join(", ", grpList);
                    if (jsonApp != null) jsonApp.AssignmentsAvailable = v;
                    if (app     != null) app.AssignmentsAvailable     = v;
                    SaveJsonApp();
                    if (app != null) SaveApps();
                }

                void RebuildGroups()
                {
                    grpHost.Children.Clear();
                    for (int gi = 0; gi < grpList.Count; gi++)
                    {
                        int idx = gi;
                        var card = PkgCardShell(grpHost, $"Group {idx + 1}",
                            () => { if (idx < grpList.Count) { grpList.RemoveAt(idx); SaveGroups(); RebuildGroups(); } });
                        var body = (StackPanel)card.Child;
                        PkgCardField(body, "Group Name", grpList[idx], v =>
                        {
                            if (idx < grpList.Count) { grpList[idx] = (v ?? "").Trim(); SaveGroups(); }
                        });
                    }
                }
                RebuildGroups();

                var addGrpBtn = PkgAddButton("＋  Add Group");
                addGrpBtn.Click += async (_, _) =>
                {
                    var chosen = await IntunePickerDialogs.PickGroupsAsync(Window.GetWindow(this), "Select groups");
                    if (chosen == null || chosen.Count == 0) return;
                    var seen = new HashSet<string>(grpList, StringComparer.OrdinalIgnoreCase);
                    foreach (var g in chosen)
                        if (!string.IsNullOrWhiteSpace(g.Name) && seen.Add(g.Name.Trim()))
                            grpList.Add(g.Name.Trim());
                    SaveGroups(); RebuildGroups();
                };
                PnlPackageInfo.Children.Add(addGrpBtn);

                // Communication section header — use PkgSection for consistent styling
                PkgSection("Communication");

                // "Send Mail to App Owner" is only active when the app is being published to
                // Intune (PublishToIntune = Yes).
                var spSendMail = PkgRadioYesNo("Send Mail to App Owner",
                    jsonApp?.SendMailToAppOwner ?? "No",
                    v => { if (jsonApp != null) jsonApp.SendMailToAppOwner = v; if (app != null) app.SendMailToAppOwner = v; chkSendMail.IsChecked = v.Equals("Yes", StringComparison.OrdinalIgnoreCase); },
                    enabled: effectivePublishToIntune);

                // App Owner Email moved to sit directly below Send Mail to App Owner.
                var txAppOwnerEmail = PkgTxtRow("App Owner Email",
                    jsonApp?.AppOwnerEmail ?? "",
                    v => { if (jsonApp != null) jsonApp.AppOwnerEmail = v; if (app != null) app.AppOwnerEmail = v; });

                // Per-app mail wording. Empty falls back to the global values in
                // AutoPackage.json (Settings window > Mail); tokens {AppName},
                // {AppVersion}, {AppVendor} and {PackageName} are supported.
                var txMailSubject = PkgTxtRow("Mail Subject",
                    jsonApp?.MailSubject ?? "",
                    v => { if (jsonApp != null) jsonApp.MailSubject = v; if (app != null) app.MailSubject = v; });
                var txMailBody = PkgTxtRow("Mail Body",
                    jsonApp?.MailBody ?? "",
                    v => { if (jsonApp != null) jsonApp.MailBody = v; if (app != null) app.MailBody = v; });
                // Behaves like the Settings window's Mail Body: starts one row tall,
                // Enter inserts a new line and the box grows to show every line.
                txMailBody.AcceptsReturn = true;
                txMailBody.TextWrapping = TextWrapping.Wrap;
                // Local auto height overrides any fixed Height in ModernTextBoxStyle,
                // and the row itself must size to content instead of the fixed 26.
                txMailBody.Height = double.NaN;
                txMailBody.MinHeight = 26;
                if (txMailBody.Parent is Grid gMailBody && gMailBody.RowDefinitions.Count > 0)
                    gMailBody.RowDefinitions[0].Height = GridLength.Auto;

                // App Owner Email is only editable when Send Mail to App Owner = Yes.
                {
                    var smY = spSendMail.Children.OfType<RadioButton>().FirstOrDefault(rb => (rb.Content as string) == "Yes");
                    var smN = spSendMail.Children.OfType<RadioButton>().FirstOrDefault(rb => (rb.Content as string) == "No");
                    void SyncOwnerEmail()
                    {
                        bool on = smY?.IsChecked == true;
                        txAppOwnerEmail.IsEnabled = on;
                        txMailSubject.IsEnabled   = on;
                        txMailBody.IsEnabled      = on;
                    }
                    if (smY != null) smY.Checked += (_, _) => SyncOwnerEmail();
                    if (smN != null) smN.Checked += (_, _) => SyncOwnerEmail();
                    SyncOwnerEmail();
                }

                // App Owner Email must be a valid address; invalid entries get a red border.
                {
                    var okBorder = txAppOwnerEmail.BorderBrush;
                    void ValidateOwnerEmail()
                    {
                        string em = txAppOwnerEmail.Text.Trim();
                        bool valid = em.Length == 0 || System.Text.RegularExpressions.Regex.IsMatch(em, @"^[^@\s]+@[^@\s]+\.[^@\s]+$");
                        txAppOwnerEmail.BorderBrush = valid ? okBorder : System.Windows.Media.Brushes.Red;
                        txAppOwnerEmail.ToolTip     = valid ? null : "Enter a valid email address (e.g. name@company.com).";
                    }
                    txAppOwnerEmail.TextChanged += (_, _) => ValidateOwnerEmail();
                    ValidateOwnerEmail();
                }

                PnlPackageInfo.Children.Add(new Border { Height = 8 }); // bottom spacer
                SyncCreatePkgGating(); // initial gating: after all rows (incl. Intune & Communication) exist

                // Group the sections just built into the three Package Information tabs and show the
                // one the user last had open. Every row stays a child of PnlPackageInfo; only its
                // Visibility is toggled, so the existing label/index walkers are unaffected.
                RebuildPackageInfoTabs();
            }


            PnlAppInfo.Children.Add(headerGrid);

            // Download links
            // Locked preference → render only the matching download button so a
            // per-variant entry (e.g. "Smekal FileCompare x64 MSI") offers exactly
            // its configured file. Defensive: if nothing matches, show everything.
            var renderLinks = info.Links;
            if ((_selectedApp?.LockDownloadPreference ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase) &&
                string.Equals(info.SourceAppName, _selectedApp?.SourceAppName, StringComparison.OrdinalIgnoreCase))
            {
                var matched = info.Links.Where(l =>
                    $"{l.Type}_{l.Arch}".Equals(_selectedApp?.DownloadPreference ?? "",
                        StringComparison.OrdinalIgnoreCase)).ToList();
                if (matched.Count > 0) renderLinks = matched;
            }
            if (renderLinks.Count > 0)
            {
                PnlAppInfo.Children.Add(new TextBlock { Text = "Download Links", FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg, Margin = new Thickness(0, 0, 0, 6) });

                foreach (var typeGroup in renderLinks.GroupBy(l => l.Type).OrderBy(g => g.Key == "MSI" ? 0 : 1))
                {
                    // x64 → x86 → ARM64; buttons are laid out two per line with equal
                    // widths. An odd leftover button (e.g. EXE ARM64) gets a line of its
                    // own spanning the full row width, so icon + label are never clipped.
                    var rowCards = new List<Border>();

                foreach (var link in typeGroup.OrderBy(l => l.Arch == "x64" ? 0 : l.Arch == "x86" ? 1 : 2))
                    {
                        string capUrl   = link.Url;
                        string capLabel = link.Label;

                        Brush cardBg = link.Arch == "x64"   ? new SolidColorBrush(Color.FromArgb(0x18, 0x6C, 0x63, 0xFF))
                                     : link.Arch == "x86"   ? new SolidColorBrush(Color.FromArgb(0x18, 0xFF, 0x87, 0x00))
                                     :                         new SolidColorBrush(Color.FromArgb(0x18, 0x00, 0x99, 0xFF));
                        Brush cardFg = link.Arch == "x64"   ? accent
                                     : link.Arch == "x86"   ? new SolidColorBrush(Color.FromRgb(0xB8, 0x5C, 0x00))
                                     :                         new SolidColorBrush(Color.FromRgb(0x00, 0x77, 0xCC));

                        // Highlight the button whose label matches the current DownloadPreference
                        // e.g. DownloadPreference "MSI_x64" matches link.Label "MSI x64"
                        string prefNorm  = (_selectedApp?.DownloadPreference ?? "").Replace("_", " ").Trim();
                        bool   isPref    = capLabel.Equals(prefNorm, StringComparison.OrdinalIgnoreCase);

                        var card = new Border
                        {
                            Background      = isPref ? cardFg : cardBg,
                            CornerRadius    = new CornerRadius(6),
                            BorderBrush     = cardFg,
                            BorderThickness = isPref ? new Thickness(2) : new Thickness(1),
                            Padding         = new Thickness(10, 4, 10, 4),
                            // Bottom margin gives wrapped rows (e.g. EXE ARM64) the same
                            // vertical gap the type-rows have between each other.
                            Margin          = new Thickness(0, 0, 6, 4),
                            Cursor          = System.Windows.Input.Cursors.Hand,
                            ToolTip         = capUrl,
                            // Width comes from the UniformGrid cell — all buttons equal,
                            // two per row, regardless of label length (x64 / x86 / ARM64).
                        };
                        var cs = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center };
                        Brush btnTextFg = isPref ? new SolidColorBrush(Colors.White) : cardFg;
                        cs.Children.Add(new TextBlock { Text = "⬇  ", FontSize = 11, VerticalAlignment = VerticalAlignment.Center, Foreground = btnTextFg });
                        cs.Children.Add(new TextBlock { Text = capLabel, FontSize = 11, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Center, Foreground = btnTextFg });
                        card.Child = cs;
                        string capType  = link.Type; // "EXE" or "MSI"
                        card.MouseLeftButtonUp += (_, _) =>
                        {
                            // Req 4: while locked, ignore everything EXCEPT a Download
                            // Preference change (handled below). A click on a *different*
                            // download button only switches the preference; it must not
                            // start a second download or reset anything mid-flow.
                            bool wasLocked = _downloadColumnsLocked;

                            string appName = info.SourceAppName;
                            string version = info.Version;
                            string vendor  = info.SourceAppVendor;

                            // Req 5 + Req 4: update DownloadPreference and persist ONLY that
                            // value to the per-app JSON — never re-write any other variable.
                            string newPref = capLabel.Replace(" ", "_"); // e.g. "EXE x64" → "EXE_x64"
                            if (_selectedApp != null && _selectedApp.DownloadPreference != newPref)
                            {
                                _selectedApp.DownloadPreference = newPref;
                                SaveDownloadPreferenceOnly(_selectedApp, newPref); // Req 5: only this field
                                SyncPkgInfoRadio("Download Preference", newPref);
                                // Re-render to re-highlight the selected button. Capture the
                                // CURRENT info object directly (do NOT read the mutable
                                // _lastInfo field later — it may have changed/cleared and
                                // RenderInfoPanel dereferences it → NullReferenceException).
                                var infoForRender = _lastInfo ?? info;
                                if (infoForRender != null)
                                    Dispatcher.BeginInvoke(new Action(() => RenderInfoPanel(infoForRender)),
                                        System.Windows.Threading.DispatcherPriority.Background);
                            }

                            // A download-button click changes ONLY the Download Preference (and the
                            // button highlight); it deliberately does NOT touch the Rule Type
                            // checkboxes. Whatever the user had checked before the download stays as-is.
                            // The Rule Type follows the Download Preference only when the user changes
                            // that radio by hand (see the Download Preference row), never on a download.

                            // Req 4: if a download/flow is already running, a button click is
                            // treated ONLY as a Download Preference change (done above). Do not
                            // start another download or reset tabs while locked.
                            if (wasLocked) return;

                            // ── Pre-flight required-field check (mirrors the Add App dialog) ──
                            // Blocks the download until the fields marked with * are filled.
                            // Always: Source App Vendor, Source App Version, API Type.
                            // If Create package is checked: App Vendor / App Name / App Version.
                            // If Publish is checked: the Intune fields + a detection Rule Type.
                            if (_selectedApp != null)
                            {
                                var dlMissing = new List<string>();
                                if (string.IsNullOrWhiteSpace(_selectedApp.SourceAppVendor))  dlMissing.Add("Source App Vendor");
                                if (string.IsNullOrWhiteSpace(_selectedApp.SourceAppName))    dlMissing.Add("Source App Name");
                                if (string.IsNullOrWhiteSpace(_selectedApp.SourceAppVersion)) dlMissing.Add("Source App Version");
                                if (string.IsNullOrWhiteSpace(_selectedApp.ApiType))          dlMissing.Add("API Type");
                                if (string.Equals(_selectedApp.CreatePackage, "Yes", StringComparison.OrdinalIgnoreCase))
                                {
                                    if (string.IsNullOrWhiteSpace(_selectedApp.AppVendor))  dlMissing.Add("App Vendor");
                                    if (string.IsNullOrWhiteSpace(_selectedApp.AppName))    dlMissing.Add("App Name");
                                    if (string.IsNullOrWhiteSpace(_selectedApp.AppVersion)) dlMissing.Add("App Version");
                                }
                                bool dlPublishOn = string.Equals(_selectedApp.PublishSettings, "Yes", StringComparison.OrdinalIgnoreCase)
                                                || string.Equals(_selectedApp.PublishToIntune, "Yes", StringComparison.OrdinalIgnoreCase);
                                if (dlPublishOn)
                                {
                                    if (string.IsNullOrWhiteSpace(_selectedApp.IntuneAppName))   dlMissing.Add("App Name (Intune)");
                                    if (string.IsNullOrWhiteSpace(_selectedApp.IntuneAppVendor)) dlMissing.Add("App Vendor (Intune)");
                                    if (string.IsNullOrWhiteSpace(_selectedApp.Description))     dlMissing.Add("Description");
                                    bool dlManualDet = string.IsNullOrWhiteSpace(_selectedApp.RulesFormat)
                                                       || string.Equals(_selectedApp.RulesFormat, "Manual detection rules", StringComparison.OrdinalIgnoreCase);
                                    bool dlAnyRuleType = string.Equals(_selectedApp.DetectionTypeMSI, "Yes", StringComparison.OrdinalIgnoreCase)
                                                      || string.Equals(_selectedApp.DetectionTypeFile, "Yes", StringComparison.OrdinalIgnoreCase)
                                                      || string.Equals(_selectedApp.DetectionTypeRegistry, "Yes", StringComparison.OrdinalIgnoreCase);
                                    if (dlManualDet && !dlAnyRuleType) dlMissing.Add("Rule Type");
                                }
                                // "Send mail to app owner" is on - App Owner Email is required to send it.
                                if (string.Equals(_selectedApp.SendMailToAppOwner, "Yes", StringComparison.OrdinalIgnoreCase) &&
                                    string.IsNullOrWhiteSpace(_selectedApp.AppOwnerEmail))
                                {
                                    ShowStyledInfoDialog(Window.GetWindow(this)!, "Source Download - App Owner Email", "⚠️", new[]
                                    {
                                        ("App Owner Email", "\"Send mail to app owner\" is checked, so enter the App Owner Email in the Package Information column before downloading."),
                                    });
                                    return;
                                }
                                if (dlMissing.Count > 0)
                                {
                                    ShowStyledInfoDialog(Window.GetWindow(this)!, "Source Download - Required Fields", "⚠️", new[]
                                    {
                                        ("Required", "Please fill the fields marked with * before downloading:"),
                                        ("Missing",  string.Join(", ", dlMissing)),
                                    });
                                    return;
                                }
                            }

                            _lastTriggeredDownloadType = capType;

                            // Req 3: clear previous downstream data before a new download so
                            // nothing stale from the prior run survives. ResetAllTabs() clears
                            // the Package / Execute / Intunewin / Publish tab state (the cache
                            // and in-memory data that belongs to the previous run).
                            //
                            // NOTE: we intentionally do NOT clear _liveVersionCache or null
                            // _lastInfo here — those drive the "⬆ New" badges and the current
                            // download-info panel, and clearing them caused a crash in
                            // RenderInfoPanel and wiped badges for unrelated apps.
                            //
                            // Use _mainWindow.AutoPackagePage (direct typed reference) as the
                            // primary path — FindAncestorAutoPackagePage() walks the visual tree
                            // through a WPF Frame, which is unreliable and can return null even
                            // when the page is fully loaded.
                            try
                            {
                                _mainWindow ??= Window.GetWindow(this) as IAutoPackageHost;
                                var autoPage = _mainWindow?.AutoPackagePage
                                               ?? FindAncestorAutoPackagePage();
                                autoPage?.ResetAllTabs();
                            }
                            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }

                            // Req 3: reclaim freed managed memory from the reset tabs.
                            try { GC.Collect(); GC.WaitForPendingFinalizers(); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }

                            // Req 4: lock the Download-Information and Package-Information
                            // columns until the flow completes. Only the Cancel "X" stays
                            // usable; the Download Preference row is locked too.
                            _autoFlowChainPending = false; // re-armed by the completion block if a chain runs
                            LockDownloadAndPackageColumns();

                            UpdatePackageInfoSilentParams();
                            _activeDownloadTask = DownloadFileAsync(capUrl, capLabel, appName, version, vendor);
                        };
                        rowCards.Add(card);
                    }
                    for (int ci = 0; ci < rowCards.Count; ci += 2)
                    {
                        bool pair = ci + 1 < rowCards.Count;
                        var line = new System.Windows.Controls.Primitives.UniformGrid { Columns = pair ? 2 : 1 };
                        line.Children.Add(rowCards[ci]);
                        if (pair) line.Children.Add(rowCards[ci + 1]);
                        PnlAppInfo.Children.Add(line);
                    }
                }
            }
            else
            {
                PnlAppInfo.Children.Add(new TextBlock { Text = "Please check the Download Source for correct details and check whether the internet is enabled, then close the app and reopen.", FontSize = 11, Foreground = mutFg, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 14) });
            }

            // Open download page button
            if (!string.IsNullOrWhiteSpace(info.PageUrl))
            {
                string capPage = info.PageUrl;
                var pageBtn = new Button { Content = "🌐  Open Download Page", Style = sec, Height = 28, FontSize = 11, HorizontalAlignment = HorizontalAlignment.Left, ToolTip = capPage };
                pageBtn.Click += (_, _) =>
                {
                    try { Process.Start(new ProcessStartInfo(capPage) { UseShellExecute = true }); }
                    catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                };
                PnlAppInfo.Children.Add(pageBtn);
            }

            // ── Checkboxes below Open Download Page ───────────────────────
            // This array, NOT chkPanel above, is what puts the boxes on screen: each one is
            // re-parented out of chkPanel into chkSection here. Anything added to chkPanel and
            // left out of this list is built, wired and invisible.
            var chkSection = new StackPanel { Margin = new Thickness(0, 4, 0, 0) };
            foreach (var chk in new[] { chkInstall, chkUninstall, chkPC, chkInstallPkg, chkUninstallPkg, chkCreateIntunewin, chkPublishToIntune, chkPublishToIntune2, chkAutoSupersede, chkSendMail })
            {
                if (LogicalTreeHelper.GetParent(chk) is System.Windows.Controls.Panel op) op.Children.Remove(chk);
                chk.Margin    = new Thickness(0, 1, 0, 1);
                chk.FontSize  = 11;
                chkSection.Children.Add(chk);
            }
            PnlAppInfo.Children.Add(chkSection);

            // Req 4: if a download/flow is currently running, the panel was just
            // rebuilt with fresh (interactive) controls — re-apply the lock so the
            // Download-Information and Package-Information columns stay disabled
            // (only the Cancel "X" remains usable).
            if (_downloadColumnsLocked)
                LockDownloadAndPackageColumns();

            // If a silent Install/Uninstall phase is currently running, the panel was just
            // rebuilt with a fresh checkbox — re-apply the highlight to the new instance so
            // it stays lit for the whole phase (the old reference was orphaned by the rebuild).
            if (_activeSilentPhase != null)
            {
                HighlightSilentLabel(FindSilentCheckBox(
                    _activeSilentPhase == "uninstall" ? "Uninstall source silently"
                                                      : "Install source silently"));
                if (TopSilentProgressBar != null)
                {
                    TopSilentProgressBar.IsIndeterminate = true;
                    TopSilentProgressBar.Visibility      = Visibility.Visible;
                }
                if (FindName("BtnCancelSilent") is Button cb) cb.Visibility = Visibility.Visible;
            }

            // Re-surface a pending package-error notice (if any) for this app. The panel was
            // just cleared and rebuilt above, so this appends it below the action checklist.
            RenderPackageErrorNotice();
        }

        // Package Information section tabs.
        // The Package Information column groups its sections under three tabs so the user picks a
        // section instead of scrolling one long list:
        //   Application settings = App Identity, Download Source, Download Schedule, Silent Parameters
        //   Package settings = Package Settings
        //   Intune settings  = Intune & Deployment, Communication
        // Every row stays a child of PnlPackageInfo (so the label/index walkers elsewhere keep
        // working); switching tabs only flips each row's Visibility.
        private string _pkgActiveTab = "app";
        private readonly Dictionary<string, List<UIElement>> _pkgTabRows = new()
        {
            ["app"]    = new List<UIElement>(),
            ["pkg"]    = new List<UIElement>(),
            ["intune"] = new List<UIElement>(),
            ["email"]  = new List<UIElement>(),
        };
        private Button? _pkgTabBtnApp, _pkgTabBtnPkg, _pkgTabBtnIntune, _pkgTabBtnEmail;
        // Re-applies the Rules Format show/hide rules after a tab switch, because
        // ShowPackageInfoTab makes EVERY row of the active tab visible and would
        // otherwise clobber the detection-row visibility (script rows showing in
        // Manual mode and vice versa).
        private Action? _pkgReapplyDetVis;
        // Same trap for the Download Schedule rows on the Application settings tab:
        // the tab sweep shows them all even when Auto Download Source is No.
        private Action? _pkgReapplyScheduleVis;
        // And again for Create MST / Remove Desktop Shortcut on the Package settings tab,
        // which belong to MSI downloads only. Without this the sweep shows both rows for an
        // EXE app the moment that tab is opened, however the preference is set.
        private Action? _pkgReapplyMstVis;

        // Section title (as passed to PkgSection) maps to a tab key. Anything not listed rides with
        // Application settings. Communication sits under Intune settings because Send Mail to App Owner is
        // part of the Intune publish step (it is gated on Publish to Intune = Yes).
        private static string PkgTabForSection(string section) => section switch
        {
            "Package Settings"    => "pkg",
            "Intune & Deployment" => "intune",
            "Communication"       => "email",
            _                     => "app",
        };

        // Built once. The three buttons live in the XAML PkgTabStripHost, outside PnlPackageInfo, so
        // they survive the panel rebuild RenderInfoPanel does on every app selection.
        private void BuildPackageInfoTabStrip()
        {
            if (PkgTabStripHost == null || PkgTabStripHost.Child != null) return;

            var strip = new System.Windows.Controls.Primitives.UniformGrid { Rows = 1, Columns = 4 };

            Button MakeTab(string text, string key)
            {
                var b = new Button
                {
                    Content = text, FontSize = 11, Height = 26,
                    Margin = new Thickness(2, 0, 2, 0), Cursor = Cursors.Hand,
                    BorderThickness = new Thickness(1), Tag = key,
                    Template = RoundedTabButtonTemplate(),
                };
                b.Click += (_, _) => { ShowPackageInfoTab(key); SvPackage?.ScrollToTop(); };
                return b;
            }

            _pkgTabBtnApp    = MakeTab("Application settings",  "app");
            _pkgTabBtnPkg    = MakeTab("Package settings", "pkg");
            _pkgTabBtnIntune = MakeTab("Intune settings",  "intune");
            _pkgTabBtnEmail  = MakeTab("Email settings",   "email");
            strip.Children.Add(_pkgTabBtnApp);
            strip.Children.Add(_pkgTabBtnPkg);
            strip.Children.Add(_pkgTabBtnIntune);
            strip.Children.Add(_pkgTabBtnEmail);
            PkgTabStripHost.Child = strip;
        }

        // A rounded button template whose Background and BorderBrush follow the button itself, so the
        // active and inactive colours can be swapped just by setting those brushes (see
        // ShowPackageInfoTab). The text colour comes from the button's Foreground by inheritance, the
        // same way the other code-built buttons on this page work.
        private static ControlTemplate RoundedTabButtonTemplate()
        {
            var tpl = new ControlTemplate(typeof(Button));
            var bd  = new FrameworkElementFactory(typeof(Border));
            bd.SetValue(Border.CornerRadiusProperty, new CornerRadius(5));
            bd.SetValue(Border.BorderThicknessProperty, new Thickness(1));
            bd.SetBinding(Border.BackgroundProperty,
                new System.Windows.Data.Binding(nameof(Control.Background))
                { RelativeSource = new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent) });
            bd.SetBinding(Border.BorderBrushProperty,
                new System.Windows.Data.Binding(nameof(Control.BorderBrush))
                { RelativeSource = new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent) });
            var cp = new FrameworkElementFactory(typeof(ContentPresenter));
            cp.SetValue(FrameworkElement.MarginProperty, new Thickness(4, 0, 4, 0));
            cp.SetValue(ContentPresenter.HorizontalAlignmentProperty, HorizontalAlignment.Center);
            cp.SetValue(ContentPresenter.VerticalAlignmentProperty,   VerticalAlignment.Center);
            bd.AppendChild(cp);
            tpl.VisualTree = bd;
            var hov = new Trigger { Property = UIElement.IsMouseOverProperty, Value = true };
            hov.Setters.Add(new Setter(UIElement.OpacityProperty, 0.85));
            tpl.Triggers.Add(hov);
            return tpl;
        }

        // Re-buckets the freshly built PnlPackageInfo into the three tabs by walking its children in
        // order and switching bucket at each PkgSection header, then re-applies the active tab. Called
        // at the end of the RenderInfoPanel build.
        private void RebuildPackageInfoTabs()
        {
            if (PnlPackageInfo == null) return;
            BuildPackageInfoTabStrip();

            foreach (var bucket in _pkgTabRows.Values) bucket.Clear();

            const string marker = "PKGSECTION:";
            string cur = "app";   // any rows before the first section header ride with Application settings
            foreach (UIElement child in PnlPackageInfo.Children)
            {
                if (child is FrameworkElement fe && fe.Tag is string t && t.StartsWith(marker, StringComparison.Ordinal))
                    cur = PkgTabForSection(t.Substring(marker.Length));
                if (_pkgTabRows.TryGetValue(cur, out var bucket)) bucket.Add(child);
            }

            if (PkgTabStripHost != null) PkgTabStripHost.Visibility = Visibility.Visible;
            ShowPackageInfoTab(_pkgActiveTab);
        }

        // Shows the rows of the chosen tab and hides the rest, and restyles the tab buttons so the
        // active one reads as selected. Scroll position is left alone (the button Click resets it).
        private void ShowPackageInfoTab(string tab)
        {
            if (!_pkgTabRows.ContainsKey(tab)) tab = "app";
            _pkgActiveTab = tab;

            foreach (var kv in _pkgTabRows)
            {
                var vis = kv.Key == tab ? Visibility.Visible : Visibility.Collapsed;
                foreach (var el in kv.Value) el.Visibility = vis;
            }
            // The sweep above just made every row of the active tab visible; re-apply
            // the conditional-visibility rules so only the rows for the current
            // selections stay shown.
            if (tab == "intune") _pkgReapplyDetVis?.Invoke();
            if (tab == "app")    _pkgReapplyScheduleVis?.Invoke();
            if (tab == "pkg")    _pkgReapplyMstVis?.Invoke();

            void StyleTab(Button? b)
            {
                if (b == null) return;
                if ((b.Tag as string) == tab)
                {
                    b.SetResourceReference(Control.BackgroundProperty,  "AccentBlueBrush");
                    b.SetResourceReference(Control.BorderBrushProperty, "AccentBlueBrush");
                    b.Foreground = Brushes.White;
                    b.FontWeight = FontWeights.Bold;
                }
                else
                {
                    b.SetResourceReference(Control.BackgroundProperty,  "InputBgBrush");
                    b.SetResourceReference(Control.BorderBrushProperty, "BorderMainBrush");
                    b.SetResourceReference(Control.ForegroundProperty,  "TextSecondaryBrush");
                    b.FontWeight = FontWeights.SemiBold;
                }
            }
            StyleTab(_pkgTabBtnApp);
            StyleTab(_pkgTabBtnPkg);
            StyleTab(_pkgTabBtnIntune);
            StyleTab(_pkgTabBtnEmail);
        }

        // ── Search ─────────────────────────────────────────────────────────
        private void TxtSearch_TextChanged(object sender, TextChangedEventArgs e)
        {
            _searchText     = TxtSearch.Text;
            _selectedVendor = "";
            TxtSearchPlaceholder.Visibility = string.IsNullOrEmpty(_searchText) ? Visibility.Visible : Visibility.Collapsed;
            if (BtnClearSearch != null)
                BtnClearSearch.Visibility = string.IsNullOrEmpty(_searchText) ? Visibility.Collapsed : Visibility.Visible;
            RenderVendors();
            RenderCards();
            var firstApp = _allApps
                .Where(a => _activeCategory == "All" || a.Category == _activeCategory)
                .Where(a => string.IsNullOrWhiteSpace(_searchText)
                         || a.SourceAppName.Contains(_searchText, StringComparison.OrdinalIgnoreCase)
                         || a.SourceAppVendor.Contains(_searchText, StringComparison.OrdinalIgnoreCase))
                .OrderBy(a => a.SourceAppVendor).ThenBy(a => a.SourceAppName).FirstOrDefault();
            if (firstApp != null) SelectApp(firstApp);
        }

        private void BtnClearSearch_Click(object sender, RoutedEventArgs e)
        {
            TxtSearch.Text = "";
            TxtSearch.Focus();
        }

        private void BtnChipAll_Click(object sender, RoutedEventArgs e)
        {
            _activeCategory = "All";
            _selectedVendor = "";
            _selectedApp    = null;
            if (BtnChipAll != null)
                BtnChipAll.Style = (Style)(TryFindResource("ChipActiveStyle") ?? new Style());
            foreach (Button c in PnlCategories.Children)
                c.Style = (Style)(TryFindResource("ChipStyle") ?? new Style());
            RenderVendors();
            RenderCards();
            var firstApp = _allApps.OrderBy(a => a.SourceAppVendor).ThenBy(a => a.SourceAppName).FirstOrDefault();
            if (firstApp != null) SelectApp(firstApp);
        }

        // ── App logo ───────────────────────────────────────────────────────
        // Intune does not require a logo, but every app published here gets one, so the logo is
        // fetched for the app rather than hunted down by hand: from the vendor's own site, saved
        // as Icon.png in the app's folder, and written into the Logo field the Publish flow reads.
        //
        // It runs at two moments and only when the app has no logo yet: right after Add App
        // creates the folder, and after a download completes (which covers apps added before this
        // existed, and scheduled runs). A logo the user picked by hand is never replaced.

        private static readonly System.Threading.SemaphoreSlim _logoGate = new(1, 1);

        // The Logo textbox of the currently rendered Package Information panel and the app it was
        // built for, so a fetch that finishes while the panel is open can fill the box in place
        // instead of waiting for the app to be re-selected.
        private TextBox? _pkgLogoBox;
        private DownloadSourceEntry? _pkgLogoBoxApp;

        /// <summary>
        /// Same vendor and name, which is app identity here. Needed because the Add path saves a
        /// copy of the dialog's entry into the list: the fetch may hold the dialog's object while
        /// the list, the selection and the panel all hold the copy.
        /// </summary>
        private static bool SameApp(DownloadSourceEntry? a, DownloadSourceEntry? b)
            => a != null && b != null
            && string.Equals(a.SourceAppVendor, b.SourceAppVendor, StringComparison.OrdinalIgnoreCase)
            && string.Equals(a.SourceAppName,   b.SourceAppName,   StringComparison.OrdinalIgnoreCase);

        /// <summary>
        /// Carries a fetched logo path everywhere the app lives: the JSON (via the caller's
        /// SaveAppJson), every matching in-memory entry, and the Intune settings Logo box when the
        /// panel is open on this app. The publish flow reads the in-memory object, so the JSON
        /// alone is not enough - an app added and published in one sitting would publish without
        /// the logo its own folder holds.
        /// </summary>
        private void ApplyLogoEverywhere(DownloadSourceEntry app, string dest)
        {
            Dispatcher.BeginInvoke((Action)(() =>
            {
                try
                {
                    foreach (var other in _allApps)
                        if (SameApp(other, app) && string.IsNullOrWhiteSpace(other.Logo))
                            other.Logo = dest;
                    if (SameApp(_selectedApp, app) && string.IsNullOrWhiteSpace(_selectedApp!.Logo))
                        _selectedApp.Logo = dest;

                    if (_pkgLogoBox != null && SameApp(_pkgLogoBoxApp, app)
                        && string.IsNullOrWhiteSpace(_pkgLogoBox.Text))
                        _pkgLogoBox.Text = dest;   // TextChanged saves it through the row's own callback
                }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
            }));
        }

        // Called from the auto-flow complete callback (UI thread). By now the Execute step has
        // written Icon.png into the app's per-app folder, so fill the Intune Logo box on the FIRST
        // run rather than waiting for the panel to be re-rendered on a later trigger. Persists to
        // the JSON and, via ApplyLogoEverywhere, updates the open box and the in-memory entries.
        private void ApplyIconLogoForFinishedApp(string vendor, string appName)
        {
            try
            {
                DownloadSourceEntry? app = _allApps.FirstOrDefault(a =>
                    string.Equals(a.SourceAppVendor, vendor,  StringComparison.OrdinalIgnoreCase) &&
                    string.Equals(a.SourceAppName,   appName, StringComparison.OrdinalIgnoreCase));
                if (app == null) return;
                string tf = (app.PackageTemplateFolder ?? "").Trim();
                if (tf.Length == 0) return;
                string cand = Path.Combine(tf, "Icon.png");
                if (!File.Exists(cand)) return;
                if (string.IsNullOrWhiteSpace(app.Logo)) { app.Logo = cand; SaveAppJson(app); }
                ApplyLogoEverywhere(app, cand);
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
        }

        // Called from the auto-flow complete callback (UI thread). With no PSADT template the
        // Intune Install/Uninstall command IS the Source command Create Package computed; it was
        // stored on AutoPackagePage's shared selected-app during packaging. Carry it into the JSON
        // and the in-memory entries now, and re-render the panel if it is open on this app, so the
        // Intune settings tab shows the fresh command on the FIRST run instead of the previous one
        // (and a second run, e.g. EXE after MSI, replaces the earlier value instead of keeping it).
        private void ApplyIntuneCommandsForFinishedApp(string vendor, string appName)
        {
            try
            {
                DownloadSourceEntry? app = _allApps.FirstOrDefault(a =>
                    string.Equals(a.SourceAppVendor, vendor,  StringComparison.OrdinalIgnoreCase) &&
                    string.Equals(a.SourceAppName,   appName, StringComparison.OrdinalIgnoreCase));
                if (app == null) return;
                // Template apps keep the PSADT command; this path is for direct-install apps only.
                if (!string.IsNullOrWhiteSpace(app.PSADTTemplateFolder)) return;

                var sa = AutoPackagePage.StaticSelectedApp;
                if (sa == null
                    || !string.IsNullOrWhiteSpace(sa.PSADTTemplateFolder)
                    || !string.Equals(sa.SourceAppName, app.SourceAppName, StringComparison.OrdinalIgnoreCase))
                    return;

                // With an empty template the shared app's InstallCommand/UninstallCommand ARE the
                // Source commands (set by the Create Package derivation). Mirror them into both the
                // Source* fields and the final Intune fields so a later template toggle stays right.
                string inst = sa.InstallCommand   ?? "";
                string unin = sa.UninstallCommand ?? "";
                if (string.IsNullOrWhiteSpace(inst) && string.IsNullOrWhiteSpace(unin)) return;

                // Write ONLY the final Intune InstallCommand/UninstallCommand (what this tab shows,
                // and what publishes for a template app). Do NOT touch SourceInstallCommand or
                // SourceUninstallCommand: those are the Publish page's per-run derivation cache, and
                // filling them here makes a later run publish this run's command instead of deriving
                // its own (an MSI run would otherwise publish the earlier EXE command). Leaving them
                // empty keeps the Publish Program tab deriving fresh from the current preference.
                bool changed = false;
                if (!string.IsNullOrWhiteSpace(inst) && app.InstallCommand   != inst) { app.InstallCommand   = inst; changed = true; }
                if (!string.IsNullOrWhiteSpace(unin) && app.UninstallCommand != unin) { app.UninstallCommand = unin; changed = true; }

                // Mirror the final commands onto the in-memory selected app when it is the one on
                // screen, so the tab stays consistent without a reload. Same rule as above: final
                // fields only, never the Source* derivation cache the Publish page reads.
                bool isShown = SameApp(_selectedApp, app);
                if (isShown && _selectedApp != null)
                {
                    if (!string.IsNullOrWhiteSpace(inst)) _selectedApp.InstallCommand   = inst;
                    if (!string.IsNullOrWhiteSpace(unin)) _selectedApp.UninstallCommand = unin;
                }

                if (changed) SaveAppJson(app);

                // Re-render so the Install/Uninstall Command rows pick up the new value. The active
                // sub-tab (_pkgActiveTab) is preserved, so the user stays on the tab they are on.
                if (changed && isShown && _lastInfo != null)
                    RenderInfoPanel(_lastInfo);
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
        }


        private async Task TryEnsureAppLogoAsync(DownloadSourceEntry? app)
        {
            if (app == null) return;
            string folder = (app.PackageTemplateFolder ?? "").Trim();
            if (folder.Length == 0 || !Directory.Exists(folder)) return;

            string dest = Path.Combine(folder, "Icon.png");
            try
            {
                // Already sorted: the Logo field points at a real file, or an earlier run left a
                // Icon.png in the folder that only needs wiring into the field.
                if (!string.IsNullOrWhiteSpace(app.Logo) && File.Exists(app.Logo)) return;
                if (File.Exists(dest)) { app.Logo = dest; SaveAppJson(app); ApplyLogoEverywhere(app, dest); return; }

                string page = (app.DownloadPageUrl ?? "").Trim();
                // A winget-picked app arrives with a blank Download Page URL - that field is
                // optional and hand-typed - but its homepage is on record in the winget locale
                // manifest as PackageUrl. That is the vendor's own site, so it is as good a place
                // to look for the logo as a typed URL would have been.
                if (page.Length == 0)
                    page = await WingetHomepageAsync(app).ConfigureAwait(false);
                if (!Uri.TryCreate(page, UriKind.Absolute, out var pageUri)
                    || (pageUri.Scheme != Uri.UriSchemeHttp && pageUri.Scheme != Uri.UriSchemeHttps))
                    return;   // nowhere to look; the field stays browseable by hand

                await _logoGate.WaitAsync().ConfigureAwait(false);
                try
                {
                    if (File.Exists(dest)) { app.Logo = dest; SaveAppJson(app); ApplyLogoEverywhere(app, dest); return; }
                    byte[]? png = await FetchSiteLogoPngAsync(pageUri).ConfigureAwait(false);
                    if (png == null)
                    {
                        System.Diagnostics.Debug.WriteLine($"[Logo] nothing usable on {pageUri.Host} for {app.SourceAppName}");
                        return;
                    }
                    File.WriteAllBytes(dest, png);
                    app.Logo = dest;
                    SaveAppJson(app);
                    ApplyLogoEverywhere(app, dest);
                    System.Diagnostics.Debug.WriteLine($"[Logo] saved {dest}");
                }
                finally { _logoGate.Release(); }
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
        }

        /// <summary>
        /// The vendor homepage from the winget locale manifest, or "". Same raw-CDN path shape as
        /// WingetCommandsAsync, pointed at the en-US locale file, which is where PackageUrl and
        /// PublisherUrl live - the installer manifest the rest of this page fetches carries
        /// neither.
        /// </summary>
        private static async Task<string> WingetHomepageAsync(DownloadSourceEntry app)
        {
            string id  = (app.WingetPackageId  ?? "").Trim();
            string ver = (app.SourceAppVersion ?? "").Trim();
            if (id.Length == 0 || ver.Length == 0 || id.IndexOf('.') < 0) return "";
            try
            {
                string relPath = "manifests/" + char.ToLowerInvariant(id[0]) + "/" + id.Replace('.', '/');
                string verSeg = Uri.EscapeDataString(ver);
                string yaml = await _http.GetStringAsync(
                    $"https://raw.githubusercontent.com/microsoft/winget-pkgs/master/{relPath}/{verSeg}/{id}.locale.en-US.yaml")
                    .ConfigureAwait(false);
                // PackageUrl is the product's page, PublisherUrl the vendor's - the product page
                // first, since a suite vendor's front door may carry a different product's branding.
                var m = Regex.Match(yaml, @"^PackageUrl:\s*(\S+)", RegexOptions.Multiline);
                if (!m.Success) m = Regex.Match(yaml, @"^PublisherUrl:\s*(\S+)", RegexOptions.Multiline);
                return m.Success ? m.Groups[1].Value.Trim().Trim('"', '\'') : "";
            }
            catch (System.Exception exSwallow)
            { System.Diagnostics.Debug.WriteLine("[Logo] winget homepage: " + exSwallow.Message); return ""; }
        }

        /// <summary>
        /// The vendor site's best icon as PNG bytes, or null. The page's own markup is what names
        /// the icons - apple-touch-icon first, since it is a 180px PNG on most sites, then the
        /// declared icons largest first, then /favicon.ico as the fallback every site has.
        /// </summary>
        private static async Task<byte[]?> FetchSiteLogoPngAsync(Uri pageUri)
        {
            var candidates = new List<(int rank, int size, Uri url)>();
            try
            {
                string html = await _http.GetStringAsync(pageUri).ConfigureAwait(false);
                foreach (Match m in Regex.Matches(html, "<link[^>]*>", RegexOptions.IgnoreCase))
                {
                    string tag  = m.Value;
                    string rel  = HtmlAttr(tag, "rel").ToLowerInvariant();
                    string href = HtmlAttr(tag, "href");
                    if (href.Length == 0) continue;

                    int rank = rel.Contains("apple-touch-icon") ? 0
                             : Regex.IsMatch(rel, @"\bicon\b")   ? 1
                             : -1;
                    if (rank < 0) continue;

                    // "180x180" and "32x32 64x64" both appear in the wild; the largest number wins.
                    int size = 0;
                    foreach (Match sm in Regex.Matches(HtmlAttr(tag, "sizes"), @"(\d+)x\d+"))
                        if (int.TryParse(sm.Groups[1].Value, out int s) && s > size) size = s;

                    if (Uri.TryCreate(pageUri, href, out var abs)
                        && (abs.Scheme == Uri.UriSchemeHttp || abs.Scheme == Uri.UriSchemeHttps))
                        candidates.Add((rank, size, abs));
                }
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }

            candidates.Sort((a, b) => a.rank != b.rank ? a.rank - b.rank : b.size - a.size);
            candidates.Add((9, 0, new Uri(pageUri.GetLeftPart(UriPartial.Authority) + "/favicon.ico")));

            // First one at least 64px wins outright; failing that, the largest that decoded at
            // all. A 16px favicon blown up on the Intune tile is worse than most alternatives,
            // but it is still better than the grey placeholder, so it is kept as a last resort.
            (byte[] png, int px)? fallback = null;
            foreach (var (_, _, url) in candidates)
            {
                try
                {
                    byte[] raw = await _http.GetByteArrayAsync(url).ConfigureAwait(false);
                    if (raw.Length == 0 || raw.Length > 4 * 1024 * 1024) continue;
                    var got = DecodeToPng(raw);
                    if (got == null) continue;   // SVG and friends land here; the next candidate may decode
                    if (got.Value.px >= 64) return got.Value.png;
                    if (fallback == null || got.Value.px > fallback.Value.px) fallback = got;
                }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
            }
            return fallback?.png;
        }

        private static string HtmlAttr(string tag, string name)
            => Regex.Match(tag, name + @"\s*=\s*[""']([^""']*)[""']", RegexOptions.IgnoreCase).Groups[1].Value.Trim();

        /// <summary>
        /// Re-encodes whatever arrived as PNG and reports its width. An .ico holds several sizes
        /// and the largest frame is the one worth keeping; a PNG or JPG passes through with one.
        /// Null for anything WPF cannot decode, which is how SVG favicons are skipped.
        /// </summary>
        private static (byte[] png, int px)? DecodeToPng(byte[] raw)
        {
            try
            {
                using var ms = new System.IO.MemoryStream(raw);
                var dec = System.Windows.Media.Imaging.BitmapDecoder.Create(ms,
                    System.Windows.Media.Imaging.BitmapCreateOptions.PreservePixelFormat,
                    System.Windows.Media.Imaging.BitmapCacheOption.OnLoad);
                if (dec.Frames.Count == 0) return null;
                var best = dec.Frames[0];
                foreach (var f in dec.Frames)
                    if (f.PixelWidth * f.PixelHeight > best.PixelWidth * best.PixelHeight) best = f;
                var enc = new System.Windows.Media.Imaging.PngBitmapEncoder();
                enc.Frames.Add(best);
                using var outMs = new System.IO.MemoryStream();
                enc.Save(outMs);
                return (outMs.ToArray(), best.PixelWidth);
            }
            catch { return null; }
        }

        // ── Add App Dialog ─────────────────────────────────────────────────
        /// <summary>
        /// Re-renders all code-built UI after a theme switch. Controls created in
        /// code capture brush values at build time (not DynamicResource), so the
        /// vendors list, app cards, and the information columns must be rebuilt
        /// for the new theme to take effect without leaving the page.
        /// </summary>
        public void RefreshAfterThemeChange()
        {
            try
            {
                BuildCategoryChips();
                RenderVendors();
                RenderCards();
                if (_selectedApp != null) SelectApp(_selectedApp);
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
        }

        private void BtnAddApp_Click(object sender, RoutedEventArgs e) => ShowAddEditAppDialog(null);

        private void ShowAddEditAppDialog(DownloadSourceEntry? existing)
        {
            bool isEdit = existing != null;

            // Adding a new app requires Package Input Folder to be configured, since the app's
            // JSON is written under it. Without it the app would only live in memory and be lost
            // on restart, so block the add and point the user to Settings.
            if (!isEdit)
            {
                string pif = "";
                try
                {
                    if (File.Exists(JsonPath))
                    {
                        var cfgNode = System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(JsonPath));
                        pif = cfgNode?["PackageInputFolder"]?.GetValue<string>() ?? "";
                    }
                }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                if (string.IsNullOrWhiteSpace(pif))
                {
                    ShowStyledInfoDialog(Window.GetWindow(this)!, "Package Input Folder Not Set", "⚠️", new[]
                    {
                        ("Required", "Set the Package Input Folder in Settings before adding an app."),
                        ("Reason",   "The app is saved as a JSON file under this folder. Without it the app cannot be stored on disk and would be lost on restart."),
                    });
                    return;
                }
            }

            var winBg  = Res("NavBarBgBrush", new SolidColorBrush(Color.FromRgb(0xE8, 0xEA, 0xF5)));
            var bClr   = new SolidColorBrush(Color.FromRgb(0x53, 0x56, 0x63));

            // Clamp the dialog height to the current screen work area so the whole
            // form (including the button bar) stays on-screen at any resolution or
            // DPI scale. The inner ScrollViewer handles any remaining overflow.
            double maxWinH = Math.Max(480, SystemParameters.WorkArea.Height - 48);
            var win = new Window
            {
                Title = isEdit ? "Edit App" : "Add App",
                // Add mode is a slim form with a wide inline results table (winget / github), so it
                // is wider and hugs its content vertically (no trailing empty space). Edit keeps the
                // original fixed size for its full multi-tab form.
                Width = isEdit ? 560 : 780,
                Height = isEdit ? Math.Min(700, maxWinH) : double.NaN,
                SizeToContent = isEdit ? SizeToContent.Manual : SizeToContent.Height,
                MaxHeight = maxWinH,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = Window.GetWindow(this),
                ResizeMode = ResizeMode.NoResize,
                WindowStyle = WindowStyle.None,
                AllowsTransparency = true,
                Background = Brushes.Transparent,
                FontFamily = new System.Windows.Media.FontFamily("Segoe UI"),
                ShowInTaskbar = false
            };

            var outer = new Border
            {
                Background = winBg, BorderBrush = bClr, BorderThickness = new Thickness(1.5),
                CornerRadius = new CornerRadius(10),
                Effect = new System.Windows.Media.Effects.DropShadowEffect { BlurRadius = 20, ShadowDepth = 4, Opacity = 0.3, Color = System.Windows.Media.Colors.Black }
            };
            win.Content = outer;

            // ── Outer layout: title bar | scroll area | button bar
            var og = new Grid();
            og.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); // title
            og.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); // section tab strip
            // Add mode sizes to content (Auto), so the scroll row must be Auto too or a Star row
            // collapses to nothing; the ScrollViewer's own MaxHeight still handles overflow. Edit
            // keeps the Star row that fills its fixed-height window.
            og.RowDefinitions.Add(new RowDefinition { Height = isEdit ? new GridLength(1, GridUnitType.Star) : GridLength.Auto }); // scroll
            og.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); // buttons
            outer.Child = og;

            // ── Title bar
            var tb = new Border { Background = bClr, BorderThickness = new Thickness(0, 0, 0, 1), BorderBrush = Res("BorderMainBrush", Brushes.LightGray), CornerRadius = new CornerRadius(10, 10, 0, 0), Padding = new Thickness(16, 8, 12, 8) };
            tb.MouseLeftButtonDown += (_, _) => win.DragMove();
            Grid.SetRow(tb, 0);
            var tg = new Grid();
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            var ti  = new TextBlock { Text = "📥", FontSize = 14, Foreground = Brushes.White, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 0) };
            var tt  = new TextBlock { Text = isEdit ? "Edit App" : "Add App", FontSize = 13, FontWeight = FontWeights.SemiBold, Foreground = Brushes.White, VerticalAlignment = VerticalAlignment.Center };
            var tcl = new Button   { Content = "✕", FontSize = 11, Foreground = new SolidColorBrush(Color.FromArgb(0xCC, 0xFF, 0xFF, 0xFF)), Background = Brushes.Transparent, BorderThickness = new Thickness(0), Cursor = System.Windows.Input.Cursors.Hand, VerticalAlignment = VerticalAlignment.Center, Padding = new Thickness(6, 2, 6, 2) };
            tcl.Click += (_, _) => win.Close();
            Grid.SetColumn(ti, 0); Grid.SetColumn(tt, 1); Grid.SetColumn(tcl, 2);
            tg.Children.Add(ti); tg.Children.Add(tt); tg.Children.Add(tcl);
            tb.Child = tg; og.Children.Add(tb);

            // ── Scrollable form
            var sv = new ScrollViewer { VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Margin = new Thickness(0) };
            // Add mode sizes the window to content; cap the scroll area so a tall content state
            // (the inline results panel open) still fits on screen and scrolls instead of pushing
            // the window off the bottom. Title bar + button bar take ~120px.
            if (!isEdit) sv.MaxHeight = Math.Max(360, maxWinH - 120);
            // Apply ▲▼ arrow scrollbar style by hooking into the dialog's Loaded event
            sv.Loaded += (_, _) =>
            {
                // Find the vertical ScrollBar inside the ScrollViewer and apply the app's arrow template
                var vBar = sv.Template?.FindName("PART_VerticalScrollBar", sv) as System.Windows.Controls.Primitives.ScrollBar;
                if (vBar != null && Application.Current.Resources.Contains("VertSB"))
                    vBar.Template = (ControlTemplate)Application.Current.Resources["VertSB"];
                else if (vBar != null && Application.Current.Resources.Contains("ApVertSB"))
                    vBar.Template = (ControlTemplate)Application.Current.Resources["ApVertSB"];
            };
            Grid.SetRow(sv, 2); og.Children.Add(sv);

            var cg = new Grid { Margin = new Thickness(16, 8, 16, 8) };
            cg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(160) });
            cg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            sv.Content = cg;

            var bBg    = Res("InputBgBrush", Brushes.White);
            var bBdr   = Res("BorderMainBrush", Brushes.LightGray);
            var lFg    = Res("TextPrimaryBrush", Brushes.Black);
            var secFg  = Res("TextSecondaryBrush", Brushes.Gray);
            var tbStyle = Application.Current.TryFindResource("ModernTextBoxStyle") as Style;
            var sec    = Application.Current.TryFindResource("SecondaryButtonStyle") as Style;

            // Shared ComboBox style with rounded corners
            var cbStyle = new Style(typeof(ComboBox));
            cbStyle.Setters.Add(new Setter(ComboBox.BorderBrushProperty, bBdr));
            cbStyle.Setters.Add(new Setter(ComboBox.BackgroundProperty, bBg));
            cbStyle.Setters.Add(new Setter(ComboBox.FontSizeProperty, 11.0));
            cbStyle.Setters.Add(new Setter(ComboBox.HeightProperty, 28.0));
            cbStyle.Setters.Add(new Setter(Border.CornerRadiusProperty, new CornerRadius(6)));

            const int ROW_GAP = 8; // unified gap after every row
            int r = 0;

            // Section-tab state (Application settings / Package settings / Intune settings). The tab strip
            // added before ShowDialog masks whole sections by row height. dlgSections records each
            // section's first row (filled by MakeSection); reapplyDlgTab re-asserts the active tab
            // after the one cross-tab conditional (Download Preference) runs.
            var dlgSections = new List<(int startRow, string title)>();
            string dlgActiveTab = "app";
            Action? reapplyDlgTab = null;
            Action? updateIdentitySectionVisibility = null;

            // Builds a field label; when required, appends a red asterisk to flag
            // fields that must be filled before adding.
            TextBlock MakeFieldLabel(string label, bool required, double? width = null)
            {
                var lbl = new TextBlock { FontSize = 11, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 0) };
                if (width.HasValue) lbl.Width = width.Value;
                lbl.Inlines.Add(new System.Windows.Documents.Run(label) { Foreground = lFg });
                if (required)
                    lbl.Inlines.Add(new System.Windows.Documents.Run(" *") { Foreground = new SolidColorBrush(Color.FromRgb(0xE5, 0x39, 0x35)), FontWeight = FontWeights.Bold });
                return lbl;
            }

            TextBox MakeRow(string label, string value, string? hint = null, bool required = false)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var lb = MakeFieldLabel(label, required);
                var tx = new TextBox   { Text = value, FontSize = 11, Height = 28, Style = tbStyle, Background = bBg, BorderBrush = bBdr, Foreground = lFg, Padding = new Thickness(8, 0, 8, 0) };
                Grid.SetRow(lb, r); Grid.SetColumn(lb, 0);
                Grid.SetRow(tx, r); Grid.SetColumn(tx, 1);
                cg.Children.Add(lb); cg.Children.Add(tx); r++;
                if (hint != null)
                {
                    cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                    var ht = new TextBlock { Text = hint, FontSize = 9, FontStyle = FontStyles.Italic, Foreground = secFg, TextWrapping = TextWrapping.Wrap };
                    Grid.SetRow(ht, r); Grid.SetColumn(ht, 1); cg.Children.Add(ht); r++;
                }
                cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(ROW_GAP) }); r++;
                return tx;
            }

            // Like MakeRow, but overlays a search button inside the textbox that opens the winget
            // catalog picker - parity with the Package Information column's Winget Package ID field.
            // showPickButton=false omits the icon (Add mode uses an always-visible inline results
            // panel instead, so the button is redundant there).
            TextBox MakePickRow(string label, string value, string icon, string tooltip, Action onPick, bool showPickButton = true)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var lb = MakeFieldLabel(label, false);
                var host = new Grid();
                // No icon → the textbox can use the full width (no reserved right padding).
                var tx = new TextBox { Text = value, FontSize = 11, Height = 28, Style = tbStyle, Background = bBg, BorderBrush = bBdr, Foreground = lFg, Padding = new Thickness(8, 0, showPickButton ? 28 : 8, 0) };
                host.Children.Add(tx);
                if (showPickButton)
                {
                    // Segoe MDL2 Assets, not an emoji. 🔍 is a COLOUR glyph: the font paints it a fixed
                    // dark blue and ignores Foreground entirely, so on the dark theme it was a dark
                    // smudge on a dark box. MDL2 glyphs are monochrome and take the brush they are
                    // given, so the icon follows the theme like every other piece of text.
                    var pick = new Button
                    {
                        Content = icon, FontSize = 12, Width = 22, Height = 20,
                        FontFamily = new System.Windows.Media.FontFamily("Segoe MDL2 Assets"),
                        HorizontalAlignment = HorizontalAlignment.Right, VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 0, 4, 0), Background = Brushes.Transparent, BorderThickness = new Thickness(0),
                        Cursor = System.Windows.Input.Cursors.Hand, ToolTip = tooltip,
                    };
                    pick.SetResourceReference(Control.ForegroundProperty, "TextPrimaryBrush");
                    pick.Click += (_, _) => onPick();
                    host.Children.Add(pick);
                }
                Grid.SetRow(lb, r); Grid.SetColumn(lb, 0);
                Grid.SetRow(host, r); Grid.SetColumn(host, 1);
                cg.Children.Add(lb); cg.Children.Add(host); r++;
                cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(ROW_GAP) }); r++;
                return tx;
            }

            // Returns (getValueFn, labelElement, radioPanel, dataRowIndex, gapRowIndex)
            // so callers can collapse/show both the label and radio StackPanel together.
            (Func<string> get, TextBlock lb, StackPanel sp, int dataRow, int gapRow) MakeRadioRowEx(string label, string[] options, string defaultVal)
            {
                int dataRowIdx = r;
                cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(28) });
                var lb2 = new TextBlock { Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 0) };
                var sp2 = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                var rbs2 = new List<RadioButton>();
                var rawValues2 = new List<string>();
                string grp2 = Guid.NewGuid().ToString();
                foreach (var opt in options)
                {
                    string displayLabel = opt.Replace("_", " ");
                    var rb = new RadioButton { Content = displayLabel, GroupName = grp2, FontSize = 11, Margin = new Thickness(0, 0, 14, 0), Cursor = System.Windows.Input.Cursors.Hand, Foreground = lFg, VerticalAlignment = VerticalAlignment.Center };
                    rb.IsChecked = opt.Equals(defaultVal, StringComparison.OrdinalIgnoreCase);
                    sp2.Children.Add(rb); rbs2.Add(rb); rawValues2.Add(opt);
                }
                Grid.SetRow(lb2, r); Grid.SetColumn(lb2, 0);
                Grid.SetRow(sp2, r); Grid.SetColumn(sp2, 1);
                cg.Children.Add(lb2); cg.Children.Add(sp2); r++;
                int gapRowIdx = r;
                cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(ROW_GAP) }); r++;
                Func<string> getter = () => { for (int i = 0; i < rbs2.Count; i++) if (rbs2[i].IsChecked == true) return rawValues2[i]; return defaultVal; };
                return (getter, lb2, sp2, dataRowIdx, gapRowIdx);
            }

            var addAppRadioPanels = new Dictionary<string, WrapPanel>();
            Func<string> MakeRadioRow(string label, string[] options, string defaultVal, Action<string>? onChanged = null)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto, MinHeight = 28 }); // grows when radios wrap
                var lb = new TextBlock { Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 0) };
                var sp = new WrapPanel { VerticalAlignment = VerticalAlignment.Center };
                var rbs = new List<RadioButton>();
                var rawValues = new List<string>(); // parallel list of raw values to return on save
                string grp = Guid.NewGuid().ToString();
                foreach (var opt in options)
                {
                    string displayLabel = opt.Replace("_", " "); // e.g. MSI_x64 → MSI x64
                    var rb = new RadioButton { Content = displayLabel, GroupName = grp, FontSize = 11, Margin = new Thickness(0, 0, 14, 0), Cursor = System.Windows.Input.Cursors.Hand, Foreground = lFg, VerticalAlignment = VerticalAlignment.Center };
                    rb.IsChecked = opt.Equals(defaultVal, StringComparison.OrdinalIgnoreCase);
                    string capOpt = opt;
                    if (onChanged != null)
                        rb.Click += (_, _) => onChanged(capOpt);
                    sp.Children.Add(rb); rbs.Add(rb); rawValues.Add(opt);
                }
                Grid.SetRow(lb, r); Grid.SetColumn(lb, 0);
                Grid.SetRow(sp, r); Grid.SetColumn(sp, 1);
                cg.Children.Add(lb); cg.Children.Add(sp); r++;
                addAppRadioPanels[label] = sp;
                cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(ROW_GAP) }); r++;
                // Return the raw value (with underscores) matching the checked radio button
                return () =>
                {
                    for (int i = 0; i < rbs.Count; i++)
                        if (rbs[i].IsChecked == true) return rawValues[i];
                    return defaultVal;
                };
            }

            // ComboBox wrapped in rounded Border for reliable corner radius across all WPF themes
            Func<string> MakeComboRow(string label, string[] options, string defaultVal)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(28) }); // same height as textbox
                var lb = new TextBlock { Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 0) };
                var cb = new ComboBox { FontSize = 11, BorderThickness = new Thickness(0), Background = Brushes.Transparent, VerticalAlignment = VerticalAlignment.Stretch };
                foreach (var opt in options) cb.Items.Add(opt);
                var matchIdx = options.ToList().FindIndex(o => o.Equals(defaultVal, StringComparison.OrdinalIgnoreCase));
                cb.SelectedIndex = matchIdx >= 0 ? matchIdx : 0;
                // Wrap in Border with CornerRadius — this is the reliable cross-theme approach
                var brd = new Border { Background = bBg, BorderBrush = bBdr, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(6), ClipToBounds = true, Child = cb };
                // ClipToBounds clips to the rectangular bounds only, so the ComboBox's own square
                // corners still show through the rounded border (visible in dark mode). Apply an
                // explicit rounded clip that tracks the size so all four corners stay round.
                brd.SizeChanged += (_, se) => brd.Clip = new RectangleGeometry(new Rect(0, 0, se.NewSize.Width, se.NewSize.Height), 6, 6);
                Grid.SetRow(lb,  r); Grid.SetColumn(lb,  0);
                Grid.SetRow(brd, r); Grid.SetColumn(brd, 1);
                cg.Children.Add(lb); cg.Children.Add(brd); r++;
                cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(ROW_GAP) }); r++;
                return () => cb.SelectedItem?.ToString()?.Trim() ?? "";
            }

            void MakeSection(string title)
            {
                // Record the section's first row so the tab strip can mask/show it as a unit.
                dlgSections.Add((r, title));
                // Sections are separated by a bold header only (no divider line).
                cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(10) }); r++;
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var hdr = new TextBlock { Text = title, FontSize = 11, FontWeight = FontWeights.Bold, Foreground = lFg, Margin = new Thickness(0, 0, 0, 2) };
                Grid.SetRow(hdr, r); Grid.SetColumnSpan(hdr, 2); cg.Children.Add(hdr); r++;
                cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(6) }); r++;
            }

            cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(4) }); r++;

            // The three App Identity boxes are DECLARED here but BUILT below the Download Source
            // section, so Download Source renders first. The Download Source pickers (winget /
            // GitHub) write into them through ApplyAutoIdentity, and every one of those calls comes
            // from a lambda that cannot run before the dialog is shown, by which point the real
            // controls are assigned. null! keeps them definitely assigned for the lambda capture.
            TextBox txVend = null!, txName = null!, txSrcVer = null!;

            // Auto-fill tracking: remember what we last auto-filled into the App Identity fields, so a
            // later source (a different API Type, the winget pick, a GitHub repo) can refresh those
            // values while still preserving anything the user typed by hand. A field is overwritten only
            // when it is empty or still holds our previous auto-fill; "" clears an auto-filled field.
            string autoVend = "", autoName = "", autoVer = "";
            void ApplyAutoIdentity(string vend, string name, string ver)
            {
                // The boxes are built below the Download Source section, so nothing may write to
                // them until that build has run. Every caller is a deferred handler today; this
                // keeps a future synchronous caller from dereferencing a not-yet-built control.
                if (txVend == null || txName == null || txSrcVer == null) return;
                if (string.IsNullOrWhiteSpace(txVend.Text)   || txVend.Text   == autoVend) txVend.Text   = vend;
                if (string.IsNullOrWhiteSpace(txName.Text)   || txName.Text   == autoName) txName.Text   = name;
                if (string.IsNullOrWhiteSpace(txSrcVer.Text) || txSrcVer.Text == autoVer)  txSrcVer.Text = ver;
                autoVend = vend; autoName = name; autoVer = ver;
            }
            // Assigned after the Silent Parameters fields are built (they live further down); the
            // winget pick invokes these so it can fill the EXE silent switches - first from a fast
            // built-in map (refreshSilentEXE), then refined from the package's actual winget manifest
            // (fetchManifestSilentEXE), which covers every package, not just the well-known ones.
            Action? refreshSilentEXE = null;
            Action<string, string>? fetchManifestSilentEXE = null;
            Action<string, string, string>? fetchGitHubSilentEXE = null;   // (winget id, version, repo)
            // Holds the in-flight manifest fetch started by the last apply, so Add can await it and
            // capture the EXE silent switches before saving (the winget/github catalog carries none).
            Task? pendingSilentFetch = null;

            // ── Download Source ────────────────────────────────────────────
            MakeSection("Download Source");
            // API Type is a dropdown here too - a typo silently produced an app with no download
            // links and no error (see ApiTypeOptions). MakeComboRow only returns a getter, and the
            // Edit path has to PREFILL it, so build the box directly and keep the reference.
            // Built inline rather than via MakeComboRow because that only returns a getter, and the
            // Edit path has to PREFILL the box. Same visual structure as MakeComboRow.
            ComboBox cbApi;
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(28) });
                var lb = new TextBlock { Text = "API Type", FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 0) };
                cbApi = new ComboBox { FontSize = 11, BorderThickness = new Thickness(0), Background = Brushes.Transparent, VerticalAlignment = VerticalAlignment.Stretch };
                foreach (var opt in ApiTypeOptions) cbApi.Items.Add(opt);
                int ai = ApiTypeOptions.ToList().FindIndex(o => o.Equals(existing?.ApiType ?? "winget", StringComparison.OrdinalIgnoreCase));
                cbApi.SelectedIndex = ai >= 0 ? ai : 0;   // default "winget" for new apps
                var brdApi = new Border { Background = bBg, BorderBrush = bBdr, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(6), ClipToBounds = true, Child = cbApi };
                brdApi.SizeChanged += (_, se) => brdApi.Clip = new RectangleGeometry(new Rect(0, 0, se.NewSize.Width, se.NewSize.Height), 6, 6);
                Grid.SetRow(lb,     r); Grid.SetColumn(lb,     0);
                Grid.SetRow(brdApi, r); Grid.SetColumn(brdApi, 1);
                cg.Children.Add(lb); cg.Children.Add(brdApi); r++;
                cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(ROW_GAP) }); r++;
            }
            int dsRowGh = r;
            TextBox txRepo = null!;

            // Apply a chosen GitHub app to the form - shared by the popup (Edit) and the inline
            // results panel (Add), mirroring ApplyPickedWinget.
            void ApplyPickedGitHub(GitHubApp a)
            {
                if (a == null) return;
                txRepo.Text = a.Repo;
                ApplyAutoIdentity(a.Vendor, a.Name, a.Version);
                fetchGitHubSilentEXE?.Invoke(a.Id, a.Version, a.Repo);
            }

            // Assigned after the inline panels are built (Add mode); focuses the github results.
            Action? focusInlineGitHub = null;
            txRepo = MakePickRow("GitHub Repo", existing?.GitHubRepo ?? "", "\uE721", "Search GitHub-hosted apps",
                () =>
                {
                    if (!isEdit && focusInlineGitHub != null) { focusInlineGitHub(); return; }
                    var a = PickGitHubApp("");
                    if (a != null) ApplyPickedGitHub(a);
                },
                showPickButton: isEdit);
            // Add mode fills this box only by picking from the inline results grid below, so it is
            // read-only there (the pick still sets .Text in code). Edit mode keeps it hand-editable.
            if (!isEdit) txRepo.IsReadOnly = true;
            // GitHub repos are "owner/repo" (a full github.com URL works too): fill Vendor from the
            // owner and Name from the repo when the field loses focus, without clobbering user input.
            txRepo.LostFocus += (_, _) =>
            {
                var parts = (txRepo.Text ?? "").Trim().TrimEnd('/').Split('/');
                if (parts.Length >= 2)
                {
                    string owner = parts[parts.Length - 2].Trim();
                    string repo  = parts[parts.Length - 1].Trim();
                    if (owner.Length > 0 && repo.Length > 0) ApplyAutoIdentity(owner, repo, "");
                }
            };
            int dsRowWg = r;
            TextBox txWinget = null!;
            // Assigned once the Download Preference row exists (built below). Aligns the preference
            // with what the picked package actually ships, per the picker's own footer readout.
            Action<string, string>? applyWingetInstallerType = null;

            // Apply a chosen winget package to the form - identical work whether the choice came
            // from the popup picker (Edit) or the inline results panel (Add).
            void ApplyPickedWinget(WingetCatalog.WingetPackage wp)
            {
                if (wp == null) return;
                txWinget.Text = wp.Id;
                // Vendor comes from the id publisher segment (Smekal.FileCompare -> Smekal).
                int dot = wp.Id.IndexOf('.');
                string vend = dot > 0 ? wp.Id.Substring(0, dot) : wp.Id;
                ApplyAutoIdentity(vend, wp.Name, wp.Version);
                refreshSilentEXE?.Invoke();
                fetchManifestSilentEXE?.Invoke(wp.Id, wp.Version);
                applyWingetInstallerType?.Invoke(wp.Id, wp.Version);
            }

            // Add mode shows the winget results inline (below the field); the Search icon just
            // focuses that panel's search box. Edit keeps the popup picker. Assigned after the
            // inline panels are built, further down.
            Action? focusInlineWinget = null;
            txWinget = MakePickRow("Winget Package ID", existing?.WingetPackageId ?? "", "\uE721", "Search the winget catalog",
                () =>
                {
                    if (!isEdit && focusInlineWinget != null) { focusInlineWinget(); return; }
                    var wp = PickWingetPackage("");
                    if (wp != null) ApplyPickedWinget(wp);
                },
                showPickButton: isEdit);
            // Add mode fills this box only by picking from the inline winget grid below, so it is
            // read-only there (the pick still sets .Text in code). Edit mode keeps it hand-editable.
            if (!isEdit) txWinget.IsReadOnly = true;
            int dsRowVendor = r;
            var txVendor  = MakeRow("Vendor API ID",         existing?.VendorApiId       ?? "");
            int dsRowUrl = r;
            // Download Page URL is optional for winget/github (the fetchers supply the links) and
            // required only for API Type = URL. Built inline (rather than via MakeRow) so it can
            // carry a greyed placeholder overlay - "Optional", or "Required" for URL, kept in sync
            // by SyncDownloadSourceRows. Shown only while the box is empty.
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var lblUrl = MakeFieldLabel("Download Page URL", false);
            var urlHost = new Grid();
            var txUrl = new TextBox { Text = existing?.DownloadPageUrl ?? "", FontSize = 11, Height = 28, Style = tbStyle, Background = bBg, BorderBrush = bBdr, Foreground = lFg, Padding = new Thickness(8, 0, 8, 0) };
            var urlPlaceholder = new TextBlock
            {
                Text = "Optional", FontSize = 11, Foreground = secFg,
                IsHitTestVisible = false, VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(10, 0, 0, 0),
                Visibility = string.IsNullOrEmpty(txUrl.Text) ? Visibility.Visible : Visibility.Collapsed,
            };
            txUrl.TextChanged += (_, _) => urlPlaceholder.Visibility = string.IsNullOrEmpty(txUrl.Text) ? Visibility.Visible : Visibility.Collapsed;
            urlHost.Children.Add(txUrl);
            urlHost.Children.Add(urlPlaceholder);
            Grid.SetRow(lblUrl, r); Grid.SetColumn(lblUrl, 0);
            Grid.SetRow(urlHost, r); Grid.SetColumn(urlHost, 1);
            cg.Children.Add(lblUrl); cg.Children.Add(urlHost); r++;
            cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(ROW_GAP) }); r++;

            // Show only the download-source identifier the API Type actually uses (parity with the
            // Package Information column): winget -> Winget Package ID, github -> GitHub Repo, URL ->
            // neither (Download Page URL becomes the required source, flagged with *). Each row is a
            // MakeRow/MakePickRow, so collapse both its data row and its trailing gap row.
            TextBlock? DsLabelAt(int row)
            {
                foreach (UIElement ch in cg.Children)
                    if (ch is TextBlock tbl && Grid.GetRow(ch) == row && Grid.GetColumn(ch) == 0) return tbl;
                return null;
            }
            var dsLblUrl = DsLabelAt(dsRowUrl);
            void DsSetRow(FrameworkElement ctl, int dataRow, bool shown)
            {
                var vis = shown ? Visibility.Visible : Visibility.Collapsed;
                ctl.Visibility = vis;
                var lab = DsLabelAt(dataRow); if (lab != null) lab.Visibility = vis;
                if (dataRow < cg.RowDefinitions.Count)
                    cg.RowDefinitions[dataRow].Height = shown ? GridLength.Auto : new GridLength(0);
                if (dataRow + 1 < cg.RowDefinitions.Count)
                    cg.RowDefinitions[dataRow + 1].Height = shown ? new GridLength(ROW_GAP) : new GridLength(0);
            }
            void SyncDownloadSourceRows()
            {
                string t = (cbApi.SelectedItem as string ?? "URL").Trim();
                DsSetRow(txRepo, dsRowGh, t.Equals("github", StringComparison.OrdinalIgnoreCase));
                DsSetRow((FrameworkElement)txWinget.Parent, dsRowWg, t.Equals("winget", StringComparison.OrdinalIgnoreCase));
                DsSetRow(txVendor, dsRowVendor, t.Equals("Vendor API", StringComparison.OrdinalIgnoreCase));
                bool req = t.Equals("URL", StringComparison.OrdinalIgnoreCase);
                urlPlaceholder.Text = req ? "Required" : "Optional";
                if (dsLblUrl != null)
                {
                    dsLblUrl.Inlines.Clear();
                    dsLblUrl.Inlines.Add(new System.Windows.Documents.Run("Download Page URL") { Foreground = lFg });
                    if (req)
                        dsLblUrl.Inlines.Add(new System.Windows.Documents.Run(" *") { Foreground = new SolidColorBrush(Color.FromRgb(0xE5, 0x39, 0x35)), FontWeight = FontWeights.Bold });
                }
            }
            // Built-in vendor fetchers imply a known vendor and product; offer them as defaults when
            // that API Type is chosen, without clobbering anything the user already typed. These are
            // starting points only - edit as needed.
            void AutoFillFromApiType()
            {
                // none/winget/github all clear the auto-filled Vendor/Name so the picker (winget)
                // or repo (github) can supply fresh values.
                ApplyAutoIdentity("", "", "");
            }

            // Inline results panels (Add mode): shown automatically for the selected API Type, so
            // no popup and no Search click are needed. Assigned when the panels are built below.
            Action<string>? syncInlinePanels = null;
            cbApi.SelectionChanged += (_, _) =>
            {
                SyncDownloadSourceRows();
                AutoFillFromApiType();
                syncInlinePanels?.Invoke((cbApi.SelectedItem as string ?? "").Trim());
                updateIdentitySectionVisibility?.Invoke();
                reapplyDlgTab?.Invoke();
            };
            SyncDownloadSourceRows();

            // Applies the currently highlighted inline result for the active API Type (Add mode);
            // called by Add so the nearest match is committed without a Select button.
            Action? applyInlineWinget = null;
            Action? applyInlineGitHub = null;

            // ── Inline results panels (Add mode) ───────────────────────────────
            // For winget and github, the matching results table is shown right here in the form (no
            // popup, no Search-icon click). Selecting API Type winget shows the winget catalog;
            // github shows the github catalog. Double-click or Select fills the fields. There is no
            // Close button - the panel simply follows the API Type. Both reuse the same apply logic
            // as the popups (ApplyPickedWinget / ApplyPickedGitHub), which Edit still uses.
            if (!isEdit)
            {
                // Generic builder for one inline results panel. `refresh(query, list, hint)` fills the
                // list for the current search text; `apply(item)` handles a picked row. Returns a
                // (show, focus) pair: show(bool) reveals/hides the panel (loading on first reveal),
                // focus() reveals it and focuses the search box (used by the Search icon).
                (Action<bool> show, Action focus, Action applySelected) BuildInlinePanel(
                    string placeholder,
                    Action<string, ListView, TextBlock> refresh,
                    GridViewColumn[] columns,
                    Action<object> apply)
                {
                    int panelRow = r;
                    cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

                    var search = new TextBox
                    {
                        FontSize = 11, Height = 30, Padding = new Thickness(28, 0, 8, 0),
                        VerticalContentAlignment = VerticalAlignment.Center,
                        Style = tbStyle, Background = bBg, BorderBrush = bBdr, Foreground = lFg,
                    };
                    // Search glyph inside the box (Segoe MDL2 Assets, monochrome so it takes the theme
                    // brush - unlike the 🔍 emoji, which paints its own fixed colour). Non-hit-testing
                    // so clicks fall through to the TextBox.
                    var searchIcon = new TextBlock
                    {
                        Text = "\uE721", FontSize = 12,
                        FontFamily = new System.Windows.Media.FontFamily("Segoe MDL2 Assets"),
                        Foreground = secFg, IsHitTestVisible = false,
                        VerticalAlignment = VerticalAlignment.Center, HorizontalAlignment = HorizontalAlignment.Left,
                        Margin = new Thickness(9, 0, 0, 0),
                    };
                    // Grey placeholder overlay: shown only while the box is empty; hidden on typing.
                    var placeholderTb = new TextBlock
                    {
                        Text = placeholder, FontSize = 11, Foreground = secFg,
                        IsHitTestVisible = false, VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(30, 0, 0, 0),
                    };
                    var searchHost = new Grid { Margin = new Thickness(0, 0, 0, 6) };
                    searchHost.Children.Add(search);
                    searchHost.Children.Add(searchIcon);
                    searchHost.Children.Add(placeholderTb);

                    var list = new ListView { FontSize = 11, Foreground = lFg, BorderBrush = bBdr, Background = bBg, Height = 260 };
                    var gv = new GridView();
                    foreach (var c in columns) gv.Columns.Add(c);
                    list.View = gv;

                    // Themed selection: the stock ListViewItem template paints the selected row with the
                    // system highlight (a light blue) but leaves the text at TextPrimaryBrush — near-white
                    // in dark mode — so a selected row's text vanishes. Reuse the downloads-grid row
                    // template, whose selection tint is a translucent accent over the input background,
                    // keeping the row's own foreground legible in both themes.
                    Color pkAccent = Res("AccentBrush", new SolidColorBrush(Color.FromRgb(0x6C, 0x63, 0xFF))) is SolidColorBrush pkAcc
                        ? pkAcc.Color : Color.FromRgb(0x6C, 0x63, 0xFF);
                    var pkGridLine = new SolidColorBrush(Color.FromArgb(0x40, 0x90, 0x90, 0x90));
                    var pkHoverBg  = new SolidColorBrush(Color.FromArgb(0x33, pkAccent.R, pkAccent.G, pkAccent.B));
                    var pkSelBg    = new SolidColorBrush(Color.FromArgb(0x66, pkAccent.R, pkAccent.G, pkAccent.B));
                    var pkSelBd    = new SolidColorBrush(Color.FromArgb(0xB0, pkAccent.R, pkAccent.G, pkAccent.B));
                    pkGridLine.Freeze(); pkHoverBg.Freeze(); pkSelBg.Freeze(); pkSelBd.Freeze();

                    var pkRowStyle = new Style(typeof(ListViewItem));
                    pkRowStyle.Setters.Add(new Setter(Control.ForegroundProperty,      lFg));
                    pkRowStyle.Setters.Add(new Setter(Control.BackgroundProperty,      Brushes.Transparent));
                    pkRowStyle.Setters.Add(new Setter(Control.BorderBrushProperty,     pkGridLine));
                    pkRowStyle.Setters.Add(new Setter(Control.BorderThicknessProperty, new Thickness(0, 0, 0, 1)));
                    pkRowStyle.Setters.Add(new Setter(Control.PaddingProperty,         new Thickness(2, 3, 2, 3)));
                    pkRowStyle.Setters.Add(new Setter(Control.TemplateProperty,
                        DownloadsRowTemplate(pkHoverBg, pkSelBg, pkSelBd)));
                    list.ItemContainerStyle = pkRowStyle;

                    double wheelAccum = 0;
                    list.PreviewMouseWheel += (_, me) =>
                    {
                        var svw = FindVisualChild<ScrollViewer>(list);
                        if (svw == null) return;
                        wheelAccum += me.Delta / 120.0;
                        int rows = (int)wheelAccum;
                        if (rows != 0) { svw.ScrollToVerticalOffset(svw.VerticalOffset - rows); wheelAccum -= rows; }
                        me.Handled = true;
                    };
                    // The third column (Package ID / GitHub Repo) absorbs leftover width so the four
                    // columns fill the panel edge-to-edge with no horizontal scrollbar.
                    list.SizeChanged += (_, _) => list.Dispatcher.BeginInvoke(new Action(() =>
                    {
                        if (gv.Columns.Count < 4) return;
                        double others = gv.Columns[0].Width + gv.Columns[1].Width + gv.Columns[3].Width;
                        double fill = list.ActualWidth - others - 28;
                        if (fill > 160) gv.Columns[2].Width = fill;
                    }), System.Windows.Threading.DispatcherPriority.Loaded);

                    var hint = new TextBlock { Text = "", FontSize = 9.5, FontStyle = FontStyles.Italic, Foreground = secFg, Margin = new Thickness(0, 6, 0, 0) };

                    void DoRefresh()
                    {
                        refresh(search.Text?.Trim() ?? "", list, hint);
                        // Auto-select the nearest match (top-ranked hit) so no manual row click is
                        // needed; Add then applies whatever row is highlighted.
                        list.SelectedIndex = list.Items.Count > 0 ? 0 : -1;
                    }
                    search.TextChanged += (_, _) =>
                    {
                        placeholderTb.Visibility = string.IsNullOrEmpty(search.Text) ? Visibility.Visible : Visibility.Collapsed;
                        DoRefresh();
                    };

                    void Pick() { if (list.SelectedItem != null) apply(list.SelectedItem); }
                    list.MouseDoubleClick += (_, _) => Pick();

                    // No Select button: the nearest match is auto-selected on search and applied
                    // when Add is clicked. Double-click still applies a row immediately.
                    var stack = new StackPanel();
                    stack.Children.Add(searchHost);
                    stack.Children.Add(list);
                    stack.Children.Add(hint);

                    var panel = new Border
                    {
                        Background = bBg, BorderBrush = bBdr, BorderThickness = new Thickness(1),
                        CornerRadius = new CornerRadius(6), Padding = new Thickness(10),
                        Margin = new Thickness(0, 0, 0, ROW_GAP),
                        Visibility = Visibility.Collapsed,
                        Child = stack,
                    };
                    Grid.SetRow(panel, panelRow); Grid.SetColumn(panel, 0); Grid.SetColumnSpan(panel, 2);
                    cg.Children.Add(panel); r++;

                    bool loadedOnce = false;
                    void Show(bool on)
                    {
                        if (on)
                        {
                            if (!loadedOnce) { DoRefresh(); loadedOnce = true; }
                            panel.Visibility = Visibility.Visible;
                        }
                        else panel.Visibility = Visibility.Collapsed;
                    }
                    void Focus() { Show(true); search.Focus(); }
                    return (Show, Focus, Pick);
                }

                // Winget panel.
                var winget = BuildInlinePanel(
                    "Type here to search application",
                    (query, list, hint) =>
                    {
                        var hits = WingetCatalog.SearchPackages(query);
                        var hide = WingetHiddenIds();
                        if (hide.Count > 0) hits = hits.Where(p => !hide.Contains(p.Id)).ToList();
                        hits = hits.Where(p => !IsBetaPackage(p.Id, p.Name)).ToList();
                        list.ItemsSource = hits;
                        hint.Text = hits.Count > 0
                            ? $"{hits.Count:N0} package(s) - double-click a row to select"
                            : System.IO.File.Exists(WingetIndexPath)
                                ? "no match in the catalog"
                                : "the package catalog is still downloading - reopen this in a moment, "
                                + "or press Check now in the Applications Status window";
                    },
                    new[]
                    {
                        new GridViewColumn { Header = "Vendor",     Width = 120, DisplayMemberBinding = new System.Windows.Data.Binding("Id") { Converter = _idVendor } },
                        new GridViewColumn { Header = "Name",       Width = 180, DisplayMemberBinding = new System.Windows.Data.Binding("Name") },
                        new GridViewColumn { Header = "Package ID", Width = 240, DisplayMemberBinding = new System.Windows.Data.Binding("Id") },
                        new GridViewColumn { Header = "Version",    Width = 90,  DisplayMemberBinding = new System.Windows.Data.Binding("Version") },
                    },
                    sel => { if (sel is WingetCatalog.WingetPackage wp) ApplyPickedWinget(wp); });

                // GitHub panel.
                var github = BuildInlinePanel(
                    "Type here to search application",
                    (query, list, hint) =>
                    {
                        var hits = GitHubCatalog.Search(query).Where(a => !IsBetaPackage(a.Id, a.Name)).ToList();
                        list.ItemsSource = hits;
                        hint.Text = !GitHubCatalog.Available
                            ? "github_catalog.json not found - place it in the app's Templates folder"
                            : hits.Count == 0 ? "no match in the catalog"
                            : $"{hits.Count:N0} app(s) - double-click a row to select";
                    },
                    new[]
                    {
                        new GridViewColumn { Header = "Vendor",      Width = 120, DisplayMemberBinding = new System.Windows.Data.Binding("Vendor") },
                        new GridViewColumn { Header = "Name",        Width = 180, DisplayMemberBinding = new System.Windows.Data.Binding("Name") },
                        new GridViewColumn { Header = "GitHub Repo", Width = 240, DisplayMemberBinding = new System.Windows.Data.Binding("Repo") },
                        new GridViewColumn { Header = "Version",     Width = 90,  DisplayMemberBinding = new System.Windows.Data.Binding("Version") },
                    },
                    sel => { if (sel is GitHubApp a) ApplyPickedGitHub(a); });

                // Search icons focus the matching inline panel instead of opening a popup.
                focusInlineWinget = winget.focus;
                focusInlineGitHub = github.focus;
                applyInlineWinget = winget.applySelected;
                applyInlineGitHub = github.applySelected;

                syncInlinePanels = apiType =>
                {
                    winget.show(apiType.Equals("winget", StringComparison.OrdinalIgnoreCase));
                    github.show(apiType.Equals("github", StringComparison.OrdinalIgnoreCase));
                };
                // Show the panel for the API Type the dialog opened on (default winget).
                syncInlinePanels((cbApi.SelectedItem as string ?? "").Trim());
            }

            int catDataRow = r;
            var getCat    = MakeComboRow("Category",
                new[] { "Browser", "Communication", "Media", "PDF", "Runtime", "Security", "Utility", "Other" },
                string.IsNullOrWhiteSpace(existing?.Category) ? "Other" : existing.Category);
            // Rule Type follows Download Preference, same additive rule as the Package Information
            // column: tick the default for the new preference and never untick anything, so a
            // File / MSI / Registry combination chosen by hand survives switching back and forth.
            // The Rule Type checkboxes are built much further down (Intune settings), hence the
            // forward-declared Action.
            Action<string>? applyDlgRuleTypeForPreference = null;
            int dlPrefDataRow = r;
            var getDlPref = MakeRadioRow("Download Preference",
                new[] { "MSI_x64", "MSI_x86", "MSI_ARM64", "EXE_x64", "EXE_x86", "EXE_ARM64" },
                string.IsNullOrWhiteSpace(existing?.DownloadPreference) ? "MSI_x64" : existing.DownloadPreference,
                v => applyDlgRuleTypeForPreference?.Invoke(v));
            int lockPrefDataRow = r;
            var getLockPref = MakeRadioRow("Lock Download Preference",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.LockDownloadPreference) ? "No" : existing.LockDownloadPreference);

            // Add mode shows a slim form: only the Download Source pickers (API Type, the per-type
            // ID/URL, Download Page URL). Category, Download Preference and Lock Download Preference
            // are collapsed here (their getters still return the defaults, so save/logic is
            // unchanged); the user sets them later from the Package Information column. On Edit the
            // full form is shown, so this is skipped entirely.
            if (!isEdit)
            {
                void CollapseRow(int dataRow)
                {
                    if (dataRow >= 0 && dataRow < cg.RowDefinitions.Count)
                        cg.RowDefinitions[dataRow].Height = new GridLength(0);
                    if (dataRow + 1 < cg.RowDefinitions.Count)
                        cg.RowDefinitions[dataRow + 1].Height = new GridLength(0);   // trailing gap row
                    foreach (UIElement ch in cg.Children)
                        if (Grid.GetRow(ch) == dataRow) ch.Visibility = Visibility.Collapsed;
                }
                CollapseRow(catDataRow);
                CollapseRow(dlPrefDataRow);
                CollapseRow(lockPrefDataRow);
            }

            // Tick a Download Preference programmatically. MakeRadioRow wires its onChanged to
            // rb.Click, which a code-set IsChecked does not raise, so the Rule Type rule is driven
            // by hand here - otherwise the preference would move and the Rule Type would not follow.
            void SetDlgDownloadPreference(string rawPref)
            {
                if (!addAppRadioPanels.TryGetValue("Download Preference", out var wpPref) || wpPref == null) return;
                string display = rawPref.Replace('_', ' ');
                bool hit = false;
                foreach (var rbPref in wpPref.Children.OfType<RadioButton>())
                {
                    bool on = (rbPref.Content?.ToString() ?? "").Equals(display, StringComparison.OrdinalIgnoreCase);
                    rbPref.IsChecked = on;
                    if (on) hit = true;
                }
                if (hit) applyDlgRuleTypeForPreference?.Invoke(rawPref);
            }

            // The picker footer reports what a package actually ships (MSI only / EXE only /
            // MSI + EXE). An EXE-only package can never satisfy an MSI preference, so align the
            // preference with it - and, through the rule above, the Rule Type with the preference.
            // MSI + EXE and unknown are left alone: both are genuine choices, not a single answer.
            // Fire-and-forget: WingetCommandsAsync is memory-cached, so the lookup the picker just
            // did usually makes this instant, and a failure leaves the defaults untouched.
            applyWingetInstallerType = async (id, version) =>
            {
                try
                {
                    var meta = await WingetCommandsAsync(id, version);
                    // Ignore a late result if the user has since picked a different package.
                    if ((txWinget.Text ?? "").Trim() != id) return;
                    string pref = string.Equals(meta.type, "EXE only", StringComparison.OrdinalIgnoreCase) ? "EXE_x64"
                                : string.Equals(meta.type, "MSI only", StringComparison.OrdinalIgnoreCase) ? "MSI_x64"
                                : "";
                    if (pref.Length > 0) SetDlgDownloadPreference(pref);
                }
                catch (Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] installer type: " + exSwallow.Message); }
            };

            // ── App Identity ───────────────────────────────────────────────
            // Built here, below Download Source, so the picker that fills these sits above them.
            MakeSection("App Identity");
            txVend   = MakeRow("Source App Vendor",   existing?.SourceAppVendor   ?? "", required: true);
            txName   = MakeRow("Source App Name",     existing?.SourceAppName     ?? "", required: true);
            txSrcVer = MakeRow("Source App Version",  existing?.SourceAppVersion  ?? "", required: true);

            // ── Download Schedule ──────────────────────────────────────────
            MakeSection("Download Schedule");

            // Auto Download Source radio — default No
            var getSrcDl = MakeRadioRow("Auto Download Source",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.AutoDownloadSource) ? "No" : existing.AutoDownloadSource);

            // Helper: makes a combo row wrapped in a single-row StackPanel so we can
            // collapse the entire row (label + combo + spacer) with one Visibility toggle.
            (StackPanel wrapper, ComboBox cb) MakeScheduleCombo(string label, string[] options, string defaultVal)
            {
                var lb2 = new TextBlock { Text = label, FontSize = 11, FontWeight = FontWeights.SemiBold,
                    Foreground = lFg, VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 0, 8, 0) };
                var cb2 = new ComboBox { FontSize = 11, BorderThickness = new Thickness(0), Background = Brushes.Transparent };
                foreach (var opt in options) cb2.Items.Add(opt);
                var matchIdx = options.ToList().FindIndex(o => o.Equals(defaultVal, StringComparison.OrdinalIgnoreCase));
                cb2.SelectedIndex = matchIdx >= 0 ? matchIdx : 0;

                var brd2 = new Border { Background = bBg, BorderBrush = bBdr, BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(6), ClipToBounds = true, Child = cb2,
                    Height = 28, VerticalAlignment = VerticalAlignment.Center };

                var dp = new DockPanel { Margin = new Thickness(0, 0, 0, ROW_GAP), LastChildFill = true };
                lb2.Width = 160;
                DockPanel.SetDock(lb2, Dock.Left);
                dp.Children.Add(lb2);
                dp.Children.Add(brd2);

                var wrapper = new StackPanel();
                wrapper.Children.Add(dp);
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                Grid.SetRow(wrapper, r); Grid.SetColumnSpan(wrapper, 2);
                cg.Children.Add(wrapper); r++;
                return (wrapper, cb2);
            }

            var (wFreq,  cbFreq)  = MakeScheduleCombo("Download Frequency",
                new[] { "Hourly", "Daily", "Weekly", FREQ_EVERY_2_WEEKS, "Monthly", "Quarterly", "HalfYearly", "Yearly", "Every" },
                string.IsNullOrWhiteSpace(existing?.DownloadFrequency) || existing.DownloadFrequency == "None" ? "Hourly"
                    : IsEvery2Weeks(existing.DownloadFrequency) ? FREQ_EVERY_2_WEEKS   // old "Fortnightly" -> renamed item
                    : existing.DownloadFrequency);

            // Schedule Hour — "Every [N] Hours" row using same grid pattern
            var cbHour = new ComboBox { Height = 26, FontSize = 11, Width = 52, HorizontalContentAlignment = HorizontalAlignment.Center };
            // Use app's rounded ComboBox style if available
            if (Application.Current.Resources.Contains("ModernComboBoxStyle"))
                cbHour.Style = (System.Windows.Style)Application.Current.Resources["ModernComboBoxStyle"];
            foreach (var h in Enumerable.Range(1, 12)) cbHour.Items.Add(h.ToString("D2"));
            string savedHour = existing?.DownloadScheduleHour ?? "";
            cbHour.SelectedItem = string.IsNullOrWhiteSpace(savedHour) ? "02" : savedHour.PadLeft(2, '0');
            if (cbHour.SelectedIndex < 0) cbHour.SelectedIndex = 1;

            // Build the value panel: "Every [cbHour] Hours"
            var pnlHour = new StackPanel { Orientation = Orientation.Horizontal };
            pnlHour.Children.Add(new TextBlock { Text = "Every  ", Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, FontSize = 11 });
            pnlHour.Children.Add(cbHour);
            pnlHour.Children.Add(new TextBlock { Text = " Hours", Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, FontSize = 11, Margin = new Thickness(6,0,0,0) });

            // Add to grid same way MakeScheduleCombo does
            int rHour = r;
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var lblHour = new TextBlock { Text = "Schedule Hour", FontWeight = FontWeights.SemiBold, FontSize = 11,
                Foreground = lFg,
                VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0,4,0,4) };
            Grid.SetRow(lblHour, r); Grid.SetColumn(lblHour, 0); cg.Children.Add(lblHour);
            Grid.SetRow(pnlHour, r); Grid.SetColumn(pnlHour, 1); cg.Children.Add(pnlHour);
            r++;
            // wHour not needed - visibility managed via lblHour + pnlHour directly

            // Schedule Occurrence — "Every month [First▾]" row  (shown for "Every" frequency)
            var cbOccurrence = new ComboBox { Height = 26, FontSize = 11, Width = 110 };
            if (Application.Current.Resources.Contains("ModernComboBoxStyle"))
                cbOccurrence.Style = (System.Windows.Style)Application.Current.Resources["ModernComboBoxStyle"];
            foreach (var occ in new[] { "First", "Second", "Third", "Fourth" })
                cbOccurrence.Items.Add(occ);
            string savedOcc = existing?.DownloadOccurrence ?? "";
            cbOccurrence.SelectedItem = string.IsNullOrWhiteSpace(savedOcc) ? "Second" : savedOcc;
            if (cbOccurrence.SelectedIndex < 0) cbOccurrence.SelectedItem = "Second";

            var pnlOccurrence = new StackPanel { Orientation = Orientation.Horizontal };
            pnlOccurrence.Children.Add(new TextBlock { Text = "Every month  ", Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, FontSize = 11 });
            pnlOccurrence.Children.Add(cbOccurrence);

            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            var lblOccurrence = new TextBlock { Text = "Occurrence", FontWeight = FontWeights.SemiBold, FontSize = 11,
                Foreground = lFg,
                VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0,4,0,10) };
            Grid.SetRow(lblOccurrence, r); Grid.SetColumn(lblOccurrence, 0); cg.Children.Add(lblOccurrence);
            Grid.SetRow(pnlOccurrence, r); Grid.SetColumn(pnlOccurrence, 1); cg.Children.Add(pnlOccurrence);
            r++;
            var wOccurrence = lblOccurrence;

            // Schedule Days - "Starting from [Day]" row
            var cbDays = new ComboBox { Height = 26, FontSize = 11, Width = 120 };
            if (Application.Current.Resources.Contains("ModernComboBoxStyle"))
                cbDays.Style = (System.Windows.Style)Application.Current.Resources["ModernComboBoxStyle"];
            foreach (var d in new[] { "Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday" })
                cbDays.Items.Add(d);
            string savedDay = existing?.DownloadScheduleDays ?? "";
            cbDays.SelectedItem = string.IsNullOrWhiteSpace(savedDay) ? "Monday" : savedDay;
            if (cbDays.SelectedIndex < 0) cbDays.SelectedItem = "Monday";

            var pnlDays = new StackPanel { Orientation = Orientation.Horizontal };
            var lbDaysPrefix = new TextBlock { Text = "Starting from  ", Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, FontSize = 11 };
            pnlDays.Children.Add(lbDaysPrefix);
            pnlDays.Children.Add(cbDays);

            // Built here, PLACED with the rest of the date rows further down.
            var lblDays = new TextBlock { Text = "Schedule Days", FontWeight = FontWeights.SemiBold, FontSize = 11,
                Foreground = lFg,
                VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0,4,0,10) };
            var wDays = lblDays;

            // Schedule Date — "On day [DD]" row
            var cbDate = new ComboBox { Height = 26, FontSize = 11, Width = 62,
                HorizontalContentAlignment = HorizontalAlignment.Center };
            if (Application.Current.Resources.Contains("ModernComboBoxStyle"))
                cbDate.Style = (System.Windows.Style)Application.Current.Resources["ModernComboBoxStyle"];
            foreach (var d in Enumerable.Range(1, 31)) cbDate.Items.Add(d.ToString("D2"));
            string savedDate = existing?.DownloadScheduleDate ?? "";
            cbDate.SelectedItem = string.IsNullOrWhiteSpace(savedDate) ? "01"
                : savedDate.PadLeft(2, '0');
            if (cbDate.SelectedIndex < 0) cbDate.SelectedItem = "01";

            var pnlDate = new StackPanel { Orientation = Orientation.Horizontal };
            pnlDate.Children.Add(new TextBlock { Text = "Starting from  ", Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, FontSize = 11 });
            pnlDate.Children.Add(cbDate);

            // Built here, PLACED with the rest of the date rows further down.
            var lblDate = new TextBlock { Text = "Schedule Date", FontWeight = FontWeights.SemiBold, FontSize = 11,
                Foreground = lFg,
                VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0,4,0,10) };
            var wDate = lblDate;

            // Schedule Time — custom "At [HH] Hours [MM] Minutes" row
            var cbTimeHour = new ComboBox { Height = 26, FontSize = 11, Width = 52,
                HorizontalContentAlignment = HorizontalAlignment.Center };
            var cbTimeMin  = new ComboBox { Height = 26, FontSize = 11, Width = 52,
                HorizontalContentAlignment = HorizontalAlignment.Center };
            if (Application.Current.Resources.Contains("ModernComboBoxStyle"))
            {
                cbTimeHour.Style = (System.Windows.Style)Application.Current.Resources["ModernComboBoxStyle"];
                cbTimeMin.Style  = (System.Windows.Style)Application.Current.Resources["ModernComboBoxStyle"];
            }
            foreach (var h in Enumerable.Range(0, 24)) cbTimeHour.Items.Add(h.ToString("D2"));   // 00..23, see the panel
            foreach (var m in new[] { 0,5,10,15,20,25,30,35,40,45,50,55 }) cbTimeMin.Items.Add(m.ToString("D2"));

            // Parse existing saved time "HH:MM"
            string savedTime = existing?.DownloadScheduleTime ?? "";
            string[] timeParts = savedTime.Split(':');
            string dlgHh = timeParts.Length > 0 && !string.IsNullOrWhiteSpace(timeParts[0]) ? timeParts[0].PadLeft(2,'0') : "06";
            if (dlgHh == "24") dlgHh = "00";   // legacy "end of day" value retired; show midnight
            cbTimeHour.SelectedItem = dlgHh;
            cbTimeMin.SelectedItem  = timeParts.Length > 1 && !string.IsNullOrWhiteSpace(timeParts[1]) ? timeParts[1].PadLeft(2,'0') : "00";
            if (cbTimeHour.SelectedIndex < 0) cbTimeHour.SelectedItem = "06";
            if (cbTimeMin.SelectedIndex  < 0) cbTimeMin.SelectedItem  = "00";

            // Build "At [HH] Hours [MM] Minutes" panel. The prefix is captured because Hourly reads
            // "Starting from" instead: there the time is the phase the interval counts from, not the
            // moment of a run. UpdateScheduleVisibility owns the wording, as it does for the weekday.
            var lbTimePrefix = new TextBlock { Text = "At  ", Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, FontSize = 11 };
            var pnlTime = new StackPanel { Orientation = Orientation.Horizontal };
            pnlTime.Children.Add(lbTimePrefix);
            pnlTime.Children.Add(cbTimeHour);
            pnlTime.Children.Add(new TextBlock { Text = "  Hours  ", Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, FontSize = 11 });
            pnlTime.Children.Add(cbTimeMin);
            pnlTime.Children.Add(new TextBlock { Text = "  Minutes", Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, FontSize = 11 });

            // Built here but PLACED after the month and year rows below, so the schedule reads day,
            // then month, then year, then time.
            var lblTime = new TextBlock { Text = "Schedule Time", FontWeight = FontWeights.SemiBold, FontSize = 11,
                Foreground = lFg,
                VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0,10,0,4) };
            var wTime = lblTime; // visibility handle

            // cbTime getter — returns "HH:MM" combined
            ComboBox cbTime = cbTimeHour; // kept for dirty tracking wire-up

            // Schedule Month — "Starting from [Month]" row
            var cbMonth = new ComboBox { Height = 26, FontSize = 11, Width = 130 };
            if (Application.Current.Resources.Contains("ModernComboBoxStyle"))
                cbMonth.Style = (System.Windows.Style)Application.Current.Resources["ModernComboBoxStyle"];
            foreach (var mo in new[] { "January","February","March","April","May","June",
                                       "July","August","September","October","November","December" })
                cbMonth.Items.Add(mo);
            string savedMonth = existing?.DownloadScheduleMonth ?? "";
            cbMonth.SelectedItem = string.IsNullOrWhiteSpace(savedMonth) ? "January" : savedMonth;
            if (cbMonth.SelectedIndex < 0) cbMonth.SelectedItem = "January";

            var pnlMonth = new StackPanel { Orientation = Orientation.Horizontal };
            pnlMonth.Children.Add(new TextBlock { Text = "Starting from  ", Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, FontSize = 11 });
            pnlMonth.Children.Add(cbMonth);

            // Schedule Year - its own row under the month. Day, month and year together are the
            // first run of the series, and nothing fires before it.
            var cbYear = new ComboBox { Height = 26, FontSize = 11, Width = 96 };
            if (Application.Current.Resources.Contains("ModernComboBoxStyle"))
                cbYear.Style = (System.Windows.Style)Application.Current.Resources["ModernComboBoxStyle"];
            for (int y = DateTime.Now.Year - 1; y <= DateTime.Now.Year + 10; y++) cbYear.Items.Add(y.ToString());
            string savedYear = (existing?.DownloadScheduleYear ?? "").Trim();
            // A stored year outside the offered range is added rather than silently replaced.
            if (savedYear.Length > 0 && !cbYear.Items.Contains(savedYear)) cbYear.Items.Insert(0, savedYear);
            cbYear.SelectedItem = savedYear.Length > 0 ? savedYear : DateTime.Now.Year.ToString();
            if (cbYear.SelectedIndex < 0) cbYear.SelectedItem = DateTime.Now.Year.ToString();

            var pnlYear = new StackPanel { Orientation = Orientation.Horizontal };
            pnlYear.Children.Add(new TextBlock { Text = "Starting from  ", Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, FontSize = 11 });
            pnlYear.Children.Add(cbYear);

            // February is 28 days, or 29 in a leap year, and four months have 30 - so the day list
            // follows the month and year that are selected, for every frequency, and a stored day
            // the new month cannot hold is pulled back to the last day of it.
            void SyncDialogDateItems()
            {
                int mo3 = cbMonth.SelectedIndex + 1;
                if (mo3 < 1 || mo3 > 12) mo3 = 1;
                int? yr3 = int.TryParse(cbYear.SelectedItem as string ?? "", out int py3) ? py3 : (int?)null;
                int days3 = DaysInScheduleMonth(yr3, mo3);
                if (cbDate.Items.Count == days3) return;

                string cur3 = cbDate.SelectedItem as string ?? "01";
                cbDate.Items.Clear();
                foreach (var d in Enumerable.Range(1, days3)) cbDate.Items.Add(d.ToString("D2"));
                int want3 = int.TryParse(cur3, out int c3) && c3 >= 1 ? Math.Min(c3, days3) : 1;
                cbDate.SelectedItem = want3.ToString("D2");
            }
            // The weekday is a fact about the start date, not a separate choice: 1 February 2026 IS
            // a Sunday. So it fills itself in from year + month + date, while staying editable -
            // Weekly and Every read it as "which weekday to run", which need not be the weekday the
            // series happens to start on.
            void SyncDialogDerivedDay()
            {
                // Only where the weekday is part of the schedule; elsewhere the row is hidden and
                // the field is saved blank. "Every" is excluded: its weekday is a real choice paired
                // with the occurrence, and it has no date row to read one from.
                string fDerive = cbFreq.SelectedItem?.ToString()?.Trim() ?? "";
                if (!ScheduleFieldsFor(fDerive).Days || fDerive == "Every") return;
                int mo4 = cbMonth.SelectedIndex + 1;
                if (mo4 < 1 || mo4 > 12) mo4 = 1;
                if (!int.TryParse(cbYear.SelectedItem as string ?? "", out int yr4)) return;
                if (!int.TryParse(cbDate.SelectedItem as string ?? "", out int dd4)) return;
                string dayName = new DateTime(yr4, mo4, ScheduleDayIn(dd4, yr4, mo4)).DayOfWeek.ToString();
                if ((cbDays.SelectedItem as string ?? "") == dayName) return;
                cbDays.SelectedItem = dayName;
            }
            cbMonth.SelectionChanged += (_, _) => { SyncDialogDateItems(); SyncDialogDerivedDay(); };
            cbYear.SelectionChanged  += (_, _) => { SyncDialogDateItems(); SyncDialogDerivedDay(); };
            cbDate.SelectionChanged  += (_, _) => SyncDialogDerivedDay();

            var lblMonth = new TextBlock { Text = "Schedule Month", FontWeight = FontWeights.SemiBold, FontSize = 11,
                Foreground = lFg,
                VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0,4,0,10) };
            var wMonth = lblMonth;

            var lblYear = new TextBlock { Text = "Schedule Year", FontWeight = FontWeights.SemiBold, FontSize = 11,
                Foreground = lFg,
                VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0,4,0,10) };
            var wYear = lblYear;

            // All five rows are PLACED here, in reading order: one date from its widest part down -
            // year, month, day of the month, the weekday that date falls on - and then the time of
            // day. They are built further up in whatever order their dependencies allow.
            void PlaceScheduleRow(UIElement label, UIElement content)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                Grid.SetRow(label,   r); Grid.SetColumn(label,   0); cg.Children.Add(label);
                Grid.SetRow(content, r); Grid.SetColumn(content, 1); cg.Children.Add(content);
                r++;
            }
            PlaceScheduleRow(lblYear,  pnlYear);
            PlaceScheduleRow(lblMonth, pnlMonth);
            PlaceScheduleRow(lblDate,  pnlDate);
            PlaceScheduleRow(lblDays,  pnlDays);
            PlaceScheduleRow(lblTime,  pnlTime);


            // Getter lambdas
            Func<string> getFreq  = () => cbFreq.SelectedItem?.ToString()?.Trim()  ?? "";
            Func<string> getDays  = () => cbDays.SelectedItem?.ToString()?.Trim() ?? "Monday";
            Func<string> getDate  = () => cbDate.SelectedItem?.ToString()?.Trim() ?? "01";
            Func<string> getTime  = () => $"{cbTimeHour.SelectedItem?.ToString()?.Trim() ?? "06"}:{cbTimeMin.SelectedItem?.ToString()?.Trim() ?? "00"}";
            Func<string> getHour  = () => cbHour.SelectedItem?.ToString()?.Trim()  ?? "";
            Func<string> getMonth = () => cbMonth.SelectedItem?.ToString()?.Trim() ?? "January";
            Func<string> getYear  = () => cbYear.SelectedItem?.ToString()?.Trim() ?? DateTime.Now.Year.ToString();
            Func<string> getOccurrence = () => cbOccurrence.SelectedItem?.ToString()?.Trim() ?? "Second";

            // Master visibility update — reads SelectedItem so always in sync
            void UpdateScheduleVisibility()
            {
                bool srcYes = getSrcDl() == "Yes";
                string freq = cbFreq.SelectedItem?.ToString()?.Trim() ?? "";

                wFreq.Visibility = srcYes ? Visibility.Visible : Visibility.Collapsed;
                // Default to Hourly when enabling Auto Download Source
                if (srcYes && (cbFreq.SelectedItem?.ToString() == "None" || cbFreq.SelectedItem == null))
                    cbFreq.SelectedItem = "Hourly";

                if (!srcYes) { lblHour.Visibility = pnlHour.Visibility = lblDays.Visibility = pnlDays.Visibility = lblDate.Visibility = pnlDate.Visibility = lblTime.Visibility = pnlTime.Visibility = lblMonth.Visibility = pnlMonth.Visibility = lblYear.Visibility = pnlYear.Visibility = wOccurrence.Visibility = pnlOccurrence.Visibility = Visibility.Collapsed; return; }
                // Same single rule the schedule panel and the save block read.
                var use = ScheduleFieldsFor(freq);

                lblHour.Visibility  = pnlHour.Visibility  = use.Hour       ? Visibility.Visible : Visibility.Collapsed;
                lblYear.Visibility  = pnlYear.Visibility  = use.Month      ? Visibility.Visible : Visibility.Collapsed;
                lblMonth.Visibility = pnlMonth.Visibility = use.Month      ? Visibility.Visible : Visibility.Collapsed;
                lblDate.Visibility  = pnlDate.Visibility  = use.Date       ? Visibility.Visible : Visibility.Collapsed;
                lblDays.Visibility  = pnlDays.Visibility  = use.Days       ? Visibility.Visible : Visibility.Collapsed;
                lblTime.Visibility  = pnlTime.Visibility  = use.Time       ? Visibility.Visible : Visibility.Collapsed;
                wOccurrence.Visibility = pnlOccurrence.Visibility = use.Occurrence ? Visibility.Visible : Visibility.Collapsed;

                // One start date across the four rows. "Every" is the exception: there the weekday
                // pairs with the occurrence and reads as "the Fourth Friday".
                lbDaysPrefix.Text = freq == "Every" ? "" : "Starting from  ";

                // On Hourly the time is part of that same start: the interval is counted from it.
                lbTimePrefix.Text = freq.Equals("Hourly", StringComparison.OrdinalIgnoreCase)
                                  ? "Starting from  " : "At  ";

                // The frequency decides whether the day list is measured against the chosen month,
                // so it is re-checked here as well as when a month or year is picked.
                SyncDialogDateItems();

                // Only "Every" lets the weekday be picked - there it pairs with the occurrence. Every
                // other frequency reads it off the start date, so it is locked, and re-derived here
                // rather than only on a date change: a locked field has to be right on its own.
                bool dayIsChosen = freq == "Every";
                cbDays.IsEnabled = dayIsChosen;
                cbDays.ToolTip   = dayIsChosen ? null : "Set by the schedule date above";
                if (!dayIsChosen) SyncDialogDerivedDay();
            }

            // Wire Auto Download Source radio buttons - all Yes/No radios before the freq combo row.
            // MakeRadioRow builds its radio container as a WrapPanel, so match Panel (not just
            // StackPanel) or the Auto Download Source toggle never reaches UpdateScheduleVisibility
            // and the schedule fields stay hidden.
            foreach (var sp2 in cg.Children.OfType<Panel>()
                .Where(sp => Grid.GetRow(sp) < Grid.GetRow(wFreq)))
                foreach (var rb in sp2.Children.OfType<RadioButton>())
                    rb.Checked += (_, _) => UpdateScheduleVisibility();

            // Wire frequency combo — SelectionChanged fires immediately on dropdown pick
            // UpdateScheduleVisibility owns the days prefix. A second setter used to run here, right
            // after it, reaching into pnlDays.Children[0] by index and putting "On" back - which is
            // exactly the kind of duplicate that survives a rename of the first one.
            cbFreq.SelectionChanged += (_, _) => UpdateScheduleVisibility();

            // Apply initial state synchronously right now (no Loaded needed)
            UpdateScheduleVisibility();

            // ── Silent Parameters ──────────────────────────────────────────
            StackPanel wUninstPath = new StackPanel(); // assigned with the real panel below
            MakeSection("Silent Parameters");
            var txSiMSI     = MakeRow("Silent Install MSI",      string.IsNullOrWhiteSpace(existing?.SilentInstallParameterMSI)   ? "/qn /norestart" : existing.SilentInstallParameterMSI);
            var txSuMSI     = MakeRow("Silent Uninstall MSI",    string.IsNullOrWhiteSpace(existing?.SilentUninstallParameterMSI) ? "/qn /norestart" : existing.SilentUninstallParameterMSI);
            var txSiEXE     = MakeRow("Silent Install EXE",      existing?.SilentInstallParameterEXE   ?? "");
            var txSuEXE     = MakeRow("Silent Uninstall EXE",    existing?.SilentUninstallParameterEXE ?? "");

            // Clears the EXE silent switches when the source changes, and leaves them clear.
            //
            // A table of well-known winget package ids used to fill them in instantly, each mapped
            // to its installer framework's switch. It is gone, with every other compiled list of
            // other people's software. Nothing is lost but a second: the id is
            // then handed to ManifestSilentEXE below, which reads the real installer manifest and
            // fills the same two boxes from what the publisher actually declares. That always
            // overwrote this guess anyway.
            //
            // MSI stays /qn /norestart (universal) and is not touched here.
            string autoSiEXE = "", autoSuEXE = "";
            void AutoFillSilentEXE()
            {
                if (string.IsNullOrWhiteSpace(txSiEXE.Text) || txSiEXE.Text == autoSiEXE) txSiEXE.Text = "";
                if (string.IsNullOrWhiteSpace(txSuEXE.Text) || txSuEXE.Text == autoSuEXE) txSuEXE.Text = "";
                autoSiEXE = ""; autoSuEXE = "";
            }
            cbApi.SelectionChanged += (_, _) => AutoFillSilentEXE();
            refreshSilentEXE = AutoFillSilentEXE;
            // Refine the EXE silent switches from the picked package's real winget manifest (the local
            // catalog has no switches). Fetches {id}.installer.yaml from the same raw.githubusercontent
            // CDN the downloader uses (no API quota), reads InstallerSwitches.Silent, and infers from
            // InstallerType when absent. Best-effort and fire-and-forget: failures leave the fields as
            // they are, and a stale result is ignored if the user has moved on.
            async Task ManifestSilentEXE(string id, string version)
            {
                var meta = await WingetCommandsAsync(id, version);
                string si = meta.install, su = meta.uninstall;
                if (si.Length == 0 && su.Length == 0) return;
                // Ignore if the user has since changed source or picked a different package.
                if ((cbApi.SelectedItem as string ?? "").Trim().ToLowerInvariant() != "winget") return;
                if ((txWinget.Text ?? "").Trim() != id) return;
                if (string.IsNullOrWhiteSpace(txSiEXE.Text) || txSiEXE.Text == autoSiEXE) { txSiEXE.Text = si; autoSiEXE = si; }
                if (su.Length > 0 && (string.IsNullOrWhiteSpace(txSuEXE.Text) || txSuEXE.Text == autoSuEXE)) { txSuEXE.Text = su; autoSuEXE = su; }
            }
            fetchManifestSilentEXE = (id, version) => { pendingSilentFetch = ManifestSilentEXE(id, version); };
            // Same idea for GitHub-hosted apps: they ARE winget packages, so the winget id (carried in
            // the GitHub catalog) fetches the exact same manifest and switches. Guard on API Type =
            // github + the current repo so a stale/late result cannot overwrite a changed selection.
            async Task ManifestSilentEXEForGitHub(string id, string version, string repo)
            {
                if (string.IsNullOrWhiteSpace(id)) return;
                var meta = await WingetCommandsAsync(id, version);
                string si = meta.install, su = meta.uninstall;
                if (si.Length == 0 && su.Length == 0) return;
                if ((cbApi.SelectedItem as string ?? "").Trim().ToLowerInvariant() != "github") return;
                if ((txRepo.Text ?? "").Trim() != repo) return;
                if (string.IsNullOrWhiteSpace(txSiEXE.Text) || txSiEXE.Text == autoSiEXE) { txSiEXE.Text = si; autoSiEXE = si; }
                if (su.Length > 0 && (string.IsNullOrWhiteSpace(txSuEXE.Text) || txSuEXE.Text == autoSuEXE)) { txSuEXE.Text = su; autoSuEXE = su; }
            }
            fetchGitHubSilentEXE = (id, version, repo) => { pendingSilentFetch = ManifestSilentEXEForGitHub(id, version, repo); };
            // Uninstall Path row — wrapped in StackPanel for clean show/hide (no empty space)
            var lbUninstPath = new TextBlock { Text = "Uninstall Path", FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 0) };
            var txUninstPath = new TextBox { Text = existing?.UninstallPath ?? "", FontSize = 11, Height = 28, Style = tbStyle, Background = bBg, BorderBrush = bBdr, Padding = new Thickness(8, 0, 8, 0) };

            // Use a sub-Grid with same column widths as the parent cg so textbox aligns perfectly
            var gUninstPath = new Grid { Margin = new Thickness(0, 0, 0, ROW_GAP) };
            gUninstPath.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(160) });
            gUninstPath.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            gUninstPath.RowDefinitions.Add(new RowDefinition { Height = new GridLength(28) });
            Grid.SetColumn(lbUninstPath, 0); Grid.SetColumn(txUninstPath, 1);
            gUninstPath.Children.Add(lbUninstPath); gUninstPath.Children.Add(txUninstPath);

            wUninstPath = new StackPanel();
            wUninstPath.Children.Add(gUninstPath);
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            Grid.SetRow(wUninstPath, r); Grid.SetColumnSpan(wUninstPath, 2);
            cg.Children.Add(wUninstPath); r++;
            txUninstPath.TextChanged += MarkDirtyText;
            var getInstSil  = MakeRadioRow("Install Source Silently",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.InstallSourceSilently) ? "Yes" : existing.InstallSourceSilently);
            var getUninstSil = MakeRadioRow("Uninstall Source Silently",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.UninstallSourceSilently) ? "Yes" : existing.UninstallSourceSilently);

            // ── Package Settings ───────────────────────────────────────────
            MakeSection("Package Settings");
            Func<string> getCreateMst     = () => "No";
            Func<string> getRemoveDesktop  = () => "No";
            Action updateUninstallPathVisibility = () => { };
            // Forward-declared so the scoped block and UpdateUninstallPathVisibility can reference them
            StackPanel? spCreateMst = null, spRemoveDesktop = null;
            // (wUninstPath is declared just before the Silent Parameters section,
            // where the Uninstall Path row is now built.)
            // Create Package sits at the top of Package Settings (above Create MST).
            var getCreatePkg = MakeRadioRow("Create Package",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.CreatePackage) ? "Yes" : existing.CreatePackage);
            {
                var (getMst, lbMst, spMst, rowMst, gapMst) = MakeRadioRowEx("Create MST",
                    new[] { "Yes", "No" },
                    string.IsNullOrWhiteSpace(existing?.CreateMST) ? "No" : existing.CreateMST);
                var (getRem, lbRem, spRem, rowRem, gapRem) = MakeRadioRowEx("Remove Desktop Shortcut",
                    new[] { "Yes", "No" },
                    string.IsNullOrWhiteSpace(existing?.RemoveDesktopShortcut) ? "Yes" : existing.RemoveDesktopShortcut);
                getCreateMst    = getMst;
                getRemoveDesktop = getRem;
                spCreateMst     = spMst;
                spRemoveDesktop = spRem;

                // Remove Desktop Shortcut is editable only when Create MST = Yes; when No, force it to No + disable.
                {
                    var mstY = spMst.Children.OfType<RadioButton>().FirstOrDefault(rb => (rb.Content as string) == "Yes");
                    var mstN = spMst.Children.OfType<RadioButton>().FirstOrDefault(rb => (rb.Content as string) == "No");
                    var remN = spRem.Children.OfType<RadioButton>().FirstOrDefault(rb => (rb.Content as string) == "No");
                    void SyncRemoveDesktop()
                    {
                        bool mstOn = mstY?.IsChecked == true;
                        spRem.IsEnabled = mstOn;
                        if (!mstOn && remN != null) remN.IsChecked = true;
                    }
                    if (mstY != null) mstY.Checked += (_, _) => SyncRemoveDesktop();
                    if (mstN != null) mstN.Checked += (_, _) => SyncRemoveDesktop();
                    SyncRemoveDesktop();
                }

                void UpdateUninstallPathVisibility()
                {
                    // Uninstall Path stays visible for every download preference —
                    // parity with the Package Information column, which always shows it.
                    bool isMsi = !getDlPref().StartsWith("EXE", StringComparison.OrdinalIgnoreCase);
                    wUninstPath.Visibility     = Visibility.Visible;
                    var vis  = isMsi ? Visibility.Visible : Visibility.Collapsed;
                    var dataH = isMsi ? new GridLength(28)      : new GridLength(0);
                    var gapH  = isMsi ? new GridLength(ROW_GAP) : new GridLength(0);
                    lbMst.Visibility = vis; spMst.Visibility = vis;
                    lbRem.Visibility = vis; spRem.Visibility = vis;
                    if (rowMst < cg.RowDefinitions.Count) cg.RowDefinitions[rowMst].Height = dataH;
                    if (gapMst < cg.RowDefinitions.Count) cg.RowDefinitions[gapMst].Height = gapH;
                    if (rowRem < cg.RowDefinitions.Count) cg.RowDefinitions[rowRem].Height = dataH;
                    if (gapRem < cg.RowDefinitions.Count) cg.RowDefinitions[gapRem].Height = gapH;
                }
                updateUninstallPathVisibility = UpdateUninstallPathVisibility; // expose to outer scope

                // Wire Download Preference radio buttons to update visibility
                foreach (var sp2 in cg.Children.OfType<StackPanel>())
                {
                    var rbs2 = sp2.Children.OfType<RadioButton>().ToList();
                    if (rbs2.Count == 4 && rbs2[0].Content?.ToString() == "MSI x64")
                        foreach (var rb in rbs2)
                            rb.Checked += (_, _) => { UpdateUninstallPathVisibility(); reapplyDlgTab?.Invoke(); };
                }
                UpdateUninstallPathVisibility(); // set initial state
            }

            // ── Template Folder row with folder icon inside the textbox ───
            //
            // On ADD there is no `existing`, so this used to open blank and every new app had to
            // have the path typed or browsed again. It now falls back to PSADTTemplateFolder from
            // AutoPackage.json (Settings > Paths).
            //
            // Edit is deliberately NOT defaulted. An existing app that was saved with an empty
            // folder meant it on purpose, and quietly filling it on open would rewrite that choice
            // the next time the user pressed Save without touching the row.
            string tplDefault = isEdit ? (existing?.PSADTTemplateFolder ?? "")
                                       : (!string.IsNullOrWhiteSpace(existing?.PSADTTemplateFolder)
                                             ? existing!.PSADTTemplateFolder
                                             : (_psadtTemplateFolder ?? "").Trim());
            TextBox txTemplateFolder;
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var lb = new TextBlock { Text = "PSADT Template Folder", FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lFg, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 0) };
                // TextBox with extra right padding to leave room for the icon inside
                var tx = new TextBox { Text = tplDefault, FontSize = 11, Height = 28, Style = tbStyle, Background = bBg, BorderBrush = bBdr, Foreground = lFg, Padding = new Thickness(8, 0, 32, 0) };
                // Icon button overlaid on the right inside the textbox
                var browseBtn = new Button
                {
                    Content = "📁", FontSize = 12,
                    Width = 28, Height = 28,
                    Background = Brushes.Transparent, BorderThickness = new Thickness(0),
                    Foreground = lFg, Cursor = System.Windows.Input.Cursors.Hand,
                    HorizontalAlignment = HorizontalAlignment.Right,
                    VerticalAlignment = VerticalAlignment.Center,
                    ToolTip = "Browse for PSADT Template Folder",
                    Padding = new Thickness(0),
                };
                browseBtn.Click += (_, _) =>
                {
                    var hwnd = new System.Windows.Interop.WindowInteropHelper(win).Handle;
                    string? picked = ShellFolderPicker.Browse(hwnd,
                        "Select PSADT Template Folder",
                        string.IsNullOrWhiteSpace(tx.Text) ? null : tx.Text);
                    if (picked != null) tx.Text = picked;
                };
                // Overlay: Grid with textbox filling all space, button on top-right
                var overlay = new Grid();
                overlay.Children.Add(tx);
                overlay.Children.Add(browseBtn);
                Grid.SetRow(lb,      r); Grid.SetColumn(lb,      0);
                Grid.SetRow(overlay, r); Grid.SetColumn(overlay, 1);
                cg.Children.Add(lb); cg.Children.Add(overlay); r++;
                cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(ROW_GAP) }); r++;
                txTemplateFolder = tx;
                tx.TextChanged += MarkDirtyText;
            }

            var txAVend      = MakeRow("App Vendor",              existing?.AppVendor          ?? "", required: true);
            var txAName      = MakeRow("App Name",                existing?.AppName            ?? "", required: true);
            var txAppVer     = MakeRow("App Version",             existing?.AppVersion         ?? "", required: true);
            var txClose      = MakeRow("Close Apps",              existing?.CloseApps           ?? "", "comma-separated process names");
            var getAddInstallName  = MakeRadioRow("Add Install Name",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.AddInstallName)  ? "Yes" : existing.AddInstallName);
            var getAddInstallTitle = MakeRadioRow("Add Install Title",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.AddInstallTitle) ? "Yes" : existing.AddInstallTitle);
            var getAddNoRemove = MakeRadioRow("Hide Uninstall Button",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.AddNoRemove) ? "Yes" : existing.AddNoRemove);
            var getAddNoModify = MakeRadioRow("Hide Change Button",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.AddNoModify) ? "Yes" : existing.AddNoModify);
            var getAddNoRepair = MakeRadioRow("Hide Repair Button",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.AddNoRepair) ? "Yes" : existing.AddNoRepair);
            // Install Package / Uninstall Package - enabled only when PSADT Template Folder is set.
            // Computed from tplDefault, NOT from existing?.PSADTTemplateFolder: on Add the textbox is
            // now seeded from the global default, and reading the entry instead would leave these
            // greyed out with a populated folder sitting directly above them.
            bool addAppHasTpl = !string.IsNullOrWhiteSpace(tplDefault);
            var (getInstPkg, _lbInstPkg, spInstPkg, _, _)   = MakeRadioRowEx("Install Package",
                new[] { "No", "Administrator", "System Context" },
                string.IsNullOrWhiteSpace(existing?.InstallPackage) || existing.InstallPackage.Equals("Yes", StringComparison.OrdinalIgnoreCase) ? "Administrator" : existing.InstallPackage);
            spInstPkg.IsEnabled = addAppHasTpl;
            spInstPkg.ToolTip   = addAppHasTpl ? null : "Set PSADT Template Folder first to enable";
            var (getUninstPkg, _lbUninstPkg, spUninstPkg, _, _) = MakeRadioRowEx("Uninstall Package",
                new[] { "No", "Administrator", "System Context" },
                string.IsNullOrWhiteSpace(existing?.UninstallPackage) || existing.UninstallPackage.Equals("Yes", StringComparison.OrdinalIgnoreCase) ? "Administrator" : existing.UninstallPackage);
            spUninstPkg.IsEnabled = addAppHasTpl;
            spUninstPkg.ToolTip   = addAppHasTpl ? null : "Set PSADT Template Folder first to enable";

            // Both rows default to Administrator, which is the right default once a template folder
            // exists - but with no folder the row is greyed out at Administrator and Add still saved
            // that value, because only the TextChanged handler below resets it and it never fires on
            // a folder the user did not touch. The app then arrived in the Download Information
            // checklist with Install/Uninstall package disabled but ticked. Select No up front so a
            // disabled row can only ever save No.
            if (!addAppHasTpl)
            {
                foreach (var rb in spInstPkg.Children.OfType<RadioButton>())
                    rb.IsChecked = rb.Content?.ToString() == "No";
                foreach (var rb in spUninstPkg.Children.OfType<RadioButton>())
                    rb.IsChecked = rb.Content?.ToString() == "No";
            }

            // Wire txTemplateFolder.TextChanged to update Install/Uninstall Package enabled state
            txTemplateFolder.TextChanged += (_, _) =>
            {
                bool hasTpl = !string.IsNullOrWhiteSpace(txTemplateFolder.Text);
                spInstPkg.IsEnabled   = hasTpl;
                spUninstPkg.IsEnabled = hasTpl;
                string tip = hasTpl ? null! : "Set PSADT Template Folder first to enable";
                spInstPkg.ToolTip   = tip;
                spUninstPkg.ToolTip = tip;
                if (!hasTpl)
                {
                    // Reset to No when template folder is cleared
                    foreach (var rb in spInstPkg.Children.OfType<RadioButton>())
                        rb.IsChecked = rb.Content?.ToString() == "No";
                    foreach (var rb in spUninstPkg.Children.OfType<RadioButton>())
                        rb.IsChecked = rb.Content?.ToString() == "No";
                }
            };
            var getShowMsgBox = MakeRadioRow("Show Message Box",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.ShowMessageBox) ? "No" : existing.ShowMessageBox);

            // PSADT Install / Uninstall Command. Seeded with the standard PSADT v4 invocation so a
            // new app writes a usable command into its JSON instead of an empty key.
            var txPsadtInstCmd = MakeRow("PSADT Install Command",
                string.IsNullOrWhiteSpace(existing?.PSADTInstallCommand)   ? DefaultPsadtInstallCommand   : existing.PSADTInstallCommand);
            var txPsadtUninstCmd = MakeRow("PSADT Uninstall Command",
                string.IsNullOrWhiteSpace(existing?.PSADTUninstallCommand) ? DefaultPsadtUninstallCommand : existing.PSADTUninstallCommand);

            // Disable the PSADT group (Close Apps .. Show Message Box) when the template folder is empty.
            // (Install/Uninstall Package are handled by the txTemplateFolder handler above.)
            void SyncAddAppPsadtGroup()
            {
                bool hasTpl = !string.IsNullOrWhiteSpace(txTemplateFolder.Text);
                txClose.IsEnabled = hasTpl;
                txPsadtInstCmd.IsEnabled   = hasTpl;
                txPsadtUninstCmd.IsEnabled = hasTpl;
                foreach (var key in new[] { "Add Install Name", "Add Install Title", "Hide Uninstall Button", "Hide Change Button", "Hide Repair Button", "Show Message Box" })
                    if (addAppRadioPanels.TryGetValue(key, out var wp)) wp.IsEnabled = hasTpl;
            }
            txTemplateFolder.TextChanged += (_, _) => SyncAddAppPsadtGroup();
            SyncAddAppPsadtGroup();
            var txPkgFolder  = txVend; // unused — set automatically on Add
            var txCat        = txVend; // unused — moved to Download Source

            // ── Intune & Deployment ────────────────────────────────────────
            MakeSection("Intune & Deployment");
            var getCreateIntunewin = MakeRadioRow("Create Intunewin",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.CreateIntunewin) ? "Yes" : existing.CreateIntunewin);
            var getPublish  = MakeRadioRow("Publish settings",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.PublishSettings) ? "Yes" : existing.PublishSettings);
            var getDeplMach = MakeRadioRow("Publish to intune",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.PublishToIntune) ? "No" : existing.PublishToIntune);

            // ── Intune Category ─────────────────────────────────────────────
            var intuneCatItems = new[] {
                "Business", "Books & Reference", "Developer Tools", "Education",
                "Entertainment", "Games", "Government & Politics", "Kids",
                "Lifestyle", "Medical", "Productivity", "Security",
                "Shopping", "Social", "Sports", "Travel", "Utilities", "Other" };
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); r++;
            var lbIntuneCat = new TextBlock { Text = "Category", FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lFg, VerticalAlignment = VerticalAlignment.Center };
            Grid.SetRow(lbIntuneCat, r - 1); Grid.SetColumn(lbIntuneCat, 0);
            cg.Children.Add(lbIntuneCat);
            var cbIntuneCat = new ComboBox { FontSize = 11, Height = 28, Margin = new Thickness(0, 0, 0, ROW_GAP) };
            if (Application.Current.Resources.Contains("ModernComboBoxStyle"))
                cbIntuneCat.Style = (Style)Application.Current.Resources["ModernComboBoxStyle"];
            foreach (var ci in intuneCatItems) cbIntuneCat.Items.Add(ci);
            var intuneCatIdx = Array.FindIndex(intuneCatItems, c => c.Equals(existing?.IntuneCategory, StringComparison.OrdinalIgnoreCase));
            cbIntuneCat.SelectedIndex = intuneCatIdx >= 0 ? intuneCatIdx : 0; // default: Business
            Grid.SetRow(cbIntuneCat, r - 1); Grid.SetColumn(cbIntuneCat, 1);
            cg.Children.Add(cbIntuneCat);
            Func<string> getIntuneCat = () => cbIntuneCat.SelectedItem?.ToString() ?? "Business";

            // ── 1  App Info tab fields ──────────────────────────────────────
            var txIntuneAppName    = MakeRow("App Name",         existing?.IntuneAppName    ?? "", required: true);
            var txIntuneAppVendor  = MakeRow("App Vendor",       existing?.IntuneAppVendor  ?? "", required: true);
            var txIntuneAppVersion = MakeRow("App Version",      existing?.IntuneAppVersion ?? "");

            // Auto-fill App Identity across sections: typing the Source App Vendor/Name/Version
            // mirrors into the core App fields (Package Settings) and Intune App fields
            // (Intune & Deployment) so the identity is entered once. A target keeps tracking
            // only while empty or still holding the previously mirrored Source value; once it
            // is edited to a different value it stops updating, so a deliberate override sticks.
            string _idPrevVend = txVend.Text, _idPrevName = txName.Text, _idPrevVer = txSrcVer.Text;
            txVend.TextChanged += (_, _) =>
            {
                string v = txVend.Text;
                if (txAVend.Text == _idPrevVend           || string.IsNullOrEmpty(txAVend.Text))           txAVend.Text           = v;
                if (txIntuneAppVendor.Text == _idPrevVend || string.IsNullOrEmpty(txIntuneAppVendor.Text)) txIntuneAppVendor.Text = v;
                _idPrevVend = v;
            };
            txName.TextChanged += (_, _) =>
            {
                string v = txName.Text;
                if (txAName.Text == _idPrevName         || string.IsNullOrEmpty(txAName.Text))         txAName.Text         = v;
                if (txIntuneAppName.Text == _idPrevName || string.IsNullOrEmpty(txIntuneAppName.Text)) txIntuneAppName.Text = v;
                _idPrevName = v;
            };
            txSrcVer.TextChanged += (_, _) =>
            {
                string v = txSrcVer.Text;
                if (txAppVer.Text == _idPrevVer           || string.IsNullOrEmpty(txAppVer.Text))           txAppVer.Text           = v;
                if (txIntuneAppVersion.Text == _idPrevVer || string.IsNullOrEmpty(txIntuneAppVersion.Text)) txIntuneAppVersion.Text = v;
                _idPrevVer = v;
            };

            var getFeaturedApp     = MakeRadioRow("Featured App",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.FeaturedApp) ? "Yes" : existing.FeaturedApp,
                v => { if (_selectedApp != null) _selectedApp.FeaturedApp = v; SaveJsonAppForSelectedApp(); });
            var txDesc             = MakeRow("Description",      existing?.Description      ?? "Auto Package", required: true);
            // Behaves like Mail Body: Enter inserts a new line and the box grows to
            // show every line.
            txDesc.AcceptsReturn = true;
            txDesc.TextWrapping = TextWrapping.Wrap;
            txDesc.Height = double.NaN;
            txDesc.MinHeight = 28;
            var txDeveloper        = MakeRow("Developer",        existing?.Developer        ?? "");
            var txOwner            = MakeRow("Owner",            existing?.Owner            ?? "");
            var txInformationURL   = MakeRow("Information URL",  existing?.InformationURL   ?? "");
            var txPrivacyURL       = MakeRow("Privacy URL",      existing?.PrivacyURL       ?? "");
            var txNotes            = MakeRow("Notes",            existing?.Notes            ?? "");
            TextBox txLogo = null!;
            txLogo = MakePickRow("Logo", existing?.Logo ?? "", "\uE8B7", "Browse for file",
                () => { var ofd = new Microsoft.Win32.OpenFileDialog { Title = "Select file" }; if (ofd.ShowDialog() == true) txLogo.Text = ofd.FileName; });

            // ── 2  Program tab fields ───────────────────────────────────────
            var txInstallCommand   = MakeRow("Install Command",
                string.IsNullOrWhiteSpace(existing?.InstallCommand)   ? DefaultPsadtInstallCommand   : existing.InstallCommand);
            var txUninstallCommand = MakeRow("Uninstall Command",
                string.IsNullOrWhiteSpace(existing?.UninstallCommand) ? DefaultPsadtUninstallCommand : existing.UninstallCommand);
            var getAllowAvailableUninstall = MakeRadioRow("Allow Available Uninstall",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.AllowAvailableUninstall) ? "Yes" : existing.AllowAvailableUninstall,
                v => { if (_selectedApp != null) _selectedApp.AllowAvailableUninstall = v; SaveJsonAppForSelectedApp(); });
            var getInstallBehaviour = MakeRadioRow("Install Behaviour",
                new[] { "System", "User" },
                string.IsNullOrWhiteSpace(existing?.InstallBehaviour) ? "System" : existing.InstallBehaviour,
                v => {
                    if (_selectedApp != null) { _selectedApp.InstallBehaviour = v; _selectedApp.InstallBehavior = v; }
                    SaveJsonAppForSelectedApp();
                });
            var txInstallationTime = MakeRow("Installation Time (mins)", existing?.InstallationTime ?? "60");

            // Device Restart Behaviour — dropdown
            var restartItems = new[] {
                "Determine behaviour based on return codes",
                "No specific action",
                "App install may force a device restart",
                "SwiftPack will force a device restart" };
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); r++;
            var lbRestart = new TextBlock { Text = "Device Restart Behaviour", FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lFg, VerticalAlignment = VerticalAlignment.Center };
            Grid.SetRow(lbRestart, r - 1); Grid.SetColumn(lbRestart, 0); cg.Children.Add(lbRestart);
            var cbRestart = new ComboBox { FontSize = 11, Height = 28, Margin = new Thickness(0, 0, 0, ROW_GAP) };
            if (Application.Current.Resources.Contains("ModernComboBoxStyle"))
                cbRestart.Style = (Style)Application.Current.Resources["ModernComboBoxStyle"];
            foreach (var ri in restartItems) cbRestart.Items.Add(ri);
            var restartIdx = Array.FindIndex(restartItems, s => s.Equals(existing?.DeviceRestartBehaviour, StringComparison.OrdinalIgnoreCase));
            cbRestart.SelectedIndex = restartIdx >= 0 ? restartIdx : 0;
            Grid.SetRow(cbRestart, r - 1); Grid.SetColumn(cbRestart, 1); cg.Children.Add(cbRestart);
            Func<string> getDeviceRestartBehaviour = () => cbRestart.SelectedItem?.ToString() ?? restartItems[0];

            // ── 3  Requirements tab fields ──────────────────────────────────
            var osItems = new[] {
                "Windows 10 1507", "Windows 10 1511", "Windows 10 1607", "Windows 10 1703",
                "Windows 10 1709", "Windows 10 1803", "Windows 10 1809", "Windows 10 1903",
                "Windows 10 1909", "Windows 10 2004", "Windows 10 20H2", "Windows 10 21H1",
                "Windows 10 21H2", "Windows 10 22H2", "Windows 11 21H2", "Windows 11 22H2",
                "Windows 11 23H2", "Windows 11 24H2" };
            cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); r++;
            var lbMinOs = new TextBlock { Text = "Minimum Operating System", FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lFg, VerticalAlignment = VerticalAlignment.Center };
            Grid.SetRow(lbMinOs, r - 1); Grid.SetColumn(lbMinOs, 0); cg.Children.Add(lbMinOs);
            var cbMinOs = new ComboBox { FontSize = 11, Height = 28, Margin = new Thickness(0, 0, 0, ROW_GAP) };
            if (Application.Current.Resources.Contains("ModernComboBoxStyle"))
                cbMinOs.Style = (Style)Application.Current.Resources["ModernComboBoxStyle"];
            foreach (var oi in osItems) cbMinOs.Items.Add(oi);
            var osIdx = Array.FindIndex(osItems, s => s.Equals(existing?.MinimumOperatingSystem, StringComparison.OrdinalIgnoreCase));
            cbMinOs.SelectedIndex = osIdx >= 0 ? osIdx : 12; // default: Windows 10 21H2
            Grid.SetRow(cbMinOs, r - 1); Grid.SetColumn(cbMinOs, 1); cg.Children.Add(cbMinOs);
            Func<string> getMinOs = () => cbMinOs.SelectedItem?.ToString() ?? osItems[12];

            // OS Architecture — radio
            var getOsArch = MakeRadioRow("OS Architecture",
                new[] { "64Bit", "32Bit", "ARM64" },
                string.IsNullOrWhiteSpace(existing?.OperatingSystemArchitecture) ? "64Bit" : existing.OperatingSystemArchitecture);

            // ── 4  Detection tab fields ─────────────────────────────────────
            // Rules Format — Manual detection rules / Custom script
            var getRulesFormat = MakeRadioRow("Rules Format",
                new[] { "Manual detection rules", "Custom script" },
                string.IsNullOrWhiteSpace(existing?.RulesFormat) ? "Manual detection rules" : existing.RulesFormat);
            // Helper: build a label+control DockPanel row inside a StackPanel wrapper,
            // add it to cg with GridLength.Auto, and return (wrapper, control).
            // Toggling wrapper.Visibility shows/hides the entire row cleanly.
            StackPanel MakeDetRow(string label, UIElement ctrl, bool required = false)
            {
                var lb2 = MakeFieldLabel(label, required, 160);
                var dp = new DockPanel { Margin = new Thickness(0, 0, 0, ROW_GAP), LastChildFill = true };
                DockPanel.SetDock(lb2, Dock.Left);
                dp.Children.Add(lb2);
                dp.Children.Add(ctrl);
                var wrap = new StackPanel();
                wrap.Children.Add(dp);
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                Grid.SetRow(wrap, r); Grid.SetColumnSpan(wrap, 2);
                cg.Children.Add(wrap); r++;
                return wrap;
            }
            // Helper: Yes/No radio pair — returns (StackPanel, getter)
            (StackPanel sp, Func<string> get) MakeDetYesNo(string current)
            {
                var sp2   = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                var grp2  = Guid.NewGuid().ToString();
                var rbY   = new RadioButton { Content = "Yes", GroupName = grp2, FontSize = 11, Margin = new Thickness(0, 0, 14, 0), Foreground = lFg };
                var rbN   = new RadioButton { Content = "No",  GroupName = grp2, FontSize = 11, Foreground = lFg };
                bool isY  = (current ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase);
                rbY.IsChecked = isY; rbN.IsChecked = !isY;
                sp2.Children.Add(rbY); sp2.Children.Add(rbN);
                return (sp2, () => rbY.IsChecked == true ? "Yes" : "No");
            }
            // Helper: ComboBox — returns (ComboBox, getter)
            (ComboBox cb, Func<string> get) MakeDetCombo(string[] items, string current, int defIdx)
            {
                var cb2 = new ComboBox { FontSize = 11, Height = 28 };
                if (Application.Current.Resources.Contains("ModernComboBoxStyle"))
                    cb2.Style = (Style)Application.Current.Resources["ModernComboBoxStyle"];
                foreach (var oi in items) cb2.Items.Add(oi);
                var idx = Array.FindIndex(items, s => s.Equals(current ?? "", StringComparison.OrdinalIgnoreCase));
                cb2.SelectedIndex = idx >= 0 ? idx : defIdx;
                return (cb2, () => cb2.SelectedItem?.ToString() ?? items[defIdx]);
            }

            // Rule Type initial state. A FRESH app (Add App, existing == null) seeds from the
            // default Download Preference: MSI download detected by product code, EXE by the ARP
            // registry key. An existing app keeps exactly what it saved - re-deriving it here
            // would overwrite a rule type the user chose by hand.
            // An existing app with no rule type at all is seeded too: Rule Type is required, so
            // "all three off" is never a deliberate saved state, and there is nothing to lose.
            bool dlgPrefIsMsi = (string.IsNullOrWhiteSpace(existing?.DownloadPreference) ? "MSI_x64" : existing.DownloadPreference)
                                .StartsWith("MSI", StringComparison.OrdinalIgnoreCase);
            bool dlgDetMsiSaved  = (existing?.DetectionTypeMSI      ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase);
            bool dlgDetFileSaved = (existing?.DetectionTypeFile     ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase);
            bool dlgDetRegSaved  = (existing?.DetectionTypeRegistry ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase);
            bool dlgSeedRuleType = !dlgDetMsiSaved && !dlgDetFileSaved && !dlgDetRegSaved;
            bool dlgDetMsiInit = dlgSeedRuleType ?  dlgPrefIsMsi : dlgDetMsiSaved;
            bool dlgDetRegInit = dlgSeedRuleType ? !dlgPrefIsMsi : dlgDetRegSaved;

            // Detection Type — checkboxes: MSI, File, Registry (Manual); Script checkbox (Custom script)
            // Manual: MSI / File / Registry checkboxes
            var spDetChkManual = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
            var cbDetMsi = new CheckBox { Content = "MSI",      FontSize = 11, IsChecked = dlgDetMsiInit,   Margin = new Thickness(0,0,14,0), Foreground = lFg };
            var cbDetFile= new CheckBox { Content = "File",     FontSize = 11, IsChecked = dlgDetFileSaved, Margin = new Thickness(0,0,14,0), Foreground = lFg };
            var cbDetReg = new CheckBox { Content = "Registry", FontSize = 11, IsChecked = dlgDetRegInit,   Margin = new Thickness(0,0,14,0), Foreground = lFg };
            cbDetMsi.SetResourceReference(FrameworkElement.StyleProperty, "ModernCheckBoxStyle"); cbDetFile.SetResourceReference(FrameworkElement.StyleProperty, "ModernCheckBoxStyle"); cbDetReg.SetResourceReference(FrameworkElement.StyleProperty, "ModernCheckBoxStyle");
            spDetChkManual.Children.Add(cbDetMsi); spDetChkManual.Children.Add(cbDetFile); spDetChkManual.Children.Add(cbDetReg);
            var wDetTypeManual = MakeDetRow("Rule Type", spDetChkManual, required: true);
            Func<string> getDetTypeMSI      = () => cbDetMsi.IsChecked  == true ? "Yes" : "No";
            Func<string> getDetTypeFile     = () => cbDetFile.IsChecked  == true ? "Yes" : "No";
            Func<string> getDetTypeRegistry = () => cbDetReg.IsChecked   == true ? "Yes" : "No";

            // Assigned once the MSI Version Check row exists (built below). Detecting by MSI means
            // detecting on its version, so ticking MSI turns it on - only towards Yes and only on
            // tick, so unticking MSI leaves it alone and a No set afterwards stays No.
            Action? dlgTurnOnMsiVersionCheck = null;
            // Set while Import restores saved values, so the auto-tick does not overwrite them.
            bool dlgSuppressMsiVcAutoTick = false;
            cbDetMsi.Checked += (_, _) => { if (!dlgSuppressMsiVcAutoTick) dlgTurnOnMsiVersionCheck?.Invoke(); };

            // True once the Rule Type row holds a real choice rather than the seeded default.
            // Starts true for an app that arrived with rule types saved, and is set by a click on
            // any of the three boxes (Click fires for user input only, so the seed above and the
            // programmatic fills in PopulateFields do not trip it - Import sets it explicitly).
            bool dlgRuleTypeChosen = !dlgSeedRuleType;
            foreach (var cbRt in new[] { cbDetMsi, cbDetFile, cbDetReg })
                cbRt.Click += (_, _) => dlgRuleTypeChosen = true;

            // Wire the forward-declared hook from the Download Preference row above. MSI downloads
            // are detected by product code; an EXE has no MSI to look up, so it falls back to the
            // ARP registry key.
            applyDlgRuleTypeForPreference = pref =>
            {
                if (string.IsNullOrWhiteSpace(pref)) return;
                bool isMsi = pref.StartsWith("MSI", StringComparison.OrdinalIgnoreCase);
                var target = isMsi ? cbDetMsi : cbDetReg;
                var other  = isMsi ? cbDetReg : cbDetMsi;
                if (target.IsChecked != true) target.IsChecked = true;
                // While the row is still the untouched seed, switching preference REPLACES the
                // default rather than adding to it, so a fresh app that starts MSI and is switched
                // to EXE ends up Registry only. Once the user has ticked anything themselves,
                // nothing is ever unticked - a hand-picked File / MSI / Registry combination
                // survives switching back and forth.
                if (!dlgRuleTypeChosen && other.IsChecked == true) other.IsChecked = false;
            };

            // Custom script: Script Detection Type row removed — no checkbox shown when Custom script is selected
            // wDetTypeScript kept as null so UpdateDetVis null-checks are safe
            Grid? wDetTypeScript = null;

            // Keep stubs for legacy references (wDetTypeLb/Sp/rDetType no longer used)
            TextBlock wDetTypeLb = new TextBlock(); StackPanel wDetTypeSp = new StackPanel(); int rDetType = 0;

            var operOpts = new[] { "Equals","Not equal to","Greater than or equal to","Greater than","Less than or equal to","Less than" };

            // ── MSI sub-rows ──────────────────────────────────────────────────
            var txMsiProductCode = new TextBox { Text = existing?.DetectionMsiProductCode ?? "", FontSize = 11, Height = 28, Style = tbStyle, Background = bBg, BorderBrush = bBdr, Foreground = lFg, Padding = new Thickness(8,0,8,0) };
            var wMsiPc  = MakeDetRow("Product Code", txMsiProductCode);

            // A fresh app seeds Rule Type = MSI from the MSI download preference (see above), and
            // detecting by MSI means detecting on its version, so seed this Yes to match. An
            // existing app keeps exactly what it saved.
            var (spMsiVcCtrl, getMsiVerCheck) = MakeDetYesNo(
                dlgSeedRuleType && dlgDetMsiInit ? "Yes" : (existing?.DetectionMsiVersionCheck ?? "No"));
            var wMsiVc  = MakeDetRow("MSI Version Check", spMsiVcCtrl);

            var (cbMsiOp, getMsiOperator) = MakeDetCombo(operOpts, existing?.DetectionMsiOperator ?? "Greater than or equal to", 1);
            var wMsiOp  = MakeDetRow("MSI Operator", cbMsiOp);

            var txMsiValue = new TextBox { Text = existing?.DetectionMsiValue ?? "", FontSize = 11, Height = 28, Style = tbStyle, Background = bBg, BorderBrush = bBdr, Foreground = lFg, Padding = new Thickness(8,0,8,0) };
            var wMsiValue = MakeDetRow("MSI Value", txMsiValue);
            // MSI Operator only visible when Version Check = Yes
            void RefreshMsiOpVis()
            {
                bool vc = spMsiVcCtrl.Children.OfType<RadioButton>().FirstOrDefault(x => x.Content?.ToString() == "Yes")?.IsChecked == true;
                wMsiOp.Visibility    = vc ? Visibility.Visible : Visibility.Collapsed;
                wMsiValue.Visibility = vc ? Visibility.Visible : Visibility.Collapsed;
            }
            foreach (var rb in spMsiVcCtrl.Children.OfType<RadioButton>()) rb.Checked += (_, _) => RefreshMsiOpVis();
            // Wire the forward-declared hook from the Rule Type checkboxes above. Setting IsChecked
            // raises Checked, so RefreshMsiOpVis runs and the MSI Operator / MSI Value rows appear.
            dlgTurnOnMsiVersionCheck = () =>
            {
                var rbYes = spMsiVcCtrl.Children.OfType<RadioButton>()
                    .FirstOrDefault(x => (x.Content?.ToString() ?? "").Equals("Yes", StringComparison.OrdinalIgnoreCase));
                if (rbYes != null && rbYes.IsChecked != true) rbYes.IsChecked = true;
            };

            // ── File sub-rows ─────────────────────────────────────────────────
            var txFilePath = new TextBox { Text = existing?.DetectionFileFolderPath ?? "", FontSize = 11, Height = 28, Style = tbStyle, Background = bBg, BorderBrush = bBdr, Foreground = lFg, Padding = new Thickness(8,0,32,0) };
            var filePathBrowseBtn = new Button { Content = "\U0001F4C1", FontSize = 12, Width = 28, Height = 28, Background = Brushes.Transparent, BorderThickness = new Thickness(0), Foreground = lFg, Cursor = System.Windows.Input.Cursors.Hand, HorizontalAlignment = HorizontalAlignment.Right, VerticalAlignment = VerticalAlignment.Center, Padding = new Thickness(0), ToolTip = "Browse for folder" };
            filePathBrowseBtn.Click += (_, _) => { var fbd = new System.Windows.Forms.FolderBrowserDialog { Description = "Select folder", UseDescriptionForTitle = true }; if (fbd.ShowDialog() == System.Windows.Forms.DialogResult.OK) txFilePath.Text = fbd.SelectedPath; };
            var filePathOverlay = new Grid(); filePathOverlay.Children.Add(txFilePath); filePathOverlay.Children.Add(filePathBrowseBtn);
            var wFilePath  = MakeDetRow("File Folder Path", filePathOverlay);

            var txFileFile = new TextBox { Text = existing?.DetectionFileFileName ?? "", FontSize = 11, Height = 28, Style = tbStyle, Background = bBg, BorderBrush = bBdr, Foreground = lFg, Padding = new Thickness(8,0,8,0) };
            var wFileFile  = MakeDetRow("File Name", txFileFile);

            var fileChkOpts = new[] { "File or folder exists","Date modified","Date created","Size in MB","String (Version)" };
            var (cbFileChk, getFileCheckType) = MakeDetCombo(fileChkOpts, existing?.DetectionFileDetectionMethod ?? "String (Version)", 4);
            var wFileChk  = MakeDetRow("File Detection Method", cbFileChk);

            var (cbFileOp, getFileOperator) = MakeDetCombo(operOpts, existing?.DetectionFileOperator ?? "Greater than or equal to", 1);
            var wFileOp   = MakeDetRow("File Operator", cbFileOp);

            // File Value — the appropriate stored field is chosen by detection method on save.
            var txFileValue = new TextBox { Text = existing?.DetectionFileValue ?? "", FontSize = 11, Height = 28, Style = tbStyle, Background = bBg, BorderBrush = bBdr, Foreground = lFg, Padding = new Thickness(8,0,8,0) };
            var wFileValue = MakeDetRow("File Value", txFileValue);

            var cbFile32  = new CheckBox { IsChecked = (existing?.DetectionFile32Bit ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase), Foreground = lFg, VerticalAlignment = VerticalAlignment.Center };
            cbFile32.SetResourceReference(FrameworkElement.StyleProperty, "ModernCheckBoxStyle");
            var wFile32   = MakeDetRow("Associated with a 32-bit app on 64-bit clients", cbFile32);
            Func<string> getFile32Bit = () => cbFile32.IsChecked == true ? "Yes" : "No";

            // ── Registry sub-rows ─────────────────────────────────────────────
            var txRegKey  = new TextBox { Text = existing?.DetectionRegKeyPath ?? "", FontSize = 11, Height = 28, Style = tbStyle, Background = bBg, BorderBrush = bBdr, Foreground = lFg, Padding = new Thickness(8,0,32,0) };
            var regKeyBrowseBtn = new Button { Content = "\U0001F511", FontSize = 12, Width = 28, Height = 28, Background = Brushes.Transparent, BorderThickness = new Thickness(0), Foreground = lFg, Cursor = System.Windows.Input.Cursors.Hand, HorizontalAlignment = HorizontalAlignment.Right, VerticalAlignment = VerticalAlignment.Center, Padding = new Thickness(0), ToolTip = "Open Registry Editor" };
            regKeyBrowseBtn.Click += (_, _) => { try { System.Diagnostics.Process.Start("regedit.exe"); } catch (System.Exception exReg) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exReg.GetType().Name + ": " + exReg.Message); } };
            var regKeyOverlay = new Grid(); regKeyOverlay.Children.Add(txRegKey); regKeyOverlay.Children.Add(regKeyBrowseBtn);
            var wRegKey   = MakeDetRow("Registry Key Path", regKeyOverlay);

            var txRegVal  = new TextBox { Text = existing?.DetectionRegValueName ?? "", FontSize = 11, Height = 28, Style = tbStyle, Background = bBg, BorderBrush = bBdr, Foreground = lFg, Padding = new Thickness(8,0,8,0) };
            var wRegVal   = MakeDetRow("Registry Value Name", txRegVal);

            var regChkOpts = new[] { "Key exists","Key does not exist","Value exists","Value does not exist","String comparison","Integer comparison","Version comparison" };
            var (cbRegChk, getRegCheckType) = MakeDetCombo(regChkOpts, existing?.DetectionRegDetectionMethod ?? "Version comparison", 3);
            var wRegChk   = MakeDetRow("Registry Detection Method", cbRegChk);

            var (cbRegOp, getRegOperator) = MakeDetCombo(operOpts, existing?.DetectionRegOperator ?? "Greater than or equal to", 1);
            var wRegOp    = MakeDetRow("Registry Operator", cbRegOp);

            var txRegValue = new TextBox { Text = existing?.DetectionRegistryValue ?? "", FontSize = 11, Height = 28, Style = tbStyle, Background = bBg, BorderBrush = bBdr, Foreground = lFg, Padding = new Thickness(8,0,8,0) };
            var wRegValue = MakeDetRow("Registry Value", txRegValue);

            var cbReg32   = new CheckBox { IsChecked = (existing?.DetectionReg32Bit ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase), Foreground = lFg, VerticalAlignment = VerticalAlignment.Center };
            cbReg32.SetResourceReference(FrameworkElement.StyleProperty, "ModernCheckBoxStyle");
            var wReg32    = MakeDetRow("Associated with a 32-bit app on 64-bit clients", cbReg32);
            Func<string> getReg32Bit = () => cbReg32.IsChecked == true ? "Yes" : "No";

            // ── Script sub-rows ───────────────────────────────────────────────
            var txScriptFile = new TextBox { Text = existing?.DetectionScriptFile ?? "", FontSize = 11, Height = 28, Style = tbStyle, Background = bBg, BorderBrush = bBdr, Foreground = lFg, Padding = new Thickness(8,0,32,0) };
            var scriptBrowseBtn = new Button { Content = "📁", FontSize = 12, Width = 28, Height = 28, Background = Brushes.Transparent, BorderThickness = new Thickness(0), Foreground = lFg, Cursor = System.Windows.Input.Cursors.Hand, HorizontalAlignment = HorizontalAlignment.Right, VerticalAlignment = VerticalAlignment.Center, Padding = new Thickness(0), ToolTip = "Browse for detection script (.ps1)" };
            scriptBrowseBtn.Click += (_, _) => { var ofd = new Microsoft.Win32.OpenFileDialog { Filter = "PowerShell scripts (*.ps1)|*.ps1|All files (*.*)|*.*", Title = "Select Detection Script" }; if (ofd.ShowDialog() == true) txScriptFile.Text = ofd.FileName; };
            var scriptOverlay = new Grid(); scriptOverlay.Children.Add(txScriptFile); scriptOverlay.Children.Add(scriptBrowseBtn);
            var wScriptFile = MakeDetRow("Script File", scriptOverlay);

            var (spScriptSig, getScriptEnforce) = MakeDetYesNo(existing?.DetectionScriptEnforceSignatureCheck ?? "No");
            var wScriptSig  = MakeDetRow("Enforce Script Signature Check", spScriptSig);

            var (spScript32, getScriptRunAs32) = MakeDetYesNo(existing?.DetectionScriptRunAs32Bit ?? "No");
            var wScript32   = MakeDetRow("Run as 32-bit process on 64-bit client", spScript32);

            // ── Show/hide based on Rules Format ───────────────────────────────
            void UpdateDetVis()
            {
                bool isManual = getRulesFormat().Equals("Manual detection rules", StringComparison.OrdinalIgnoreCase);
                var manVis    = isManual  ? Visibility.Visible : Visibility.Collapsed;
                var scriptVis = !isManual ? Visibility.Visible : Visibility.Collapsed;

                // Detection Type rows
                wDetTypeManual.Visibility = manVis;
                if (wDetTypeScript != null) wDetTypeScript.Visibility = scriptVis;
                // MSI sub-rows — Manual
                wMsiPc.Visibility    = manVis;
                wMsiVc.Visibility    = manVis; wMsiOp.Visibility    = manVis; wMsiValue.Visibility = manVis;
                // File sub-rows — Manual
                wFilePath.Visibility = manVis; wFileFile.Visibility = manVis;
                wFileChk.Visibility  = manVis; wFileOp.Visibility   = manVis; wFileValue.Visibility = manVis; wFile32.Visibility = manVis;
                // Registry sub-rows — Manual
                wRegKey.Visibility   = manVis; wRegVal.Visibility   = manVis;
                wRegChk.Visibility   = manVis; wRegOp.Visibility    = manVis; wRegValue.Visibility = manVis; wReg32.Visibility  = manVis;
                // Script sub-rows — Custom script only
                wScriptFile.Visibility = scriptVis; wScriptSig.Visibility = scriptVis; wScript32.Visibility = scriptVis;
                // MSI operator/value follow the version-check toggle.
                RefreshMsiOpVis();
            }

            // ── 7  Assignments tab fields ───────────────────────────────────
            // Order matches the Package Information column exactly: Dependencies (+auto-install
            // toggle) → Supersedences (+uninstall-previous toggle) → Assignments →
            // Communication (Send Mail → App Owner Email).

            // ── Dynamic Dependencies + Supersedences (any count) ──
            // Work on copies so Cancel does not mutate the existing entry; assigned on Save.
            var dlgDeps = (existing?.Dependencies ?? new List<DependencyItem>())
                .Select(d => new DependencyItem { AppName = d.AppName, AppID = d.AppID, AutoInstall = d.AutoInstall }).ToList();
            var dlgSups = (existing?.Supersedences ?? new List<SupersedenceItem>())
                .Select(s => new SupersedenceItem { AppName = s.AppName, AppID = s.AppID, UninstallPreviousVersion = s.UninstallPreviousVersion }).ToList();

            void AddFullRow(UIElement el)
            {
                cg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                Grid.SetRow(el, r); Grid.SetColumn(el, 0); Grid.SetColumnSpan(el, 2);
                cg.Children.Add(el); r++;
                cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(ROW_GAP) }); r++;
            }
            void DlgCardField(Panel host, string label, string value, Action<string> onChanged)
            {
                var g = new Grid { Margin = new Thickness(0, 0, 0, 4) };
                g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(100) });
                g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                var lbl = new TextBlock { Text = label, FontSize = 11, Foreground = lFg, VerticalAlignment = VerticalAlignment.Center };
                var tx = new TextBox { Text = value, FontSize = 11, Height = 26, Style = tbStyle, Background = bBg, BorderBrush = bBdr, Foreground = lFg, Padding = new Thickness(8, 0, 8, 0) };
                tx.TextChanged += (_, _) => onChanged(tx.Text);
                Grid.SetColumn(lbl, 0); Grid.SetColumn(tx, 1);
                g.Children.Add(lbl); g.Children.Add(tx);
                host.Children.Add(g);
            }
            void DlgCardRadio(Panel host, string label, string value, Action<string> onChanged)
            {
                var g = new Grid { Margin = new Thickness(0, 0, 0, 2) };
                g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(100) });
                g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                var lbl = new TextBlock { Text = label, FontSize = 11, Foreground = lFg, VerticalAlignment = VerticalAlignment.Center };
                var sp = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                string grp = Guid.NewGuid().ToString();
                bool isYes = string.Equals(value, "Yes", StringComparison.OrdinalIgnoreCase);
                var rbY = new RadioButton { Content = "Yes", GroupName = grp, FontSize = 11, IsChecked = isYes,  Margin = new Thickness(0, 0, 14, 0), Cursor = System.Windows.Input.Cursors.Hand, Foreground = lFg };
                var rbN = new RadioButton { Content = "No",  GroupName = grp, FontSize = 11, IsChecked = !isYes, Cursor = System.Windows.Input.Cursors.Hand, Foreground = lFg };
                rbY.Checked += (_, _) => onChanged("Yes");
                rbN.Checked += (_, _) => onChanged("No");
                sp.Children.Add(rbY); sp.Children.Add(rbN);
                Grid.SetColumn(lbl, 0); Grid.SetColumn(sp, 1);
                g.Children.Add(lbl); g.Children.Add(sp);
                host.Children.Add(g);
            }
            Border DlgCardShell(Panel host, string title, Action onDelete)
            {
                var card = new Border { BorderBrush = bBdr, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(6), Padding = new Thickness(8), Margin = new Thickness(0, 0, 0, 6) };
                var body = new StackPanel(); card.Child = body;
                var hg = new Grid();
                hg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                hg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                var ht = new TextBlock { Text = title, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lFg, VerticalAlignment = VerticalAlignment.Center };
                var del = new Button { Content = "✕", FontSize = 11, Width = 22, Height = 22, Background = Brushes.Transparent, BorderThickness = new Thickness(0), Foreground = secFg, Cursor = System.Windows.Input.Cursors.Hand, ToolTip = "Remove" };
                del.Click += (_, _) => onDelete();
                Grid.SetColumn(ht, 0); Grid.SetColumn(del, 1);
                hg.Children.Add(ht); hg.Children.Add(del);
                body.Children.Add(hg);
                host.Children.Add(card);
                return card;
            }

            // Dependencies
            AddFullRow(new TextBlock { Text = "Dependencies", FontSize = 11, FontWeight = FontWeights.Bold, Foreground = lFg, Margin = new Thickness(0, 4, 0, 2) });
            var dlgDepHost = new StackPanel();
            AddFullRow(dlgDepHost);
            void RebuildDlgDeps()
            {
                dlgDepHost.Children.Clear();
                for (int di = 0; di < dlgDeps.Count; di++)
                {
                    var d = dlgDeps[di]; int idx = di;
                    var body = (StackPanel)DlgCardShell(dlgDepHost, $"Dependency {idx + 1}",
                        () => { if (idx < dlgDeps.Count) { dlgDeps.RemoveAt(idx); RebuildDlgDeps(); } }).Child;
                    DlgCardField(body, "App Name", d.AppName, v => d.AppName = v);
                    DlgCardField(body, "App ID",   d.AppID,   v => d.AppID = v);
                    DlgCardRadio(body, "Auto Install", d.AutoInstall, v => d.AutoInstall = v);
                }
            }
            RebuildDlgDeps();
            var addDlgDep = new Button { Content = "＋  Add Dependency", FontSize = 11, Padding = new Thickness(10, 3, 10, 3), HorizontalAlignment = HorizontalAlignment.Left, Cursor = System.Windows.Input.Cursors.Hand, Style = TryFindResource("ActionBtnStyle") as Style };
            addDlgDep.Click += async (_, _) =>
            {
                var chosen = await IntunePickerDialogs.PickAppsAsync(win, "Add dependency", "Dependency Count", superseded: false);
                if (chosen == null || chosen.Count == 0) return;
                var seen = new HashSet<string>(dlgDeps.Select(d => (d.AppName ?? "").Trim())
                    .Where(s => s.Length > 0), StringComparer.OrdinalIgnoreCase);
                foreach (var a in chosen)
                    if (seen.Add(a.Name)) dlgDeps.Add(new DependencyItem { AppName = a.Name, AppID = a.Id, AutoInstall = "Yes" });
                RebuildDlgDeps();
            };
            AddFullRow(addDlgDep);

            // Supersedences
            AddFullRow(new TextBlock { Text = "Supersedences", FontSize = 11, FontWeight = FontWeights.Bold, Foreground = lFg, Margin = new Thickness(0, 4, 0, 2) });
            // Written to the per-app JSON on Add, and read back by the publish script. Blank counts
            // as Yes, which is what every build before this one did.
            var getAutoSupersede = MakeRadioRow("Add Supersedence Automatically",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.AddSupersedenceAutomatically) ? "Yes" : existing.AddSupersedenceAutomatically);
            var dlgSupHost = new StackPanel();
            AddFullRow(dlgSupHost);
            void RebuildDlgSups()
            {
                dlgSupHost.Children.Clear();
                for (int si = 0; si < dlgSups.Count; si++)
                {
                    var s = dlgSups[si]; int idx = si;
                    var body = (StackPanel)DlgCardShell(dlgSupHost, $"Supersedence {idx + 1}",
                        () => { if (idx < dlgSups.Count) { dlgSups.RemoveAt(idx); RebuildDlgSups(); } }).Child;
                    DlgCardField(body, "App Name", s.AppName, v => s.AppName = v);
                    DlgCardField(body, "App ID",   s.AppID,   v => s.AppID = v);
                    DlgCardRadio(body, "Uninstall Prev.", s.UninstallPreviousVersion, v => s.UninstallPreviousVersion = v);
                }
            }
            RebuildDlgSups();
            var addDlgSup = new Button { Content = "＋  Add Supersedence", FontSize = 11, Padding = new Thickness(10, 3, 10, 3), HorizontalAlignment = HorizontalAlignment.Left, Cursor = System.Windows.Input.Cursors.Hand, Style = TryFindResource("ActionBtnStyle") as Style };
            addDlgSup.Click += async (_, _) =>
            {
                var chosen = await IntunePickerDialogs.PickAppsAsync(win, "Add app to supersede", "Superseded Count", superseded: true);
                if (chosen == null || chosen.Count == 0) return;
                var seen = new HashSet<string>(dlgSups.Select(s => (s.AppName ?? "").Trim())
                    .Where(s => s.Length > 0), StringComparer.OrdinalIgnoreCase);
                foreach (var a in chosen)
                    if (seen.Add(a.Name)) dlgSups.Add(new SupersedenceItem { AppName = a.Name, AppID = a.Id, UninstallPreviousVersion = "No" });
                RebuildDlgSups();
            };
            AddFullRow(addDlgSup);

            AddFullRow(new TextBlock { Text = "Assignments", FontSize = 11, FontWeight = FontWeights.Bold, Foreground = lFg, Margin = new Thickness(0, 4, 0, 2) });
            // Assignments are managed via the Add Group button below (parity with the Package
            // Information column, which dropped the raw text box). Keep a non-UI TextBox as the data
            // holder so Add Group, ReadFields, and PopulateFields keep working unchanged.
            var txAssignAvail    = new TextBox { Text = existing?.AssignmentsAvailable ?? "" };
            var addDlgGrp = new Button { Content = "＋  Add Group", FontSize = 11, Padding = new Thickness(10, 3, 10, 3), HorizontalAlignment = HorizontalAlignment.Left, Cursor = System.Windows.Input.Cursors.Hand, Style = TryFindResource("ActionBtnStyle") as Style };
            addDlgGrp.Click += async (_, _) =>
            {
                var chosen = await IntunePickerDialogs.PickGroupsAsync(win, "Select groups");
                if (chosen == null || chosen.Count == 0) return;
                var names = new List<string>();
                foreach (var part in (txAssignAvail.Text ?? "").Split(','))
                { var t = part.Trim(); if (t.Length > 0) names.Add(t); }
                var seen = new HashSet<string>(names, StringComparer.OrdinalIgnoreCase);
                foreach (var g in chosen)
                    if (!string.IsNullOrWhiteSpace(g.Name) && seen.Add(g.Name.Trim())) names.Add(g.Name.Trim());
                txAssignAvail.Text = string.Join(", ", names);
            };
            AddFullRow(addDlgGrp);

            // ── Communication section ───────────────────────────────────────
            MakeSection("Communication");
            var getSendMail = MakeRadioRow("Send Mail to App Owner",
                new[] { "Yes", "No" },
                string.IsNullOrWhiteSpace(existing?.SendMailToAppOwner) ? "No" : existing.SendMailToAppOwner);
            var txOwnerEmail = MakeRow("App Owner Email",  existing?.AppOwnerEmail ?? "");

            // Per-app mail wording. Empty falls back to the global values in
            // AutoPackage.json (Settings window > Mail); tokens {AppName},
            // {AppVersion}, {AppVendor} and {PackageName} are supported.
            var txDlgMailSubject = MakeRow("Mail Subject", existing?.MailSubject ?? "");
            var txDlgMailBody    = MakeRow("Mail Body",    existing?.MailBody ?? "");
            // Behaves like the Settings window's Mail Body: starts one row tall,
            // Enter inserts a new line and the box grows to show every line.
            txDlgMailBody.AcceptsReturn = true;
            txDlgMailBody.TextWrapping = TextWrapping.Wrap;
            txDlgMailBody.Height = double.NaN;
            txDlgMailBody.MinHeight = 28;

            cg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(8) }); r++;

            // ── Helper: read all fields into a DownloadSourceEntry ──────────
            DownloadSourceEntry ReadFields()
            {
                var e = new DownloadSourceEntry
                {
                    SourceAppVendor             = txVend.Text.Trim(),
                    SourceAppName               = txName.Text.Trim(),
                    SourceAppVersion            = txSrcVer.Text.Trim(),
                    ApiType                     = (cbApi.SelectedItem as string) ?? "URL",
                    GitHubRepo                  = txRepo.Text.Trim(),
                    WingetPackageId             = txWinget.Text.Trim(),
                    VendorApiId                 = txVendor.Text.Trim(),
                    DownloadPageUrl             = txUrl.Text.Trim(),
                    DownloadPreference          = getDlPref(),
                    LockDownloadPreference      = getLockPref(),
                    SilentInstallParameterMSI   = txSiMSI.Text.Trim(),
                    SilentUninstallParameterMSI = txSuMSI.Text.Trim(),
                    SilentInstallParameterEXE   = txSiEXE.Text.Trim(),
                    SilentUninstallParameterEXE = txSuEXE.Text.Trim(),
                    InstallSourceSilently       = getInstSil(),
                    UninstallSourceSilently     = getUninstSil(),
                    CreatePackage               = getCreatePkg(),
                    AppVendor                   = txAVend.Text.Trim(),
                    AppName                     = txAName.Text.Trim(),
                    AppVersion                  = txAppVer.Text.Trim(),
                    InstallPackage              = getInstPkg(),
                    UninstallPackage            = getUninstPkg(),
                    UninstallPath               = txUninstPath.Text.Trim(),
                    CloseApps                   = txClose.Text.Trim(),
                    PackageTemplateFolder       = existing?.PackageTemplateFolder ?? "",
                    CreateMST                   = getCreateMst(),
                    RemoveDesktopShortcut       = getRemoveDesktop(),
                    ShowMessageBox              = getShowMsgBox(),
                    AddInstallName              = getAddInstallName(),
                    AddInstallTitle             = getAddInstallTitle(),
                    AddNoRemove                 = getAddNoRemove(),
                    AddNoModify                 = getAddNoModify(),
                    AddNoRepair                 = getAddNoRepair(),
                    PSADTTemplateFolder         = txTemplateFolder.Text.Trim(),
                    Category                    = getCat(),
                    AutoDownloadSource          = getSrcDl(),
                    DownloadFrequency           = getFreq(),
                    // Each schedule field is written exactly when its row is on screen, and blank
                    // otherwise, so the JSON never carries settings from a frequency this app no
                    // longer uses. The list lives in ScheduleFieldsFor, shared with the schedule
                    // panel and with UpdateScheduleVisibility below: spelled out here as well, it
                    // once drifted and silently dropped everything "Every 2 weeks" needed.
                    DownloadScheduleDays        = ScheduleFieldsFor(getFreq()).Days       ? getDays()       : "",
                    DownloadScheduleDate        = ScheduleFieldsFor(getFreq()).Date       ? getDate()       : "",
                    DownloadScheduleTime        = ScheduleFieldsFor(getFreq()).Time       ? getTime()       : "",
                    DownloadScheduleHour        = ScheduleFieldsFor(getFreq()).Hour       ? getHour()       : "",
                    DownloadScheduleMonth       = ScheduleFieldsFor(getFreq()).Month      ? getMonth()      : "",
                    DownloadScheduleYear        = ScheduleFieldsFor(getFreq()).Month      ? getYear()       : "",
                    DownloadOccurrence          = ScheduleFieldsFor(getFreq()).Occurrence ? getOccurrence() : "",
                    PublishSettings             = getPublish(),
                    PublishToIntune             = getDeplMach(),
                    IntuneCategory              = getIntuneCat(),
                    InstallBehaviour            = getInstallBehaviour(),
                    CreateIntunewin             = getCreateIntunewin(),
                    // 1 App Info
                    IntuneAppName               = txIntuneAppName.Text.Trim(),
                    IntuneAppVendor             = txIntuneAppVendor.Text.Trim(),
                    IntuneAppVersion            = txIntuneAppVersion.Text.Trim(),
                    FeaturedApp                 = getFeaturedApp(),
                    Description                 = txDesc.Text.Trim(),
                    Developer                   = txDeveloper.Text.Trim(),
                    Owner                       = txOwner.Text.Trim(),
                    InformationURL              = txInformationURL.Text.Trim(),
                    PrivacyURL                  = txPrivacyURL.Text.Trim(),
                    Notes                       = txNotes.Text.Trim(),
                    Logo                        = txLogo.Text.Trim(),
                    // 2 Program
                    InstallCommand              = txInstallCommand.Text.Trim(),
                    UninstallCommand            = txUninstallCommand.Text.Trim(),
                    PSADTInstallCommand         = txPsadtInstCmd.Text.Trim(),
                    PSADTUninstallCommand       = txPsadtUninstCmd.Text.Trim(),
                    AllowAvailableUninstall     = getAllowAvailableUninstall(),
                    InstallBehavior             = getInstallBehaviour(),
                    InstallationTime            = txInstallationTime.Text.Trim(),
                    DeviceRestartBehaviour      = getDeviceRestartBehaviour(),
                    // 3 Requirements
                    MinimumOperatingSystem      = getMinOs(),
                    OperatingSystemArchitecture = getOsArch(),
                    // 4 Detection
                    RulesFormat                          = getRulesFormat(),
                    DetectionTypeMSI                     = getDetTypeMSI(),
                    DetectionTypeFile                    = getDetTypeFile(),
                    DetectionTypeRegistry                = getDetTypeRegistry(),
                    DetectionMsiProductCode              = txMsiProductCode.Text.Trim(),
                    DetectionMsiVersionCheck             = getMsiVerCheck(),
                    DetectionMsiOperator                 = getMsiOperator(),
                    DetectionMsiValue                    = txMsiValue.Text.Trim(),
                    DetectionFileFolderPath              = txFilePath.Text.Trim(),
                    DetectionFileFileName                = txFileFile.Text.Trim(),
                    DetectionFileDetectionMethod               = getFileCheckType(),
                    DetectionFileOperator                = getFileOperator(),
                    DetectionFileValue                   = txFileValue.Text.Trim(),
                    DetectionFile32Bit                   = getFile32Bit(),
                    DetectionRegKeyPath                  = txRegKey.Text.Trim(),
                    DetectionRegValueName                = txRegVal.Text.Trim(),
                    DetectionRegDetectionMethod                = getRegCheckType(),
                    DetectionRegOperator                 = getRegOperator(),
                    DetectionRegistryValue               = txRegValue.Text.Trim(),
                    DetectionReg32Bit                    = getReg32Bit(),
                    DetectionScriptFile                  = txScriptFile.Text.Trim(),
                    DetectionScriptEnforceSignatureCheck = getScriptEnforce(),
                    DetectionScriptRunAs32Bit            = getScriptRunAs32(),
                    // 7 Assignments
                    AssignmentsAvailable        = txAssignAvail.Text.Trim(),
                    AppOwnerEmail               = txOwnerEmail.Text.Trim(),
                    SendMailToAppOwner          = getSendMail(),
                    MailSubject                 = txDlgMailSubject.Text.Trim(),
                    MailBody                    = txDlgMailBody.Text.Trim(),
                    Dependencies                = dlgDeps,
                    Supersedences               = dlgSups,
                    AddSupersedenceAutomatically = getAutoSupersede(),
                };
                // For API Type "URL" the Download Page URL points straight at the installer, so the
                // Rule Type follows the file extension: an .msi is detected by product code (MSI), an
                // .exe by its ARP registry key (Registry). This overrides whatever the Download
                // Preference left ticked - a leftover "MSI x64" tick on an .exe app is exactly the
                // wrong state to persist. File is left as the user set it; other API types are left
                // untouched (their Rule Type follows the Download Preference as before).
                if ((e.ApiType ?? "").Trim().Equals("URL", StringComparison.OrdinalIgnoreCase))
                {
                    string u = (e.DownloadPageUrl ?? "").Trim();
                    int cut = u.IndexOfAny(new[] { '?', '#' });   // drop any query/fragment before the extension
                    if (cut >= 0) u = u.Substring(0, cut);
                    string ext = System.IO.Path.GetExtension(u).ToLowerInvariant();
                    if (ext == ".msi")      { e.DetectionTypeMSI = "Yes"; e.DetectionTypeRegistry = "No";  }
                    else if (ext == ".exe") { e.DetectionTypeMSI = "No";  e.DetectionTypeRegistry = "Yes"; }
                }
                return e;
            }
            // ── Button bar ─────────────────────────────────────────────────
            var btnBar = new Border { BorderBrush = bBdr, BorderThickness = new Thickness(0, 1, 0, 0), Padding = new Thickness(16, 10, 16, 12) };
            Grid.SetRow(btnBar, 3); og.Children.Add(btnBar);
            var bAdd    = new Button { Content = isEdit ? "✔  Save" : "✔  Add", Style = sec, FontSize = 11, FontWeight = FontWeights.SemiBold, Height = 28, Padding = new Thickness(12, 0, 12, 0), Margin = new Thickness(0, 0, 8, 0) };
            SdApplyPrimaryLook(bAdd);
            var bImport = new Button { Content = "📂  Import",                   Style = sec, FontSize = 11, FontWeight = FontWeights.SemiBold, Height = 28, Padding = new Thickness(12, 0, 12, 0), Margin = new Thickness(0, 0, 8, 0) };
            var bSaveJson = new Button { Content = "💾  Save",                   Style = sec, FontSize = 11, FontWeight = FontWeights.SemiBold, Height = 28, Padding = new Thickness(12, 0, 12, 0), Margin = new Thickness(0, 0, 8, 0) };
            var bCncl   = new Button { Content = "✕  Cancel",                   Style = sec, FontSize = 11, FontWeight = FontWeights.SemiBold, Height = 28, Padding = new Thickness(12, 0, 12, 0) };
            var bp = new StackPanel { Orientation = Orientation.Horizontal };
            // Add mode shows only Add + Cancel. Import and Save (save-to-JSON) are Edit-time tools;
            // their Click handlers are still wired below, they are just not placed in the bar here,
            // so no logic changes.
            bp.Children.Add(bAdd);
            if (isEdit) { bp.Children.Add(bImport); bp.Children.Add(bSaveJson); }
            bp.Children.Add(bCncl);
            btnBar.Child = bp;

            // ── Populate helper (for Import) ───────────────────────────────
            // ── Helper: populate all fields from a DownloadSourceEntry (used by Import)
            Action<DownloadSourceEntry> PopulateFields = (e) =>
            {
                txVend.Text       = e.SourceAppVendor;
                txName.Text       = e.SourceAppName;
                txSrcVer.Text     = e.SourceAppVersion;
                { int ai2 = ApiTypeOptions.ToList().FindIndex(o => o.Equals(e.ApiType ?? "", StringComparison.OrdinalIgnoreCase)); cbApi.SelectedIndex = ai2 >= 0 ? ai2 : 0; }
                txRepo.Text       = e.GitHubRepo;
                txWinget.Text     = e.WingetPackageId;
                txUrl.Text        = e.DownloadPageUrl;
                txSiMSI.Text      = e.SilentInstallParameterMSI;
                txSuMSI.Text      = e.SilentUninstallParameterMSI;
                txSiEXE.Text      = e.SilentInstallParameterEXE;
                txSuEXE.Text      = e.SilentUninstallParameterEXE;
                txAVend.Text      = e.AppVendor;
            };

            // Store StackPanel refs for Yes/No radio rows so PopulateFields can update them
            // We rebuild with direct refs instead of walking:
            StackPanel? spDlPref=null, spInstSil=null, spUninstSil=null, spCreatePkg=null,
                        spInstPkgW=null, spUninstPkgW=null, spSrcDl=null,
                        spCreateIntunewin=null, spPublish=null, spDeplMach=null, spInstallBehaviour=null, spDetType=null,
                        spShowMsgBox=null, spAddInstallName=null, spAddInstallTitle=null,
                        spAddNoRemove=null, spAddNoModify=null, spAddNoRepair=null, spSendMail=null;
            foreach (var child in cg.Children.OfType<StackPanel>())
            {
                var rbs2 = child.Children.OfType<RadioButton>().ToList();
                if (!rbs2.Any()) continue;
                var opts = rbs2.Select(x => x.Content?.ToString() ?? "").ToList();
                if (opts.SequenceEqual(new[]{"MSI x64","MSI x86","EXE x64","EXE x86"})) spDlPref    = child;
                else if (opts.SequenceEqual(new[]{"MSI","File","Registry","Script"}))    spDetType    = child;
                else if (opts.SequenceEqual(new[]{"System","User"}))                     spInstallBehaviour = child;
            }
            // Wire Rules Format radios → UpdateDetVis (now that all rows are built).
            // MakeRadioRow hosts its radios in a WrapPanel, not a StackPanel, so the
            // previous OfType<StackPanel> scan silently found nothing and the radios
            // stayed unwired (toggling Rules Format never re-ran UpdateDetVis). Take
            // the panel from the addAppRadioPanels registry instead.
            if (addAppRadioPanels.TryGetValue("Rules Format", out var spRulesFormatDlg) && spRulesFormatDlg != null)
                foreach (var rb in spRulesFormatDlg.Children.OfType<RadioButton>())
                    rb.Checked += (_, _) => UpdateDetVis();
            UpdateDetVis();
            var yesNoPanels = cg.Children.OfType<StackPanel>()
                .Where(sp => sp.Children.OfType<RadioButton>().Select(x => x.Content?.ToString()).SequenceEqual(new[]{"Yes","No"}))
                .OrderBy(sp => Grid.GetRow(sp)).ToList();
            if (yesNoPanels.Count > 0)  spSrcDl          = yesNoPanels[0];
            if (yesNoPanels.Count > 1)  spInstSil        = yesNoPanels[1];
            if (yesNoPanels.Count > 2)  spUninstSil      = yesNoPanels[2];
            // spCreateMst and spRemoveDesktop are captured directly from MakeRadioRowEx above
            if (yesNoPanels.Count > 5)  spCreatePkg      = yesNoPanels[5];
            if (yesNoPanels.Count > 6)  spAddInstallName    = yesNoPanels[6];
            if (yesNoPanels.Count > 7)  spAddInstallTitle   = yesNoPanels[7];
            if (yesNoPanels.Count > 8)  spAddNoRemove    = yesNoPanels[8];
            if (yesNoPanels.Count > 9)  spAddNoModify    = yesNoPanels[9];
            if (yesNoPanels.Count > 10) spAddNoRepair    = yesNoPanels[10];
            if (yesNoPanels.Count > 11) spInstPkgW       = yesNoPanels[11];
            if (yesNoPanels.Count > 12) spUninstPkgW     = yesNoPanels[12];
            if (yesNoPanels.Count > 13) spShowMsgBox     = yesNoPanels[13];
            if (yesNoPanels.Count > 14) spCreateIntunewin= yesNoPanels[14];
            if (yesNoPanels.Count > 15) spPublish        = yesNoPanels[15];
            if (yesNoPanels.Count > 16) spDeplMach       = yesNoPanels[16];
            if (yesNoPanels.Count > 17) spSendMail       = yesNoPanels[17];

            void SetRb(StackPanel? sp2, string val) { if (sp2 == null) return; foreach (RadioButton rb in sp2.Children.OfType<RadioButton>()) rb.IsChecked = rb.Content?.ToString()?.Equals(val, StringComparison.OrdinalIgnoreCase) == true; }

            // Override PopulateFields with full version now that we have refs
            PopulateFields = (e) =>
            {
                txVend.Text       = e.SourceAppVendor;
                txName.Text       = e.SourceAppName;
                txSrcVer.Text     = e.SourceAppVersion;
                { int ai2 = ApiTypeOptions.ToList().FindIndex(o => o.Equals(e.ApiType ?? "", StringComparison.OrdinalIgnoreCase)); cbApi.SelectedIndex = ai2 >= 0 ? ai2 : 0; }
                txRepo.Text       = e.GitHubRepo;
                txWinget.Text     = e.WingetPackageId;
                txUrl.Text        = e.DownloadPageUrl;
                SetRb(spDlPref,    e.DownloadPreference);
                updateUninstallPathVisibility();
                txSiMSI.Text      = e.SilentInstallParameterMSI;
                txSuMSI.Text      = e.SilentUninstallParameterMSI;
                txSiEXE.Text      = e.SilentInstallParameterEXE;
                txSuEXE.Text      = e.SilentUninstallParameterEXE;
                SetRb(spInstSil,   e.InstallSourceSilently);
                SetRb(spUninstSil, e.UninstallSourceSilently);
                SetRb(spCreatePkg,     e.CreatePackage);
                SetRb(spCreateMst,     e.CreateMST);
                SetRb(spRemoveDesktop, e.RemoveDesktopShortcut);
                txTemplateFolder.Text = e.PSADTTemplateFolder ?? "";
                SetRb(spShowMsgBox,       e.ShowMessageBox);
                txPsadtInstCmd.Text   = string.IsNullOrWhiteSpace(e.PSADTInstallCommand)   ? DefaultPsadtInstallCommand   : e.PSADTInstallCommand;
                txPsadtUninstCmd.Text = string.IsNullOrWhiteSpace(e.PSADTUninstallCommand) ? DefaultPsadtUninstallCommand : e.PSADTUninstallCommand;
                SetRb(spAddInstallName,  e.AddInstallName);
                SetRb(spAddInstallTitle, e.AddInstallTitle);
                SetRb(spAddNoRemove,     string.IsNullOrWhiteSpace(e.AddNoRemove) ? "Yes" : e.AddNoRemove);
                SetRb(spAddNoModify,     string.IsNullOrWhiteSpace(e.AddNoModify) ? "Yes" : e.AddNoModify);
                SetRb(spAddNoRepair,     string.IsNullOrWhiteSpace(e.AddNoRepair) ? "Yes" : e.AddNoRepair);
                txAVend.Text      = e.AppVendor;
                txAName.Text      = e.AppName;
                txAppVer.Text     = e.AppVersion;
                SetRb(spInstPkgW,   e.InstallPackage);
                SetRb(spUninstPkgW, e.UninstallPackage);
                txUninstPath.Text = e.UninstallPath;
                txClose.Text      = e.CloseApps;
                SetRb(spSrcDl,     e.AutoDownloadSource);
                // Category combo (index 0 in main grid combos)
                var mainCombos = cg.Children.OfType<ComboBox>().OrderBy(c => Grid.GetRow(c)).ToList();
                if (mainCombos.Count > 0) mainCombos[0].Text = e.Category;
                // Schedule combos — set directly by reference using SelectedItem
                void SetComboVal(ComboBox cb2, string val) {
                    var idx = Enumerable.Range(0, cb2.Items.Count)
                        .FirstOrDefault(i => cb2.Items[i]?.ToString()?.Equals(val, StringComparison.OrdinalIgnoreCase) == true, 0);
                    cb2.SelectedIndex = idx;
                }
                SetComboVal(cbFreq,  string.IsNullOrWhiteSpace(e.DownloadFrequency) ? "None" : e.DownloadFrequency);
                SetComboVal(cbHour,  e.DownloadScheduleHour  ?? "");
                SetComboVal(cbDays, string.IsNullOrWhiteSpace(e.DownloadScheduleDays) ? "Monday" : e.DownloadScheduleDays);
                SetComboVal(cbDate, string.IsNullOrWhiteSpace(e.DownloadScheduleDate) ? "01" : e.DownloadScheduleDate.PadLeft(2, '0'));
                { var tp = (e.DownloadScheduleTime ?? "").Split(':'); var popHh = tp.Length>0 ? tp[0].PadLeft(2,'0') : "06"; if (popHh == "24") popHh = "00"; SetComboVal(cbTimeHour, popHh); SetComboVal(cbTimeMin, tp.Length>1 ? tp[1].PadLeft(2,'0') : "00"); }
                SetComboVal(cbMonth, string.IsNullOrWhiteSpace(e.DownloadScheduleMonth) ? "January" : e.DownloadScheduleMonth);
                SetComboVal(cbYear,  string.IsNullOrWhiteSpace(e.DownloadScheduleYear)  ? DateTime.Now.Year.ToString() : e.DownloadScheduleYear.Trim());
                SyncDialogDateItems();
                {
                    // The day list may now be shorter than 31 - the month and year decide it - so a
                    // stored day that no longer exists is shown as the last day of that month.
                    // SetComboVal alone would not find it and would drop back to the 1st.
                    int domE = int.TryParse((e.DownloadScheduleDate ?? "").Trim(), out int dE) && dE >= 1 ? dE : 1;
                    int maxE = cbDate.Items.Count > 0 ? cbDate.Items.Count : 1;
                    SetComboVal(cbDate, Math.Min(domE, maxE).ToString("D2"));
                }
            SetComboVal(cbOccurrence, string.IsNullOrWhiteSpace(e.DownloadOccurrence) ? "Second" : e.DownloadOccurrence);
                UpdateScheduleVisibility();
                SetRb(spCreateIntunewin, e.CreateIntunewin);
                SetRb(spPublish,   e.PublishSettings);
                SetRb(spDeplMach,  e.PublishToIntune);
                var intuneCatIdx2 = Array.FindIndex(intuneCatItems, c => c.Equals(e.IntuneCategory, StringComparison.OrdinalIgnoreCase));
                cbIntuneCat.SelectedIndex = intuneCatIdx2 >= 0 ? intuneCatIdx2 : 0;
                SetRb(spInstallBehaviour, e.InstallBehaviour);
                // Populate DetectionType checkboxes. Setting IsChecked raises Checked, which would
                // otherwise force MSI Version Check to Yes and overwrite the imported value, so the
                // auto-tick is suppressed for the duration of the restore.
                dlgSuppressMsiVcAutoTick = true;
                cbDetMsi.IsChecked    = (e.DetectionTypeMSI      ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase);
                cbDetFile.IsChecked   = (e.DetectionTypeFile     ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase);
                cbDetReg.IsChecked    = (e.DetectionTypeRegistry ?? "No").Equals("Yes", StringComparison.OrdinalIgnoreCase);
                dlgSuppressMsiVcAutoTick = false;
                // Imported rule types are real data, not the seeded default, so a later preference
                // change must add to them rather than replace them.
                dlgRuleTypeChosen = true;
                // cbDetScript removed — Detection Type Script row no longer shown
                txAssignAvail.Text  = e.AssignmentsAvailable ?? "";
                txDesc.Text         = e.Description;
                // New fields
                var intuneCatIdxPop = Array.FindIndex(intuneCatItems, c => c.Equals(e.IntuneCategory, StringComparison.OrdinalIgnoreCase));
                cbIntuneCat.SelectedIndex = intuneCatIdxPop >= 0 ? intuneCatIdxPop : 0;
                txOwnerEmail.Text = e.AppOwnerEmail;
                txDlgMailSubject.Text = e.MailSubject;
                txDlgMailBody.Text    = e.MailBody;
                SetRb(spSendMail,  string.IsNullOrWhiteSpace(e.SendMailToAppOwner) ? "No" : e.SendMailToAppOwner);
                dlgDeps.Clear();
                foreach (var d in e.Dependencies) dlgDeps.Add(new DependencyItem { AppName = d.AppName, AppID = d.AppID, AutoInstall = d.AutoInstall });
                RebuildDlgDeps();
                dlgSups.Clear();
                foreach (var s in e.Supersedences) dlgSups.Add(new SupersedenceItem { AppName = s.AppName, AppID = s.AppID, UninstallPreviousVersion = s.UninstallPreviousVersion });
                RebuildDlgSups();
                // MakeRadioRow hosts its radios in a WrapPanel, so SetRb (which walks StackPanels)
                // cannot reach this row. Take the panel from the addAppRadioPanels registry.
                if (addAppRadioPanels.TryGetValue("Add Supersedence Automatically", out var spAutoSupDlg) && spAutoSupDlg != null)
                {
                    string autoSupVal = string.IsNullOrWhiteSpace(e.AddSupersedenceAutomatically) ? "Yes" : e.AddSupersedenceAutomatically;
                    foreach (var rb in spAutoSupDlg.Children.OfType<RadioButton>())
                        rb.IsChecked = rb.Content?.ToString()?.Equals(autoSupVal, StringComparison.OrdinalIgnoreCase) == true;
                }
            };

            if (existing != null) PopulateFields(existing);

            // ── Modification tracking ──────────────────────────────────────
            bool isDirty = false;
            // Set once the app is saved and the window is intentionally closing, so a late async
            // manifest fetch that re-dirties a field cannot trigger the unsaved-changes prompt.
            bool closingAfterSave = false;
            bool importMode = false; // true after Import clicked, Add is disabled

            void MarkDirty(object? s, System.Windows.RoutedEventArgs e2) { isDirty = true; }
            void MarkDirtyText(object? s, System.Windows.Controls.TextChangedEventArgs e2) { isDirty = true; }

            // Wire all text boxes
            foreach (var tx in cg.Children.OfType<TextBox>())
                tx.TextChanged += MarkDirtyText;
            // Wire all radio buttons
            foreach (var sp2 in cg.Children.OfType<StackPanel>())
                foreach (var rb in sp2.Children.OfType<RadioButton>())
                    rb.Checked += MarkDirty;
            // Wire main combos
            foreach (var cb2 in cg.Children.OfType<Border>().Select(b => b.Child).OfType<ComboBox>())
                cb2.SelectionChanged += (s, e2) => isDirty = true;
            // Wire schedule combos
            cbFreq.SelectionChanged  += (s, e2) => isDirty = true;
            cbHour.SelectionChanged  += (s, e2) => isDirty = true;
            cbDays.SelectionChanged += (s, e2) => isDirty = true;
            cbDate.SelectionChanged += (s, e2) => isDirty = true;
            // Minutes stay selectable for every hour now that 24 (which forced minutes to 00) is gone.
            cbTimeHour.SelectionChanged += (s, e2) => isDirty = true;
            cbTimeMin.SelectionChanged  += (s, e2) => isDirty = true;
            cbMonth.SelectionChanged += (s, e2) => isDirty = true;
            cbOccurrence.SelectionChanged += (s, e2) => isDirty = true;
            cbRestart.SelectionChanged += (s, e2) => isDirty = true;
            cbMinOs.SelectionChanged   += (s, e2) => isDirty = true;

            // ── Uninstall Path / MST visibility is now handled in the scoped block above ──


            bImport.Click += (_, _) =>
            {
                var dlg = new Microsoft.Win32.OpenFileDialog
                {
                    Title            = "Import App JSON",
                    Filter           = "JSON files (*.json)|*.json|All files (*.*)|*.*",
                    InitialDirectory = !string.IsNullOrWhiteSpace(_packageInputFolder) ? _packageInputFolder : "",
                };
                if (dlg.ShowDialog(win) == true)
                {
                    try
                    {
                        var imported = JsonSerializer.Deserialize<DownloadSourceEntry>(
                            File.ReadAllText(dlg.FileName),
                            new JsonSerializerOptions { PropertyNameCaseInsensitive = true });
                        if (imported != null)
                        {
                            PopulateFields(imported);
                            importMode = true;
                            bAdd.IsEnabled = false;
                            bAdd.Opacity   = 0.4;
                            isDirty = false; // imported state is not "dirty" yet
                        }
                    }
                    catch { ShowStyledInfoDialog(win, "Source Download - Import Error", "⚠", new[] { ("Error", "Failed to read JSON file.") }); }
                }
            };

            // ── Save JSON: writes straight to the app's own file, no file picker
            //
            // The picker was asking a question with one right answer. An app's JSON is found again
            // through GetAppJsonPath - PackageTemplateFolder plus Vendor_AppName.json - so any other
            // location is a copy nothing ever reads, and offering the same path every time meant
            // Windows then asked whether to replace the file already sitting there. Two dialogs to
            // save a file to the one place it can go.
            bSaveJson.Click += (_, _) =>
            {
                var entry = ReadFields();
                try
                {
                    // An established app already knows its folder.
                    string? target = GetAppJsonPath(entry);

                    // Not added yet, so PackageTemplateFolder is still blank. Build the same
                    // <PackageInputFolder>\<Vendor>\<AppName> structure the Add button creates, so
                    // saving now and adding later land on one file rather than two.
                    if (string.IsNullOrWhiteSpace(target) && !string.IsNullOrWhiteSpace(_packageInputFolder))
                    {
                        string sv = (entry.SourceAppVendor ?? "").Trim();
                        string sn = (entry.SourceAppName   ?? "").Trim();
                        foreach (char c in Path.GetInvalidFileNameChars())
                        { sv = sv.Replace(c, '_'); sn = sn.Replace(c, '_'); }
                        if (string.IsNullOrWhiteSpace(sv)) sv = "Unknown";

                        string appFolder = Path.Combine(_packageInputFolder, sv, sn);
                        Directory.CreateDirectory(appFolder);
                        entry.PackageTemplateFolder = appFolder;
                        target = GetAppJsonPath(entry);
                    }

                    // The one case still worth a window: there is genuinely nowhere to write.
                    if (string.IsNullOrWhiteSpace(target))
                    {
                        ShowStyledInfoDialog(win, "Source Download - Save Error", "⚠", new[]
                        {
                            ("Error", "This app has no folder yet. Set the Package Input Folder in Settings, or add the app first."),
                        });
                        return;
                    }

                    string? dir = Path.GetDirectoryName(target);
                    if (!string.IsNullOrWhiteSpace(dir)) Directory.CreateDirectory(dir);
                    File.WriteAllText(target, JsonSerializer.Serialize(entry,
                        new JsonSerializerOptions { WriteIndented = true }));

                    // Re-enable Add after successful save
                    importMode     = false;
                    bAdd.IsEnabled = true;
                    bAdd.Opacity   = 1.0;
                    isDirty        = false;
                }
                catch { ShowStyledInfoDialog(win, "Source Download - Save Error", "⚠", new[] { ("Error", "Failed to save JSON file.") }); }
            };

            // ── Add / Save to app list
            bAdd.Click += async (_, _) =>
            {
                // Add mode has no Select button. Commit the nearest match highlighted in the inline
                // results (winget / github) so its Winget Package ID / GitHub Repo and the derived
                // vendor / name / version are filled before validation and save. Only when identity
                // is still empty, so a row the user already double-clicked is not re-applied.
                if (!isEdit)
                {
                    string apiTypeSel = (cbApi.SelectedItem as string ?? "URL").Trim();
                    bool identityEmpty = string.IsNullOrWhiteSpace(txVend.Text)
                                      && string.IsNullOrWhiteSpace(txName.Text)
                                      && string.IsNullOrWhiteSpace(txSrcVer.Text);
                    if (identityEmpty)
                    {
                        if (apiTypeSel.Equals("winget", StringComparison.OrdinalIgnoreCase)) applyInlineWinget?.Invoke();
                        else if (apiTypeSel.Equals("github", StringComparison.OrdinalIgnoreCase)) applyInlineGitHub?.Invoke();
                    }

                    // The apply above starts an async manifest fetch that fills the EXE silent
                    // switches (the winget/github catalog carries none). Wait for it - bounded so a
                    // slow or offline fetch never hangs Add - so ReadFields captures the switches.
                    if (pendingSilentFetch != null)
                    {
                        bAdd.IsEnabled = false;
                        try { await Task.WhenAny(pendingSilentFetch, Task.Delay(6000)); }
                        catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                        bAdd.IsEnabled = true;
                    }
                }

                // ── Validate mandatory fields (marked with * in the form) ──
                var missing = new List<string>();
                if (string.IsNullOrWhiteSpace(txVend.Text))   missing.Add("Source App Vendor");
                if (string.IsNullOrWhiteSpace(txName.Text))   missing.Add("Source App Name");
                if (string.IsNullOrWhiteSpace(txSrcVer.Text)) missing.Add("Source App Version");
                // API Type is a dropdown now - it can never be blank, so there is nothing to miss.
                if (isEdit)
                {
                    // Add mode only shows the Application settings tab (App Identity); Package
                    // settings, Intune settings and Description/Rule Type live on tabs it hides, so
                    // they are only checked here in Edit mode, where the full form is visible.
                    if (string.IsNullOrWhiteSpace(txAVend.Text))  missing.Add("App Vendor");
                    if (string.IsNullOrWhiteSpace(txAName.Text))  missing.Add("App Name");
                    if (string.IsNullOrWhiteSpace(txAppVer.Text)) missing.Add("App Version");
                    if (string.IsNullOrWhiteSpace(txIntuneAppName.Text))   missing.Add("App Name (Intune)");
                    if (string.IsNullOrWhiteSpace(txIntuneAppVendor.Text)) missing.Add("App Vendor (Intune)");
                    if (string.IsNullOrWhiteSpace(txDesc.Text))   missing.Add("Description");
                    // Rule Type: at least one detection type must be selected in Manual mode.
                    bool manualDet = getRulesFormat().Equals("Manual detection rules", StringComparison.OrdinalIgnoreCase);
                    bool anyRuleType = getDetTypeMSI() == "Yes" || getDetTypeFile() == "Yes" || getDetTypeRegistry() == "Yes";
                    if (manualDet && !anyRuleType) missing.Add("Rule Type");
                }
                if (missing.Count > 0)
                {
                    string apiTypeNow = (cbApi.SelectedItem as string ?? "URL").Trim();
                    bool hasPicker = apiTypeNow.Equals("winget", StringComparison.OrdinalIgnoreCase)
                                  || apiTypeNow.Equals("github", StringComparison.OrdinalIgnoreCase);
                    if (!isEdit && hasPicker)
                        // Add mode hides the identity/package/intune fields; they are filled by the
                        // Download Source picker. If they are still empty the user has not picked a
                        // package yet, so point them at Search rather than at fields they cannot see.
                        ShowStyledInfoDialog(win, "Source Download - Select a Package", "⚠️", new[]
                        {
                            ("Pick a source", "Choose an API Type, then search and select an application."),
                            ("Why",           "That fills the app's vendor, name and version automatically. Once a package is selected you can add it, and configure the rest from the app's Package Information after adding."),
                        });
                    else
                        // Manual API Types (none / Vendor API) show Source App Vendor / Name / Version
                        // right here (App Identity is unmasked for them), so a missing value really is
                        // a blank required box - list it, same as Edit mode.
                        ShowStyledInfoDialog(win, "Source Download - Required Fields", "⚠️", new[]
                        {
                            ("Required", "Please fill the fields marked with * before adding:"),
                            ("Missing",  string.Join(", ", missing)),
                        });
                    return;
                }
                var entry = ReadFields();
                if (isEdit && existing != null)
                {
                    // Copy all fields back onto existing entry
                    var props = typeof(DownloadSourceEntry).GetProperties();
                    foreach (var p in props) p.SetValue(existing, p.GetValue(entry));
                }
                else
                {
                    // Prevent adding a duplicate: an application with the same Source App Vendor +
                    // Source App Name (case-insensitive) is already in the list.
                    bool duplicate = _allApps.Any(a =>
                        string.Equals((a.SourceAppVendor ?? "").Trim(), (entry.SourceAppVendor ?? "").Trim(), StringComparison.OrdinalIgnoreCase) &&
                        string.Equals((a.SourceAppName   ?? "").Trim(), (entry.SourceAppName   ?? "").Trim(),   StringComparison.OrdinalIgnoreCase));
                    if (duplicate)
                    {
                        ShowStyledInfoDialog(win, "Source Download - Already Exists", "⚠️", new[]
                        {
                            ("Already exists", $"'{entry.SourceAppName}' from vendor '{entry.SourceAppVendor}' is already in the list."),
                            ("Tip",            "Edit the existing application instead, or use a different Source App Vendor / Name."),
                        });
                        return;
                    }
                    _allApps.Add(entry);
                }
                SaveApps();

                SaveApps();
                // Re-read the configured PackageInputFolder FRESH from AutoPackage.json on
                // disk so a stale in-memory value can't redirect folder creation to the
                // installed default (e.g. ...\Templates\Packages) instead of the configured
                // path (e.g. C:\Temp\Source).
                try
                {
                    if (File.Exists(JsonPath))
                    {
                        string diskPif = ExtractJsonString(File.ReadAllText(JsonPath), "PackageInputFolder");
                        if (!string.IsNullOrWhiteSpace(diskPif)) _packageInputFolder = diskPif;
                    }
                }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                // ── Create folder structure and per-app JSON for new apps
                string createdFolder = "";
                if (!isEdit && !string.IsNullOrWhiteSpace(_packageInputFolder))
                {
                    try
                    {
                        // Sanitise each part for use as a folder/file name
                        string sv = (entry.SourceAppVendor ?? "").Trim();
                        string sn = (entry.SourceAppName   ?? "").Trim();
                        foreach (char c in Path.GetInvalidFileNameChars())
                        { sv = sv.Replace(c,'_'); sn = sn.Replace(c,'_'); }
                        if (string.IsNullOrWhiteSpace(sv)) sv = "Unknown";

                        // New structure: <PackageInputFolder>\<Vendor>\<AppName>\
                        string appFolderName = sn;
                        string appFolder     = Path.Combine(_packageInputFolder, sv, appFolderName);
                        Directory.CreateDirectory(appFolder);
                        Directory.CreateDirectory(Path.Combine(appFolder, "Files"));
                        createdFolder = appFolder;

                        entry.PackageTemplateFolder = appFolder;
                        var saved = _allApps.LastOrDefault();
                        if (saved != null) saved.PackageTemplateFolder = appFolder;

                        // Write JSON as Vendor_AppName.json (matches GetAppJsonPath)
                        string jsonFileName = $"{entry.SourceAppVendor}_{entry.SourceAppName}.json";
                        string jsonFile     = Path.Combine(appFolder, jsonFileName);
                        File.WriteAllText(jsonFile, JsonSerializer.Serialize(entry,
                            new JsonSerializerOptions { WriteIndented = true }));
                        // Remove any stale wrongly-named JSON files
                        foreach (string stale in Directory.GetFiles(appFolder, "*.json"))
                            if (!stale.Equals(jsonFile, StringComparison.OrdinalIgnoreCase))
                                try { File.Delete(stale); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }

                        SaveApps();

                        // Icon.png is deliberately NOT created here anymore. The old vendor-site
                        // fetch fell back to a 16/32/64px favicon when the site had no large
                        // apple-touch-icon, and because it wrote Icon.png up front the Execute
                        // (Install) step - which only writes when Icon.png is absent - was never
                        // reached, so the tiny favicon won. The 256px logo taken from the installed
                        // application's own icon at Execute time is the single source now.
                    }
                    catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                }

                isDirty = false;
                closingAfterSave = true;

                // The row just written: on an edit the field values were copied onto `existing`,
                // on an add it is the new entry.
                var justSaved = isEdit && existing != null ? existing : entry;

                // Both the category chip and the search box filter RenderVendors AND RenderCards, so
                // an app can be saved correctly into a list that is currently filtered to exclude it
                // and still not appear. Clear whichever one would hide the row we are about to
                // select, rather than re-rendering into a view it cannot show up in.
                if (_activeCategory != "All"
                    && !string.Equals(justSaved.Category ?? "", _activeCategory, StringComparison.OrdinalIgnoreCase))
                {
                    _activeCategory = "All";
                    if (BtnChipAll != null)
                        BtnChipAll.Style = (Style)(TryFindResource("ChipActiveStyle") ?? new Style());
                }
                if (!string.IsNullOrWhiteSpace(_searchText) && TxtSearch != null
                    && !(justSaved.SourceAppName   ?? "").Contains(_searchText, StringComparison.OrdinalIgnoreCase)
                    && !(justSaved.SourceAppVendor ?? "").Contains(_searchText, StringComparison.OrdinalIgnoreCase))
                    TxtSearch.Text = "";        // TextChanged resets _searchText and re-renders

                BuildCategoryChips();

                // RenderVendors was the missing call. This path rebuilt the chips and the CARD list
                // only, so a brand new vendor never entered the master panel: it appeared only once
                // something else happened to re-render it - leaving the page and coming back, or
                // clicking another vendor, which calls RenderVendors to move the highlight. That is
                // what the "click Refresh" note in the dialog below was compensating for, and there
                // is no Refresh button in the toolbar any more.
                //
                // SelectAppAnyVendor does the whole job in the right order: sets _selectedVendor,
                // re-renders the vendor list, selects the app (which calls RenderCards) and scrolls
                // the vendor into view. It also follows a vendor RENAME on an edit, which the old
                // RenderCards-only call could not.
                SelectAppAnyVendor(justSaved);

                if (!isEdit && !string.IsNullOrWhiteSpace(createdFolder))
                    ShowStyledInfoDialog(win, "Source Download - App Added", "✅", new[]
                    {
                        ("Status", "The app was added successfully."),
                        ("Folder", createdFolder),
                        ("Next",   $"'{justSaved.SourceAppName}' is now selected under vendor '{justSaved.SourceAppVendor}' in the Download tab."),
                    },
                    actionButton: ("📂  Open Folder", () => { try { System.Diagnostics.Process.Start("explorer.exe", $"\"{createdFolder}\""); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); } }));
                win.Close();
            };

            bCncl.Click += (_, _) => win.Close(); // Closing event handles confirmation
            // Note: tcl.Click already wired above in title bar setup
            win.Closing += (_, e2) =>
            {
                if (closingAfterSave || !isDirty) return;
                e2.Cancel = true;

                // ── Styled confirmation dialog — matches Execute Package Cancel pattern
                bool confirmed = false;
                var winBg2     = Res("WindowBgBrush", Brushes.White);
                var borderClr2 = Res("BorderMainBrush", Brushes.LightGray);
                var boxBg2     = Res("InputBgBrush", new SolidColorBrush(Color.FromRgb(0xF0, 0xF1, 0xF8)));
                var boxBdr2    = Res("BorderMainBrush", new SolidColorBrush(Color.FromRgb(0xDD, 0xDF, 0xEA)));
                var lblFg2     = Res("TextSecondaryBrush", Brushes.Gray);
                var valFg2     = Res("TextPrimaryBrush", Brushes.Black);
                var sec2       = Application.Current.TryFindResource("SecondaryButtonStyle") as Style;
                var titleBarBg = new SolidColorBrush(Color.FromRgb(0x53, 0x56, 0x63));

                var cwin = new Window
                {
                    Width = 460, SizeToContent = SizeToContent.Height,
                    WindowStartupLocation = WindowStartupLocation.CenterOwner,
                    Owner = win, ResizeMode = ResizeMode.NoResize,
                    WindowStyle = WindowStyle.None, AllowsTransparency = true,
                    Background = Brushes.Transparent,
                    FontFamily = new System.Windows.Media.FontFamily("Segoe UI"), ShowInTaskbar = false
                };
                var outer2 = new Border { Background = winBg2, BorderBrush = borderClr2, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(10), Effect = new System.Windows.Media.Effects.DropShadowEffect { BlurRadius = 16, ShadowDepth = 2, Opacity = 0.18, Color = Colors.Black } };
                cwin.Content = outer2;
                var og2 = new Grid();
                og2.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                og2.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                outer2.Child = og2;

                // Title bar
                var tb2 = new Border { Background = titleBarBg, BorderThickness = new Thickness(0,0,0,1), BorderBrush = titleBarBg, CornerRadius = new CornerRadius(10,10,0,0), Padding = new Thickness(16,6,12,6) };
                tb2.MouseLeftButtonDown += (_, _) => cwin.DragMove();
                Grid.SetRow(tb2, 0);
                var tg2 = new Grid();
                tg2.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                tg2.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                tg2.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                var ti2 = new TextBlock { Text = "📥", FontSize = 13, Foreground = Brushes.White, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0,0,8,0) };
                var tt2 = new TextBlock { Text = "Source Download - Unsaved Changes", FontSize = 13, FontWeight = FontWeights.SemiBold, Foreground = Brushes.White, VerticalAlignment = VerticalAlignment.Center };
                var tc2 = new Button { Content = "✕", FontSize = 11, Foreground = new SolidColorBrush(Color.FromArgb(0xCC,0xFF,0xFF,0xFF)), Background = Brushes.Transparent, BorderThickness = new Thickness(0), Cursor = System.Windows.Input.Cursors.Hand, VerticalAlignment = VerticalAlignment.Center, Padding = new Thickness(6,2,6,2) };
                tc2.Click += (_, _) => cwin.Close();
                Grid.SetColumn(ti2,0); Grid.SetColumn(tt2,1); Grid.SetColumn(tc2,2);
                tg2.Children.Add(ti2); tg2.Children.Add(tt2); tg2.Children.Add(tc2);
                tb2.Child = tg2; og2.Children.Add(tb2);

                // Body
                var root2 = new Grid { Margin = new Thickness(8) };
                Grid.SetRow(root2, 1); og2.Children.Add(root2);
                var dg2 = new Grid();
                dg2.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(62) });
                dg2.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                dg2.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                dg2.RowDefinitions.Add(new RowDefinition { Height = new GridLength(8) });
                dg2.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                dg2.RowDefinitions.Add(new RowDefinition { Height = new GridLength(8) });
                dg2.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

                Border MkBox2(string text) { var b = new Border { Background = boxBg2, BorderBrush = boxBdr2, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(6), Padding = new Thickness(10,6,10,6) }; b.Child = new TextBlock { Text = text, FontSize = 11, TextWrapping = TextWrapping.Wrap, Foreground = valFg2 }; return b; }
                TextBlock MkLbl2(string text) => new TextBlock { Text = text, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg2, VerticalAlignment = VerticalAlignment.Center };

                var l0 = MkLbl2("Status"); var b0 = MkBox2("You have unsaved changes.");
                var l1 = MkLbl2("Action"); var b1 = MkBox2("Are you sure you want to cancel?");
                Grid.SetRow(l0,0); Grid.SetColumn(l0,0); Grid.SetRow(b0,0); Grid.SetColumn(b0,1);
                Grid.SetRow(l1,2); Grid.SetColumn(l1,0); Grid.SetRow(b1,2); Grid.SetColumn(b1,1);
                dg2.Children.Add(l0); dg2.Children.Add(b0);
                dg2.Children.Add(l1); dg2.Children.Add(b1);

                var bg2 = new System.Windows.Controls.Primitives.UniformGrid { Rows = 1, Columns = 2 };
                var by2 = new Button { Content = "✔  Yes", Style = sec2, FontSize = 11, FontWeight = FontWeights.SemiBold, Height = 28, Padding = new Thickness(6,0,6,0), Margin = new Thickness(0,0,4,0) };
                SdApplyPrimaryLook(by2);
                by2.Click += (_, _) => { confirmed = true; cwin.Close(); };
                var bn2 = new Button { Content = "✕  No",  Style = sec2, FontSize = 11, FontWeight = FontWeights.SemiBold, Height = 28, Padding = new Thickness(6,0,6,0), Margin = new Thickness(4,0,0,0), IsDefault = true };
                bn2.Click += (_, _) => { confirmed = false; cwin.Close(); };
                bg2.Children.Add(by2); bg2.Children.Add(bn2);
                Grid.SetRow(bg2,4); Grid.SetColumn(bg2,1);
                dg2.Children.Add(bg2);
                var icon2 = SdDecisionIcon();
                Grid.SetRow(icon2,4); Grid.SetColumn(icon2,0);
                dg2.Children.Add(icon2);
                root2.Children.Add(dg2);
                cwin.ShowDialog();

                if (confirmed)
                {
                    isDirty = false;
                    win.Dispatcher.BeginInvoke(new Action(() => win.Close()),
                        System.Windows.Threading.DispatcherPriority.Background);
                }
            };

            // ---- Section tabs: Application settings / Package settings / Intune settings ----
            // Mirror the Package Information column. The form stays one Grid; a tab is shown by
            // restoring its sections' rows to their saved heights and hidden by forcing those rows
            // to 0. Child Visibility inside a section is left to the existing conditional logic
            // (schedule fields, MST/Remove Desktop, detection type): a masked section's controls are
            // hidden and cannot fire those conditionals, and the exact heights/visibilities are saved
            // on mask and restored on show, so the two never fight. The one cross-tab rule (Download
            // Preference drives the MST/Remove Desktop row heights) is re-asserted whenever the
            // Package tab is shown, so those rows always match the current preference.
            {
                var savedRowH  = new Dictionary<int, GridLength>();
                var savedMinH  = new Dictionary<int, double>();
                var savedVis   = new Dictionary<UIElement, Visibility>();
                var maskedSecs = new HashSet<int>();
                bool IsZeroH(GridLength g) => g.IsAbsolute && g.Value == 0.0;

                void MaskSec(int si, int start, int end)
                {
                    maskedSecs.Add(si);
                    for (int ri = start; ri < end && ri < cg.RowDefinitions.Count; ri++)
                    {
                        var rd = cg.RowDefinitions[ri];
                        // Height=0 alone will not collapse a row that has MinHeight (MakeRadioRow rows
                        // set MinHeight=28), so zero MinHeight too and restore both on show.
                        if (!IsZeroH(rd.Height) || rd.MinHeight > 0)
                        {
                            savedRowH[ri] = rd.Height; savedMinH[ri] = rd.MinHeight;
                            rd.Height = new GridLength(0); rd.MinHeight = 0;
                        }
                    }
                    foreach (UIElement ch in cg.Children)
                    {
                        int rr = Grid.GetRow(ch);
                        if (rr >= start && rr < end && ch.Visibility != Visibility.Collapsed)
                        { savedVis[ch] = ch.Visibility; ch.Visibility = Visibility.Collapsed; }
                    }
                }

                void ShowSec(int si, int start, int end)
                {
                    if (!maskedSecs.Remove(si)) return;
                    for (int ri = start; ri < end && ri < cg.RowDefinitions.Count; ri++)
                    {
                        if (savedRowH.TryGetValue(ri, out var h)) { cg.RowDefinitions[ri].Height = h; savedRowH.Remove(ri); }
                        if (savedMinH.TryGetValue(ri, out var mh)) { cg.RowDefinitions[ri].MinHeight = mh; savedMinH.Remove(ri); }
                    }
                    foreach (UIElement ch in cg.Children)
                    {
                        int rr = Grid.GetRow(ch);
                        if (rr >= start && rr < end && savedVis.TryGetValue(ch, out var v))
                        { ch.Visibility = v; savedVis.Remove(ch); }
                    }
                }

                Button MakeDlgTab(string text)
                {
                    return new Button
                    {
                        Content = text, FontSize = 11, Height = 26,
                        Margin = new Thickness(2, 0, 2, 0), Cursor = System.Windows.Input.Cursors.Hand,
                        BorderThickness = new Thickness(1), Template = RoundedTabButtonTemplate(),
                    };
                }
                var dlgTabApp    = MakeDlgTab("Application settings");
                var dlgTabPkg    = MakeDlgTab("Package settings");
                var dlgTabIntune = MakeDlgTab("Intune settings");
                var dlgTabEmail  = MakeDlgTab("Email settings");

                void StyleDlgTab(Button b, bool active)
                {
                    if (active)
                    {
                        b.SetResourceReference(Control.BackgroundProperty,  "AccentBlueBrush");
                        b.SetResourceReference(Control.BorderBrushProperty, "AccentBlueBrush");
                        b.Foreground = Brushes.White;
                        b.FontWeight = FontWeights.Bold;
                    }
                    else
                    {
                        b.SetResourceReference(Control.BackgroundProperty,  "InputBgBrush");
                        b.SetResourceReference(Control.BorderBrushProperty, "BorderMainBrush");
                        b.SetResourceReference(Control.ForegroundProperty,  "TextSecondaryBrush");
                        b.FontWeight = FontWeights.SemiBold;
                    }
                }

                // In Add mode the form is slimmed to the Download Source pickers only. Download
                // Schedule and Silent Parameters are built (so all controls, getters and auto-fill
                // keep working and Add can save) but never shown. App Identity is different: winget
                // and github fill Source App Vendor/Name/Version from the picker, so it stays hidden
                // for those two - but none/Vendor API have no picker, so it has to be shown and
                // filled by hand, or there is no way to give the app an identity at all. On Edit the
                // set is empty (the full form is always shown).
                var hiddenSections = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                if (!isEdit)
                {
                    hiddenSections.Add("Download Schedule");
                    hiddenSections.Add("Silent Parameters");
                }
                updateIdentitySectionVisibility = () =>
                {
                    if (isEdit) return;
                    string apiTypeNow = (cbApi.SelectedItem as string ?? "URL").Trim();
                    bool hasPicker = apiTypeNow.Equals("winget", StringComparison.OrdinalIgnoreCase)
                                  || apiTypeNow.Equals("github", StringComparison.OrdinalIgnoreCase);
                    if (hasPicker) hiddenSections.Add("App Identity");
                    else           hiddenSections.Remove("App Identity");
                };
                updateIdentitySectionVisibility();

                void ShowDlgTab(string tab)
                {
                    dlgActiveTab = tab;
                    for (int si = 0; si < dlgSections.Count; si++)
                    {
                        int start = dlgSections[si].startRow;
                        int end   = (si + 1 < dlgSections.Count) ? dlgSections[si + 1].startRow : cg.RowDefinitions.Count;
                        bool belongsToTab = PkgTabForSection(dlgSections[si].title) == tab;
                        bool forceHidden  = hiddenSections.Contains(dlgSections[si].title);
                        if (belongsToTab && !forceHidden) ShowSec(si, start, end);
                        else MaskSec(si, start, end);
                    }
                    // Package settings owns the one cross-tab height rule (Download Preference drives
                    // the MST / Remove Desktop rows). Re-assert it whenever that tab is shown so those
                    // rows reflect the current preference, even if it changed while the tab was hidden.
                    if (tab == "pkg") updateUninstallPathVisibility();
                    if (tab == "app") UpdateScheduleVisibility();
                    // Intune settings owns the Rules Format show/hide rules; re-assert
                    // them whenever the tab is shown so Manual vs Custom script rows
                    // reflect the current selection.
                    if (tab == "intune") UpdateDetVis();
                    StyleDlgTab(dlgTabApp,    tab == "app");
                    StyleDlgTab(dlgTabPkg,    tab == "pkg");
                    StyleDlgTab(dlgTabIntune, tab == "intune");
                    StyleDlgTab(dlgTabEmail,  tab == "email");
                    sv.ScrollToTop();
                }

                dlgTabApp.Click    += (_, _) => ShowDlgTab("app");
                dlgTabPkg.Click    += (_, _) => ShowDlgTab("pkg");
                dlgTabIntune.Click += (_, _) => ShowDlgTab("intune");
                dlgTabEmail.Click  += (_, _) => ShowDlgTab("email");
                reapplyDlgTab = () => ShowDlgTab(dlgActiveTab);

                // Add mode shows only the Application settings tab (Download Source pickers). The
                // Package / Intune / Email sections are still built - so their controls exist for
                // save/logic - but there is no tab to reach them, and ShowDlgTab masks them. Edit
                // keeps all four tabs.
                var tabStrip = new System.Windows.Controls.Primitives.UniformGrid { Rows = 1, Columns = isEdit ? 4 : 1 };
                tabStrip.Children.Add(dlgTabApp);
                if (isEdit)
                {
                    tabStrip.Children.Add(dlgTabPkg);
                    tabStrip.Children.Add(dlgTabIntune);
                    tabStrip.Children.Add(dlgTabEmail);
                }
                // Add mode has a single logical tab (Download Source), so the tab strip is
                // redundant - skip the whole strip row. Masking still runs via ShowDlgTab("app")
                // below. Edit keeps the four-tab strip.
                if (isEdit)
                {
                    var tabHost = new Border
                    {
                        Background = winBg,
                        BorderBrush = Res("BorderMainBrush", Brushes.LightGray),
                        BorderThickness = new Thickness(0, 0, 0, 1),
                        Padding = new Thickness(16, 8, 16, 8),
                    };
                    tabHost.Child = tabStrip;
                    Grid.SetRow(tabHost, 1);
                    og.Children.Add(tabHost);
                }

                ShowDlgTab("app");   // start on Application settings
            }

            win.ShowDialog();
        }

        /// <summary>
        /// Professional styled information dialog matching the app's dark title-bar
        /// chrome (rounded border, drop shadow, drag-move title bar). Renders one
        /// label/value row per entry in <paramref name="rows"/> with a single OK
        /// button. Used for the app-added confirmation and required-field prompts.
        /// </summary>
        private void BtnSettings_Click(object sender, RoutedEventArgs e) => OpenSettingsDialog();

        /// <summary>
        /// Modal editor over AutoPackage.json. Loads the current values, lets the user edit a
        /// curated set of global settings, and writes the changes back with every other key
        /// (MSTProperties and anything else) preserved via a JsonNode round-trip.
        /// </summary>
        private void OpenSettingsDialog()
        {
            System.Text.Json.Nodes.JsonObject root;
            try
            {
                var docOpts = new JsonDocumentOptions { AllowTrailingCommas = true, CommentHandling = JsonCommentHandling.Skip };
                root = (File.Exists(JsonPath)
                    ? System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(JsonPath), null, docOpts)?.AsObject()
                    : null) ?? new System.Text.Json.Nodes.JsonObject();
            }
            catch
            {
                ShowStyledInfoDialog(Window.GetWindow(this)!, "Settings", "⚠️", new[]
                {
                    ("Error", "AutoPackage.json is missing or is not valid JSON. Fix the file, then try again."),
                    ("Path",  JsonPath),
                });
                return;
            }

            var winBg      = Res("WindowBgBrush", Brushes.White);
            var borderClr  = Res("BorderMainBrush", Brushes.LightGray);
            var boxBg      = Res("InputBgBrush", new SolidColorBrush(Color.FromRgb(0xF0, 0xF1, 0xF8)));
            var boxBdr     = Res("BorderMainBrush", new SolidColorBrush(Color.FromRgb(0xDD, 0xDF, 0xEA)));
            var lblFg      = Res("TextSecondaryBrush", Brushes.Gray);
            var valFg      = Res("TextPrimaryBrush", Brushes.Black);
            var sec        = TryFindResource("SecondaryButtonStyle") as Style;
            var act        = TryFindResource("ActionBtnStyle") as Style;
            var titleBarBg = new SolidColorBrush(Color.FromRgb(0x53, 0x56, 0x63));

            var cwin = new Window
            {
                Width = 560, SizeToContent = SizeToContent.Height, MaxHeight = Math.Max(480, SystemParameters.WorkArea.Height - 48),
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = Window.GetWindow(this), ResizeMode = ResizeMode.NoResize,
                WindowStyle = WindowStyle.None, AllowsTransparency = true,
                Background = Brushes.Transparent,
                FontFamily = new System.Windows.Media.FontFamily("Segoe UI"), ShowInTaskbar = false
            };
            var outer = new Border { Background = winBg, BorderBrush = borderClr, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(10), Effect = new System.Windows.Media.Effects.DropShadowEffect { BlurRadius = 16, ShadowDepth = 2, Opacity = 0.18, Color = Colors.Black } };
            cwin.Content = outer;
            var og = new Grid();
            og.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            og.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            og.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            outer.Child = og;

            var tb = new Border { Background = titleBarBg, CornerRadius = new CornerRadius(10, 10, 0, 0), Padding = new Thickness(16, 6, 12, 6) };
            tb.MouseLeftButtonDown += (_, _) => cwin.DragMove();
            Grid.SetRow(tb, 0);
            var tg = new Grid();
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            var ti = new TextBlock { Text = "⚙", FontSize = 13, Foreground = Brushes.White, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 0) };
            var tt = new TextBlock { Text = "Settings", FontSize = 13, FontWeight = FontWeights.SemiBold, Foreground = Brushes.White, VerticalAlignment = VerticalAlignment.Center };
            var tc = new Button { Content = "✕", FontSize = 11, Foreground = new SolidColorBrush(Color.FromArgb(0xCC, 0xFF, 0xFF, 0xFF)), Background = Brushes.Transparent, BorderThickness = new Thickness(0), Cursor = System.Windows.Input.Cursors.Hand, VerticalAlignment = VerticalAlignment.Center, Padding = new Thickness(6, 2, 6, 2) };
            tc.Click += (_, _) => cwin.Close();
            Grid.SetColumn(ti, 0); Grid.SetColumn(tt, 1); Grid.SetColumn(tc, 2);
            tg.Children.Add(ti); tg.Children.Add(tt); tg.Children.Add(tc);
            tb.Child = tg; og.Children.Add(tb);

            var form = new StackPanel { Margin = new Thickness(16, 12, 16, 8) };
            var scroll = new ScrollViewer { VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Content = form };
            Grid.SetRow(scroll, 1); og.Children.Add(scroll);

            // (section, JSON key, label, kind)  kind: s=string, p=path (folder browse, REQUIRED),
            // po=path (folder browse, optional - no asterisk, not enforced on Save), int=number,
            // yn=Yes/No, f=file browse, it=IntuneSettings nested string
            var fields = new (string section, string key, string label, string kind)[]
            {
                ("Paths",  "SourceDownloadPath",   "Source Download Path",    "p"),
                ("Paths",  "PackageInputFolder",   "Package Input Folder",    "p"),
                ("Paths",  "PackageOutputFolder",  "Package Output Folder",   "p"),
                ("Paths",  "AppVersionReportPath", "App Version Report Path", "p"),
                ("Paths",  "PSADTTemplateFolder",  "PSADT Template Folder",   "po"),
                ("Mail",   "MailMode",             "Mail Mode",               "s"),
                ("Mail",   "MailSenderAddress",    "Mail Sender Address",      "s"),
                ("Mail",   "MailSubject",          "Mail Subject",            "s"),
                ("Mail",   "MailBody",             "Mail Body",               "ml"),
                ("GitHub", "GitHubToken",          "GitHub Token (optional)", "s"),
                ("Intune", "TenantId",             "Tenant ID",               "it"),
                ("Intune", "ClientId",             "Client ID",               "it"),
                ("Intune", "IntuneAuthPath",       "Intune Auth Path",        "f"),
                ("Flags",  "CopyLogsToDocuments",  "Copy Logs To Documents",  "yn"),
                ("Flags",  "CopytxtToDocuments",   "Copy .txt To Documents",  "yn"),
                ("Flags",  "CopydocxToDocuments",  "Copy .docx To Documents", "yn"),
                ("Flags",  "AddMsiCommandToPs1",   "Add MSI Command To PS1",  "yn"),
                ("Flags",  "AddExeCommandToPs1",   "Add EXE Command To PS1",  "yn"),
            };

            string ReadStr(System.Text.Json.Nodes.JsonNode? n)
            {
                if (n == null) return "";
                try { return n.GetValue<string>(); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                try { return n.GetValue<int>().ToString(); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                try { return n.GetValue<double>().ToString(); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                try { return n.ToJsonString().Trim('"'); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                return "";
            }

            var editors = new System.Collections.Generic.Dictionary<string, Control>();
            string curSection = "";
            foreach (var f in fields)
            {
                if (f.section != curSection)
                {
                    curSection = f.section;
                    form.Children.Add(new TextBlock { Text = curSection, FontSize = 12, FontWeight = FontWeights.Bold, Foreground = valFg, Margin = new Thickness(0, form.Children.Count == 0 ? 0 : 12, 0, 6) });
                }

                string cur = f.kind == "it"
                    ? ReadStr((root["IntuneSettings"] as System.Text.Json.Nodes.JsonObject)?[f.key])
                    : ReadStr(root[f.key]);

                var rowGrid = new Grid { Margin = new Thickness(0, 0, 0, 6) };
                rowGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(180) });
                rowGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                var lbl = new TextBlock { FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg, VerticalAlignment = VerticalAlignment.Center };
                lbl.Inlines.Add(new System.Windows.Documents.Run(f.label));
                if (f.kind == "p")
                    lbl.Inlines.Add(new System.Windows.Documents.Run(" *") { Foreground = new SolidColorBrush(Color.FromRgb(0xE5, 0x39, 0x35)), FontWeight = FontWeights.Bold });
                Grid.SetColumn(lbl, 0); rowGrid.Children.Add(lbl);

                Control editor;
                if (f.kind == "yn")
                {
                    bool isYes = string.Equals(cur, "Yes", StringComparison.OrdinalIgnoreCase);
                    var rbY = new RadioButton { Content = "Yes", FontSize = 11, IsChecked = isYes,  Foreground = valFg, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 18, 0), Cursor = System.Windows.Input.Cursors.Hand };
                    var rbN = new RadioButton { Content = "No",  FontSize = 11, IsChecked = !isYes, Foreground = valFg, VerticalAlignment = VerticalAlignment.Center, Cursor = System.Windows.Input.Cursors.Hand };
                    var rbPanel = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                    rbPanel.Children.Add(rbY); rbPanel.Children.Add(rbN);   // no GroupName: the parent panel groups them
                    Grid.SetColumn(rbPanel, 1); rowGrid.Children.Add(rbPanel);
                    editor = rbY;   // on save: rbY.IsChecked -> "Yes"/"No"
                }
                else
                {
                    var txv = new TextBox { Text = cur, FontSize = 11, MinHeight = 26, BorderThickness = new Thickness(0), Background = Brushes.Transparent, Foreground = valFg, VerticalContentAlignment = VerticalAlignment.Center };
                    if (f.kind == "ml")
                    {
                        // Multi-line editor: Enter inserts a new line instead of closing
                        // the dialog, and the box is at least 4 lines tall. Line breaks
                        // are preserved into the JSON value; the mail composer turns
                        // blank lines into paragraphs and single breaks into <br/>.
                        txv.AcceptsReturn = true;
                        txv.TextWrapping = TextWrapping.Wrap;
                        txv.MinLines = 4;
                        txv.VerticalScrollBarVisibility = ScrollBarVisibility.Auto;
                        txv.VerticalContentAlignment = VerticalAlignment.Top;
                        lbl.VerticalAlignment = VerticalAlignment.Top;
                        lbl.Margin = new Thickness(0, 6, 0, 0);
                    }
                    UIElement inner = txv;
                    // "po" is a path like "p" - same textbox, same folder browser - but optional, so
                    // it is excluded from the red asterisk above and from the mandatory-paths check
                    // on Save. Both of those test kind == "p" exactly, so an optional path only has
                    // to opt IN here rather than opt out in two other places.
                    if (f.kind == "p" || f.kind == "po" || f.kind == "f")
                    {
                        bool isFile = f.kind == "f";
                        // Browse icon sits inside the rounded box, at the right edge.
                        var browse = new Button { Content = "📁", FontSize = 14, Foreground = valFg, Width = 28, Height = 26, Background = Brushes.Transparent, BorderThickness = new Thickness(0), Cursor = System.Windows.Input.Cursors.Hand, Padding = new Thickness(0), VerticalAlignment = VerticalAlignment.Center, ToolTip = isFile ? "Browse for file" : "Browse for folder" };
                        browse.Click += (_, _) =>
                        {
                            try
                            {
                                if (isFile)
                                {
                                    var ofd = new Microsoft.Win32.OpenFileDialog { Title = "Select file", Filter = "JSON files (*.json)|*.json|All files (*.*)|*.*" };
                                    try { if (!string.IsNullOrWhiteSpace(txv.Text)) ofd.FileName = txv.Text; } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                                    if (ofd.ShowDialog() == true) txv.Text = ofd.FileName;
                                }
                                else
                                {
                                    var fbd = new System.Windows.Forms.FolderBrowserDialog { Description = "Select folder", UseDescriptionForTitle = true };
                                    try { if (!string.IsNullOrWhiteSpace(txv.Text)) fbd.SelectedPath = txv.Text; } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                                    if (fbd.ShowDialog() == System.Windows.Forms.DialogResult.OK) txv.Text = fbd.SelectedPath;
                                }
                            }
                            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                        };
                        var ig = new Grid();
                        ig.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                        ig.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                        Grid.SetColumn(txv, 0); Grid.SetColumn(browse, 1);
                        ig.Children.Add(txv); ig.Children.Add(browse);
                        inner = ig;
                    }
                    var wrap = new Border { Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(6), Padding = new Thickness(8, 2, 6, 2), Child = inner };
                    Grid.SetColumn(wrap, 1); rowGrid.Children.Add(wrap);
                    editor = txv;
                }
                form.Children.Add(rowGrid);
                editors[f.key] = editor;
            }

            // MST Properties: an editable Property/Value list (add / remove rows).
            form.Children.Add(new TextBlock { Text = "MST Properties", FontSize = 12, FontWeight = FontWeights.Bold, Foreground = valFg, Margin = new Thickness(0, 12, 0, 6) });
            var mstRows = new System.Collections.Generic.List<(TextBox prop, TextBox val)>();
            var mstPanel = new StackPanel();
            form.Children.Add(mstPanel);
            void AddMstRow(string propVal, string valVal)
            {
                var rg = new Grid { Margin = new Thickness(0, 0, 0, 4) };
                rg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                rg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                rg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                var pTx = new TextBox { Text = propVal, FontSize = 11, MinHeight = 26, BorderThickness = new Thickness(0), Background = Brushes.Transparent, Foreground = valFg, VerticalContentAlignment = VerticalAlignment.Center };
                var vTx = new TextBox { Text = valVal,  FontSize = 11, MinHeight = 26, BorderThickness = new Thickness(0), Background = Brushes.Transparent, Foreground = valFg, VerticalContentAlignment = VerticalAlignment.Center };
                var pWrap = new Border { Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(6), Padding = new Thickness(8, 2, 6, 2), Margin = new Thickness(0, 0, 6, 0), Child = pTx };
                var vWrap = new Border { Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(6), Padding = new Thickness(8, 2, 6, 2), Margin = new Thickness(0, 0, 6, 0), Child = vTx };
                var del = new Button { Content = "✕", FontSize = 11, Width = 26, Height = 26, Background = Brushes.Transparent, BorderThickness = new Thickness(0), Foreground = lblFg, Cursor = System.Windows.Input.Cursors.Hand, ToolTip = "Remove this property" };
                var entry = (pTx, vTx);
                del.Click += (_, _) => { mstPanel.Children.Remove(rg); mstRows.Remove(entry); };
                Grid.SetColumn(pWrap, 0); Grid.SetColumn(vWrap, 1); Grid.SetColumn(del, 2);
                rg.Children.Add(pWrap); rg.Children.Add(vWrap); rg.Children.Add(del);
                mstPanel.Children.Add(rg);
                mstRows.Add(entry);
            }
            try
            {
                if (root["MSTProperties"] is System.Text.Json.Nodes.JsonArray mstArrLoad)
                    foreach (var item in mstArrLoad)
                    {
                        var obj = item as System.Text.Json.Nodes.JsonObject;
                        AddMstRow(ReadStr(obj?["Property"]), ReadStr(obj?["Value"]));
                    }
            }
            catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
            var addMstBtn = new Button { Content = "＋  Add Property", Style = sec, Height = 26, Padding = new Thickness(10, 0, 10, 0), HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(0, 2, 0, 4) };
            addMstBtn.Click += (_, _) => AddMstRow("", "");
            form.Children.Add(addMstBtn);

            var btnBar = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(16, 4, 16, 14) };
            Grid.SetRow(btnBar, 2);
            var bCancel = new Button { Content = "✕  Cancel", Style = act, Height = 30, Padding = new Thickness(12, 0, 12, 0), Margin = new Thickness(0, 0, 8, 0), VerticalAlignment = VerticalAlignment.Center };
            bCancel.Click += (_, _) => cwin.Close();
            var bSave = new Button { Content = "💾  Save", Style = act, Height = 30, Padding = new Thickness(12, 0, 12, 0), VerticalAlignment = VerticalAlignment.Center };
            SdApplyPrimaryLook(bSave);
            bSave.Click += (_, _) =>
            {
                try
                {
                    // Paths are mandatory.
                    var missingPaths = new List<string>();
                    foreach (var pf in fields)
                        if (pf.kind == "p" && string.IsNullOrWhiteSpace((editors[pf.key] as TextBox)?.Text))
                            missingPaths.Add(pf.label);
                    if (missingPaths.Count > 0)
                    {
                        ShowStyledInfoDialog(cwin, "Settings - Required Paths", "⚠️", new[]
                        {
                            ("Required", "The following path(s) must be set before saving:"),
                            ("Missing",  string.Join(", ", missingPaths)),
                        });
                        return;
                    }
                    foreach (var f in fields)
                    {
                        var ed = editors[f.key];
                        string val = f.kind == "yn" ? ((ed as RadioButton)?.IsChecked == true ? "Yes" : "No") : ((ed as TextBox)?.Text ?? "").Trim();
                        if (f.kind == "it")
                        {
                            System.Text.Json.Nodes.JsonObject io;
                            if (root["IntuneSettings"] is System.Text.Json.Nodes.JsonObject existingIo) io = existingIo;
                            else { io = new System.Text.Json.Nodes.JsonObject(); root["IntuneSettings"] = io; }
                            io[f.key] = val;
                        }
                        else if (f.kind == "int")
                        {
                            if (int.TryParse(val, out var p)) root[f.key] = p; else root[f.key] = val;
                        }
                        else root[f.key] = val;
                    }
                    var mstOut = new System.Text.Json.Nodes.JsonArray();
                    foreach (var (pTx, vTx) in mstRows)
                    {
                        string pv = pTx.Text.Trim();
                        if (pv.Length == 0) continue;   // skip rows with no property name
                        mstOut.Add(new System.Text.Json.Nodes.JsonObject { ["Property"] = pv, ["Value"] = vTx.Text });
                    }
                    root["MSTProperties"] = mstOut;
                    File.WriteAllText(JsonPath, root.ToJsonString(new JsonSerializerOptions { WriteIndented = true }));

                    // Pick up a newly pasted GitHub token straight away rather than on next launch.
                    ResetGitHubToken();
                    cwin.Close();
                    ShowStyledInfoDialog(Window.GetWindow(this)!, "Settings", "✅", new[]
                    {
                        // The path comes from JsonPath rather than being spelled out, so this stays
                        // correct if the config ever moves. The dialog is a fixed 480 wide with
                        // TextWrapping.Wrap, so a long path wraps instead of stretching the window.
                        //
                        // The old wording ended "Path changes apply after a Refresh." There is no
                        // Refresh control anywhere in the app, so it pointed at a button that does
                        // not exist.
                        ("Saved", $"Settings written to {JsonPath}"),
                    });
                }
                catch (Exception ex)
                {
                    ShowStyledInfoDialog(cwin, "Settings", "⚠️", new[]
                    {
                        ("Save failed", ex.Message),
                        ("Path",        JsonPath),
                    });
                }
            };
            btnBar.Children.Add(bCancel); btnBar.Children.Add(bSave);
            og.Children.Add(btnBar);

            cwin.ShowDialog();
        }

        private void ShowStyledInfoDialog(Window owner, string titleText, string bodyIcon, (string label, string body)[] rows, (string text, Action onClick)? actionButton = null)
        {
            var winBg      = Res("WindowBgBrush", Brushes.White);
            var borderClr  = Res("BorderMainBrush", Brushes.LightGray);
            var boxBg      = Res("InputBgBrush", new SolidColorBrush(Color.FromRgb(0xF0, 0xF1, 0xF8)));
            var boxBdr     = Res("BorderMainBrush", new SolidColorBrush(Color.FromRgb(0xDD, 0xDF, 0xEA)));
            var lblFg      = Res("TextSecondaryBrush", Brushes.Gray);
            var valFg      = Res("TextPrimaryBrush", Brushes.Black);
            var sec        = Application.Current.TryFindResource("SecondaryButtonStyle") as Style;
            var titleBarBg = new SolidColorBrush(Color.FromRgb(0x53, 0x56, 0x63));

            var cwin = new Window
            {
                Width = 480, SizeToContent = SizeToContent.Height,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = owner, ResizeMode = ResizeMode.NoResize,
                WindowStyle = WindowStyle.None, AllowsTransparency = true,
                Background = Brushes.Transparent,
                FontFamily = new System.Windows.Media.FontFamily("Segoe UI"), ShowInTaskbar = false
            };
            var outer = new Border { Background = winBg, BorderBrush = borderClr, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(10), Effect = new System.Windows.Media.Effects.DropShadowEffect { BlurRadius = 16, ShadowDepth = 2, Opacity = 0.18, Color = Colors.Black } };
            cwin.Content = outer;
            var og = new Grid();
            og.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            og.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            outer.Child = og;

            // Title bar
            var tb = new Border { Background = titleBarBg, BorderThickness = new Thickness(0,0,0,1), BorderBrush = titleBarBg, CornerRadius = new CornerRadius(10,10,0,0), Padding = new Thickness(16,6,12,6) };
            tb.MouseLeftButtonDown += (_, _) => cwin.DragMove();
            Grid.SetRow(tb, 0);
            var tg = new Grid();
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            tg.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            var ti = new TextBlock { Text = "📥", FontSize = 13, Foreground = Brushes.White, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0,0,8,0) };
            var tt = new TextBlock { Text = titleText, FontSize = 13, FontWeight = FontWeights.SemiBold, Foreground = Brushes.White, VerticalAlignment = VerticalAlignment.Center };
            var tc = new Button { Content = "✕", FontSize = 11, Foreground = new SolidColorBrush(Color.FromArgb(0xCC,0xFF,0xFF,0xFF)), Background = Brushes.Transparent, BorderThickness = new Thickness(0), Cursor = System.Windows.Input.Cursors.Hand, VerticalAlignment = VerticalAlignment.Center, Padding = new Thickness(6,2,6,2) };
            tc.Click += (_, _) => cwin.Close();
            Grid.SetColumn(ti,0); Grid.SetColumn(tt,1); Grid.SetColumn(tc,2);
            tg.Children.Add(ti); tg.Children.Add(tt); tg.Children.Add(tc);
            tb.Child = tg; og.Children.Add(tb);

            // Body
            var root = new Grid { Margin = new Thickness(8) };
            Grid.SetRow(root, 1); og.Children.Add(root);
            var dg = new Grid();
            dg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(62) });
            dg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            Border MkBox(string text) { var b = new Border { Background = boxBg, BorderBrush = boxBdr, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(6), Padding = new Thickness(10,6,10,6) }; b.Child = new TextBlock { Text = text, FontSize = 11, TextWrapping = TextWrapping.Wrap, Foreground = valFg }; return b; }
            TextBlock MkLbl(string text) => new TextBlock { Text = text, FontSize = 11, FontWeight = FontWeights.SemiBold, Foreground = lblFg, VerticalAlignment = VerticalAlignment.Center };

            int dr = 0;
            foreach (var (label, body) in rows)
            {
                dg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var lbl = MkLbl(label); var box = MkBox(body);
                Grid.SetRow(lbl, dr); Grid.SetColumn(lbl, 0);
                Grid.SetRow(box, dr); Grid.SetColumn(box, 1);
                dg.Children.Add(lbl); dg.Children.Add(box); dr++;
                dg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(8) }); dr++;
            }
            dg.RowDefinitions.Add(new RowDefinition { Height = new GridLength(2) }); dr++;
            dg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var okBtn = new Button { Content = "✔  OK", Style = sec, FontSize = 11, FontWeight = FontWeights.SemiBold, Height = 28, MinWidth = 96, Padding = new Thickness(10,0,10,0), IsDefault = true };
            SdApplyPrimaryLook(okBtn);
            okBtn.Click += (_, _) => cwin.Close();
            var btnRow = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
            if (actionButton.HasValue)
            {
                var act = actionButton.Value.onClick;
                var actBtn = new Button { Content = actionButton.Value.text, Style = sec, FontSize = 11, FontWeight = FontWeights.SemiBold, Height = 28, MinWidth = 96, Padding = new Thickness(10,0,10,0), Margin = new Thickness(0,0,8,0) };
                actBtn.Click += (_, _) => { try { act(); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); } };
                btnRow.Children.Add(actBtn);
            }
            btnRow.Children.Add(okBtn);
            Grid.SetRow(btnRow, dr); Grid.SetColumn(btnRow, 1);
            dg.Children.Add(btnRow);
            var icon = SdDecisionIcon();
            Grid.SetRow(icon, dr); Grid.SetColumn(icon, 0);
            dg.Children.Add(icon);
            root.Children.Add(dg);
            cwin.ShowDialog();
        }

        // Give a dialog button the highlighted "primary action" look: a filled
        // accent background, rounded corners and a subtle hover. Theme resources
        // keep it readable in both light and dark modes, mirroring the Publish
        // Package dialog. Applied on top of any existing Style (local values win
        // in WPF), so callers keep their own sizing.
        private static void SdApplyPrimaryLook(Button b)
        {
            Brush bg     = Application.Current.TryFindResource("DlgBtnBlueBgBrush")     as Brush ?? new SolidColorBrush(Color.FromRgb(0x42, 0x9B, 0xF5));
            Brush fg     = Application.Current.TryFindResource("DlgBtnBlueFgBrush")     as Brush ?? Brushes.White;
            Brush border = Application.Current.TryFindResource("DlgBtnBlueBorderBrush") as Brush ?? bg;

            b.Background      = bg;
            b.Foreground      = fg;
            b.BorderBrush     = border;
            b.BorderThickness = new Thickness(1);
            b.Cursor          = Cursors.Hand;

            var tpl = new ControlTemplate(typeof(Button));
            var bd  = new FrameworkElementFactory(typeof(Border));
            bd.SetValue(Border.BackgroundProperty,      bg);
            bd.SetValue(Border.BorderBrushProperty,     border);
            bd.SetValue(Border.BorderThicknessProperty, new Thickness(1));
            bd.SetValue(Border.CornerRadiusProperty,    new CornerRadius(6));
            var cp = new FrameworkElementFactory(typeof(ContentPresenter));
            cp.SetValue(FrameworkElement.MarginProperty, new Thickness(12, 0, 12, 0));
            cp.SetValue(ContentPresenter.HorizontalAlignmentProperty, HorizontalAlignment.Center);
            cp.SetValue(ContentPresenter.VerticalAlignmentProperty,   VerticalAlignment.Center);
            bd.AppendChild(cp);
            tpl.VisualTree = bd;
            var hov = new Trigger { Property = UIElement.IsMouseOverProperty, Value = true };
            hov.Setters.Add(new Setter(UIElement.OpacityProperty, 0.85));
            tpl.Triggers.Add(hov);
            b.Template = tpl;
        }

        // Uniform "make a choice" icon for a dialog's action row: a blue question
        // glyph matching the Publish Package dialog exactly (same glyph, colour
        // and size) so every popup looks the same. The title bar still carries
        // the page context icon. A monochrome glyph with an explicit Foreground
        // is used so the blue tint always applies in both themes.
        private static TextBlock SdDecisionIcon()
            => new TextBlock
            {
                Text = "\u2753",
                FontSize = 22,
                Foreground = new SolidColorBrush(Color.FromRgb(0x42, 0x9B, 0xF5)),
                HorizontalAlignment = HorizontalAlignment.Left,
                VerticalAlignment   = VerticalAlignment.Center
            };

        /// <summary>
        /// Reads the ProductCode property from an MSI file using WindowsInstaller COM.
        /// Must run on an STA thread — this wrapper creates one automatically.
        /// Returns empty string on any error.
        /// </summary>
        private static string ReadMsiProductCodeSTA(string msiPath)
        {
            string productCode = "";
            var thread = new System.Threading.Thread(() =>
            {
                object? inst = null, db = null, vw = null;
                try
                {
                    Type t = Type.GetTypeFromProgID("WindowsInstaller.Installer")!;
                    inst = Activator.CreateInstance(t)!;
                    db   = t.InvokeMember("OpenDatabase", System.Reflection.BindingFlags.InvokeMethod,
                               null, inst, new object[] { msiPath, 0 });
                    var dt = db!.GetType();
                    vw   = dt.InvokeMember("OpenView", System.Reflection.BindingFlags.InvokeMethod,
                               null, db, new object[] { "SELECT Value FROM Property WHERE Property='ProductCode'" });
                    var vt = vw!.GetType();
                    vt.InvokeMember("Execute", System.Reflection.BindingFlags.InvokeMethod, null, vw, null);
                    object? rec = vt.InvokeMember("Fetch", System.Reflection.BindingFlags.InvokeMethod, null, vw, null);
                    if (rec != null)
                    {
                        productCode = rec.GetType().InvokeMember("StringData",
                            System.Reflection.BindingFlags.GetProperty, null, rec, new object[] { 1 }) as string ?? "";
                        System.Runtime.InteropServices.Marshal.ReleaseComObject(rec);
                    }
                }
                catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                finally
                {
                    if (vw   != null) try { System.Runtime.InteropServices.Marshal.ReleaseComObject(vw);   } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                    if (db   != null) try { System.Runtime.InteropServices.Marshal.ReleaseComObject(db);   } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                    if (inst != null) try { System.Runtime.InteropServices.Marshal.ReleaseComObject(inst); } catch (System.Exception exSwallow) { System.Diagnostics.Debug.WriteLine("[SourceDownloadPage] swallowed " + exSwallow.GetType().Name + ": " + exSwallow.Message); }
                }
            });
            thread.SetApartmentState(System.Threading.ApartmentState.STA);
            thread.Start();
            thread.Join();
            return productCode.Trim();
        }
    }
}
